--

CREATE TABLE public.purchase_order_line (
    id integer NOT NULL,
    product_id integer,
    sequence integer,
    uom_id integer,
    order_id integer NOT NULL,
    company_id integer,
    partner_id integer,
    create_uid integer,
    write_uid integer,
    qty_received_method character varying,
    display_type character varying,
    analytic_distribution jsonb,
    name text,
    product_qty numeric NOT NULL,
    discount numeric,
    price_unit numeric NOT NULL,
    price_unit_product_uom numeric,
    price_subtotal numeric,
    price_total numeric,
    qty_invoiced numeric,
    qty_received numeric,
    qty_received_manual numeric,
    qty_to_invoice numeric,
    qty_to_invoice_raw numeric,
    is_downpayment boolean,
    date_planned timestamp without time zone,
    create_date timestamp without time zone,
    write_date timestamp without time zone,
    product_uom_qty double precision,
    price_tax double precision,
    non_deductible_tax double precision,
    technical_price_unit double precision,
    orderpoint_id integer,
    forecasted_location_id integer,
    product_description_variants character varying,
    propagate_cancel boolean,
    date_promised timestamp without time zone,
    sale_line_id integer,
    CONSTRAINT purchase_order_line_accountable_required_fields CHECK (((display_type IS NOT NULL) OR is_downpayment OR ((product_id IS NOT NULL) AND (uom_id IS NOT NULL) AND (date_planned IS NOT NULL)))),
    CONSTRAINT purchase_order_line_non_accountable_null_fields CHECK (((display_type IS NULL) OR ((product_id IS NULL) AND (price_unit = (0)::numeric) AND (product_uom_qty = (0)::double precision) AND (uom_id IS NULL) AND (date_planned IS NULL))))
);


