--
-- Name: res_country; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.res_country (
    id integer NOT NULL,
    address_view_id integer,
    currency_id integer,
    phone_code integer,
    create_uid integer,
    write_uid integer,
    code character varying(2) NOT NULL,
    name_position character varying,
    zip_applicability character varying NOT NULL,
    name jsonb NOT NULL,
    vat_label jsonb,
    address_format text,
    state_required boolean,
    create_date timestamp without time zone,
    write_date timestamp without time zone,
    enforce_cities boolean,
    l10n_ar_afip_code character varying(3),
    l10n_ar_natural_vat character varying(11),
    l10n_ar_legal_entity_vat character varying(11),
    l10n_ar_other_vat character varying(11),
    CONSTRAINT res_country_code_check CHECK (((length((code)::text) = 2) AND (upper((code)::text) = (code)::text)))
);


--
-- Name: TABLE res_country; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.res_country IS 'Country';


