    calendar_id integer NOT NULL,
    sequence integer,
    recurrency_interval integer,
    recurrency_count integer,
    create_uid integer,
    write_uid integer,
    day_period character varying,
    dayofweek character varying NOT NULL,
    recurrency_type character varying,
    recurrency_end_type character varying,
    date date,
    recurrency_until date,
    recurrency_excluded_occurences jsonb,
    duration_based boolean,
    recurrency boolean,
    create_date timestamp without time zone,
    write_date timestamp without time zone,
    hour_from double precision NOT NULL,
    hour_to double precision NOT NULL,
    duration_hours double precision,
    CONSTRAINT resource_calendar_attendance_check_count CHECK (((recurrency IS NOT TRUE) OR ((recurrency_end_type)::text <> 'times'::text) OR (recurrency_count > 0))),
    CONSTRAINT resource_calendar_attendance_check_duration_hours CHECK (((duration_hours > (0)::double precision) AND (duration_hours <= (24)::double precision))),
    CONSTRAINT resource_calendar_attendance_check_interval CHECK (((recurrency IS NOT TRUE) OR (recurrency_interval >= 1))),
    CONSTRAINT resource_calendar_attendance_check_recurrency_until CHECK (((recurrency IS NOT TRUE) OR (recurrency_until >= date)))
);


