--
-- Name: survey_survey; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.survey_survey (
    id integer NOT NULL,
    color integer,
    user_id integer,
    attempts_limit integer,
    certification_mail_template_id integer,
    certification_badge_id integer,
    session_question_id integer,
    session_speed_rating_time_limit integer,
    create_uid integer,
    write_uid integer,
    survey_type character varying NOT NULL,
    background_image_filename character varying,
    questions_layout character varying NOT NULL,
    questions_selection character varying NOT NULL,
    progression_mode character varying,
    access_mode character varying NOT NULL,
    access_token character varying,
    scoring_type character varying NOT NULL,
    certification_report_layout character varying,
    session_state character varying,
    session_code character varying,
    title jsonb NOT NULL,
    description jsonb,
    description_done jsonb,
    active boolean,
    users_login_required boolean,
    users_can_go_back boolean,
    is_attempts_limited boolean,
    is_time_limited boolean,
    certification boolean,
    certification_give_badge boolean,
    session_question_can_answer boolean,
    session_speed_rating boolean,
    session_start_time timestamp without time zone,
    session_question_start_time timestamp without time zone,
    create_date timestamp without time zone,
    write_date timestamp without time zone,
    scoring_success_min double precision,
    time_limit double precision,
    certification_validity_months integer,
    CONSTRAINT survey_survey_attempts_limit_check CHECK (((is_attempts_limited = false) OR ((attempts_limit IS NOT NULL) AND (attempts_limit > 0)))),
    CONSTRAINT survey_survey_certification_check CHECK ((((scoring_type)::text <> 'no_scoring'::text) OR (certification = false))),
    CONSTRAINT survey_survey_scoring_success_min_check CHECK (((scoring_success_min IS NULL) OR ((scoring_success_min >= (0)::double precision) AND (scoring_success_min <= (100)::double precision)))),
    CONSTRAINT survey_survey_session_speed_rating_has_time_limit CHECK (((session_speed_rating <> true) OR ((session_speed_rating_time_limit IS NOT NULL) AND (session_speed_rating_time_limit > 0)))),
    CONSTRAINT survey_survey_time_limit_check CHECK (((is_time_limited = false) OR ((time_limit IS NOT NULL) AND (time_limit > (0)::double precision))))
);


