t-foreach=\\"move_lines\\" t-as=\\"move_operation\\">\\n                                                <td>\\n                                                    <span t-field=\\"move_operation.display_name\\">Product Name</span>\\n                                                </td>\\n                                                <td>\\n                                                    <span t-out=\\"sum(move_operation.mapped('quantity'))\\">Quantity Done</span>\\n                                                    <span t-field=\\"move_operation.uom_id\\" groups=\\"uom.group_uom\\"/>\\n                                                </td>\\n                                                <td>\\n                                                    <span t-out=\\"move_operation.picking_id.display_name\\">Transfer Display Name</span>\\n                                                </td>\\n                                                <td t-if=\\"has_serial_number\\" class=\\"text-center h6\\" width=\\"15%\\">\\n                                                    <span t-if=\\"move_operation.lot_id or move_operation.lot_name\\" t-field=\\"move_operation.lot_id.name\\" t-options=\\"{'widget': 'barcode', 'humanreadable': 1, 'width': 600, 'height': 100, 'img_style': 'width:100%;height:35px;'}\\">Lot Number</span>\\n                                                </td>\\n                                                <td width=\\"15%\\" class=\\"text-center\\" t-if=\\"has_barcode\\">\\n                                                    <span t-field=\\"move_operation.product_id.barcode\\" t-options=\\"{'widget': 'barcode', 'symbology': 'auto', 'width': 600, 'height': 100, 'img_style': 'width:100%;height:35px;'}\\">Product Barcode</span>\\n                                                </td>\\n                                                <td t-if=\\"has_package\\" width=\\"15%\\">\\n                                                    <span t-field=\\"move_operation.package_id\\">Package ID</span>\\n                                                    <t t-if=\\"move_operation.result_package_id\\">\\n                                                        <strong>→</strong> <span t-field=\\"move_operation.result_package_id\\">Result Package ID</span>\\n                                                    </t>\\n                                                </td>\\n                                            </tr>\\n                                        </tbody>\\n                                    </t>\\n                                </t>\\n                            </table>\\n                        </div>\\n                    </t>\\n                </t>\\n            </t>\\n        </t>"}	<?xml version="1.0"?>\n<t t-name="stock.report_picking_batch">\n            <t t-call="web.html_container">\n                <div class="oe_structure"/>\n                <t t-foreach="docs" t-as="o">\n                    <t t-set="move_line_ids" t-value="o.picking_ids.mapped('move_line_ids')"/>\n                    <t t-set="has_package" t-value="move_line_ids.filtered('result_package_id')" groups="stock.group_tracking_lot"/>\n                    <t t-set="has_serial_number" t-value="move_line_ids.filtered('lot_id')" groups="stock.group_production_lot"/>\n                    <t t-set="has_barcode" t-value="move_line_ids.mapped('product_id').filtered('barcode')"/>\n                    <t t-set="locations" t-value="move_line_ids.mapped('location_id').sorted(lambda location: location.complete_name)"/>\n                    <t t-call="web.external_layout">\n                        <div class="page">\n                            <div class="d-flex">\n                                <div><h3>Summary: <span t-field="o.name">Batch Name</span></h3></div>\n                                <div class="me-auto">\n                                    <span t-field="o.name" t-options="{'widget': 'barcode', 'width': 600, 'height': 150, 'img_style': 'width:300px;height:50px;'}">Batch</span>\n                                </div>\n                            </div>\n                            <div t-if="o.user_id">\n                                <strong>Responsible:</strong>\n                                <span t-field="o.user_id">John Doe</span>\n                            </div><br/>\n                            <div class="oe_structure"/>\n                            <table class="table table-borderless">\n                                <thead>\n                                    <tr>\n                                        <th>Transfer</th>\n                                        <th>Barcode</th>\n                                        <th>Status</th>\n                                        <th>Scheduled Date</th>\n                                    </tr>\n                                </thead>\n                                <tbody>\n                                    <tr t-foreach="o.picking_ids.sorted(lambda p: p.batch_sequence)" t-as="pick">\n                                        <td>\n                                            <span t-field="pick.name">Transfer Name</span>\n                                        </td>\n                                        <td>\n                                            <span t-field="pick.name" t-options="{'widget': 'barcode', 'quiet': 0, 'width': 400, 'height': 100, 'img_style': 'width:200px;height:50px;'}">Transfer</span>\n                                        </td>\n                                        <td>\n                                            <span t-field="pick.state">Gujarat</span>\n                                        </td>\n                                        <td>\n                                            <span t-field="pick.scheduled_date">2023-08-20</span>\n                                        </td>\n                                    </tr>\n                                </tbody>\n                            </table>\n                            <p style="page-break-after: always;"/>\n                            <div class="oe_structure"/>\n                            <h3><span t-field="o.name">Batch Name</span></h3>\n                            <div t-if="o.user_id">\n                                <strong>Responsible:</strong>\n                                <span t-field="o.user_id">John Doe</span>\n                            </div><br/>\n                            <div class="oe_structure"/>\n                            <table class="table table-borderless">\n                                <thead>\n                                    <tr>\n                                        <th>Product</th>\n                                        <th>Quantity</th>\n                                        <th width="20%">Transfer</th>\n                                        <th t-if="has_serial_number" width="15%">\n                                            <strong>Lot/Serial Number</strong>\n                                        </th>\n                                        <th t-if="has_barcode" width="15%" class="text-center">\n                                            <strong>Product Barcode</strong>\n                                        </th>\n                                        <th t-if="has_package" width="15%">\n                                            <strong>Package</strong>\n                                        </th>\n                                    </tr>\n                                </thead>\n                                <t t-foreach="locations" t-as="location_from">\n                                    <t t-set="loc_move_line" t-value="move_line_ids.filtered(lambda x: x.location_id==location_from)"/>\n                                    <t t-foreach="loc_move_line.location_dest_id" t-as="location_dest">\n                                        <t t-set="move_lines" t-value="loc_move_line.filtered(lambda x: x.location_dest_id==location_dest).sorted(lambda ml: ml.product_id.id)"/>\n                                        <t t-set="products" t-value="move_lines.product_id"/>\n                                        <tbody>\n                                            <tr>\n                                                <td style="background-color:lightgrey" colspan="6">\n                                                    <p style="margin:0px"><strong>FROM</strong>\n                                                    <span t-out="move_lines.location_id.display_name">Location From Name</span></p>\n                                                    <p style="margin:0px"><strong>TO</strong>\n                                                    <span t-out="move_lines.location_dest_id.display_name">Location To Name</span></p>\n                                                </td>\n                                            </tr>\n                                            <tr t-foreach="move_lines" t-as="move_operation">\n                                                <td>\n                                                    <span t-field="move_operation.display_name">Product Name</span>\n                                                </td>\n                                                <td>\n                                                    <span t-out="sum(move_operation.mapped('quantity'))">Quantity Done</span>\n                                                    <span t-field="move_operation.uom_id" groups="uom.group_uom"/>\n                                                </td>\n                                                <td>\n                                                    <span t-out="move_operation.picking_id.display_name">Transfer Display Name</span>\n                                                </td>\n                                                <td t-if="has_serial_number" class="text-center h6" width="15%">\n                                                    <span t-if="move_operation.lot_id or move_operation.lot_name" t-field="move_operation.lot_id.name" t-options="{'widget': 'barcode', 'humanreadable': 1, 'width': 600, 'height': 100, 'img_style': 'width:100%;height:35px;'}">Lot Number</span>\n                                                </td>\n                                                <td width="15%" class="text-center" t-if="has_barcode">\n                                                    <span t-field="move_operation.product_id.barcode" t-options="{'widget': 'barcode', 'symbology': 'auto', 'width': 600, 'height': 100, 'img_style': 'width:100%;height:35px;'}">Product Barcode</span>\n                                                </td>\n                                                <td t-if="has_package" width="15%">\n                                                    <span t-field="move_operation.package_id">Package ID</span>\n                                                    <t t-if="move_operation.result_package_id">\n                                                        <strong>→</strong> <span t-field="move_operation.result_package_id">Result Package ID</span>\n                                                    </t>\n                                                </td>\n                                            </tr>\n                                        </tbody>\n                                    </t>\n                                </t>\n                            </table>\n                        </div>\n                    </t>\n                </t>\n            </t>\n        </t>\n\n        	\N	f	t	2026-10-26 23:55:10.724392	2026-10-26 23:55:10.724392	f
1720	16	\N	1	1	report_picking	\N	stock.report_picking	qweb	stock/report/report_stockpicking_operations.xml	primary	\N	{"en_US": "<t t-name=\\"stock.report_picking\\">\\n            <t t-call=\\"web.report_layout\\">\\n                <div class=\\"article o_report_layout_standard\\">\\n                    <t t-foreach=\\"docs\\" t-as=\\"o\\">\\n                        <t t-set=\\"address\\" t-value=\\"None\\"/>\\n                        <div class=\\"page\\">\\n                            <div class=\\"row justify-content-between\\">\\n                                <div class=\\"col-4\\">\\n                                    <h3 t-field=\\"o.picking_type_id.code\\"/>\\n                                    <h2 t-field=\\"o.name\\">WH/OUT/00001</h2>\\n                                </div>\\n                                <div class=\\"col-8\\" name=\\"right_box\\">\\n                                    <div t-field=\\"o.name\\" style=\\"display:flex;justify-content:flex-end;display:-webkit-box;-webkit-box-pack:end;\\" t-options=\\"{'widget': 'barcode', 'width': 600, 'height': 100, 'img_style': 'width:300px;height:50px;margin-right:0;'}\\">\\n                                        <div class=\\"bg-light border-1 rounded d-flex flex-column align-items-center justify-content-center p-3 opacity-75 text-muted text-center\\">\\n                                            (document barcode)\\n                                        </div>\\n                                    </div>\\n                                </div>\\n                            </div>\\n                            <div class=\\"row\\">\\n                                <div class=\\"col-6\\" name=\\"div_outgoing_address\\">\\n                                    <div t-if=\\"o.should_print_delivery_address()\\">\\n                                        <strong>Delivery Address:</strong>\\n                                        <div t-out=\\"o.move_ids[0].partner_id or o.partner_id\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}\\">\\n                                                <div class=\\"bg-light border-1 rounded h-100 d-flex flex-column align-items-center justify-content-center p-4 opacity-75 text-muted text-center\\">\\n                                                    <strong>Delivery address</strong>\\n                                                    <div>Presence depends on the operation category.</div>\\n                                                </div>\\n                                        </div>\\n                                    </div>\\n                                </div>\\n                                <div class=\\"col-5 offset-1\\" name=\\"div_customer_address\\" t-if=\\"o.picking_type_id.code=='outgoing' and o.partner_id and o.partner_id != o.partner_id.commercial_partner_id\\">\\n                                    <div>\\n                                        <span><strong>Customer Address:</strong></span>\\n                                    </div>\\n                                    <div name=\\"partner_header\\">\\n                                        <div t-field=\\"o.partner_id.commercial_partner_id\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;, &quot;vat&quot;] if show_full_address else [&quot;name&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}\\">\\n                                                <div class=\\"bg-light border-1 rounded h-100 d-flex flex-column align-items-center justify-content-center p-4 opacity-75 text-muted text-center\\">\\n                                                <strong>Recipient address</strong>\\n                                                <div>Presence depends on the operation category.</div>\\n                                            </div>\\n                                        </div>\\n                                    </div>\\n                                </div>\\n                            </div>\\n                            <div class=\\"oe_structure\\"/>\\n                            <div class=\\"mt32 mb32 o_stock_report_header_row\\">\\n                                <div t-if=\\"o.origin\\" name=\\"div_origin\\">\\n                                    <strong>Order:</strong>\\n                                    <p t-field=\\"o.origin\\">S0001</p>\\n                                </div>\\n                                <div name=\\"div_warehouse\\">\\n                                    <strong>Warehouse:</strong>\\n                                    <div t-if=\\"o.picking_type_id.warehouse_id.partner_id\\" t-field=\\"o.picking_type_id.warehouse_id.partner_id\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;name&quot;], &quot;no_marker&quot;: True}\\"/>\\n                                    <div t-else=\\"\\" t-field=\\"o.picking_type_id.warehouse_id.name\\"/>\\n                                    </div>\\n                                <div t-if=\\"o.picking_type_id.code == 'internal' and o.partner_id\\" class=\\"col\\" name=\\"div_contact\\">\\n                                    <strong>Contact</strong>\\n                                    <div t-field=\\"o.partner_id\\" class=\\"m-0\\"/>\\n                                </div>\\n                                <div name=\\"div_state\\">\\n                                    <strong>Status:</strong>\\n                                    <p t-field=\\"o.state\\">Draft</p>\\n                                </div>\\n                                <div t-if=\\"o.user_id\\" name=\\"div_operator\\">\\n                                    <strong>Operator:</strong>\\n                                    <p t-field=\\"o.user_id\\">Mitchel Admin</p>\\n                                </div>\\n                                <div name=\\"div_picking_date\\">\\n                                    <t t-if=\\"o.state == 'done' and o.date_done\\">\\n                                        <strong>Done Date:</strong>\\n                                        <p t-field=\\"o.date_done\\" t-options=\\"{&quot;widget&quot;: &quot;date&quot;}\\">2023-09-24</p>\\n                                    </t>\\n                                    <t t-elif=\\"o.state != 'done' and o.scheduled_date\\">\\n                                        <strong>Scheduled Date:</strong>\\n                                        <p t-field=\\"o.scheduled_date\\" t-options=\\"{&quot;widget&quot;: &quot;date&quot;}\\">2023-09-24</p>\\n                                    </t>\\n                                </div>\\n                                <div name=\\"div_warn\\" t-if=\\"o.picking_warning_text\\">\\n                                    <strong>Instructions:</strong>\\n                                    <div t-field=\\"o.picking_warning_text\\"/>\\n                                </div>\\n                                <div name=\\"div_vendor\\" t-if=\\"o.picking_type_id.code=='incoming' and o.partner_id\\">\\n                                    <strong>From:</strong>\\n                                    <div t-field=\\"o.partner_id.commercial_partner_id\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}\\">\\n                                    </div>\\n                                </div>\\n                            </div>\\n                            <t t-set=\\"format_number\\" t-value=\\"lambda x: int(x) if x == int(x) else x\\"/>\\n                            <!-- In this step, we loop over every move of the picking and do the following\\n                                1. We add the barcode column if any of the products has a barcode or if we have a tracked move\\n                                2. We add From/To columns according to the type of the picking\\n                                3. If a move has multiple move lines, we add a header line summarizing the move,\\n                                then we then loop over indvidual move lines and print a breakdown of them\\n                                4. If a move contains only one move line, the move is summarized in the heading only\\n                            -->\\n                            <table class=\\"table o_main_table\\" t-if=\\"o.move_line_ids and o.move_ids.move_line_ids.filtered(lambda ml: not ml.is_entire_pack)\\" style=\\"table-layout: fixed; width: 100%\\">\\n                                <t t-set=\\"picking_has_barcode\\" t-value=\\"any(move_line.product_id and move_line.product_id.barcode for move_line in o.move_line_ids)\\"/>\\n                                <t t-set=\\"picking_has_serial_number\\" t-value=\\"any(move_line.lot_id or move_line.lot_name for move_line in o.move_line_ids)\\" groups=\\"stock.group_production_lot\\"/>\\n                                <t t-set=\\"barcode_col_exists\\" t-value=\\"picking_has_barcode or picking_has_serial_number\\"/>\\n                                <t t-set=\\"from_col_exists\\" t-value=\\"o.picking_type_id.code != 'incoming'\\"/>\\n                                <t t-set=\\"to_col_exists\\" t-value=\\"o.picking_type_id.code != 'outgoing'\\"/>\\n                                <thead>\\n                                    <tr>\\n                                        <th name=\\"th_product\\" class=\\"text-start\\">\\n                                            <strong>Product</strong>\\n                                        </th>\\n                                        <th name=\\"th_quantity\\" class=\\"text-end\\">\\n                                            <strong>Quantity</strong>\\n                                        </th>\\n                                        <th name=\\"th_from\\" class=\\"text-start\\" t-if=\\"from_col_exists\\" groups=\\"stock.group_stock_multi_locations\\">\\n                                            <strong>From</strong>\\n                                        </th>\\n                                        <th name=\\"th_to\\" class=\\"text-start\\" t-if=\\"to_col_exists\\" groups=\\"stock.group_stock_multi_locations\\">\\n                                            <strong>To</strong>\\n                                        </th>\\n                                        <th name=\\"th_barcode\\" class=\\"text-center\\" t-if=\\"barcode_col_exists\\">\\n                                            <strong>Barcode</strong>\\n                                        </th>\\n                                    </tr>\\n                                </thead>\\n                                <tbody>\\n                                    <t t-foreach=\\"o.move_ids.filtered(lambda m: m.quantity and any(not ml.is_entire_pack for ml in m.move_line_ids)).sorted(key=lambda                                                   move: (move.move_line_ids and move.move_line_ids[0].location_id.complete_name,                                                   move.move_line_ids and move.move_line_ids[0].location_dest_id.complete_name))\\" t-as=\\"move\\">\\n                                        <t t-set=\\"move_lines_without_entire_pack\\" t-value=\\"move.move_line_ids.filtered(lambda ml: not ml.is_entire_pack)\\"/>\\n                                        <!-- This flag is true if there are multiple move lines in a move, or if there is at least one tracked move line -->\\n                                        <t t-set=\\"move_has_multiple_lines\\" t-value=\\"len(move.move_line_ids) &gt; 1 or any(move_line.lot_id or move_line.lot_name for move_line in move_lines_without_entire_pack)\\"/>\\n                                        <tr>\\n                                            <td class=\\"text-start\\">\\n                                                <span t-field=\\"move.product_id.display_name\\">Customizable Desk</span><br/>\\n                                                <span t-if=\\"move.description_picking and move.description_picking != move.product_id.name and move.description_picking != move.product_id.display_name\\">\\n                                                    <span t-out=\\"move.description_picking\\" t-options=\\"{'widget': 'text'}\\">Description on transfer</span>\\n                                                </span>\\n                                            </td>\\n                                            <td class=\\"o_td_quantity text-end\\">\\n                                                <span t-out=\\"format_number(move.quantity)\\" class=\\"text-nowrap\\">3.00</span>\\n                                                <span t-field=\\"move.uom_id\\" groups=\\"uom.group_uom\\">units</span>\\n                                                <span t-if=\\"move.packaging_uom_id and move.packaging_uom_id != move.uom_id\\">\\n                                                    (<span t-field=\\"move.packaging_uom_qty\\" t-options=\\"{&quot;widget&quot;: &quot;integer&quot;}\\"/> <span t-field=\\"move.packaging_uom_id.name\\"/>)\\n                                                </span>\\n                                            </td>\\n                                            <!-- If a move contains only one move line, the move is summarized in the heading only -->\\n                                            <td class=\\"text-start\\" t-if=\\"from_col_exists\\" groups=\\"stock.group_stock_multi_locations\\">\\n                                                <div t-if=\\"move.move_line_ids and not move_has_multiple_lines\\">\\n                                                    <span t-field=\\"move.move_line_ids[0].location_id.display_name\\">WH/Stock</span>\\n                                                    <t t-if=\\"move.move_line_ids[0].package_id\\">\\n                                                        <span t-field=\\"move.move_line_ids[0].package_id\\">Package A</span>\\n                                                    </t>\\n                                                </div>\\n                                            </td>\\n                                            <!-- If a move contains only one move line, the move is summarized in the heading only -->\\n                                            <td class=\\"text-start\\" t-if=\\"to_col_exists\\" groups=\\"stock.group_stock_multi_locations\\">\\n                                                <div t-if=\\"move.move_line_ids and not move_has_multiple_lines\\">\\n                                                    <span t-field=\\"move.move_line_ids[0].location_dest_id.display_name\\">WH/Outgoing</span>\\n                                                    <t t-if=\\"move.move_line_ids[0].result_package_id\\">\\n                                                        <span t-field=\\"move.move_line_ids[0].result_package_id\\">Package B</span>\\n                                                    </t>\\n                                                </div>\\n                                            </td>\\n                                            <!-- We add the barcode column if any of the products has a barcode or if we have a tracked move -->\\n                                            <td class=\\"text-center\\" t-if=\\"barcode_col_exists\\">\\n                                                <span t-if=\\"move.product_id and move.product_id.barcode\\">\\n                                                    <div t-field=\\"move.product_id.barcode\\" t-options=\\"{'widget': 'barcode', 'symbology': 'auto', 'width': 400, 'height': 100, 'quiet': 0, 'img_style': 'height:35px;'}\\">\\n                                                        <div class=\\"bg-light border-1 rounded d-flex flex-column align-items-center justify-content-center px-1 py-2 opacity-75 text-muted text-center\\">\\n                                                            (product barcode)\\n                                                        </div>\\n                                                    </div>\\n                                                </span>\\n                                            </td>\\n                                        </tr>\\n                                        <!-- If a move has multiple move lines, we then loop over them and print a breakdown -->\\n                                        <t t-foreach=\\"move_lines_without_entire_pack.sorted(key=lambda ml: (ml.location_id.complete_name,                                                       ml.location_dest_id.complete_name))\\" t-as=\\"line\\" t-if=\\"move_has_multiple_lines\\">\\n                                            <tr>\\n                                                <td class=\\"text-start\\">\\n                                                    <span style=\\"margin-left: 50px;\\" t-if=\\"line.lot_id or line.lot_name\\" t-out=\\"line.lot_id.name\\"/>\\n                                                </td>\\n                                                <td class=\\"text-end\\">\\n                                                    <span t-out=\\"format_number(line.quantity)\\">3.00</span>\\n                                                    <span t-field=\\"line.uom_id\\" groups=\\"uom.group_uom\\">units</span>\\n                                                </td>\\n                                                <td class=\\"text-start\\" t-if=\\"from_col_exists\\" groups=\\"stock.group_stock_multi_locations\\">\\n                                                    <span t-field=\\"line.location_id.display_name\\">WH/Stock</span>\\n                                                    <t t-if=\\"line.package_id\\">\\n                                                        <span t-field=\\"line.package_id\\">Package A</span>\\n                                                    </t>\\n                                                </td>\\n                                                <td class=\\"text-start\\" t-if=\\"to_col_exists\\" groups=\\"stock.group_stock_multi_locations\\">\\n                                                    <span t-field=\\"line.location_dest_id.display_name\\">WH/Outgoing</span>\\n                                                    <t t-if=\\"line.result_package_id\\">\\n                                                        <span t-field=\\"line.result_package_id\\">Package A</span>\\n                                                    </t>\\n                                                </td>\\n                                                <td class=\\" text-center h6\\" t-if=\\"barcode_col_exists\\">\\n                                                    <span t-if=\\"line.lot_id or line.lot_name\\" t-out=\\"line.lot_id.name or line.lot_name\\" t-options=\\"{'widget': 'barcode', 'humanreadable': 1, 'width': 400, 'height': 100, 'img_style': 'width:100%;height:35px;'}\\">\\n                                                        <div class=\\"bg-light border-1 rounded d-flex flex-column align-items-center justify-content-center px-1 py-2 opacity-75 text-muted text-center\\">\\n                                                            (serial barcode)\\n                                                        </div>\\n                                                    </span>\\n                                                </td>\\n                                            </tr>\\n                                        </t>\\n                                    </t>\\n                                    </tbody>\\n                            </table>\\n                            <div t-if=\\"not (any(ml.is_entire_pack for ml in o.move_line_ids) and o.state in ['assigned', 'done'])\\" class=\\"oe_structure\\"/>\\n                            <table t-else=\\"\\" class=\\"table table-borderless\\">\\n                                <thead>\\n                                    <tr>\\n                                        <th name=\\"th_package\\">Package</th>\\n                                        <th name=\\"th_pko_from\\" t-if=\\"o.picking_type_id.code != 'incoming'\\" groups=\\"stock.group_stock_multi_locations\\">From</th>\\n                                        <th name=\\"th_pki_from\\" t-if=\\"o.picking_type_id.code != 'outgoing'\\" groups=\\"stock.group_stock_multi_locations\\">To</th>\\n                                    </tr>\\n                                </thead>\\n                                <tbody>\\n                                    <t t-if=\\"o.state != 'done'\\">\\n                                        <tr t-foreach=\\"o.move_line_ids.filtered(lambda ml: ml.is_entire_pack).package_id.outermost_package_id.sorted(key=lambda p: p.name)\\" t-as=\\"package\\">\\n                                            <td name=\\"td_pk_barcode\\">\\n                                                <t t-set=\\"package\\" t-value=\\"package.with_context(picking_id=o.id)\\"/>\\n                                                <div t-field=\\"package.name\\" t-options=\\"{'widget': 'barcode', 'humanreadable': 1, 'width': 600, 'height': 100, 'img_style': 'width:300px;height:50px;margin-left: -50px;'}\\">\\n                                                    <div class=\\"bg-light border-1 rounded d-flex flex-column align-items-center justify-content-center px-1 py-2  opacity-75 text-muted text-center\\">\\n                                                        (package barcode)\\n                                                    </div>\\n                                                </div>\\n                                                    <br/>\\n                                            </td>\\n                                            <td t-if=\\"o.picking_type_id.code != 'incoming'\\" groups=\\"stock.group_stock_multi_locations\\">\\n                                                <span t-field=\\"package.location_id\\"/>\\n                                                <span t-field=\\"package.parent_package_id\\"/>\\n                                            </td>\\n                                            <td t-if=\\"o.picking_type_id.code != 'outgoing'\\" groups=\\"stock.group_stock_multi_locations\\">\\n                                                <span t-field=\\"package.location_dest_id\\"/>\\n                                                <span t-field=\\"package.package_dest_id\\"/>\\n                                            </td>\\n                                        </tr>\\n                                    </t>\\n                                    <t t-else=\\"\\">\\n                                        <tr t-foreach=\\"o.package_history_ids.filtered(lambda ph: not ph.parent_dest_id and all(ml.is_entire_pack for ml in ph.move_line_ids)).sorted(key=lambda ph: ph.package_id.name)\\" t-as=\\"package_history\\">\\n                                            <td name=\\"td_pk_barcode\\">\\n                                                <t t-set=\\"package\\" t-value=\\"package_history.package_id.with_context(picking_id=o.id)\\"/>\\n                                                <div t-field=\\"package.name\\" t-options=\\"{'widget': 'barcode', 'humanreadable': 1, 'width': 600, 'height': 100, 'img_style': 'width:300px;height:50px;margin-left: -50px;'}\\">\\n                                                    <div class=\\"bg-light border-1 rounded d-flex flex-column align-items-center justify-content-center px-1 py-2  opacity-75 text-muted text-center\\">\\n                                                        (package barcode)\\n                                                    </div>\\n                                                </div>\\n                                                <br/>\\n                                            </td>\\n                                            <td t-if=\\"o.picking_type_id.code != 'incoming'\\" groups=\\"stock.group_stock_multi_locations\\">\\n                                                <span t-field=\\"package_history.location_id\\"/>\\n                                                <span t-field=\\"package_history.parent_orig_id\\"/>\\n                                            </td>\\n                                            <td t-if=\\"o.picking_type_id.code != 'outgoing'\\" groups=\\"stock.group_stock_multi_locations\\">\\n                                                <span t-field=\\"package_history.location_dest_id\\"/>\\n                                                <span t-field=\\"package_history.parent_dest_id\\"/>\\n                                            </td>\\n                                        </tr>\\n                                    </t>\\n                                </tbody>\\n                            </table>\\n\\n                            <t t-set=\\"no_reserved_product\\" t-value=\\"o.move_ids.filtered(lambda x: x.product_uom_qty &gt; x.quantity and x.move_line_ids and x.state!='done')\\"/>\\n                            <p t-if=\\"o.state in ['draft', 'waiting', 'confirmed'] or no_reserved_product\\"><i class=\\"oi\\" data-icon=\\"warning\\"/>\\n                                All products could not be reserved. Click on the \\"Reserve\\" button to try to reserve products.\\n                            </p>\\n                            <p t-else=\\"\\"/>\\n                            <div class=\\"oe_structure\\"/>\\n                            <p t-field=\\"o.note\\"/>\\n                            <div class=\\"oe_structure\\"/>\\n                        </div>\\n                        <t t-if=\\"not o_last\\">\\n                            <p style=\\"page-break-after: always;\\"/>\\n                        </t>\\n                    </t>\\n                </div>\\n            </t>\\n        </t>", "es_ES": "<t t-name=\\"stock.report_picking\\">\\n            <t t-call=\\"web.report_layout\\">\\n                <div class=\\"article o_report_layout_standard\\">\\n                    <t t-foreach=\\"docs\\" t-as=\\"o\\">\\n                        <t t-set=\\"address\\" t-value=\\"None\\"/>\\n                        <div class=\\"page\\">\\n                            <div class=\\"row justify-content-between\\">\\n                                <div class=\\"col-4\\">\\n                                    <h3 t-field=\\"o.picking_type_id.code\\"/>\\n                                    <h2 t-field=\\"o.name\\">WH/OUT/00001</h2>\\n                                </div>\\n                                <div class=\\"col-8\\" name=\\"right_box\\">\\n                                    <div t-field=\\"o.name\\" style=\\"display:flex;justify-content:flex-end;display:-webkit-box;-webkit-box-pack:end;\\" t-options=\\"{'widget': 'barcode', 'width': 600, 'height': 100, 'img_style': 'width:300px;height:50px;margin-right:0;'}\\">\\n                                        <div class=\\"bg-light border-1 rounded d-flex flex-column align-items-center justify-content-center p-3 opacity-75 text-muted text-center\\">\\n                                            (código de barras del documento)\\n                                        </div>\\n                                    </div>\\n                                </div>\\n                            </div>\\n                            <div class=\\"row\\">\\n                                <div class=\\"col-6\\" name=\\"div_outgoing_address\\">\\n                                    <div t-if=\\"o.should_print_delivery_address()\\">\\n                                        <strong>Dirección de entrega:</strong>\\n                                        <div t-out=\\"o.move_ids[0].partner_id or o.partner_id\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}\\">\\n                                                <div class=\\"bg-light border-1 rounded h-100 d-flex flex-column align-items-center justify-content-center p-4 opacity-75 text-muted text-center\\">\\n                                                    <strong>Dirección de entrega</strong>\\n                                                    <div>La presencia depende de la categoría de la operación.</div>\\n                                                </div>\\n                                        </div>\\n                                    </div>\\n                                </div>\\n                                <div class=\\"col-5 offset-1\\" name=\\"div_customer_address\\" t-if=\\"o.picking_type_id.code=='outgoing' and o.partner_id and o.partner_id != o.partner_id.commercial_partner_id\\">\\n                                    <div>\\n                                        <span><strong>Dirección del Cliente:</strong></span>\\n                                    </div>\\n                                    <div name=\\"partner_header\\">\\n                                        <div t-field=\\"o.partner_id.commercial_partner_id\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;, &quot;vat&quot;] if show_full_address else [&quot;name&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}\\">\\n                                                <div class=\\"bg-light border-1 rounded h-100 d-flex flex-column align-items-center justify-content-center p-4 opacity-75 text-muted text-center\\">\\n                                                <strong>Dirección del destinatario</strong>\\n                                                <div>La presencia depende de la categoría de la operación.</div>\\n                                            </div>\\n                                        </div>\\n                                    </div>\\n                                </div>\\n                            </div>\\n                            <div class=\\"oe_structure\\"/>\\n                            <div class=\\"mt32 mb32 o_stock_report_header_row\\">\\n                                <div t-if=\\"o.origin\\" name=\\"div_origin\\">\\n                                    <strong>Orden:</strong>\\n                                    <p t-field=\\"o.origin\\">S0001</p>\\n                                </div>\\n                                <div name=\\"div_warehouse\\">\\n                                    <strong>Almacén:</strong>\\n                                    <div t-if=\\"o.picking_type_id.warehouse_id.partner_id\\" t-field=\\"o.picking_type_id.warehouse_id.partner_id\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;name&quot;], &quot;no_marker&quot;: True}\\"/>\\n                                    <div t-else=\\"\\" t-field=\\"o.picking_type_id.warehouse_id.name\\"/>\\n                                    </div>\\n                                <div t-if=\\"o.picking_type_id.code == 'internal' and o.partner_id\\" class=\\"col\\" name=\\"div_contact\\">\\n                                    <strong>Contacto</strong>\\n                                    <div t-field=\\"o.partner_id\\" class=\\"m-0\\"/>\\n                                </div>\\n                                <div name=\\"div_state\\">\\n                                    <strong>Estado:</strong>\\n                                    <p t-field=\\"o.state\\">Borrador</p>\\n                                </div>\\n                                <div t-if=\\"o.user_id\\" name=\\"div_operator\\">\\n                                    <strong>Operador:</strong>\\n                                    <p t-field=\\"o.user_id\\">Mitchel Admin</p>\\n                                </div>\\n                                <div name=\\"div_picking_date\\">\\n                                    <t t-if=\\"o.state == 'done' and o.date_done\\">\\n                                        <strong>Fecha de finalización:</strong>\\n                                        <p t-field=\\"o.date_done\\" t-options=\\"{&quot;widget&quot;: &quot;date&quot;}\\">2023-09-24</p>\\n                                    </t>\\n                                    <t t-elif=\\"o.state != 'done' and o.scheduled_date\\">\\n                                        <strong>Cita agendada:</strong>\\n                                        <p t-field=\\"o.scheduled_date\\" t-options=\\"{&quot;widget&quot;: &quot;date&quot;}\\">2023-09-24</p>\\n                                    </t>\\n                                </div>\\n                                <div name=\\"div_warn\\" t-if=\\"o.picking_warning_text\\">\\n                                    <strong>Instrucciones:</strong>\\n                                    <div t-field=\\"o.picking_warning_text\\"/>\\n                                </div>\\n                                <div name=\\"div_vendor\\" t-if=\\"o.picking_type_id.code=='incoming' and o.partner_id\\">\\n                                    <strong>De:</strong>\\n                                    <div t-field=\\"o.partner_id.commercial_partner_id\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}\\">\\n                                    </div>\\n                                </div>\\n                            </div>\\n                            <t t-set=\\"format_number\\" t-value=\\"lambda x: int(x) if x == int(x) else x\\"/>\\n                            <!-- In this step, we loop over every move of the picking and do the following\\n                                1. We add the barcode column if any of the products has a barcode or if we have a tracked move\\n                                2. We add From/To columns according to the type of the picking\\n                                3. If a move has multiple move lines, we add a header line summarizing the move,\\n                                then we then loop over indvidual move lines and print a breakdown of them\\n                                4. If a move contains only one move line, the move is summarized in the heading only\\n                            -->\\n                            <table class=\\"table o_main_table\\" t-if=\\"o.move_line_ids and o.move_ids.move_line_ids.filtered(lambda ml: not ml.is_entire_pack)\\" style=\\"table-layout: fixed; width: 100%\\">\\n                                <t t-set=\\"picking_has_barcode\\" t-value=\\"any(move_line.product_id and move_line.product_id.barcode for move_line in o.move_line_ids)\\"/>\\n                                <t t-set=\\"picking_has_serial_number\\" t-value=\\"any(move_line.lot_id or move_line.lot_name for move_line in o.move_line_ids)\\" groups=\\"stock.group_production_lot\\"/>\\n                                <t t-set=\\"barcode_col_exists\\" t-value=\\"picking_has_barcode or picking_has_serial_number\\"/>\\n                                <t t-set=\\"from_col_exists\\" t-value=\\"o.picking_type_id.code != 'incoming'\\"/>\\n                                <t t-set=\\"to_col_exists\\" t-value=\\"o.picking_type_id.code != 'outgoing'\\"/>\\n                                <thead>\\n                                    <tr>\\n                                        <th name=\\"th_product\\" class=\\"text-start\\">\\n                                            <strong>Producto</strong>\\n                                        </th>\\n                                        <th name=\\"th_quantity\\" class=\\"text-end\\">\\n                                            <strong>Cantidad</strong>\\n                                        </th>\\n                                        <th name=\\"th_from\\" class=\\"text-start\\" t-if=\\"from_col_exists\\" groups=\\"stock.group_stock_multi_locations\\">\\n                                            <strong>Desde</strong>\\n                                        </th>\\n                                        <th name=\\"th_to\\" class=\\"text-start\\" t-if=\\"to_col_exists\\" groups=\\"stock.group_stock_multi_locations\\">\\n                                            <strong>A</strong>\\n                                        </th>\\n                                        <th name=\\"th_barcode\\" class=\\"text-center\\" t-if=\\"barcode_col_exists\\">\\n                                            <strong>Código de barras</strong>\\n                                        </th>\\n                                    </tr>\\n                                </thead>\\n                                <tbody>\\n                                    <t t-foreach=\\"o.move_ids.filtered(lambda m: m.quantity and any(not ml.is_entire_pack for ml in m.move_line_ids)).sorted(key=lambda                                                   move: (move.move_line_ids and move.move_line_ids[0].location_id.complete_name,                                                   move.move_line_ids and move.move_line_ids[0].location_dest_id.complete_name))\\" t-as=\\"move\\">\\n                                        <t t-set=\\"move_lines_without_entire_pack\\" t-value=\\"move.move_line_ids.filtered(lambda ml: not ml.is_entire_pack)\\"/>\\n                                        <!-- This flag is true if there are multiple move lines in a move, or if there is at least one tracked move line -->\\n                                        <t t-set=\\"move_has_multiple_lines\\" t-value=\\"len(move.move_line_ids) &gt; 1 or any(move_line.lot_id or move_line.lot_name for move_line in move_lines_without_entire_pack)\\"/>\\n                                        <tr>\\n                                            <td class=\\"text-start\\">\\n                                                <span t-field=\\"move.product_id.display_name\\">Escritorio personalizable</span><br/>\\n                                                <span t-if=\\"move.description_picking and move.description_picking != move.product_id.name and move.description_picking != move.product_id.display_name\\">\\n                                                    <span t-out=\\"move.description_picking\\" t-options=\\"{'widget': 'text'}\\">Descripción en el traslado</span>\\n                                                </span>\\n                                            </td>\\n                                            <td class=\\"o_td_quantity text-end\\">\\n                                                <span t-out=\\"format_number(move.quantity)\\" class=\\"text-nowrap\\">3.00</span>\\n                                                <span t-field=\\"move.uom_id\\" groups=\\"uom.group_uom\\">unidades</span>\\n                                                <span t-if=\\"move.packaging_uom_id and move.packaging_uom_id != move.uom_id\\">\\n                                                    (<span t-field=\\"move.packaging_uom_qty\\" t-options=\\"{&quot;widget&quot;: &quot;integer&quot;}\\"/> <span t-field=\\"move.packaging_uom_id.name\\"/>)\\n                                                </span>\\n                                            </td>\\n                                            <!-- If a move contains only one move line, the move is summarized in the heading only -->\\n                                            <td class=\\"text-start\\" t-if=\\"from_col_exists\\" groups=\\"stock.group_stock_multi_locations\\">\\n                                                <div t-if=\\"move.move_line_ids and not move_has_multiple_lines\\">\\n                                                    <span t-field=\\"move.move_line_ids[0].location_id.display_name\\">WH/Stock</span>\\n                                                    <t t-if=\\"move.move_line_ids[0].package_id\\">\\n                                                        <span t-field=\\"move.move_line_ids[0].package_id\\">Paquete A</span>\\n                                                    </t>\\n                                                </div>\\n                                            </td>\\n                                            <!-- If a move contains only one move line, the move is summarized in the heading only -->\\n                                            <td class=\\"text-start\\" t-if=\\"to_col_exists\\" groups=\\"stock.group_stock_multi_locations\\">\\n                                                <div t-if=\\"move.move_line_ids and not move_has_multiple_lines\\">\\n                                                    <span t-field=\\"move.move_line_ids[0].location_dest_id.display_name\\">WH/Outgoing</span>\\n                                                    <t t-if=\\"move.move_line_ids[0].result_package_id\\">\\n                                                        <span t-field=\\"move.move_line_ids[0].result_package_id\\">Paquete B</span>\\n                                                    </t>\\n                                                </div>\\n                                            </td>\\n                                            <!-- We add the barcode column if any of the products has a barcode or if we have a tracked move -->\\n                                            <td class=\\"text-center\\" t-if=\\"barcode_col_exists\\">\\n                                                <span t-if=\\"move.product_id and move.product_id.barcode\\">\\n                                                    <div t-field=\\"move.product_id.barcode\\" t-options=\\"{'widget': 'barcode', 'symbology': 'auto', 'width': 400, 'height': 100, 'quiet': 0, 'img_style': 'height:35px;'}\\">\\n                                                        <div class=\\"bg-light border-1 rounded d-flex flex-column align-items-center justify-content-center px-1 py-2 opacity-75 text-muted text-center\\">\\n                                                            (código de barras del producto)\\n                                                        </div>\\n                                                    </div>\\n                                                </span>\\n                                            </td>\\n                                        </tr>\\n                                        <!-- If a move has multiple move lines, we then loop over them and print a breakdown -->\\n                                        <t t-foreach=\\"move_lines_without_entire_pack.sorted(key=lambda ml: (ml.location_id.complete_name,                                                       ml.location_dest_id.complete_name))\\" t-as=\\"line\\" t-if=\\"move_has_multiple_lines\\">\\n                                            <tr>\\n                                                <td class=\\"text-start\\">\\n                                                    <span style=\\"margin-left: 50px;\\" t-if=\\"line.lot_id or line.lot_name\\" t-out=\\"line.lot_id.name\\"/>\\n                                                </td>\\n                                                <td class=\\"text-end\\">\\n                                                    <span t-out=\\"format_number(line.quantity)\\">3.00</span>\\n                                                    <span t-field=\\"line.uom_id\\" groups=\\"uom.group_uom\\">unidades</span>\\n                                                </td>\\n                                                <td class=\\"text-start\\" t-if=\\"from_col_exists\\" groups=\\"stock.group_stock_multi_locations\\">\\n                                                    <span t-field=\\"line.location_id.display_name\\">WH/Stock</span>\\n                                                    <t t-if=\\"line.package_id\\">\\n                                                        <span t-field=\\"line.package_id\\">Paquete A</span>\\n                                                    </t>\\n                                                </td>\\n                                                <td class=\\"text-start\\" t-if=\\"to_col_exists\\" groups=\\"stock.group_stock_multi_locations\\">\\n                                                    <span t-field=\\"line.location_dest_id.display_name\\">WH/Outgoing</span>\\n                                                    <t t-if=\\"line.result_package_id\\">\\n                                                        <span t-field=\\"line.result_package_id\\">Paquete A</span>\\n                                                    </t>\\n                                                </td>\\n                                                <td class=\\" text-center h6\\" t-if=\\"barcode_col_exists\\">\\n                                                    <span t-if=\\"line.lot_id or line.lot_name\\" t-out=\\"line.lot_id.name or line.lot_name\\" t-options=\\"{'widget': 'barcode', 'humanreadable': 1, 'width': 400, 'height': 100, 'img_style': 'width:100%;height:35px;'}\\">\\n                                                        <div class=\\"bg-light border-1 rounded d-flex flex-column align-items-center justify-content-center px-1 py-2 opacity-75 text-muted text-center\\">\\n                                                            (código de barras de la serie)\\n                                                        </div>\\n                                                    </span>\\n                                                </td>\\n                                            </tr>\\n                                        </t>\\n                                    </t>\\n                                    </tbody>\\n                            </table>\\n                            <div t-if=\\"not (any(ml.is_entire_pack for ml in o.move_line_ids) and o.state in ['assigned', 'done'])\\" class=\\"oe_structure\\"/>\\n                            <table t-else=\\"\\" class=\\"table table-borderless\\">\\n                                <thead>\\n                                    <tr>\\n                                        <th name=\\"th_package\\">Paquete</th>\\n                                        <th name=\\"th_pko_from\\" t-if=\\"o.picking_type_id.code != 'incoming'\\" groups=\\"stock.group_stock_multi_locations\\">Desde</th>\\n                                        <th name=\\"th_pki_from\\" t-if=\\"o.picking_type_id.code != 'outgoing'\\" groups=\\"stock.group_stock_multi_locations\\">A</th>\\n                                    </tr>\\n                                </thead>\\n                                <tbody>\\n                                    <t t-if=\\"o.state != 'done'\\">\\n                                        <tr t-foreach=\\"o.move_line_ids.filtered(lambda ml: ml.is_entire_pack).package_id.outermost_package_id.sorted(key=lambda p: p.name)\\" t-as=\\"package\\">\\n                                            <td name=\\"td_pk_barcode\\">\\n                                                <t t-set=\\"package\\" t-value=\\"package.with_context(picking_id=o.id)\\"/>\\n                                                <div t-field=\\"package.name\\" t-options=\\"{'widget': 'barcode', 'humanreadable': 1, 'width': 600, 'height': 100, 'img_style': 'width:300px;height:50px;margin-left: -50px;'}\\">\\n                                                    <div class=\\"bg-light border-1 rounded d-flex flex-column align-items-center justify-content-center px-1 py-2  opacity-75 text-muted text-center\\">\\n                                                        (código de barras del paquete)\\n                                                    </div>\\n                                                </div>\\n                                                    <br/>\\n                                            </td>\\n                                            <td t-if=\\"o.picking_type_id.code != 'incoming'\\" groups=\\"stock.group_stock_multi_locations\\">\\n                                                <span t-field=\\"package.location_id\\"/>\\n                                                <span t-field=\\"package.parent_package_id\\"/>\\n                                            </td>\\n                                            <td t-if=\\"o.picking_type_id.code != 'outgoing'\\" groups=\\"stock.group_stock_multi_locations\\">\\n                                                <span t-field=\\"package.location_dest_id\\"/>\\n                                                <span t-field=\\"package.package_dest_id\\"/>\\n                                            </td>\\n                                        </tr>\\n                                    </t>\\n                                    <t t-else=\\"\\">\\n                                        <tr t-foreach=\\"o.package_history_ids.filtered(lambda ph: not ph.parent_dest_id and all(ml.is_entire_pack for ml in ph.move_line_ids)).sorted(key=lambda ph: ph.package_id.name)\\" t-as=\\"package_history\\">\\n                                            <td name=\\"td_pk_barcode\\">\\n                                                <t t-set=\\"package\\" t-value=\\"package_history.package_id.with_context(picking_id=o.id)\\"/>\\n                                                <div t-field=\\"package.name\\" t-options=\\"{'widget': 'barcode', 'humanreadable': 1, 'width': 600, 'height': 100, 'img_style': 'width:300px;height:50px;margin-left: -50px;'}\\">\\n                                                    <div class=\\"bg-light border-1 rounded d-flex flex-column align-items-center justify-content-center px-1 py-2  opacity-75 text-muted text-center\\">\\n                                                        (código de barras del paquete)\\n                                                    </div>\\n                                                </div>\\n                                                <br/>\\n                                            </td>\\n                                            <td t-if=\\"o.picking_type_id.code != 'incoming'\\" groups=\\"stock.group_stock_multi_locations\\">\\n                                                <span t-field=\\"package_history.location_id\\"/>\\n                                                <span t-field=\\"package_history.parent_orig_id\\"/>\\n                                            </td>\\n                                            <td t-if=\\"o.picking_type_id.code != 'outgoing'\\" groups=\\"stock.group_stock_multi_locations\\">\\n                                                <span t-field=\\"package_history.location_dest_id\\"/>\\n                                                <span t-field=\\"package_history.parent_dest_id\\"/>\\n                                            </td>\\n                                        </tr>\\n                                    </t>\\n                                </tbody>\\n                            </table>\\n\\n                            <t t-set=\\"no_reserved_product\\" t-value=\\"o.move_ids.filtered(lambda x: x.product_uom_qty &gt; x.quantity and x.move_line_ids and x.state!='done')\\"/>\\n                            <p t-if=\\"o.state in ['draft', 'waiting', 'confirmed'] or no_reserved_product\\"><i class=\\"oi\\" data-icon=\\"warning\\"/>\\n                                All products could not be reserved. Click on the \\"Reserve\\" button to try to reserve products.\\n                            </p>\\n                            <p t-else=\\"\\"/>\\n                            <div class=\\"oe_structure\\"/>\\n                            <p t-field=\\"o.note\\"/>\\n                            <div class=\\"oe_structure\\"/>\\n                        </div>\\n                        <t t-if=\\"not o_last\\">\\n                            <p style=\\"page-break-after: always;\\"/>\\n                        </t>\\n                    </t>\\n                </div>\\n            </t>\\n        </t>"}	<?xml version="1.0"?>\n<t t-name="stock.report_picking">\n            <t t-call="web.report_layout">\n                <div class="article o_report_layout_standard">\n                    <t t-foreach="docs" t-as="o">\n                        <t t-set="address" t-value="None"/>\n                        <div class="page">\n                            <div class="row justify-content-between">\n                                <div class="col-4">\n                                    <h3 t-field="o.picking_type_id.code"/>\n                                    <h2 t-field="o.name">WH/OUT/00001</h2>\n                                </div>\n                                <div class="col-8" name="right_box">\n                                    <div t-field="o.name" style="display:flex;justify-content:flex-end;display:-webkit-box;-webkit-box-pack:end;" t-options="{'widget': 'barcode', 'width': 600, 'height': 100, 'img_style': 'width:300px;height:50px;margin-right:0;'}">\n                                        <div class="bg-light border-1 rounded d-flex flex-column align-items-center justify-content-center p-3 opacity-75 text-muted text-center">\n                                            (document barcode)\n                                        </div>\n                                    </div>\n                                </div>\n                            </div>\n                            <div class="row">\n                                <div class="col-6" name="div_outgoing_address">\n                                    <div t-if="o.should_print_delivery_address()">\n                                        <strong>Delivery Address:</strong>\n                                        <div t-out="o.move_ids[0].partner_id or o.partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}">\n                                                <div class="bg-light border-1 rounded h-100 d-flex flex-column align-items-center justify-content-center p-4 opacity-75 text-muted text-center">\n                                                    <strong>Delivery address</strong>\n                                                    <div>Presence depends on the operation category.</div>\n                                                </div>\n                                        </div>\n                                    </div>\n                                </div>\n                                <div class="col-5 offset-1" name="div_customer_address" t-if="o.picking_type_id.code=='outgoing' and o.partner_id and o.partner_id != o.partner_id.commercial_partner_id">\n                                    <div>\n                                        <span><strong>Customer Address:</strong></span>\n                                    </div>\n                                    <div name="partner_header">\n                                        <div t-field="o.partner_id.commercial_partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;, &quot;vat&quot;] if show_full_address else [&quot;name&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}">\n                                                <div class="bg-light border-1 rounded h-100 d-flex flex-column align-items-center justify-content-center p-4 opacity-75 text-muted text-center">\n                                                <strong>Recipient address</strong>\n                                                <div>Presence depends on the operation category.</div>\n                                            </div>\n                                        </div>\n                                    </div>\n                                </div>\n                            </div>\n                            <div class="oe_structure"/>\n                            <div class="mt32 mb32 o_stock_report_header_row">\n                                <div t-if="o.origin" name="div_origin">\n                                    <strong>Order:</strong>\n                                    <p t-field="o.origin">S0001</p>\n                                </div>\n                                <div name="div_warehouse">\n                                    <strong>Warehouse:</strong>\n                                    <div t-if="o.picking_type_id.warehouse_id.partner_id" t-field="o.picking_type_id.warehouse_id.partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;name&quot;], &quot;no_marker&quot;: True}"/>\n                                    <div t-else="" t-field="o.picking_type_id.warehouse_id.name"/>\n                                    </div>\n                                <div t-if="o.picking_type_id.code == 'internal' and o.partner_id" class="col" name="div_contact">\n                                    <strong>Contact</strong>\n                                    <div t-field="o.partner_id" class="m-0"/>\n                                </div>\n                                <div name="div_state">\n                                    <strong>Status:</strong>\n                                    <p t-field="o.state">Draft</p>\n                                </div>\n                                <div t-if="o.user_id" name="div_operator">\n                                    <strong>Operator:</strong>\n                                    <p t-field="o.user_id">Mitchel Admin</p>\n                                </div>\n                                <div name="div_picking_date">\n                                    <t t-if="o.state == 'done' and o.date_done">\n                                        <strong>Done Date:</strong>\n                                        <p t-field="o.date_done" t-options="{&quot;widget&quot;: &quot;date&quot;}">2023-09-24</p>\n                                    </t>\n                                    <t t-elif="o.state != 'done' and o.scheduled_date">\n                                        <strong>Scheduled Date:</strong>\n                                        <p t-field="o.scheduled_date" t-options="{&quot;widget&quot;: &quot;date&quot;}">2023-09-24</p>\n                                    </t>\n                                </div>\n                                <div name="div_warn" t-if="o.picking_warning_text">\n                                    <strong>Instructions:</strong>\n                                    <div t-field="o.picking_warning_text"/>\n                                </div>\n                                <div name="div_vendor" t-if="o.picking_type_id.code=='incoming' and o.partner_id">\n                                    <strong>From:</strong>\n                                    <div t-field="o.partner_id.commercial_partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}">\n                                    </div>\n                                </div>\n                            </div>\n                            <t t-set="format_number" t-value="lambda x: int(x) if x == int(x) else x"/>\n                            <!-- In this step, we loop over every move of the picking and do the following\n                                1. We add the barcode column if any of the products has a barcode or if we have a tracked move\n                                2. We add From/To columns according to the type of the picking\n                                3. If a move has multiple move lines, we add a header line summarizing the move,\n                                then we then loop over indvidual move lines and print a breakdown of them\n                                4. If a move contains only one move line, the move is summarized in the heading only\n                            -->\n                            <table class="table o_main_table" t-if="o.move_line_ids and o.move_ids.move_line_ids.filtered(lambda ml: not ml.is_entire_pack)" style="table-layout: fixed; width: 100%">\n                                <t t-set="picking_has_barcode" t-value="any(move_line.product_id and move_line.product_id.barcode for move_line in o.move_line_ids)"/>\n                                <t t-set="picking_has_serial_number" t-value="any(move_line.lot_id or move_line.lot_name for move_line in o.move_line_ids)" groups="stock.group_production_lot"/>\n                                <t t-set="barcode_col_exists" t-value="picking_has_barcode or picking_has_serial_number"/>\n                                <t t-set="from_col_exists" t-value="o.picking_type_id.code != 'incoming'"/>\n                                <t t-set="to_col_exists" t-value="o.picking_type_id.code != 'outgoing'"/>\n                                <thead>\n                                    <tr>\n                                        <th name="th_product" class="text-start">\n                                            <strong>Product</strong>\n                                        </th>\n                                        <th name="th_quantity" class="text-end">\n                                            <strong>Quantity</strong>\n                                        </th>\n                                        <th name="th_from" class="text-start" t-if="from_col_exists" groups="stock.group_stock_multi_locations">\n                                            <strong>From</strong>\n                                        </th>\n                                        <th name="th_to" class="text-start" t-if="to_col_exists" groups="stock.group_stock_multi_locations">\n                                            <strong>To</strong>\n                                        </th>\n                                        <th name="th_barcode" class="text-center" t-if="barcode_col_exists">\n                                            <strong>Barcode</strong>\n                                        </th>\n                                    </tr>\n                                </thead>\n                                <tbody>\n                                    <t t-foreach="o.move_ids.filtered(lambda m: m.quantity and any(not ml.is_entire_pack for ml in m.move_line_ids)).sorted(key=lambda                                                   move: (move.move_line_ids and move.move_line_ids[0].location_id.complete_name,                                                   move.move_line_ids and move.move_line_ids[0].location_dest_id.complete_name))" t-as="move">\n                                        <t t-set="move_lines_without_entire_pack" t-value="move.move_line_ids.filtered(lambda ml: not ml.is_entire_pack)"/>\n                                        <!-- This flag is true if there are multiple move lines in a move, or if there is at least one tracked move line -->\n                                        <t t-set="move_has_multiple_lines" t-value="len(move.move_line_ids) &gt; 1 or any(move_line.lot_id or move_line.lot_name for move_line in move_lines_without_entire_pack)"/>\n                                        <tr>\n                                            <td class="text-start">\n                                                <span t-field="move.product_id.display_name">Customizable Desk</span><br/>\n                                                <span t-if="move.description_picking and move.description_picking != move.product_id.name and move.description_picking != move.product_id.display_name">\n                                                    <span t-out="move.description_picking" t-options="{'widget': 'text'}">Description on transfer</span>\n                                                </span>\n                                            </td>\n                                            <td class="o_td_quantity text-end">\n                                                <span t-out="format_number(move.quantity)" class="text-nowrap">3.00</span>\n                                                <span t-field="move.uom_id" groups="uom.group_uom">units</span>\n                                                <span t-if="move.packaging_uom_id and move.packaging_uom_id != move.uom_id">\n                                                    (<span t-field="move.packaging_uom_qty" t-options="{&quot;widget&quot;: &quot;integer&quot;}"/> <span t-field="move.packaging_uom_id.name"/>)\n                                                </span>\n                                            </td>\n                                            <!-- If a move contains only one move line, the move is summarized in the heading only -->\n                                            <td class="text-start" t-if="from_col_exists" groups="stock.group_stock_multi_locations">\n                                                <div t-if="move.move_line_ids and not move_has_multiple_lines">\n                                                    <span t-field="move.move_line_ids[0].location_id.display_name">WH/Stock</span>\n                                                    <t t-if="move.move_line_ids[0].package_id">\n                                                        <span t-field="move.move_line_ids[0].package_id">Package A</span>\n                                                    </t>\n                                                </div>\n                                            </td>\n                                            <!-- If a move contains only one move line, the move is summarized in the heading only -->\n                                            <td class="text-start" t-if="to_col_exists" groups="stock.group_stock_multi_locations">\n                                                <div t-if="move.move_line_ids and not move_has_multiple_lines">\n                                                    <span t-field="move.move_line_ids[0].location_dest_id.display_name">WH/Outgoing</span>\n                                                    <t t-if="move.move_line_ids[0].result_package_id">\n                                                        <span t-field="move.move_line_ids[0].result_package_id">Package B</span>\n                                                    </t>\n                                                </div>\n                                            </td>\n                                            <!-- We add the barcode column if any of the products has a barcode or if we have a tracked move -->\n                                            <td class="text-center" t-if="barcode_col_exists">\n                                                <span t-if="move.product_id and move.product_id.barcode">\n                                                    <div t-field="move.product_id.barcode" t-options="{'widget': 'barcode', 'symbology': 'auto', 'width': 400, 'height': 100, 'quiet': 0, 'img_style': 'height:35px;'}">\n                                                        <div class="bg-light border-1 rounded d-flex flex-column align-items-center justify-content-center px-1 py-2 opacity-75 text-muted text-center">\n                                                            (product barcode)\n                                                        </div>\n                                                    </div>\n                                                </span>\n                                            </td>\n                                        </tr>\n                                        <!-- If a move has multiple move lines, we then loop over them and print a breakdown -->\n                                        <t t-foreach="move_lines_without_entire_pack.sorted(key=lambda ml: (ml.location_id.complete_name,                                                       ml.location_dest_id.complete_name))" t-as="line" t-if="move_has_multiple_lines">\n                                            <tr>\n                                                <td class="text-start">\n                                                    <span style="margin-left: 50px;" t-if="line.lot_id or line.lot_name" t-out="line.lot_id.name"/>\n                                                </td>\n                                                <td class="text-end">\n                                                    <span t-out="format_number(line.quantity)">3.00</span>\n                                                    <span t-field="line.uom_id" groups="uom.group_uom">units</span>\n                                                </td>\n                                                <td class="text-start" t-if="from_col_exists" groups="stock.group_stock_multi_locations">\n                                                    <span t-field="line.location_id.display_name">WH/Stock</span>\n                                                    <t t-if="line.package_id">\n                                                        <span t-field="line.package_id">Package A</span>\n                                                    </t>\n                                                </td>\n                                                <td class="text-start" t-if="to_col_exists" groups="stock.group_stock_multi_locations">\n                                                    <span t-field="line.location_dest_id.display_name">WH/Outgoing</span>\n                                                    <t t-if="line.result_package_id">\n                                                        <span t-field="line.result_package_id">Package A</span>\n                                                    </t>\n                                                </td>\n                                                <td class=" text-center h6" t-if="barcode_col_exists">\n                                                    <span t-if="line.lot_id or line.lot_name" t-out="line.lot_id.name or line.lot_name" t-options="{'widget': 'barcode', 'humanreadable': 1, 'width': 400, 'height': 100, 'img_style': 'width:100%;height:35px;'}">\n                                                        <div class="bg-light border-1 rounded d-flex flex-column align-items-center justify-content-center px-1 py-2 opacity-75 text-muted text-center">\n                                                            (serial barcode)\n                                                        </div>\n                                                    </span>\n                                                </td>\n                                            </tr>\n                                        </t>\n                                    </t>\n                                    </tbody>\n                            </table>\n                            <div t-if="not (any(ml.is_entire_pack for ml in o.move_line_ids) and o.state in ['assigned', 'done'])" class="oe_structure"/>\n                            <table t-else="" class="table table-borderless">\n                                <thead>\n                                    <tr>\n                                        <th name="th_package">Package</th>\n                                        <th name="th_pko_from" t-if="o.picking_type_id.code != 'incoming'" groups="stock.group_stock_multi_locations">From</th>\n                                        <th name="th_pki_from" t-if="o.picking_type_id.code != 'outgoing'" groups="stock.group_stock_multi_locations">To</th>\n                                    </tr>\n                                </thead>\n                                <tbody>\n                                    <t t-if="o.state != 'done'">\n                                        <tr t-foreach="o.move_line_ids.filtered(lambda ml: ml.is_entire_pack).package_id.outermost_package_id.sorted(key=lambda p: p.name)" t-as="package">\n                                            <td name="td_pk_barcode">\n                                                <t t-set="package" t-value="package.with_context(picking_id=o.id)"/>\n                                                <div t-field="package.name" t-options="{'widget': 'barcode', 'humanreadable': 1, 'width': 600, 'height': 100, 'img_style': 'width:300px;height:50px;margin-left: -50px;'}">\n                                                    <div class="bg-light border-1 rounded d-flex flex-column align-items-center justify-content-center px-1 py-2  opacity-75 text-muted text-center">\n                                                        (package barcode)\n                                                    </div>\n                                                </div>\n                                                    <br/>\n                                            </td>\n                                            <td t-if="o.picking_type_id.code != 'incoming'" groups="stock.group_stock_multi_locations">\n                                                <span t-field="package.location_id"/>\n                                                <span t-field="package.parent_package_id"/>\n                                            </td>\n                                            <td t-if="o.picking_type_id.code != 'outgoing'" groups="stock.group_stock_multi_locations">\n                                                <span t-field="package.location_dest_id"/>\n                                                <span t-field="package.package_dest_id"/>\n                                            </td>\n                                        </tr>\n                                    </t>\n                                    <t t-else="">\n                                        <tr t-foreach="o.package_history_ids.filtered(lambda ph: not ph.parent_dest_id and all(ml.is_entire_pack for ml in ph.move_line_ids)).sorted(key=lambda ph: ph.package_id.name)" t-as="package_history">\n                                            <td name="td_pk_barcode">\n                                                <t t-set="package" t-value="package_history.package_id.with_context(picking_id=o.id)"/>\n                                                <div t-field="package.name" t-options="{'widget': 'barcode', 'humanreadable': 1, 'width': 600, 'height': 100, 'img_style': 'width:300px;height:50px;margin-left: -50px;'}">\n                                                    <div class="bg-light border-1 rounded d-flex flex-column align-items-center justify-content-center px-1 py-2  opacity-75 text-muted text-center">\n                                                        (package barcode)\n                                                    </div>\n                                                </div>\n                                                <br/>\n                                            </td>\n                                            <td t-if="o.picking_type_id.code != 'incoming'" groups="stock.group_stock_multi_locations">\n                                                <span t-field="package_history.location_id"/>\n                                                <span t-field="package_history.parent_orig_id"/>\n                                            </td>\n                                            <td t-if="o.picking_type_id.code != 'outgoing'" groups="stock.group_stock_multi_locations">\n                                                <span t-field="package_history.location_dest_id"/>\n                                                <span t-field="package_history.parent_