ress_label\\" readonly=\\"1\\" class=\\"fw-bold\\"/>\\n                            </span>\\n                            <div class=\\"o_address_format\\">\\n                                <field name=\\"street\\" placeholder=\\"Calle...\\" class=\\"o_address_street\\"/>\\n                                <field name=\\"street2\\" placeholder=\\"Calle 2...\\" class=\\"o_address_street\\"/>\\n                                <field name=\\"city\\" placeholder=\\"Ciudad\\" class=\\"o_address_city\\"/>\\n                                <field name=\\"state_id\\" placeholder=\\"Provincia\\" class=\\"o_address_state\\" options=\\"{'no_open': True, 'no_quick_create': True}\\" context=\\"{'country_id': country_id, 'default_country_id': country_id, 'zip': zip}\\"/>\\n                                <field name=\\"zip\\" placeholder=\\"C.P.\\" class=\\"o_address_zip\\"/>\\n                                <div name=\\"partner_address_country\\" class=\\"d-flex justify-content-between\\">\\n                                    <field name=\\"country_id\\" placeholder=\\"País\\" class=\\"o_address_country\\" options=\\"{&quot;no_open&quot;: True, &quot;no_create&quot;: True}\\"/>\\n                                </div>\\n                            </div>\\n                            <div name=\\"identifiers\\" class=\\"o_wrap_label\\">\\n                                <label for=\\"vat\\"/>\\n                                <div id=\\"vat_div\\" class=\\"o_outlined o_row d-flex\\">\\n                                    <field name=\\"vat\\" nolabel=\\"1\\" placeholder=\\"p. ej., ESA00000000\\"/>\\n                                    <field name=\\"additional_identifiers\\" widget=\\"additional_identifiers_button\\" nolabel=\\"1\\"/>\\n                                </div>\\n                                <field name=\\"additional_identifiers\\" widget=\\"additional_identifiers_list\\" colspan=\\"2\\" nolabel=\\"1\\"/>\\n                            </div>\\n                        </group>\\n                        <group>\\n                            <field name=\\"function\\" placeholder=\\"p. ej. director de ventas\\"/>\\n                            <field name=\\"website\\" string=\\"Sitio web\\" widget=\\"url\\" placeholder=\\"p. ej. https://www.odoo.com\\"/>\\n                            <field name=\\"lang\\" invisible=\\"active_lang_count &lt;= 1\\"/>\\n                            <field name=\\"category_id\\" widget=\\"many2many_tags\\" options=\\"{'color_field': 'color', 'on_tag_click': 'edit_color'}\\" placeholder=\\"p. ej., &quot;B2B&quot;, &quot;VIP&quot;, &quot;consultoría&quot;, ...\\"/>\\n                        </group>\\n                    </group>\\n                    <div class=\\"d-flex\\">\\n                        <field name=\\"properties\\" nolabel=\\"1\\" columns=\\"2\\"/>\\n                    </div>\\n\\n                    <notebook colspan=\\"4\\">\\n                        <page string=\\"Contactos\\" name=\\"contact_addresses\\" autofocus=\\"autofocus\\">\\n                            <field name=\\"child_ids\\" mode=\\"kanban\\" context=\\"{'default_parent_id': id, 'default_street': street, 'default_street2': street2, 'default_city': city, 'default_state_id': state_id, 'default_zip': zip, 'default_country_id': country_id, 'default_lang': lang, 'default_user_id': user_id, 'default_type': 'contact'}\\">\\n                                <kanban color=\\"color\\">\\n                                    <field name=\\"color\\"/>\\n                                    <field name=\\"type\\"/>\\n                                    <field name=\\"is_company\\"/>\\n                                    <field name=\\"image_128\\"/>\\n                                    <field name=\\"name\\"/>\\n                                    <templates>\\n                                        <t t-name=\\"card\\" class=\\"o_res_partner_kanban_card flex-row gap-2\\">\\n                                            <main class=\\"gap-2\\">\\n                                                <div class=\\"d-flex flex-column w-100\\">\\n                                                    <field name=\\"name\\" invisible=\\"not name\\" class=\\"flex-grow-1 fw-bold\\"/>\\n                                                    <field name=\\"type\\" invisible=\\"name\\" class=\\"flex-grow-1 fw-bold\\"/>\\n                                                    <span t-if=\\"record.type.raw_value != 'contact'\\" class=\\"text-muted\\">\\n                                                        <i class=\\"oi oi-fw me-1\\" t-att-data-icon=\\"{'invoice': 'description','delivery': 'local_shipping', 'other': 'deployed_code'}[record.type.raw_value]\\" role=\\"img\\" t-att-title=\\"{'invoice': 'Invoice','delivery': 'Delivery', 'other': 'Other'}[record.type.raw_value]\\"/>\\n                                                        <field name=\\"type\\"/> address\\n                                                    </span>\\n                                                </div>\\n                                                <div>\\n                                                    <div t-if=\\"record.email.raw_value\\" class=\\"text-truncate\\">\\n                                                        <i class=\\"oi oi-fw oi-filled me-1\\" data-icon=\\"mail\\" title=\\"Email\\"/>\\n                                                        <field name=\\"email\\"/>\\n                                                    </div>\\n                                                    <div t-if=\\"record.phone.raw_value\\">\\n                                                        <i class=\\"oi oi-fw oi-filled me-1\\" data-icon=\\"phone\\" title=\\"Phone\\"/>\\n                                                        <field name=\\"phone\\"/>\\n                                                    </div>\\n                                                    <div invisible=\\"not function\\">\\n                                                        <i class=\\"oi oi-fw me-1\\" data-icon=\\"luggage\\" title=\\"Position\\"/>\\n                                                        <field name=\\"function\\"/>\\n                                                    </div>\\n                                                    <div t-if=\\"record.type.raw_value != 'contact' and (record.city.raw_value or record.country_id.raw_value)\\">\\n                                                        <i class=\\"oi oi-fw me-1\\" data-icon=\\"location_on\\" title=\\"Location\\"/>\\n                                                        <field name=\\"city\\"/>\\n                                                        <span t-if=\\"record.city.raw_value and record.country_id.raw_value\\">, </span>\\n                                                        <field name=\\"country_id\\"/>\\n                                                    </div>\\n                                                </div>\\n                                            </main>\\n                                            <aside>\\n                                                <field name=\\"avatar_128\\" class=\\"o_card_image_fill w-100\\" widget=\\"image\\" options=\\"{'img_class': 'w-100 rounded border object-fit-contain'}\\"/>\\n                                            </aside>\\n                                        </t>\\n                                    </templates>\\n                                </kanban>\\n                                <form string=\\"Contacto/dirección\\">\\n                                    <sheet>\\n                                        <field name=\\"parent_id\\" invisible=\\"1\\"/>  <!-- Used for partner_autocomplete -->\\n                                        <field name=\\"type\\" required=\\"1\\" widget=\\"badges_selection\\" class=\\"mb-2 oi-filled\\" options=\\"{                                                  'icon_mapping': {                            