flex align-items-baseline w-md-50 gap-2\\">\\n                                                    <i class=\\"oi oi-filled d-none d-md-block\\" data-icon=\\"phone\\" title=\\"Phone\\"/>\\n                                                    <field name=\\"phone\\" widget=\\"phone\\" placeholder=\\"Teléfono\\"/>\\n                                                </div>\\n                                                <label for=\\"function\\" class=\\"d-md-none\\" invisible=\\"type != 'contact'\\"/>\\n                                                <div class=\\"d-flex align-items-baseline w-md-50 gap-2\\" invisible=\\"type != 'contact'\\">\\n                                                    <i class=\\"oi d-none d-md-block\\" data-icon=\\"luggage\\" title=\\"Position\\"/>\\n                                                    <field name=\\"function\\" placeholder=\\"Nombre del puesto\\"/>\\n                                                </div>\\n                                            </group>\\n                                        </div>\\n                                        <group invisible=\\"type == 'contact'\\" name=\\"other_info\\">\\n                                            <group>\\n                                                <span class=\\"o_form_label o_td_label o_address_type\\">\\n                                                    <field name=\\"type_address_label\\" readonly=\\"1\\" class=\\"fw-bold\\"/>\\n                                                </span>\\n                                                <div class=\\"o_address_format\\" name=\\"div_address\\">\\n                                                    <field name=\\"street\\" placeholder=\\"Calle...\\" class=\\"o_address_street\\"/>\\n                                                    <field name=\\"street2\\" placeholder=\\"Calle 2...\\" class=\\"o_address_street\\"/>\\n                                                    <field name=\\"city\\" placeholder=\\"Ciudad\\" class=\\"o_address_city\\"/>\\n                                                    <field name=\\"state_id\\" class=\\"o_address_state\\" placeholder=\\"Provincia\\" options=\\"{'no_open': True, 'no_quick_create': True}\\" context=\\"{'country_id': country_id, 'default_country_id': country_id, 'zip': zip}\\"/>\\n                                                    <field name=\\"zip\\" placeholder=\\"C.P.\\" class=\\"o_address_zip\\"/>\\n                                                    <field name=\\"country_id\\" placeholder=\\"País\\" class=\\"o_address_country\\" options=\\"{&quot;no_open&quot;: True, &quot;no_create&quot;: True}\\"/>\\n                                                </div>\\n                                            </group>\\n                                        </group>\\n                                        <group>\\n                                            <field name=\\"company_id\\" invisible=\\"1\\"/>    <!-- Need to save value from parented record, cf onchange -->\\n                                            <label for=\\"comment\\"/>\\n                                            <field name=\\"comment\\" options=\\"{'height': 100}\\" placeholder=\\"Notas internas...\\" nolabel=\\"1\\"/>\\n                                        </group>\\n                                        <field name=\\"lang\\" invisible=\\"True\\"/>  <!-- Need to add lang to save default value from parented record -->\\n                                    </sheet>\\n                                </form>\\n                            </field>\\n                        </page>\\n                        <page name=\\"sales_purchases\\" string=\\"Ventas y compras\\">\\n                            <group name=\\"container_row_2\\">\\n                                <group string=\\"Ventas\\" name=\\"sale\\" priority=\\"1\\">\\n                                    <field name=\\"user_id\\" widget=\\"many2one_avatar_user\\" domain=\\"[('share', '=', False)]\\"/>\\n                                </group>\\n                                <group string=\\"Compra\\" name=\\"purchase\\" priority=\\"2\\">\\n                                </group>\\n                                <group name=\\"misc\\" string=\\"Varios\\">\\n                                    <field name=\\"ref\\" string=\\"Referencia\\"/>\\n                                    <field name=\\"company_id\\" groups=\\"base.group_multi_company\\" options=\\"{'no_create': True}\\" readonly=\\"parent_id\\" force_save=\\"1\\" placeholder=\\"Visible para todos\\"/>\\n                                    <field name=\\"company_id\\" invisible=\\"1\\"/> <!-- need to be able to compute based on the company even without multi company groups -->\\n                                    <field name=\\"industry_id\\" options=\\"{'no_create': True}\\"/>\\n                                </group>\\n                            </group>\\n                        </page>\\n                        <page name=\\"internal_notes\\" string=\\"Notas\\">\\n                            <field name=\\"comment\\" placeholder=\\"Notas internas...\\"/>\\n                            <group name=\\"warnings\\"/>\\n                        </page>\\n                    </notebook>\\n                </sheet>\\n                </form>"}	<?xml version="1.0"?>\n<form string="Partners">\n                <div class="alert alert-warning oe_edit_only" role="alert" name="warning_tax" invisible="not same_vat_partner_id">\n                    Potential duplicates:\n                    <field name="same_vat_partner_id" context="{'show_address': False, 'show_identifier': False}"/>\n                    (Same <field name="vat_label"/>)\n                </div>\n                <sheet>\n                    <div class="oe_button_box" name="button_box"/>\n                    <widget name="web_ribbon" title="Archived" bg_color="text-bg-danger" invisible="active"/>\n                    <div class="d-flex flex-column flex-md-row align-items-center gap-3">\n                        <field name="image_1920" widget="contact_image" options="{'preview_image': 'avatar_128', 'size': [130,130], 'img_class': 'border rounded h-100 object-fit-contain'}"/>\n                        <field name="avatar_128" invisible="1"/> <!-- Needed in contact_image widget -->\n                        <group class="d-flex flex-column gap-md-0 w-100">\n                            <label for="name" class="d-md-none"/>\n                            <h1>\n                                <field options="{'line_breaks': False}" widget="text" class="text-break d-block" name="name" default_focus="1" placeholder="Name (company or person)" required="type == 'contact'"/>\n                            </h1>\n                            <label for="parent_id" class="d-md-none"/>\n                            <div class="d-flex align-items-baseline w-md-50 gap-2">\n                                <i class="oi d-none d-md-inline-flex" data-icon="business" title="Company"/>\n                                <field name="parent_id" widget="res_partner_many2one" placeholder="Company Employer" domain="[('parent_id', '=', False)]" context="{'default_user_id': user_id}"/>\n                            </div>\n\n                            <label for="email" class="d-md-none"/>\n                            <div class="d-flex align-items-baseline w-md-50 gap-2">\n                                <i class="oi oi-filled d-none d-md-inline-flex" data-icon="mail" title="Email"/>\n                                <field name="email" widget="email" required="user_ids" placeholder="Email"/>\n                            </div>\n\n                            <label for="phone" class="d-md-none"/>\n                            <div class="d-flex align-items-baseline w-md-50 gap-2">\n                                <i class="oi oi-filled d-none d-md-inline-flex" data-icon="phone" title="Phone"/>\n                                <field na