ron_ids or context.key != 'server_action'\\" context=\\"{'key': 'ir_cron'}\\" class=\\"oe_stat_button\\" icon=\\"refresh\\">\\n                                <div class=\\"o_stat_info\\">\\n                                    <span class=\\"o_stat_text\\">Acción programada</span>\\n                                </div>\\n                            </button>\\n                        </div>\\n                        <h1 class=\\"oe_title\\">\\n                            <field name=\\"automated_name\\" invisible=\\"1\\"/> <!-- needed for name compute -->\\n                            <field name=\\"name\\" placeholder=\\"Establecer un nombre explícito\\"/>\\n                        </h1>\\n                        <group invisible=\\"context.get('is_modal')\\">\\n                            <group>\\n                                <field name=\\"model_id\\" options=\\"{'no_create': True, 'no_open': True}\\" groups=\\"base.group_no_one\\"/>\\n                                <field name=\\"model_id\\" options=\\"{'no_create': True, 'no_open': True}\\" groups=\\"!base.group_no_one\\" invisible=\\"context.get('default_model_id')\\" domain=\\"[('id', 'in', available_model_ids)]\\"/>\\n                            </group>\\n                            <group groups=\\"base.group_no_one\\">\\n                                <field name=\\"group_ids\\" widget=\\"many2many_tags\\"/>\\n                            </group>\\n                        </group>\\n                        <t name=\\"action_content\\" invisible=\\"not model_id\\">\\n                            <field name=\\"allowed_states\\" invisible=\\"1\\"/> <!-- Used to filter state using badges_selection -->\\n                            <div class=\\"d-flex flex-column pb-2\\">\\n                                <label for=\\"state\\"/>\\n                                <field name=\\"state\\" widget=\\"badges_selection\\" options=\\"{'allowed_selection_field': 'allowed_states'}\\"/>\\n                            </div>\\n                            <div class=\\"alert alert-warning\\" role=\\"alert\\" invisible=\\"not warning\\">\\n                                <i class=\\"oi pe-2\\" data-icon=\\"warning\\" title=\\"Warning\\"/><field class=\\"d-inline\\" name=\\"warning\\" nolabel=\\"1\\"/>\\n                            </div>\\n                            <div class=\\"d-flex flex-row flex-wrap gap-2\\" invisible=\\"state != 'object_write'\\">\\n                                <field name=\\"evaluation_type\\" class=\\"oe_inline\\"/>\\n                                <field name=\\"update_property\\" invisible=\\"True\\"/> <!-- The field is store=True and readonly=False, in this view we want to save the value from compute/onchange -->\\n                                <label for=\\"update_path\\" string=\\"Select Field:\\" class=\\"fw-bold ps-2\\"/>\\n                                <field name=\\"update_path\\" widget=\\"field_selector\\" class=\\"oe_inline\\" options=\\"{'model': 'model_name', 'allow_properties': True}\\" required=\\"state == 'object_write'\\"/>\\n                                <field name=\\"update_field_id\\" invisible=\\"True\\"/>  <!-- The field is store=True and readonly=False, in this view we want to save the value from compute/onchange -->\\n                                <field name=\\"update_related_model_id\\" invisible=\\"True\\"/> <!-- This field is required for 'resource_ref' to compute possible m2m and m2o values -->\\n                                <span invisible=\\"evaluation_type != 'value' or value_field_to_show != 'x2many'\\">by</span>\\n                                <field name=\\"update_m2m_operation\\" class=\\"oe_inline\\" invisible=\\"evaluation_type != 'value' or value_field_to_show != 'x2many'\\" required=\\"value_field_to_show != 'x2many'\\"/>\\n                                <span invisible=\\"evaluation_type != 'value' or value_field_to_show == 'x2many'\\">to</span>\\n                                <span invisible=\\"evaluation_type != 'sequence'\\">with</span>\\n                                <field name=\\"value\\" class=\\"oe_inline\\" placeholder=\\"Establecer un valor...\\" invisible=\\"update_field_id == False or value_field_to_show != 'value' or evaluation_type != 'value'\\" string=\\"Valor personalizado\\"/>\\n                                <field name=\\"html_value\\" class=\\"w-100\\" placeholder=\\"Establecer un valor...\\" invisible=\\"update_field_id == False or value_field_to_show != 'html_value' or evaluation_type != 'value'\\" string=\\"Valor personalizado\\"/>\\n                                <field name=\\"sequence_id\\" class=\\"oe_inline\\" placeholder=\\"Seleccionar una secuencia...\\" invisible=\\"evaluation_type != 'sequence'\\" required=\\"evaluation_type == 'sequence'\\"/>\\n                                <field name=\\"resource_ref\\" class=\\"oe_inline\\" placeholder=\\"Elija un valor...\\" string=\\"Valor personalizado\\" options=\\"{'model_field': 'update_related_model_id', 'no_create': True, 'no_open': True}\\" invisible=\\"update_field_id == False or value_field_to_show not in ['resource_ref', 'x2many'] or evaluation_type == 'equation' or update_m2m_operation == 'clear'\\"/>\\n                                <field name=\\"selection_value\\" class=\\"oe_inline\\" placeholder=\\"Elija un valor...\\" options=\\"{'no_create': True, 'no_open': True}\\" invisible=\\"update_field_id == False or value_field_to_show != 'selection_value' or evaluation_type == 'equation'\\"/>\\n                                <field name=\\"property_selection\\" widget=\\"property_selection\\" options=\\"{'property_field_name': 'update_field_name', 'property_name': 'update_property', 'property_model_name': 'model_name'}\\" class=\\"oe_inline\\" placeholder=\\"Establecer un valor...\\" invisible=\\"update_field_id == False or value_field_to_show != 'property_selection' or evaluation_type == 'equation'\\"/>\\n                                <field name=\\"update_boolean_value\\" class=\\"oe_inline\\" invisible=\\"evaluation_type != 'value' or value_field_to_show != 'update_boolean_value'\\" required=\\"value_field_to_show == 'update_boolean_value'\\"/>\\n                                <span invisible=\\"update_field_id != False or evaluation_type != 'value'\\" class=\\"o_actions_server_set_a_value text-muted\\">Establezca un valor...</span>\\n                                <span invisible=\\"evaluation_type != 'equation'\\">\\n                                    para esta expresión Python:\\n                                </span>\\n                                <div class=\\"w-100 d-flex flex-row gap-3\\" invisible=\\"evaluation_type != 'equation'\\">\\n                                    <field name=\\"value\\" class=\\"w-50\\" widget=\\"code\\" options=\\"{'mode': 'python'}\\" string=\\"Expresión\\"/>\\n                                    <div class=\\"w-50 opacity-75\\">\\n                                        <span colspan=\\"2\\" class=\\"text-muted\\"> Variables disponibles: </span>\\n                                            <ul colspan=\\"2\\" class=\\"text-muted\\">\\n                                                <li><code>env</code>: entorno en el que se activa la acción.</li>\\n                                                <li><code>model</code>: modelo del registro en el cual se activa la acción. Es un conjunto de registros vacío.</li>\\n                                                <li><code>record</code>: registro en el que se activa la acción</li>\\n                                                <li><code>records</code>: conjunto de todos los registros en lo cuales la acción fue activada en modo múltiple</li>\\n                                                <li><code>time</code>, <code>datetime</code>, <code>dateutil</code>, <code>timezone</code>: bibliotecas útiles de Python</li>\\n                                                <li><code>float_compare()</code>: función de utilidad para comparar flotas basada en una precisión específica.</li>\\n                                            </ul>\\n                                    </div>\\n                                </div>\\n                            </div>\\n                            <group invisible=\\"state not in ['object_create', 'object_copy']\\">\\n                                <group>\\n                                    <field name=\\"crud_model_id\\" options=\\"{'no_create': True, 'no_open': True}\\" required=\\"state in ['object_create', 'object_copy']\\"/>\\n                                    <field name=\\"value\\" widget=\\"char\\" string=\\"Nombre\\" invisible=\\"state != 'object_create'\\" help=\\"El nombre del registro a crear\\" placeholder=\\"p. ej., seguimiento\\"/>\\n                                    <field name=\\"resource_ref\\" placeholder=\\"Elija un registro...\\" string=\\"Duplicar de\\" options=\\"{'model_field': 'crud_model_id', 'no_create': True, 'no_open': True}\\" invisible=\\"crud_model_id == False or state != 'object_copy'\\" required=\\"state == 'object_copy'\\"/>\\n                                    <field name=\\"link_field_id\\" domain=\\"[('model_id', '=', model_id), ('relation', '=', crud_model_name),                                         ('ttype', 'in', ['many2one', 'one2many', 'many2many'])]\\" placeholder=\\"Seleccione un campo al cual vincular el registro\\" options=\\"{'no_create': True, 'no_open': True}\\" context=\\"{'default_model_id': model_id, 'default_relation': crud_model_name}\\"/>\\n                                </group>\\n                            </group>\\n                            <group invisible=\\"state != 'webhook'\\">\\n                                <group>\\n                                    <field name=\\"webhook_url\\" string=\\"URL\\" placeholder=\\"p. ej., https://maker.ifttt.com/use/...\\"/>\\n                                    <field name=\\"webhook_field_ids\\" string=\\"Campos\\" widget=\\"many2many_tags\\" context=\\"{'hide_model': 1}\\" domain=\\"[('model_id', '=', model_id)]\\" placeholder=\\"Campos seleccionados para incluir en la solicitud...\\"/>\\n                                </group>\\n                                <group>\\n                                    <label for=\\"webhook_sample_payload\\"/>\\n                                    <field name=\\"webhook_sample_payload\\" string=\\"Carga efectiva de ejemplo\\" nolabel=\\"1\\" colspan=\\"2\\" readonly=\\"1\\" widget=\\"code\\" options=\\"{'mode': 'javascript'}\\"/>\\n                                </group>\\n                            </group>\\n                            <t invisible=\\"state != 'multi'\\">\\n                                <field name=\\"child_ids\\" widget=\\"many2many\\" mode=\\"kanban\\" context=\\"{                                     'is_modal': 1,                                     'default_model_id': model_id,                                 }\\"/>\\n                            </t>\\n                            <notebook>\\n                                <page string=\\"Código\\" invisible=\\"state != 'code'\\">\\n                                    <field name=\\"code\\" invisible=\\"state != 'code'\\" widget=\\"code\\" options=\\"{'mode': 'python'}\\" placeholder=\\"Introduzca código Python aquí. Ayuda disponible sobre expresiones Python en la pestaña de ayuda de este documento.\\"/>\\n                                </page>\\n                                <page string=\\"Ayuda\\" invisible=\\"state != 'code'\\" name=\\"ir_actions_server_code_help\\">\\n                                    <p>Puede usar las siguientes variables:</p>\\n                                    <ul>\\n                                        <li><code>env</code>: entorno en el que se activa la acción.</li>\\n                                        <li><code>model</code>: modelo del registro en el cual se activa la acción. Es un conjunto de registros vacío.</li>\\n                                        <li><code>record</code>: registro en el que se activa la acción; puede estar vacío</li>\\n                                        <li><code>records</code>: conjunto de todos los registros en lo cuales la acción fue activada en modo múltiple; puede ser vacío</li>\\n                                        <li><code>time</code>, <code>datetime</code>, <code>dateutil</code>, <code>timezone</code>: bibliotecas útiles de Python</li>\\n                                        <li><code>float_compare()</code>: función de utilidad para comparar flotas basada en una precisión específica.</li>\\n                                        <li><code>log(message, level='info')</code>: función de registro para registrar información de depuración en la tabla <code>ir.logging</code></li>\\n                                        <li><code>_logger.info(message)</code>: registrador para emitir mensajes en los registros del servidor</li>\\n                                        <li><code>UserError</code>: clase de excepción para generar mensajes de advertencia dirigidos al usuario</li>\\n                                        <li><code>Command</code>: espacios de nombres de comandos x2many</li>\\n                                        <li>Para devolver una acción, asigne: <code>action = {...}</code></li>\\n                                        <li>Para notificar el progreso para la llamada del CRON y vuelva a activar la llamada si hay tareas faltantes, use <code>env['ir.cron']._notify_progress(done=task_done_count, remaining=task_remaining_count)</code></li>\\n                                    </ul>\\n                                    <p>\\n                                        <widget name=\\"documentation_link\\" path=\\"/developer/reference/backend/orm.html\\" label=\\"ORM API Documentation\\" icon=\\"east\\" icon_class=\\"oi-fw\\"/>\\n                                    </p>\\n                                    <div>\\n                                        <p>Ejemplo de código Python:</p>\\n                                        <pre style=\\"white-space: pre-wrap\\">partner_name = record.name + '_code'\\nenv['res.partner'].create({'name': partner_name})\\n    </pre>\\n                                    </div>\\n                                </page>\\n                                <page string=\\"Explanation\\" name=\\"explanation\\">\\n                                    <field name=\\"explanation\\" nolabel=\\"1\\" class=\\"oe-bordered-editor\\"/>\\n                                </page>\\n                                <page string=\\"Uso\\" name=\\"usage\\" invisible=\\"1\\"/>\\n                            </notebook>\\n                        </t>\\n                    </sheet>\\n                </form>"}	<?xml version="1.0"?>\n<form string="Server Action">\n                    <header invisible="context.get('is_modal')">\n                        <button name="create_action" string="Create Contextual Action" type="object" class="btn-primary" invisible="binding_model_id" help="Display an option in the 'More' top-menu in order to run this action."/>\n                        <button name="unlink_action" string="Remove Contextual Action" type="object" invisible="not binding_model_id" help="Remove 'More' top-menu contextual action related to this action"/>\n                        <button name="run" string="Run" type="object" class="btn-primary" invisible="model_name != 'ir.actions.server' or state != 'code'" help="Run this action manually."/>\n                        <button name="history_wizard_action" string="Code History" type="object" invisible="not show_code_history" help="View code history and restore a previous version"/>\n                    </header>\n                    <sheet>\n                        <div class="oe_button_box" name="button_box">\n                            <button type="object" name="action_open_parent_action" invisible="not parent_id" class="oe_stat_button" icon="database">\n                                <div class="o_stat_info">\n                                    <span class="o_stat_text">Parent Action</span>\n                                </div>\n                            </button>\n                            <button type="object" name="action_open_scheduled_action" invisible="not ir_cron_ids or context.key != 'server_action'" context="{'key': 'ir_cron'}" class="oe_stat_button" icon="refresh">\n                                <div class="o_stat_info">\n                                    <span class="o_stat_text">Scheduled Action</span>\n                                </div>\n                            </button>\n                        </div>\n                        <h1 class="oe_title">\n                            <field name="automated_name" invisible="1"/> <!-- needed for name compute -->\n                            <field name="name" placeholder="Set an explicit name"/>\n                        </h1>\n                        <group invisible="context.get('is_modal')">\n                            <group>\n                                <field name="model_id" options="{'no_create': True, 'no_open': True}" groups="base.group_no_one"/>\n                                <field name="model_id" options="{'no_create': True, 'no_open': True}" groups="!base.group_no_one" invisible="context.get('default_model_id')" domain="[('id', 'in', available_model_ids)]"/>\n                            </group>\n                            <group groups="base.group_no_one">\n                                <field name="group_ids" widget="many2many_tags"/>\n                            </group>\n                        </group>\n                        <t name="action_content" invisible="not model_id">\n                            <field name="allowed_states" invisible="1"/> <!-- Used to filter state using badges_selection -->\n                            <div class="d-flex flex-column pb-2">\n                                <label for="state"/>\n                                <field name="state" widget="badges_selection" options="{'allowed_selection_field': 'allowed_states'}"/>\n                            </div>\n                            <div class="alert alert-warning" role="alert" invisible="not warning">\n                                <i class="oi pe-2" data-icon="warning" title="Warning"/><field class="d-inline" name="warning" nolabel="1"/>\n                            </div>\n                            <div class="d-flex flex-row flex-wrap gap-2" invisible="state != 'object_write'">\n                                <field name="evaluation_type" class="oe_inline"/>\n                                <field name="update_property" invisible="True"/> <!-- The field is store=True and readonly=False, in this view we want to save the value from compute/onchange -->\n                                <label for="update_path" string="Select Field:" class="fw-bold ps-2"/>\n                                <field name="update_path" widget="field_selector" class="oe_inline" options="{'model': 'model_name', 'allow_properties': True}" required="state == 'object_write'"/>\n                                <field name="update_field_id" invisible="True"/>  <!-- The field is store=True and readonly=False, in this view we want to save the value from compute/onchange -->\n                                <field name="update_related_model_id" invisible="True"/> <!-- This field is required for 'resource_ref' to compute possible m2m and m2o values -->\n                                <span invisible="evaluation_type != 'value' or value_field_to_show != 'x2many'">by</span>\n                                <field name="update_m2m_operation" class="oe_inline" invisible="evaluation_type != 'value' or value_field_to_show != 'x2many'" required="value_field_to_show != 'x2many'"/>\n                                <span invisible="evaluation_type != 'value' or value_field_to_show == 'x2many'">to</span>\n                                <span invisible="evaluation_type != 'sequence'">with</span>\n                                <field name="value" class="oe_inline" placeholder="Set a value..." invisible="update_field_id == False or value_field_to_show != 'value' or evaluation_type != 'value'" string="Custom Value"/>\n                                <field name="html_value" class="w-100" placeholder="Set a value..." invisible="update_field_id == False or value_field_to_show != 'html_value' or evaluation_type != 'value'" string="Custom Value"/>\n                                <field name="sequence_id" class="oe_inline" placeholder="Select a sequence..." invisible="evaluation_type != 'sequence'" required="evaluation_type == 'sequence'"/>\n                                <field name="resource_ref" class="oe_inline" placeholder="Choose a value..." string="Custom Value" options="{'model_field': 'update_related_model_id', 'no_create': True, 'no_open': True}" invisible="update_field_id == False or value_field_to_show not in ['resource_ref', 'x2many'] or evaluation_type == 'equation' or update_m2m_operation == 'clear'"/>\n                                <field name="selection_value" class="oe_inline" placeholder="Choose a value..." options="{'no_create': True, 'no_open': True}" invisible="update_field_id == False or value_field_to_show != 'selection_value' or evaluation_type == 'equation'"/>\n                                <field name="property_selection" widget="property_selection" options="{'property_field_name': 'update_field_name', 'property_name': 'update_property', 'property_model_name': 'model_name'}" class="oe_inline" placeholder="Set a value..." invisible="update_field_id == False or value_field_to_show != 'property_selection' or evaluation_type == 'equation'"/>\n                                <field name="update_boolean_value" class="oe_inline" invisible="evaluation_type != 'value' or value_field_to_show != 'update_boolean_value'" required="value_field_to_show == 'update_boolean_value'"/>\n                                <span invisible="update_field_id != False or evaluation_type != 'value'" class="o_actions_server_set_a_value text-muted">Set a value...</span>\n                                <span invisible="evaluation_type != 'equation'">\n                                    to this Python expression:\n                                </span>\n                                <div class="w-100 d-flex flex-row gap-3" invisible="evaluation_type != 'equation'">\n                                    <field name="value" class="w-50" widget="code" options="{'mode': 'python'}" string="Expression"/>\n                                    <div class="w-50 opacity-75">\n                                        <span colspan="2" class="text-muted"> Available variables: </span>\n                                            <ul colspan="2" class="text-muted">\n                                                <li><code>env</code>: environment on which the action is triggered</li>\n                                                <li><code>model</code>: model of the record on which the action is triggered; is a void recordset</li>\n                                                <li><code>record</code>: record on which the action is triggered</li>\n                                                <li><code>records</code>: recordset of all records on which the action is triggered in multi mode</li>\n                                                <li><code>time</code>, <code>datetime</code>, <code>dateutil</code>, <code>timezone</code>: useful Python libraries</li>\n                                                <li><code>float_compare()</code>: utility function to compare floats based on a specific precision</li>\n                                            </ul>\n                                    </div>\n                                </div>\n                            </div>\n                            <group invisible="state not in ['object_create', 'object_copy']">\n                                <group>\n                                    <field name="crud_model_id" options="{'no_create': True, 'no_open': True}" required="state in ['object_create', 'object_copy']"/>\n                                    <field name="value" widget="char" string="Name" invisible="state != 'object_create'" help="The name of the record to create" placeholder="e.g. Follow-up"/>\n                                    <field name="resource_ref" placeholder="Choose a record..." string="Duplicate from" options="{'model_field': 'crud_model_id', 'no_create': True, 'no_open': True}" invisible="crud_model_id == False or state != 'object_copy'" required="state == 'object_copy'"/>\n                                    <field name="link_field_id" domain="[('model_id', '=', model_id), ('relation', '=', crud_model_name),                                         ('ttype', 'in', ['many2one', 'one2many', 'many2many'])]" placeholder="Select a field to link the record to" options="{'no_create': True, 'no_open': True}" context="{'default_model_id': model_id, 'default_relation': crud_model_name}"/>\n                                </group>\n                            </group>\n                            <group invisible="state != 'webhook'">\n                                <group>\n                                    <field name="webhook_url" string="URL" placeholder="e.g. https://maker.ifttt.com/use/..."/>\n                                    <field name="webhook_field_ids" string="Fields" widget="many2many_tags" context="{'hide_model': 1}" domain="[('model_id', '=', model_id)]" placeholder="Select fields to include in the request..."/>\n                                </group>\n                                <group>\n                                    <label for="webhook_sample_payload"/>\n                                    <field name="webhook_sample_payload" string="Sample Payload" nolabel="1" colspan="2" readonly="1" widget="code" options="{'mode': 'javascript'}"/>\n                                </group>\n                            </group>\n                            <t invisible="state != 'multi'">\n                                <field name="child_ids" widget="many2many" mode="kanban" context="{                                     'is_modal': 1,                                     'default_model_id': model_id,                                 }"/>\n                            </t>\n                            <notebook>\n                                <page string="Code" invisible="state != 'code'">\n                                    <field name="code" invisible="state != 'code'" widget="code" options="{'mode': 'python'}" placeholder="Enter Python code here. Help about Python expression is available in the help tab of this document."/>\n                                </page>\n                                <page string="Help" invisible="state != 'code'" name="ir_actions_server_code_help">\n                                    <p>The following variables can be used:</p>\n                                    <ul>\n                                        <li><code>env</code>: environment on which the action is triggered</li>\n                                        <li><code>model</code>: model of the record on which the action is triggered; is a void recordset</li>\n                                        <li><code>record</code>: record on which the action is triggered; may be be void</li>\n                                        <li><code>records</code>: recordset of all records on which the action is triggered in multi mode; may be void</li>\n                                        <li><code>time</code>, <code>datetime</code>, <code>dateutil</code>, <code>timezone</code>: useful Python libraries</li>\n                                        <li><code>float_compare()</code>: utility function to compare floats based on a specific precision</li>\n                                        <li><code>log(message, level='info')</code>: logging function to record debug information in <code>ir.logging</code> table</li>\n                                        <li><code>_logger.info(message)</code>: logger to emit messages in server logs</li>\n                                        <li><code>UserError</code>: exception class for raising user-facing warning messages</li>\n                                        <li><code>Command</code>: x2many commands namespace</li>\n                                        <li>To return an action, assign: <code>action = {...}</code></li>\n                                        <li>To notify progress for CRON call and re-trigger a call if there is remaining tasks, use <code>env['ir.cron']._notify_progress(done=task_done_count, remaining=task_remaining_count)</code></li>\n                                    </ul>\n                                    <p>\n                                        <widget name="documentation_link" path="/developer/reference/backend/orm.html" label="ORM API Documentation" icon="east" icon_class="oi-fw"/>\n                                    </p>\n                                    <div>\n                                        <p>Example of Python code:</p>\n                                        <pre style="white-space: pre-wrap">partner_name = record.name + '_code'\nenv['res.partner'].create({'name': partner_name})\n    </pre>\n                                    </div>\n                                </page>\n                                <page string="Explanation" name="explanation">\n                                    <field name="explanation" nolabel="1" class="oe-bordered-editor"/>\n                                </page>\n                                <page string="Usage" name="usage" invisible="1"/>\n                            </notebook>\n                        </t>\n                    </sheet>\n                </form>\n            	\N	f	t	2026-10-26 23:38:33.217677	2026-10-26 23:38:33.217677	\N
