             'object_write': 'oi-filled',                                     'mail_post': 'oi-filled',                                     'followers': 'oi-filled',                                     'remove_followers': 'oi-filled',                                     'webhook': 'oi-filled',                                 }[record.state.raw_value]\\" t-att-data-icon=\\"{                                     'code': 'code',                                     'object_create': 'add_box',                                     'object_copy': 'content_copy',                                     'object_write': 'edit',                                     'multi': 'format_list_bulleted',                                     'mail_post': 'mail',                                     'followers': 'person',                                     'remove_followers': 'person_remove',                                     'next_activity': 'schedule',                                     'sms': 'smartphone',                                     'webhook': 'send',                                     'whatsapp': 'oi_whatsapp',                                     'ai': 'wand_stars',                                 }[record.state.raw_value] || 'radio_button_unchecked'\\"/>\\n                            <i class=\\"oi text-warning px-2 m-0\\" data-icon=\\"warning\\" invisible=\\"not warning\\" t-att-title=\\"record.warning.raw_value\\"/>\\n                            <field name=\\"name\\" class=\\"text-truncate\\"/>\\n                            <button type=\\"delete\\" name=\\"delete\\" class=\\"btn oi oi-filled px-3 ms-auto\\" data-icon=\\"delete\\" title=\\"Eliminar acción\\"/>\\n                        </t>\\n                    </templates>\\n                </kanban>"}	<?xml version="1.0"?>\n<kanban default_order="sequence, name, id">\n                    <control>\n                        <create string="Add an action"/>\n                    </control>\n                    <field name="state"/>\n                    <field name="evaluation_type"/>\n                    <field name="value"/>\n                    <field name="value_field_to_show"/>\n                    <field name="update_field_type"/>\n                    <field name="update_m2m_operation"/>\n                    <templates>\n                        <t t-name="card" class="o_draggable_norotate w-100 flex-row align-items-center gap-1">\n                            <field name="sequence" widget="handle" class="px-1"/>\n                            <!-- Icon section -->\n                            <i data-name="server_action_icon" t-att-title="record.state.value" class="oi oi-fw" t-att-class="{                                     'object_create': 'oi-filled',                                     'object_write': 'oi-filled',                                     'mail_post': 'oi-filled',                                     'followers': 'oi-filled',                                     'remove_followers': 'oi-filled',                                     'webhook': 'oi-filled',                                 }[record.state.raw_value]" t-att-data-icon="{                                     'code': 'code',                                     'object_create': 'add_box',                                     'object_copy': 'content_copy',                                     'object_write': 'edit',                                     'multi': 'format_list_bulleted',                                     'mail_post': 'mail',                                     'followers': 'person',                                     'remove_followers': 'person_remove',                                     'next_activity': 'schedule',                                     'sms': 'smartphone',                                     'webhook': 'send',                                     'whatsapp': 'oi_whatsapp',                                     'ai': 'wand_stars',                                 }[record.state.raw_value] |