el\\" for=\\"sql_no_gap_profile\\">SQL sin espacio</label>\\n                                </div>\\n                                <div class=\\"form-check\\" t-if=\\"has_sql\\">\\n                                    <input type=\\"checkbox\\" class=\\"form-check-input\\" id=\\"sql_density_profile\\" name=\\"sql_density_profile\\" value=\\"True\\" t-att-checked=\\"default_params.get('sql_density_profile')\\"/>\\n                                    <label class=\\"form-check-label\\" for=\\"sql_density_profile\\">Densidad SQL</label>\\n                                </div>\\n                                <div class=\\"form-check\\" t-if=\\"has_traces\\">\\n                                    <input type=\\"checkbox\\" class=\\"form-check-input\\" id=\\"frames_profile\\" name=\\"frames_profile\\" value=\\"True\\" t-att-checked=\\"default_params.get('frames_profile')\\"/>\\n                                    <label class=\\"form-check-label\\" for=\\"frames_profile\\">Cuadros</label>\\n                                </div>\\n                                <div class=\\"form-check\\" t-if=\\"has_traces and profiles._has_memory_traces()\\">\\n                                    <input type=\\"checkbox\\" class=\\"form-check-input\\" id=\\"memory_profile\\" name=\\"memory_profile\\" value=\\"True\\" t-att-checked=\\"default_params.get('memory_profile')\\"/>\\n                                    <label class=\\"form-check-label\\" for=\\"memory_profile\\">Memory (heuristic)</label>\\n                                </div>\\n\\n                                <input type=\\"hidden\\" name=\\"profile_id\\" t-att-value=\\"profile_str\\"/>\\n                                \\n                                <div class=\\"mt-3\\">\\n                                    <button type=\\"submit\\" class=\\"btn btn-secondary\\" name=\\"action\\" value=\\"speedscope_download_json\\"><i class=\\"oi oi-fw\\" data-icon=\\"download\\"/> (json)</button>\\n                        