n name=\\"51\\" icon=\\"east\\" type=\\"action\\" string=\\"Gestionar compañías\\" class=\\"btn-link\\"/>\\n                                    </div>\\n                                </setting>\\n                                <setting id=\\"document_layout_setting\\" string=\\"Diseño de documento\\" help=\\"Elija el diseño de sus documentos\\" company_dependent=\\"1\\">\\n                                    <div class=\\"content-group\\">\\n                                        <div class=\\"mt16\\" groups=\\"base.group_no_one\\">\\n                                            <label for=\\"external_report_layout_id\\" string=\\"Diseño\\" class=\\"col-3 col-lg-3 o_light_label\\"/>\\n                                            <field name=\\"external_report_layout_id\\" domain=\\"[('type','=', 'qweb')]\\" class=\\"oe_inline\\"/>\\n                                        </div>\\n                                            <button name=\\"82\\" string=\\"Configurar diseño de documento\\" type=\\"action\\" class=\\"oe_link\\" icon=\\"east\\"/>\\n                                            <br groups=\\"base.group_no_one\\"/>\\n                                            <button name=\\"edit_external_header\\" string=\\"Editar diseño\\" type=\\"object\\" class=\\"oe_link\\" groups=\\"base.group_no_one\\" icon=\\"east\\"/>\\n                                            <br groups=\\"base.group_no_one\\"/>\\n                                            <button name=\\"80\\" string=\\"Visualizar el documento\\" type=\\"action\\" class=\\"oe_link\\" groups=\\"base.group_no_one\\" icon=\\"east\\"/>\\n                                    </div>\\n                                </setting>\\n                                <field name=\\"company_id\\" invisible=\\"1\\"/>\\n                                <setting id=\\"inter_company\\" string=\\"Transacciones dentro de la compañía\\" company_dependent=\\"1\\" help=\\"Cree los pedidos y facturas de entrada/salida correspondientes cuando venda/compre entre sus empresas\\" groups=\\"base.group_multi_company\\">\\n                                    <field name=\\"module_account_inter_company_rules\\" widget=\\"upgrade_boolean\\"/>\\n                                    <div class=\\"content-group\\" invisible=\\"not module_account_inter_company_rules\\" id=\\"inter_companies_rules\\">\\n                                        <div class=\\"mt16 text-warning\\"><strong>Guarda</strong> esta página y vuelve aquí para configurar la funcionalidad.</div>\\n                                    </div>\\n                                </setting>\\n                            </block>\\n                        </div>\\n                        <div id=\\"emails\\"/>\\n\\n                        <div id=\\"contacts_settings\\">\\n                            <block title=\\"Contactos\\" name=\\"contacts_setting_container\\">\\n                                <setting id=\\"sms\\" string=\\"Enviar SMS\\" documentation=\\"/applications/marketing/sms_marketing/pricing/pricing_and_faq.html\\" help=\\"Envíe mensajes de texto a sus contactos\\">\\n                                    <!-- Invisible to avoid breaking any custom inheriting templates -->\\n                                    <field name=\\"module_sms\\" invisible=\\"1\\"/>\\n                                </setting>\\n                                <setting help=\\"Mejore automáticamente su base de contactos con datos de la compañía\\" title=\\"Cuando termine de crear su libreta de direcciones, Odoo proporcionará una lista de compañías coincidentes. Si selecciona un elemento, los datos de la compañía y el logo se completarán automáticamente.\\" id=\\"partner_autocomplete\\">\\n                                    <field name=\\"module_partner_autocomplete\\"/>\\n                                </setting>\\n                        </block>\\n                    </div>\\n\\n                    <block title=\\"Permisos\\" id=\\"user_default_rights\\">\\n                        <setting string=\\"Permisos de acceso por defecto\\" help=\\"Configure reglas de acceso personalizadas para usuarios nuevos\\" title=\\"Por defecto, los nuevos usuarios reciben los derechos de acceso con mayor jerarquía en todas las aplicaciones instaladas. Si no está seleccionada, los nuevos usuarios solo tendrán acceso básico como empleados.\\" id=\\"access_rights\\">\\n                            <div class=\\"content-group\\">\\n                                <div class=\\"mt8\\">\\n                                    <button type=\\"object\\" name=\\"open_new_user_default_groups\\" string=\\"Permisos de acceso por defecto\\" icon=\\"east\\" class=\\"btn-link\\"/>\\n                                </div>\\n                            </div>\\n                        </setting>\\n                        <setting string=\\"Claves API\\" help=\\"Las claves API permiten a sus usuarios acceder a Odoo mediante herramientas externas cuando la autenticación de múltiples factores está habilitada.\\" groups=\\"base.group_system\\">\\n                            <button type=\\"action\\" name=\\"70\\" string=\\"Gestionar claves API\\" icon=\\"east\\" class=\\"btn-link\\"/>\\n                        </setting>\\n                        <setting string=\\"Importación y exportación\\" help=\\"Permita a los usuarios importar datos desde archivos CSV/XLS/XLSX/ODS\\" documentation=\\"/applications/general/export_import_data.html\\" groups=\\"base.group_no_one\\" id=\\"allow_import\\">\\n                            <field name=\\"module_base_import\\"/>\\n                        </setting>\\n                        <setting id=\\"feedback_motivate_setting\\" help=\\"Añada comentarios divertidos y motive a sus empleados\\" groups=\\"base.group_no_one\\">\\n                            <field name=\\"show_effect\\"/>\\n                        </setting>\\n                    </block>\\n\\n                    <block title=\\"Aplicación web progresiva\\