plications/websites/website/configuration/spam_protection.html#website-spam-protection-cloudflare-turnstile\\">\\n                                <field name=\\"module_website_cf_turnstile\\"/>\\n                                <div class=\\"content-group\\" invisible=\\"not module_website_cf_turnstile\\" id=\\"turnstile_warning\\">\\n                                    <div class=\\"mt16 text-warning\\"><strong>Guarde</strong> esta página y regrese para configurar Cloudflare Turnstile.</div>\\n                                </div>\\n                            </setting>\\n                            <setting help=\\"Autocomplete las direcciones de sus contactos con Google Places\\" id=\\"google_address_autocomplete\\" documentation=\\"https://www.odoo.com/documentation/latest/applications/general/integrations/address_autocomplete.html\\">\\n                                <field name=\\"module_google_address_autocomplete\\"/>\\n                                <div class=\\"content-group\\" invisible=\\"not module_google_address_autocomplete\\" id=\\"google_address_autocomplete_warning\\">\\n                                    <div class=\\"mt16 text-warning\\"><strong>Guarde</strong> esta página y regrese para configurar la clave API de Google Places</div>\\n                                </div>\\n                            </setting>\\n\\n                        </block>\\n\\n                        <block title=\\"Rendimiento\\" groups=\\"base.group_no_one\\" name=\\"performance\\">\\n                            <setting id=\\"profiling_enabled_until\\" help=\\"Habilite la herramienta de análisis de rendimiento. Este análisis puede afectar el rendimiento mientras se encuentre activo.\\">\\n                                <field name=\\"profiling_enabled_until\\"/>\\n                            </setting>\\n                        </block>\\n\\n                        <widget name=\\"res_config_dev_tool\\"/>\\n                        <div id=\\"about\\">\\n   