mains for your mail aliases" company_dependent="1" documentation="/applications/general/email_communication/email_domain.html#be-spf-compliant">\n                            <span class="me-1">@</span>\n                            <field name="alias_domain_id" placeholder="e.g. mycompany.com" options="{'no_create_edit': True}"/>\n                        </setting>\n                        <setting string="Use a Gmail Server" help="Send and receive emails through your Gmail account." documentation="https://console.developers.google.com/" invisible="not external_email_server_default">\n                            <field name="module_google_gmail"/>\n                            <div class="content-group" invisible="not module_google_gmail" id="msg_module_google_gmail">\n                                <div class="mt16 text-warning"><strong>Save</strong> this page and come back here to set up the feature.</div>\n                            </div>\n                        </setting>\n                        <setting id="email-outlook-setting" string="Use an Outlook Server" help="Send and receive emails through your Outlook account." documentation="https://docs.microsoft.com/en-us/azure/active-directory/develop/quickstart-register-app" invisible="not external_email_server_default">\n                            <field name="module_microsoft_outlook"/>\n                            <div class="content-group" id="msg_module_microsoft_outlook" invisible="not module_microsoft_outlook">\n                                <div class="mt16 text-warning">\n                                    <strong>Save</strong> this page and come back here to set up the feature.\n                                </div>\n                            </div>\n                        </setting>\n                        <setting id="restrict_template_rendering_setting" help="Restrict mail templates edition and QWEB placeholders usage.">\n                            <field name="restrict_template_rendering