t2">\n                Apartment, suite, etc.\n            </label>\n            <input id="o_street2" type="text" name="street2" class="form-control" t-att-value="partner_sudo.street2"/>\n        </div>\n        <div class="w-100 "/>\n        <t name="b2b_fields">\n            <div class="w-100 mt-4"/>\n            <t t-if="is_used_as_billing">\n                <div id="company_name_div" class="col-lg-6 mb-2">\n                    <label class="col-form-label fw-normal label-optional" for="o_company_name">\n                        Company\n                    </label>\n                    <t t-if="not is_main_address" t-call="portal.address_warning_icon" warning="commercial_fields_warning"/>\n                    <input id="o_company_name" type="text" name="parent_name" t-att-value="current_partner.parent_name" t-att-readonly="'1' if not is_main_address else None" class="form-control"/>\n                </div>\n                <div id="div_vat" class="col-lg-6 mb-2">\n                    <label t-out="vat_label" for="o_vat" class="col-form-label fw-normal label-optional"/>\n                    <t t-call="portal.address_warning_icon" warning="commercial_fields_warning or vat_warning"/>\n                    <input type="text" id="o_vat" name="vat" t-att-value="current_partner.vat" t-att-readonly="'1' if (commercial_fields_warning or vat_warning) else None" class="form-control"/>\n                </div>\n                <div t-if="commercial_address_update_url" class="col-12 d-none d-lg-block mb-1">\n                    <small class="form-text text-muted">\n                        If you want to modify it, update\n                        <a t-att-href="commercial_address_update_url">your account details</a>.\n                    </small>\n                </div>\n            </t>\n        </t>\n        <input type="hidden" name="address_type" t-att-value="address_type"/>\n        <input type="hidden" name="csrf_token" t-att-value="request.csrf_token()"/>\n        <input 