                       <group>\\n                            <div class=\\"o_td_label\\">\\n                                <label for=\\"partner_id\\" string=\\"Dirección de entrega\\" style=\\"font-weight:bold;\\" invisible=\\"picking_type_code != 'outgoing'\\"/>\\n                                <label for=\\"partner_id\\" string=\\"Recibir de\\" style=\\"font-weight:bold;\\" invisible=\\"picking_type_code != 'incoming'\\"/>\\n                                <label for=\\"partner_id\\" string=\\"Contacto\\" style=\\"font-weight:bold;\\" invisible=\\"picking_type_code in ['incoming', 'outgoing']\\"/>\\n                            </div>\\n                            <field name=\\"partner_id\\" nolabel=\\"1\\" readonly=\\"state in ['cancel', 'done']\\" placeholder=\\"p. ej. Lumber Inc\\"/>\\n                            <field name=\\"picking_type_id\\" options=\\"{'no_open': True, 'no_quick_create': True}\\" readonly=\\"state in ('done', 'cancel')\\" domain=\\"[('code', 'in', ('incoming', 'outgoing', 'internal'))]\\"/>\\n                            <field name=\\"location_id\\" groups=\\"!stock.group_stock_multi_locations\\" invisible=\\"1\\" readonly=\\"state == 'done'\\"/>\\n                            <field name=\\"location_dest_id\\" groups=\\"!stock.group_stock_multi_locations\\" invisible=\\"1\\" readonly=\\"state == 'done'\\"/>\\n                            <field name=\\"location_id\\" options=\\"{'no_create': True}\\" groups=\\"stock.group_stock_multi_locations\\" invisible=\\"picking_type_code == 'incoming'\\" readonly=\\"state == 'done'\\"/>\\n                            <field name=\\"location_dest_id\\" options=\\"{'no_create': True}\\" groups=\\"stock.group_stock_multi_locations\\" invisible=\\"picking_type_code == 'outgoing'\\" readonly=\\"state == 'done'\\"/>\\n                            <field name=\\"backorder_id\\" invisible=\\"not backorder_id\\"/>\\n                            <field name=\\"use_create_lots\\" invisible=\\"1\\"/> <!-- used by embedded stock.move list view below -->\\n                        </group>\\n                        <group>\\n                            <label for=\\"scheduled_date\\"/>\\n                            <div class=\\"o_row\\">\\n                                <field name=\\"scheduled_date\\" readonly=\\"not is_date_editable\\" required=\\"id\\" decoration-warning=\\"id and state not in ('done', 'cancel') and scheduled_date &lt; now\\" decoration-danger=\\"state not in ('done', 'cancel') and scheduled_date &lt; current_date\\" decoration-bf=\\"state not in ('done', 'cancel') and (scheduled_date &lt; current_date or scheduled_date &lt; now)\\"/>\\n                                <field name=\\"json_popover\\" nolabel=\\"1\\" widget=\\"stock_rescheduling_popover\\" invisible=\\"not json_popover\\"/>\\n                            </div>\\n                            <field name=\\"date_deadline\\" invisible=\\"state in ('done', 'cancel') or not date_deadline\\" decoration-danger=\\"date_deadline and date_deadline &lt; current_date\\" decoration-bf=\\"date_deadline and date_deadline &lt; current_date\\"/>\\n                            <field name=\\"products_availability_state\\" invisible=\\"1\\"/>\\n                            <field name=\\"products_availability\\" invisible=\\"picking_type_code not in ('outgoing', 'internal') or state not in ['confirmed', 'waiting', 'assigned']\\" decoration-success=\\"state == 'assigned' or products_availability_state == 'available'\\" decoration-warning=\\"state != 'assigned' and products_availability_state in ('expected', 'available')\\" decoration-danger=\\"state != 'assigned' and products_availability_state == 'late'\\"/>\\n                            <field name=\\"date_done\\" string=\\"Fecha efectiva\\" invisible=\\"state != 'done'\\" readonly=\\"not is_date_editable\\"/>\\n                            <field name=\\"origin\\" placeholder=\\"p. ej. PO0032\\" readonly=\\"state in ['cancel', 'done']\\"/>\\n                            <field name=\\"owner_id\\" groups=\\"stock.group_tracking_owner\\" invisible=\\"picking_type_code != 'incoming'\\" readonly=\\"state in ['cancel', 'done']\\"/>\\n                        </group>\\n                    </group>\\n                    <field name=\\"picking_properties\\" columns=\\"2\\"/>\\n                    <notebook>\\n                        <page string=\\"Operaciones\\" name=\\"operations\\">\\n                            <field name=\\"move_ids\\" mode=\\"list,kanban\\" widget=\\"stock_move_one2many\\" add-label=\\"Añadir un producto\\" readonly=\\"state == 'done' and is_locked\\" context=\\"{'default_company_id': company_id, 'default_date': scheduled_date, 'default_date_deadline': date_deadline, 'picking_type_code': picking_type_code, 'default_picking_id': id, 'form_view_ref': 'stock.view_stock_move_operations', 'address_in_id': partner_id, 'default_picking_type_id': picking_type_id, 'default_location_id': location_id, 'default_location_dest_id': location_dest_id, 'default_partner_id': partner_id, 'picking_state': state}\\">\\n                                <list decoration-muted=\\"is_scrap or state == 'cancel' or (state == 'done' and is_locked == True)\\" string=\\"Movimientos de stock\\" editable=\\"bottom\\">\\n                                    <control>\\n                                        <create string=\\"Añadir un producto\\" hotkey=\\"shift+p\\"/>\\n                                    </control>\\n                                    <field name=\\"sequence\\" widget=\\"handle\\"/>\\n                                    <field name=\\"company_id\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"state\\" readonly=\\"0\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"picking_type_id\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"location_id\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"location_dest_id\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"partner_id\\" column_invisible=\\"True\\" readonly=\\"state == 'done'\\"/>\\n                                    <field name=\\"picking_code\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"show_details_visible\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"additional\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"move_lines_count\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"is_locked\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"is_storable\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"has_tracking\\" column_invisible=\\"True\\"/>\\n                                    <column>\\n                                        <field name=\\"product_id\\" context=\\"{'default_is_storable': True}\\" required=\\"1\\" readonly=\\"(state != 'draft' and not additional) or move_lines_count &gt; 0\\" force_save=\\"1\\" placeholder=\\"Select a Product...\\"/>\\n                                        <field name=\\"description_picking\\" string=\\"Descripción\\" optional=\\"show\\" placeholder=\\"Enter a Description...\\" readonly=\\"parent.state in ('cancel', 'done')\\" widget=\\"description_picking_text\\"/>\\n                                    </column>\\n                                    <field name=\\"forecast_availability\\" string=\\"\\" widget=\\"forecast_widget\\" column_invisible=\\"parent.state in ('cancel', 'done') or parent.picking_type_code not in ['internal', 'outgoing']\\"/>\\n                                    <field name=\\"packaging_uom_qty\\" optional=\\"hide\\" groups=\\"uom.group_uom\\"/>\\n                                    <field name=\\"packaging_uom_id\\" optional=\\"hide\\" groups=\\"uom.group_uom\\"/>\\n                                    <field name=\\"forecasted_location_id\\" optional=\\"hide\\" groups=\\"stock.group_stock_multi_locations\\"/>\\n                                    <field name=\\"date\\" optional=\\"hide\\"/>\\n                                    <field name=\\"date_deadline\\" optional=\\"hide\\"/>\\n                                    <field name=\\"is_quantity_done_editable\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"show_quant\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"show_lots_text\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"show_lots_m2o\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"is_initial_demand_editable\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"display_import_lot\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"has_lines_without_result_package\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"package_ids\\" optional=\\"show\\" widget=\\"package_m2m\\" groups=\\"stock.group_tracking_lot\\" width=\\"200px\\" readonly=\\"1\\"/>\\n                                    <field name=\\"product_uom_qty\\" string=\\"Demanda\\" readonly=\\"not is_initial_demand_editable\\"/>\\n                                    <field name=\\"forecast_expected_date\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"product_qty\\" readonly=\\"1\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"quantity\\" string=\\"Cantidad\\" readonly=\\"not is_quantity_done_editable\\" column_invisible=\\"parent.state=='draft'\\" decoration-danger=\\"product_uom_qty and quantity &gt; product_uom_qty and parent.state not in ['done', 'cancel']\\"/>\\n                                    <field name=\\"uom_id\\" readonly=\\"state != 'draft' and not additional\\" options=\\"{'no_open': True, 'no_create': True}\\" widget=\\"many2one_uom\\" groups=\\"uom.group_uom\\"/>\\n                                    <field name=\\"picked\\" optional=\\"hide\\" column_invisible=\\"parent.state=='draft'\\"/>\\n                                    <field name=\\"lot_ids\\" widget=\\"many2many_tags\\" column_invisible=\\"parent.state == 'draft'\\" groups=\\"stock.group_production_lot\\" invisible=\\"not show_details_visible or has_tracking not in ['serial', 'lot']\\" optional=\\"hide\\" create=\\"parent.use_create_lots == True\\" context=\\"{'default_company_id': company_id, 'default_product_id': product_id, 'active_picking_id': parent.id}\\" domain=\\"[('product_id','=',product_id)]\\"/>\\n                                    <button name=\\"action_show_details\\" type=\\"object\\" string=\\"Detalles\\" invisible=\\"not show_details_visible\\"/>\\n                                </list>\\n                            </field>\\n                            <field name=\\"id\\" invisible=\\"1\\"/>\\n                            <button class=\\"btn-secondary float-end\\" name=\\"action_put_in_pack\\" type=\\"object\\" string=\\"Poner en paquete\\" invisible=\\"state in ('draft', 'done', 'cancel')\\" groups=\\"stock.group_tracking_lot\\" data-hotkey=\\"shift+g\\"/>\\n                            <button class=\\"btn-secondary float-end me-2\\" name=\\"action_return_all\\" type=\\"object\\" string=\\"Devolver todo\\" invisible=\\"state != 'draft' or not return_id\\" groups=\\"base.group_user\\"/>\\n                            <button class=\\"btn-secondary float-end me-2\\" name=\\"action_clear_return\\" type=\\"object\\" string=\\"Limpiar\\" invisible=\\"state != 'draft' or not return_id\\" groups=\\"base.group_user\\"/>\\n                        </page>\\n                        <page string=\\"Info adicional\\" name=\\"extra\\">\\n                            <group>\\n                                <group string=\\"Otra información\\" name=\\"other_infos\\">\\n                                    <field name=\\"move_type\\" invisible=\\"picking_type_code == 'incoming'\\" readonly=\\"state in ['cancel', 'done']\\"/>\\n                                    <field name=\\"user_id\\" widget=\\"many2one_avatar_user\\" domain=\\"[('share', '=', False)]\\" readonly=\\"state in ['cancel', 'done']\\"/>\\n                                    <field name=\\"company_id\\" groups=\\"base.group_multi_company\\" options=\\"{'no_create': True}\\" force_save=\\"1\\"/>\\n                                    <field name=\\"batch_id\\" groups=\\"stock.group_stock_picking_batch\\" readonly=\\"1\\" options=\\"{'no_create': True}\\"/>\\n                                </group>\\n                            </group>\\n                        </page>\\n                        <page string=\\"Nota\\" name=\\"note\\">\\n                            <field name=\\"note\\" string=\\"Nota\\" placeholder=\\"Añada una nota interna que se imprimirá en la hoja de operaciones de la preparación de pedidos\\"/>\\n                        </page>\\n                    </notebook>\\n                </sheet>\\n                <chatter/>\\n                </form>"}	<?xml version="1.0"?>\n<form string="Transfer">\n                <header>\n                    <button name="action_confirm" invisible="state != 'draft'" string="Mark as To Do" type="object" class="oe_highlight" groups="base.group_user" data-hotkey="q"/>\n                    <button name="action_assign" invisible="not show_check_availability" string="Reserve" type="object" class="oe_highlight" groups="base.group_user" data-hotkey="w"/>\n                    <button name="button_validate" string="Validate" type="object" class="oe_highlight" groups="stock.group_stock_user" data-hotkey="v" invisible="validate_button_style != 'primary'"/>\n                    <button name="button_validate" string="Validate" type="object" class="btn-secondary" groups="stock.group_stock_user" data-hotkey="v" invisible="validate_button_style != 'secondary'"/>\n                    <widget name="signature" string="Sign" highlight="1" invisible="not id or picking_type_code != 'outgoing' or state != 'done' or is_signed" full_name="partner_id" groups="stock.group_stock_sign_delivery"/>\n                    <widget name="signature" string="Sign" invisible="not id or picking_type_code != 'outgoing' or state == 'done' or is_signed" full_name="partner_id" groups="stock.group_stock_sign_delivery"/>\n                    <button name="do_print_picking" string="Print" groups="stock.group_stock_user" type="object" invisible="state != 'assigned'" data-hotkey="o"/>\n                    <button name="536" string="Print" invisible="state != 'done'" type="action" groups="base.group_user" data-hotkey="o"/>\n                    <button name="action_return" string="Return" invisible="not show_return or state != 'done'" type="object" groups="base.group_user" data-hotkey="k"/>\n                    <button name="action_exchange" string="Exchange" invisible="show_return or state not in ('assigned', 'done')" type="object" groups="base.group_user"/>\n                    <field name="state" widget="stock_picking_locked_statusbar" invisible="picking_type_code != 'incoming'" statusbar_visible="draft,assigned,done"/>\n                    <field name="state" widget="stock_picking_locked_statusbar" invisible="picking_type_code == 'incoming'" statusbar_visible="draft,confirmed,assigned,done"/>\n                    <button name="action_cancel" invisible="state not in ('assigned', 'confirmed', 'draft', 'waiting')" string="Cancel" groups="base.group_user" type="object" confirm="Are you sure you want to cancel this transfer?" data-hotkey="x"/>\n                    <button name="action_toggle_is_locked" string="Lock" groups="stock.group_stock_manager" type="object" invisible="is_locked or state == 'cancel'" class="btn btn-primary"/>\n                    <button name="action_toggle_is_locked" string="Unlock" groups="stock.group_stock_manager" type="object" invisible="not is_locked or state not in ('done', 'cancel')"/>\n                </header>\n                <div class="alert alert-info" role="alert" invisible="not picking_warning_text">\n                    <field name="picking_warning_text" class="fw-bold"/>\n                </div>\n                <sheet>\n                    <div class="oe_button_box" name="button_box">\n                        <button name="action_see_returns" type="object" class="oe_stat_button" icon="undo" invisible="return_count == 0">\n                            <field string="Returns" name="return_count" widget="statinfo"/>\n                        </button>\n                        <button name="action_see_move_scrap" string="Scraps" type="object" class="oe_stat_button" icon="height" invisible="not has_scrap_move"/>\n                        <button name="action_see_packages" string="Packages" type="object" class="oe_stat_button" icon="package_2" invisible="state == 'done' or not packages_count" groups="stock.group_tracking_lot">\n                            <div class="o_stat_info">\n                                <span class="o_stat_text">Packages</span>\n                            </div>\n                        </button>\n                        <button name="action_see_package_histories" string="Packages" type="object" class="oe_stat_button" icon="package_2" invisible="state != 'done' or not packages_count" groups="stock.group_tracking_lot">\n                            <div class="o_stat_info">\n                                <span class="o_stat_text">Packages</span>\n                            </div>\n                        </button>\n                        <button name="534" icon="north" class="oe_stat_button" type="action" invisible="state != 'done' or not has_tracking" groups="stock.group_production_lot">\n                            <div class="o_stat_info">\n                                <span class="o_stat_text">Traceability</span>\n                            </div>\n                        </button>\n                        <button name="action_view_allocation_report" type="object" class="oe_stat_button" icon="format_list_bulleted" invisible="not show_allocation">\n                            <div class="o_stat_info">\n                                <span class="o_stat_text">Allocation</span>\n                            </div>\n                        </button>\n                        <!-- Use the following button to avoid onchange on one2many -->\n                        <button name="action_picking_move_tree" class="oe_stat_button" icon="height" type="object" help="List view of operations" groups="base.group_no_one" invisible="(is_locked or state == 'done') or state == 'done' and is_locked" context="{'picking_type_code': picking_type_code, 'default_picking_id': id, 'form_view_ref':'stock.view_move_form', 'address_in_id': partner_id, 'default_picking_type_id': picking_type_id, 'default_location_id': location_id, 'default_location_dest_id': location_dest_id}">\n                            <div class="o_form_field o_stat_info">\n                                <span class="o_stat_text">Operations</span>\n                            </div>\n                        </button>\n                        <button name="action_detailed_operations" class="oe_stat_button" icon="menu" type="object" help="List view of detailed operations">\n                            <div class="o_form_field o_stat_info">\n                                <span class="o_stat_text">Moves</span>\n                            </div>\n                        </button>\n                        <button name="action_next_transfer" class="oe_stat_button" icon="sync_alt" type="object" help="List view of next transfers" invisible="not show_next_pickings">\n                            <div class="o_form_field o_stat_info">\n                                <span class="o_stat_text">Next Transfer</span>\n                            </div>\n                        </button>\n                        <button type="object" name="action_view_batch" class="oe_stat_button" icon="local_shipping" string="Batch" invisible="not batch_id" groups="stock.group_stock_picking_batch"/>\n                    </div>\n                    <div class="oe_title">\n                        <h1 class="o_outlined d-flex align-items-center gap-2">\n                            <field name="priority" widget="priority"/>\n                            <div invisible="id">New <field name="picking_type_code"/></div>\n                            <field name="name" invisible="not id"/>\n                        </h1>\n                    </div>\n                    <group>\n                        <group>\n                            <div class="o_td_label">\n                                <label for="partner_id" string="Delivery Address" style="font-weight:bold;" invisible="picking_type_code != 'outgoing'"/>\n                                <label for="partner_id" string="Receive From" style="font-weight:bold;" invisible="picking_type_code != 'incoming'"/>\n                                <label for="partner_id" string="Contact" style="font-weight:bold;" invisible="picking_type_code in ['incoming', 'outgoing']"/>\n                            </div>\n                            <field name="partner_id" nolabel="1" readonly="state in ['cancel', 'done']" placeholder="e.g. Lumber Inc"/>\n                            <field name="picking_type_id" options="{'no_open': True, 'no_quick_create': True}" readonly="state in ('done', 'cancel')" domain="[('code', 'in', ('incoming', 'outgoing', 'internal'))]"/>\n                            <field name="location_id" groups="!stock.group_stock_multi_locations" invisible="1" readonly="state == 'done'"/>\n                            <field name="location_dest_id" groups="!stock.group_stock_multi_locations" invisible="1" readonly="state == 'done'"/>\n                            <field name="location_id" options="{'no_create': True}" groups="stock.group_stock_multi_locations" invisible="picking_type_code == 'incoming'" readonly="state == 'done'"/>\n                            <field name="location_dest_id" options="{'no_create': True}" groups="stock.group_stock_multi_locations" invisible="picking_type_code == 'outgoing'" readonly="state == 'done'"/>\n                            <field name="backorder_id" invisible="not backorder_id"/>\n                            <field name="use_create_lots" invisible="1"/> <!-- used by embedded stock.move list view below -->\n                        </group>\n                        <group>\n                            <label for="scheduled_date"/>\n                            <div class="o_row">\n                                <field name="scheduled_date" readonly="not is_date_editable" required="id" decoration-warning="id and state not in ('done', 'cancel') and scheduled_date &lt; now" decoration-danger="state not in ('done', 'cancel') and scheduled_date &lt; current_date" decoration-bf="state not in ('done', 'cancel') and (scheduled_date &lt; current_date or scheduled_date &lt; now)"/>\n                                <field name="json_popover" nolabel="1" widget="stock_rescheduling_popover" invisible="not json_popover"/>\n                            </div>\n                            <field name="date_deadline" invisible="state in ('done', 'cancel') or not date_deadline" decoration-danger="date_deadline and date_deadline &lt; current_date" decoration-bf="date_deadline and date_deadline &lt; current_date"/>\n                            <field name="products_availability_state" invisible="1"/>\n                            <field name="products_availability" invisible="picking_type_code not in ('outgoing', 'internal') or state not in ['confirmed', 'waiting', 'assigned']" decoration-success="state == 'assigned' or products_availability_state == 'available'" decoration-warning="state != 'assigned' and products_availability_state in ('expected', 'available')" decoration-danger="state != 'assigned' and products_availability_state == 'late'"/>\n                            <field name="date_done" string="Effective Date" invisible="state != 'done'" readonly="not is_date_editable"/>\n                            <field name="origin" placeholder="e.g. PO0032" readonly="state in ['cancel', 'done']"/>\n                            <field name="owner_id" groups="stock.group_tracking_owner" invisible="picking_type_code != 'incoming'" readonly="state in ['cancel', 'done']"/>\n                        </group>\n                    </group>\n                    <field name="picking_properties" columns="2"/>\n                    <notebook>\n                        <page string="Operations" name="operations">\n                            <field name="move_ids" mode="list,kanban" widget="stock_move_one2many" add-label="Add a Product" readonly="state == 'done' and is_locked" context="{'default_company_id': company_id, 'default_date': scheduled_date, 'default_date_deadline': date_deadline, 'picking_type_code': picking_type_code, 'default_picking_id': id, 'form_view_ref': 'stock.view_stock_move_operations', 'address_in_id': partner_id, 'default_picking_type_id': picking_type_id, 'default_location_id': location_id, 'default_location_dest_id': location_dest_id, 'default_partner_id': partner_id, 'picking_state': state}">\n                                <list decoration-muted="is_scrap or state == 'cancel' or (state == 'done' and is_locked == True)" string="Stock Moves" editable="bottom">\n                                    <control>\n                                        <create string="Add a Product" hotkey="shift+p"/>\n                                    </control>\n                                    <field name="sequence" widget="handle"/>\n                                    <field name="company_id" column_invisible="True"/>\n                                    <field name="state" readonly="0" column_invisible="True"/>\n                                    <field name="picking_type_id" column_invisible="True"/>\n                                    <field name="location_id" column_invisible="True"/>\n                                    <field name="location_dest_id" column_invisible="True"/>\n                                    <field name="partner_id" column_invisible="True" readonly="state == 'done'"/>\n                                    <field name="picking_code" column_invisible="True"/>\n                                    <field name="show_details_visible" column_invisible="True"/>\n                                    <field name="additional" column_invisible="True"/>\n                                    <field name="move_lines_count" column_invisible="True"/>\n                                    <field name="is_locked" column_invisible="True"/>\n                                    <field name="is_storable" column_invisible="True"/>\n                                    <field name="has_tracking" column_invisible="True"/>\n                                    <column>\n                                        <field name="product_id" context="{'default_is_storable': True}" required="1" readonly="(state != 'draft' and not additional) or move_lines_count &gt; 0" force_save="1" placeholder="Select a Product..."/>\n                                        <field name="description_picking" string="Description" optional="show" placeholder="Enter a Description..." readonly="parent.state in ('cancel', 'done')" widget="description_picking_text"/>\n                                    </column>\n                                    <field name="forecast_availability" string="" widget="forecast_widget" column_invisible="parent.state in ('cancel', 'done') or parent.picking_type_code not in ['internal', 'outgoing']"/>\n                                    <field name="packaging_uom_qty" optional="hide" groups="uom.group_uom"/>\n                                    <field name="packaging_uom_id" optional="hide" groups="uom.group_uom"/>\n                                    <field name="forecasted_location_id" optional="hide" groups="stock.group_stock_multi_locations"/>\n                                    <field name="date" optional="hide"/>\n                                    <field name="date_deadline" optional="hide"/>\n                                    <field name="is_quantity_done_editable" column_invisible="True"/>\n                                    <field name="show_quant" column_invisible="True"/>\n                                    <field name="show_lots_text" column_invisible="True"/>\n                                    <field name="show_lots_m2o" column_invisible="True"/>\n                                    <field name="is_initial_demand_editable" column_invisible="True"/>\n                                    <field name="display_import_lot" column_invisible="True"/>\n                                    <field name="has_lines_without_result_package" column_invisible="True"/>\n                                    <field name="package_ids" optional="show" widget="package_m2m" groups="stock.group_tracking_lot" width="200px" readonly="1"/>\n                                    <field name="product_uom_qty" string="Demand" readonly="not is_initial_demand_editable"/>\n                                    <field name="forecast_expected_date" column_invisible="True"/>\n                                    <field name="product_qty" readonly="1" column_invisible="True"/>\n                                    <field name="quantity" string="Quantity" readonly="not is_quantity_done_editable" column_invisible="parent.state=='draft'" decoration-danger="product_uom_qty and quantity &gt; product_uom_qty and parent.state not in ['done', 'cancel']"/>\n                                    <field name="uom_id" readonly="state != 'draft' and not additional" options="{'no_open': True, 'no_create': True}" widget="man