mage:height\\" content=\\"200\\"/>\\n                <meta name=\\"twitter:card\\" content=\\"summary_large_image\\"/>\\n            </t>\\n        </xpath>\\n        <head position=\\"inside\\">\\n            <t t-if=\\"not website\\">\\n                <style>\\n                    :root {\\n                        --portal-primary-color: <t t-out=\\"request.env.company.email_secondary_color\\"/>;\\n                        --portal-text-color: <t t-out=\\"request.env.company.email_primary_color\\"/>;\\n                    }\\n                    a, .text-primary {\\n                        color: var(--portal-primary-color) !important;\\n                    }\\n\\n                    .btn-primary {\\n                        background-color: var(--portal-primary-color) !important;\\n                        border-color: var(--portal-primary-color) !important;\\n                        color: var(--portal-text-color) !important;\\n                    }\\n                </style>\\n            </t>\\n        </head>\\n    </data>", "es_ES": "<data name=\\"Main Frontend Layout\\">\\n        <xpath expr=\\"//html\\" position=\\"attributes\\">\\n            <attribute name=\\"t-att-dir\\">request.env['res.lang']._get_data(code=request.env.lang).direction</attribute>\\n        </xpath>\\n        <xpath expr=\\"//body\\" position=\\"before\\">\\n            <t t-set=\\"classname_from_template\\" t-value=\\"(' o_' + response_template.replace('.', '_')) if isinstance(response_template, str) else 'o_id_' + str(response_template) if response_template else ''\\"/>\\n            <t t-set=\\"body_classname\\" t-valuef=\\"{{body_classname}}{{classname_from_template}}\\"/>\\n        </xpath>\\n        <xpath expr=\\"//div[@id='wrapwrap']\\" position=\\"attributes\\">\\n            <attribute name=\\"t-attf-class\\" add=\\"#{env['res.lang']._get_data(code=env.lang).direction == 'rtl' and 'o_rtl' or ''}\\" separator=\\" \\"/>\\n            <attribute name=\\"t-attf-class\\" add=\\"