           <!-- attrs doesn't work for 'disabled'-->\\n                    <button string=\\"Send\\" type=\\"object\\" class=\\"oe_highlight\\" name=\\"action_send_sms\\" data-hotkey=\\"q\\" invisible=\\"composition_mode not in ('comment', 'numbers') or not recipient_single_valid or scheduled_date\\"/>\\n                    <button string=\\"Schedule\\" type=\\"object\\" class=\\"btn-primary\\" name=\\"action_schedule_message\\" data-hotkey=\\"q\\" invisible=\\"composition_mode != 'comment' or not scheduled_date or not recipient_single_valid\\"/>\\n                    <button string=\\"Send\\" type=\\"object\\" class=\\"oe_highlight\\" name=\\"action_send_sms\\" data-hotkey=\\"q\\" invisible=\\"composition_mode not in ('comment', 'numbers') or recipient_single_valid or scheduled_date\\" disabled=\\"1\\"/>\\n                    <button string=\\"Schedule\\" type=\\"object\\" class=\\"btn-primary\\" name=\\"action_schedule_message\\" data-hotkey=\\"q\\" invisible=\\"composition_mode != 'comment' or not scheduled_date or recipient_single_valid\\" disabled=\\"1\\"/>\\n                    <button string=\\"Put in queue\\" type=\\"object\\" class=\\"oe_highlight\\" name=\\"action_send_sms\\" data-hotkey=\\"q\\" invisible=\\"composition_mode != 'mass'\\"/>\\n                    <button string=\\"Send now\\" type=\\"object\\" name=\\"action_send_sms_mass_now\\" data-hotkey=\\"w\\" invisible=\\"composition_mode != 'mass'\\"/>\\n                    <button class=\\"btn btn-secondary\\" special=\\"cancel\\" data-hotkey=\\"x\\"/>\\n                    <div class=\\"d-flex align-items-center\\">\\n                        <field name=\\"scheduled_date\\" widget=\\"text_scheduled_date\\" invisible=\\"composition_mode != 'comment'\\"/>\\n                        <field name=\\"template_id\\" widget=\\"mail_composer_template_selector\\" options=\\"{'no_label': True}\\" context=\\"{'default_model_id': res_model}\\"/>\\n                    </div>\\n                    <widget name=\\"s