732	16	\N	1	1	payment.confirm	\N	payment.confirm	qweb	payment/views/portal_templates.xml	primary	\N	{"en_US": "<t t-name=\\"payment.confirm\\">\\n        <!-- Parameters description:\\n            - tx: The transaction to display.\\n        -->\\n        <t t-set=\\"page_title\\">Payment Confirmation</t>\\n        <t t-set=\\"additional_title\\"><t t-out=\\"page_title\\"/></t>\\n        <t t-call=\\"portal.frontend_layout\\" page_title=\\"page_title\\" additional_title=\\"additional_title\\">\\n            <t t-set=\\"show_pm\\" t-value=\\"tx.payment_method_code != 'unknown'\\"/>\\n            <div class=\\"wrap\\">\\n                <div class=\\"container\\">\\n                    <!-- Portal breadcrumb -->\\n                    <t t-call=\\"payment.portal_breadcrumb\\"/>\\n                    <div class=\\"row justify-content-center my-3\\">\\n                    <div class=\\"col-12 col-lg-7\\">\\n                        <!-- Confirmation page -->\\n                        <div class=\\"row\\">\\n                            <div class=\\"col\\">\\n                                <t t-call=\\"payment.state_header\\"/>\\n                            </div>\\n                        </div>\\n                        <div t-att-class=\\"'text-bg-light row row-cols-1 mx-0 mb-3 py-2 rounded'                                           + (' row-cols-md-4' if show_pm else ' row-cols-md-3')\\">\\n                            <t t-call=\\"payment.summary_item\\" name.f=\\"amount\\" label.translate=\\"Amount\\" value=\\"tx.amount\\" options=\\"{'widget': 'monetary', 'display_currency': tx.currency_id}\\"/>\\n                            <t t-call=\\"payment.summary_item\\" name.f=\\"reference\\" label.translate=\\"Reference\\" value=\\"tx.reference\\" include_separator=\\"True\\"/>\\n                            <t t-if=\\"tx.payment_method_code != 'unknown'\\">\\n                               <t t-call=\\"payment.summary_item\\" name.f=\\"method\\" label.translate=\\"Payment Method\\" value=\\"tx.payment_method_id.name\\" include_separator=\\"True\\"/>\\n                            </t>\\n                            <t t-call=\\"payment.summary_item\\" name.f=\\"provider\\" label.translate=\\"Processed by\\" value=\\"tx.provider_id.sudo().name\\" include_separator=\\"True\\"/>\\n                        </div>\\n\\n                        <div class=\\"row\\">\\n                            <div class=\\"col offset-md-3 ps-0\\">\\n                                <a role=\\"button\\" class=\\"btn btn-primary float-end\\" href=\\"/my/home\\">\\n                                    Go to my Account <i class=\\"oi ms-2\\" data-icon=\\"east\\"/>\\n                                </a>\\n                            </div>\\n                        </div>\\n                    </div>\\n                    </div>\\n                </div>\\n            </div>\\n        </t>\\n    </t>", "es_ES": "<t t-name=\\"payment.confirm\\">\\n        <!-- Parameters description:\\n            - tx: The transaction to display.\\n        -->\\n        <t t-set=\\"page_title\\">Confirmación del pago</t>\\n        <t t-set=\\"additional_title\\"><t t-out=\\"page_title\\"/></t>\\n        <t t-call=\\"portal.frontend_layout\\" page_title=\\"page_title\\" additional_title=\\"additional_title\\">\\n            <t t-set=\\"show_pm\\" t-value=\\"tx.payment_method_code != 'unknown'\\"/>\\n            <div class=\\"wrap\\">\\n                <div class=\\"container\\">\\n                    <!-- Portal breadcrumb -->\\n                    <t t-call=\\"payment.portal_breadcrumb\\"/>\\n                    <div class=\\"row justify-content-center my-3\\">\\n                    <div class=\\"col-12 col-lg-7\\">\\n                        <!-- Confirmation page -->\\n                        <div class=\\"row\\">\\n                            <div class=\\"col\\">\\n                                <t t-call=\\"payment.state_header\\"/>\\n                            </div>\\n       