  </t>\\n                        <t t-else=\\"\\">\\n                            Conectar <span t-field=\\"env.company.onboarding_payment_module\\"/>\\n                        </t>\\n                    </a>\\n                    <a t-if=\\"not providers_sudo\\" role=\\"button\\" type=\\"action\\" class=\\"btn btn-outline-primary alert-warning\\" href=\\"/odoo/action-payment.action_payment_provider\\">\\n                        Buscar un proveedor de pago\\n                    </a>\\n                    <a t-else=\\"\\" role=\\"button\\" type=\\"action\\" class=\\"btn btn-outline-primary alert-warning\\" href=\\"/odoo/action-payment.action_payment_method\\">\\n                        Métodos de pago\\n                    </a>\\n                    <a t-if=\\"availability_report and debug\\" role=\\"button\\" class=\\"btn-link alert-warning align-self-center\\" data-bs-toggle=\\"collapse\\" href=\\"#payment_availability_report\\">\\n                        <strong><i class=\\"oi oi-filled\\" data-icon=\\"article\\"/> Mostrar informe de disponibilidad</strong>\\n                    </a>\\n                </div>\\n            </div>\\n            <t t-else=\\"\\">\\n                <div>\\n                    <strong>No hay métodos de pago disponibles</strong>\\n                </div>\\n                <div>\\n                    <a href=\\"/contactus\\">Contacto</a> el administrador del sitio web.\\n                </div>\\n            </t>\\n        </div>\\n        <!-- === Availability report === -->\\n        <t t-call=\\"payment.availability_report\\"/>\\n    </t>"}	<?xml version="1.0"?>\n<t t-name="payment.no_pms_available_warning">\n        <div class="alert alert-warning">\n            <div t-if="env.is_system()">\n                <p t-if="providers_sudo">\n                    None is configured for:\n                    <t t-out="env.company.country_id.name"/>,\n                    <t t-out="env.company.currency_id.name"/>.\n                </p>\n            