1935	100	\N	1	1	mrp.bom.form	mrp.bom	\N	form	mrp/views/mrp_bom_views.xml	primary	\N	{"en_US": "<form string=\\"Bill of Material\\">\\n                    <sheet>\\n                        <div class=\\"oe_button_box\\" name=\\"button_box\\" invisible=\\"context.get('parent_production_id')\\">\\n                            <button name=\\"action_open_exploded_bom_lines\\" type=\\"object\\" class=\\"oe_stat_button\\" icon=\\"account_tree\\" invisible=\\"component_count == 0\\">\\n                                <div class=\\"o_stat_info\\">\\n                                    <div class=\\"d-flex align-items-baseline gap-1\\">\\n                                        <span class=\\"o_stat_value order-1\\">\\n                                            <field name=\\"component_count\\"/>\\n                                        </span>\\n                                        <span class=\\"o_stat_text order-2\\">Components</span>\\n                                    </div>\\n                                    <div class=\\"d-flex align-items-baseline gap-1\\">\\n                                        <span class=\\"o_stat_value order-1\\">\\n                                            <field name=\\"subassembly_count\\"/>\\n                                        </span>\\n                                        <span class=\\"o_stat_text order-2\\">Sub Assemblies</span>\\n                                    </div>\\n                                </div>\\n                            </button>\\n                            <button name=\\"649\\" type=\\"action\\" class=\\"oe_stat_button\\" icon=\\"schedule\\" groups=\\"mrp.group_mrp_routings\\" invisible=\\"not operation_ids\\">\\n                                <div class=\\"o_field_widget o_stat_info\\">\\n                                    <span class=\\"o_stat_text\\">Operations<br/>Performance</span>\\n                                </div>\\n                            </button>\\n                            <button name=\\"670\\" type=\\"action\\" class=\\"oe_stat_button\\" icon=\\"menu\\">\\n                                <div class=\\"o_stat_info\\">\\n                                    <span class=\\"o_stat_text\\">BoM Overview</span>\\n                                </div>\\n                            </button>\\n                        </div>\\n                        <widget name=\\"web_ribbon\\" title=\\"Archived\\" bg_color=\\"text-bg-danger\\" invisible=\\"active\\"/>\\n                    <group>\\n                        <group>\\n                            <field name=\\"active\\" invisible=\\"1\\"/>\\n                            <field name=\\"company_id\\" invisible=\\"1\\"/>\\n                            <field name=\\"product_tmpl_id\\" context=\\"{'default_is_storable': True}\\" placeholder=\\"Product to build...\\"/>\\n                            <field name=\\"allow_operation_dependencies\\" invisible=\\"1\\"/>\\n                            <field name=\\"product_id\\" groups=\\"product.group_product_variant\\" options=\\"{'no_create': True}\\"/>\\n                            <field name=\\"product_id\\" groups=\\"!product.group_product_variant\\" invisible=\\"1\\"/>\\n                            <label for=\\"product_qty\\" string=\\"Quantity\\"/>\\n                            <div class=\\"o_row\\">\\n                                <field name=\\"product_qty\\" class=\\"mw-25\\"/>\\n                                <field name=\\"uom_id\\" options=\\"{'no_open':True, 'no_create':True, 'product_field': 'product_tmpl_id', 'quantity_field': 'product_qty'}\\" groups=\\"uom.group_uom\\" widget=\\"many2one_uom\\"/>\\n                            </div>\\n                        </group>\\n                        <group>\\n                            <field name=\\"code\\"/>\\n                            <field name=\\"type\\" widget=\\"radio\\" invisible=\\"context.get('parent_production_id')\\"/>\\n                            <p colspan=\\"2\\" class=\\"opacity-50 oe_edit_only\\" invisible=\\"type != 'phantom'\\">\\n                            <ul>\\n                                A BoM of type Kit is not produced with a manufacturing order.<br/>\\n                                Instead, it is used to decompose a BoM into its components when:\\n                                <li>\\n                                    it is added as a component in a manufacturing order\\n                                </li>\\n                                <li>\\n                                    it is moved via a transfer, such as a receipt or a delivery order for instance.\\n                                </li>\\n                            </ul>\\n                            </p>\\n                            <field name=\\"company_id\\" groups=\\"base.group_multi_company\\" options=\\"{'no_create': True, 'no_open': True}\\" invisible=\\"context.get('parent_production_id')\\" placeholder=\\"Visible to all\\"/>\\n                        </group>\\n                    </group>\\n                    <notebook>\\n                        <page string=\\"Components\\" name=\\"components\\">\\n                            <field name=\\"bom_line_ids\\" widget=\\"one2many\\" context=\\"{'default_parent_product_tmpl_id': product_tmpl_id, 'default_product_id': False, 'default_bom_id': id}\\">\\n                                <list string=\\"Components\\" editable=\\"bottom\\">\\n                                    <control>\\n                                        <create string=\\"Add a line\\"/>\\n                                        <button name=\\"action_add_from_catalog\\" string=\\"Catalog\\" type=\\"object\\" class=\\"px-4 btn-link\\" context=\\"{'order_id': parent.id}\\"/>\\n                                    </control>\\n                                    <field name=\\"company_id\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"sequence\\" widget=\\"handle\\"/>\\n                                    <field name=\\"product_id\\" context=\\"{'default_is_storable': True}\\"/>\\n                                    <field name=\\"product_tmpl_id\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"product_qty\\"/>\\n                                    <field name=\\"parent_product_tmpl_id\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"uom_id\\" options=\\"{'no_open': True, 'no_create': True, 'quantity_field': 'product_qty'}\\" groups=\\"uom.group_uom\\" widget=\\"many2one_uom\\"/>\\n                                    <field name=\\"possible_bom_product_template_attribute_value_ids\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"bom_product_template_attribute_value_ids\\" optional=\\"hide\\" widget=\\"many2many_tags\\" options=\\"{'no_create': True}\\" column_invisible=\\"parent.product_id\\" groups=\\"product.group_product_variant\\"/>\\n                                    <field name=\\"allowed_operation_ids\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"operation_id\\" groups=\\"mrp.group_mrp_routings\\" optional=\\"hidden\\" column_invisible=\\"parent.type not in ('normal', 'phantom')\\" options=\\"{'no_quick_create':True,'no_create_edit':True}\\"/>\\n                                </list>\\n                            </field>\\n                        </page>\\n                        <page string=\\"Operations\\" name=\\"operations\\" invisible=\\"type not in ('normal', 'phantom')\\" groups=\\"mrp.group_mrp_routings\\">\\n                                <field name=\\"operation_ids\\" invisible=\\"operation_ids.length == 0\\" context=\\"{'bom_id_invisible': True, 'default_bom_id': id, 'list_view_ref': 'mrp.mrp_routing_workcenter_bom_tree_view', 'target': 'new'}\\"/>\\n                                <div invisible=\\"operation_ids.length != 0\\">\\n                                    <div class=\\"o_mrp_routing_image bill_of_material position-relative\\">\\n                                        <img class=\\"position-absolute\\" src=\\"/mrp/static/img/routing_shopfloor.png\\" alt=\\"Shop Floor\\"/>\\n                                        <div class=\\"separator position-relative\\"/>\\n                                        <span class=\\"o_annotation o_annotation_1 o_annotation_end position-absolute\\">Time Clock</span>\\n                                        <span class=\\"o_annotation o_annotation_2 o_annotation_end position-absolute\\">Quality Control</span>\\n                                        <span class=\\"o_annotation o_annotation_3 o_annotation_start position-absolute\\">Feedback Loop</span>\\n                                        <span class=\\"o_annotation o_annotation_4 o_annotation_start position-absolute\\">Register Materials</span>\\n                                        <span class=\\"o_annotation o_annotation_5 o_annotation_start position-absolute\\">Select Operator</span>\\n                                        <div class=\\"o_text position-absolute\\">\\n                                            <p>\\n                                                No Operations Yet !\\n                                            </p>\\n                                            <p>\\n                                                Run your Shop Floor with work orders for each operation defined on your bill of material.\\n                                            </p>\\n                                            <p>\\n                                                Each operation can have multiple steps (scan products, view instructions) or even quality checks.\\n                                            </p>\\n                                        </div>\\n                                    </div>\\n                                </div>\\n                                <div class=\\"d-flex justify-content-center gap-1\\" invisible=\\"operation_ids.length != 0\\">\\n                                    <button name=\\"action_open_operation_form\\" type=\\"object\\" class=\\"btn btn-primary\\">\\n                                        <span class=\\"o_stat_text\\">Add Operation</span>\\n                                    </button>\\n                                    <button name=\\"action_copy_existing_operations\\" type=\\"object\\" invisible=\\"not show_copy_operations_button\\">\\n                                        <span class=\\"o_stat_text\\">Copy Existing Operations</span>\\n                                    </button>\\n                                </div>\\n                        </page>\\n                        <page string=\\"By-products\\" name=\\"by_products\\" invisible=\\"type != 'normal'\\" groups=\\"mrp.group_mrp_byproducts\\">\\n                            <field name=\\"byproduct_ids\\" context=\\"{'form_view_ref' : 'mrp.mrp_bom_byproduct_form_view', 'default_bom_id': id}\\">\\n                                <list string=\\"By-products\\" editable=\\"bottom\\">\\n                                    <control>\\n                                        <create string=\\"Add a line\\"/>\\n                                        <button name=\\"action_add_from_catalog\\" string=\\"Catalog\\" type=\\"object\\" class=\\"px-4 btn-link\\" context=\\"{'order_id': parent.id}\\"/>\\n                                    </control>\\n                                    <field name=\\"company_id\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"sequence\\" widget=\\"handle\\"/>\\n                                    <field name=\\"product_id\\" context=\\"{'default_is_storable': True}\\"/>\\n                                    <field name=\\"product_qty\\"/>\\n                                    <field name=\\"uom_id\\" groups=\\"uom.group_uom\\" options=\\"{'quantity_field': 'product_qty'}\\" widget=\\"many2one_uom\\"/>\\n                                    <field name=\\"cost_share\\" optional=\\"hide\\"/>\\n                                    <field name=\\"allowed_operation_ids\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"operation_id\\" groups=\\"mrp.group_mrp_routings\\" options=\\"{'no_quick_create':True,'no_create_edit':True}\\"/>\\n                                    <field name=\\"possible_bom_product_template_attribute_value_ids\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"bom_product_template_attribute_value_ids\\" optional=\\"hide\\" widget=\\"many2many_tags\\" options=\\"{'no_create': True}\\" column_invisible=\\"parent.product_id\\" groups=\\"product.group_product_variant\\"/>\\n                                </list>\\n                            </field>\\n                       </page>\\n                        <page string=\\"Miscellaneous\\" name=\\"miscellaneous\\">\\n                            <group>\\n                                <group invisible=\\"type == 'phantom'\\">\\n                                    <field name=\\"picking_type_id\\" options=\\"{'no_quick_create': True}\\" groups=\\"stock.group_adv_location\\"/>\\n                                    <label for=\\"produce_delay\\"/>\\n                                    <div class=\\"o_row\\">\\n                                        <field name=\\"produce_delay\\" class=\\"oe_inline\\"/>\\n                                        <span>days</span>\\n                                    </div>\\n                                    <label for=\\"days_to_prepare_mo\\"/>\\n                                    <div class=\\"o_row\\">\\n                                        <field name=\\"days_to_prepare_mo\\" class=\\"oe_inline\\"/>\\n                                        <span>days</span>\\n                                        <button class=\\"btn btn-link\\" type=\\"button\\">\\n                                            <field name=\\"json_popover\\" invisible=\\"not json_popover\\" widget=\\"mrp_bom_popover\\"/>\\n                                        </button>\\n                                    </div>\\n                                    <label for=\\"batch_size\\" invisible=\\"type != 'normal'\\"/>\\n                                    <div class=\\"o_row\\" invisible=\\"type != 'normal'\\">\\n                                        <field name=\\"enable_batch_size\\"/>\\n                                        <field name=\\"batch_size\\" class=\\"w-50\\" invisible=\\"not enable_batch_size\\" decoration-danger=\\"batch_size &lt;= 0.0\\"/>\\n                                        <field name=\\"uom_id\\" groups=\\"uom.group_uom\\" readonly=\\"1\\" invisible=\\"not enable_batch_size\\"/>\\n                                    </div>\\n                                    <field name=\\"continuous\\" invisible=\\"type != 'normal'\\" groups=\\"mrp.group_mrp_routings\\"/>\\n                                </group>\\n                                <group>\\n                                    <field name=\\"ready_to_produce\\" invisible=\\"type == 'phantom'\\" string=\\"Manufacturing Readiness\\" widget=\\"radio\\" groups=\\"mrp.group_mrp_routings\\"/>\\n                                    <field name=\\"allow_operation_dependencies\\" groups=\\"mrp.group_mrp_routings\\"/>\\n                                    <field name=\\"note\\"/>\\n                                </group>\\n                            </group>\\n                        </page>\\n                    </notebook>\\n                    </sheet>\\n                    <chatter/>\\n                </form>", "es_ES": "<form string=\\"Lista de materiales\\">\\n                    <sheet>\\n                        <div class=\\"oe_button_box\\" name=\\"button_box\\" invisible=\\"context.get('parent_production_id')\\">\\n                            <button name=\\"action_open_exploded_bom_lines\\" type=\\"object\\" class=\\"oe_stat_button\\" icon=\\"account_tree\\" invisible=\\"component_count == 0\\">\\n                                <div class=\\"o_stat_info\\">\\n                                    <div class=\\"d-flex align-items-baseline gap-1\\">\\n                                        <span class=\\"o_stat_value order-1\\">\\n                                            <field name=\\"component_count\\"/>\\n                                        </span>\\n                                        <span class=\\"o_stat_text order-2\\">Components</span>\\n                                    </div>\\n                                    <div class=\\"d-flex align-items-baseline gap-1\\">\\n                                        <span class=\\"o_stat_value order-1\\">\\n                                            <field name=\\"subassembly_count\\"/>\\n                                        </span>\\n                                        <span class=\\"o_stat_text order-2\\">Sub Assemblies</span>\\n                                    </div>\\n                                </div>\\n                            </button>\\n                            <button name=\\"649\\" type=\\"action\\" class=\\"oe_stat_button\\" icon=\\"schedule\\" groups=\\"mrp.group_mrp_routings\\" invisible=\\"not operation_ids\\">\\n                                <div class=\\"o_field_widget o_stat_info\\">\\n                                    <span class=\\"o_stat_text\\">Rendimiento de las<br/>operaciones</span>\\n                                </div>\\n                            </button>\\n                            <button name=\\"670\\" type=\\"action\\" class=\\"oe_stat_button\\" icon=\\"menu\\">\\n                                <div class=\\"o_stat_info\\">\\n                                    <span class=\\"o_stat_text\\">Vista general de LdM</span>\\n                                </div>\\n                            </button>\\n                        </div>\\n                        <widget name=\\"web_ribbon\\" title=\\"Archivado\\" bg_color=\\"text-bg-danger\\" invisible=\\"active\\"/>\\n                    <group>\\n                        <group>\\n                            <field name=\\"active\\" invisible=\\"1\\"/>\\n                            <field name=\\"company_id\\" invisible=\\"1\\"/>\\n                            <field name=\\"product_tmpl_id\\" context=\\"{'default_is_storable': True}\\" placeholder=\\"Producto a construir...\\"/>\\n                            <field name=\\"allow_operation_dependencies\\" invisible=\\"1\\"/>\\n                            <field name=\\"product_id\\" groups=\\"product.group_product_variant\\" options=\\"{'no_create': True}\\"/>\\n                            <field name=\\"product_id\\" groups=\\"!product.group_product_variant\\" invisible=\\"1\\"/>\\n                            <label for=\\"product_qty\\" string=\\"Cantidad\\"/>\\n                            <div class=\\"o_row\\">\\n                                <field name=\\"product_qty\\" class=\\"mw-25\\"/>\\n                                <field name=\\"uom_id\\" options=\\"{'no_open':True, 'no_create':True, 'product_field': 'product_tmpl_id', 'quantity_field': 'product_qty'}\\" groups=\\"uom.group_uom\\" widget=\\"many2one_uom\\"/>\\n                            </div>\\n                        </group>\\n                        <group>\\n                            <field name=\\"code\\"/>\\n                            <field name=\\"type\\" widget=\\"radio\\" invisible=\\"context.get('parent_production_id')\\"/>\\n                            <p colspan=\\"2\\" class=\\"opacity-50 oe_edit_only\\" invisible=\\"type != 'phantom'\\">\\n                            <ul>\\n                                Una lista de materiales (LdM) de tipo kit no se produce con una orden de fabricación.<br/>\\n                                Por el contrario, se utiliza para desglosar una LdM en componentes cuando:\\n                                <li>\\n                                    se añadió como componente en una orden de fabricación\\n                                </li>\\n                                <li>\\n                                    se movió a través de un traslado, como por ejemplo una recepción o una orden de entrega.\\n                                </li>\\n                            </ul>\\n                            </p>\\n                            <field name=\\"company_id\\" groups=\\"base.group_multi_company\\" options=\\"{'no_create': True, 'no_open': True}\\" invisible=\\"context.get('parent_production_id')\\" placeholder=\\"Visible para todos\\"/>\\n                        </group>\\n                    </group>\\n                    <notebook>\\n                        <page string=\\"Componentes\\" name=\\"components\\">\\n                            <field name=\\"bom_line_ids\\" widget=\\"one2many\\" context=\\"{'default_parent_product_tmpl_id': product_tmpl_id, 'default_product_id': False, 'default_bom_id': id}\\">\\n                                <list string=\\"Componentes\\" editable=\\"bottom\\">\\n                                    <control>\\n                                        <create string=\\"Añadir una línea\\"/>\\n                                        <button name=\\"action_add_from_catalog\\" string=\\"Catálogo\\" type=\\"object\\" class=\\"px-4 btn-link\\" context=\\"{'order_id': parent.id}\\"/>\\n                                    </control>\\n                                    <field name=\\"company_id\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"sequence\\" widget=\\"handle\\"/>\\n                                    <field name=\\"product_id\\" context=\\"{'default_is_storable': True}\\"/>\\n                                    <field name=\\"product_tmpl_id\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"product_qty\\"/>\\n                                    <field name=\\"parent_product_tmpl_id\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"uom_id\\" options=\\"{'no_open': True, 'no_create': True, 'quantity_field': 'product_qty'}\\" groups=\\"uom.group_uom\\" widget=\\"many2one_uom\\"/>\\n                                    <field name=\\"possible_bom_product_template_attribute_value_ids\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"bom_product_template_attribute_value_ids\\" optional=\\"hide\\" widget=\\"many2many_tags\\" options=\\"{'no_create': True}\\" column_invisible=\\"parent.product_id\\" groups=\\"product.group_product_variant\\"/>\\n                                    <field name=\\"allowed_operation_ids\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"operation_id\\" groups=\\"mrp.group_mrp_routings\\" optional=\\"hidden\\" column_invisible=\\"parent.type not in ('normal', 'phantom')\\" options=\\"{'no_quick_create':True,'no_create_edit':True}\\"/>\\n                                </list>\\n                            </field>\\n                        </page>\\n                        <page string=\\"Operaciones\\" name=\\"operations\\" invisible=\\"type not in ('normal', 'phantom')\\" groups=\\"mrp.group_mrp_routings\\">\\n                                <field name=\\"operation_ids\\" invisible=\\"operation_ids.length == 0\\" context=\\"{'bom_id_invisible': True, 'default_bom_id': id, 'list_view_ref': 'mrp.mrp_routing_workcenter_bom_tree_view', 'target': 'new'}\\"/>\\n                                <div invisible=\\"operation_ids.length != 0\\">\\n                                    <div class=\\"o_mrp_routing_image bill_of_material position-relative\\">\\n                                        <img class=\\"position-absolute\\" src=\\"/mrp/static/img/routing_shopfloor.png\\" alt=\\"Taller\\"/>\\n                                        <div class=\\"separator position-relative\\"/>\\n                                        <span class=\\"o_annotation o_annotation_1 o_annotation_end position-absolute\\">Reloj de fichaje</span>\\n                                        <span class=\\"o_annotation o_annotation_2 o_annotation_end position-absolute\\">Control de calidad</span>\\n                                        <span class=\\"o_annotation o_annotation_3 o_annotation_start position-absolute\\">Bucle de retroalimentación</span>\\n                                        <span class=\\"o_annotation o_annotation_4 o_annotation_start position-absolute\\">Registrar materiales</span>\\n                                        <span class=\\"o_annotation o_annotation_5 o_annotation_start position-absolute\\">Seleccionar operario</span>\\n                                        <div class=\\"o_text position-absolute\\">\\n                                            <p>\\n                                                ¡Aún no hay operaciones!\\n                                            </p>\\n                                            <p>\\n                                                Gestiona tu taller con órdenes de trabajo para cada operación definida en tu lista de materiales.\\n                                            </p>\\n                                            <p>\\n                                                Cada operación puede tener varios pasos (escanear productos, ver instrucciones) o incluso controles de calidad.\\n                                            </p>\\n                                        </div>\\n                                    </div>\\n                                </div>\\n                                <div class=\\"d-flex justify-content-center gap-1\\" invisible=\\"operation_ids.length != 0\\">\\n                                    <button name=\\"action_open_operation_form\\" type=\\"object\\" class=\\"btn btn-primary\\">\\n                                        <span class=\\"o_stat_text\\">Añadir operación</span>\\n                                    </button>\\n                                    <button name=\\"action_copy_existing_operations\\" type=\\"object\\" invisible=\\"not show_copy_operations_button\\">\\n                                        <span class=\\"o_stat_text\\">Copiar operaciones existentes</span>\\n                                    </button>\\n                                </div>\\n                        </page>\\n                        <page string=\\"Subproductos\\" name=\\"by_products\\" invisible=\\"type != 'normal'\\" groups=\\"mrp.group_mrp_byproducts\\">\\n                            <field name=\\"byproduct_ids\\" context=\\"{'form_view_ref' : 'mrp.mrp_bom_byproduct_form_view', 'default_bom_id': id}\\">\\n                                <list string=\\"Subproductos\\" editable=\\"bottom\\">\\n                                    <control>\\n                                        <create string=\\"Añadir una línea\\"/>\\n                                        <button name=\\"action_add_from_catalog\\" string=\\"Catálogo\\" type=\\"object\\" class=\\"px-4 btn-link\\" context=\\"{'order_id': parent.id}\\"/>\\n                                    </control>\\n                                    <field name=\\"company_id\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"sequence\\" widget=\\"handle\\"/>\\n                                    <field name=\\"product_id\\" context=\\"{'default_is_storable': True}\\"/>\\n                                    <field name=\\"product_qty\\"/>\\n                                    <field name=\\"uom_id\\" groups=\\"uom.group_uom\\" options=\\"{'quantity_field': 'product_qty'}\\" widget=\\"many2one_uom\\"/>\\n                                    <field name=\\"cost_share\\" optional=\\"hide\\"/>\\n                                    <field name=\\"allowed_operation_ids\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"operation_id\\" groups=\\"mrp.group_mrp_routings\\" options=\\"{'no_quick_create':True,'no_create_edit':True}\\"/>\\n                                    <field name=\\"possible_bom_product_template_attribute_value_ids\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"bom_product_template_attribute_value_ids\\" optional=\\"hide\\" widget=\\"many2many_tags\\" options=\\"{'no_create': True}\\" column_invisible=\\"parent.product_id\\" groups=\\"product.group_product_variant\\"/>\\n                                </list>\\n                            </field>\\n                       </page>\\n                        <page string=\\"Varios\\" name=\\"miscellaneous\\">\\n                            <group>\\n                                <group invisible=\\"type == 'phantom'\\">\\n                                    <field name=\\"picking_type_id\\" options=\\"{'no_quick_create': True}\\" groups=\\"stock.group_adv_location\\"/>\\n                                    <label for=\\"produce_delay\\"/>\\n                                    <div class=\\"o_row\\">\\n                                        <field name=\\"produce_delay\\" class=\\"oe_inline\\"/>\\n                                        <span>days</span>\\n                                    </div>\\n                                    <label for=\\"days_to_prepare_mo\\"/>\\n                                    <div class=\\"o_row\\">\\n                                        <field name=\\"days_to_prepare_mo\\" class=\\"oe_inline\\"/>\\n                                        <span>days</span>\\n                                        <button class=\\"btn btn-link\\" type=\\"button\\">\\n                                            <field name=\\"json_popover\\" invisible=\\"not json_popover\\" widget=\\"mrp_bom_popover\\"/>\\n                                        </button>\\n                                    </div>\\n                                    <label for=\\"batch_size\\" invisible=\\"type != 'normal'\\"/>\\n                                    <div class=\\"o_row\\" invisible=\\"type != 'normal'\\">\\n                                        <field name=\\"enable_batch_size\\"/>\\n                                        <field name=\\"batch_size\\" class=\\"w-50\\" invisible=\\"not enable_batch_size\\" decoration-danger=\\"batch_size &lt;= 0.0\\"/>\\n                                        <field name=\\"uom_id\\" groups=\\"uom.group_uom\\" readonly=\\"1\\" invisible=\\"not enable_batch_size\\"/>\\n                                    </div>\\n                                    <field name=\\"continuous\\" invisible=\\"type != 'normal'\\" groups=\\"mrp.group_mrp_routings\\"/>\\n                                </group>\\n                                <group>\\n                                    <field name=\\"ready_to_produce\\" invisible=\\"type == 'phantom'\\" string=\\"Preparación para la fabricación\\" widget=\\"radio\\" groups=\\"mrp.group_mrp_routings\\"/>\\n                                    <field name=\\"allow_operation_dependencies\\" groups=\\"mrp.group_mrp_routings\\"/>\\n                                    <field name=\\"note\\"/>\\n                                </group>\\n                            </group>\\n                        </page>\\n                    </notebook>\\n                    </sheet>\\n                    <chatter/>\\n                </form>"}	<?xml version="1.0"?>\n<form string="Bill of Material">\n                    <sheet>\n                        <div class="oe_button_box" name="button_box" invisible="context.get('parent_production_id')">\n                            <button name="action_open_exploded_bom_lines" type="object" class="oe_stat_button" icon="account_tree" invisible="component_count == 0">\n                                <div class="o_stat_info">\n                                    <div class="d-flex align-items-baseline gap-1">\n                                        <span class="o_stat_value order-1">\n                                            <field name="component_count"/>\n                                        </span>\n                                        <span class="o_stat_text order-2">Components</span>\n                                    </div>\n                                    <div class="d-flex align-items-baseline gap-1">\n                                        <span class="o_stat_value order-1">\n                                            <field name="subassembly_count"/>\n                                        </span>\n                                        <span class="o_stat_text order-2">Sub Assemblies</span>\n                                    </div>\n                                </div>\n                            </button>\n                            <button name="649" type="action" class="oe_stat_button" icon="schedule" groups="mrp.group_mrp_routings" invisible="not operation_ids">\n                                <div class="o_field_widget o_stat_info">\n                                    <span class="o_stat_text">Operations<br/>Performance</span>\n                                </div>\n                            </button>\n                            <button name="670" type="action" class="oe_stat_button" icon="menu">\n                                <div class="o_stat_info">\n                                    <span class="o_stat_text">BoM Overview</span>\n                                </div>\n                            </button>\n                        </div>\n                        <widget name="web_ribbon" title="Archived" bg_color="text-bg-danger" invisible="active"/>\n                    <group>\n                        <group>\n                            <field name="active" invisible="1"/>\n                            <field name="company_id" invisible="1"/>\n                            <field name="product_tmpl_id" context="{'default_is_storable': True}" placeholder="Product to build..."/>\n                            <field name="allow_operation_dependencies" invisible="1"/>\n                            <field name="product_id" groups="product.group_product_variant" options="{'no_create': True}"/>\n                            <field name="product_id" groups="!product.group_product_variant" invisible="1"/>\n                            <label for="product_qty" string="Quantity"/>\n                            <div class="o_row">\n                                <field name="product_qty" class="mw-25"/>\n                                <field name="uom_id" options="{'no_open':True, 'no_create':True, 'product_field': 'product_tmpl_id', 'quantity_field': 'product_qty'}" groups="uom.group_uom" widget="many2one_uom"/>\n                            </div>\n                        </group>\n                        <group>\n                            <field name="code"/>\n                            <field name="type" widget="radio" invisible="context.get('parent_production_id')"/>\n                            <p colspan="2" class="opacity-50 oe_edit_only" invisible="type != 'phantom'">\n                            <ul>\n                                A BoM of type Kit is not produced with a manufacturing order.<br/>\n                                Instead, it is used to decompose a BoM into its components when:\n                                <li>\n                                    it is added as a component in a manufacturing order\n                                </li>\n                                <li>\n                                    it is moved via a transfer, such as a receipt or a delivery order for instance.\n                                </li>\n                            </ul>\n                            </p>\n                            <field name="company_id" groups="base.group_multi_company" options="{'no_create': True, 'no_open': True}" invisible="context.get('parent_production_id')" placeholder="Visible to all"/>\n                        </group>\n                    </group>\n                    <notebook>\n                        <page string="Components" name="components">\n                            <field name="bom_line_ids" widget="one2many" context="{'default_parent_product_tmpl_id': product_tmpl_id, 'default_product_id': False, 'default_bom_id': id}">\n                                <list string="Components" editable="bottom">\n                                    <control>\n                                        <create string="Add a line"/>\n                                        <button name="action_add_from_catalog" string="Catalog" type="object" class="px-4 btn-link" context="{'order_id': parent.id}"/>\n                                    </control>\n                                    <field name="company_id" column_invisible="True"/>\n                                    <field name="sequence" widget="handle"/>\n                                    <field name="product_id" context="{'default_is_storable': True}"/>\n                                    <field name="product_tmpl_id" column_invisible="True"/>\n                                    <field name="product_qty"/>\n                                    <field name="parent_product_tmpl_id" column_invisible="True"/>\n                                    <field name="uom_id" options="{'no_open': True, 'no_create': True, 'quantity_field': 'product_qty'}" groups="uom.group_uom" widget="many2one_uom"/>\n                                    <field name="possible_bom_product_template_attribute_value_ids" column_invisible="True"/>\n                                    <field name="bom_product_template_attribute_value_ids" optional="hide" widget="many2many_tags" options="{'no_create': True}" column_invisible="parent.product_id" groups="product.group_product_variant"/>\n                                    <field name="allowed_operation_ids" column_invisible="True"/>\n                            