 not lot_producing_ids or (serial_numbers_count &lt;= 1 and product_qty &lt;= 1)\\"/>\\n                                <button name=\\"action_generate_serial\\" type=\\"object\\" class=\\"btn btn-primary o_right_alignment\\" string=\\"Generate Lot Number\\" aria-label=\\"Creates a new lot number\\" role=\\"img\\" invisible=\\"product_tracking != 'lot' or lot_producing_ids\\"/>\\n                                <button name=\\"action_clear_lot_producing_ids\\" type=\\"object\\" class=\\"btn btn-secondary o_right_alignment\\" string=\\"Clear\\" aria-label=\\"Clears the selected lot/serial number\\" role=\\"img\\" invisible=\\"state == 'done' or (product_tracking == 'serial' and (product_qty &gt; 1 or serial_numbers_count &gt; 1)) or not lot_producing_ids\\"/>\\n                            </div>\\n                        </group>\\n                        <group name=\\"group_extra_info\\">\\n                            <label name=\\"scheduled_date\\" for=\\"date_start\\" string=\\"Scheduled Date\\" invisible=\\"state in ['progress', 'to_close', 'done', 'cancel']\\"/>\\n                            <label name=\\"start_date\\" for=\\"date_start\\" string=\\"Start Date\\" invisible=\\"state not in ['progress', 'to_close', 'done', 'cancel']\\"/>\\n                            <div class=\\"o_row\\" name=\\"date_start\\">\\n                                <field name=\\"date_start\\" readonly=\\"state in ['done', 'to_close', 'cancel']\\" decoration-warning=\\"state not in ('done', 'cancel') and date_start &lt; now\\" decoration-danger=\\"state not in ('done', 'cancel') and date_deadline and date_deadline &lt; date_finished\\" help=\\"Date at which you plan to start.                                           Red if the scheduled end is forecasted after the production order deadline.                                           Orange if the scheduled date is in the past.\\"/>\\n                                <field name=\\"delay_alert_date\\" invisible=\\"1\\"/>\\n                                <field nolabel=\\"1\\" name=\\"json_popover\\" widget=\\"stock_rescheduling_popover\\" invisible=\\"not json_popover\\"/>\\n                            </div>\\n                            <field name=\\"date_finished\\" string=\\"End Date\\" readonly=\\"is_locked\\" invisible=\\"state != 'done'\\" help=\\"Date at which you finished production.\\"/>\\n                            <field name=\\"components_availability_state\\" invisible=\\"1\\"/>\\n                            <field name=\\"components_availability\\" invisible=\\"state not in ['confirmed', 'progress']\\" decoration-success=\\"reservation_state == 'assigned' or components_availability_state == 'available'\\" decoration-warning=\\"reservation_state != 'assigned' and components_availability_state in ('expected', 'available')\\" decoration-danger=\\"reservation_state != 'assigned' and components_availability_state in ('late', 'unavailable')\\"/>\\n                            <field name=\\"user_id\\" widget=\\"many2one_avatar\\" readonly=\\"state in ['cancel', 'done']\\"/>\\n                            <field name=\\"show_final_lots\\" invisible=\\"1\\"/>\\n                            <field name=\\"production_location_id\\" invisible=\\"1\\" readonly=\\"1\\"/>\\n                            <field name=\\"move_finished_ids\\" invisible=\\"1\\" readonly=\\"state == 'cancel' or (state == 'done' and is_locked)\\">\\n                                <list editable=\\"bottom\\">\\n                                    <field name=\\"product_id\\" readonly=\\"state == 'done'\\"/>\\n                                    <field name=\\"product_uom_qty\\" readonly=\\"state == 'done'\\"/>\\n                                    <field name=\\"uom_id\\" groups=\\"uom.group_uom\\" widget=\\"many2one_uom\\"/>\\n                                    <field name=\\"operation_id\\"/>\\n                                    <field name=\\"byproduct_id\\"/>\\n                                    <field name=\\"date_deadline\\"/>\\n                                    <field name=\\"picking_type_id\\"/>\\n                                    <field name=\\"location_id\\"/>\\n                                    <field name=\\"location_dest_id\\"/>\\n                                    <field name=\\"company_id\\"/>\\n                                    <field name=\\"warehouse_id\\"/>\\n                                    <field name=\\"origin\\"/>\\n                                    <field name=\\"propagate_cancel\\"/>\\n                                    <field name=\\"move_dest_ids\\"/>\\n                                    <field name=\\"state\\"/>\\n                                    <!-- Useless as the editable in tree declaration -> For Form Test-->\\n                                    <field name=\\"allowed_operation_ids\\"/>\\n                                    <!--\\n                                    Required for test_00_mrp_byproduct\\n                                    when changing the mrp.production product_qty\\n                                    `_onchange_producing` is called,\\n                                    calling `_set_qty_producing`,\\n                                    which changes the `quantity_done` of byproducts\\n                                    If byproducts are not in the view (`groups=\\"mrp.group_mrp_byproducts\\"`)\\n                                    and `quantity_done` is not within the finished move views,\\n                                    (byproduct moves are a subset of finished moves)\\n                                    the `quantity_done` of byproducts is not updated correctly with the onchange\\n                                    Another solution is to add `self.env.user.group_ids += self.env.ref('mrp.group_mrp_byproducts')`\\n                                    to the test `test_00_mrp_byproduct`, which could makes sense as it's a test testing the byproducts features,\\n                                    for which you should have the byproducts group to have access to,\\n                                    but it seemed better to keep the feature working even if you do not see the byproducts features with your user.\\n                                    That being said, the best would be to have the byproducts feature working without relying on anything in the view,\\n                                    e.g. so the byproducts feature works with xmlrpc calls.\\n                                    -->\\n                                    <field name=\\"quantity\\"/>\\n                                    <field name=\\"picked\\"/>\\n                                    <!-- Required for test_fifo_byproduct -->\\n                                    <field name=\\"cost_share\\"/>\\n                                </list>\\n                            </field>\\n                        </group>\\n                    </group>\\n                    <notebook>\\n                        <page string=\\"Components\\" name=\\"components\\">\\n                            <field name=\\"move_raw_ids\\" mode=\\"list,kanban\\" context=\\"{'default_date': date_start, 'default_date_deadline': date_start, 'default_location_id': location_src_id, 'default_location_dest_id': production_location_id, 'default_warehouse_id': warehouse_id, 'default_state': 'draft', 'default_raw_material_production_id': id, 'default_picking_type_id': picking_type_id, 'default_company_id': company_id, 'form_view_ref': 'mrp.view_mrp_stock_move_operations', 'active_mo_id': id}\\" readonly=\\"state in ('done', 'cancel')\\">\\n                                <list editable=\\"bottom\\">\\n                                    <control>\\n                                        <create string=\\"Add a line\\"/>\\n                                        <button name=\\"action_add_from_catalog_raw\\" string=\\"Catalog\\" type=\\"object\\" class=\\"px-4 btn-link\\" context=\\"{'order_id': parent.id}\\"/>\\n                                    </control>\\n                                    <field name=\\"sequence\\" widget=\\"handle\\"/>\\n                                    <field name=\\"product_id\\" force_save=\\"1\\" context=\\"{'default_is_storable': True}\\" required=\\"1\\" readonly=\\"move_lines_count &gt; 0 or state == 'cancel' or (state != 'draft' and not additional)\\" domain=\\"[('type', '=', 'consu')]\\"/>\\n                                    <field name=\\"forecast_availability\\" column_invisible=\\"parent.state in ['done', 'cancel']\\" string=\\"\\" widget=\\"forecast_widget\\"/>\\n                                    <field name=\\"location_id\\" string=\\"From\\" readonly=\\"1\\" force_save=\\"1\\" groups=\\"stock.group_stock_multi_locations\\" optional=\\"hide\\"/>\\n                                    <!-- test_immediate_validate_uom_2, test_product_produce_different_uom -->\\n                                    <field name=\\"uom_id\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"propagate_cancel\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"price_unit\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"company_id\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"allowed_operation_ids\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"unit_factor\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"date_deadline\\" column_invisible=\\"True\\" force_save=\\"1\\"/>\\n                                    <field name=\\"date\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"additional\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"picking_type_id\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"is_storable\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"has_tracking\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"operation_id\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"bom_line_id\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"sequence\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"warehouse_id\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"is_locked\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"move_lines_count\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"location_dest_id\\" domain=\\"[('id', 'child_of', parent.location_dest_id)]\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"state\\" column_invisible=\\"True\\" force_save=\\"1\\"/>\\n                                    <field name=\\"should_consume_qty\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"product_uom_qty\\" widget=\\"mrp_should_consume\\" force_save=\\"1\\" string=\\"To Consume\\" column_invisible=\\"parent.qty_producing in (0, parent.product_qty)\\" readonly=\\"parent.state != 'draft'                                                      and ((parent.state not in ('confirmed', 'progress', 'to_close') and not parent.is_planned)                                                           or (parent.is_locked and state != 'draft'))\\"/>\\n                                    <field name=\\"product_uom_qty\\" force_save=\\"1\\" string=\\"To Consume\\" column_invisible=\\"parent.qty_producing not in (0, parent.product_qty)\\" readonly=\\"parent.state != 'draft'                                                      and ((parent.state not in ('confirmed', 'progress', 'to_close') and not parent.is_planned)                                                           or (parent.is_locked and state != 'draft'))\\"/>\\n                                    <field name=\\"product_qty\\" readonly=\\"1\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"forecast_expected_date\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"quantity\\" string=\\"Consumed\\" decoration-success=\\"(state not in ['done', 'cancel']) and (quantity - (should_consume_qty if parent.qty_producing else product_uom_qty) == 0)\\" decoration-danger=\\"(state not in ['done', 'cancel']) and (quantity - (should_consume_qty if parent.qty_producing else product_uom_qty) &gt; 0)\\" decoration-warning=\\"(state not in ['done', 'cancel']) and (quantity - (should_consume_qty if parent.qty_producing else product_uom_qty) &lt; 0)\\" column_invisible=\\"parent.state == 'draft'\\" force_save=\\"1\\"/>\\n                                    <field name=\\"uom_id\\" readonly=\\"state != 'draft' and id\\" options=\\"{'no_open': True, 'no_create': True}\\" groups=\\"uom.group_uom\\" widget=\\"many2one_uom\\"/>\\n                                    <field name=\\"picked\\" optional=\\"hide\\"/>\\n                                    <field name=\\"show_details_visible\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"lot_ids\\" widget=\\"many2many_tags\\" optional=\\"hide\\" string=\\"Lot/Serial Numbers\\" help=\\"Displays the consumed Lot/Serial Numbers.\\" groups=\\"stock.group_production_lot\\" readonly=\\"1\\" column_invisible=\\"not parent.show_lot_ids or parent.state == 'draft'\\" invisible=\\"not show_details_visible\\" create=\\"parent.use_create_components_lots\\" context=\\"{'default_product_id': product_id}\\" domain=\\"[('product_id','=',product_id)]\\"/>\\n                                    <button name=\\"action_show_details\\" type=\\"object\\" string=\\"Details\\" context=\\"{'default_product_uom_qty': 0}\\" invisible=\\"not show_details_visible or has_tracking not in ['lot', 'serial']\\"/>\\n                                    <button class=\\"o_optional_button btn\\" name=\\"action_show_details\\" type=\\"object\\" string=\\"Details\\" context=\\"{'default_product_uom_qty': 0}\\" invisible=\\"(has_tracking in ['lot', 'serial']) or not show_details_visible\\"/>\\n                                </list>\\n                            </field>\\n                        </page>\\n                        <page string=\\"Work Orders\\" name=\\"operations\\" groups=\\"mrp.group_mrp_routings\\">\\n                            <field name=\\"workorder_ids\\" context=\\"{'list_view_ref': 'mrp.mrp_production_workorder_tree_editable_view_mo_form', 'from_manufacturing_order': True}\\" create=\\"id != False and state != 'done'\\"/>\\n                        </page>\\n                        <page string=\\"By-Products\\" name=\\"finished_products\\" groups=\\"mrp.group_mrp_byproducts\\">\\n                            <field name=\\"move_byproduct_ids\\" context=\\"{'default_date': date_finished, 'default_date_deadline': date_deadline, 'default_warehouse_id': warehouse_id, 'default_location_id': production_location_id, 'default_location_dest_id': location_dest_id, 'default_state': 'draft', 'default_production_id': id, 'default_picking_type_id': picking_type_id, 'default_company_id': company_id, 'form_view_ref': 'mrp.view_mrp_stock_move_operations'}\\" readonly=\\"state in ('done', 'cancel')\\">\\n                                <list default_order=\\"sequence, id\\" decoration-muted=\\"state in ['done', 'cancel']\\" editable=\\"bottom\\">\\n                                    <control>\\n                                        <create string=\\"Add a line\\"/>\\n                                        <button name=\\"action_add_from_catalog_byproduct\\" string=\\"Catalog\\" type=\\"object\\" class=\\"px-4 btn-link\\" context=\\"{'order_id': parent.id}\\"/>\\n                                    </control>\\n                                    <field name=\\"sequence\\" widget=\\"handle\\"/>\\n                                    <field name=\\"product_id\\" context=\\"{'default_is_storable': True}\\" domain=\\"[('type', '=', 'consu')]\\" required=\\"1\\" readonly=\\"move_lines_count &gt; 0 or state == 'cancel' or (state != 'draft' and not additional)\\"/>\\n                                    <field name=\\"location_dest_id\\" string=\\"To\\" readonly=\\"1\\" force_save=\\"1\\" groups=\\"stock.group_stock_multi_locations\\"/>\\n                                    <field name=\\"company_id\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"allowed_operation_ids\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"unit_factor\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"date\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"date_deadline\\" column_invisible=\\"True\\" force_save=\\"1\\"/>\\n                                    <field name=\\"additional\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"picking_type_id\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"has_tracking\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"operation_id\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"bom_line_id\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"byproduct_id\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"sequence\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"location_id\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"warehouse_id\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"is_locked\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"move_lines_count\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"state\\" column_invisible=\\"True\\" force_save=\\"1\\"/>\\n                                    <field name=\\"product_uom_qty\\" string=\\"To Produce\\" force_save=\\"1\\" readonly=\\"parent.state != 'draft' and ((parent.state not in ('confirmed', 'progress', 'to_close') and not parent.is_planned) or parent.is_locked)\\"/>\\n                                    <field name=\\"quantity\\" column_invisible=\\"parent.state == 'draft'\\" readonly=\\"has_tracking in ['lot', 'serial']\\"/>\\n                                    <field name=\\"picked\\" string=\\"Produced\\" column_invisible=\\"parent.state == 'draft'\\" optional=\\"show\\"/>\\n                                    <field name=\\"uom_id\\" groups=\\"uom.group_uom\\" widget=\\"many2one_uom\\"/>\\n                                    <field name=\\"cost_share\\" optional=\\"hide\\"/>\\n                                    <field name=\\"show_details_visible\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"lot_ids\\" widget=\\"many2many_tags\\" optional=\\"hide\\" string=\\"Lot/Serial Numbers\\" help=\\"Displays the produced Lot/Serial Numbers.\\" groups=\\"stock.group_production_lot\\" readonly=\\"1\\" column_invisible=\\"not parent.show_lot_ids or parent.state == 'draft'\\" invisible=\\"not show_details_visible\\" create=\\"parent.use_create_components_lots\\" context=\\"{'default_product_id': product_id}\\" domain=\\"[('product_id','=',product_id)]\\"/>\\n                                    <button name=\\"action_show_details\\" type=\\"object\\" title=\\"Show Details\\" icon=\\"format_list_bulleted\\" invisible=\\"has_tracking not in ['lot', 'serial'] or not show_details_visible\\"/>\\n                                    <button class=\\"o_optional_button btn btn-light\\" name=\\"action_show_details\\" type=\\"object\\" title=\\"Show Details\\" icon=\\"format_list_bulleted\\" invisible=\\"has_tracking in ['lot', 'serial'] or not show_details_visible\\"/>\\n                                </list>\\n                            </field>\\n                        </page>\\n                        <page string=\\"Miscellaneous\\" name=\\"miscellaneous\\">\\n                            <group>\\n                                <group>\\n                                    <field name=\\"picking_type_id\\" options=\\"{'no_quick_create': True}\\" readonly=\\"state not in ('draft', 'confirmed')\\"/>\\n                                    <field name=\\"location_src_id\\" groups=\\"stock.group_stock_multi_locations\\" options=\\"{'no_create': True}\\" readonly=\\"state != 'draft'\\"/>\\n                                    <field name=\\"location_src_id\\" groups=\\"!stock.group_stock_multi_locations\\" invisible=\\"1\\"/>\\n                                    <field name=\\"warehouse_id\\" invisible=\\"1\\"/>\\n                                    <field name=\\"location_dest_id\\" groups=\\"stock.group_stock_multi_locations\\" options=\\"{'no_create': True}\\" readonly=\\"state != 'draft'\\"/>\\n                                    <field name=\\"location_dest_id\\" groups=\\"!stock.group_stock_multi_locations\\" invisible=\\"1\\"/>\\n                                </group>\\n                                <group>\\n                                    <field name=\\"origin\\" readonly=\\"state in ['cancel', 'done']\\"/>\\n                                    <field name=\\"date_deadline\\"/>\\n                                    <field name=\\"is_delayed\\" invisible=\\"True\\"/>\\n                                    <field name=\\"company_id\\" groups=\\"base.group_multi_company\\" options=\\"{'no_create': True}\\" readonly=\\"state != 'draft'\\" force_save=\\"1\\"/>\\n                                    <field name=\\"note\\" readonly=\\"False\\"/>\\n                                </group>\\n                            </group>\\n                        </page>\\n                    </notebook>\\n                </sheet>\\n                <chatter/>\\n                </form>", "es_ES": "<form string=\\"Órdenes de fabricación\\">\\n                <header>\\n                    <field name=\\"show_lock\\" invisible=\\"1\\"/>\\n                    <button name=\\"button_mark_done\\" type=\\"object\\" string=\\"Producir\\" class=\\"oe_highlight\\" data-hotkey=\\"g\\" invisible=\\"not move_raw_ids or validate_button_style != 'primary'\\"/>\\n                    <button name=\\"button_mark_done\\" type=\\"object\\" string=\\"Producir\\" class=\\"btn-secondary\\" data-hotkey=\\"g\\" invisible=\\"not move_raw_ids or validate_button_style != 'secondary'\\"/>\\n                    <button name=\\"button_mark_done\\" type=\\"object\\" string=\\"Producir\\" class=\\"oe_highlight\\" data-hotkey=\\"g\\" invisible=\\"move_raw_ids or validate_button_style != 'primary'\\" confirm=\\"No hay componentes a consumir. ¿Está seguro de que desea continuar?\\"/>\\n                    <button name=\\"button_mark_done\\" type=\\"object\\" string=\\"Producir\\" class=\\"btn-secondary\\" data-hotkey=\\"g\\" invisible=\\"move_raw_ids or validate_button_style != 'secondary'\\" confirm=\\"No hay componentes a consumir. ¿Está seguro de que desea continuar?\\"/>\\n                    <button name=\\"action_confirm\\" invisible=\\"state != 'draft'\\" string=\\"Confirmar\\" type=\\"object\\" class=\\"oe_highlight\\" data-hotkey=\\"q\\"/>\\n                    <button name=\\"button_plan\\" type=\\"object\\" string=\\"Planificar\\" class=\\"oe_highlight\\" invisible=\\"state in ('cancel', 'done') or is_planned or not workorder_ids\\" groups=\\"mrp.group_mrp_routings\\" data-hotkey=\\"z\\"/>\\n                    <button name=\\"button_unplan\\" type=\\"object\\" string=\\"Anular planificación\\" invisible=\\"not is_planned or state in ['cancel', 'done']\\" groups=\\"mrp.group_mrp_routings\\" data-hotkey=\\"z\\"/>\\n                    <button name=\\"action_start\\" type=\\"object\\" string=\\"Iniciar\\" invisible=\\"state != 'confirmed'\\"/>\\n                    <field name=\\"state\\" widget=\\"statusbar\\" statusbar_visible=\\"draft,confirmed,progress,done\\" invisible=\\"workorder_ids\\"/>\\n                    <field name=\\"state\\" widget=\\"statusbar\\" statusbar_visible=\\"draft,confirmed,progress,to_close,done\\" invisible=\\"not workorder_ids\\" groups=\\"mrp.group_mrp_routings\\"/>\\n                    <button name=\\"action_cancel\\" type=\\"object\\" string=\\"Cancelar\\" data-hotkey=\\"x\\" invisible=\\"not id or state in ('done', 'cancel')\\" confirm=\\"Are you sure you want to cancel this manufacturing order?&#10;This action cannot be undone.\\" confirm-title=\\"Cancel Manufacturing Order\\" confirm-label=\\"Cancel this Order\\"/>\\n                    <button name=\\"action_reset_to_draft\\" type=\\"object\\" string=\\"Reset to Draft\\" invisible=\\"state != 'cancel'\\" groups=\\"mrp.group_mrp_manager\\"/>\\n                    <button name=\\"action_reset_to_progress\\" type=\\"object\\" string=\\"Set to In Progress\\" invisible=\\"state != 'done'\\" groups=\\"mrp.group_mrp_manager\\"/>\\n                </header>\\n                <sheet>\\n                    <field name=\\"reservation_state\\" invisible=\\"1\\"/>\\n                    <field name=\\"is_locked\\" invisible=\\"1\\"/>\\n                    <field name=\\"qty_produced\\" invisible=\\"1\\"/>\\n                    <field name=\\"unreserve_visible\\" invisible=\\"1\\"/>\\n                    <field name=\\"reserve_visible\\" invisible=\\"1\\"/>\\n                    <field name=\\"is_planned\\" invisible=\\"1\\"/>\\n                    <field name=\\"show_allocation\\" invisible=\\"1\\"/>\\n                    <field name=\\"workorder_ids\\" invisible=\\"1\\"/>\\n                    <div class=\\"oe_button_box\\" name=\\"button_box\\">\\n                        <button name=\\"action_view_allocation_report\\" string=\\"Asignación\\" type=\\"object\\" class=\\"oe_stat_button\\" icon=\\"format_list_bulleted\\" invisible=\\"not show_allocation\\"/>\\n                        <button class=\\"oe_stat_button\\" name=\\"action_view_mrp_production_all_childs\\" type=\\"object\\" icon=\\"build\\" invisible=\\"mrp_production_all_child_count == 0\\">\\n                            <div class=\\"o_field_widget o_stat_info\\">\\n                                <span class=\\"o_stat_value\\"><field name=\\"mrp_production_all_child_count\\"/></span>\\n                                <span class=\\"o_stat_text\\">Orden de fabricación hija</span>\\n                            </div>\\n                        </button>\\n                        <button class=\\"oe_stat_button\\" name=\\"action_view_mrp_production_sources\\" type=\\"object\\" icon=\\"build\\" invisible=\\"mrp_production_source_count == 0\\">\\n                            <div class=\\"o_field_widget o_stat_info\\">\\n                                <span class=\\"o_stat_value\\"><field name=\\"mrp_production_source_count\\"/></span>\\n                                <span class=\\"o_stat_text\\">Orden de fabricación de origen</span>\\n                            </div>\\n                        </button>\\n                        <button class=\\"oe_stat_button\\" name=\\"action_view_mrp_production_backorders\\" type=\\"object\\" icon=\\"build\\" invisible=\\"mrp_production_backorder_count &lt; 2\\">\\n                            <div class=\\"o_field_widget o_stat_info\\">\\n                                <span class=\\"o_stat_value\\"><field name=\\"mrp_production_backorder_count\\"/></span>\\n                                <span class=\\"o_stat_text\\">Entregas parciales</span>\\n                            </div>\\n                        </button>\\n                        <button class=\\"oe_stat_button\\" name=\\"action_view_mrp_production_unbuilds\\" type=\\"object\\" icon=\\"undo\\" invisible=\\"unbuild_count == 0\\">\\n                            <div class=\\"o_field_widget o_stat_info\\">\\n                                <span class=\\"o_stat_value\\"><field name=\\"unbuild_count\\"/></span>\\n                                <span class=\\"o_stat_text\\">Desmontajes</span>\\n                            </div>\\n                        </button>\\n                        <button class=\\"oe_stat_button\\" name=\\"action_see_move_scrap\\" type=\\"object\\" icon=\\"height\\" invisible=\\"scrap_count == 0\\">\\n                            <div class=\\"o_field_widget o_stat_info\\">\\n                                <span class=\\"o_stat_value\\"><field name=\\"scrap_count\\"/></span>\\n                                <span class=\\"o_stat_text\\">Desechos</span>\\n                            </div>\\n                        </button>\\n                        <button type=\\"object\\" name=\\"action_view_mo_delivery\\" class=\\"oe_stat_button\\" icon=\\"local_shipping\\" groups=\\"base.group_user\\" invisible=\\"delivery_count == 0\\">\\n                            <field name=\\"delivery_count\\" widget=\\"statinfo\\" string=\\"Traslados\\"/>\\n                        </button>\\n                        <button name=\\"676\\" type=\\"action\\" class=\\"oe_stat_button\\" icon=\\"menu\\">\\n                            <div class=\\"o_stat_info\\">\\n                                <span class=\\"o_stat_text\\">Vista general</span>\\n                            </div>\\n                        </button>\\n                        <button name=\\"647\\" type=\\"action\\" class=\\"oe_stat_button\\" icon=\\"sync_alt\\" invisible=\\"state != 'done'\\">\\n                            <div class=\\"o_stat_info\\">\\n                                <span class=\\"o_stat_text\\">Movimientos de producto</span>\\n                            </div>\\n                        </button>\\n                        <button name=\\"534\\" icon=\\"north\\" class=\\"oe_stat_button\\" string=\\"Trazabilidad\\" type=\\"action\\" invisible=\\"state != 'done'\\" groups=\\"stock.group_production_lot\\">\\n                            <div class=\\"o_stat_info\\">\\n                                <span class=\\"o_stat_text\\">Trazabilidad</span>\\n                            </div>\\n                        </button>\\n                        <button name=\\"action_detailed_operations\\" class=\\"oe_stat_button\\" icon=\\"menu\\" type=\\"object\\" groups=\\"stock.group_tracking_lot\\" help=\\"List view of detailed operations\\">\\n                            <div class=\\"o_form_field o_stat_info\\">\\n                                <span class=\\"o_stat_text\\">Moves</span>\\n                            </div>\\n                        </button>\\n                        <button name=\\"action_view_packages\\" string=\\"Packages\\" type=\\"object\\" class=\\"oe_stat_button\\" icon=\\"package_2\\" invisible=\\"not packages_count\\" groups=\\"stock.group_tracking_lot\\">\\n                            <div class=\\"o_stat_info\\">\\n                                <span class=\\"o_stat_text\\">Packages</span>\\n                            </div>\\n                        </button>\\n                        <button class=\\"oe_stat_button\\" name=\\"action_view_serial_numbers\\" type=\\"object\\" icon=\\"build\\" invisible=\\"serial_numbers_count == 0 or state == 'draft'\\">\\n                            <div class=\\"o_field_widget o_stat_info\\">\\n                                <span class=\\"o_stat_value\\"><field name=\\"serial_numbers_count\\"/></span>\\n                                <span class=\\"o_stat_text\\">Números de serie</span>\\n                            </div>\\n                        </button>\\n                    </div>\\n                    <div class=\\"oe_title\\">\\n                        <h1 class=\\"o_outlined d-flex align-items-center gap-2\\">\\n                            <field name=\\"priority\\" widget=\\"priority\\"/>\\n                            <field name=\\"name\\" placeholder=\\"Referencia de fabricación\\"/>\\n                        </h1>\\n                    </div>\\n                    <group>\\n                        <group>\\n                            <field name=\\"id\\" invisible=\\"1\\"/>\\n                            <field name=\\"use_create_components_lots\\" invisible=\\"1\\"/>\\n                            <field name=\\"show_lot_ids\\" invisible=\\"1\\"/>\\n                            <field name=\\"product_tracking\\" invisible=\\"1\\"/>\\n                            <field name=\\"allow_workorder_dependencies\\" invisible=\\"1\\"/>\\n                            <field name=\\"product_id\\" context=\\"{'default_is_storable': True}\\" readonly=\\"state != 'draft'\\" default_focus=\\"1\\" placeholder=\\"Producto a construir...\\"/>\\n                            <field name=\\"product_tmpl_id\\" invisible=\\"1\\"/>\\n                            <field name=\\"forecasted_issue\\" invisible=\\"1\\"/>\\n                            <field name=\\"company_id\\" invisible=\\"1\\"/>\\n                            <field name=\\"product_description_variants\\" invisible=\\"product_description_variants in (False, '')\\" readonly=\\"state != 'draft'\\"/>\\n                            <label for=\\"bom_id\\" name=\\"bom_label\\"/>\\n                            <div class=\\"o_row\\" name=\\"bom_div\\">\\n                                <field name=\\"is_outdated_bom\\" invisible=\\"1\\"/>\\n                                <field name=\\"bom_id\\" context=\\"{'default_product_tmpl_id': product_tmpl_id}\\" invisible=\\"state != 'draft' and not bom_id\\" readonly=\\"state != 'draft'\\"/>\\n                                <button name=\\"action_generate_bom\\" type=\\"object\\" icon=\\"add\\" title=\\"Generar una nueva LdM desde esta orden de fabricación\\" groups=\\"mrp.group_mrp_manager\\" invisible=\\"not show_generate_bom\\">\\n                                    <span>Generar lista de materiales</span>\\n                                </button>\\n                                <button name=\\"action_update_bom\\" string=\\"Actualizar LdM\\" type=\\"object\\" title=\\"Tenga en cuenta que está disponible otra versión de esta LdM.\\" class=\\"text-danger\\" invisible=\\"not is_outdated_bom or state not in ['draft', 'confirmed', 'progress', 'to_close']\\"/>\\n                            </div>\\n                            <label for=\\"product_qty\\" string=\\"Cantidad\\" class=\\"d-touch-none\\"/>\\n                            <div class=\\"o_row g-0 d-flex\\" name=\\"qty\\">\\n                                <div invisible=\\"state == 'draft'\\" class=\\"o_row flex-grow-1\\">\\n                                    <label for=\\"qty_producing\\" string=\\"Cantidad\\" class=\\"d-none d-touch-block\\"/>\\n                                    <field name=\\"qty_producing\\" widget=\\"external_placeholder_float_field\\" placeholder=\\"product_qty\\" class=\\"text-start text-truncate\\" readonly=\\"state in ('done', 'cancel') or product_tracking=='serial'\\" force_save=\\"1\\"/>\\n                                    /\\n                                </div>\\n                                <field name=\\"product_qty\\" class=\\"oe_inline text-start text-truncate\\" invisible=\\"state not in ('draft', 'done')\\" readonly=\\"state != 'draft'\\" style=\\"width:auto!important\\"/>\\n                                <button type=\\"action\\" name=\\"639\\" context=\\"{'default_mo_id': id}\\" class=\\"oe_link oe_inline\\" style=\\"margin: 0px; padding: 0px;\\" invisible=\\"state in ('draft', 'done', 'cancel') or not id\\">\\n                                    <field name=\\"product_qty\\" class=\\"oe_inline\\" readonly=\\"state != 'draft'\\"/>\\n                                </button>\\n                                <label for=\\"uom_id\\" string=\\"\\" class=\\"oe_inline\\"/>\\n                                <field name=\\"uom_id\\" options=\\"{'no_open': True, 'no_create': True, 'quantity_field': 'product_qty'}\\" groups=\\"uom.group_uom\\" widget=\\"many2one_uom\\" readonly=\\"state != 'draft'\\" class=\\"flex-grow-0\\" style=\\"width:auto!important\\"/>\\n                                <span name=\\"to_produce\\" class=\\"fw-bold text-nowrap\\">Por producir</span>\\n                                <button type=\\"object\\" name=\\"action_product_forecast_report\\" title=\\"Informe de pronóstico\\" icon=\\"area_chart\\" invisible=\\"forecasted_issue\\"/>\\n                                <button type=\\"object\\" name=\\"action_product_forecast_report\\" title=\\"Informe de pronóstico\\" icon=\\"area_chart\\" invisible=\\"not forecasted_issue\\" class=\\"text-danger\\"/>\\n                            </div>\\n                            <label for=\\"lot_producing_ids\\" invisible=\\"state in ('draft', 'cancel') or not product_tracking or (state == 'done' and product_tracking == 'serial' and product_qty &gt; 1)\\"/>\\n                            <div class=\\"o_row\\" invisible=\\"state in ('draft', 'cancel') or not product_tracking or (state == 'done' and product_tracking == 'serial' and product_qty &gt; 1)\\">\\n                                <field name=\\"lot_producing_ids\\" widget=\\"many2many_tags\\" options=\\"{'on_tag_click': 'open_form'}\\" invisible=\\"not product_tracking or (product_tracking == 'serial' and (product_qty &gt; 1 or serial_numbers_count &gt; 1))\\" readonly=\\"lot_producing_ids\\" force_save=\\"1\\" context=\\"{'default_product_id': product_id}\\"/>\\n                                <button name=\\"action_generate_serial\\" type=\\"object\\" class=\\"btn btn-primary o_right_alignment\\" string=\\"Generar números de serie\\" aria-label=\\"Creates new serial numbers\\" role=\\"img\\" invisible=\\"product_tracking != 'serial' or lot_producing_ids\\"/>\\n                                <button name=\\"action_generate_serial\\" type=\\"object\\" class=\\"btn btn-secondary o_right_alignment\\" string=\\"Edit Serial Numbers\\" aria-label=\\"Edit generated serial numbers\\" role=\\"img\\" invisible=\\"state == 'done' or product_tracking != 'serial' or not lot_producing_ids or (serial_numbers_count &lt;= 1 and product_qty &lt;= 1)\\"/>\\n                                <button name=\\"action_generate_serial\\" type=\\"object\\" class=\\"btn btn-primary o_right_alignment\\" string=\\"Generate Lot Number\\" aria-label=\\"Crea un nuevo número de lote\\" role=\\"img\\" invisible=\\"product_tracking != 'lot' or lot_producing_ids\\"/>\\n                                <button name=\\"action_clear_lot_producing_ids\\" type=\\"object\\" class=\\"btn btn-secondary o_right_alignment\\" string=\\"Limpiar\\" aria-label=\\"Borra el lote/número de serie seleccionado\\" role=\\"img\\" invisible=\\"state == 'done' or (product_tracking == 'serial' and (product_qty &gt; 1 or serial_numbers_count &gt; 1)) or not lot_producing_ids\\"/>\\n                            </div>\\n                        </group>\\n                        <group name=\\"group_extra_info\\">\\n                            <label name=\\"scheduled_date\\" for=\\"date_start\\" string=\\"Fecha programada\\" invisible=\\"state in ['progress', 'to_close', 'done', 'cancel']\\"/>\\n                            <label name=\\"start_date\\" for=\\"date_start\\" string=\\"Fecha de inicio\\" invisible=\\"state not in ['progress', 'to_close', 'done', 'cancel']\\"/>\\n                            <div class=\\"o_row\\" name=\\"date_start\\">\\n                                <field name=\\"date_start\\" readonly=\\"state in ['done', 'to_close', 'cancel']\\" decoration-warning=\\"state not in ('done', 'cancel') and date_start &lt; now\\" decoration-danger=\\"state not in ('done', 'cancel') and date_deadline and date_deadline &lt; date_finished\\" help=\\"Fecha en la que planifica empezar.                                           Aparecerá en rojo si el fin programado se pronostica después de la fecha límite de la orden de producción.                                           Aparecerá en naranja si la fecha programada es en el pasado.\\"/>\\n                                <field name=\\"delay_alert_date\\" invisible=\\"1\\"/>\\n                                <field nolabel=\\"1\\" name=\\"json_popover\\" widget=\\"stock_rescheduling_popover\\" invisible=\\"not json_popover\\"/>\\n                            </div>\\n                            <field name=\\"date_finished\\" string=\\"Fecha de finalización\\" readonly=\\"is_locked\\" invisible=\\"state != 'done'\\" help=\\"Date at which you finished production.\\"/>\\n                            <field name=\\"components_availability_state\\" invisible=\\"1\\"/>\\n                            <field name=\\"components_availability\\" invisible=\\"state not in ['confirmed', 'progress']\\" decoration-success=\\"reservation_state == 'assigned' or components_availability_state == 'available'\\" decoration-warning=\\"reservation_state != 'assigned' and components_availability_state in ('expected', 'available')\\" decoration-danger=\\"reservation_state != 'assigned' and components_availability_state in ('late', 'unavailable')\\"/>\\n                            <field name=\\"user_id\\" widget=\\"many2one_avatar\\" readonly=\\"state in ['cancel', 'done']\\"/>\\n                            <field name=\\"show_final_lots\\" invisible=\\"1\\"/>\\n                            <field name=\\"production_location_id\\" invisible=\\"1\\" readonly=\\"1\\"/>\\n                            <field name=\\"move_finished_ids\\" invisible=\\"1\\" readonly=\\"state == 'cancel' or (state == 'done' and is_locked)\\">\\n                                <list editable=\\"bottom\\">\\n                                    <field name=\\"product_id\\" readonly=\\"state == 'done'\\"/>\\n                                    <field name=\\"product_uom_qty\\" readonly=\\"state == 'done'\\"/>\\n                                    <field name=\\"uom_id\\" groups=\\"uom.group_uom\\" widget=\\"many2one_uom\\"/>\\n                                    <field name=\\"operation_id\\"/>\\n                                    <field name=\\"byproduct_id\\"/>\\n                                    <field name=\\"date_deadline\\"/>\\n                                    <field name=\\"picking_type_id\\"/>\\n                                    <field name=\\"location_id\\"/>\\n                                    <field name=\\"location_dest_id\\"/>\\n                                    <field name=\\"company_id\\"/>\\n                                    <field name=\\"warehouse_id\\"/>\\n                                    <field name=\\"origin\\"/>\\n                                    <field name=\\"propagate_cancel\\"/>\\n                                    <field name=\\"move_dest_ids\\"/>\\n                                    <field name=\\"state\\"/>\\n                                    <!-- Useless as the editable in tree declaration -> For Form Test-->\\n                                    <field name=\\"allowed_operation_ids\\"/>\\n                                    <!--\\n                                    Required for test_00_mrp_byproduct\\n                                    when changing the mrp.production product_qty\\n                                    `_onchange_producing` is called,\\n                                    calling `_set_qty_producing`,\\n                                    which changes the `quantity_done` of byproducts\\n                                    If byproducts are not in the view (`groups=\\"mrp.group_mrp_byproducts\\"`)\\n                                    and `quantity_done` is not within the finished move views,\\n                                    (byproduct moves are a subset of finished moves)\\n                                    the `quantity_done` of byproducts is not updated correctly with the onchange\\n                                    Another solution is to add `self.env.user.group_ids += self.env.ref('mrp.group_mrp_byproducts')`\\n                                    to the test `test_00_mrp_byproduct`, which could makes sense as it's a test testing the byproducts features,\\n                                    for which you should have the byproducts group to have access to,\\n                                    but it seemed better to keep the feature working even if you do not see the byproducts features with your user.\\n                                    That being said, the best would be to have the byproducts feature working without relying on anything in the view,\\n                                    e.g. so the byproducts feature works with xmlrpc calls.\\n                                    -->\\n                                    <field name=\\"quantity\\"/>\\n                                    <field name=\\"picked\\"/>\\n                                    <!-- Required for test_fifo_byproduct -->\\n                                    <field name=\\"cost_share\\"/>\\n                                </list>\\n                            </field>\\n                        </group>\\n                    </group>\\n                    <notebook>\\n                        <page string=\\"Componentes\\" name=\\"components\\">\\n                            <field name=\\"move_raw_ids\\" mode=\\"list,kanban\\" context=\\"{'default_date': date_start, 'default_date_deadline': date_start, 'default_location_id': location_src_id, 'default_location_dest_id': production_location_id, 'default_warehouse_id': warehouse_id, 'default_state': 'draft', 'default_raw_material_production_id': id, 'default_picking_type_id': picking_type_id, 'default_company_id': company_id, 'form_view_ref': 'mrp.view_mrp_stock_move_operations', 'active_mo_id': id}\\" readonly=\\"state in ('done', 'cancel')\\">\\n                                <list editable=\\"bottom\\">\\n                                    <control>\\n                                        <create string=\\"Añadir una línea\\"/>\\n                                        <button name=\\"action_add_from_catalog_raw\\" string=\\"Catálogo\\" type=\\"object\\" class=\\"px-4 btn-link\\" context=\\"{'order_id': parent.id}\\"/>\\n                                    </control>\\n                                    <field name=\\"sequence\\" widget=\\"handle\\"/>\\n                                    <field name=\\"product_id\\" force_save=\\"1\\" context=\\"{'default_is_storable': True}\\" required=\\"1\\" readonly=\\"move_lines_count &gt; 0 or state == 'cancel' or (state != 'draft' and not additional)\\" domain=\\"[('type', '=', 'consu')]\\"/>\\n                                    <field name=\\"forecast_availability\\" column_invisible=\\"parent.state in ['done', 'cancel']\\" string=\\"\\" widget=\\"forecast_widget\\"/>\\n                                    <field name=\\"location_id\\" string=\\"Desde\\" readonly=\\"1\\" force_save=\\"1\\" groups=\\"stock.group_stock_multi_locations\\" optional=\\"hide\\"/>\\n                                    <!-- test_immediate_validate_uom_2, test_product_produce_different_uom -->\\n                                    <field name=\\"uom_id\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"propagate_cancel\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"price_unit\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"company_id\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"allowed_operation_ids\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"unit_factor\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"date_deadline\\" column_invisible=\\"True\\" force_save=\\"1\\"/>\\n                                    <field name=\\"date\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"additional\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"picking_type_id\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"is_storable\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"has_tracking\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"operation_id\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"bom_line_id\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"sequence\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"warehouse_id\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"is_locked\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"move_lines_count\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"location_dest_id\\" domain=\\"[('id', 'child_of', parent.location_dest_id)]\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"state\\" column_invisible=\\"True\\" force_save=\\"1\\"/>\\n                                    <field name=\\"should_consume_qty\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"product_uom_qty\\" widget=\\"mrp_should_consume\\" force_save=\\"1\\" string=\\"A consumir\\" column_invisible=\\"parent.qty_producing in (0, parent.product_qty)\\" readonly=\\"parent.state != 'draft'                                                      and ((parent.state not in ('confirmed', 'progress', 'to_close') and not parent.is_planned)                                                           or (parent.is_locked and state != 'draft'))\\"/>\\n                                    <field name=\\"product_uom_qty\\" force_save=\\"1\\" string=\\"A consumir\\" column_invisible=\\"parent.qty_producing not in (0, parent.product_qty)\\" readonly=\\"parent.state != 'draft'                                                      and ((parent.state not in ('confirmed', 'progress', 'to_close') and not parent.is_planned)                                                           or (parent.is_locked and state != 'draft'))\\"/>\\n                                    <field name=\\"product_qty\\" readonly=\\"1\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"forecast_expected_date\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"quantity\\" string=\\"La cantidad consumida\\" decoration-success=\\"(state not in ['done', 'cancel']) and (quantity - (should_consume_qty if parent.qty_producing else product_uom_qty) == 0)\\" decoration-danger=\\"(state not in ['done', 'cancel']) and (quantity - (should_consume_qty if parent.qty_producing else product_uom_qty) &gt; 0)\\" decoration-warning=\\"(state not in ['done', 'cancel']) and (quantity - (should_consume_qty if parent.qty_producing else product_uom_qty) &lt; 0)\\" column_invisible=\\"parent.state == 'draft'\\" force_save=\\"1\\"/>\\n                                    <field name=\\"uom_id\\" readonly=\\"state != 'draft' and id\\" options=\\"{'no_open': True, 'no_create': True}\\" groups=\\"uom.group_uom\\" widget=\\"many2one_uom\\"/>\\n                                    <field name=\\"picked\\" optional=\\"hide\\"/>\\n                                    <field name=\\"show_details_visible\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"lot_ids\\" widget=\\"many2many_tags\\" optional=\\"hide\\" string=\\"Números de lote/serie\\" help=\\"Muestra los números de lote/serie consumidos.\\" groups=\\"stock.group_production_lot\\" readonly=\\"1\\" column_invisible=\\"not parent.show_lot_ids or parent.state == 'draft'\\" invisible=\\"not show_details_visible\\" create=\\"parent.use_create_components_lots\\" context=\\"{'default_product_id': product_id}\\" domain=\\"[('product_id','=',product_id)]\\"/>\\n                                    <button name=\\"action_show_details\\" type=\\"object\\" string=\\"Detalles\\" context=\\"{'default_product_uom_qty': 0}\\" invisible=\\"not show_details_visible or has_tracking not in ['lot', 'serial']\\"/>\\n                                    <button class=\\"o_optional_button btn\\" name=\\"action_show_details\\" type=\\"object\\" string=\\"Detalles\\" context=\\"{'default_product_uom_qty': 0}\\" invisible=\\"(has_tracking in ['lot', 'serial']) or not show_details_visible\\"/>\\n                                </list>\\n                            </field>\\n                        </page>\\n                        <page string=\\"Órdenes de trabajo\\" name=\\"operations\\" groups=\\"mrp.group_mrp_routings\\">\\n                            <field name=\\"workorder_ids\\" context=\\"{'list_view_ref': 'mrp.mrp_production_workorder_tree_editable_view_mo_form', 'from_manufacturing_order': True}\\" create=\\"id != False and state != 'done'\\"/>\\n                        </page>\\n                        <page string=\\"Subproductos\\" name=\\"finished_products\\" groups=\\"mrp.group_mrp_byproducts\\">\\n                            <field name=\\"move_byproduct_ids\\" context=\\"{'default_date': date_finished, 'default_date_deadline': date_deadline, 'default_warehouse_id': warehouse_id, 'default_location_id': production_location_id, 'default_location_dest_id': location_dest_id, 'default_state': 'draft', 'default_production_id': id, 'default_picking_type_id': picking_type_id, 'default_company_id': company_id, 'form_view_ref': 'mrp.view_mrp_stock_move_operations'}\\" readonly=\\"state in ('done', 'cancel')\\">\\n                                <list default_order=\\"sequence, id\\" decoration-muted=\\"state in ['done', 'cancel']\\" editable=\\"bottom\\">\\n                                    <control>\\n                                        <create string=\\"Añadir una línea\\"/>\\n                                        <button name=\\"action_add_from_catalog_byproduct\\" string=\\"Catálogo\\" type=\\"object\\" class=\\"px-4 btn-link\\" context=\\"{'order_id': parent.id}\\"/>\\n                                    </control>\\n                                    <field name=\\"sequence\\" widget=\\"handle\\"/>\\n                                    <field name=\\"product_id\\" context=\\"{'default_is_storable': True}\\" domain=\\"[('type', '=', 'consu')]\\" required=\\"1\\" readonly=\\"move_lines_count &gt; 0 or state == 'cancel' or (state != 'draft' and not additional)\\"/>\\n                                    <field name=\\"location_dest_id\\" string=\\"A\\" readonly=\\"1\\" force_save=\\"1\\" groups=\\"stock.group_stock_multi_locations\\"/>\\n                                    <field name=\\"company_id\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"allowed_operation_ids\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"unit_factor\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"date\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"date_deadline\\" column_invisible=\\"True\\" force_save=\\"1\\"/>\\n                                    <field name=\\"additional\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"picking_type_id\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"has_tracking\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"operation_id\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"bom_line_id\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"byproduct_id\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"sequence\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"location_id\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"warehouse_id\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"is_locked\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"move_lines_count\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"state\\" column_invisible=\\"True\\" force_save=\\"1\\"/>\\n                                    <field name=\\"product_uom_qty\\" string=\\"A producir\\" force_save=\\"1\\" readonly=\\"parent.state != 'draft' and ((parent.state not in ('confirmed', 'progress', 'to_close') and not parent.is_planned) or parent.is_locked)\\"/>\\n                                    <field name=\\"quantity\\" column_invisible=\\"parent.state == 'draft'\\" readonly=\\"has_tracking in ['lot', 'serial']\\"/>\\n                                    <field name=\\"picked\\" string=\\"La cantidad producida\\" column_invisible=\\"parent.state == 'draft'\\" optional=\\"show\\"/>\\n                                    <field name=\\"uom_id\\" groups=\\"uom.group_uom\\" widget=\\"many2one_uom\\"/>\\n                                    <field name=\\"cost_share\\" optional=\\"hide\\"/>\\n                                    <field name=\\"show_details_visible\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"lot_ids\\" widget=\\"many2many_tags\\" optional=\\"hide\\" string=\\"Números de lote/serie\\" help=\\"Muestra los números de lote/serie producidos.\\" groups=\\"stock.group_production_lot\\" readonly=\\"1\\" column_invisible=\\"not parent.show_lot_ids or parent.state == 'draft'\\" invisible=\\"not show_details_visible\\" create=\\"parent.use_create_components_lots\\" context=\\"{'default_product_id': product_id}\\" domain=\\"[('product_id','=',product_id)]\\"/>\\n                                    <button name=\\"action_show_details\\" type=\\"object\\" title=\\"Mostrar detalles\\" icon=\\"format_list_bulleted\\" invisible=\\"has_tracking not in ['lot', 'serial'] or not show_details_visible\\"/>\\n                                    <button class=\\"o_optional_button btn btn-light\\" name=\\"action_show_details\\" type=\\"object\\" title=\\"Mostrar detalles\\" icon=\\"format_list_bulleted\\" invisible=\\"has_tracking in ['lot', 'serial'] or not show_details_visible\\"/>\\n                                </list>\\n                            </field>\\n                        </page>\\n                        <page string=\\"Varios\\" name=\\"miscellaneous\\">\\n                            <group>\\n                                <group>\\n                                    <field name=\\"picking_type_id\\" options=\\"{'no_quick_create': True}\\" readonly=\\"state not in ('draft', 'confirmed')\\"/>\\n                                    <field name=\\"location_src_id\\" groups=\\"stock.group_stock_multi_locations\\" options=\\"{'no_create': True}\\" readonly=\\"state != 'draft'\\"/>\\n                                    <field name=\\"location_src_id\\" groups=\\"!stock.group_stock_multi_locations\\" invisible=\\"1\\"/>\\n                                    <field name=\\"warehouse_id\\" invisible=\\"1\\"/>\\n                                    <field name=\\"location_dest_id\\" groups=\\"stock.group_stock_multi_locations\\" options=\\"{'no_create': True}\\" readonly=\\"state != 'draft'\\"/>\\n                                    <field name=\\"location_dest_id\\" groups=\\"!stock.group_stock_multi_locations\\" invisible=\\"1\\"/>\\n                                </group>\\n                                <group>\\n                                    <field name=\\"origin\\" readonly=\\"state in ['cancel', 'done']\\"/>\\n                                    <field name=\\"date_deadline\\"/>\\n                                    <field name=\\"is_delayed\\" invisible=\\"True\\"/>\\n                                    <field name=\\"company_id\\" groups=\\"base.group_multi_company\\" options=\\"{'no_create': True}\\" readonly=\\"state != 'draft'\\" force_save=\\"1\\"/>\\n                                    <field name=\\"note\\" readonly=\\"False\\"/>\\n                                </group>\\n                            </group>\\n                        </page>\\n                    </notebook>\\n                </sheet>\\n                <chatter/>\\n                </form>"}	<?xml version="1.0"?>\n<form string="Manufacturing Orders">\n                <header>\n                    <field name="show_lock" invisible="1"/>\n                    <button name="button_mark_done" type="object" string="Produce" class="oe_highlight" data-hotkey="g" invisible="not move_raw_ids or validate_button_style != 'primary'"/>\n                    <button name="button_mark_done" type="object" string="Produce" class="btn-secondary" data-hotkey="g" invisible="not move_raw_ids or validate_button_style != 'secondary'"/>\n                    <button name="button_mark_done" type="object" string="Produce" class="oe_highlight" data-hotkey="g" invisible="move_raw_ids or validate_button_style != 'primary'" confirm="There are no components to consume. Are you still sure you want to continue?"/>\n                    <button name="button_mark_done" type="object" string="Produce" class="btn-secondary" data-hotkey="g" invisible="move_raw_ids or validate_button_style != 'secondary'" confirm="There are no components to consume. Are you still sure you want to continue?"/>\n                    <button name="action_confirm" invisible="state != 'draft'" string="Confirm" type="object" class="oe_highlight" data-hotkey="q"/>\n                    <button name="button_plan" type="object" string="Plan" class="oe_highlight" invisible="state in ('cancel', 'done') or is_planned or not workorder_ids" groups="mrp.group_mrp_routings" data-hotkey="z"/>\n                    <button name="button_unplan" type="object" string="Unplan" invisible="not is_planned or state in ['cancel', 'done']" groups="mrp.group_mrp_routings" data-hotkey="z"/>\n                    <button name="action_start" type="object" string="Start" invisible="state != 'confirmed'"/>\n                    <field name="state" widget="statusbar" statusbar_visible="draft,confirmed,progress,done" invisible="workorder_ids"/>\n                    <field name="state" widget="statusbar" statusbar_visible="draft,confirmed,progress,to_close,done" invisible="not workorder_ids" groups="mrp.group_mrp_routings"/>\n                    <button name="action_cancel" type="object" string="Cancel" data-hotkey="x" invisible="not id or state in ('done', 'cancel')" confirm="Are you sure you want to cancel this manufacturing order?&#10;This action cannot be undone." confirm-title="Cancel Manufacturing Order" confirm-label="Cancel this Order"/>\n                    <button name="action_reset_to_draft" type="object" string="Reset to Draft" invisible="state != 'cancel'" groups="mrp.group_mrp_manager"/>\n                    <button name="action_reset_to_progress" type="object" string="Set to In Progress" invisible="state != 'done'" groups="mrp.group_mrp_manager"/>\n                </header>\n                <sheet>\n                    <field name="reservation_state" invisible="1"/>\n                    <field name="is_locked" invisible="1"/>\n                    <field name="qty_produced" invisible="1"/>\n                    <field name="unreserve_visible" invisible="1"/>\n                    <field name="reserve_visible" invisible="1"/>\n                    <field name="is_planned" invisible="1"/>\n                    <field name="show_allocation" invisible="1"/>\n                    <field name="workorder_ids" invisible="1"/>\n                    <div class="oe_button_box" name="button_box">\n                        <button name="action_view_allocation_report" string="Allocation" type="object" class="oe_stat_button" icon="format_list_bulleted" invisible="not show_allocation"/>\n                        <button class="oe_stat_button" name="action_view_mrp_production_all_childs" type="object" icon="build" invisible="mrp_production_all_child_count == 0">\n                            <div class="o_field_widget o_stat_info">\n                                <span class="o_stat_value"><field name="mrp_production_all_child_count"/></span>\n                                <span class="o_stat_text">Child MO</span>\n                            </div>\n                        </button>\n                        <button class="oe_stat_button" name="action_view_mrp_production_sources" type="object" icon="build" invisible="mrp_production_source_count == 0">\n                            <div class="o_field_widget o_stat_info">\n                                <span class="o_stat_value"><field name="mrp_production_source_count"/></span>\n                                <span class="o_stat_text">Source MO</span>\n                            </div>\n                        </button>\n                        <button class="oe_stat_button" name="action_view_mrp_production_backorders" type="object" icon="build" invisible="mrp_production_backorder_count &lt; 2">\n                            <div class="o_field_widget o_stat_info">\n                                <span class="o_stat_value"><field name="mrp_production_backorder_count"/></span>\n                                <span class="o_stat_text">Backorders</span>\n                            </div>\n                        </button>\n                        <button class="oe_stat_button" name="action_view_mrp_production_unbuilds" type="object" icon="undo" invisible="unbuild_count == 0">\n                            <div class="o_field_widget o_stat_info">\n                                <span class="o_stat_value"><field name="unbuild_count"/></span>\n                                <span class="o_stat_text">Unbuilds</span>\n                            </div>\n                        </button>\n                        <button class="oe_stat_button" name="action_see_move_scrap" type="object" icon="height" invisible="scrap_count == 0">\n                            <div class="o_field_widget o_stat_info">\n                                <span class="o_stat_value"><field name="scrap_count"/></span>\n                                <span class="o_stat_text">Scraps</span>\n                            </div>\n                        </button>\n                        <button type="object" name="action_view_mo_delivery" class="oe_stat_button" icon="local_shipping" groups="base.group_user" invisible="delivery_count == 0">\n                            <field name="delivery_count" widget="statinfo" string="Transfers"/>\n                        </button>\n                        <button name="676" type="action" class="oe_stat_button" icon="menu">\n                            <div class="o_stat_info">\n                                <span class="o_stat_text">Overview</span>\n                            </div>\n                        </button>\n                        <button name="647" type="action" class="oe_stat_button" icon="sync_alt" invisible="state != 'done'">\n                            <div class="o_stat_info">\n                                <span class="o_stat_text">Product Moves</span>\n                            </div>\n                        </button>\n                        <button name="534" icon="north" class="oe_stat_button" string="Traceability" type="action" invisible="state != 'done'" groups="stock.group_production_lot">\n                            <div class="o_stat_info">\n                                <span class="o_stat_text">Traceability</span>\n                            </div>\n                        </button>\n                        <button name="action_detailed_operations" class="oe_stat_button" icon="menu" type="object" groups="stock.group_tracking_lot" help="List view of detailed operations">\n                            <div class="o_form_field o_stat_info">\n                                <span class="o_stat_text">Moves</span>\n                            </div>\n                        </button>\n                        <button name="action_view_packages" string="Packages" type="object" class="oe_stat_button" icon="package_2" invisible="not packages_count" groups="stock.group_tracking_lot">\n                            <div class="o_stat_info">\n                                <span class="o_stat_text">Packages</span>\n                            </div>\n                        </button>\n                        <button class="oe_stat_button" name="action_view_serial_numbers" type="object" icon="build" invisible="serial_numbers_count == 0 or state == 'draft'">\n                            <div class="o_field_widget o_stat_info">\n                                <span class="o_stat_value"><field name="serial_numbers_count"/></span>\n                                <span class="o_stat_text">Serial Numbers</span>\n                            </div>\n                        </button>\n                    </div>\n                    <div class="oe_title">\n                        <h1 class="o_outlined d-flex align-items-center gap-2">\n                            <field name="priority" widget="priority"/>\n                            <field name="name" placeholder="Manufacturing Reference"/>\n                        </h1>\n                    </div>\n                    <group>\n                        <group>\n                            <field name="id" invisible="1"/>\n                            <field name="use_create_components_lots" invisible="1"/>\n                            <field name="show_lot_ids" invisible="1"/>\n                            <field name="product_tracking" invisible="1"/>\n                            <field name="allow_workorder_dependencies" invisible="1"/>\n                            <field name="product_id" context="{'default_is_storable': True}" readonly="state != 'draft'" default_focus="1" placeholder="Product to build..."/>\n                            <field name="product_tmpl_id" invisible="1"/>\n                            <field name="forecasted_issue" invisible="1"/>\n                            <field name="company_id" invisible="1"/>\n                            <field name="product_description_variants" invisible="product_description_variants in (False, '')" readonly="state != 'draft'"/>\n                            <label for="bom_id" name="bom_label"/>\n                            <div class="o_row" name="bom_div">\n                                <field name="is_outdated_bom" invisible="1"/>\n                                <field name="bom_id" context="{'default_product_tmpl_id': product_tmpl_id}" invisible="state != 'draft' and not bom_id" readonly="state != 'draft'"/>\n                                <button name="action_generate_bom" type="object" icon="add" title="Generate a new BoM from this Manufacturing Order" groups="mrp.group_mrp_manager" invisible="not show_generate_bom">\n                                    <span>Generate BOM</span>\n                                </button>\n                                <button name="action_update_bom" string="Update BoM" type="object" title="Note that another version of this BOM is available." class="text-danger" invisible="not is_outdated_bom or state not in ['draft', 'confirmed', 'progress', 'to_close']"/>\n                            </div>\n                            <label for="product_qty" string="Quantity" class="d-touch-none"/>\n                            <div class="o_row g-0 d-flex" name="qty">\n                                <div invisible="state == 'draft'" class="o_row flex-grow-1">\n                                    <label for="qty_producing" string="Quantity" class="d-none d-touch-block"/>\n                                    <field name="qty_producing" widget="external_placeholder_float_field" placeholder="product_qty" class="text-start text-truncate" readonly="state in ('done', 'cancel') or product_tracking=='serial'" force_save="1"/>\n                                    /\n                                </div>\n                                <field name="product_qty" class="oe_inline text-start text-truncate" invisible="state not in ('draft', 'done')" readonly="state != 'draft'" style="width:auto!important"/>\n                                <button type="action" name="639" context="{'default_mo_id': id}" class="oe_link oe_inline" style="margin: 0px; padding: 0px;" invisible="state in ('draft', 'done', 'cancel') or not id">\n                                    <field name="product_qty" class="oe_inline" readonly="state != 'draft'"/>\n                                </button>\n                                <label for="uom_id" string="" class="oe_inline"/>\n                                <field name="uom_id" options="{'no_open': True, 'no_create': True, 'quantity_field': 'product_qty'}" groups="uom.group_uom" widget="many2one_uom" readonly="state != 'draft'" class="flex-grow-0" style="width:auto!important"/>\n                                <span name="to_produce" class="fw-bold text-nowrap">To Produce</span>\n                                <button type="object" name="action_product_forecast_report" title="Forecast Report" icon="area_chart" invisible="forecasted_issue"/>\n                                <button type="object" name="action_product_forecast_report" title="Forecast Report" icon="area_chart" invisible="not forecasted_issue" class="text-danger"/>\n                            </div>\n                            <label for="lot_producing_ids" invisible="state in ('draft', 'cancel') or not product_tracking or (state == 'done' and product_tracking == 'serial' and product_qty &gt; 1)"/>\n                            <div class="o_row" invisible="state in ('draft', 'cancel') or not product_tracking or (state == 'done' and product_tracking == 'serial' and product_qty &gt; 1)">\n                                <field name="lot_producing_ids" widget="many2many_tags" options="{'on_tag_click': 'open_form'}" invisible="not product_tracking or (product_tracking == 'serial' and (product_qty &gt; 1 or serial_numbers_count &gt; 1))" readonly="lot_producing_ids" force_save="1" context="{'default_product_id': product_id}"/>\n                                <button name="action_generate_serial" type="object" class="btn btn-primary o_right_alignment" string="Generate Serial Numbers" aria-label="Creates new serial numbers" role="img" invisible="product_tracking != 'serial' or lot_producing_ids"/>\n                                <button name="action_generate_serial" type="object" class="btn btn-secondary o_right_alignment" string="Edit Serial Numbers" aria-label="Edit generated serial numbers" role="img" invisible="state == 'done' or product_tracking != 'serial' or not lot_producing_ids or (serial_numbers_count &lt;= 1 and product_qty &lt;= 1)"/>\n                                <button name="action_generate_serial" type="object" class="btn btn-primary o_right_alignment" string="Generate Lot Number" aria-label="Creates a new lot number" role="img" invisible="product_tracking != 'lot' or lot_producing_ids"/>\n                                <button name="action_clear_lot_producing_ids" type="object" class="btn btn-secondary o_right_alignment" string="Clear" aria-label="Clears the selected lot/serial number" role="img" invisible="state == 'done' or (product_tracking == 'serial' and (product_qty &gt; 1 or serial_numbers_count &gt; 1)) or not lot_producing_ids"/>\n                            </div>\n                        </group>\n                        <group name="group_extra_info">\n                            <label name="scheduled_date" for="date_start" string="Scheduled Date" invisible="state in ['progress', 'to_close', 'done', 'cancel']"/>\n                            <label name="start_date" for="date_start" string="Start Date" invisible="state not in ['progress', 'to_close', 'done', 'cancel']"/>\n                            <div class="o_row" name="date_start">\n                                <field name="date_start" readonly="state in ['done', 'to_close', 'cancel']" decoration-warning="state not in ('done', 'cancel') and date_start &lt; now" decoration-danger="state not in ('done', 'cancel') and date_deadline and date_deadline &lt; date_finished" help="Date at which you plan to start.                                           Red if the scheduled end is forecasted after the production order deadline.                                           Orange if the scheduled date is in the past."/>\n                                <field name="delay_alert_date" invisible="1"/>\n                                <field nolabel="1" name="json_popover" widget="stock_rescheduling_popover" invisible="not json_popover"/>\n                            </div>\n                            <field name="date_finished" string="End Date" readonly="is_locked" invisible="state != 'done'" help="Date at which you finished production."/>\n                            <field name="components_availability_state" invisible="1"/>\n                            <field name="components_availability" invisible="state not in ['confirmed', 'progress']" decoration-success="reservation_state == 'assigned' or components_availability_state == 'available'" decoration-warning="reservation_state != 'assigned' and components_availability_state in ('expected', 'available')" decoration-danger="reservation_state != 'assigned' and components_availability_state in ('late', 'unavailable')"/>\n                            <field name="user_id" widget="many2one_avatar" readonly="state in ['cancel', 'done']"/>\n                            <field name="show_final_lots" invisible="1"/>\n                            <field name="production_location_id" invisible="1" readonly="1"/>\n                            <field name="move_finished_ids" invisible="1" readonly="state == 'cancel' or (state == 'done' and is_locked)">\n                                <list editable="bottom">\n                                    <field name="product_id" readonly="state == 'done'"/>\n                                    <field name="product_uom_qty" readonly="state == 'done'"/>\n                                    <field name="uom_id" groups="uom.group_uom" widget="many2one_uom"/>\n                                    <field name="operation_id"/>\n                                    <field name="byproduct_id"/>\n                                    <field name="date_deadline"/>\n                                    <field name="picking_type_id"/>\n                                    <field name="location_id"/>\n                                    <field name="location_dest_id"/>\n                                    <field name="company_id"/>\n                                    <field name="warehouse_id"/>\n                                    <field name="origin"/>\n                                    <field name="propagate_cancel"/>\n                                    <field name="move_dest_ids"/>\n                                    <field name="state"/>\n                                    <!-- Useless as the editable in tree declaration -> For Form Test-->\n                                    <field name="allowed_operation_ids"/>\n                                    <!--\n                                    Required for test_00_mrp_byproduct\n                                    when changing the mrp.production product_qty\n                                    `_onchange_producing` is called,\n                                    calling `_set_qty_producing`,\n                                    which changes the `quantity_done` of byproducts\n                                    If byproducts are not in the view (`groups="mrp.group_mrp_byproducts"`)\n                           