   </div>\\n                                    </div>\\n                                </div>\\n\\n                            </setting>\\n                            <setting help=\\"Delegue parte del proceso de producción a subcontratistas\\" documentation=\\"/applications/inventory_and_mrp/manufacturing/management/subcontracting.html\\">\\n                                <field name=\\"module_mrp_subcontracting\\"/>\\n                            </setting>\\n                            <setting id=\\"process_mrp_barcodes\\" help=\\"Procese órdenes de fabricación desde la aplicación Código de barras\\">\\n                                <field name=\\"module_stock_barcode\\" widget=\\"upgrade_boolean\\"/>\\n                            </setting>\\n                            <setting id=\\"quality_control_mrp\\" help=\\"Añada controles de calidad a sus órdenes de trabajo\\">\\n                                <field name=\\"module_quality_control\\" widget=\\"upgrade_boolean\\"/>\\n                                <div class=\\"row mt-2\\" invisible=\\"not module_quality_control\\">\\n                                    <field name=\\"module_quality_control_worksheet\\" widget=\\"upgrade_boolean\\" class=\\"col flex-grow-0 ml16 mr0 pe-2\\"/>\\n                                    <div class=\\"col ps-0\\">\\n                                        <label for=\\"module_quality_control_worksheet\\"/>\\n                                        <div class=\\"text-muted\\">\\n                                            Cree hojas de trabajo personalizables para sus controles de calidad\\n                                        </div>\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                            <setting help=\\"Permitir a los usuarios de fabricación modificar las cantidades a consumir sin aprobación previa\\" id=\\"mrp_lock\\">\\n                                <field name=\\"group_unlocked_by_default\\"/>\\n                            </setting>\\n                            <setting id=\\"mrp_byproduct\\" help=\\"Producir productos residuales (A + B -&gt; C + D)\\" title=\\"Añada subproductos a las listas de materiales. Esto se puede usar para obtener varios productos terminados al mismo tiempo. Sin esta opción, solo puede hacer:  A + B = C. Con ella: A + B = C + D.\\">\\n                                <field name=\\"group_mrp_byproducts\\"/>\\n                            </setting>\\n                        </block>\\n                        <block title=\\"Planificación\\">\\n                            <setting id=\\"mrp_mps\\" help=\\"Planificar órdenes de fabricación o pedidos de compra basados en pronósticos\\" documentation=\\"/applications/inventory_and_mrp/manufacturing/management/use_mps.html\\" title=\\"Es útil la utilización de un informe MPS para planificar sus operaciones de reabastecimiento y fabricación si ha tenido tiempo y si se ha producido según el pronóstico de ventas.\\">\\n                                <field name=\\"module_mrp_mps\\" widget=\\"upgrade_boolean\\"/>\\n                            </setting>\\n                        </block>\\n                    </app>\\n                </xpath>"}	<?xml version="1.0"?>\n<xpath expr="//form" position="inside">\n                    <app data-string="Manufacturing" string="Manufacturing" name="mrp" groups="mrp.group_mrp_manager">\n                        <block title="Operations" name="process_operations_setting_container">\n                            <setting id="work_order" string="Work Orders" help="Process operations at specific work centers" documentation="/applications/inventory_and_mrp/manufacturing/management/bill_configuration.html#adding-a-routing" title="Work Order Operations allow you to create and manage the manufacturing operations that should be followed within your work centers in order to produce a product. They are attached to bills of materials