                                    </div>\n                                    </div>\n                                </div>\n                            </setting>\n                            <setting help="Allow manufacturing users to modify quantities to consume, without the need for prior approval" id="mrp_lock">\n                                <field name="group_unlocked_by_default"/>\n                            </setting>\n                            <setting id="mrp_byproduct" help="Produce residual products (A + B -&gt; C + D)" title="Add by-products to bills of materials. This can be used to get several finished products as well. Without this option you only do: A + B = C. With the option: A + B = C + D.">\n                                <field name="group_mrp_byproducts"/>\n                            </setting>\n                        </block>\n                        <block title="Planning">\n                            <setting id="mrp_mps" help="Plan manufacturing or purchase orders based on forecasts" documentation="/applications/inventory_and_mrp/manufacturing/management/use_mps.html" title="Using a MPS report to schedule your reordering and manufacturing operations is useful if you have long lead time and if you produce based on sales forecasts.">\n                                <field name="module_mrp_mps" widget="upgrade_boolean"/>\n                            </setting>\n                        </block>\n                    </app>\n                </xpath>\n            	\N	f	t	2026-10-26 23:55:22.988604	2026-10-26 23:55:22.988604	f
861	16	\N	1	1	Terms & Conditions	\N	account.account_terms_conditions_page	qweb	account/views/terms_template.xml	primary	\N	{"en_US": "<t name=\\"Terms &amp; Conditions\\" t-name=\\"account.account_terms_conditions_page\\">\\n        <t t-set=\\"o_portal_fullwidth_alert\\" groups=\\"account.group_account_manager\\">\\n            <t t-call=\\"account.account_terms_conditions_setting_banner\\" backend_url.f=\\"/odoo/action-account.action_open_settings\\"/>\\n        </t>\\n        <t t-call=\\"web.frontend_layout\\" o_portal_fullwidth_alert=\\"o_portal_fullwidth_alert\\">\\n            <div class=\\"oe_structure\\" id=\\"oe_structure_terms_conditions\\"/>\\n                <div class=\\"container oe_website_terms_conditions\\">\\n                    <div id=\\"o_terms_conditions\\">\\n                        <div t-field=\\"company.invoice_terms_html\\"/>\\n                    </div>\\n                </div>\\n        </t>\\n    </t>"}	<?xml version="1.0"?>\n<t name="Terms &amp; Conditions" t-name="account.account_terms_conditions_page">\n        <t t-set="o_portal_fullwidth_alert" groups="account.group_account_manager">\n            <t t-call="account.account_terms_conditions_setting_banner" backend_url.f="/odoo/action-account.action_open_settings"/>\n        </t>\n        <t t-call="web.frontend_layout" o_portal_fullwidth_alert="o_portal_fullwidth_alert">\n            <div class="oe_structure" id="oe_structure_terms_conditions"/>\n                <div class="container oe_website_terms_conditions">\n                    <div id="o_terms_conditions">\n                        <div t-field="company.invoice_terms_html"/>\n                    </div>\n                </div>\n        </t>\n    </t>\n\n    	\N	f	t	2026-10-26 23:48:13.569719	2026-10-26 23:48:13.569719	f
1978	16	1722	1	1	stock_report_delivery_document_inherit_mrp	\N	mrp.stock_report_delivery_document_inherit_mrp	qweb	mrp/report/report_deliveryslip.xml	extension	\N	{"en_US": "<data>\\n        <!-- needs to be set before so elif directly follows if later on -->\\n        <xpath expr=\\"//t[@name='has_packages']\\" position=\\"before\\">\\n            <!-- get only the top level kits' (i.e. no subkit) move lines for easier mapping later on + we ignore subkit groupings-->\\n            <!-- note that move.name uses top level kit's product.template.display_name value instead of product.template.name -->\\n            <t t-set=\\"has_kits\\" t-value=\\"o.move_line_ids.filtered(lambda l: l.move_id.bom_line_id and l.move_id.bom_line_id.bom_id.type == 'phantom')\\"/>\\n        </xpath>\\n        <xpath expr=\\"//t[@name='no_package_section']\\" position=\\"before\\">\\n            <t t-set=\\"has_kits\\" t-value=\\"o.move_line_ids.filtered(lambda l: l.move_id.bom_line_id and l.move_id.bom_line_id.bom_id.type == 'phantom')\\"/>\\n            <t t-if=\\"has_kits\\">\\n                <!-- print the products not in a package or kit first -->\\n                <t t-set=\\"move_lines\\" t-value=\\"move_lines.filtered(lambda m: not m.move_id.bom_line_id)\\"/>\\n            </t>\\n        </xpath>\\n        <xpath expr=\\"//t[@name='no_package_move_lines']\\" position=\\"inside\\">\\n            <t t-call=\\"mrp.stock_report_delivery_kit_sections\\"/>\\n        </xpath>\\n        <xpath expr=\\"//t[@name='has_packages']\\" position=\\"after\\">\\n            <!-- Additional use case: group by kits when no packages exist and then apply use case 1. (serial/lot numbers used/printed) -->\\n            <t t-elif=\\"has_kits and not packages_count\\">\\n                <t t-call=\\"mrp.stock_report_delivery_kit_sections\\"/>\\n                <t t-call=\\"mrp.stock_report_delivery_no_kit_section\\"/>\\n            </t>\\n        </xpath>\\n    </data>"}	<?xml version="1.0"?>\n<data>\n        <!-- needs to be set before so elif directly follows if later on -->\n        <xpath expr="//t[@name='has_packages']" position="before">\n            <!-- get only the top level kits' (i.e. no subkit) move lines for easier mapping later on + we ignore subkit groupings-->\n            <!-- note that move.name uses top level kit's product.template.display_name value instead of product.template.name -->\n            <t t-set="has_kits" t-value="o.move_line_ids.filtered(lambda l: l.move_id.bom_line_id and l.move_id.bom_line_id.bom_id.type == 'phantom')"/>\n        </xpath>\n        <xpath expr="//t[@name='no_package_section']" position="before">\n            <t t-set="has_kits" t-value="o.move_line_ids.filtered(lambda l: l.move_id.bom_line_id and l.move_id.bom_line_id.bom_id.type == 'phantom')"/>\n            <t t-if="has_kits">\n                <!-- print the products not in a package or kit first -->\n                <t t-set="move_lines" t-value="move_lines.filtered(lambda m: not m.move_id.bom_line_id)"/>\n            </t>\n        </xpath>\n        <xpath expr="//t[@name='no_package_move_lines']" position="inside">\n            <t t-call="mrp.stock_report_delivery_kit_sections"/>\n        </xpath>\n        <xpath expr="//t[@name='has_packages']" position="after">\n            <!-- Additional use case: group by kits when no packages exist and then apply use case 1. (serial/lot numbers used/printed) -->\n            <t t-elif="has_kits and not packages_count">\n                <t t-call="mrp.stock_report_delivery_kit_sections"/>\n                <t t-call="mrp.stock_report_delivery_no_kit_section"/>\n            </t>\n        </xpath>\n    </data>\n\n    	\N	f	t	2026-10-26 23:55:22.988604	2026-10-26 23:55:22.988604	f
864	16	118	1	1	res.company.form.inherit.account	res.company	\N	form	account/views/res_company_views.xml	extension	\N	{"en_US": "<data><xpath expr=\\"//field[@name='country_id']\\" position=\\"after\\">\\n                <field name=\\"account_enabled_tax_country_ids\\" invisible=\\"1\\"/>\\n            </xpath>\\n            <xpath expr=\\"//sheet\\" position=\\"after\\">\\n                <chatter/>\\n            </xpath>\\n            <field name=\\"vat\\" position=\\"before\\">\\n                <field name=\\"company_vat_placeholder\\" invisible=\\"1\\"/> <!-- Needed for the placeholder widget -->\\n            </field>\\n            <field name=\\"vat\\" position=\\"attributes\\">\\n                <attribute name=\\"options\\">{'placeholder_field': 'company_vat_placeholder'}</attribute>\\n            </field>\\n        </data>"}	<?xml version="1.0"?>\n<data><xpath expr="//field[@name='country_id']" position="after">\n                <field name="account_enabled_tax_country_ids" invisible="1"/>\n            </xpath>\n            <xpath expr="//sheet" position="after">\n                <chatter/>\n            </xpath>\n            <field name="vat" position="before">\n                <field name="company_vat_placeholder" invisible="1"/> <!-- Needed for the placeholder widget -->\n            </field>\n            <field name="vat" position="attributes">\n                <attribute name="options">{'placeholder_field': 'company_vat_placeholder'}</attribute>\n            </field>\n        </data>	\N	f	t	2026-10-26 23:48:13.569719	2026-10-26 23:48:13.569719	f
1979	16	\N	1	1	stock_report_delivery_kit_sections	\N	mrp.stock_report_delivery_kit_sections	qweb	mrp/report/report_deliveryslip.xml	primary	\N	{"en_US": "<t t-name=\\"mrp.stock_report_delivery_kit_sections\\">\\n        <!-- get all kits-related SML, including subkits -->\\n        <t t-set=\\"all_kits_move_lines\\" t-value=\\"o.move_ids.move_line_ids.filtered(lambda l: l.move_id.bom_line_id.bom_id.type == 'phantom')\\"/>\\n        <!-- do another map to get unique top level kits -->\\n        <t t-set=\\"boms\\" t-value=\\"has_kits.mapped('move_id.bom_line_id.bom_id')\\"/>\\n        <t t-foreach=\\"boms\\" t-as=\\"bom\\">\\n            <!-- Separate product.product from template for variants-->\\n            <t t-if=\\"bom.product_id\\">\\n                <t t-set=\\"kit_product\\" t-value=\\"bom.product_id\\"/>\\n            </t>\\n            <t t-else=\\"\\">\\n                <t t-set=\\"kit_product\\" t-value=\\"bom.product_tmpl_id\\"/>\\n            </t>\\n            <tr t-att-class=\\"'fw-bold o_line_section'\\">\\n                <td colspan=\\"99\\">\\n                    <span t-out=\\"kit_product.display_name\\"/>\\n                </td>\\n            </tr>\\n            <t t-set=\\"kit_move_lines\\" t-value=\\"all_kits_move_lines.filtered(lambda l: l.move_id.bom_line_id.bom_id == bom)\\"/>\\n            <t t-if=\\"has_serial_number\\">\\n                <tr t-foreach=\\"kit_move_lines\\" t-as=\\"move_line\\">\\n                    <t t-set=\\"description\\" t-value=\\"move_line.move_id.description_picking\\"/>\\n                    <t t-if=\\"description == kit_product.display_name\\">\\n                        <t t-set=\\"description\\" t-value=\\"\\"/>\\n                    </t>\\n                    <t t-call=\\"stock.stock_report_delivery_has_serial_move_line\\"/>\\n                </tr>\\n            </t>\\n            <t t-else=\\"\\">\\n                <t t-set=\\"aggregated_lines\\" t-value=\\"kit_move_lines._get_aggregated_product_quantities(kit_name=kit_product.display_name)\\"/>\\n                <t t-if=\\"aggregated_lines\\">\\n                    <t t-call=\\"stock.stock_report_delivery_aggregated_move_lines\\"/>\\n                </t>\\n            </t>\\n        </t>\\n    </t>"}	<?xml version="1.0"?>\n<t t-name="mrp.stock_report_delivery_kit_sections">\n        <!-- get all kits-related SML, including subkits -->\n        <t t-set="all_kits_move_lines" t-value="o.move_ids.move_line_ids.filtered(lambda l: l.move_id.bom_line_id.bom_id.type == 'phantom')"/>\n        <!-- do another map to get unique top level kits -->\n        <t t-set="boms" t-value="has_kits.mapped('move_id.bom_line_id.bom_id')"/>\n        <t t-foreach="boms" t-as="bom">\n            <!-- Separate product.product from template for variants-->\n            <t t-if="bom.product_id">\n                <t t-set="kit_product" t-value="bom.product_id"/>\n            </t>\n            <t t-else="">\n                <t t-set="kit_product" t-value="bom.product_tmpl_id"/>\n            </t>\n            <tr t-att-class="'fw-bold o_line_section'">\n                <td colspan="99">\n                    <span t-out="kit_product.display_name"/>\n                </td>\n            </tr>\n            <t t-set="kit_move_lines" t-value="all_kits_move_lines.filtered(lambda l: l.move_id.bom_line_id.bom_id == bom)"/>\n            <t t-if="has_serial_number">\n                <tr t-foreach="kit_move_lines" t-as="move_line">\n                    <t t-set="description" t-value="move_line.move_id.description_picking"/>\n                    <t t-if="description == kit_product.display_name">\n                        <t t-set="description" t-value=""/>\n                    </t>\n                    <t t-call="stock.stock_report_delivery_has_serial_move_line"/>\n                </tr>\n            </t>\n            <t t-else="">\n                <t t-set="aggregated_lines" t-value="kit_move_lines._get_aggregated_product_quantities(kit_name=kit_product.display_name)"/>\n                <t t-if="aggregated_lines">\n                    <t t-call="stock.stock_report_delivery_aggregated_move_lines"/>\n                </t>\n            </t>\n        </t>\n    </t>\n\n    	\N	f	t	2026-10-26 23:55:22.988604	2026-10-26 23:55:22.988604	f
862	16	\N	1	1	account_default_terms_and_conditions	\N	account.account_default_terms_and_conditions	qweb	account/views/terms_template.xml	primary	\N	{"en_US": "<t t-name=\\"account.account_default_terms_and_conditions\\">\\n        <div>\\n            <h1>STANDARD TERMS AND CONDITIONS OF SALE</h1>\\n            <p>You should update this document to reflect your T&amp;C.</p>\\n            <p>Below text serves as a suggestion and doesn’t engage Odoo S.A. responsibility.</p>\\n            <ol>\\n                <li>\\n                    The client explicitly waives its own standard terms and conditions, even if these were drawn up after these standard terms and conditions of sale. In order to be valid, any derogation must be expressly agreed to in advance in writing.\\n                </li>\\n                <li>\\n                    Our invoices are payable within 21 working days, unless another payment timeframe is indicated on either the invoice or the order. In the event of non-payment by the due date, <t t-out=\\"company_name\\"/> reserves the right to request a fixed interest payment amounting to 10% of the sum remaining due. <t t-out=\\"company_name\\"/> will be authorized to suspend any provision of services without prior warning in the event of late payment.\\n                </li>\\n                <li>\\n                    If a payment is still outstanding more than sixty (60) days after the due payment date, <t t-out=\\"company_name\\"/> reserves the right to call on the services of a debt recovery company. All legal expenses will be payable by the client.\\n                </li>\\n                <li>\\n                    Certain countries apply withholding at source on the amount of invoices, in accordance with their internal legislation. Any withholding at source will be paid by the client to the tax authorities. Under no circumstances can <t t-out=\\"company_name\\"/> become involved in costs related to a country's legislation. The amount of the invoice will therefore be due to <t t-out=\\"company_name\\"/> in its entirety and does not include any costs relating to the legislation of the country in which the client is located.\\n                </li>\\n                <li>\\n                    <t t-out=\\"company_name\\"/> undertakes to do its best to supply performant services in due time in accordance with the agreed timeframes. However, none of its obligations can be considered as being an obligation to achieve results. <t t-out=\\"company_name\\"/> cannot under any circumstances, be required by the client to appear as a third party in the context of any claim for damages filed against the client by an end consumer.\\n                </li>\\n                <li>\\n                    In order for it to be admissible, <t t-out=\\"company_name\\"/> must be notified of any claim by means of a letter sent by recorded delivery to its registered office within 8 days of the delivery of the goods or the provision of the services.\\n                </li>\\n                <li>\\n                    All our contractual relations will be governed exclusively by <t t-out=\\"company_country\\"/> law.\\n                </li>\\n            </ol>\\n        </div>\\n    </t>", "es_ES": "<t t-name=\\"account.account_default_terms_and_conditions\\">\\n        <div>\\n            <h1>TÉRMINOS Y CONDICIONES ESTÁNDAR DE VENTA</h1>\\n            <p>Debe actualizar este documento para que refleje sus términos y condiciones.</p>\\n            <p>El texto a continuación sirve como sugerencia y no compromete la responsabilidad de Odoo S.A. de C.V.</p>\\n            <ol>\\n                <li>\\n                    El cliente renuncia explícitamente a sus propios términos y condiciones estándar, incluso si éstas se redactaron después de los presentes términos y condiciones estándar de venta. Para que sea válida, se debe acordar cualquier derogación expresamente por escrito y con antelación.\\n                </li>\\n                <li>\\n                    Nuestras facturas se pueden pagar en un plazo de 21 días laborables, a menos que en la factura o en el pedido se indique otro plazo de pago. En caso de no pagar antes de la fecha de vencimiento, <t t-out=\\"company_name\\"/> se reserva el derecho de solicitar un pago de intereses fijo que asciende al 10 % de la suma que queda por pagar. <t t-out=\\"company_name\\"/> estará autorizada a suspender cualquier prestación de servicios sin previo aviso en caso de retraso en el pago.\\n                </li>\\n                <li>\\n                    Si un pago sigue pendiente por más de sesenta (60) días después de la fecha límite, <t t-out=\\"company_name\\"/> se reserva el derecho de recurrir a los servicios de una empresa de cobro de deudas. Todos los gastos legales correrán a cargo del cliente.\\n                </li>\\n                <li>\\n                    Algunos países aplican retenciones en origen sobre el importe de las facturas, de acuerdo con su legislación interna. Cualquier retención en origen será pagada por el cliente a las autoridades fiscales. En ningún caso puede <t t-out=\\"company_name\\"/> se involucra en los costes relacionados con la legislación de un país. Por lo tanto, el importe de la factura se deberá a <t t-out=\\"company_name\\"/> en su totalidad y no incluye ningún coste relacionado con la legislación del país en el que se encuentra el cliente.\\n                </li>\\n                <li>\\n                    <t t-out=\\"company_name\\"/> se compromete a hacer todo lo posible para prestar los servicios en el plazo acordado. Sin embargo, ninguna de sus obligaciones puede considerarse como una obligación a obtener resultados. <t t-out=\\"company_name\\"/> no puede, en ningún caso, ser requerido por el cliente para comparecer como tercero en el contexto de un reclamo por daños presentado contra el cliente por un consumidor final.\\n                </li>\\n                <li>\\n                    Para que sea admisible, <t t-out=\\"company_name\\"/> debe ser notificado de cualquier reclamo mediante una carta enviada por correo certificado a su oficina registrada en un plazo de 8 días desde la entrega de los bienes o la prestación de los servicios.\\n                </li>\\n                <li>\\n                    Todas las relaciones contractuales serán gobernadas exclusivamente por <t t-out=\\"company_country\\"/> ley.\\n                </li>\\n            </ol>\\n        </div>\\n    </t>"}	<?xml version="1.0"?>\n<t t-name="account.account_default_terms_and_conditions">\n        <div>\n            <h1>STANDARD TERMS AND CONDITIONS OF SALE</h1>\n            <p>You should update this document to reflect your T&amp;C.</p>\n            <p>Below text serves as a suggestion and doesn’t engage Odoo S.A. responsibility.</p>\n            <ol>\n                <li>\n                    The client explicitly waives its own standard terms and conditions, even if these were drawn up after these standard terms and conditions of sale. In order to be valid, any derogation must be expressly agreed to in advance in writing.\n                </li>\n                <li>\n                    Our invoices are payable within 21 working days, unless another payment timeframe is indicated on either the invoice or the order. In the event of non-payment by the due date, <t t-out="company_name"/> reserves the right to request a fixed interest payment amounting to 10% of the sum remaining due. <t t-out="company_name"/> will be authorized to suspend any provision of services without prior warning in the event of late payment.\n                </li>\n                <li>\n                    If a payment is still outstanding more than sixty (60) days after the due payment date, <t t-out="company_name"/> reserves the right to call on the services of a debt recovery company. All legal expenses will be payable by the client.\n                </li>\n                <li>\n                    Certain countries apply withholding at source on the amount of invoices, in accordance with their internal legislation. Any withholding at source will be paid by the client to the tax authorities. Under no circumstances can <t t-out="company_name"/> become involved in costs related to a country's legislation. The amount of the invoice will therefore be due to <t t-out="company_name"/> in its entirety and does not include any costs relating to the legislation of the country in which the client is located.\n                </li>\n                <li>\n                    <t t-out="company_name"/> undertakes to do its best to supply performant services in due time in accordance with the agreed timeframes. However, none of its obligations can be considered as being an obligation to achieve results. <t t-out="company_name"/> cannot under any circumstances, be required by the client to appear as a third party in the context of any claim for damages filed against the client by an end consumer.\n                </li>\n                <li>\n                    In order for it to be admissible, <t t-out="company_name"/> must be notified of any claim by means of a letter sent by recorded delivery to its registered office within 8 days of the delivery of the goods or the provision of the services.\n                </li>\n                <li>\n                    All our contractual relations will be governed exclusively by <t t-out="company_country"/> law.\n                </li>\n            </ol>\n        </div>\n    </t>\n\n	\N	f	t	2026-10-26 23:48:13.569719	2026-10-26 23:48:13.569719	f
