1981	16	\N	1	1	report_mrp_bom	\N	mrp.report_mrp_bom	qweb	mrp/report/mrp_report_bom_structure.xml	primary	\N	{"en_US": "<t t-name=\\"mrp.report_mrp_bom\\">\\n        <div class=\\"o_mrp_bom_report_page container py-3 py-lg-5 px-0 bg-view\\">\\n            <div t-if=\\"data.get('lines')\\">\\n                <div>\\n                    <h1>BoM Overview</h1>\\n                    <h3 t-out=\\"data['name']\\"/>\\n                    <hr t-if=\\"data['bom_code']\\"/>\\n                    <h6 t-if=\\"data['bom_code']\\">Reference: <t t-out=\\"data['bom_code']\\"/></h6>\\n                </div>\\n                <t t-set=\\"currency\\" t-value=\\"data['currency']\\"/>\\n                <table class=\\"o_mrp_bom_expandable table table-borderless\\">\\n                    <thead>\\n                        <tr>\\n                            <th name=\\"th_mrp_bom_h\\">Product</th>\\n                            <th class=\\"text-end\\">Quantity</th>\\n                            <th class=\\"text-end\\" groups=\\"uom.group_uom\\"/>\\n                            <th name=\\"th_mrp_bom_free_to_use\\" t-if=\\"data['forecast_mode']\\" class=\\"text-center\\">Free to Use / On Hand</th>\\n                            <th t-if=\\"data['forecast_mode']\\" class=\\"text-center\\">Status</th>\\n                            <th t-if=\\"data['forecast_mode']\\" class=\\"text-center\\">Lead Time</th>\\n                            <th t-if=\\"data['forecast_mode']\\">Route</th>\\n                            <th class=\\"text-end text-nowrap\\" t-attf-colspan=\\"{{ 1 if data['forecast_mode'] else 2 }}\\">Total Cost</th>\\n                        </tr>\\n                    </thead>\\n                    <tbody>\\n                        <tr>\\n                            <td name=\\"td_mrp_bom\\" t-out=\\"data['name']\\"/>\\n                            <td class=\\"text-end\\" t-out=\\"data['quantity']\\" t-options=\\"{&quot;widget&quot;: &quot;float&quot;, &quot;decimal_precision&quot;: &quot;Product Unit&quot;}\\"/>\\n                            <td class=\\"text-start\\" groups=\\"uom.group_uom\\" t-out=\\"data['uom_name']\\"/>\\n                            <td name=\\"td_mrp_bom_free_to_use\\" t-if=\\"data['forecast_mode']\\" class=\\"text-center\\">\\n                                <t t-out=\\"data['quantity_available']\\" t-options=\\"{&quot;widget&quot;: &quot;float&quot;, &quot;decimal_precision&quot;: &quot;Product Unit&quot;}\\"/> /\\n                                <t t-out=\\"data['quantity_on_hand']\\" t-options=\\"{&quot;widget&quot;: &quot;float&quot;, &quot;decimal_precision&quot;: &quot;Product Unit&quot;}\\"/>\\n                            </td>\\n                            <td t-if=\\"data['forecast_mode']\\" class=\\"text-center\\">\\n                                <t t-if=\\"data['status']\\">\\n                                    <span t-attf-class=\\"{{'text-danger' if data.get('availability_state') == 'unavailable' else ''}}                                                         {{'text-success' if data.get('producible_qty') else ''}}\\" t-out=\\"data['status']\\">\\n                                    </span>\\n                                </t>\\n                            </td>\\n                            <td t-if=\\"data['forecast_mode']\\" class=\\"text-end\\">\\n                                <span t-if=\\"data['lead_time'] is not False\\">\\n                                    <t t-out=\\"data['lead_time']\\" t-options=\\"{'widget': 'float', 'precision': 0}\\"/>\\n                                    Days\\n                                </span>\\n                            </td>\\n                            <td t-if=\\"data['forecast_mode']\\">\\n                                <span t-if=\\"data['route_name'] and data['route_detail']\\" t-attf-class=\\"{{'text-danger' if data.get('route_alert') else ''}}\\">\\n                                    <t t-out=\\"data['route_name']\\"/>:</span>\\n                                <span t-out=\\"data['route_detail']\\"/>\\n                            </td>\\n                            <td class=\\"text-end\\" t-out=\\"data['bom_cost']\\" t-attf-colspan=\\"{{ 1 if data['forecast_mode'] else 2 }}\\" t-options=\\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: currency}\\"/>\\n                        </tr>\\n                        <t t-call=\\"mrp.report_mrp_bom_pdf_line\\"/>\\n                    </tbody>\\n                    <tfoot t-if=\\"data['quantity'] &gt; 0\\">\\n                        <tr>\\n                            <td name=\\"td_mrp_bom_f\\" class=\\"text-end\\" t-attf-colspan=\\"2\\">\\n                                <t t-if=\\"data['byproducts']\\" t-out=\\"data['name']\\"/>\\n                            </td>\\n                            <td t-if=\\"(data['byproducts'] or data['product_uom_name'] != data['uom_name'])\\" groups=\\"uom.group_uom\\" t-out=\\"data['product_uom_name']\\"/>\\n                            <td name=\\"free_to_use\\" t-if=\\"data['forecast_mode']\\"/>\\n                            <td name=\\"status\\" t-if=\\"data['forecast_mode']\\"/>\\n                            <td name=\\"lead_time\\" t-if=\\"data['forecast_mode']\\"/>\\n                            <td name=\\"route_column\\" class=\\"text-end\\" t-attf-colspan=\\"{{ 1 if len(data['byproducts']) or not data['show_uom'] or data['show_uom'] and data['product_uom_name'] != data['uom_name'] else 2 }}\\">\\n                                <strong>Unit Cost</strong>\\n                            </td>\\n                            <td name=\\"cost\\" class=\\"text-end\\" width=\\"5rem\\">\\n                                <t t-out=\\"data['bom_unit_cost'] / data['quantity']\\" t-options=\\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: currency}\\"/>\\n                            </td>\\n                        </tr>\\n                        <t t-if=\\"data['byproducts']\\" t-foreach=