group\\">\\n                                        <div class=\\"row mt8\\">\\n                                            <label for=\\"account_journal_early_pay_discount_gain_account_id\\" class=\\"col-lg-5 o_light_label\\"/>\\n                                            <field name=\\"account_journal_early_pay_discount_gain_account_id\\" decoration-muted=\\"not account_journal_early_pay_discount_gain_account_active\\"/>\\n                                        </div>\\n                                        <div class=\\"row mt8\\">\\n                                            <label for=\\"account_journal_early_pay_discount_loss_account_id\\" class=\\"col-lg-5 o_light_label\\"/>\\n                                            <field name=\\"account_journal_early_pay_discount_loss_account_id\\" decoration-muted=\\"not account_journal_early_pay_discount_loss_account_active\\"/>\\n                                        </div>\\n                                    </div>\\n                                </setting>\\n                                <setting id=\\"product_accounts\\" string=\\"Product Accounts:\\">\\n                                    <div class=\\"content-group\\">\\n                                        <div class=\\"row mt8\\">\\n                                            <label for=\\"income_account_id\\" class=\\"col-lg-5 o_light_label\\"/>\\n                                            <field name=\\"income_account_id\\" decoration-muted=\\"not income_account_active\\"/>\\n                                        </div>\\n                                        <div class=\\"row mt8\\">\\n                                            <label for=\\"expense_account_id\\" class=\\"col-lg-5 o_light_label\\"/>\\n                                            <field name=\\"expense_account_id\\" decoration-muted=\\"not expense_account_active\\"/>\\n                                        </div>\\n                                    </div>\\n                                </setting>\\n                                <setting id=\\"cash_rounding_accounts\\" string=\\"Total Rounding Accounts:\\" groups=\\"account.group_cash_rounding\\">\\n                                    <div class=\\"content-group\\">\\n                                        <div class=\\"row mt8\\">\\n                                            <label for=\\"cash_rounding_profit_account_id\\" string=\\"Profit Account\\" class=\\"col-lg-5 o_light_label\\"/>\\n                                            <field name=\\"cash_rounding_profit_account_id\\"/>\\n                                        </div>\\n                                        <div class=\\"row mt8\\">\\n                                            <label for=\\"cash_rounding_loss_account_id\\" string=\\"Loss Account\\" class=\\"col-lg-5 o_light_label\\"/>\\n                                            <field name=\\"cash_rounding_loss_account_id\\"/>\\n                                        </div>\\n                                    </div>\\n                                </setting>\\n                            </block>\\n                        </t>\\n\\n                        <t groups=\\"account.group_account_user\\">\\n                            <block title=\\"Bank &amp; Cash\\" id=\\"bank_cash\\">\\n                                <setting title=\\"Once installed, set 'Bank Feeds' to 'File Import' in bank account settings.This adds a button to import from the Accounting dashboard.\\" string=\\"QIF Import\\" help=\\"Import your bank statements in QIF\\">\\n                                    <field name=\\"module_account_bank_statement_import_qif\\" widget=\\"upgrade_boolean\\"/>\\n                                </setting>\\n                            </block>\\n                        </t>\\n\\n                        <t groups=\\"account.group_account_user\\">\\n                            <block title=\\"Fiscal Periods\\" id=\\"accounting_reports\\">\\n                                <setting id=\\"fiscalyear\\" invisible=\\"1\\" groups=\\"account.group_account_user\\"/>\\n                            </block>\\n                        </t>\\n                        <block title=\\"Analytics\\" id=\\"analytic\\" groups=\\"account.group_account_user\\">\\n                            <setting id=\\"track_costs_revenues\\" title=\\"Allows you to use the analytic accounting.\\" groups=\\"account.group_account_user\\" help=\\"Track costs &amp; revenues by project, department, etc\\" documentation=\\"/applications/finance/accounting/others/analytic_accounting.html\\">\\n                                <field name=\\"group_analytic_accounting\\"/>\\n                            </setting>\\n                            <setting id=\\"account_budget\\" title=\\"This allows accountants to manage analytic and crossovered budgets. Once the master budgets and the budgets are defined, the project managers can set the planned amount on each analytic account.\\" groups=\\"account.group_account_user\\" help=\\"Use budgets to compare actual with expected revenues and costs\\" documentation=\\"/applications/finance/accounting/others/adviser/budget.html\\">\\n                                <field name=\\"module_account_budget\\" widget=\\"upgrade_boolean\\"/>\\n                            </setting>\\n                            <setting id=\\"monitor_product_margins\\" string=\\"Margin Analysis\\" help=\\"Monitor your product margins from invoices\\" groups=\\"account.group_account_user\\">\\n                                <field name=\\"module_product_margin\\"/>\\n                            </setting>\\n                        </block>\\n                        <block title=\\"Reporting\\" id=\\"account_reports_settings\\" groups=\\"account.group_account_user\\">\\n                            <setting string=\\"Restrictive Audit Trail\\" company_dependent=\\"1\\" invisible=\\"force_restrictive_audit_trail\\" help=\\"Log changes to posted journal entries immutably\\">\\n                                <field name=\\"restrictive_audit_trail\\"/>\\n                            </setting>\\n                        </block>\\n                        <field name=\\"is_account_peppol_eligible\\" invisible=\\"1\\"/>\\n                        <block title=\\"Storno Accounting\\" id=\\"storno\\" groups=\\"account.group_account_user\\" invisible=\\"not display_account_storno\\">\\n                            <setting id=\\"enable_storno_accounting\\" company_dependent=\\"1\\" help=\\"Use negative numbers to reverse original entries\\">\\n                                <field name=\\"account_storno\\"/>\\n                            </setting>\\n                        </block>\\n                        <block title=\\"Accounting Firms mode\\">\\n                            <setting id=\\"quick_edit_mode_enabled\\" company_dependent=\\"1\\" help=\\"A new field 'Total (tax inc.)' to speed up and control the encoding by automating line creation with the right account and tax.\\">\\n                                <field name=\\"quick_edit_mode_enabled\\"/>\\n                                <field name=\\"quick_edit_mode\\" required=\\"quick_edit_mode_enabled\\" invisible=\\"not quick_edit_mode_enabled\\"/>\\n                            </setting>\\n                            <setting id=\\"document_sequence_editable\\" company_dependent=\\"1\\" help=\\"The document's sequence becomes editable on all documents.\\">\\n                                <field name=\\"document_sequence_editable\\"/>\\n                            </setting>\\n                            <setting id=\\"set_to_review_documents\\" company_dependent=\\"1\\" help=\\"Review all the modification done by the user with right under bookkeeper.\\">\\n                                <field name=\\"set_to_review_documents\\"/>\\n                            </setting>\\n                        </block>\\n                    </app>\\n                </xpath>", "es_ES": "<xpath expr=\\"//form\\" position=\\"inside\\">\\n                    <field name=\\"country_code\\" invisible=\\"1\\" groups=\\"account.group_account_manager\\"/>\\n                    <app data-string=\\"Invoicing\\" string=\\"Facturación\\" name=\\"account\\" groups=\\"account.group_account_manager\\">\\n                        <field name=\\"has_chart_of_accounts\\" invisible=\\"1\\"/>\\n                        <field name=\\"has_accounting_entries\\" invisible=\\"1\\"/>\\n                        <block title=\\"Initial Setup\\" name=\\"fiscal_localization_setting_container\\" invisible=\\"not is_root_company\\">\\n                            <setting string=\\"Localización fiscal\\" company_dependent=\\"1\\" help=\\"Impuestos, posiciones fiscales, plan contable y declaraciones legales de su país\\" documentation=\\"/applications/finance/fiscal_localizations.html\\">\\n                                <div class=\\"content-group\\">\\n                                    <div class=\\"mt16\\">\\n                                        <div>\\n                                            <field name=\\"chart_template\\" readonly=\\"has_accounting_entries\\" required=\\"chart_template\\" class=\\"w-100\\" placeholder=\\"Paquete\\"/>\\n                                        </div>\\n                                        <div class=\\"mt16\\">\\n                                            <button name=\\"reload_template\\" type=\\"object\\" string=\\"Recargar\\" class=\\"btn-secondary ps-2 w-100\\" icon=\\"refresh\\" title=\\"Volver a cargar datos contables (impuestos, cuentas,...) si hay inconsistencias. Esta acción es irreversible.\\" invisible=\\"not has_accounting_entries or not chart_template\\"/>\\n                                        </div>\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                        </block>\\n                        <block title=\\"Electronic Invoicing\\" id=\\"peppol\\" invisible=\\"not is_account_peppol_eligible\\">\\n                            <div id=\\"account_peppol_install\\" class=\\"col-12 col-lg-12 o_setting_box\\">\\n                                <div class=\\"o_setting_left_pane\\">\\n                                    <field name=\\"module_account_peppol\\" readonly=\\"False\\"/>\\n                                </div>\\n                                <div class=\\"o_setting_right_pane\\">\\n                                    <label for=\\"module_account_peppol\\" string=\\"Habilitar PEPPOL\\"/>\\n                                    <div class=\\"text-muted\\">\\n                                        Permita que se envíen y reciban facturas a través de la red de PEPPOL\\n                                    </div>\\n                                </div>\\n                            </div>\\n                        </block>\\n                        <block title=\\"Impuestos\\" name=\\"default_taxes_setting_container\\">\\n                            <setting id=\\"vat_disabled_setting\\" invisible=\\"not vat_disabled_available\\" help=\\"If you are not subject to VAT, you will have no sale taxes and only non deductible taxes activated\\" company_dependent=\\"1\\" title=\\"Not Subject to VAT\\">\\n                                <field name=\\"vat_disabled\\" readonly=\\"not is_root_company\\"/>\\n                            </setting>\\n                            <setting id=\\"default_taxes\\" string=\\"Impuestos por defecto\\" company_dependent=\\"1\\" help=\\"Impuestos aplicados por defecto al crear nuevos productos.\\" documentation=\\"/applications/finance/accounting/taxation/taxes/default_taxes.html\\">\\n                                <div class=\\"content-group\\">\\n                                    <div id=\\"sale_tax\\" class=\\"row mt16\\">\\n                                        <label string=\\"Impuesto de venta\\" for=\\"sale_tax_id\\" class=\\"col-lg-3 o_light_label\\"/>\\n                                        <field name=\\"sale_tax_id\\" domain=\\"[('type_tax_use', 'in', ('sale', 'all'))]\\"/>\\n                                    </div>\\n                                    <div class=\\"row\\">\\n                                        <label string=\\"Impuesto de compra\\" for=\\"purchase_tax_id\\" class=\\"col-lg-3 o_light_label\\"/>\\n                                        <field name=\\"purchase_tax_id\\" domain=\\"[('type_tax_use', 'in', ('purchase', 'all'))]\\"/>\\n                                    </div>\\n                                    <div class=\\"row\\">\\n                                        <div class=\\"col-lg-3\\">\\n                                            <label string=\\"Precios\\" for=\\"account_price_include\\" class=\\"o_light_label\\"/>\\n                                        </div>\\n                                        <field name=\\"account_price_include\\" widget=\\"radio\\"/>\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                            <setting id=\\"rounding_method\\" company_dependent=\\"1\\" string=\\"Método de redondeo\\" help=\\"Cómo se calcula el importe total de impuestos en pedidos y facturas\\" title=\\"- Se recomienda redondear por impuesto si los precios no incluyen impuestos. Esto reduce los errores de redondeo acumulados, ya que primero suma todos los importes de impuestos sin redondear y solo redondea el total de impuestos una vez.\\\\n                                                                                                                                                                                - Se recomienda redondear por línea si los precios incluyen impuestos. De este modo, la suma de los subtotales de línea coincidirá con el total de impuestos.\\">\\n                                <field name=\\"tax_calculation_rounding_method\\" class=\\"o_light_label mt16\\" widget=\\"radio\\"/>\\n                            </setting>\\n                            <setting id=\\"avatax_settings\\" string=\\"AvaTax\\" help=\\"Automatically compute US and Canadian tax rates.\\" documentation=\\"/applications/finance/accounting/taxation/taxes/avatax.html\\" invisible=\\"vat_disabled or country_code not in ('US', 'CA')\\" company_dependent=\\"1\\">\\n                                <field name=\\"module_account_avatax\\" widget=\\"upgrade_boolean\\"/>\\n                            </setting>\\n                            <setting id=\\"eu_service\\" title=\\"Si vende productos y servicios a clientes en un país                                 fuera de la UE, debe cobrar el IVA en función de la dirección de entrega.                                 Esta regla aplica sin importar dónde se encuentra usted.\\" string=\\"Venta a distancia intracomunitaria de la UE\\" documentation=\\"/applications/finance/accounting/taxation/taxes/eu_distance_selling.html\\" help=\\"Aplique el IVA del país de la Unión Europea al que se entregan productos y servicios.\\" invisible=\\"vat_disabled or not('EU' in company_country_group_codes or company_country_code in ('CH', 'UK'))\\">\\n                                <button type=\\"object\\" name=\\"action_eu_oss_tax_mapping\\" icon=\\"refresh\\" string=\\"Mapeo fiscal de OSS\\" class=\\"btn-link\\"/>\\n                            </setting>\\n                            <setting id=\\"vies_service_setting\\" help=\\"Verify VAT numbers using the European VIES service\\" company_dependent=\\"1\\" title=\\"If this checkbox is ticked, the default fiscal position that applies will                                            depend upon the output of the verification by the European VIES Service.\\" documentation=\\"/applications/finance/accounting/taxation/taxes/vat_validation.html\\">\\n                                <field name=\\"vat_check_vies\\"/>\\n                            </setting>\\n                            <setting id=\\"tax_exigibility\\" company_dependent=\\"1\\" help=\\"Permita configurar impuestos con criterio de caja\\" title=\\"Seleccione esto si los impuestos deben usar el criterio de caja, que creará un asiento para dichos impuestos en una cuenta determinada durante la conciliación.\\" documentation=\\"/applications/finance/accounting/taxation/taxes/cash_basis_taxes.html\\" invisible=\\"vat_disabled\\">\\n                                <field name=\\"tax_exigibility\\"/>\\n                                <div class=\\"content-group\\" invisible=\\"not tax_exigibility\\" groups=\\"account.group_account_user\\">\\n                                    <div class=\\"row mt16\\">\\n                                        <label for=\\"tax_cash_basis_journal_id\\" class=\\"col-lg-3 o_light_label\\"/>\\n                                        <field name=\\"tax_cash_basis_journal_id\\"/>\\n                                    </div>\\n                                    <div class=\\"row mt16\\">\\n                                        <label for=\\"account_cash_basis_base_account_id\\" class=\\"col-lg-3 o_light_label\\"/>\\n                                        <field name=\\"account_cash_basis_base_account_id\\" decoration-muted=\\"not account_cash_basis_base_account_active\\"/>\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                            <setting id=\\"tax_fiscal_country_234\\" string=\\"País fiscal\\" company_dependent=\\"1\\" help=\\"País de origen de su contabilidad\\">\\n                                <field name=\\"account_fiscal_country_id\\" options=\\"{'no_create': True, 'no_open': True}\\"/>\\n                            </setting>\\n                        </block>\\n                        <block title=\\"Monedas\\" name=\\"main_currency_setting_container\\">\\n                            <setting id=\\"main_currency\\" string=\\"Moneda principal\\" company_dependent=\\"1\\" help=\\"Moneda principal de su compañía\\" documentation=\\"/applications/finance/accounting/others/multi_currency.html\\">\\n                                <div class=\\"content-group\\">\\n                                    <div class=\\"row mt16\\">\\n                                        <label for=\\"currency_id\\" class=\\"col-lg-3 o_light_label\\"/>\\n                                        <field name=\\"currency_id\\" options=\\"{'no_create_edit': True, 'no_open': True}\\" context=\\"{'active_test': False}\\"/>\\n                                        <field name=\\"group_multi_currency\\" invisible=\\"1\\"/>\\n                                    </div>\\n                                    <div class=\\"mt8\\">\\n                                        <button type=\\"action\\" name=\\"63\\" string=\\"Monedas\\" class=\\"btn-link\\" icon=\\"east\\"/>\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                            <setting id=\\"update_exchange_rates\\" invisible=\\"not group_multi_currency\\" help=\\"Actualizar los tipos de cambio automáticamente\\" documentation=\\"/applications/finance/accounting/others/multi_currency.html\\">\\n                                <field name=\\"module_currency_rate_live\\" widget=\\"upgrade_boolean\\"/>\\n                            </setting>\\n                        </block>\\n                        <block title=\\"Facturas de cliente\\" id=\\"invoicing_settings\\">\\n                            <setting id=\\"send_invoices_followups\\" help=\\"Send invoices and payment reminders by post\\" documentation=\\"/applications/finance/accounting/receivables/customer_invoices/snailmail.html\\">\\n                                <field name=\\"module_snailmail_account\\"/>\\n                            </setting>\\n                            <setting id=\\"invoice_delivery_addresses\\" documentation=\\"/applications/sales/sales/send_quotations/different_addresses.html\\" help=\\"Seleccione direcciones de factura y entrega específicas\\">\\n                                <field name=\\"group_sale_delivery_address\\"/>\\n                            </setting>\\n                            <setting id=\\"smallest_coinage_currency\\" help=\\"Apply rounding to the total amount of a sales invoice.\\" documentation=\\"/applications/finance/accounting/receivables/customer_invoices/cash_rounding.html\\">\\n                                <field name=\\"group_cash_rounding\\"/>\\n                                <div class=\\"mt8\\">\\n                                    <button name=\\"306\\" icon=\\"east\\" type=\\"action\\" string=\\"Rounding Methods\\" class=\\"btn-link\\" invisible=\\"not group_cash_rounding\\"/>\\n                                </div>\\n                            </setting>\\n                            <setting id=\\"intrastat_statistics\\" help=\\"Recolecte información y produzca estadísticas de la negociación de bienes en Europa con intrastat.\\" documentation=\\"/applications/finance/accounting/reporting/declarations/intrastat.html\\" invisible=\\"'INTRASTAT' not in company_country_group_codes\\">\\n                                <field name=\\"module_account_intrastat\\" widget=\\"upgrade_boolean\\"/>\\n                            </setting>\\n                            <setting id=\\"default_incoterm\\" string=\\"Incoterm por defecto\\" help=\\"Incoterm por defecto de su empresa\\">\\n                                <field name=\\"incoterm_id\\"/>\\n                            </setting>\\n                            <setting id=\\"show_sale_receipts\\" help=\\"Activar para crear un recibo de venta\\">\\n                                <field name=\\"show_sale_receipts\\"/>\\n                            </setting>\\n                            <setting id=\\"use_invoice_terms\\" company_dependent=\\"1\\" help=\\"Añada sus términos y condiciones al final de sus facturas, pedidos o presupuestos\\">\\n                                <field name=\\"use_invoice_terms\\"/>\\n                                <div class=\\"content-group\\" invisible=\\"not use_invoice_terms\\">\\n                                    <div class=\\"mt16\\">\\n                                        <field name=\\"terms_type\\" class=\\"o_light_label\\" widget=\\"radio\\"/>\\n                                        <div>\\n                                            <field name=\\"invoice_terms\\" invisible=\\"terms_type == 'html'\\" class=\\"oe_account_terms mt-5 w-100\\" placeholder=\\"Inserte sus términos y condiciones aquí...\\"/>\\n                                        </div>\\n                                        <div class=\\"mt8\\" invisible=\\"terms_type != 'html'\\">\\n                                            <button name=\\"action_update_terms\\" icon=\\"east\\" type=\\"object\\" string=\\"Actualizar términos\\" class=\\"btn-link\\"/>\\n                                        </div>\\n                                        <field name=\\"preview_ready\\" invisible=\\"1\\"/>\\n                                        <div class=\\"mt4 ms-1\\" invisible=\\"not preview_ready\\">\\n                                            <a class=\\"btn-link\\" href=\\"/terms\\" role=\\"button\\">\\n                                                <i class=\\"oi\\" data-icon=\\"east\\"/>\\n                                                Vista previa\\n                                            </a>\\n                                        </div>\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                            <setting company_dependent=\\"1\\" help=\\"Active alertas al crear facturas y pedidos de venta para contactos con un importe total por cobrar que exceden un límite.                                      Establezca un valor superior a 0,0 para activar una comprobación del crédito concedido\\">\\n                                <field name=\\"account_use_credit_limit\\"/>\\n                                <div class=\\"content-group mt-2\\" invisible=\\"not account_use_credit_limit\\">\\n                                    <div class=\\"row\\">\\n                                        <label for=\\"account_default_credit_limit\\" class=\\"col-lg-4 o_light_label\\"/>\\n                                        <field name=\\"account_default_credit_limit\\" widget=\\"monetary\\"/>\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                            <setting id=\\"total_amount_words\\" company_dependent=\\"1\\" help=\\"Display the total amount of an invoice in words\\">\\n                                <field name=\\"display_invoice_amount_total_words\\"/>\\n                            </setting>\\n                            <setting id=\\"display_invoice_tax_company_currency\\" company_dependent=\\"1\\" help=\\"En las facturas también se mostrarán los impuestos en la moneda local\\">\\n                                <field name=\\"display_invoice_tax_company_currency\\"/>\\n                            </setting>\\n                        </block>\\n                        <block title=\\"Unidades y embalajes\\">\\n                            <setting id=\\"account_uom\\" help=\\"Venda y compre productos en diferentes unidades de medida o embalajes\\">\\n                                <field name=\\"group_uom\\"/>\\n                                <div class=\\"content-group\\" invisible=\\"not group_uom\\">\\n                                    <button name=\\"92\\" icon=\\"east\\" type=\\"action\\" string=\\"Unidades y embalajes\\" class=\\"btn-link\\"/>\\n                                </div>\\n                            </setting>\\n                        </block>\\n                        <block title=\\"Pagos de cliente\\" id=\\"pay_invoice_online_setting_container\\">\\n                            <setting help=\\"Let your customers pay their invoices on your portal\\" documentation=\\"/applications/finance/accounting/receivables/customer_payments/online_payment.html\\">\\n                                <field name=\\"module_account_payment\\"/>\\n                                <div class=\\"mt-3 d-flex\\" invisible=\\"not module_account_payment\\">\\n                                    <field name=\\"link_qr_code\\" string=\\"Añadir enlace del código QR en archivos PDF\\"/>\\n                                    <div>\\n                                        <label for=\\"link_qr_code\\"/><br/>\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                            <setting id=\\"account_batch_payment\\" string=\\"Pagos por lotes\\" help=\\"Agrupa pagos en un solo lote para facilitar el proceso de conciliación\\" documentation=\\"/applications/finance/accounting/receivables/customer_payments/batch.html\\">\\n                                <field name=\\"module_account_batch_payment\\" widget=\\"upgrade_boolean\\"/>\\n                            </setting>\\n                            <setting id=\\"collect_customer_payment\\" title=\\"Si selecciona esta casilla, podrá cobrar utilizando los mandatos de domiciliación bancaria SEPA.\\" string=\\"Domiciliación bancaria SEPA (SDD)\\" company_dependent=\\"1\\" help=\\"Recolecta los pagos de los clientes con un solo clic utilizando el Servicio Euro SEPA.\\" documentation=\\"/applications/finance/accounting/receivables/customer_payments/batch_sdd.html\\" invisible=\\"'SEPA' not in company_country_group_codes\\">\\n                                <field name=\\"module_account_sepa_direct_debit\\" class=\\"oe_inline\\" widget=\\"upgrade_boolean\\"/>\\n                                <div class=\\"content-group\\" invisible=\\"not module_account_sepa_direct_debit\\">\\n                                    <div class=\\"text-warning mt16 mb4\\">\\n                                        Guarde esta página y luego regrese para configurar la función.\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                            <setting id=\\"qr_code_invoices_sepa\\" help=\\"Añada un código QR a sus facturas para que sus clientes puedan pagar instantáneamente con su aplicación móvil bancaria.\\" string=\\"SEPA QR Codes\\" company_dependent=\\"1\\" documentation=\\"/applications/finance/accounting/receivables/customer_invoices/epc_qr_code.html\\" invisible=\\"'SEPA' not in company_country_group_codes\\">\\n                                <field name=\\"qr_code\\" class=\\"oe_inline\\"/>\\n                            </setting>\\n                            <setting id=\\"qr_code_invoices\\" help=\\"Add a QR-code to your invoices so that your customers can pay instantly with their banking application.\\" string=\\"Payment QR Codes\\" company_dependent=\\"1\\" invisible=\\"'SEPA' in company_country_group_codes\\">\\n                                <field name=\\"qr_code\\" class=\\"oe_inline\\"/>\\n                            </setting>\\n                        </block>\\n                        <block title=\\"Facturas de proveedores\\" id=\\"account_vendor_bills\\">\\n                            <setting id=\\"autopost_bills\\" help=\\"Proponga validar automáticamente las facturas cuando la precisión de la IA sea correcta tres veces seguidas para un proveedor.\\">\\n                                <field name=\\"autopost_bills\\"/>\\n                            </setting>\\n                        </block>\\n                        <block title=\\"Pagos de proveedor\\" id=\\"print_vendor_checks_setting_container\\">\\n                            <setting id=\\"print_checks\\" groups=\\"account.group_account_user\\" string=\\"Controles\\" company_dependent=\\"1\\" help=\\"Imprima cheques para pagar a sus proveedores\\" documentation=\\"/applications/finance/accounting/payables/pay/check.html\\">\\n                                <field name=\\"module_account_check_printing\\"/>\\n                            </setting>\\n                            <setting id=\\"sepa_payments\\" title=\\"Si marcas esta casilla, podrás registrar tu pago utilizando SEPA / ISO20022.\\" company_dependent=\\"1\\" help=\\"Paga tus facturas con un solo clic utilizando el servicio Euro SEPA / ISO20022\\" documentation=\\"/applications/finance/accounting/payables/pay/sepa.html\\">\\n                                <field name=\\"module_account_iso20022\\" widget=\\"upgrade_boolean\\"/>\\n                            </setting>\\n                        </block>\\n\\n                        <block title=\\"Digitalización\\" id=\\"account_digitalization\\">\\n                            <setting id=\\"account_ocr_settings\\" help=\\"Digitalice su PDF o documentos escaneados con el OCR e Inteligencia Artificial.\\" documentation=\\"/applications/finance/accounting/payables/supplier_bills/invoice_digitization.html\\" class=\\"oe_inline mb-0\\">\\n                                <field name=\\"module_account_extract\\" widget=\\"upgrade_boolean\\"/>\\n                                <div id=\\"msg_invoice_extract\\" class=\\"content-group\\" invisible=\\"not module_account_extract\\">\\n                                    <div class=\\"text-warning mt16 mb4\\">\\n                                        Guarde esta página y luego regrese para configurar la función.\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                            <div id=\\"account_ocr_settings_moves\\" class=\\"row\\"/>\\n                        </block>\\n\\n                        <t groups=\\"account.group_account_user\\">\\n                            <block title=\\"Cuentas por defecto\\" id=\\"default_accounts\\">\\n                                <setting invisible=\\"not group_multi_currency\\" string=\\"Asientos de diferencia de cambio:\\">\\n                                    <div class=\\"content-group\\">\\n                                        <div class=\\"row mt8\\">\\n                                            <label for=\\"currency_exchange_journal_id\\" class=\\"col-lg-4 o_light_label\\" string=\\"Diario\\"/>\\n                                            <field name=\\"currency_exchange_journal_id\\"/>\\n                                        </div>\\n                                        <div class=\\"row mt8\\">\\n                                            <label for=\\"income_currency_exchange_account_id\\" string=\\"Ganancia\\" class=\\"col-lg-4 o_light_label\\"/>\\n                                            <field name=\\"income_currency_exchange_account_id\\" decoration-muted=\\"not income_currency_exchange_account_active\\"/>\\n                                        </div>\\n                                        <div class=\\"row mt8\\">\\n                                            <label for=\\"expense_currency_exchange_account_id\\" string=\\"Pérdidas\\" class=\\"col-lg-4 o_light_label\\"/>\\n                                            <field name=\\"expense_currency_exchange_account_id\\" decoration-muted=\\"not expense_currency_exchange_account_active\\"/>\\n                                        </div>\\n                                    </div>\\n                                </setting>\\n                                <setting id=\\"post_bank_transactions_and_payments_setting\\" string=\\"Transacciones bancarias y pagos:\\">\\n                                    <div class=\\"content-group\\">\\n                                        <div class=\\"row mt8\\">\\n                                            <label for=\\"account_journal_suspense_account_id\\" class=\\"col-lg-5 o_light_label\\"/>\\n                                            <field name=\\"account_journal_suspense_account_id\\" decoration-muted=\\"not account_journal_suspense_account_active\\"/>\\n                                        </div>\\n                                        <div class=\\"row mt8\\">\\n                                            <label for=\\"transfer_account_id\\" class=\\"col-lg-5 o_light_label\\"/>\\n                                            <field name=\\"transfer_account_id\\" decoration-muted=\\"not transfer_account_active\\"/>\\n                                        </div>\\n                                    </div>\\n                                </setting>\\n                                <setting string=\\"Descuentos por línea de factura:\\" title=\\"Si está vacío, el descuento se realizará directamente sobre la cuenta de ingresos/gastos. Si está establecido, los descuentos sobre las facturas se realizarán en cuentas separadas.\\">\\n                                    <div class=\\"content-group\\">\\n                                        <div class=\\"row mt8\\">\\n                                            <label for=\\"account_discount_expense_allocation_id\\" class=\\"col-lg-5 o_light_label\\" string=\\"Facturas de cliente\\"/>\\n                                            <field name=\\"account_discount_expense_allocation_id\\" placeholder=\\"Misma cuenta que en el producto\\" decoration-muted=\\"not account_discount_expense_allocation_active\\"/>\\n                                        </div>\\n                                        <div class=\\"row mt8\\" id=\\"account_discount_income_allocation\\">\\n                                            <label for=\\"account_discount_income_allocation_id\\" class=\\"col-lg-5 o_light_label\\" string=\\"Facturas de proveedores\\"/>\\n                                            <field name=\\"account_discount_income_allocation_id\\" placeholder=\\"Misma cuenta que en el producto\\" decoration-muted=\\"not account_discount_income_allocation_active\\"/>\\n                                        </div>\\n                                    </div>\\n                                </setting>\\n                                <setting string=\\"Descuentos por pago anticipado:\\">\\n                                    <div class=\\"content-group\\">\\n                                        <div class=\\"row mt8\\">\\n                                            <label for=\\"account_journal_early_pay_discount_gain_account_id\\" class=\\"col-lg-5 o_light_label\\"/>\\n                                            <field name=\\"account_journal_early_pay_discount_gain_account_id\\" decoration-muted=\\"not account_journal_early_pay_discount_gain_account_active\\"/>\\n                                        </div>\\n                                        <div class=\\"row mt8\\">\\n                                            <label for=\\"account_journal_early_pay_discount_loss_account_id\\" class=\\"col-lg-5 o_light_label\\"/>\\n                                            <field name=\\"account_journal_early_pay_discount_loss_account_id\\" decoration-muted=\\"not account_journal_early_pay_discount_loss_account_active\\"/>\\n                                        </div>\\n                                    </div>\\n                                </setting>\\n                                <setting id=\\"product_accounts\\" string=\\"Cuentas del producto:\\">\\n                                    <div class=\\"content-group\\">\\n                                        <div class=\\"row mt8\\">\\n                                            <label for=\\"income_account_id\\" class=\\"col-lg-5 o_light_label\\"/>\\n                                            <field name=\\"income_account_id\\" decoration-muted=\\"not income_account_active\\"/>\\n                                        </div>\\n                                        <div class=\\"row mt8\\">\\n                                            <label for=\\"expense_account_id\\" class=\\"col-lg-5 o_light_label\\"/>\\n                                            <field name=\\"expense_account_id\\" decoration-muted=\\"not expense_account_active\\"/>\\n                                        </div>\\n                                    </div>\\n                                </setting>\\n                                <setting id=\\"cash_rounding_accounts\\" string=\\"Total Rounding Accounts:\\" groups=\\"account.group_cash_rounding\\">\\n                                    <div class=\\"content-group\\">\\n                                        <div class=\\"row mt8\\">\\n                                            <label for=\\"cash_rounding_profit_account_id\\" string=\\"Cuenta de ganancias\\" class=\\"col-lg-5 o_light_label\\"/>\\n                                            <field name=\\"cash_rounding_profit_account_id\\"/>\\n                                        </div>\\n                                        <div class=\\"row mt8\\">\\n                                            <label for=\\"cash_rounding_loss_account_id\\" string=\\"Cuenta de pérdidas\\" class=\\"col-lg-5 o_light_label\\"/>\\n                                            <field name=\\"cash_rounding_loss_account_id\\"/>\\n                                        </div>\\n                                    </div>\\n                                </setting>\\n                            </block>\\n                        </t>\\n\\n                        <t groups=\\"account.group_account_user\\">\\n                            <block title=\\"Banco y efectivo\\" id=\\"bank_cash\\">\\n                                <setting title=\\"Una vez instalado, configure 'Fuentes bancarias' para 'Importar archivo' en la configuración de la cuenta bancaria. Esto añade un botón para importar desde el tablero de Contabilidad.\\" string=\\"Importar QIF\\" help=\\"Importe sus extractos bancarios en QIF\\">\\n                                    <field name=\\"module_account_bank_statement_import_qif\\" widget=\\"upgrade_boolean\\"/>\\n                                </setting>\\n                            </block>\\n                        </t>\\n\\n                        <t groups=\\"account.group_account_user\\">\\n                            <block title=\\"Periodos fiscales\\" id=\\"accounting_reports\\">\\n                                <setting id=\\"fiscalyear\\" invisible=\\"1\\" groups=\\"account.group_account_user\\"/>\\n                            </block>\\n                        </t>\\n                        <block title=\\"Análisis\\" id=\\"analytic\\" groups=\\"account.group_account_user\\">\\n                            <setting id=\\"track_costs_revenues\\" title=\\"Le permite usar la contabilidad analítica.\\" groups=\\"account.group_account_user\\" help=\\"Lleve el seguimiento de costes e ingresos por proyecto, departamento, etc.\\" documentation=\\"/applications/finance/accounting/others/analytic_accounting.html\\">\\n                                <field name=\\"group_analytic_accounting\\"/>\\n                            </setting>\\n                            <setting id=\\"account_budget\\" title=\\"Esto permite a los asesores fiscales gestionar presupuestos analíticos y cruzados. Una vez que se definen los presupuestos maestros y los presupuestos, los administradores del proyecto pueden establecer el importe planificado en cada cuenta analítica.\\" groups=\\"account.group_account_user\\" help=\\"Utilice los presupuestos para comparar los ingresos y costes reales con los esperados\\" documentation=\\"/applications/finance/accounting/others/adviser/budget.html\\">\\n                                <field name=\\"module_account_budget\\" widget=\\"upgrade_boolean\\"/>\\n                            </setting>\\n                            <setting id=\\"monitor_product_margins\\" string=\\"Análisis de margen\\" help=\\"Controle sus márgenes de productos de las facturas\\" groups=\\"account.group_account_user\\">\\n                                <field name=\\"module_product_margin\\"/>\\n                            </setting>\\n                        </block>\\n                        <block title=\\"Informes\\" id=\\"account_reports_settings\\" groups=\\"account.group_account_user\\">\\n                            <setting string=\\"Pista de auditoría restrictiva\\" company_dependent=\\"1\\" invisible=\\"force_restrictive_audit_trail\\" help=\\"Registre los cambios de los asientos contables publicados de forma inmutable.\\">\\n                                <field name=\\"restrictive_audit_trail\\"/>\\n                            </setting>\\n                        </block>\\n                        <field name=\\"is_account_peppol_eligible\\" invisible=\\"1\\"/>\\n                        <block title=\\"Contabilidad Storno\\" id=\\"storno\\" groups=\\"account.group_account_user\\" invisible=\\"not display_account_storno\\">\\n                            <setting id=\\"enable_storno_accounting\\" company_dependent=\\"1\\" help=\\"Utilice números negativos para revertir los asientos originales\\">\\n                                <field name=\\"account_storno\\"/>\\n                            </setting>\\n                        </block>\\n                        <block title=\\"Modo de asesoría contable\\">\\n                            <setting id=\\"quick_edit_mode_enabled\\" company_dependent=\\"1\\" help=\\"A new field 'Total (tax inc.)' to speed up and control the encoding by automating line creation with the right account and tax.\\">\\n                                <field name=\\"quick_edit_mode_enabled\\"/>\\n                                <field name=\\"quick_edit_mode\\" required=\\"quick_edit_mode_enabled\\" invisible=\\"not quick_edit_mode_enabled\\"/>\\n                            </setting>\\n                            <setting id=\\"document_sequence_editable\\" company_dependent=\\"1\\" help=\\"The document's sequence becomes editable on all documents.\\">\\n                                <field name=\\"document_sequence_editable\\"/>\\n                            </setting>\\n                            <setting id=\\"set_to_review_documents\\" company_dependent=\\"1\\" help=\\"Review all the modification done by the user with right under bookkeeper.\\">\\n                                <field name=\\"set_to_review_documents\\"/>\\n                            </setting>\\n                        </block>\\n                    </app>\\n                </xpath>"}	<?xml version="1.0"?>\n<xpath expr="//form" position="inside">\n                    <field name="country_code" invisible="1" groups="account.group_account_manager"/>\n                    <app data-string="Invoicing" string="Invoicing" name="account" groups="account.group_account_manager">\n                        <field name="has_chart_of_accounts" invisible="1"/>\n                        <field name="has_accounting_entries" invisible="1"/>\n                        <block title="Initial Setup" name="fiscal_localization_setting_container" invisible="not is_root_company">\n                            <setting string="Fiscal Localization" company_dependent="1" help="Taxes, fiscal positions, chart of accounts &amp; legal statements for your country" documentation="/applications/finance/fiscal_localizations.html">\n                                <div class="content-group">\n                                    <div class="mt16">\n                                        <div>\n                                            <field name="chart_template" readonly="has_accounting_entries" required="chart_template" class="w-100" placeholder="Package"/>\n                                        </div>\n                                        <div class="mt16">\n                                            <button name="reload_template" type="object" string="Reload" class="btn-secondary ps-2 w-100" icon="refresh" title="Reload accounting data (taxes, accounts, ...) if you notice inconsistencies. This action is irreversible." invisible="not has_accounting_entries or not chart_template"/>\n                                        </div>\n                                    </div>\n                                </div>\n                            </setting>\n                        </block>\n                        <block title="Electronic Invoicing" id="peppol" invisible="not is_account_peppol_eligible">\n                            <div id="account_peppol_install" class="col-12 col-lg-12 o_setting_box">\n                                <div class="o_setting_left_pane">\n                                    <field name="module_account_peppol" readonly="False"/>\n                                </div>\n                                <div class="o_setting_right_pane">\n                                    <label for="module_account_peppol" string="Enable PEPPOL"/>\n                                    <div class="text-muted">\n                                        Allow sending and receiving invoices through the PEPPOL network\n                                    </div>\n                                </div>\n                            </div>\n                        </block>\n                        <block title="Taxes" name="default_taxes_setting_container">\n                            <setting id="vat_disabled_setting" invisible="not vat_disabled_available" help="If you are not subject to VAT, you will have no sale taxes and only non deductible taxes activated" company_dependent="1" title="Not Subject to VAT">\n                                <field name="vat_disabled" readonly="not is_root_company"/>\n                            </setting>\n                            <setting id="default_taxes" string="Default Taxes" company_dependent="1" help="Default taxes applied when creating new products." documentation="/applications/finance/accounting/taxation/taxes/default_taxes.html">\n                                <div class="content-group">\n                                    <div id="sale_tax" class="row mt16">\n                                        <label string="Sales Tax" for="sale_tax_id" class="col-lg-3 o_light_label"/>\n                                        <field name="sale_tax_id" domain="[('type_tax_use', 'in', ('sale', 'all'))]"/>\n                                    </div>\n                                    <div class="row">\n                                        <label string="Purchase Tax" for="purchase_tax_id" class="col-lg-3 o_light_label"/>\n                                        <field name="purchase_tax_id" domain="[('type_tax_use', 'in', ('purchase', 'all'))]"/>\n                                    </div>\n                                    <div class="row">\n                                        <div class="col-lg-3">\n                                            <label string="Prices" for="account_price_include" class="o_light_label"/>\n                                        </div>\n                                        <field name="account_price_include" widget="radio"/>\n                                    </div>\n                                </div>\n                            </setting>\n                            <setting id="rounding_method" company_dependent="1" string="Rounding Method" help="How total tax amount is computed in orders and invoices" title="- A rounding per tax is advised if your prices are tax-excluded. This minimizes cumulative rounding errors because it totals all unrounded tax amounts first and only rounds the final tax total once.\\n                                                                                                                                                                                - A rounding per line is advised if your prices are tax-included. That way, the sum of