\"values['display_payment_method'] and o.payment_method_line_id\\">\\n                                Payment Method: <span t-field=\\"o.payment_method_line_id.name\\">Credit card</span>\\n                            </div>\\n                            <div t-if=\\"o.memo\\">\\n                                Memo: <span t-field=\\"o.memo\\">Sample Memo</span>\\n                            </div>\\n                        </div>\\n                    </div>\\n                    <div class=\\"oe_structure\\"/>\\n                </div>\\n\\n                <div class=\\"oe_structure\\"/>\\n                <table name=\\"invoices\\" t-if=\\"values['display_invoices']\\" class=\\"table table-borderless\\">\\n                    <t t-set=\\"invoices\\" t-value=\\"o.reconciled_invoice_ids or o.reconciled_bill_ids\\"/>\\n                    <t t-set=\\"inv_to_rows\\" t-value=\\"{inv.id: inv._get_reconciled_invoices_partials_for_receipt() for inv in invoices}\\"/>\\n                    <!-- Check if invoices include different currencies -->\\n                    <t t-set=\\"otherCurrency\\" t-value=\\"any(row['currency_payment'] and inv.currency_id != row['currency_payment'] for inv in invoices for row in inv_to_rows[inv.id])\\"/>\\n                    <thead>\\n                        <tr>\\n                            <th><span>Invoice Date</span></th>\\n                            <th><span>Invoice Number</span></th>\\n                            <th><span>Reference</span></th>\\n                            <!-- Add a column if there are different currencies -->\\n                            <th t-if=\\"otherCurrency\\" class=\\"text-end\\"><span>Amount In Currency</span></th>\\n                            <th class=\\"text-end\\"><span>Amount</span></th>\\n                        </tr>\\n                    </thead>\\n                    <tbody>\\n                        <t t-foreach=\\"invoices\\" t-as=\\"inv\\">\\n                            <!-- MOVE -->\\n                            <t t-if=\\"inv.move_type != 'entry'\\">\\n                                <tr>\\n                                    <td><span t-field=\\"inv.invoice_date\\">2023-01-01</span></td>\\n                                    <td><span t-field=\\"inv.name\\">INV001</span></td>\\n                                    <td><span t-field=\\"inv.ref\\" data-oe-demo=\\"Sample Ref\\"/></td>\\n                                    <td t-if=\\"otherCurrency\\"/>\\n                                    <td class=\\"text-end\\"><span t-field=\\"inv.amount_total\\">100.00 USD</span></td>\\n                                </tr>\\n                                <!-- PAYMENTS/REVERSALS -->\\n                                <tr t-foreach=\\"inv_to_rows[inv.id]\\" t-as=\\"row\\">\\n                                    <td><span t-if=\\"row['date']\\" t-out=\\"row['date']\\" t-options=\\"{'widget': 'date'}\\">2023-01-05</span></td>\\n                                    <td><span t-out=\\"row['name']\\">PAY001</span></td>\\n                                    <td><span t-if=\\"row['ref']\\" t-out=\\"row['ref']\\" data-oe-demo=\\"Payment Ref\\"/></td>\\n                                    <!-- Fill the column \\"Amount In Currency\\" only if necessary -->\\n                                    <td t-if=\\"otherCurrency\\" class=\\"text-end\\"><span t-if=\\"row['currency_payment'] and row['currency_payment'] != row['currency_invoice']\\" t-out=\\"row['amount_payment']\\" t-options=\\"{'widget': 'monetary', 'display_currency': row['currency_payment']}\\">50.00 EUR</span></td>\\n                                    <td class=\\"text-end\\"><span t-out=\\"row['amount_invoice']\\" t-options=\\"{'widget': 'monetary', 'display_currency': row['currency_invoice']}\\">25.00 USD</span></td>\\n                                </tr>\\n                                <!-- BALANCE -->\\n                                <tr>\\n                                    <td/>\\n                                    <td><strong>Due Amount for <span t-field=\\"inv.name\\">INV001</span></strong></td>\\n                                    <td/>\\n                                    <td t-if=\\"otherCurrency\\"/>\\n                                    <td class=\\"text-end\\"><strong><span t-field=\\"inv.amount_residual\\">25.0 USD</span></strong></td>\\n                                </tr>\\n                            </t>\\n                        </t>\\n                    </tbody>\\n                </table>\\n            </div>\\n            <div class=\\"oe_structure\\"/>\\n        </t>\\n    </t>", "es_ES": "<t t-name=\\"account.report_payment_receipt_document\\">\\n        <t t-set=\\"o\\" t-value=\\"o.with_context(lang=lang)\\"/>\\n        <t t-call=\\"web.external_layout\\" o=\\"o\\">\\n            <t t-set=\\"values\\" t-value=\\"o._get_payment_receipt_report_values()\\"/>\\n            <div class=\\"page\\">\\n                <h3><strong><span t-field=\\"o.payment_receipt_title\\">Recibo de pago</span>: <span t-field=\\"o.name\\">INV0001</span></strong></h3>\\n\\n                <div class=\\"mb-4 mt-3\\">\\n                    <div class=\\"oe_structure\\"/>\\n                    <div class=\\"row\\">\\n                        <div class=\\"col-6\\" t-if=\\"o.partner_type\\">\\n                            <div>\\n                                <t t-if=\\"o.partner_type == 'customer'\\">Cliente:</t>\\n                                <t t-else=\\"o.partner_type == 'supplier'\\">Proveedor:</t>\\n                                <span t-field=\\"o.partner_id\\" data-oe-demo=\\"Marc Demo\\"/>\\n                            </div>\\n                            <address t-field=\\"o.partner_id\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;], &quot;no_marker&quot;: True}\\"/>\\n                        </div>\\n                        <div class=\\"col-6\\">\\n                            <div t-if=\\"o.date\\">\\n      