<!-- Add a column if there are different currencies -->\\n                            <th t-if=\\"otherCurrency\\" class=\\"text-end\\"><span>Importe en moneda</span></th>\\n                            <th class=\\"text-end\\"><span>Importe</span></th>\\n                        </tr>\\n                    </thead>\\n                    <tbody>\\n                        <t t-foreach=\\"invoices\\" t-as=\\"inv\\">\\n                            <!-- MOVE -->\\n                            <t t-if=\\"inv.move_type != 'entry'\\">\\n                                <tr>\\n                                    <td><span t-field=\\"inv.invoice_date\\">2023-01-01</span></td>\\n                                    <td><span t-field=\\"inv.name\\">INV001</span></td>\\n                                    <td><span t-field=\\"inv.ref\\" data-oe-demo=\\"Sample Ref\\"/></td>\\n                                    <td t-if=\\"otherCurrency\\"/>\\n                                    <td class=\\"text-end\\"><span t-field=\\"inv.amount_total\\">100,00 USD</span></td>\\n                                </tr>\\n                                <!-- PAYMENTS/REVERSALS -->\\n                                <tr t-foreach=\\"inv_to_rows[inv.id]\\" t-as=\\"row\\">\\n                                    <td><span t-if=\\"row['date']\\" t-out=\\"row['date']\\" t-options=\\"{'widget': 'date'}\\">2023-01-05</span></td>\\n                                    <td><span t-out=\\"row['name']\\">PAY001</span></td>\\n                                    <td><span t-if=\\"row['ref']\\" t-out=\\"row['ref']\\" data-oe-demo=\\"Payment Ref\\"/></td>\\n                                    <!-- Fill the column \\"Amount In Currency\\" only if necessary -->\\n                                    <td t-if=\\"otherCurrency\\" class=\\"text-end\\"><span t-if=\\"row['currency_payment'] and row['currency_payment'] != row['currency_invoice']\\" t-out=\\"row['amount_payment']\\" t-options=\\"{'widget': 'monetary', 'display_curr