-demo="Marc Demo"/>\n                            </div>\n                            <address t-field="o.partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;], &quot;no_marker&quot;: True}"/>\n                        </div>\n                        <div class="col-6">\n                            <div t-if="o.date">\n                                Payment Date: <span t-field="o.date">2026-01-01</span>\n                            </div>\n                            <div t-if="o.amount">\n                                Payment Amount: <span t-field="o.amount" t-options="{'widget': 'monetary', 'display_currency': o.currency_id}">50 USD</span>\n                            </div>\n                            <div name="payment_method" t-if="values['display_payment_method'] and o.payment_method_line_id">\n                                Payment Method: <span t-field="o.payment_method_line_id.name">Credit card</span>\n                            </div>\n                            <div t-if="o.memo">\n                                Memo: <span t-field="o.memo">Sample Memo</span>\n                            </div>\n                        </div>\n                    </div>\n                    <div class="oe_structure"/>\n                </div>\n\n                <div class="oe_structure"/>\n                <table name="invoices" t-if="values['display_invoices']" class="table table-borderless">\n                    <t t-set="invoices" t-value="o.reconciled_invoice_ids or o.reconciled_bill_ids"/>\n                    <t t-set="inv_to_rows" t-value="{inv.id: inv._get_reconciled_invoices_partials_for_receipt() for inv in invoices}"/>\n                    <!-- Check if invoices include different currencies -->\n                    <t t-set="otherCurrency" t-value="any(row['currency_payment'] and inv.currency_id != row['currency_payment'] for inv in invoices for row in inv_to_rows[inv.id])"/>\n                    <thead>\