oration-muted=\\"status_in_payment in ('posted', 'sent', 'partial')\\" decoration-success=\\"status_in_payment in ('in_payment', 'paid', 'reversed')\\" invisible=\\"payment_state == 'invoicing_legacy' or move_type == 'entry'\\"/>\\n                            </footer>\\n                        </t>\\n                    </templates>\\n                </kanban>", "es_ES": "<kanban class=\\"o_kanban_mobile\\" sample=\\"1\\" js_class=\\"account_documents_kanban\\">\\n                    <field name=\\"currency_id\\"/>\\n                    <field name=\\"review_state\\"/>\\n                    <templates>\\n                        <t t-name=\\"card\\">\\n                            <div class=\\"d-flex align-items-baseline mb-2\\">\\n                                <field name=\\"partner_id\\" class=\\"fw-bolder fs-5 me-2\\" invisible=\\"not partner_id\\" readonly=\\"state != 'draft'\\"/>\\n                                <field name=\\"journal_id\\" class=\\"fw-bolder fs-5 me-2\\" invisible=\\"partner_id\\"/>\\n                                <div invisible=\\"review_state not in ('todo', 'anomaly') or state != 'posted'\\" groups=\\"account.group_account_user\\">\\n                                    <span class=\\"badge rounded-pill text-bg-info\\">\\n                                        Por revisar\\n                                    </span>\\n                                </div>\\n                                <field name=\\"amount_total_in_currency_signed\\" widget=\\"monetary\\" class=\\"fw-bolder ms-auto flex-shrink-0\\"/>\\n                            </div>\\n                            <footer class=\\"align-items-end\\">\\n                                <div class=\\"d-flex flex-wrap gap-1 text-muted text-nowrap\\">\\n                                    <field name=\\"name\\"/>\\n                                    <field name=\\"date\\"/>\\n                                    <field name=\\"activity_ids\\" widget=\\"kanban_activity\\"/>\\n                                </div>\\n                                <field name=\\"status_in_payment\\" widget=\\"badge\\" class=\\"ms-auto\\" decoration-info=\\"status_in_payment == 'draft'\\" decoration-danger=\\"status_in_payment in ('blocked', 'cancel')\\" decoration-muted=\\"status_in_payment in ('posted', 'sent', 'partial')\\" decoration-success=\\"status_in_payment in ('in_payment', 'paid', 'reversed')\\" invisible=\\"payment_state == 'invoicing_legacy' or move_type == 'entry'\\"/>\\n                            </footer>\\n                        </t>\\n                    </templates>\\n                </kanban>"}	<?xml version="1.0"?>\n<kanban class="o_kanban_mobile" sample="1" js_class="account_documents_kanban">\n                    <field name="currency_id"/>\n                    <field name="review_state"/>\n                    <templates>\n                        <t t-name="card">\n                            <div class="d-flex align-items-baseline mb-2">\n                                <field name="partner_id" class="fw-bolder fs-5 me-2" invisible="not partner_id" readonly="state != 'draft'"/>\n                                <field name="journal_id" class="fw-bolder fs-5 me-2" invisible="partner_id"/>\n                                <div invisible="review_state not in ('todo', 'anomaly') or state != 'posted'" groups="account.group_account_user">\n                                    <span class="badge rounded-pill text-bg-info">\n                                        To Review\n                                    </span>\n                                </div>\n                                <field name="amount_total_in_currency_signed" widget="monetary" class="fw-bolder ms-auto flex-shrink-0"/>\n                            </div>\n                            <footer class="align-items-end">\n                                <div class="d-flex flex-wrap gap-1 text-muted text-nowrap">\n                                    <field name="name"/>\n                                    <field name="date"/>\n                                    <field name="activity_ids" widget="kanban_activity"/>\n                                </div>\n                                <field name="status_in_payment" widget="badge" class="ms-auto" decoration-info="status_in_payment == 'draft'" decoration-danger="status_in_payment in ('blocked', 'cancel')" decoration-muted="status_in_payment in ('posted', 'sent', 'partial')" decoration-success="status_in_payment in ('in_payment', 'paid', 'reversed')" invisible="payment_state == 'invoicing_legacy' or move_type == 'entry'"/>\n                            </footer>\n                        </t>\n                    </templates>\n                </kanban>\n            	\N	f	t	2026-10-26 23:48:13.569719	2026-10-26 23:48:13.569719	f
799	16	\N	1	1	account.move.form	account.move	\N	form	account/views/account_move_views.xml	primary	\N	{"en_US": "<form string=\\"Account Entry\\" js_class=\\"account_move_form\\">\\n                    <header>\\n                        <!-- Post -->\\n                        <button name=\\"action_post\\" string=\\"Post\\" class=\\"oe_highlight\\" type=\\"object\\" groups=\\"account.group_account_invoice\\" data-hotkey=\\"q\\" context=\\"{'validate_analytic': True, 'disable_abnormal_invoice_detection': False}\\" invisible=\\"hide_post_button or move_type != 'entry'\\"/>\\n                        <button name=\\"action_post\\" string=\\"Confirm\\" class=\\"oe_highlight\\" type=\\"object\\" groups=\\"account.group_account_invoice\\" data-hotkey=\\"q\\" context=\\"{'validate_analytic': True, 'disable_abnormal_invoice_detection': False}\\" invisible=\\"hide_post_button or move_type == 'entry' or display_inactive_currency_warning\\"/>\\n                        <!-- Send (only invoices) -->\\n                        <button name=\\"action_invoice_sent\\" type=\\"object\\" string=\\"Send\\" invisible=\\"not display_send_button or not highlight_send_button\\" class=\\"oe_highlight\\" data-hotkey=\\"y\\"/>\\n                        <button name=\\"action_invoice_sent\\" type=\\"object\\" string=\\"Send\\" invisible=\\"not display_send_button or highlight_send_button\\" data-hotkey=\\"y\\"/>\\n                        <button name=\\"action_print_pdf\\" type=\\"object\\" class=\\"oe_highlight\\" invisible=\\"state != 'posted' or is_being_sent or invoice_pdf_report_id or move_type in ('entry', 'in_invoice','in_refund','in_receipt')\\" string=\\"Print\\" data-hotkey=\\"p\\"/>\\n                        <button name=\\"action_print_pdf\\" type=\\"object\\" invisible=\\"state != 'posted' or (not is_being_sent and not invoice_pdf_report_id) or move_type in ('in_invoice','in_refund','in_receipt')\\" string=\\"Print\\" data-hotkey=\\"p\\"/>\\n                        <!-- Register Payment (only invoices / receipts) -->\\n                        <button name=\\"action_register_payment\\" id=\\"account_invoice_payment_btn\\" type=\\"object\\" class=\\"oe_highlight\\" invisible=\\"(                                     state != 'posted'                                     or payment_state not in ('not_paid', 'partial', 'in_payment')                                     or move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')                                     or invoice_has_outstanding                                 )\\" context=\\"{'dont_redirect_to_payments': True}\\" string=\\"Pay\\" data-hotkey=\\"g\\" groups=\\"account.group_account_invoice\\"/>\\n                        <!-- Register Payment (only invoices / receipts, with outstanding payments) -->\\n                        <button name=\\"action_register_payment\\" id=\\"account_invoice_payment_secondary_btn\\" type=\\"object\\" invisible=\\"(                                     state != 'posted'                                     or payment_state not in ('not_paid', 'partial', 'in_payment')                                     or move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')                                     or not invoice_has_outstanding                                 )\\" context=\\"{'dont_redirect_to_payments': True}\\" string=\\"Pay\\" data-hotkey=\\"g\\" groups=\\"account.group_account_invoice\\"/>\\n                        <!-- Preview (only customer invoices) -->\\n                        <button name=\\"preview_invoice\\" type=\\"object\\" string=\\"Preview\\" data-hotkey=\\"o\\" invisible=\\"move_type not in ('out_invoice', 'out_refund') or state in ('draft', 'cancel')\\"/>\\n                        <!-- Reverse -->\\n                        <button name=\\"256\\" string=\\"Reverse Entry\\" type=\\"action\\" groups=\\"account.group_account_invoice\\" data-hotkey=\\"z\\" invisible=\\"move_type != 'entry' or state != 'posted' or payment_state == 'reversed'\\"/>\\n                        <button name=\\"action_reverse\\" string=\\"Credit Note\\" type=\\"object\\" groups=\\"account.group_account_invoice\\" invisible=\\"move_type not in ('out_invoice', 'in_invoice') or state != 'posted'\\" data-hotkey=\\"shift+n\\"/>\\n                        <!-- Cancel -->\\n                        <button name=\\"button_cancel\\" string=\\"Cancel Entry\\" type=\\"object\\" groups=\\"account.group_account_invoice\\" data-hotkey=\\"x\\" invisible=\\"not id or state != 'draft' or move_type != 'entry'\\"/>\\n                        <button name=\\"button_cancel\\" string=\\"Cancel\\" type=\\"object\\" groups=\\"account.group_account_invoice\\" data-hotkey=\\"x\\" invisible=\\"not id or state != 'draft' or move_type == 'entry'\\"/>\\n                        <button name=\\"button_draft\\" string=\\"Reset to Draft\\" type=\\"object\\" groups=\\"account.group_account_invoice\\" invisible=\\"not show_reset_to_draft_button\\" data-hotkey=\\"r\\"/>\\n                        <button name=\\"button_hash\\" string=\\"Lock\\" type=\\"object\\" groups=\\"account.group_account_invoice\\" invisible=\\"not restrict_mode_hash_table or inalterable_hash or state != 'posted'\\"/>\\n                        <button string=\\"Request Cancel\\" name=\\"button_request_cancel\\" type=\\"object\\" groups=\\"account.group_account_invoice\\" invisible=\\"state != 'posted' or show_reset_to_draft_button or not need_cancel_request\\" data-hotkey=\\"w\\"/>\\n                        <!-- Reload Data from attachment -->\\n                        <button name=\\"action_reload_imported_data\\" string=\\"Reload Data\\" type=\\"object\\" invisible=\\"state != 'draft'                                            or move_type not in ('in_invoice', 'in_refund', 'in_receipt', 'out_invoice', 'out_refund', 'out_receipt')                                            or not import_source_attachment_id\\"/>\\n                        <!-- Review button -->\\n                        <field name=\\"review_state\\" widget=\\"account_review_state_selection_badge\\" options=\\"{                                    'no_review': {'can_edit': 'account.group_account_user,account.group_account_manager'},                                    'todo': {'decoration': 'info'},                                    'reviewed': {'decoration': 'success'},                                    'supervised': {'decoration': 'success', 'can_edit': 'account.group_account_manager'},                                    'anomaly': {'decoration': 'danger'},                                }\\" class=\\"ms-auto me-3 align-self-center\\" invisible=\\"state != 'posted'\\" groups=\\"account.group_account_user\\"/>\\n                        <field name=\\"state\\" widget=\\"statusbar\\" statusbar_visible=\\"draft,posted\\" groups=\\"!account.group_account_secured\\"/>\\n                        <field name=\\"state\\" widget=\\"account_move_statusbar_secured\\" statusbar_visible=\\"draft,posted\\" groups=\\"account.group_account_secured\\"/>\\n                    </header>\\n\\n                    <!-- General warnings computed from `_get_alerts` -->\\n                    <div class=\\"m-0\\" id=\\"alerts\\" invisible=\\"not alerts\\">\\n                        <field name=\\"alerts\\" class=\\"o_field_html\\" widget=\\"actionable_errors\\"/>\\n                    </div>\\n                    <!--Duplicate check-->\\n                    <div class=\\"d-flex alert alert-danger w-100 d-flex align-items-center gap-1\\" invisible=\\"not is_exact_move_duplicate\\" role=\\"alert\\">\\n                        <span>This document might be a duplicate of</span>\\n                        <field name=\\"duplicated_ref_ids\\" widget=\\"x2many_buttons\\" nb_records_shown=\\"1\\" string=\\"Duplicated Documents\\" context=\\"{'name_as_amount_total': True}\\"/>\\n                        <button name=\\"action_delete_duplicates\\" type=\\"object\\" class=\\"btn btn-link text-danger ms-auto d-flex align-items-center gap-1\\" invisible=\\"not has_draft_move_duplicate\\">\\n                            <i class=\\"oi oi-filled text-danger\\" data-icon=\\"delete\\"/>\\n                            <span class=\\"text-danger\\" invisible=\\"duplicated_ref_ids.length == 1\\">Delete all duplicates</span>\\n                            <span class=\\"text-danger\\" invisible=\\"duplicated_ref_ids.length &gt; 1\\">Delete duplicate</span>\\n                        </button>\\n                    </div>\\n                    <div class=\\"d-flex alert alert-warning w-100 d-flex align-items-center gap-1\\" invisible=\\"not duplicated_ref_ids or is_exact_move_duplicate or state != 'draft'\\" role=\\"alert\\">\\n                        <span>This document might be a duplicate of</span>\\n                        <field name=\\"duplicated_ref_ids\\" widget=\\"x2many_buttons\\" nb_records_shown=\\"1\\" string=\\"Duplicated Documents\\" context=\\"{'name_as_amount_total': True}\\"/>\\n                        <button name=\\"action_delete_duplicates\\" type=\\"object\\" class=\\"btn btn-link text-danger ms-auto d-flex align-items-center gap-1\\" invisible=\\"not has_draft_move_duplicate\\">\\n                            <i class=\\"oi oi-filled text-danger\\" data-icon=\\"delete\\"/>\\n                            <span class=\\"text-danger\\" invisible=\\"duplicated_ref_ids.length == 1\\">Delete all duplicates</span>\\n                            <span class=\\"text-danger\\" invisible=\\"duplicated_ref_ids.length &gt; 1\\">Delete duplicate</span>\\n                        </button>\\n                    </div>\\n                    <!-- Invoice outstanding credits -->\\n                    <div groups=\\"account.group_account_invoice,account.group_account_readonly\\" class=\\"alert alert-info\\" role=\\"alert\\" invisible=\\"move_type not in ('out_invoice', 'out_receipt') or not invoice_has_outstanding or payment_state not in ('not_paid', 'partial')\\">\\n                        You have <bold><a class=\\"alert-link\\" href=\\"#outstanding\\" role=\\"button\\">outstanding credits</a></bold> listed below for this customer.\\n                    </div>\\n                    <div groups=\\"account.group_account_invoice,account.group_account_readonly\\" class=\\"alert alert-info\\" role=\\"alert\\" invisible=\\"move_type not in ('in_invoice', 'in_receipt') or not invoice_has_outstanding or payment_state not in ('not_paid', 'partial')\\">\\n                        You have <bold><a class=\\"alert-link\\" href=\\"#outstanding\\" role=\\"button\\">outstanding debits</a></bold> listed below for this vendor.\\n                    </div>\\n                    <div groups=\\"account.group_account_invoice,account.group_account_readonly\\" class=\\"alert alert-info\\" role=\\"alert\\" invisible=\\"move_type != 'out_refund' or not invoice_has_outstanding or payment_state not in ('not_paid', 'partial')\\">\\n                        You have <bold><a class=\\"alert-link\\" href=\\"#outstanding\\" role=\\"button\\">outstanding debits</a></bold> listed below for this customer.\\n                    </div>\\n                    <div groups=\\"account.group_account_invoice,account.group_account_readonly\\" class=\\"alert alert-info\\" role=\\"alert\\" invisible=\\"move_type != 'in_refund' or not invoice_has_outstanding or payment_state not in ('not_paid', 'partial')\\">\\n                        You have <bold><a class=\\"alert-link\\" href=\\"#outstanding\\" role=\\"button\\">outstanding credits</a></bold> listed below for this vendor.\\n                    </div>\\n                    <!-- Currency consistency -->\\n                    <div class=\\"alert alert-warning\\" role=\\"alert\\" invisible=\\"not display_inactive_currency_warning or move_type not in ('in_invoice', 'in_refund', 'in_receipt')\\">\\n                        In order to validate this bill, you must <button class=\\"oe_link\\" type=\\"object\\" name=\\"action_activate_currency\\" style=\\"padding: 0; vertical-align: baseline;\\">activate the currency of the bill</button>. The journal entries need to be computed by Odoo before being posted in your company's currency.\\n                    </div>\\n                    <div class=\\"alert alert-warning\\" role=\\"alert\\" invisible=\\"not display_inactive_currency_warning or move_type not in ('out_invoice', 'out_refund', 'out_receipt')\\">\\n                        In order to validate this invoice, you must <button class=\\"oe_link\\" type=\\"object\\" name=\\"action_activate_currency\\" style=\\"padding: 0; vertical-align: baseline;\\">activate the currency of the invoice</button>. The journal entries need to be computed by Odoo before being posted in your company's currency.\\n                    </div>\\n\\n                    <sheet>\\n                        <div name=\\"button_box\\" class=\\"oe_button_box\\">\\n                            <button name=\\"action_open_business_doc\\" class=\\"oe_stat_button\\" icon=\\"menu\\" type=\\"object\\" invisible=\\"move_type != 'entry' or not id or not origin_payment_id\\">\\n                                    <div class=\\"o_stat_info\\">\\n                                        <span class=\\"o_stat_text\\">1 Payment</span>\\n                                    </div>\\n                            </button>\\n                            <button name=\\"open_payments\\" groups=\\"account.group_account_invoice,account.group_account_readonly\\" class=\\"oe_stat_button\\" icon=\\"menu\\" type=\\"object\\" invisible=\\"not payment_count\\">\\n                                    <field name=\\"payment_count\\" string=\\"Payments\\" widget=\\"statinfo\\"/>\\n                            </button>\\n                            <button name=\\"open_reconcile_view\\" class=\\"oe_stat_button\\" icon=\\"menu\\" type=\\"object\\" invisible=\\"move_type != 'entry' or not id or not has_reconciled_entries\\">\\n                                    <div class=\\"o_stat_info\\">\\n                                        <span class=\\"o_stat_text\\">Reconciled Items</span>\\n                                    </div>\\n                            </button>\\n                            <button name=\\"open_created_caba_entries\\" class=\\"oe_stat_button\\" icon=\\"attach_money\\" type=\\"object\\" invisible=\\"not tax_cash_basis_created_move_ids\\">\\n                                    <div class=\\"o_stat_info\\">\\n                                        <span class=\\"o_stat_text\\">Cash Basis Entries</span>\\n                                    </div>\\n                            </button>\\n                            <button name=\\"open_adjusting_entries\\" class=\\"oe_stat_button\\" icon=\\"menu\\" type=\\"object\\" invisible=\\"not adjusting_entries_move_ids\\">\\n                                    <field name=\\"adjusting_entries_count\\" string=\\"Adjusting Entries\\" widget=\\"statinfo\\"/>\\n                            </button>\\n                            <button name=\\"open_adjusting_entry_origin_moves\\" class=\\"oe_stat_button\\" icon=\\"menu\\" type=\\"object\\" invisible=\\"not adjusting_entry_origin_move_ids\\">\\n                                    <div invisible=\\"adjusting_entry_origin_moves_count != 1\\" class=\\"o_stat_info\\">\\n                                        <span class=\\"o_stat_text\\">\\n                                            <field name=\\"adjusting_entry_origin_label\\"/>\\n                                        </span>\\n                                    </div>\\n                                    <field name=\\"adjusting_entry_origin_moves_count\\" invisible=\\"adjusting_entry_origin_moves_count == 1\\" string=\\"Invoices\\" widget=\\"statinfo\\"/>\\n                            </button>\\n                            <button name=\\"open_journal_items\\" groups=\\"account.group_account_invoice,account.group_account_readonly\\" invisible=\\"move_type == 'entry'\\" class=\\"oe_stat_button\\" icon=\\"menu\\" type=\\"object\\">\\n                                    <div class=\\"o_stat_info\\">\\n                                        <span class=\\"o_stat_text\\">Journal Items</span>\\n                                    </div>\\n                            </button>\\n                            <button name=\\"action_open_reversal_moves\\" class=\\"oe_stat_button\\" icon=\\"edit_square\\" type=\\"object\\" invisible=\\"reversal_move_count == 0\\">\\n                                <field name=\\"reversal_move_count\\" string=\\"Credit Notes\\" widget=\\"statinfo\\" invisible=\\"move_type != 'out_invoice'\\"/>\\n                                <field name=\\"reversal_move_count\\" string=\\"Refunds\\" widget=\\"statinfo\\" invisible=\\"move_type != 'in_invoice'\\"/>\\n                                <field name=\\"reversal_move_count\\" string=\\"Reversal Entries\\" widget=\\"statinfo\\" invisible=\\"move_type != 'entry'\\"/>\\n                            </button>\\n                            <button name=\\"action_open_reversed_entry\\" class=\\"oe_stat_button\\" icon=\\"edit_square\\" type=\\"object\\" invisible=\\"not reversed_entry_id\\">\\n                                <span class=\\"o_stat_text\\" invisible=\\"move_type != 'out_refund'\\">Invoice</span>\\n                                <span class=\\"o_stat_text\\" invisible=\\"move_type != 'in_refund'\\">Vendor Bill</span>\\n                                <span class=\\"o_stat_text\\" invisible=\\"move_type != 'entry'\\">Journal Entry</span>\\n                            </button>\\n                        </div>\\n\\n                        <widget name=\\"web_ribbon\\" title=\\"Sent\\" bg_color=\\"gray_ribbon\\" invisible=\\"not is_move_sent or payment_state != 'not_paid' or move_type not in ('out_invoice', 'out_refund', 'out_receipt')\\"/>\\n                        <!-- Payment status for invoices / receipts -->\\n                        <widget name=\\"web_ribbon\\" title=\\"Sent\\" bg_color=\\"text-bg-300\\" invisible=\\"status_in_payment != 'sent' or move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')\\"/>\\n                        <widget name=\\"web_ribbon\\" title=\\"Paid\\" invisible=\\"payment_state != 'paid' or move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')\\"/>\\n                        <widget name=\\"web_ribbon\\" title=\\"In Payment\\" invisible=\\"payment_state != 'in_payment' or move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')\\"/>\\n                        <widget name=\\"web_ribbon\\" title=\\"Partial\\" bg_color=\\"text-bg-300\\" invisible=\\"payment_state != 'partial' or move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')\\"/>\\n                        <widget name=\\"web_ribbon\\" title=\\"Reversed\\" invisible=\\"payment_state != 'reversed'\\"/>\\n                        <widget name=\\"web_ribbon\\" title=\\"Blocked\\" bg_color=\\"text-bg-danger\\" invisible=\\"payment_state != 'blocked' or move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')\\"/>\\n                         <widget name=\\"web_ribbon\\" text=\\"Invoicing App Legacy\\" bg_color=\\"text-bg-info\\" invisible=\\"payment_state != 'invoicing_legacy'\\" tooltip=\\"This entry has been generated through the Invoicing app, before installing Accounting. It has been disabled by the 'Invoicing Switch Threshold Date' setting so that it does not impact your accounting.\\"/>\\n\\n                        <!-- Invisible fields -->\\n                        <field name=\\"id\\" invisible=\\"1\\"/>\\n                        <field name=\\"state\\" invisible=\\"1\\"/>\\n                        <field name=\\"company_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"journal_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"show_name_warning\\" invisible=\\"1\\"/>\\n                        <field name=\\"posted_before\\" invisible=\\"1\\"/>\\n                        <field name=\\"import_source_attachment_id\\" invisible=\\"1\\"/>\\n                        <!--test-tags .test_01_account_tour -->\\n                        <field name=\\"move_type\\" invisible=\\"1\\" force_save=\\"1\\"/>\\n                        <field name=\\"payment_state\\" invisible=\\"1\\" force_save=\\"1\\"/>\\n                        <field name=\\"invoice_filter_type_domain\\" invisible=\\"1\\"/>\\n                        <field name=\\"suitable_journal_ids\\" invisible=\\"1\\"/>\\n                        <field name=\\"currency_id\\" invisible=\\"1\\" readonly=\\"state in ['cancel', 'posted']\\"/>\\n                        <field name=\\"company_currency_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"commercial_partner_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"bank_partner_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"display_qr_code\\" invisible=\\"1\\"/>\\n                        <field name=\\"show_reset_to_draft_button\\" invisible=\\"1\\"/>\\n                        <field name=\\"expected_currency_rate\\" invisible=\\"1\\"/>\\n\\n                        <field name=\\"invoice_has_outstanding\\" invisible=\\"1\\"/>\\n                        <field name=\\"is_move_sent\\" invisible=\\"1\\"/>\\n                        <field name=\\"invoice_pdf_report_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"need_cancel_request\\" invisible=\\"1\\"/>\\n                        <field name=\\"has_reconciled_entries\\" invisible=\\"1\\"/>\\n                        <field name=\\"restrict_mode_hash_table\\" invisible=\\"1\\"/>\\n                        <field name=\\"inalterable_hash\\" invisible=\\"1\\"/>\\n                        <field name=\\"country_code\\" invisible=\\"1\\"/>\\n                        <field name=\\"display_inactive_currency_warning\\" invisible=\\"1\\"/>\\n                        <field name=\\"statement_line_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"statement_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"origin_payment_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"tax_country_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"tax_calculation_rounding_method\\" invisible=\\"1\\"/>\\n                        <field name=\\"tax_cash_basis_created_move_ids\\" invisible=\\"1\\"/>\\n                        <field name=\\"quick_edit_mode\\" invisible=\\"1\\"/>\\n                        <field name=\\"invoice_cash_rounding_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"hide_post_button\\" invisible=\\"1\\"/>\\n                        <field name=\\"quick_encoding_vals\\" invisible=\\"1\\"/>\\n                        <field name=\\"show_delivery_date\\" invisible=\\"1\\"/>\\n                        <field name=\\"is_being_sent\\" invisible=\\"1\\"/>\\n                        <field name=\\"show_update_fpos\\" invisible=\\"1\\"/>\\n                        <field name=\\"company_vat_disabled\\" invisible=\\"1\\"/>\\n\\n                        <div class=\\"oe_title\\">\\n                            <span class=\\"o_form_label\\">\\n                                <field name=\\"move_type\\" invisible=\\"move_type == 'entry' or is_self_billing\\" widget=\\"receipt_selector\\" options=\\"{'horizontal': true}\\" nolabel=\\"1\\" readonly=\\"state != 'draft'\\"/>\\n                            </span>\\n\\n                            <div class=\\"text-warning\\" invisible=\\"not show_name_warning\\">The current highest number is <field class=\\"oe_inline\\" name=\\"highest_name\\"/>. You might want to put a higher number here.</div>\\n\\n                            <h1>\\n                                <field name=\\"name\\" invisible=\\"not (name or name_placeholder or document_sequence_editable)\\" readonly=\\"state != 'draft'\\" options=\\"{'placeholder_field': 'name_placeholder'}\\"/>\\n\\n                                <span invisible=\\"name or name_placeholder or document_sequence_editable\\">Draft</span>\\n                            </h1>\\n                        </div>\\n                        <group>\\n                            <group id=\\"header_left_group\\">\\n\\n                                <label for=\\"partner_id\\" string=\\"Customer\\" style=\\"font-weight:bold;\\" invisible=\\"move_type not in ('out_invoice', 'out_refund', 'out_receipt')\\"/>\\n                                <label for=\\"partner_id\\" string=\\"Vendor\\" style=\\"font-weight:bold;\\" invisible=\\"move_type not in ('in_invoice', 'in_refund', 'in_receipt')\\"/>\\n                                <div class=\\"o_col\\" invisible=\\"move_type not in ('out_invoice', 'out_refund', 'out_receipt', 'in_invoice', 'in_refund', 'in_receipt')\\">\\n                                    <field name=\\"partner_id\\" widget=\\"res_partner_many2one\\" nolabel=\\"1\\" context=\\"{                                             'res_partner_search_mode': (context.get('default_move_type', 'entry') in ('out_invoice', 'out_refund', 'out_receipt') and 'customer') or (context.get('default_move_type', 'entry') in ('in_invoice', 'in_refund', 'in_receipt') and 'supplier') or False,                                             'show_address': 1, 'default_is_company': True, 'show_identifier': True}\\" options=\\"{&quot;no_quick_create&quot;: True}\\" default_focus=\\"1\\" invisible=\\"move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')\\" placeholder=\\"Search a name or Tax ID...\\" readonly=\\"state != 'draft'\\"/>\\n                                    <button name=\\"action_update_fpos_values\\" type=\\"object\\" string=\\"Update Taxes and Accounts\\" help=\\"Recompute all taxes and accounts based on this fiscal position\\" class=\\"btn-link mb-1 px-0\\" icon=\\"refresh\\" invisible=\\"not show_update_fpos or state in ['cancel', 'posted']\\"/>\\n                                </div>\\n\\n                                <field name=\\"partner_shipping_id\\" groups=\\"account.group_delivery_invoice_address\\" invisible=\\"move_type not in ('out_invoice', 'out_refund', 'out_receipt')\\" readonly=\\"state != 'draft'\\"/>\\n                                <field name=\\"quick_edit_total_amount\\" class=\\"w-50\\" invisible=\\"move_type == 'entry' or not quick_edit_mode\\" readonly=\\"state != 'draft'\\"/>\\n                                <label for=\\"ref\\" string=\\"Bill Reference\\" invisible=\\"move_type not in ('in_invoice', 'in_receipt', 'in_refund')\\"/>\\n                                <field name=\\"ref\\" default_focus=\\"1\\" nolabel=\\"1\\" invisible=\\"move_type not in ('in_invoice', 'in_receipt', 'in_refund')\\"/>\\n                                <field name=\\"ref\\" default_focus=\\"1\\" invisible=\\"move_type != 'entry'\\"/>\\n                                <field name=\\"tax_cash_basis_origin_move_id\\" invisible=\\"not tax_cash_basis_origin_move_id\\"/>\\n                                <field name=\\"invoice_vendor_bill_id\\" string=\\"Auto-Complete\\" class=\\"oe_edit_only\\" invisible=\\"not show_invoice_vendor_bill\\" domain=\\"([('partner_id', 'child_of', [partner_id])] if partner_id else []) + [                                            ('company_id', '=', company_id),                                            ('move_type', '=', move_type)                                        ]\\" placeholder=\\"Select an old purchase document\\" options=\\"{'no_create': True}\\" context=\\"{'show_total_amount': True}\\"/>\\n                            </group>\\n                            <group id=\\"header_right_group\\">\\n                                <label for=\\"invoice_date\\" string=\\"Invoice Date\\" style=\\"font-weight:bold;\\" invisible=\\"move_type not in ('out_invoice', 'out_refund', 'out_receipt')\\"/>\\n                                <field name=\\"invoice_date\\" nolabel=\\"1\\" options=\\"{'warning': 'future'}\\" invisible=\\"move_type not in ('out_invoice', 'out_refund', 'out_receipt')\\" readonly=\\"state != 'draft'\\" placeholder=\\"Today\\"/>\\n\\n                                <label for=\\"invoice_date\\" string=\\"Bill Date\\" style=\\"font-weight:bold;\\" invisible=\\"move_type not in ('in_invoice', 'in_refund', 'in_receipt')\\"/>\\n                                <field name=\\"invoice_date\\" nolabel=\\"1\\" options=\\"{'warning': 'future'}\\" invisible=\\"move_type not in ('in_invoice', 'in_refund', 'in_receipt')\\" required=\\"move_type in ('in_invoice', 'in_refund', 'in_receipt')\\" readonly=\\"state != 'draft'\\"/>\\n\\n                                <field name=\\"date\\" string=\\"Accounting Date\\" invisible=\\"move_type in ('out_invoice', 'out_refund', 'out_receipt') and not quick_edit_mode and not (state == 'posted' and date != invoice_date)\\" readonly=\\"state != 'draft'\\"/>\\n                                <field name=\\"payment_reference\\" invisible=\\"move_type not in ('in_invoice', 'in_refund', 'in_receipt')\\" readonly=\\"inalterable_hash != False\\" placeholder=\\"Use Bill Reference\\"/>\\n                                <field name=\\"partner_bank_id\\" widget=\\"many2one_bank\\" context=\\"{'default_partner_id': bank_partner_id}\\" domain=\\"[('partner_id', '=', bank_partner_id)]\\" invisible=\\"move_type not in ('in_invoice', 'in_refund', 'in_receipt')\\" readonly=\\"is_move_sent and state != 'draft'\\"/>\\n\\n                                <!-- Invoice payment terms (only invoices) + due date (only invoices / receipts) -->\\n                                <div class=\\"o_td_label\\" invisible=\\"move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')\\">\\n                                    <label for=\\"invoice_date_due\\" string=\\"Due Date\\" invisible=\\"invoice_payment_term_id\\"/>\\n                                    <label for=\\"invoice_payment_term_id\\" string=\\"Payment terms\\" invisible=\\"not invoice_payment_term_id\\"/>\\n                                </div>\\n                                <div class=\\"d-flex\\" invisible=\\"move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')\\" name=\\"due_date\\">\\n                                    <field name=\\"invoice_date_due\\" force_save=\\"1\\" placeholder=\\"Date\\" invisible=\\"invoice_payment_term_id\\" decoration-danger=\\"invoice_date_due and invoice_date_due &lt; context_today().strftime('%Y-%m-%d') and payment_state not in ('paid', 'in_payment', 'reversed')\\"/>\\n                                    <span class=\\"o_form_label mx-3 oe_edit_only text-center\\" style=\\"width: 6ch;\\" invisible=\\"state != 'draft' or invoice_payment_term_id\\">or</span>\\n                                    <field name=\\"invoice_payment_term_id\\" context=\\"{'example_date': invoice_date, 'example_amount': tax_totals['total_amount_currency']}\\" placeholder=\\"Payment Terms\\" options=\\"{'no_quick_create':True}\\" readonly=\\"state in ['cancel', 'posted']\\"/>\\n                                </div>\\n                                <field name=\\"taxable_supply_date_placeholder\\" invisible=\\"1\\"/> <!-- Needed for the placeholder widget -->\\n                                <field name=\\"taxable_supply_date\\" invisible=\\"not show_taxable_supply_date\\" readonly=\\"state != 'draft'\\" options=\\"{'placeholder_field': 'taxable_supply_date_placeholder'}\\"/>\\n                                <field name=\\"delivery_date\\" invisible=\\"not show_delivery_date\\" readonly=\\"state != 'draft'\\"/>\\n                                <label for=\\"journal_id\\" invisible=\\"not show_journal\\"/>\\n                                <label for=\\"currency_id\\" groups=\\"base.group_multi_currency\\" invisible=\\"show_journal\\"/>\\n                                <div name=\\"journal_div\\" class=\\"d-flex\\">\\n                                    <field name=\\"journal_id\\" invisible=\\"not show_journal\\" options=\\"{'no_create': True, 'no_open': True}\\" readonly=\\"posted_before and name not in (False, '', '/')\\"/>\\n                                    <div name=\\"in_and_refresh_button_div\\" groups=\\"base.group_multi_currency\\" class=\\"d-flex flex-column mx-3 text-center\\" style=\\"width: 6ch;\\" invisible=\\"move_type == 'entry' or not show_journal\\">\\n                                        <div>in</div>\\n                                        <div class=\\"d-flex flex-column justify-content-center flex-grow-1\\" invisible=\\"state != 'draft' or invoice_currency_rate == expected_currency_rate\\">\\n                                            <button type=\\"object\\" name=\\"refresh_invoice_currency_rate\\" icon=\\"refresh\\" title=\\"Reset the currency rate to the default accordingly to the invoice date\\" class=\\"btn btn-link p-0\\"/>\\n                                        </div>\\n                                    </div>\\n                                    <div name=\\"currency_div\\" groups=\\"base.group_multi_currency\\" class=\\"w-100\\" invisible=\\"move_type == 'entry'\\">\\n                                        <div class=\\"d-flex gap-1\\">\\n                                            <field name=\\"currency_id\\" readonly=\\"state != 'draft'\\" class=\\"oe_inline\\" options=\\"{'no_create': True}\\"/>\\n                                            <widget name=\\"account_pick_currency_date\\" invisible=\\"state != 'draft' or currency_id == company_currency_id\\"/>\\n                                        </div>\\n                                        <div name=\\"currency_conversion_div\\" class=\\"d-flex gap-1 text-muted\\" invisible=\\"currency_id == company_currency_id\\">\\n                                            <field name=\\"company_currency_id\\" invisible=\\"1\\"/>\\n                                            <field name=\\"invoice_currency_rate\\" invisible=\\"1\\"/>\\n                                            <widget name=\\"account_currency_exchange_rate\\" readonly=\\"state != 'draft'\\" options=\\"{'rate_field': 'invoice_currency_rate'}\\"/>\\n                                            <div invisible=\\"show_journal or state != 'draft' or invoice_currency_rate == expected_currency_rate\\">\\n                                            <button type=\\"object\\" name=\\"refresh_invoice_currency_rate\\" icon=\\"refresh\\" title=\\"Reset the currency rate to the default accordingly to the invoice date\\" class=\\"btn btn-link p-0\\"/>\\n                                        </div>\\n                                        </div>\\n                                    </div>\\n                                </div>\\n                            </group>\\n                            <div>\\n                                <field name=\\"document_tax_mode\\" id=\\"document_tax_mode_mobile\\" class=\\"tax_mode_badge d-md-none\\" widget=\\"document_tax_mode_selector\\" nolabel=\\"True\\" readonly=\\"state != 'draft'\\" required=\\"move_type != 'entry'\\"/>\\n                            </div>\\n                        </group>\\n                        <notebook>\\n                            <page id=\\"invoice_tab\\" name=\\"invoice_tab\\" string=\\"Invoice Lines\\" invisible=\\"move_type == 'entry'\\">\\n                                <div class=\\"position-relative document_tax_mode\\">\\n                                    <field name=\\"document_tax_mode\\" id=\\"document_tax_mode\\" class=\\"overlap_badge_tab tax_mode_badge d-none d-md-block\\" widget=\\"document_tax_mode_selector\\" nolabel=\\"True\\" readonly=\\"state != 'draft'\\" required=\\"move_type != 'entry'\\"/>\\n                                </div>\\n                                <field name=\\"invoice_line_ids\\" widget=\\"product_label_section_and_note_field_o2m\\" mode=\\"list,kanban\\" context=\\"{                                            'default_move_type': context.get('default_move_type'),                                            'journal_id': journal_id,                                            'default_partner_id': commercial_partner_id,                                            'default_currency_id': currency_id or company_currency_id,                                            'default_display_type': 'product',                                            'quick_encoding_vals': quick_encoding_vals,                                            'from_invoice_tab': True,                                        }\\" readonly=\\"state != 'draft'\\" aggregated_fields=\\"price_subtotal,price_total\\" options=\\"{'hide_composition': True, 'hide_prices': True, 'subsections': True}\\">\\n                                    <list name=\\"journal_items\\" editable=\\"bottom\\" string=\\"Journal Items\\" default_order=\\"sequence, id\\">\\n                                        <control>\\n                                            <create name=\\"add_line_control\\" string=\\"Add a line\\" data-hotkey=\\"l\\"/>\\n                                            <create name=\\"add_section_control\\" string=\\"Add a section\\" data-hotkey=\\"shift+h\\" context=\\"{'default_display_type': 'line_section'}\\"/>\\n                                            <create name=\\"add_note_control\\" string=\\"Add a note\\" data-hotkey=\\"shift+n\\" context=\\"{'default_display_type': 'line_note'}\\"/>\\n                                            <button name=\\"action_add_from_catalog\\" string=\\"Catalog\\" data-hotkey=\\"shift+k\\" type=\\"object\\" class=\\"btn-link\\" context=\\"{'order_id': parent.id}\\"/>\\n                                        </control>\\n\\n                                        <!-- Displayed fields -->\\n                                        <field name=\\"sequence\\" widget=\\"handle\\"/>\\n                                        <column name=\\"product_and_description\\">\\n                                            <field name=\\"product_id\\" optional=\\"hide\\" widget=\\"account_product_field\\" domain=\\"                                                     context.get('default_move_type') in ('out_invoice', 'out_refund', 'out_receipt')                                                     and [('sale_ok', '=', True)]                                                     or [('purchase_ok', '=', True)]                                                 \\" placeholder=\\"Search a product\\" invisible=\\"display_type in ('line_section', 'line_subsection', 'line_note')\\"/>\\n                                            <field name=\\"name\\" placeholder=\\"Enter a description\\" decoration-it=\\"display_type == 'product' and product_id\\" optional=\\"show\\" widget=\\"text\\"/>\\n                                            <field name=\\"label\\" widget=\\"account_label_text\\" invisible=\\"display_type in ('line_section', 'line_subsection', 'line_note')\\"/>\\n                                        </column>\\n                                        <field name=\\"account_id\\" context=\\"{                                                     'partner_id': partner_id,                                                     'move_type': parent.move_type,                                                     'search_default_type_asset_fixed': 'in_' in parent.move_type,                                                     'search_default_type_expense': 'in_' in parent.move_type,                                                     'search_default_type_expense_direct_cost': 'in_' in parent.move_type,                                                     'search_default_account_type': 'out_' in parent.move_type and 'income',                                                     'preferred_account_type': 'out_' in parent.move_type and 'income' or 'in_' in parent.move_type and 'expense',                                                     'list_view_ref': 'account.view_account_list_from_entry',                                                     'from_bill': move_type == 'in_invoice',                                                }\\" widget=\\"m2o_cell_with_extra_fields\\" groups=\\"account.group_account_readonly\\" options=\\"{'no_quick_create': True, 'no_open': True, 'parent_field': 'invoice_line_ids'}\\" domain=\\"[('company_ids', 'parent_of', company_id), ('account_type', 'not in', ('asset_cash', 'asset_receivable', 'liability_payable', 'off_balance'))]\\" required=\\"display_type not in ('line_section', 'line_subsection', 'line_note')\\"/>\\n                                        <field name=\\"analytic_distribution\\" widget=\\"analytic_distribution\\" string=\\"Analytic\\" groups=\\"analytic.group_analytic_accounting\\" optional=\\"show\\" options=\\"{'product_field': 'product_id', 'account_field': 'account_id', 'amount_field': 'price_subtotal'}\\" business_domain_compute=\\"parent.move_type in ['out_invoice', 'out_refund', 'out_receipt'] and 'invoice' or parent.move_type in ['in_invoice', 'in_refund', 'in_receipt'] and 'bill' or 'general'\\"/>\\n                                        <field name=\\"quantity\\" optional=\\"show\\"/>\\n                                        <field name=\\"product_uom_id\\" groups=\\"uom.group_uom\\" optional=\\"show\\" width=\\"92px\\" options=\\"{'no_create': True, 'no_open': True, 'quantity_field': 'quantity'}\\" widget=\\"many2one_uom\\"/>\\n                                        <!-- /l10n_in_edi.test_edi_json -->\\n                                        <!-- required for @api.onchange('product_id') -->\\n                                        <field name=\\"product_uom_id\\" column_invisible=\\"True\\"/>\\n                                        <field name=\\"price_unit\\" string=\\"Price\\"/>\\n                                        <field name=\\"discount\\" width=\\"50px\\" string=\\"Disc.%\\" optional=\\"hide\\"/>\\n                                        <field name=\\"tax_ids\\" widget=\\"many2many_tax_tags\\" domain=\\"[('type_tax_use', '=?', parent.invoice_filter_type_domain), ('company_id', 'parent_of', parent.company_id), ('country_id', '=', parent.tax_country_id)]\\" context=\\"{                                                     'append_fields': not parent.invoice_filter_type_domain and ['type_tax_use'],                                                     'active_test': True,                                                     'dynamic_fiscal_position_id': parent.fiscal_position_id,                                                }\\" options=\\"{'no_create': True}\\" optional=\\"show\\"/>\\n                                        <field name=\\"deductible_percentage\\" column_invisible=\\"parent.move_type not in ('in_invoice', 'in_refund', 'in_receipt')\\" string=\\"Professional\\" optional=\\"hide\\" widget=\\"percentage\\" groups=\\"!account.group_partial_purchase_deductibility\\"/>\\n                                        <field name=\\"deductible_percentage\\" column_invisible=\\"parent.move_type not in ('in_invoice', 'in_refund', 'in_receipt')\\" string=\\"Professional\\" optional=\\"show\\" widget=\\"percentage\\" groups=\\"account.group_partial_purchase_deductibility\\"/>\\n                                        <field name=\\"price_subtotal\\" column_invisible=\\"parent.document_tax_mode == 'tax_included'\\" string=\\"Amount\\"/>\\n                                        <field name=\\"price_total\\" column_invisible=\\"parent.document_tax_mode == 'tax_excluded'\\" string=\\"Amount\\"/>\\n                                        <widget name=\\"section_state\\"/>\\n                                        <!-- Others fields -->\\n                                        <field name=\\"partner_id\\" column_invisible=\\"True\\"/>\\n                                        <field name=\\"currency_id\\" column_invisible=\\"True\\"/>\\n                                        <field name=\\"company_id\\" column_invisible=\\"True\\"/>\\n                                        <field name=\\"company_currency_id\\" column_invisible=\\"True\\"/>\\n                                        <field name=\\"display_type\\" force_save=\\"1\\" column_invisible=\\"True\\"/>\\n                                        <field name=\\"collapse_prices\\" column_invisible=\\"True\\"/>\\n                                        <field name=\\"collapse_composition\\" column_invisible=\\"True\\"/>\\n                                        <field name=\\"document_tax_mode\\" column_invisible=\\"True\\"/>\\n                                    </list>\\n                                    <kanban class=\\"o_kanban_mobile\\">\\n                                        <!-- Displayed fields -->\\n                                        <templates>\\n                                            <t t-name=\\"card\\">\\n                                                <div t-attf-class=\\"ps-0 pe-0 {{ record.display_type.raw_value ? 'o_is_' + record.display_type.raw_value : '' }}\\">\\n                                                    <t t-if=\\"!['line_note', 'line_section', 'line_subsection'].includes(record.display_type.raw_value)\\">\\n                                                        <div class=\\"row g-0\\">\\n                                                            <div t-if=\\"record.product_id.raw_value\\" class=\\"col-2 pe-3\\">\\n                                                                <field name=\\"product_id\\" widget=\\"image\\" options=\\"{'preview_image': 'image_128'}\\" class=\\"w-100\\"/>\\n                                                            </div>\\n                                                            <div t-att-class=\\"{'col-10': record.product_id.raw_value}\\">\\n                                                                <div class=\\"row\\">\\n                                                                    <div class=\\"col\\">\\n                                                                        <field t-if=\\"record.product_id.raw_value\\" class=\\"fw-bold\\" name=\\"product_id\\"/>\\n                                                                        <field t-else=\\"\\" class=\\"fw-bold\\" name=\\"name\\"/>\\n                                                                    </div>\\n                                                                    <div class=\\"col-auto fw-bold float-end text-end\\">\\n                                                                        <field name=\\"price_subtotal\\" t-if=\\"record.document_tax_mode.raw_value == 'tax_excluded'\\" string=\\"Amount\\"/>\\n                                                                        <field name=\\"price_total\\" t-if=\\"record.document_tax_mode.raw_value == 'tax_included'\\" string=\\"Amount\\"/>\\n                                                                    </div>\\n                                                                </div>\\n                                                                <div class=\\"text-muted\\">\\n                                                                    Quantity:\\n                                                                    <field name=\\"quantity\\"/>\\n                                                                    <field name=\\"product_uom_id\\" groups=\\"uom.group_uom\\" widget=\\"many2one_uom\\"/>\\n                                                                </div>\\n                                                                <div class=\\"text-muted\\">\\n                                                                    Unit Price:\\n                                                                    <field name=\\"price_unit\\"/>\\n                                                                </div>\\n                                                            </div>\\n                                                        </div>\\n                                                    </t>\\n                                                    <t t-if=\\"['line_section', 'line_subsection', 'line_note'].includes(record.display_type.raw_value)\\">\\n                                                        <div t-att-class=\\"{                                                             'fw-bolder': record.display_type.raw_value === 'line_section',                                                             'fw-bold': record.display_type.raw_value === 'line_subsection',                                                             'fst-italic': record.display_type.raw_value === 'line_note',                                                         }\\">\\n                                                            <field name=\\"name\\"/>\\n                                                        </div>\\n                                                    </t>\\n                                                </div>\\n                                            </t>\\n                                        </templates>\\n\\n                                        <!-- Others fields -->\\n                                        <field name=\\"tax_calculation_rounding_method\\"/>\\n                                        <field name=\\"currency_id\\"/>\\n                                        <field name=\\"company_currency_id\\"/>\\n                                        <field name=\\"display_type\\" force_save=\\"1\\"/>\\n                                        <field name=\\"move_type\\"/>\\n                                        <field name=\\"document_tax_mode\\"/>\\n                                    </kanban>\\n\\n                                    <!-- Form view to cover mobile use -->\\n                                    <form>\\n                                        <sheet>\\n                                            <field name=\\"tax_calculation_rounding_method\\" invisible=\\"1\\"/>\\n                                            <field name=\\"display_type\\" invisible=\\"1\\"/>\\n                                            <field name=\\"company_id\\" invisible=\\"1\\"/>\\n                                            <field name=\\"partner_id\\" invisible=\\"1\\"/>\\n                                            <group>\\n                                                <field name=\\"product_id\\" widget=\\"many2one_barcode\\"/>\\n                                                <label for=\\"name\\" string=\\"Description\\" invisible=\\"display_type in ('line_section', 'line_subsection', 'line_note')\\"/>\\n                                                <label for=\\"name\\" string=\\"Section\\" invisible=\\"display_type != 'line_section'\\"/>\\n                                                <label for=\\"name\\" string=\\"Subsection\\" invisible=\\"display_type != 'line_subsection'\\"/>\\n                                                <label for=\\"name\\" string=\\"Note\\" invisible=\\"display_type != 'line_note'\\"/>\\n                                                <field name=\\"name\\" widget=\\"text\\" nolabel=\\"1\\"/>\\n                                                <field name=\\"quantity\\"/>\\n                                                <field name=\\"product_uom_id\\" groups=\\"uom.group_uom\\" widget=\\"many2one_uom\\"/>\\n                                                <field name=\\"price_unit\\"/>\\n                                                <field name=\\"discount\\" string=\\"Disc.%\\"/>\\n                                            </group>\\n                                            <group>\\n                                                <field name=\\"account_id\\" domain=\\"[('company_ids', 'parent_of', company_id)]\\" options=\\"{'no_create': True}\\" context=\\"{'partner_id': partner_id, 'move_type': parent.move_type}\\"/>\\n                                                <field name=\\"tax_ids\\" widget=\\"many2many_tax_tags\\" domain=\\"[('type_tax_use', '=?', parent.invoice_filter_type_domain), ('company_id', 'parent_of', parent.company_id), ('country_id', '=', parent.tax_country_id)]\\" context=\\"{                                                         'append_fields': not parent.invoice_filter_type_domain and ['type_tax_use'],                                                         'active_test': True,                                                         'dynamic_fiscal_position_id': parent.fiscal_position_id,                                                     }\\" options=\\"{'no_create': True}\\"/>\\n                                                <field name=\\"analytic_distribution\\" widget=\\"analytic_distribution\\" groups=\\"analytic.group_analytic_accounting\\"/>\\n                                            </group>\\n                                            <group>\\n                                                <field name=\\"price_subtotal\\" invisible=\\"parent.move_type not in ['in_invoice', 'in_refund', 'in_receipt'] and parent.company_price_include == 'tax_included'\\" string=\\"Amount\\"/>\\n                                                <field name=\\"price_total\\" invisible=\\"parent.move_type in ['in_invoice', 'in_refund', 'in_receipt'] or parent.company_price_include == 'tax_excluded'\\" string=\\"Amount\\"/>\\n                                            </group>\\n                                        </sheet>\\n                                    </form>\\n                                </field>\\n                                <group col=\\"12\\" class=\\"oe_invoice_lines_tab overflow-hidden pt-3 pt-md-0\\">\\n                                    <group colspan=\\"8\\">\\n                                        <field name=\\"narration\\" placeholder=\\"Terms and Conditions\\" nolabel=\\"1\\"/>\\n                                    </group>\\n                                    <!-- Totals (only invoices / receipts) -->\\n                                    <group colspan=\\"4\\" class=\\"m-0\\">\\n                                        <group class=\\"oe_subtotal_footer gx-0 gx-md-5\\" invisible=\\"move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt') or payment_state == 'invoicing_legacy'\\">\\n\\n                                            <field name=\\"tax_totals\\" widget=\\"account-tax-totals-field\\" nolabel=\\"1\\" colspan=\\"2\\" class=\\"mb-3 mb-md-0\\" readonly=\\"state != 'draft' or (move_type not in ('in_invoice', 'in_refund', 'in_receipt') and not quick_edit_mode)\\"/>\\n\\n                                            <field name=\\"invoice_payments_widget\\" colspan=\\"2\\" nolabel=\\"1\\" widget=\\"payment\\" class=\\"mb-3 mb-md-0\\" invisible=\\"not invoice_payments_widget\\"/>\\n                                            <div class=\\"d-flex justify-content-end gap-3\\" colspan=\\"2\\">\\n                                                <label for=\\"amount_residual\\"/>\\n                                                <field name=\\"amount_residual\\" class=\\"oe_subtotal_footer_separator w-auto\\"/>\\n                                            </div>\\n                                        </group>\\n                                        <group class=\\"oe_subtotal_footer px-4\\" invisible=\\"not invoice_has_outstanding\\" groups=\\"account.group_account_invoice,account.group_account_readonly\\">\\n                                            <field name=\\"invoice_outstanding_credits_debits_widget\\" class=\\"oe_invoice_outstanding_credits_debits py-3\\" colspan=\\"2\\" nolabel=\\"1\\" widget=\\"payment\\"/>\\n                                        </group>\\n                                    </group>\\n                                </group>\\n                            </page>\\n                            <page id=\\"aml_tab\\" string=\\"Journal Items\\" groups=\\"account.group_account_readonly\\" name=\\"aml_tab\\">\\n                                <field name=\\"line_ids\\" mode=\\"list,kanban\\" context=\\"{                                            'default_move_type': context.get('default_move_type'),                                            'line_ids': line_ids,                                            'journal_id': journal_id,                                            'default_partner_id': commercial_partner_id,                                            'default_currency_id': currency_id or company_currency_id,                                            'kanban_view_ref': 'account.account_move_line_view_kanban_mobile',                                        }\\" invisible=\\"payment_state == 'invoicing_legacy' and move_type != 'entry'\\" readonly=\\"state != 'draft'\\">\\n                                    <list editable=\\"bottom\\" string=\\"Journal Items\\" decoration-muted=\\"display_type in ('line_section', 'line_note')\\" default_order=\\"sequence, id\\">\\n                                        <!-- Displayed fields -->\\n                                        <field name=\\"account_id\\" invisible=\\"display_type in ('line_section', 'line_note')\\" required=\\"display_type not in ('line_section', 'line_note')\\" domain=\\"[('company_ids', 'parent_of', company_id), ('account_type', '!=', 'asset_cash')]\\"/>\\n                                        <field name=\\"partner_id\\" optional=\\"show\\" domain=\\"['|', ('parent_id', '=', False), ('is_company', '=', True)]\\" column_invisible=\\"parent.move_type != 'entry'\\"/>\\n                                        <field name=\\"name\\" optional=\\"show\\"/>\\n                                        <field name=\\"analytic_distribution\\" widget=\\"analytic_distribution\\" groups=\\"analytic.group_analytic_accounting\\" optional=\\"show\\" options=\\"{'account_field': 'account_id'}\\" business_domain_compute=\\"parent.move_type in ['out_invoice', 'out_refund', 'out_receipt'] and 'invoice' or parent.move_type in ['in_invoice', 'in_refund', 'in_receipt'] and 'bill' or 'general'\\"/>\\n                                        <field name=\\"date_maturity\\" optional=\\"hide\\" decoration-danger=\\"date_maturity and date_maturity &lt; context_today().strftime('%Y-%m-%d') and parent.payment_state not in ('paid', 'in_payment', 'reversed')\\" invisible=\\"display_type in ('line_section', 'line_note')\\" column_invisible=\\"context.get('view_no_maturity')\\"/>\\n                                        <field name=\\"amount_currency\\" groups=\\"base.group_multi_currency\\" optional=\\"hide\\"/>\\n                                        <field name=\\"currency_id\\" options=\\"{'no_create': True}\\" optional=\\"hide\\" groups=\\"base.group_multi_currency\\" column_invisible=\\"parent.move_type != 'entry'\\"/>\\n                                        <field name=\\"tax_ids\\" widget=\\"autosave_many2many_tax_tags\\" optional=\\"hide\\" domain=\\"[('type_tax_use', '=?', parent.invoice_filter_type_domain), ('company_id', 'parent_of', parent.company_id)]\\" context=\\"{                                                     'append_fields': not parent.invoice_filter_type_domain and ['type_tax_use'],                                                     'active_test': True                                                }\\" options=\\"{'no_create': True}\\" force_save=\\"1\\" readonly=\\"display_type in ('line_section', 'line_note') or tax_line_id or (parent.move_type in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt') and account_type in ('asset_receivable', 'liability_payable'))\\"/>\\n                                        <field name=\\"debit\\" sum=\\"Total Debit\\" invisible=\\"display_type in ('line_section', 'line_subsection', 'line_note')\\" readonly=\\"parent.move_type in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt') and display_type in ('line_section', 'line_note', 'product')\\" decoration-muted=\\"debit == 0\\"/>\\n                                        <field name=\\"credit\\" sum=\\"Total Credit\\" invisible=\\"display_type in ('line_section', 'line_subsection', 'line_note')\\" readonly=\\"parent.move_type in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt') and display_type in ('line_section', 'line_note', 'product')\\" decoration-muted=\\"credit == 0\\"/>\\n                                        <field name=\\"balance\\" column_invisible=\\"True\\"/>\\n                                        <field name=\\"discount_date\\" string=\\"Discount Date\\" optional=\\"hide\\"/>\\n                                        <field name=\\"discount_amount_currency\\" string=\\"Discount Amount\\" optional=\\"hide\\"/>\\n\\n                                        <field name=\\"tax_tag_ids\\" widget=\\"many2many_tags\\" string=\\"Tax Grids\\" optional=\\"show\\" options=\\"{'no_create': True}\\" domain=\\"[                                                     ('applicability', '=', 'taxes'),                                                     '|', ('country_id', '=', parent.tax_country_id),                                                     ('country_id', '=', False),                                                 ]\\"/>\\n\\n                                        <!-- Others fields -->\\n                                        <field name=\\"tax_line_id\\" column_invisible=\\"True\\"/>\\n                                        <field name=\\"company_currency_id\\" column_invisible=\\"True\\"/>\\n                                        <field name=\\"display_type\\" force_save=\\"1\\" column_invisible=\\"True\\"/>\\n                                        <field name=\\"company_id\\" column_invisible=\\"True\\"/>\\n                                        <field name=\\"sequence\\" column_invisible=\\"True\\"/>\\n                                        <field name=\\"id\\" column_invisible=\\"True\\"/>\\n                                        <field name=\\"account_internal_group\\" column_invisible=\\"True\\"/>\\n                                        <field name=\\"account_type\\" column_invisible=\\"True\\"/>\\n                                    </list>\\n                                    <!-- Form view to cover mobile use -->\\n                                    <form>\\n                                      <group>\\n                                        <field name=\\"account_id\\" domain=\\"[('company_ids', 'parent_of', company_id)]\\"/>\\n                                        <field name=\\"partner_id\\" domain=\\"['|', ('parent_id', '=', False), ('is_company', '=', True)]\\"/>\\n                                        <field name=\\"name\\"/>\\n                                        <field name=\\"analytic_distribution\\" widget=\\"analytic_distribution\\" groups=\\"analytic.group_analytic_accounting\\"/>\\n                                        <field name=\\"amount_currency\\" groups=\\"base.group_multi_currency\\"/>\\n                                        <field name=\\"company_currency_id\\" invisible=\\"1\\"/>\\n                                        <field name=\\"company_id\\" invisible=\\"1\\"/>\\n                                        <field name=\\"currency_id\\" options=\\"{'no_create': True}\\" groups=\\"base.group_multi_currency\\"/>\\n                                        <field name=\\"debit\\" sum=\\"Total Debit\\"/>\\n                                        <field name=\\"credit\\" sum=\\"Total Credit\\"/>\\n                                        <field name=\\"balance\\" invisible=\\"1\\"/>\\n                                        <field name=\\"tax_ids\\" string=\\"Taxes Applied\\" widget=\\"many2many_tax_tags\\" options=\\"{'no_create': True}\\" domain=\\"[('type_tax_use', '=?', parent.invoice_filter_type_domain), ('company_id', 'parent_of', parent.company_id)]\\" context=\\"{                                                     'append_fields': not parent.invoice_filter_type_domain and ['type_tax_use'],                                                     'active_test': True,                                                }\\"/>\\n                                        <field name=\\"date_maturity\\" required=\\"0\\" invisible=\\"context.get('view_no_maturity', False)\\"/>\\n                                      </group>\\n                                    </form>\\n                                </field>\\n                                <div class=\\"alert alert-info text-center mb-0\\" role=\\"alert\\" invisible=\\"payment_state != 'invoicing_legacy' or move_type == 'entry'\\">\\n                                    <span>This entry has been generated through the Invoicing app, before installing Accounting. Its balance has been imported separately.</span>\\n                                </div>\\n                            </page>\\n                            <page id=\\"other_tab\\" string=\\"Other Info\\" name=\\"other_info\\" invisible=\\"move_type == 'entry'\\">\\n                                <group id=\\"other_tab_group\\">\\n                                    <group string=\\"Invoice\\" name=\\"sale_info_group\\" invisible=\\"move_type not in ('out_invoice', 'out_refund')\\">\\n                                        <label for=\\"ref\\" string=\\"Customer Reference\\"/>\\n                                        <field name=\\"ref\\" nolabel=\\"1\\"/>\\n                                        <field name=\\"user_id\\" invisible=\\"1\\" force_save=\\"1\\"/>\\n                                        <field name=\\"invoice_user_id\\" domain=\\"[('share', '=', False)]\\" widget=\\"many2one_avatar_user\\"/>\\n                                        <field name=\\"invoice_origin\\" string=\\"Source Document\\" force_save=\\"1\\" invisible=\\"1\\"/>\\n                                        <field name=\\"partner_bank_id\\" widget=\\"many2one_bank\\" context=\\"{'default_partner_id': bank_partner_id}\\" domain=\\"[('partner_id.ref_company_ids', 'parent_of', company_id)]\\" invisible=\\"move_type != 'out_invoice'\\" readonly=\\"is_move_sent and state != 'draft'\\"/>\\n                                        <field name=\\"partner_bank_id\\" context=\\"{'default_partner_id': bank_partner_id, 'display_account_trust': True}\\" domain=\\"[('partner_id', '=', bank_partner_id)]\\" invisible=\\"move_type != 'out_refund'\\" readonly=\\"is_move_sent and state != 'draft'\\"/>\\n                                        <field name=\\"payment_reference\\" invisible=\\"move_type not in ('out_invoice', 'out_refund')\\" readonly=\\"inalterable_hash\\" placeholder=\\"Standard communication\\"/>\\n                                        <field name=\\"qr_code_method\\" invisible=\\"not display_qr_code\\"/>\\n                                        <field name=\\"delivery_date\\" readonly=\\"state != 'draft'\\"/>\\n                                    </group>\\n                                    <group string=\\"Accounting\\" name=\\"accounting_info_group\\">\\n                                        <field name=\\"company_id\\" groups=\\"base.group_multi_company\\" domain=\\"[('id', 'child_of', journal_company_id)]\\"/>\\n                                        <field name=\\"invoice_incoterm_placeholder\\" invisible=\\"1\\"/>    <!-- Needed for placeholder_field -->\\n                                        <field name=\\"invoice_incoterm_id\\" options=\\"{'placeholder_field': 'invoice_incoterm_placeholder'}\\" invisible=\\"move_type in ('out_receipt', 'in_receipt')\\"/>\\n                                        <field name=\\"incoterm_location\\" invisible=\\"move_type in ('out_receipt', 'in_receipt')\\"/>\\n                                        <field name=\\"fiscal_position_id\\" readonly=\\"state in ['cancel', 'posted']\\"/>\\n                                        <field name=\\"secured\\" groups=\\"account.group_account_secured,base.group_no_one\\"/>\\n                                        <field name=\\"preferred_payment_method_line_id\\" string=\\"Payment Method\\" domain=\\"[('payment_type', '=', 'inbound'), ('company_id', 'parent_of', company_id)]\\" invisible=\\"move_type in ('in_invoice', 'in_refund', 'in_receipt')\\"/>\\n                                        <field name=\\"preferred_payment_method_line_id\\" string=\\"Payment Method\\" domain=\\"[('payment_type', '=', 'outbound'), ('company_id', 'parent_of', company_id)]\\" invisible=\\"move_type in ('out_invoice', 'out_refund', 'out_receipt')\\"/>\\n                                        <field name=\\"invoice_source_email\\" widget=\\"email\\" invisible=\\"move_type not in ('in_invoice', 'in_refund') or not invoice_source_email\\"/>\\n                                        <field name=\\"auto_post\\" invisible=\\"move_type in ('out_receipt', 'in_receipt')\\" readonly=\\"state != 'draft'\\"/>\\n                                        <field name=\\"auto_post_until\\" invisible=\\"auto_post in ('no', 'at_date')\\" readonly=\\"state != 'draft'\\"/>\\n                                    </group>\\n                                </group>\\n                            </page>\\n                            <page id=\\"other_tab_entry\\" string=\\"Other Info\\" name=\\"other_info\\" invisible=\\"move_type != 'entry'\\">\\n                                <group id=\\"other_tab_entry_group\\">\\n                                    <group name=\\"misc_group\\">\\n                                        <field name=\\"auto_post\\" invisible=\\"move_type != 'entry'\\" readonly=\\"state != 'draft'\\"/>\\n                                        <field name=\\"reversed_entry_id\\" invisible=\\"move_type != 'entry' or not reversed_entry_id\\"/>\\n                                        <field name=\\"auto_post_until\\" invisible=\\"auto_post in ('no', 'at_date')\\" readonly=\\"state != 'draft'\\"/>\\n                                    </group>\\n                                    <group>\\n                                        <field name=\\"fiscal_position_id\\" readonly=\\"state in ['cancel', 'posted']\\"/>\\n                                        <field name=\\"company_id\\" groups=\\"base.group_multi_company\\" required=\\"1\\"/>\\n                                    </group>\\n                                </group>\\n                                <!-- Internal note -->\\n                                <field name=\\"narration\\" placeholder=\\"Add an internal note...\\" nolabel=\\"1\\" height=\\"50\\"/>\\n                            </page>\\n                        </notebook>\\n                    </sheet>\\n                    <!-- Attachment preview -->\\n                    <div class=\\"o_attachment_preview\\" invisible=\\"move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund') or state != 'draft'\\"/>\\n                    <!-- Chatter -->\\n                    <chatter reload_on_attachment=\\"True\\"/>\\n                </form>", "es_ES": "<form string=\\"Asiento contable\\" js_class=\\"account_move_form\\">\\n                    <header>\\n                        <!-- Post -->\\n                        <button name=\\"action_post\\" string=\\"Publicación\\" class=\\"oe_highlight\\" type=\\"object\\" groups=\\"account.group_account_invoice\\" data-hotkey=\\"q\\" context=\\"{'validate_analytic': True, 'disable_abnormal_invoice_detection': False}\\" invisible=\\"hide_post_button or move_type != 'entry'\\"/>\\n                        <button name=\\"action_post\\" string=\\"Confirmar\\" class=\\"oe_highlight\\" type=\\"object\\" groups=\\"account.group_account_invoice\\" data-hotkey=\\"q\\" context=\\"{'validate_analytic': True, 'disable_abnormal_invoice_detection': False}\\" invisible=\\"hide_post_button or move_type == 'entry' or display_inactive_currency_warning\\"/>\\n                        <!-- Send (only invoices) -->\\n                        <button name=\\"action_invoice_sent\\" type=\\"object\\" string=\\"Enviar\\" invisible=\\"not display_send_button or not highlight_send_button\\" class=\\"oe_highlight\\" data-hotkey=\\"y\\"/>\\n                        <button name=\\"action_invoice_sent\\" type=\\"object\\" string=\\"Enviar\\" invisible=\\"not display_send_button or highlight_send_button\\" data-hotkey=\\"y\\"/>\\n                        <button name=\\"action_print_pdf\\" type=\\"object\\" class=\\"oe_highlight\\" invisible=\\"state != 'posted' or is_being_sent or invoice_pdf_report_id or move_type in ('entry', 'in_invoice','in_refund','in_receipt')\\" string=\\"Imprimir\\" data-hotkey=\\"p\\"/>\\n                        <button name=\\"action_print_pdf\\" type=\\"object\\" invisible=\\"state != 'posted' or (not is_being_sent and not invoice_pdf_report_id) or move_type in ('in_invoice','in_refund','in_receipt')\\" string=\\"Imprimir\\" data-hotkey=\\"p\\"/>\\n                        <!-- Register Payment (only invoices / receipts) -->\\n                        <button name=\\"action_register_payment\\" id=\\"account_invoice_payment_btn\\" type=\\"object\\" class=\\"oe_highlight\\" invisible=\\"(                                     state != 'posted'                                     or payment_state not in ('not_paid', 'partial', 'in_payment')                                     or move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')                                     or invoice_has_outstanding                                 )\\" context=\\"{'dont_redirect_to_payments': True}\\" string=\\"Pagar\\" data-hotkey=\\"g\\" groups=\\"account.group_account_invoice\\"/>\\n                        <!-- Register Payment (only invoices / receipts, with outstanding payments) -->\\n                        <button name=\\"action_register_payment\\" id=\\"account_invoice_payment_secondary_btn\\" type=\\"object\\" invisible=\\"(                                     state != 'posted'                                     or payment_state not in ('not_paid', 'partial', 'in_payment')                                     or move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')                                     or not invoice_has_outstanding                                 )\\" context=\\"{'dont_redirect_to_payments': True}\\" string=\\"Pagar\\" data-hotkey=\\"g\\" groups=\\"account.group_account_invoice\\"/>\\n                        <!-- Preview (only customer invoices) -->\\n                        <button name=\\"preview_invoice\\" type=\\"object\\" string=\\"Vista previa\\" data-hotkey=\\"o\\" invisible=\\"move_type not in ('out_invoice', 'out_refund') or state in ('draft', 'cancel')\\"/>\\n                        <!-- Reverse -->\\n                        <button name=\\"256\\" string=\\"Revertir asiento\\" type=\\"action\\" groups=\\"account.group_account_invoice\\" data-hotkey=\\"z\\" invisible=\\"move_type != 'entry' or state != 'posted' or payment_state == 'reversed'\\"/>\\n                        <button name=\\"action_reverse\\" string=\\"Factura rectificativa\\" type=\\"object\\" groups=\\"account.group_account_invoice\\" invisible=\\"move_type not in ('out_invoice', 'in_invoice') or state != 'posted'\\" data-hotkey=\\"shift+n\\"/>\\n                        <!-- Cancel -->\\n                        <button name=\\"button_cancel\\" string=\\"Cancelar asiento\\" type=\\"object\\" groups=\\"account.group_account_invoice\\" data-hotkey=\\"x\\" invisible=\\"not id or state != 'draft' or move_type != 'entry'\\"/>\\n                        <button name=\\"button_cancel\\" string=\\"Cancelar\\" type=\\"object\\" groups=\\"account.group_account_invoice\\" data-hotkey=\\"x\\" invisible=\\"not id or state != 'draft' or move_type == 'entry'\\"/>\\n                        <button name=\\"button_draft\\" string=\\"Restablecer a borrador\\" type=\\"object\\" groups=\\"account.group_account_invoice\\" invisible=\\"not show_reset_to_draft_button\\" data-hotkey=\\"r\\"/>\\n                        <button name=\\"button_hash\\" string=\\"Bloquear\\" type=\\"object\\" groups=\\"account.group_account_invoice\\" invisible=\\"not restrict_mode_hash_table or inalterable_hash or state != 'posted'\\"/>\\n                        <button string=\\"Solicitud de cancelación\\" name=\\"button_request_cancel\\" type=\\"object\\" groups=\\"account.group_account_invoice\\" invisible=\\"state != 'posted' or show_reset_to_draft_button or not need_cancel_request\\" data-hotkey=\\"w\\"/>\\n                        <!-- Reload Data from attachment -->\\n                        <button name=\\"action_reload_imported_data\\" string=\\"Reload Data\\" type=\\"object\\" invisible=\\"state != 'draft'                                            or move_type not in ('in_invoice', 'in_refund', 'in_receipt', 'out_invoice', 'out_refund', 'out_receipt')                                            or not import_source_attachment_id\\"/>\\n                        <!-- Review button -->\\n                        <field name=\\"review_state\\" widget=\\"account_review_state_selection_badge\\" options=\\"{                                    'no_review': {'can_edit': 'account.group_account_user,account.group_account_manager'},                                    'todo': {'decoration': 'info'},                                    'reviewed': {'decoration': 'success'},                                    'supervised': {'decoration': 'success', 'can_edit': 'account.group_account_manager'},                                    'anomaly': {'decoration': 'danger'},                                }\\" class=\\"ms-auto me-3 align-self-center\\" invisible=\\"state != 'posted'\\" groups=\\"account.group_account_user\\"/>\\n                        <field name=\\"state\\" widget=\\"statusbar\\" statusbar_visible=\\"draft,posted\\" groups=\\"!account.group_account_secured\\"/>\\n                        <field name=\\"state\\" widget=\\"account_move_statusbar_secured\\" statusbar_visible=\\"draft,posted\\" groups=\\"account.group_account_secured\\"/>\\n                    </header>\\n\\n                    <!-- General warnings computed from `_get_alerts` -->\\n                    <div class=\\"m-0\\" id=\\"alerts\\" invisible=\\"not alerts\\">\\n                        <field name=\\"alerts\\" class=\\"o_field_html\\" widget=\\"actionable_errors\\"/>\\n                    </div>\\n                    <!--Duplicate check-->\\n                    <div class=\\"d-flex alert alert-danger w-100 d-flex align-items-center gap-1\\" invisible=\\"not is_exact_move_duplicate\\" role=\\"alert\\">\\n                        <span>Puede que este documento sea un duplicado de</span>\\n                        <field name=\\"duplicated_ref_ids\\" widget=\\"x2many_buttons\\" nb_records_shown=\\"1\\" string=\\"Documentos duplicados\\" context=\\"{'name_as_amount_total': True}\\"/>\\n                        <button name=\\"action_delete_duplicates\\" type=\\"object\\" class=\\"btn btn-link text-danger ms-auto d-flex align-items-center gap-1\\" invisible=\\"not has_draft_move_duplicate\\">\\n                            <i class=\\"oi oi-filled text-danger\\" data-icon=\\"delete\\"/>\\n                            <span class=\\"text-danger\\" invisible=\\"duplicated_ref_ids.length == 1\\">Eliminar todos los duplicados</span>\\n                            <span class=\\"text-danger\\" invisible=\\"duplicated_ref_ids.length &gt; 1\\">Eliminar duplicado</span>\\n                        </button>\\n                    </div>\\n                    <div class=\\"d-flex alert alert-warning w-100 d-flex align-items-center gap-1\\" invisible=\\"not duplicated_ref_ids or is_exact_move_duplicate or state != 'draft'\\" role=\\"alert\\">\\n                        <span>Puede que este documento sea un duplicado de</span>\\n                        <field name=\\"duplicated_ref_ids\\" widget=\\"x2many_buttons\\" nb_records_shown=\\"1\\" string=\\"Documentos duplicados\\" context=\\"{'name_as_amount_total': True}\\"/>\\n                        <button name=\\"action_delete_duplicates\\" type=\\"object\\" class=\\"btn btn-link text-danger ms-auto d-flex align-items-center gap-1\\" invisible=\\"not has_draft_move_duplicate\\">\\n                            <i class=\\"oi oi-filled text-danger\\" data-icon=\\"delete\\"/>\\n                            <span class=\\"text-danger\\" invisible=\\"duplicated_ref_ids.length == 1\\">Eliminar todos los duplicados</span>\\n                            <span class=\\"text-danger\\" invisible=\\"duplicated_ref_ids.length &gt; 1\\">Eliminar duplicado</span>\\n                        </button>\\n                    </div>\\n                    <!-- Invoice outstanding credits -->\\n                    <div groups=\\"account.group_account_invoice,account.group_account_readonly\\" class=\\"alert alert-info\\" role=\\"alert\\" invisible=\\"move_type not in ('out_invoice', 'out_receipt') or not invoice_has_outstanding or payment_state not in ('not_paid', 'partial')\\">\\n                        Tiene <bold><a class=\\"alert-link\\" href=\\"#outstanding\\" role=\\"button\\">créditos pendientes</a></bold> que encuentra a continuación para este cliente.\\n                    </div>\\n                    <div groups=\\"account.group_account_invoice,account.group_account_readonly\\" class=\\"alert alert-info\\" role=\\"alert\\" invisible=\\"move_type not in ('in_invoice', 'in_receipt') or not invoice_has_outstanding or payment_state not in ('not_paid', 'partial')\\">\\n                        Tiene <bold><a class=\\"alert-link\\" href=\\"#outstanding\\" role=\\"button\\">débitos pendientes</a></bold> que encuentra a continuación para este proveedor.\\n                    </div>\\n                    <div groups=\\"account.group_account_invoice,account.group_account_readonly\\" class=\\"alert alert-info\\" role=\\"alert\\" invisible=\\"move_type != 'out_refund' or not invoice_has_outstanding or payment_state not in ('not_paid', 'partial')\\">\\n                        Tiene <bold><a class=\\"alert-link\\" href=\\"#outstanding\\" role=\\"button\\">débitos pendientes</a></bold> que encuentra a continuación para este cliente.\\n                    </div>\\n                    <div groups=\\"account.group_account_invoice,account.group_account_readonly\\" class=\\"alert alert-info\\" role=\\"alert\\" invisible=\\"move_type != 'in_refund' or not invoice_has_outstanding or payment_state not in ('not_paid', 'partial')\\">\\n                        Tiene <bold><a class=\\"alert-link\\" href=\\"#outstanding\\" role=\\"button\\">créditos pendientes</a></bold> que encuentra a continuación para este proveedor.\\n                    </div>\\n                    <!-- Currency consistency -->\\n                    <div class=\\"alert alert-warning\\" role=\\"alert\\" invisible=\\"not display_inactive_currency_warning or move_type not in ('in_invoice', 'in_refund', 'in_receipt')\\">\\n                        Para validar esta factura, debe <button class=\\"oe_link\\" type=\\"object\\" name=\\"action_activate_currency\\" style=\\"padding: 0; vertical-align: baseline;\\">activar la moneda de la factura</button>. Odoo debe calcular los asientos contables antes de contabilizarlas en la moneda de su empresa.\\n                    </div>\\n                    <div class=\\"alert alert-warning\\" role=\\"alert\\" invisible=\\"not display_inactive_currency_warning or move_type not in ('out_invoice', 'out_refund', 'out_receipt')\\">\\n                        Para validar esta factura, debe <button class=\\"oe_link\\" type=\\"object\\" name=\\"action_activate_currency\\" style=\\"padding: 0; vertical-align: baseline;\\">activar la moneda de la factura</button>. Odoo debe calcular los asientos contables antes de contabilizarlas en la moneda de su empresa.\\n                    </div>\\n\\n                    <sheet>\\n                        <div name=\\"button_box\\" class=\\"oe_button_box\\">\\n                            <button name=\\"action_open_business_doc\\" class=\\"oe_stat_button\\" icon=\\"menu\\" type=\\"object\\" invisible=\\"move_type != 'entry' or not id or not origin_payment_id\\">\\n                                    <div class=\\"o_stat_info\\">\\n                                        <span class=\\"o_stat_text\\">1 pago</span>\\n                                    </div>\\n                            </button>\\n                            <button name=\\"open_payments\\" groups=\\"account.group_account_invoice,account.group_account_readonly\\" class=\\"oe_stat_button\\" icon=\\"menu\\" type=\\"object\\" invisible=\\"not payment_count\\">\\n                                    <field name=\\"payment_count\\" string=\\"Pagos\\" widget=\\"statinfo\\"/>\\n                            </button>\\n                            <button name=\\"open_reconcile_view\\" class=\\"oe_stat_button\\" icon=\\"menu\\" type=\\"object\\" invisible=\\"move_type != 'entry' or not id or not has_reconciled_entries\\">\\n                                    <div class=\\"o_stat_info\\">\\n                                        <span class=\\"o_stat_text\\">Apuntes conciliados</span>\\n                                    </div>\\n                            </button>\\n                            <button name=\\"open_created_caba_entries\\" class=\\"oe_stat_button\\" icon=\\"attach_money\\" type=\\"object\\" invisible=\\"not tax_cash_basis_created_move_ids\\">\\n                                    <div class=\\"o_stat_info\\">\\n                                        <span class=\\"o_stat_text\\">Asientos del criterio de caja</span>\\n                                    </div>\\n                            </button>\\n                            <button name=\\"open_adjusting_entries\\" class=\\"oe_stat_button\\" icon=\\"menu\\" type=\\"object\\" invisible=\\"not adjusting_entries_move_ids\\">\\n                                    <field name=\\"adjusting_entries_count\\" string=\\"Asientos de ajuste\\" widget=\\"statinfo\\"/>\\n                            </button>\\n                            <button name=\\"open_adjusting_entry_origin_moves\\" class=\\"oe_stat_button\\" icon=\\"menu\\" type=\\"object\\" invisible=\\"not adjusting_entry_origin_move_ids\\">\\n                                    <div invisible=\\"adjusting_entry_origin_moves_count != 1\\" class=\\"o_stat_info\\">\\n                                        <span class=\\"o_stat_text\\">\\n                                            <field name=\\"adjusting_entry_origin_label\\"/>\\n                                        </span>\\n                                    </div>\\n                                    <field name=\\"adjusting_entry_origin_moves_count\\" invisible=\\"adjusting_entry_origin_moves_count == 1\\" string=\\"Facturas\\" widget=\\"statinfo\\"/>\\n                            </button>\\n                            <button name=\\"open_journal_items\\" groups=\\"account.group_account_invoice,account.group_account_readonly\\" invisible=\\"move_type == 'entry'\\" class=\\"oe_stat_button\\" icon=\\"menu\\" type=\\"object\\">\\n                                    <div class=\\"o_stat_info\\">\\n                                        <span class=\\"o_stat_text\\">Apuntes contables</span>\\n                                    </div>\\n                            </button>\\n                            <button name=\\"action_open_reversal_moves\\" class=\\"oe_stat_button\\" icon=\\"edit_square\\" type=\\"object\\" invisible=\\"reversal_move_count == 0\\">\\n                                <field name=\\"reversal_move_count\\" string=\\"Facturas rectificativas\\" widget=\\"statinfo\\" invisible=\\"move_type != 'out_invoice'\\"/>\\n                                <field name=\\"reversal_move_count\\" string=\\"Reembolsos\\" widget=\\"statinfo\\" invisible=\\"move_type != 'in_invoice'\\"/>\\n                                <field name=\\"reversal_move_count\\" string=\\"Reversal Entries\\" widget=\\"statinfo\\" invisible=\\"move_type != 'entry'\\"/>\\n                            </button>\\n                            <button name=\\"action_open_reversed_entry\\" class=\\"oe_stat_button\\" icon=\\"edit_square\\" type=\\"object\\" invisible=\\"not reversed_entry_id\\">\\n                                <span class=\\"o_stat_text\\" invisible=\\"move_type != 'out_refund'\\">Invoice</span>\\n                                <span class=\\"o_stat_text\\" invisible=\\"move_type != 'in_refund'\\">Vendor Bill</span>\\n                                <span class=\\"o_stat_text\\" invisible=\\"move_type != 'entry'\\">Journal Entry</span>\\n                            </button>\\n                        </div>\\n\\n                        <widget name=\\"web_ribbon\\" title=\\"Enviado\\" bg_color=\\"gray_ribbon\\" invisible=\\"not is_move_sent or payment_state != 'not_paid' or move_type not in ('out_invoice', 'out_refund', 'out_receipt')\\"/>\\n                        <!-- Payment status for invoices / receipts -->\\n                        <widget name=\\"web_ribbon\\" title=\\"Enviado\\" bg_color=\\"text-bg-300\\" invisible=\\"status_in_payment != 'sent' or move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')\\"/>\\n                        <widget name=\\"web_ribbon\\" title=\\"Pagado\\" invisible=\\"payment_state != 'paid' or move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')\\"/>\\n                        <widget name=\\"web_ribbon\\" title=\\"En proceso de pago\\" invisible=\\"payment_state != 'in_payment' or move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')\\"/>\\n                        <widget name=\\"web_ribbon\\" title=\\"Parcial\\" bg_color=\\"text-bg-300\\" invisible=\\"payment_state != 'partial' or move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')\\"/>\\n                        <widget name=\\"web_ribbon\\" title=\\"Revertido\\" invisible=\\"payment_state != 'reversed'\\"/>\\n                        <widget name=\\"web_ribbon\\" title=\\"Bloqueado\\" bg_color=\\"text-bg-danger\\" invisible=\\"payment_state != 'blocked' or move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')\\"/>\\n                         <widget name=\\"web_ribbon\\" text=\\"Invoicing App Legacy\\" bg_color=\\"text-bg-info\\" invisible=\\"payment_state != 'invoicing_legacy'\\" tooltip=\\"This entry has been generated through the Invoicing app, before installing Accounting. It has been disabled by the 'Invoicing Switch Threshold Date' setting so that it does not impact your accounting.\\"/>\\n\\n                        <!-- Invisible fields -->\\n                        <field name=\\"id\\" invisible=\\"1\\"/>\\n                        <field name=\\"state\\" invisible=\\"1\\"/>\\n                        <field name=\\"company_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"journal_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"show_name_warning\\" invisible=\\"1\\"/>\\n                        <field name=\\"posted_before\\" invisible=\\"1\\"/>\\n                        <field name=\\"import_source_attachment_id\\" invisible=\\"1\\"/>\\n                        <!--test-tags .test_01_account_tour -->\\n                        <field name=\\"move_type\\" invisible=\\"1\\" force_save=\\"1\\"/>\\n                        <field name=\\"payment_state\\" invisible=\\"1\\" force_save=\\"1\\"/>\\n                        <field name=\\"invoice_filter_type_domain\\" invisible=\\"1\\"/>\\n                        <field name=\\"suitable_journal_ids\\" invisible=\\"1\\"/>\\n                        <field name=\\"currency_id\\" invisible=\\"1\\" readonly=\\"state in ['cancel', 'posted']\\"/>\\n                        <field name=\\"company_currency_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"commercial_partner_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"bank_partner_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"display_qr_code\\" invisible=\\"1\\"/>\\n                        <field name=\\"show_reset_to_draft_button\\" invisible=\\"1\\"/>\\n                        <field name=\\"expected_currency_rate\\" invisible=\\"1\\"/>\\n\\n                        <field name=\\"invoice_has_outstanding\\" invisible=\\"1\\"/>\\n                        <field name=\\"is_move_sent\\" invisible=\\"1\\"/>\\n                        <field name=\\"invoice_pdf_report_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"need_cancel_request\\" invisible=\\"1\\"/>\\n                        <field name=\\"has_reconciled_entries\\" invisible=\\"1\\"/>\\n                        <field name=\\"restrict_mode_hash_table\\" invisible=\\"1\\"/>\\n                        <field name=\\"inalterable_hash\\" invisible=\\"1\\"/>\\n                        <field name=\\"country_code\\" invisible=\\"1\\"/>\\n                        <field name=\\"display_inactive_currency_warning\\" invisible=\\"1\\"/>\\n                        <field name=\\"statement_line_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"statement_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"origin_payment_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"tax_country_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"tax_calculation_rounding_method\\" invisible=\\"1\\"/>\\n                        <field name=\\"tax_cash_basis_created_move_ids\\" invisible=\\"1\\"/>\\n                        <field name=\\"quick_edit_mode\\" invisible=\\"1\\"/>\\n                        <field name=\\"invoice_cash_rounding_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"hide_post_button\\" invisible=\\"1\\"/>\\n                        <field name=\\"quick_encoding_vals\\" invisible=\\"1\\"/>\\n                        <field name=\\"show_delivery_date\\" invisible=\\"1\\"/>\\n                        <field name=\\"is_being_sent\\" invisible=\\"1\\"/>\\n                        <field name=\\"show_update_fpos\\" invisible=\\"1\\"/>\\n                        <field name=\\"company_vat_disabled\\" invisible=\\"1\\"/>\\n\\n                        <div class=\\"oe_title\\">\\n                            <span class=\\"o_form_label\\">\\n                                <field name=\\"move_type\\" invisible=\\"move_type == 'entry' or is_self_billing\\" widget=\\"receipt_selector\\" options=\\"{'horizontal': true}\\" nolabel=\\"1\\" readonly=\\"state != 'draft'\\"/>\\n                            </span>\\n\\n                            <div class=\\"text-warning\\" invisible=\\"not show_name_warning\\">El número más alto actual es <field class=\\"oe_inline\\" name=\\"highest_name\\"/>. Es posible que desee poner un número más alto aquí.</div>\\n\\n                            <h1>\\n                                <field name=\\"name\\" invisible=\\"not (name or name_placeholder or document_sequence_editable)\\" readonly=\\"state != 'draft'\\" options=\\"{'placeholder_field': 'name_placeholder'}\\"/>\\n\\n                                <span invisible=\\"name or name_placeholder or document_sequence_editable\\">Borrador</span>\\n                            </h1>\\n                        </div>\\n                        <group>\\n                            <group id=\\"header_left_group\\">\\n\\n                                <label for=\\"partner_id\\" string=\\"Cliente\\" style=\\"font-weight:bold;\\" invisible=\\"move_type not in ('out_invoice', 'out_refund', 'out_receipt')\\"/>\\n                                <label for=\\"partner_id\\" string=\\"Proveedor\\" style=\\"font-weight:bold;\\" invisible=\\"move_type not in ('in_invoice', 'in_refund', 'in_receipt')\\"/>\\n                                <div class=\\"o_col\\" invisible=\\"move_type not in ('out_invoice', 'out_refund', 'out_receipt', 'in_invoice', 'in_refund', 'in_receipt')\\">\\n                                    <field name=\\"partner_id\\" widget=\\"res_partner_many2one\\" nolabel=\\"1\\" context=\\"{                                             'res_partner_search_mode': (context.get('default_move_type', 'entry') in ('out_invoice', 'out_refund', 'out_receipt') and 'customer') or (context.get('default_move_type', 'entry') in ('in_invoice', 'in_refund', 'in_receipt') and 'supplier') or False,                                             'show_address': 1, 'default_is_company': True, 'show_identifier': True}\\" options=\\"{&quot;no_quick_create&quot;: True}\\" default_focus=\\"1\\" invisible=\\"move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')\\" placeholder=\\"Buscar nombre o NIF...\\" readonly=\\"state != 'draft'\\"/>\\n                                    <button name=\\"action_update_fpos_values\\" type=\\"object\\" string=\\"Actualizar impuestos y cuentas\\" help=\\"Vuelva a calcular todos los impuestos y cuentas según la posición fiscal\\" class=\\"btn-link mb-1 px-0\\" icon=\\"refresh\\" invisible=\\"not show_update_fpos or state in ['cancel', 'posted']\\"/>\\n                                </div>\\n\\n                                <field name=\\"partner_shipping_id\\" groups=\\"account.group_delivery_invoice_address\\" invisible=\\"move_type not in ('out_invoice', 'out_refund', 'out_receipt')\\" readonly=\\"state != 'draft'\\"/>\\n                                <field name=\\"quick_edit_total_amount\\" class=\\"w-50\\" invisible=\\"move_type == 'entry' or not quick_edit_mode\\" readonly=\\"state != 'draft'\\"/>\\n                                <label for=\\"ref\\" string=\\"Referencia de factura\\" invisible=\\"move_type not in ('in_invoice', 'in_receipt', 'in_refund')\\"/>\\n                                <field name=\\"ref\\" default_focus=\\"1\\" nolabel=\\"1\\" invisible=\\"move_type not in ('in_invoice', 'in_receipt', 'in_refund')\\"/>\\n                                <field name=\\"ref\\" default_focus=\\"1\\" invisible=\\"move_type != 'entry'\\"/>\\n                                <field name=\\"tax_cash_basis_origin_move_id\\" invisible=\\"not tax_cash_basis_origin_move_id\\"/>\\n                                <field name=\\"invoice_vendor_bill_id\\" string=\\"Autocompletar\\" class=\\"oe_edit_only\\" invisible=\\"not show_invoice_vendor_bill\\" domain=\\"([('partner_id', 'child_of', [partner_id])] if partner_id else []) + [                                            ('company_id', '=', company_id),                                            ('move_type', '=', move_type)                                        ]\\" placeholder=\\"Selecciona un documento de compra antiguo\\" options=\\"{'no_create': True}\\" context=\\"{'show_total_amount': True}\\"/>\\n                            </group>\\n                            <group id=\\"header_right_group\\">\\n                                <label for=\\"invoice_date\\" string=\\"Fecha de factura\\" style=\\"font-weight:bold;\\" invisible=\\"move_type not in ('out_invoice', 'out_refund', 'out_receipt')\\"/>\\n                                <field name=\\"invoice_date\\" nolabel=\\"1\\" options=\\"{'warning': 'future'}\\" invisible=\\"move_type not in ('out_invoice', 'out_refund', 'out_receipt')\\" readonly=\\"state != 'draft'\\" placeholder=\\"Hoy\\"/>\\n\\n                                <label for=\\"invoice_date\\" string=\\"Fecha de la factura\\" style=\\"font-weight:bold;\\" invisible=\\"move_type not in ('in_invoice', 'in_refund', 'in_receipt')\\"/>\\n                                <field name=\\"invoice_date\\" nolabel=\\"1\\" options=\\"{'warning': 'future'}\\" invisible=\\"move_type not in ('in_invoice', 'in_refund', 'in_receipt')\\" required=\\"move_type in ('in_invoice', 'in_refund', 'in_receipt')\\" readonly=\\"state != 'draft'\\"/>\\n\\n                                <field name=\\"date\\" string=\\"Fecha contable\\" invisible=\\"move_type in ('out_invoice', 'out_refund', 'out_receipt') and not quick_edit_mode and not (state == 'posted' and date != invoice_date)\\" readonly=\\"state != 'draft'\\"/>\\n                                <field name=\\"payment_reference\\" invisible=\\"move_type not in ('in_invoice', 'in_refund', 'in_receipt')\\" readonly=\\"inalterable_hash != False\\" placeholder=\\"Usar referencia de factura\\"/>\\n                                <field name=\\"partner_bank_id\\" widget=\\"many2one_bank\\" context=\\"{'default_partner_id': bank_partner_id}\\" domain=\\"[('partner_id', '=', bank_partner_id)]\\" invisible=\\"move_type not in ('in_invoice', 'in_refund', 'in_receipt')\\" readonly=\\"is_move_sent and state != 'draft'\\"/>\\n\\n                                <!-- Invoice payment terms (only invoices) + due date (only invoices / receipts) -->\\n                                <div class=\\"o_td_label\\" invisible=\\"move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')\\">\\n                                    <label for=\\"invoice_date_due\\" string=\\"Fecha de vencimiento\\" invisible=\\"invoice_payment_term_id\\"/>\\n                                    <label for=\\"invoice_payment_term_id\\" string=\\"Condiciones de pago\\" invisible=\\"not invoice_payment_term_id\\"/>\\n                                </div>\\n                                <div class=\\"d-flex\\" invisible=\\"move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')\\" name=\\"due_date\\">\\n                                    <field name=\\"invoice_date_due\\" force_save=\\"1\\" placeholder=\\"Fecha\\" invisible=\\"invoice_payment_term_id\\" decoration-danger=\\"invoice_date_due and invoice_date_due &lt; context_today().strftime('%Y-%m-%d') and payment_state not in ('paid', 'in_payment', 'reversed')\\"/>\\n                                    <span class=\\"o_form_label mx-3 oe_edit_only text-center\\" style=\\"width: 6ch;\\" invisible=\\"state != 'draft' or invoice_payment_term_id\\">o</span>\\n                                    <field name=\\"invoice_payment_term_id\\" context=\\"{'example_date': invoice_date, 'example_amount': tax_totals['total_amount_currency']}\\" placeholder=\\"Condiciones de pago\\" options=\\"{'no_quick_create':True}\\" readonly=\\"state in ['cancel', 'posted']\\"/>\\n                                </div>\\n                                <field name=\\"taxable_supply_date_placeholder\\" invisible=\\"1\\"/> <!-- Needed for the placeholder widget -->\\n                                <field name=\\"taxable_supply_date\\" invisible=\\"not show_taxable_supply_date\\" readonly=\\"state != 'draft'\\" options=\\"{'placeholder_field': 'taxable_supply_date_placeholder'}\\"/>\\n                                <field name=\\"delivery_date\\" invisible=\\"not show_delivery_date\\" readonly=\\"state != 'draft'\\"/>\\n                                <label for=\\"journal_id\\" invisible=\\"not show_journal\\"/>\\n                                <label for=\\"currency_id\\" groups=\\"base.group_multi_currency\\" invisible=\\"show_journal\\"/>\\n                                <div name=\\"journal_div\\" class=\\"d-flex\\">\\n                                    <field name=\\"journal_id\\" invisible=\\"not show_journal\\" options=\\"{'no_create': True, 'no_open': True}\\" readonly=\\"posted_before and name not in (False, '', '/')\\"/>\\n                                    <div name=\\"in_and_refresh_button_div\\" groups=\\"base.group_multi_currency\\" class=\\"d-flex flex-column mx-3 text-center\\" style=\\"width: 6ch;\\" invisible=\\"move_type == 'entry' or not show_journal\\">\\n                                        <div>en</div>\\n                                        <div class=\\"d-flex flex-column justify-content-center flex-grow-1\\" invisible=\\"state != 'draft' or invoice_currency_rate == expected_currency_rate\\">\\n                                            <button type=\\"object\\" name=\\"refresh_invoice_currency_rate\\" icon=\\"refresh\\" title=\\"Restablece el tipo de cambio al valor predeterminado según la fecha de la factura\\" class=\\"btn btn-link p-0\\"/>\\n                                        </div>\\n                                    </div>\\n                                    <div name=\\"currency_div\\" groups=\\"base.group_multi_currency\\" class=\\"w-100\\" invisible=\\"move_type == 'entry'\\">\\n                                        <div class=\\"d-flex gap-1\\">\\n                                            <field name=\\"currency_id\\" readonly=\\"state != 'draft'\\" class=\\"oe_inline\\" options=\\"{'no_create': True}\\"/>\\n                                            <widget name=\\"account_pick_currency_date\\" invisible=\\"state != 'draft' or currency_id == company_currency_id\\"/>\\n                                        </div>\\n                                        <div name=\\"currency_conversion_div\\" class=\\"d-flex gap-1 text-muted\\" invisible=\\"currency_id == company_currency_id\\">\\n                                            <field name=\\"company_currency_id\\" invisible=\\"1\\"/>\\n                                            <field name=\\"invoice_currency_rate\\" invisible=\\"1\\"/>\\n                                            <widget name=\\"account_currency_exchange_rate\\" readonly=\\"state != 'draft'\\" options=\\"{'rate_field': 'invoice_currency_rate'}\\"/>\\n                                            <div invisible=\\"show_journal or state != 'draft' or invoice_currency_rate == expected_currency_rate\\">\\n                                            <button type=\\"object\\" name=\\"refresh_invoice_currency_rate\\" icon=\\"refresh\\" title=\\"Restablece el tipo de cambio al valor predeterminado según la fecha de la factura\\" class=\\"btn btn-link p-0\\"/>\\n                                        </div>\\n                                        </div>\\n                                    </div>\\n                                </div>\\n                            </group>\\n                            <div>\\n                                <field name=\\"document_tax_mode\\" id=\\"document_tax_mode_mobile\\" class=\\"tax_mode_badge d-md-none\\" widget=\\"document_tax_mode_selector\\" nolabel=\\"True\\" readonly=\\"state != 'draft'\\" required=\\"move_type != 'entry'\\"/>\\n                            </div>\\n                        </group>\\n                        <notebook>\\n                            <page id=\\"invoice_tab\\" name=\\"invoice_tab\\" string=\\"Líneas de factura\\" invisible=\\"move_type == 'entry'\\">\\n                                <div class=\\"position-relative document_tax_mode\\">\\n                                    <field name=\\"document_tax_mode\\" id=\\"document_tax_mode\\" class=\\"overlap_badge_tab tax_mode_badge d-none d-md-block\\" widget=\\"document_tax_mode_selector\\" nolabel=\\"True\\" readonly=\\"state != 'draft'\\" required=\\"move_type != 'entry'\\"/>\\n                                </div>\\n                                <field name=\\"invoice_line_ids\\" widget=\\"product_label_section_and_note_field_o2m\\" mode=\\"list,kanban\\" context=\\"{                                            'default_move_type': context.get('default_move_type'),                                            'journal_id': journal_id,                                            'default_partner_id': commercial_partner_id,                                            'default_currency_id': currency_id or company_currency_id,                                            'default_display_type': 'product',                                            'quick_encoding_vals': quick_encoding_vals,                                            'from_invoice_tab': True,                                        }\\" readonly=\\"state != 'draft'\\" aggregated_fields=\\"price_subtotal,price_total\\" options=\\"{'hide_composition': True, 'hide_prices': True, 'subsections': True}\\">\\n                                    <list name=\\"journal_items\\" editable=\\"bottom\\" string=\\"Apuntes contables\\" default_order=\\"sequence, id\\">\\n                                        <control>\\n                                            <create name=\\"add_line_control\\" string=\\"Añadir una línea\\" data-hotkey=\\"l\\"/>\\n                                            <create name=\\"add_section_control\\" string=\\"Añadir una sección\\" data-hotkey=\\"shift+h\\" context=\\"{'default_display_type': 'line_section'}\\"/>\\n                                            <create name=\\"add_note_control\\" string=\\"Añadir una nota\\" data-hotkey=\\"shift+n\\" context=\\"{'default_display_type': 'line_note'}\\"/>\\n                                            <button name=\\"action_add_from_catalog\\" string=\\"Catálogo\\" data-hotkey=\\"shift+k\\" type=\\"object\\" class=\\"btn-link\\" context=\\"{'order_id': parent.id}\\"/>\\n                                        </control>\\n\\n                                        <!-- Displayed fields -->\\n                                        <field name=\\"sequence\\" widget=\\"handle\\"/>\\n                                        <column name=\\"product_and_description\\">\\n                                            <field name=\\"product_id\\" optional=\\"hide\\" widget=\\"account_product_field\\" domain=\\"                                                     context.get('default_move_type') in ('out_invoice', 'out_refund', 'out_receipt')                                                     and [('sale_ok', '=', True)]                                                     or [('purchase_ok', '=', True)]                                                 \\" placeholder=\\"Search a product\\" invisible=\\"display_type in ('line_section', 'line_subsection', 'line_note')\\"/>\\n                                            <field name=\\"name\\" placeholder=\\"Añadir una descripción\\" decoration-it=\\"display_type == 'product' and product_id\\" optional=\\"show\\" widget=\\"text\\"/>\\n                                            <field name=\\"label\\" widget=\\"account_label_text\\" invisible=\\"display_type in ('line_section', 'line_subsection', 'line_note')\\"/>\\n                                        </column>\\n                                        <field name=\\"account_id\\" context=\\"{                                                     'partner_id': partner_id,                                                     'move_type': parent.move_type,                                                     'search_default_type_asset_fixed': 'in_' in parent.move_type,                                                     'search_default_type_expense': 'in_' in parent.move_type,                                                     'search_default_type_expense_direct_cost': 'in_' in parent.move_type,                                                     'search_default_account_type': 'out_' in parent.move_type and 'income',                                                     'preferred_account_type': 'out_' in parent.move_type and 'income' or 'in_' in parent.move_type and 'expense',                                                     'list_view_ref': 'account.view_account_list_from_entry',                                                     'from_bill': move_type == 'in_invoice',                                                }\\" widget=\\"m2o_cell_with_extra_fields\\" groups=\\"account.group_account_readonly\\" options=\\"{'no_quick_create': True, 'no_open': True, 'parent_field': 'invoice_line_ids'}\\" domain=\\"[('company_ids', 'parent_of', company_id), ('account_type', 'not in', ('asset_cash', 'asset_receivable', 'liability_payable', 'off_balance'))]\\" required=\\"display_type not in ('line_section', 'line_subsection', 'line_note')\\"/>\\n                                        <field name=\\"analytic_distribution\\" widget=\\"analytic_distribution\\" string=\\"Analítico\\" groups=\\"analytic.group_analytic_accounting\\" optional=\\"show\\" options=\\"{'product_field': 'product_id', 'account_field': 'account_id', 'amount_field': 'price_subtotal'}\\" business_domain_compute=\\"parent.move_type in ['out_invoice', 'out_refund', 'out_receipt'] and 'invoice' or parent.move_type in ['in_invoice', 'in_refund', 'in_receipt'] and 'bill' or 'general'\\"/>\\n                                        <field name=\\"quantity\\" optional=\\"show\\"/>\\n                                        <field name=\\"product_uom_id\\" groups=\\"uom.group_uom\\" optional=\\"show\\" width=\\"92px\\" options=\\"{'no_create': True, 'no_open': True, 'quantity_field': 'quantity'}\\" widget=\\"many2one_uom\\"/>\\n                                        <!-- /l10n_in_edi.test_edi_json -->\\n                                        <!-- required for @api.onchange('product_id') -->\\n                                        <field name=\\"product_uom_id\\" column_invisible=\\"True\\"/>\\n                                        <field name=\\"price_unit\\" string=\\"Precio\\"/>\\n                                        <field name=\\"discount\\" width=\\"50px\\" string=\\"% de dto.\\" optional=\\"hide\\"/>\\n                                        <field name=\\"tax_ids\\" widget=\\"many2many_tax_tags\\" domain=\\"[('type_tax_use', '=?', parent.invoice_filter_type_domain), ('company_id', 'parent_of', parent.company_id), ('country_id', '=', parent.tax_country_id)]\\" context=\\"{                                                     'append_fields': not parent.invoice_filter_type_domain and ['type_tax_use'],                                                     'active_test': True,                                                     'dynamic_fiscal_position_id': parent.fiscal_position_id,                                                }\\" options=\\"{'no_create': True}\\" optional=\\"show\\"/>\\n                                        <field name=\\"deductible_percentage\\" column_invisible=\\"parent.move_type not in ('in_invoice', 'in_refund', 'in_receipt')\\" string=\\"Profesional\\" optional=\\"hide\\" widget=\\"percentage\\" groups=\\"!account.group_partial_purchase_deductibility\\"/>\\n                                        <field name=\\"deductible_percentage\\" column_invisible=\\"parent.move_type not in ('in_invoice', 'in_refund', 'in_receipt')\\" string=\\"Profesional\\" optional=\\"show\\" widget=\\"percentage\\" groups=\\"account.group_partial_purchase_deductibility\\"/>\\n                                        <field name=\\"price_subtotal\\" column_invisible=\\"parent.document_tax_mode == 'tax_included'\\" string=\\"Importe\\"/>\\n                                        <field name=\\"price_total\\" column_invisible=\\"parent.document_tax_mode == 'tax_excluded'\\" string=\\"Importe\\"/>\\n                                        <widget name=\\"section_state\\"/>\\n                                        <!-- Others fields -->\\n                                        <field name=\\"partner_id\\" column_invisible=\\"True\\"/>\\n                                        <field name=\\"currency_id\\" column_invisible=\\"True\\"/>\\n                                        <field name=\\"company_id\\" column_invisible=\\"True\\"/>\\n                                        <field name=\\"company_currency_id\\" column_invisible=\\"True\\"/>\\n                                        <field name=\\"display_type\\" force_save=\\"1\\" column_invisible=\\"True\\"/>\\n                                        <field name=\\"collapse_prices\\" column_invisible=\\"True\\"/>\\n                                        <field name=\\"collapse_composition\\" column_invisible=\\"True\\"/>\\n                                        <field name=\\"document_tax_mode\\" column_invisible=\\"True\\"/>\\n                                    </list>\\n                                    <kanban class=\\"o_kanban_mobile\\">\\n                                        <!-- Displayed fields -->\\n                                        <templates>\\n                                            <t t-name=\\"card\\">\\n                                                <div t-attf-class=\\"ps-0 pe-0 {{ record.display_type.raw_value ? 'o_is_' + record.display_type.raw_value : '' }}\\">\\n                                                    <t t-if=\\"!['line_note', 'line_section', 'line_subsection'].includes(record.display_type.raw_value)\\">\\n                                                        <div class=\\"row g-0\\">\\n                                                            <div t-if=\\"record.product_id.raw_value\\" class=\\"col-2 pe-3\\">\\n                                                                <field name=\\"product_id\\" widget=\\"image\\" options=\\"{'preview_image': 'image_128'}\\" class=\\"w-100\\"/>\\n                                                            </div>\\n                                                            <div t-att-class=\\"{'col-10': record.product_id.raw_value}\\">\\n                                                                <div class=\\"row\\">\\n                                                                    <div class=\\"col\\">\\n                                                                        <field t-if=\\"record.product_id.raw_value\\" class=\\"fw-bold\\" name=\\"product_id\\"/>\\n                                                                        <field t-else=\\"\\" class=\\"fw-bold\\" name=\\"name\\"/>\\n                                                                    </div>\\n                                                                    <div class=\\"col-auto fw-bold float-end text-end\\">\\n                                                                        <field name=\\"price_subtotal\\" t-if=\\"record.document_tax_mode.raw_value == 'tax_excluded'\\" string=\\"Importe\\"/>\\n                                                                        <field name=\\"price_total\\" t-if=\\"record.document_tax_mode.raw_value == 'tax_included'\\" string=\\"Importe\\"/>\\n                                                                    </div>\\n                                                                </div>\\n                                                                <div class=\\"text-muted\\">\\n                                                                    Cantidad:\\n                                                                    <field name=\\"quantity\\"/>\\n                                                                    <field name=\\"product_uom_id\\" groups=\\"uom.group_uom\\" widget=\\"many2one_uom\\"/>\\n                                                                </div>\\n                                                                <div class=\\"text-muted\\">\\n                                                                    Precio unitario:\\n                                                                    <field name=\\"price_unit\\"/>\\n                                                                </div>\\n                                                            </div>\\n                                                        </div>\\n                                                    </t>\\n                                                    <t t-if=\\"['line_section', 'line_subsection', 'line_note'].includes(record.display_type.raw_value)\\">\\n                                                        <div t-att-class=\\"{                                                             'fw-bolder': record.display_type.raw_value === 'line_section',                                                             'fw-bold': record.display_type.raw_value === 'line_subsection',                                                             'fst-italic': record.display_type.raw_value === 'line_note',                                                         }\\">\\n                                                            <field name=\\"name\\"/>\\n                                                        </div>\\n                                                    </t>\\n                                                </div>\\n                                            </t>\\n                                        </templates>\\n\\n                                        <!-- Others fields -->\\n                                        <field name=\\"tax_calculation_rounding_method\\"/>\\n                                        <field name=\\"currency_id\\"/>\\n                                        <field name=\\"company_currency_id\\"/>\\n                                        <field name=\\"display_type\\" force_save=\\"1\\"/>\\n                                        <field name=\\"move_type\\"/>\\n                                        <field name=\\"document_tax_mode\\"/>\\n                                    </kanban>\\n\\n                                    <!-- Form view to cover mobile use -->\\n                                    <form>\\n                                        <sheet>\\n                                            <field name=\\"tax_calculation_rounding_method\\" invisible=\\"1\\"/>\\n                                            <field name=\\"display_type\\" invisible=\\"1\\"/>\\n                                            <field name=\\"company_id\\" invisible=\\"1\\"/>\\n                                            <field name=\\"partner_id\\" invisible=\\"1\\"/>\\n                                            <group>\\n                                                <field name=\\"product_id\\" widget=\\"many2one_barcode\\"/>\\n                                                <label for=\\"name\\" string=\\"Descripción\\" invisible=\\"display_type in ('line_section', 'line_subsection', 'line_note')\\"/>\\n                                                <label for=\\"name\\" string=\\"Sección\\" invisible=\\"display_type != 'line_section'\\"/>\\n                                                <label for=\\"name\\" string=\\"Subsección\\" invisible=\\"display_type != 'line_subsection'\\"/>\\n                                                <label for=\\"name\\" string=\\"Nota\\" invisible=\\"display_type != 'line_note'\\"/>\\n                                                <field name=\\"name\\" widget=\\"text\\" nolabel=\\"1\\"/>\\n                                                <field name=\\"quantity\\"/>\\n                                                <field name=\\"product_uom_id\\" groups=\\"uom.group_uom\\" widget=\\"many2one_uom\\"/>\\n                                                <field name=\\"price_unit\\"/>\\n                                                <field name=\\"discount\\" string=\\"% de dto.\\"/>\\n                                            </group>\\n                                            <group>\\n                                                <field name=\\"account_id\\" domain=\\"[('company_ids', 'parent_of', company_id)]\\" options=\\"{'no_create': True}\\" context=\\"{'partner_id': partner_id, 'move_type': parent.move_type}\\"/>\\n                                                <field name=\\"tax_ids\\" widget=\\"many2many_tax_tags\\" domain=\\"[('type_tax_use', '=?', parent.invoice_filter_type_domain), ('company_id', 'parent_of', parent.company_id), ('country_id', '=', parent.tax_country_id)]\\" context=\\"{                                                         'append_fields': not parent.invoice_filter_type_domain and ['type_tax_use'],                                                         'active_test': True,                                                         'dynamic_fiscal_position_id': parent.fiscal_position_id,                                                     }\\" options=\\"{'no_create': True}\\"/>\\n                                                <field name=\\"analytic_distribution\\" widget=\\"analytic_distribution\\" groups=\\"analytic.group_analytic_accounting\\"/>\\n                                            </group>\\n                                            <group>\\n                                                <field name=\\"price_subtotal\\" invisible=\\"parent.move_type not in ['in_invoice', 'in_refund', 'in_receipt'] and parent.company_price_include == 'tax_included'\\" string=\\"Importe\\"/>\\n                                                <field name=\\"price_total\\" invisible=\\"parent.move_type in ['in_invoice', 'in_refund', 'in_receipt'] or parent.company_price_include == 'tax_excluded'\\" string=\\"Importe\\"/>\\n                                            </group>\\n                                        </sheet>\\n                                    </form>\\n                                </field>\\n                                <group col=\\"12\\" class=\\"oe_invoice_lines_tab overflow-hidden pt-3 pt-md-0\\">\\n                                    <group colspan=\\"8\\">\\n                                        <field name=\\"narration\\" placeholder=\\"Términos y condiciones\\" nolabel=\\"1\\"/>\\n                                    </group>\\n                                    <!-- Totals (only invoices / receipts) -->\\n                                    <group colspan=\\"4\\" class=\\"m-0\\">\\n                                        <group class=\\"oe_subtotal_footer gx-0 gx-md-5\\" invisible=\\"move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt') or payment_state == 'invoicing_legacy'\\">\\n\\n                                            <field name=\\"tax_totals\\" widget=\\"account-tax-totals-field\\" nolabel=\\"1\\" colspan=\\"2\\" class=\\"mb-3 mb-md-0\\" readonly=\\"state != 'draft' or (move_type not in ('in_invoice', 'in_refund', 'in_receipt') and not quick_edit_mode)\\"/>\\n\\n                                            <field name=\\"invoice_payments_widget\\" colspan=\\"2\\" nolabel=\\"1\\" widget=\\"payment\\" class=\\"mb-3 mb-md-0\\" invisible=\\"not invoice_payments_widget\\"/>\\n                                            <div class=\\"d-flex justify-content-end gap-3\\" colspan=\\"2\\">\\n                                                <label for=\\"amount_residual\\"/>\\n                                                <field name=\\"amount_residual\\" class=\\"oe_subtotal_footer_separator w-auto\\"/>\\n                                            </div>\\n                                        </group>\\n                                        <group class=\\"oe_subtotal_footer px-4\\" invisible=\\"not invoice_has_outstanding\\" groups=\\"account.group_account_invoice,account.group_account_readonly\\">\\n                                            <field name=\\"invoice_outstanding_credits_debits_widget\\" class=\\"oe_invoice_outstanding_credits_debits py-3\\" colspan=\\"2\\" nolabel=\\"1\\" widget=\\"payment\\"/>\\n                                        </group>\\n                                    </group>\\n                                </group>\\n                            </page>\\n                            <page id=\\"aml_tab\\" string=\\"Apuntes contables\\" groups=\\"account.group_account_readonly\\" name=\\"aml_tab\\">\\n                                <field name=\\"line_ids\\" mode=\\"list,kanban\\" context=\\"{                                            'default_move_type': context.get('default_move_type'),                                            'line_ids': line_ids,                                            'journal_id': journal_id,                                            'default_partner_id': commercial_partner_id,                                            'default_currency_id': currency_id or company_currency_id,                                            'kanban_view_ref': 'account.account_move_line_view_kanban_mobile',                                        }\\" invisible=\\"payment_state == 'invoicing_legacy' and move_type != 'entry'\\" readonly=\\"state != 'draft'\\">\\n                                    <list editable=\\"bottom\\" string=\\"Apuntes contables\\" decoration-muted=\\"display_type in ('line_section', 'line_note')\\" default_order=\\"sequence, id\\">\\n                                        <!-- Displayed fields -->\\n                                        <field name=\\"account_id\\" invisible=\\"display_type in ('line_section', 'line_note')\\" required=\\"display_type not in ('line_section', 'line_note')\\" domain=\\"[('company_ids', 'parent_of', company_id), ('account_type', '!=', 'asset_cash')]\\"/>\\n                                        <field name=\\"partner_id\\" optional=\\"show\\" domain=\\"['|', ('parent_id', '=', False), ('is_company', '=', True)]\\" column_invisible=\\"parent.move_type != 'entry'\\"/>\\n                                        <field name=\\"name\\" optional=\\"show\\"/>\\n                                        <field name=\\"analytic_distribution\\" widget=\\"analytic_distribution\\" groups=\\"analytic.group_analytic_accounting\\" optional=\\"show\\" options=\\"{'account_field': 'account_id'}\\" business_domain_compute=\\"parent.move_type in ['out_invoice', 'out_refund', 'out_receipt'] and 'invoice' or parent.move_type in ['in_invoice', 'in_refund', 'in_receipt'] and 'bill' or 'general'\\"/>\\n                                        <field name=\\"date_maturity\\" optional=\\"hide\\" decoration-danger=\\"date_maturity and date_maturity &lt; context_today().strftime('%Y-%m-%d') and parent.payment_state not in ('paid', 'in_payment', 'reversed')\\" invisible=\\"display_type in ('line_section', 'line_note')\\" column_invisible=\\"context.get('view_no_maturity')\\"/>\\n                                        <field name=\\"amount_currency\\" groups=\\"base.group_multi_currency\\" optional=\\"hide\\"/>\\n                                        <field name=\\"currency_id\\" options=\\"{'no_create': True}\\" optional=\\"hide\\" groups=\\"base.group_multi_currency\\" column_invisible=\\"parent.move_type != 'entry'\\"/>\\n                                        <field name=\\"tax_ids\\" widget=\\"autosave_many2many_tax_tags\\" optional=\\"hide\\" domain=\\"[('type_tax_use', '=?', parent.invoice_filter_type_domain), ('company_id', 'parent_of', parent.company_id)]\\" context=\\"{                                                     'append_fields': not parent.invoice_filter_type_domain and ['type_tax_use'],                                                     'active_test': True                                                }\\" options=\\"{'no_create': True}\\" force_save=\\"1\\" readonly=\\"display_type in ('line_section', 'line_note') or tax_line_id or (parent.move_type in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt') and account_type in ('asset_receivable', 'liability_payable'))\\"/>\\n                                        <field name=\\"debit\\" sum=\\"Débito total\\" invisible=\\"display_type in ('line_section', 'line_subsection', 'line_note')\\" readonly=\\"parent.move_type in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt') and display_type in ('line_section', 'line_note', 'product')\\" decoration-muted=\\"debit == 0\\"/>\\n                                        <field name=\\"credit\\" sum=\\"Crédito total\\" invisible=\\"display_type in ('line_section', 'line_subsection', 'line_note')\\" readonly=\\"parent.move_type in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt') and display_type in ('line_section', 'line_note', 'product')\\" decoration-muted=\\"credit == 0\\"/>\\n                                        <field name=\\"balance\\" column_invisible=\\"True\\"/>\\n                                        <field name=\\"discount_date\\" string=\\"Fecha de descuento\\" optional=\\"hide\\"/>\\n                                        <field name=\\"discount_amount_currency\\" string=\\"Importe del descuento\\" optional=\\"hide\\"/>\\n\\n                                        <field name=\\"tax_tag_ids\\" widget=\\"many2many_tags\\" string=\\"Tablas de impuestos\\" optional=\\"show\\" options=\\"{'no_create': True}\\" domain=\\"[                                                     ('applicability', '=', 'taxes'),                                                     '|', ('country_id', '=', parent.tax_country_id),                                                     ('country_id', '=', False),                                                 ]\\"/>\\n\\n                                        <!-- Others fields -->\\n                                        <field name=\\"tax_line_id\\" column_invisible=\\"True\\"/>\\n                                        <field name=\\"company_currency_id\\" column_invisible=\\"True\\"/>\\n                                        <field name=\\"display_type\\" force_save=\\"1\\" column_invisible=\\"True\\"/>\\n                                        <field name=\\"company_id\\" column_invisible=\\"True\\"/>\\n                                        <field name=\\"sequence\\" column_invisible=\\"True\\"/>\\n                                        <field name=\\"id\\" column_invisible=\\"True\\"/>\\n                                        <field name=\\"account_internal_group\\" column_invisible=\\"True\\"/>\\n                                        <field name=\\"account_type\\" column_invisible=\\"True\\"/>\\n                                    </list>\\n                                    <!-- Form view to cover mobile use -->\\n                                    <form>\\n                                      <group>\\n                                        <field name=\\"account_id\\" domain=\\"[('company_ids', 'parent_of', company_id)]\\"/>\\n                                        <field name=\\"partner_id\\" domain=\\"['|', ('parent_id', '=', False), ('is_company', '=', True)]\\"/>\\n                                        <field name=\\"name\\"/>\\n                                        <field name=\\"analytic_distribution\\" widget=\\"analytic_distribution\\" groups=\\"analytic.group_analytic_accounting\\"/>\\n                                        <field name=\\"amount_currency\\" groups=\\"base.group_multi_currency\\"/>\\n                                        <field name=\\"company_currency_id\\" invisible=\\"1\\"/>\\n                                        <field name=\\"company_id\\" invisible=\\"1\\"/>\\n                                        <field name=\\"currency_id\\" options=\\"{'no_create': True}\\" groups=\\"base.group_multi_currency\\"/>\\n                                        <field name=\\"debit\\" sum=\\"Débito total\\"/>\\n                                        <field name=\\"credit\\" sum=\\"Crédito total\\"/>\\n                                        <field name=\\"balance\\" invisible=\\"1\\"/>\\n                                        <field name=\\"tax_ids\\" string=\\"Impuestos aplicados\\" widget=\\"many2many_tax_tags\\" options=\\"{'no_create': True}\\" domain=\\"[('type_tax_use', '=?', parent.invoice_filter_type_domain), ('company_id', 'parent_of', parent.company_id)]\\" context=\\"{                                                     'append_fields': not parent.invoice_filter_type_domain and ['type_tax_use'],                                                     'active_test': True,                                                }\\"/>\\n                                        <field name=\\"date_maturity\\" required=\\"0\\" invisible=\\"context.get('view_no_maturity', False)\\"/>\\n                                      </group>\\n                                    </form>\\n                                </field>\\n                                <div class=\\"alert alert-info text-center mb-0\\" role=\\"alert\\" invisible=\\"payment_state != 'invoicing_legacy' or move_type == 'entry'\\">\\n                                    <span>Este asiento se ha generado a través de la aplicación *Facturación*, antes de instalar *Contabilidad*. Su saldo se ha importado por separado.</span>\\n                                </div>\\n                            </page>\\n                            <page id=\\"other_tab\\" string=\\"Otra Información\\" name=\\"other_info\\" invisible=\\"move_type == 'entry'\\">\\n                                <group id=\\"other_tab_group\\">\\n                                    <group string=\\"Factura\\" name=\\"sale_info_group\\" invisible=\\"move_type not in ('out_invoice', 'out_refund')\\">\\n                                        <label for=\\"ref\\" string=\\"Referencia del cliente\\"/>\\n                                        <field name=\\"ref\\" nolabel=\\"1\\"/>\\n                                        <field name=\\"user_id\\" invisible=\\"1\\" force_save=\\"1\\"/>\\n                                        <field name=\\"invoice_user_id\\" domain=\\"[('share', '=', False)]\\" widget=\\"many2one_avatar_user\\"/>\\n                                        <field name=\\"invoice_origin\\" string=\\"Documento de origen\\" force_save=\\"1\\" invisible=\\"1\\"/>\\n                                        <field name=\\"partner_bank_id\\" widget=\\"many2one_bank\\" context=\\"{'default_partner_id': bank_partner_id}\\" domain=\\"[('partner_id.ref_company_ids', 'parent_of', company_id)]\\" invisible=\\"move_type != 'out_invoice'\\" readonly=\\"is_move_sent and state != 'draft'\\"/>\\n                                        <field name=\\"partner_bank_id\\" context=\\"{'default_partner_id': bank_partner_id, 'display_account_trust': True}\\" domain=\\"[('partner_id', '=', bank_partner_id)]\\" invisible=\\"move_type != 'out_refund'\\" readonly=\\"is_move_sent and state != 'draft'\\"/>\\n                                        <field name=\\"payment_reference\\" invisible=\\"move_type not in ('out_invoice', 'out_refund')\\" readonly=\\"inalterable_hash\\" placeholder=\\"Mensaje estándar\\"/>\\n                                        <field name=\\"qr_code_method\\" invisible=\\"not display_qr_code\\"/>\\n                                        <field name=\\"delivery_date\\" readonly=\\"state != 'draft'\\"/>\\n                                    </group>\\n                                    <group string=\\"Contabilidad\\" name=\\"accounting_info_group\\">\\n                                        <field name=\\"company_id\\" groups=\\"base.group_multi_company\\" domain=\\"[('id', 'child_of', journal_company_id)]\\"/>\\n                                        <field name=\\"invoice_incoterm_placeholder\\" invisible=\\"1\\"/>    <!-- Needed for placeholder_field -->\\n                                        <field name=\\"invoice_incoterm_id\\" options=\\"{'placeholder_field': 'invoice_incoterm_placeholder'}\\" invisible=\\"move_type in ('out_receipt', 'in_receipt')\\"/>\\n                                        <field name=\\"incoterm_location\\" invisible=\\"move_type in ('out_receipt', 'in_receipt')\\"/>\\n                                        <field name=\\"fiscal_position_id\\" readonly=\\"state in ['cancel', 'posted']\\"/>\\n                                        <field name=\\"secured\\" groups=\\"account.group_account_secured,base.group_no_one\\"/>\\n                                        <field name=\\"preferred_payment_method_line_id\\" string=\\"Método de pago\\" domain=\\"[('payment_type', '=', 'inbound'), ('company_id', 'parent_of', company_id)]\\" invisible=\\"move_type in ('in_invoice', 'in_refund', 'in_receipt')\\"/>\\n                                        <field name=\\"preferred_payment_method_line_id\\" string=\\"Método de pago\\" domain=\\"[('payment_type', '=', 'outbound'), ('company_id', 'parent_of', company_id)]\\" invisible=\\"move_type in ('out_invoice', 'out_refund', 'out_receipt')\\"/>\\n                                        <field name=\\"invoice_source_email\\" widget=\\"email\\" invisible=\\"move_type not in ('in_invoice', 'in_refund') or not invoice_source_email\\"/>\\n                                        <field name=\\"auto_post\\" invisible=\\"move_type in ('out_receipt', 'in_receipt')\\" readonly=\\"state != 'draft'\\"/>\\n                                        <field name=\\"auto_post_until\\" invisible=\\"auto_post in ('no', 'at_date')\\" readonly=\\"state != 'draft'\\"/>\\n                                    </group>\\n                                </group>\\n                            </page>\\n                            <page id=\\"other_tab_entry\\" string=\\"Otra Información\\" name=\\"other_info\\" invisible=\\"move_type != 'entry'\\">\\n                                <group id=\\"other_tab_entry_group\\">\\n                                    <group name=\\"misc_group\\">\\n                                        <field name=\\"auto_post\\" invisible=\\"move_type != 'entry'\\" readonly=\\"state != 'draft'\\"/>\\n                                        <field name=\\"reversed_entry_id\\" invisible=\\"move_type != 'entry' or not reversed_entry_id\\"/>\\n                                        <field name=\\"auto_post_until\\" invisible=\\"auto_post in ('no', 'at_date')\\" readonly=\\"state != 'draft'\\"/>\\n                                    </group>\\n                                    <group>\\n                                        <field name=\\"fiscal_position_id\\" readonly=\\"state in ['cancel', 'posted']\\"/>\\n                                        <field name=\\"company_id\\" groups=\\"base.group_multi_company\\" required=\\"1\\"/>\\n                                    </group>\\n                                </group>\\n                                <!-- Internal note -->\\n                                <field name=\\"narration\\" placeholder=\\"Añada una nota interna...\\" nolabel=\\"1\\" height=\\"50\\"/>\\n                            </page>\\n                        </notebook>\\n                    </sheet>\\n                    <!-- Attachment preview -->\\n                    <div class=\\"o_attachment_preview\\" invisible=\\"move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund') or state != 'draft'\\"/>\\n                    <!-- Chatter -->\\n                    <chatter reload_on_attachment=\\"True\\"/>\\n                </form>"}	<?xml version="1.0"?>\n<form string="Account Entry" js_class="account_move_form">\n                    <header>\n                        <!-- Post -->\n                        <button name="action_post" string="Post" class="oe_highlight" type="object" groups="account.group_account_invoice" data-hotkey="q" context="{'validate_analytic': True, 'disable_abnormal_invoice_detection': False}" invisible="hide_post_button or move_type != 'entry'"/>\n                        <button name="action_post" string="Confirm" class="oe_highlight" type="object" groups="account.group_account_invoice" data-hotkey="q" context="{'validate_analytic': True, 'disable_abnormal_invoice_detection': False}" invisible="hide_post_button or move_type == 'entry' or display_inactive_currency_warning"/>\n                        <!-- Send (only invoices) -->\n                        <button name="action_invoice_sent" type="object" string="Send" invisible="not display_send_button or not highlight_send_button" class="oe_highlight" data-hotkey="y"/>\n                        <button name="action_invoice_sent" type="object" string="Send" invisible="not display_send_button or highlight_send_button" data-hotkey="y"/>\n                        <button name="action_print_pdf" type="object" class="oe_highlight" invisible="state != 'posted' or is_being_sent or invoice_pdf_report_id or move_type in ('entry', 'in_invoice','in_refund','in_receipt')" string="Print" data-hotkey="p"/>\n                        <button name="action_print_pdf" type="object" invisible="state != 'posted' or (not is_being_sent and not invoice_pdf_report_id) or move_type in ('in_invoice','in_refund','in_receipt')" string="Print" data-hotkey="p"/>\n                        <!-- Register Payment (only invoices / receipts) -->\n                        <button name="action_register_payment" id="account_invoice_payment_btn" type="object" class="oe_highlight" invisible="(                                     state != 'posted'                                     or payment_state not in ('not_paid', 'partial', 'in_payment')                                     or move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')                                     or invoice_has_outstanding                                 )" context="{'dont_redirect_to_payments': True}" string="Pay" data-hotkey="g" groups="account.group_account_invoice"/>\n                        <!-- Register Payment (only invoices / receipts, with outstanding payments) -->\n                        <button name="action_register_payment" id="account_invoice_payment_secondary_btn" type="object" invisible="(                                     state != 'posted'                                     or payment_state not in ('not_paid', 'partial', 'in_payment')                                     or move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')                                     or not invoice_has_outstanding                                 )" context="{'dont_redirect_to_payments': True}" string="Pay" data-hotkey="g" groups="account.group_account_invoice"/>\n                        <!-- Preview (only customer invoices) -->\n                        <button name="preview_invoice" type="object" string="Preview" data-hotkey="o" invisible="move_type not in ('out_invoice', 'out_refund') or state in ('draft', 'cancel')"/>\n                        <!-- Reverse -->\n                        <button name="256" string="Reverse Entry" type="action" groups="account.group_account_invoice" data-hotkey="z" invisible="move_type != 'entry' or state != 'posted' or payment_state == 'reversed'"/>\n                        <button name="action_reverse" string="Credit Note" type="object" groups="account.group_account_invoice" invisible="move_type not in ('out_invoice', 'in_invoice') or state != 'posted'" data-hotkey="shift+n"/>\n                        <!-- Cancel -->\n                        <button name="button_cancel" string="Cancel Entry" type="object" groups="account.group_account_invoice" data-hotkey="x" invisible="not id or state != 'draft' or move_type != 'entry'"/>\n                        <button name="button_cancel" string="Cancel" type="object" groups="account.group_account_invoice" data-hotkey="x" invisible="not id or state != 'draft' or move_type == 'entry'"/>\n                        <button name="button_draft" string="Reset to Draft" type="object" groups="account.group_account_invoice" invisible="not show_reset_to_draft_button" data-hotkey="r"/>\n                        <button name="button_hash" string="Lock" type="object" groups="account.group_account_invoice" invisible="not restrict_mode_hash_table or inalterable_hash or state != 'posted'"/>\n                        <button string="Request Cancel" name="button_request_cancel" type="object" groups="account.group_account_invoice" invisible="state != 'posted' or show_reset_to_draft_button or not need_cancel_request" data-hotkey="w"/>\n                        <!-- Reload Data from attachment -->\n                        <button name="action_reload_imported_data" string="Reload Data" type="object" invisible="state != 'draft'                                            or move_type not in ('in_invoice', 'in_refund', 'in_receipt', 'out_invoice', 'out_refund', 'out_receipt')                                            or not import_source_attachment_id"/>\n                        <!-- Review button -->\n                        <field name="review_state" widget="account_review_state_selection_badge" options="{                                    'no_review': {'can_edit': 'account.group_account_user,account.group_account_manager'},                                    'todo': {'decoration': 'info'},                                    'reviewed': {'decoration': 'success'},                                    'supervised': {'decoration': 'success', 'can_edit': 'account.group_account_manager'},                                    'anomaly': {'decoration': 'danger'},                                }" class="ms-auto me-3 align-self-center" invisible="state != 'posted'" groups="account.group_account_user"/>\n                        <field name="state" widget="statusbar" statusbar_visible="draft,posted" groups="!account.group_account_secured"/>\n                        <field name="state" widget="account_move_statusbar_secured" statusbar_visible="draft,posted" groups="account.group_account_secured"/>\n                    </header>\n\n                    <!-- General warnings computed from `_get_alerts` -->\n                    <div class="m-0" id="alerts" invisible="not alerts">\n                        <field name="alerts" class="o_field_html" widget="actionable_errors"/>\n                    </div>\n                    <!--Duplicate check-->\n                    <div class="d-flex alert alert-danger w-100 d-flex align-items-center gap-1" invisible="not is_exact_move_duplicate" role="alert">\n                        <span>This document might be a duplicate of</span>\n                        <field name="duplicated_ref_ids" widget="x2many_buttons" nb_records_shown="1" string="Duplicated Documents" context="{'name_as_amount_total': True}"/>\n                        <button name="action_delete_duplicates" type="object" class="btn btn-link text-danger ms-auto d-flex align-items-center gap-1" invisible="not has_draft_move_duplicate">\n                            <i class="oi oi-filled text-danger" data-icon="delete"/>\n                            <span class="text-danger" invisible="duplicated_ref_ids.length == 1">Delete all duplicates</span>\n                            <span class="text-danger" invisible="duplicated_ref_ids.length &gt; 1">Delete duplicate</span>\n                        </button>\n                    </div>\n                    <div class="d-flex alert alert-warning w-100 d-flex align-items-center gap-1" invisible="not duplicated_ref_ids or is_exact_move_duplicate or state != 'draft'" role="alert">\n                        <span>This document might be a duplicate of</span>\n                        <field name="duplicated_ref_ids" widget="x2many_buttons" nb_records_shown="1" string="Duplicated Documents" context="{'name_as_amount_total': True}"/>\n                        <button name="action_delete_duplicates" type="object" class="btn btn-link text-danger ms-auto d-flex align-items-center gap-1" invisible="not has_draft_move_duplicate">\n                            <i class="oi oi-filled text-danger" data-icon="delete"/>\n                            <span class="text-danger" invisible="duplicated_ref_ids.length == 1">Delete all duplicates</span>\n                            <span class="text-danger" invisible="duplicated_ref_ids.length &gt; 1">Delete duplicate</span>\n                        </button>\n                    </div>\n                    <!-- Invoice outstanding credits -->\n                    <div groups="account.group_account_invoice,account.group_account_readonly" class="alert alert-info" role="alert" invisible="move_type not in ('out_invoice', 'out_receipt') or not invoice_has_outstanding or payment_state not in ('not_paid', 'partial')">\n                        You have <bold><a class="alert-link" href="#outstanding" role="button">outstanding credits</a></bold> listed below for this customer.\n                    </div>\n                    <div groups="account.group_account_invoice,account.group_account_readonly" class="alert alert-info" role="alert" invisible="move_type not in ('in_invoice', 'in_receipt') or not invoice_has_outstanding or payment_state not in ('not_paid', 'partial')">\n                        You have <bold><a class="alert-link" href="#outstanding" role="button">outstanding debits</a></bold> listed below for this vendor.\n                    </div>\n                    <div groups="account.group_account_invoice,account.group_account_readonly" class="alert alert-info" role="alert" invisible="move_type != 'out_refund' or not invoice_has_outstanding or payment_state not in ('not_paid', 'partial')">\n                        You have <bold><a class="alert-link" href="#outstanding" role="button">outstanding debits</a></bold> listed below for this customer.\n                    </div>\n                    <div groups="account.group_account_invoice,account.group_account_readonly" class="alert alert-info" role="alert" invisible="move_type != 'in_refund' or not invoice_has_outstanding or payment_state not in ('not_paid', 'partial')">\n                        You have <bold><a class="alert-link" href="#outstanding" role="button">outstanding credits</a></bold> listed below for this vendor.\n                    </div>\n                    <!-- Currency consistency -->\n                    <div class="alert alert-warning" role="alert" invisible="not display_inactive_currency_warning or move_type not in ('in_invoice', 'in_refund', 'in_receipt')">\n                        In order to validate this bill, you must <button class="oe_link" type="object" name="action_activate_currency" style="padding: 0; vertical-align: baseline;">activate the currency of the bill</button>. The journal entries need to be computed by Odoo before being posted in your company's currency.\n                    </div>\n                    <div class="alert alert-warning" role="alert" invisible="not display_inactive_currency_warning or move_type not in ('out_invoice', 'out_refund', 'out_receipt')">\n                        In order to validate this invoice, you must <button class="oe_link" type="object" name="action_activate_currency" style="padding: 0; vertical-align: baseline;">activate the currency of the invoice</button>. The journal entries need to be computed by Odoo before being posted in your company's currency.\n                    </div>\n\n                    <sheet>\n                        <div name="button_box" class="oe_button_box">\n                            <button name="action_open_business_doc" class="oe_stat_button" icon="menu" type="object" invisible="move_type != 'entry' or not id or not origin_payment_id">\n                                    <div class="o_stat_info">\n                                        <span class="o_stat_text">1 Payment</span>\n                                    </div>\n                            </button>\n                            <button name="open_payments" groups="account.group_account_invoice,account.group_account_readonly" class="oe_stat_button" icon="menu" type="object" invisible="not payment_count">\n                                    <field name="payment_count" string="Payments" widget="statinfo"/>\n                            </button>\n                            <button name="open_reconcile_view" class="oe_stat_button" icon="menu" type="object" invisible="move_type != 'entry' or not id or not has_reconciled_entries">\n                                    <div class="o_stat_info">\n                                        <span class="o_stat_text">Reconciled Items</span>\n                                    </div>\n                            </button>\n                            <button name="open_created_caba_entries" class="oe_stat_button" icon="attach_money" type="object" invisible="not tax_cash_basis_created_move_ids">\n                                    <div class="o_stat_info">\n                                        <span class="o_stat_text">Cash Basis Entries</span>\n                                    </div>\n                            </button>\n                            <button name="open_adjusting_entries" class="oe_stat_button" icon="menu" type="object" invisible="not adjusting_entries_move_ids">\n                                    <field name="adjusting_entries_count" string="Adjusting Entries" widget="statinfo"/>\n                            </button>\n                            <button name="open_adjusting_entry_origin_moves" class="oe_stat_button" icon="menu" type="object" invisible="not adjusting_entry_origin_move_ids">\n                                    <div invisible="adjusting_entry_origin_moves_count != 1" class="o_stat_info">\n                                        <span class="o_stat_text">\n                                            <field name="adjusting_entry_origin_label"/>\n                                        </span>\n                                    </div>\n                                    <field name="adjusting_entry_origin_moves_count" invisible="adjusting_entry_origin_moves_count == 1" string="Invoices" widget="statinfo"/>\n                            </button>\n                            <button name="open_journal_items" groups="account.group_account_invoice,account.group_account_readonly" invisible="move_type == 'entry'" class="oe_stat_button" icon="menu" type="object">\n                                    <div class="o_stat_info">\n                                        <span class="o_stat_text">Journal Items</span>\n                                    </div>\n                            </button>\n                            <button name="action_open_reversal_moves" class="oe_stat_button" icon="edit_square" type="object" invisible="reversal_move_count == 0">\n                                <field name="reversal_move_count" string="Credit Notes" widget="statinfo" invisible="move_type != 'out_invoice'"/>\n                                <field name="reversal_move_count" string="Refunds" widget="statinfo" invisible="move_type != 'in_invoice'"/>\n                                <field name="reversal_move_count" string="Reversal Entries" widget="statinfo" invisible="move_type != 'entry'"/>\n                            </button>\n                            <button name="action_open_reversed_entry" class="oe_stat_button" icon="edit_square" type="object" invisible="not reversed_entry_id">\n                                <span class="o_stat_text" invisible="move_type != 'out_refund'">Invoice</span>\n                                <span class="o_stat_text" invisible="move_type != 'in_refund'">Vendor Bill</span>\n                                <span class="o_stat_text" invisible="move_type != 'entry'">Journal Entry</span>\n                            </button>\n                        </div>\n\n                        <widget name="web_ribbon" title="Sent" bg_color="gray_ribbon" invisible="not is_move_sent or payment_state != 'not_paid' or move_type not in ('out_invoice', 'out_refund', 'out_receipt')"/>\n                        <!-- Payment status for invoices / receipts -->\n                        <widget name="web_ribbon" title="Sent" bg_color="text-bg-300" invisible="status_in_payment != 'sent' or move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')"/>\n                        <widget name="web_ribbon" title="Paid" invisible="payment_state != 'paid' or move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')"/>\n                        <widget name="web_ribbon" title="In Payment" invisible="payment_state != 'in_payment' or move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')"/>\n                        <widget name="web_ribbon" title="Partial" bg_color="text-bg-300" invisible="payment_state != 'partial' or move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')"/>\n                        <widget name="web_ribbon" title="Reversed" invisible="payment_state != 'reversed'"/>\n                        <widget name="web_ribbon" title="Blocked" bg_color="text-bg-danger" invisible="payment_state != 'blocked' or move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')"/>\n                         <widget name="web_ribbon" text="Invoicing App Legacy" bg_color="text-bg-info" invisible="payment_state != 'invoicing_legacy'" tooltip="This entry has been generated through the Invoicing app, before installing Accounting. It has been disabled by the 'Invoicing Switch Threshold Date' setting so that it does not impact your accounting."/>\n\n                        <!-- Invisible fields -->\n                        <field name="id" invisible="1"/>\n                        <field name="state" invisible="1"/>\n                        <field name="company_id" invisible="1"/>\n                        <field name="journal_id" invisible="1"/>\n                        <field name="show_name_warning" invisible="1"/>\n                        <field name="posted_before" invisible="1"/>\n                        <field name="import_source_attachment_id" invisible="1"/>\n                        <!--test-tags .test_01_account_tour -->\n                        <field name="move_type" invisible="1" force_save="1"/>\n                        <field name="payment_state" invisible="1" force_save="1"/>\n                        <field name="invoice_filter_type_domain" invisible="1"/>\n                        <field name="suitable_journal_ids" invisible="1"/>\n                        <field name="currency_id" invisible="1" readonly="state in ['cancel', 'posted']"/>\n                        <field name="company_currency_id" invisible="1"/>\n                        <field name="commercial_partner_id" invisible="1"/>\n                        <field name="bank_partner_id" invisible="1"/>\n                        <field name="display_qr_code" invisible="1"/>\n                        <field name="show_reset_to_draft_button" invisible="1"/>\n                        <field name="expected_currency_rate" invisible="1"/>\n\n                        <field name="invoice_has_outstanding" invisible="1"/>\n                        <field name="is_move_sent" invisible="1"/>\n                        <field name="invoice_pdf_report_id" invisible="1"/>\n                        <field name="need_cancel_request" invisible="1"/>\n                        <field name="has_reconciled_entries" invisible="1"/>\n                        <field name="restrict_mode_hash_table" invisible="1"/>\n                        <field name="inalterable_hash" invisible="1"/>\n                        <field name="country_code" invisible="1"/>\n                        <field name="display_inactive_currency_warning" invisible="1"/>\n                        <field name="statement_line_id" invisible="1"/>\n                        <field name="statement_id" invisible="1"/>\n                        <field name="origin_payment_id" invisible="1"/>\n                        <field name="tax_country_id" invisible="1"/>\n                        <field name="tax_calculation_rounding_method" invisible="1"/>\n                        <field name="tax_cash_basis_created_move_ids" invisible="1"/>\n                        <field name="quick_edit_mode" invisible="1"/>\n                        <field name="invoice_cash_rounding_id" invisible="1"/>\n                        <field name="hide_post_button" invisible="1"/>\n                        <field name="quick_encoding_vals" invisible="1"/>\n                        <field name="show_delivery_date" invisible="1"/>\n                        <field name="is_being_sent" invisible="1"/>\n                        <field name="show_update_fpos" invisible="1"/>\n                        <field name="company_vat_disabled" invisible="1"/>\n\n                        <div class="oe_title">\n                            <span class="o_form_label">\n                                <field name="move_type" invisible="move_type == 'entry' or is_self_billing" widget="receipt_selector" options="{'horizontal': true}" nolabel="1" readonly="state != 'draft'"/>\n                            </span>\n\n                            <div class="text-warning" invisible="not show_name_warning">The current highest number is <field class="oe_inline" name="highest_name"/>. You might want to put a higher number here.</div>\n\n                            <h1>\n                                <field name="name" invisible="not (name or name_placeholder or document_sequence_editable)" readonly="state != 'draft'" options="{'placeholder_field': 'name_placeholder'}"/>\n\n                                <span invisible="name or name_placeholder or document_sequence_editable">Draft</span>\n                            </h1>\n                        </div>\n                        <group>\n                            <group id="header_left_group">\n\n                                <label for="partner_id" string="Customer" style="font-weight:bold;" invisible="move_type not in ('out_invoice', 'out_refund', 'out_receipt')"/>\n                                <label for="partner_id" string="Vendor" style="font-weight:bold;" invisible="move_type not in ('in_invoice', 'in_refund', 'in_receipt')"/>\n                                <div class="o_col" invisible="move_type not in ('out_invoice', 'out_refund', 'out_receipt', 'in_invoice', 'in_refund', 'in_receipt')">\n                                    <field name="partner_id" widget="res_partner_many2one" nolabel="1" context="{                                             'res_partner_search_mode': (context.get('default_move_type', 'entry') in ('out_invoice', 'out_refund', 'out_receipt') and 'customer') or (context.get('default_move_type', 'entry') in ('in_invoice', 'in_refund', 'in_receipt') and 'supplier') or False,                                             'show_address': 1, 'default_is_company': True, 'show_identifier': True}" options="{&quot;no_quick_create&quot;: True}" default_focus="1" invisible="move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')" placeholder="Search a name or Tax ID..." readonly="state != 'draft'"/>\n                                    <button name="action_update_fpos_values" type="object" string="Update Taxes and Accounts" help="Recompute all taxes and accounts based on this fiscal position" class="btn-link mb-1 px-0" icon="refresh" invisible="not show_update_fpos or state in ['cancel', 'posted']"/>\n                                </div>\n\n                                <field name="partner_shipping_id" groups="account.group_delivery_invoice_address" invisible="move_type not in ('out_invoice', 'out_refund', 'out_receipt')" readonly="state != 'draft'"/>\n                                <field name="quick_edit_total_amount" class="w-50" invisible="move_type == 'entry' or not quick_edit_mode" readonly="state != 'draft'"/>\n                                <label for="ref" string="Bill Reference" invisible="move_type not in ('in_invoice', 'in_receipt', 'in_refund')"/>\n                                <field name="ref" default_focus="1" nolabel="1" invisible="move_type not in ('in_invoice', 'in_receipt', 'in_refund')"/>\n                                <field name="ref" default_focus="1" invisible="move_type != 'entry'"/>\n                                <field name="tax_cash_basis_origin_move_id" invisible="not tax_cash_basis_origin_move_id"/>\n                                <field name="invoice_vendor_bill_id" string="Auto-Complete" class="oe_edit_only" invisible="not show_invoice_vendor_bill" domain="([('partner_id', 'child_of', [partner_id])] if partner_id else []) + [                                            ('company_id', '=', company_id),                                            ('move_type', '=', move_type)                                        ]" placeholder="Select an old purchase document" options="{'no_create': True}" context="{'show_total_amount': True}"/>\n                            </group>\n                            <group id="header_right_group">\n                                <label for="invoice_date" string="Invoice Date" style="font-weight:bold;" invisible="move_type not in ('out_invoice', 'out_refund', 'out_receipt')"/>\n                                <field name="invoice_date" nolabel="1" options="{'warning': 'future'}" invisible="move_type not in ('out_invoice', 'out_refund', 'out_receipt')" readonly="state != 'draft'" placeholder="Today"/>\n\n                                <label for="invoice_date" string="Bill Date" style="font-weight:bold;" invisible="move_type not in ('in_invoice', 'in_refund', 'in_receipt')"/>\n                                <field name="invoice_date" nolabel="1" options="{'warning': 'future'}" invisible="move_type not in ('in_invoice', 'in_refund', 'in_receipt')" required="move_type in ('in_invoice', 'in_refund', 'in_receipt')" readonly="state != 'draft'"/>\n\n                                <field name="date" string="Accounting Date" invisible="move_type in ('out_invoice', 'out_refund', 'out_receipt') and not quick_edit_mode and not (state == 'posted' and date != invoice_date)" readonly="state != 'draft'"/>\n                                <field name="payment_reference" invisible="move_type not in ('in_invoice', 'in_refund', 'in_receipt')" readonly="inalterable_hash != False" placeholder="Use Bill Reference"/>\n                                <field name="partner_bank_id" widget="many2one_bank" context="{'default_partner_id': bank_partner_id}" domain="[('partner_id', '=', bank_partner_id)]" invisible="move_type not in ('in_invoice', 'in_refund', 'in_receipt')" readonly="is_move_sent and state != 'draft'"/>\n\n                                <!-- Invoice payment terms (only invoices) + due date (only invoices / receipts) -->\n                                <div class="o_td_label" invisible="move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')">\n                                    <label for="invoice_date_due" string="Due Date" invisible="invoice_payment_term_id"/>\n                                    <label for="invoice_payment_term_id" string="Payment terms" invisible="not invoice_payment_term_id"/>\n                                </div>\n                                <div class="d-flex" invisible="move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')" name="due_date">\n                                    <field name="invoice_date_due" force_save="1" placeholder="Date" invisible="invoice_payment_term_id" decoration-danger="invoice_date_due and invoice_date_due &lt; context_today().strftime('%Y-%m-%d') and payment_state not in ('paid', 'in_payment', 'reversed')"/>\n                                    <span class="o_form_label mx-3 oe_edit_only text-center" style="width: 6ch;" invisible="state != 'draft' or invoice_payment_term_id">or</span>\n                                    <field name="invoice_payment_term_id" context="{'example_date': invoice_date, 'example_amount': tax_totals['total_amount_currency']}" placeholder="Payment Terms" options="{'no_quick_create':True}" readonly="state in ['cancel', 'posted']"/>\n                                </div>\n                                <field name="taxable_supply_date_placeholder" invisible="1"/> <!-- Needed for the placeholder widget -->\n                                <field name="taxable_supply_date" invisible="not show_taxable_supply_date" readonly="state != 'draft'" options="{'placeholder_field': 'taxable_supply_date_placeholder'}"/>\n                                <field name="delivery_date" invisible="not show_delivery_date" readonly="state != 'draft'"/>\n                                <label for="journal_id" invisible="not show_journal"/>\n                                <label for="currency_id" groups="base.group_multi_currency" invisible="show_journal"/>\n                                <div name="journal_div" class="d-flex">\n                                    <field name="journal_id" invisible="not show_journal" options="{'no_create': True, 'no_open': True}" readonly="posted_before and name not in (False, '', '/')"/>\n                                    <div name="in_and_refresh_button_div" groups="base.group_multi_currency" class="d-flex flex-column mx-3 text-center" style="width: 6ch;" invisible="move_type == 'entry' or not show_journal">\n                                        <div>in</div>\n                                        <div class="d-flex flex-column justify-content-center flex-grow-1" invisible="state != 'draft' or invoice_currency_rate == expected_currency_rate">\n                                            <button type="object" name="refresh_invoice_currency_rate" icon="refresh" title="Reset the currency rate to the default accordingly to the invoice date" class="btn btn-link p-0"/>\n                                        </div>\n                                    </div>\n                                    <div name="currency_div" groups="base.group_multi_currency" class="w-100" invisible="move_type == 'entry'">\n                                        <div class="d-flex gap-1">\n                                            <field name="currency_id" readonly="state != 'draft'" class="oe_inline" options="{'no_create': True}"/>\n                                            <widget name="account_pick_currency_date" invisible="state != 'draft' or currency_id == company_currency_id"/>\n                                        </div>\n                                        <div name="currency_conversion_div" class="d-flex gap-1 text-muted" invisible="currency_id == company_currency_id">\n                                            <field name="company_currency_id" invisible="1"/>\n                                            <field name="invoice_currency_rate" invisible="1"/>\n                                            <widget name="account_currency_exchange_rate" readonly="state != 'draft'" options="{'rate_field': 'invoice_currency_rate'}"/>\n                                            <div invisible="show_journal or state != 'draft' or invoice_currency_rate == expected_currency_rate">\n                                            <button type="object" name="refresh_invoice_currency_rate" icon="refresh" title="Reset the currency rate to the default accordingly to the invoice date" class="btn btn-link p-0"/>\n                                        </div>\n                                        </div>\n                                    </div>\n                                </div>\n                            </group>\n                            <div>\n                                <field name="document_tax_mode" id="document_tax_mode_mobile" class="tax_mode_badge d-md-none" widget="document_tax_mode_selector" nolabel="True" readonly="state != 'draft'" required="move_type != 'entry'"/>\n                            </div>\n                        </group>\n                        <notebook>\n                            <page id="invoice_tab" name="invoice_tab" string="Invoice Lines" invisible="move_type == 'entry'">\n                                <div class="position-relative document_tax_mode">\n                                    <field name="document_tax_mode" id="document_tax_mode" class="overlap_badge_tab tax_mode_badge d-none d-md-block" widget="document_tax_mode_selector" nolabel="True" readonly="state != 'draft'" required="move_type != 'entry'"/>\n                                </div>\n                                <field name="invoice_line_ids" widget="product_label_section_and_note_field_o2m" mode="list,kanban" context="{                                            'default_move_type': context.get('default_move_type'),                                            'journal_id': journal_id,                                            'default_partner_id': commercial_partner_id,                                            'default_currency_id': currency_id or company_currency_id,                                            'default_display_type': 'product',                                            'quick_encoding_vals': quick_encoding_vals,                                            'from_invoice_tab': True,                                        }" readonly="state != 'draft'" aggregated_fields="price_subtotal,price_total" options="{'hide_composition': True, 'hide_prices': True, 'subsections': True}">\n                                    <list name="journal_items" editable="bottom" string="Journal Items" default_order="sequence, id">\n                                        <control>\n                                            <create name="add_line_control" string="Add a line" data-hotkey="l"/>\n                                            <create name="add_section_control" string="Add a section" data-hotkey="shift+h" context="{'default_display_type': 'line_section'}"/>\n                                            <create name="add_note_control" string="Add a note" data-hotkey="shift+n" context="{'default_display_type': 'line_note'}"/>\n                                            <button name="action_add_from_catalog" string="Catalog" data-hotkey="shift+k" type="object" class="btn-link" context="{'order_id': parent.id}"/>\n                                        </control>\n\n                                        <!-- Displayed fields -->\n                                        <field name="sequence" widget="handle"/>\n                                        <column name="product_and_description">\n                                            <field name="product_id" optional="hide" widget="account_product_field" domain="                                                     context.get('default_move_type') in ('out_invoice', 'out_refund', 'out_receipt')                                                     and [('sale_ok', '=', True)]                                                     or [('purchase_ok', '=', True)]                                                 " placeholder="Search a product" invisible="display_type in ('line_section', 'line_subsection', 'line_note')"/>\n                                            <field name="name" placeholder="Enter a description" decoration-it="display_type == 'product' and product_id" optional="show" widget="text"/>\n                                            <field name="label" widget="account_label_text" invisible="display_type in ('line_section', 'line_subsection', 'line_note')"/>\n                                        </column>\n                                        <field name="account_id" context="{                                                     'partner_id': partner_id,                                                     'move_type': parent.move_type,                                                     'search_default_type_asset_fixed': 'in_' in parent.move_type,                                                     'search_default_type_expense': 'in_' in parent.move_type,                                                     'search_default_type_expense_direct_cost': 'in_' in parent.move_type,                                                     'search_default_account_type': 'out_' in parent.move_type and 'income',                                                     'preferred_account_type': 'out_' in parent.move_type and 'income' or 'in_' in parent.move_type and 'expense',                                                     'list_view_ref': 'account.view_account_list_from_entry',                                                     'from_bill': move_type == 'in_invoice',                                                }" widget="m2o_cell_with_extra_fields" groups="account.group_account_readonly" options="{'no_quick_create': True, 'no_open': True, 'parent_field': 'invoice_line_ids'}" domain="[('company_ids', 'parent_of', company_id), ('account_type', 'not in', ('asset_cash', 'asset_receivable', 'liability_payable', 'off_balance'))]" required="display_type not in ('line_section', 'line_subsection', 'line_note')"/>\n                                        <field name="analytic_distribution" widget="analytic_distribution" string="Analytic" groups="analytic.group_analytic_accounting" optional="show" options="{'product_field': 'product_id', 'account_field': 'account_id', 'amount_field': 'price_subtotal'}" business_domain_compute="parent.move_type in ['out_invoice', 'out_refund', 'out_receipt'] and 'invoice' or parent.move_type in ['in_invoice', 'in_refund', 'in_receipt'] and 'bill' or 'general'"/>\n                                        <field name="quantity" optional="show"/>\n                                        <field name="product_uom_id" groups="uom.group_uom" optional="show" width="92px" options="{'no_create': True, 'no_open': True, 'quantity_field': 'quantity'}" widget="many2one_uom"/>\n                                        <!-- /l10n_in_edi.test_edi_json -->\n                                        <!-- required for @api.onchange('product_id') -->\n                                        <field name="product_uom_id" column_invisible="True"/>\n                                        <field name="price_unit" string="Price"/>\n                                        <field name="discount" width="50px" string="Disc.%" optional="hide"/>\n                                        <field name="tax_ids" widget="many2many_tax_tags" domain="[('type_tax_use', '=?', parent.invoice_filter_type_domain), ('company_id', 'parent_of', parent.company_id), ('country_id', '=', parent.tax_country_id)]" context="{                                                     'append_fields': not parent.invoice_filter_type_domain and ['type_tax_use'],                                                     'active_test': True,                                                     'dynamic_fiscal_position_id': parent.fiscal_position_id,                                                }" options="{'no_create': True}" optional="show"/>\n                                        <field name="deductible_percentage" column_invisible="parent.move_type not in ('in_invoice', 'in_refund', 'in_receipt')" string="Professional" optional="hide" widget="percentage" groups="!account.group_partial_purchase_deductibility"/>\n                                        <field name="deductible_percentage" column_invisible="parent.move_type not in ('in_invoice', 'in_refund', 'in_receipt')" string="Professional" optional="show" widget="percentage" groups="account.group_partial_purchase_deductibility"/>\n                                        <field name="price_subtotal" column_invisible="parent.document_tax_mode == 'tax_included'" string="Amount"/>\n                                        <field name="price_total" column_invisible="parent.document_tax_mode == 'tax_excluded'" string="Amount"/>\n                                        <widget name="section_state"/>\n                                        <!-- Others fields -->\n                                        <field name="partner_id" column_invisible="True"/>\n                                        <field name="currency_id" column_invisible="True"/>\n                                        <field name="company_id" column_invisible="True"/>\n                                        <field name="company_currency_id" column_invisible="True"/>\n                                        <field name="display_type" force_save="1" column_invisible="True"/>\n                                        <field name="collapse_prices" column_invisible="True"/>\n                                        <field name="collapse_composition" column_invisible="True"/>\n                                        <field name="document_tax_mode" column_invisible="True"/>\n                                    </list>\n                                    <kanban class="o_kanban_mobile">\n                                        <!-- Displayed fields -->\n                                        <templates>\n                                            <t t-name="card">\n                                                <div t-attf-class="ps-0 pe-0 {{ record.display_type.raw_value ? 'o_is_' + record.display_type.raw_value : '' }}">\n                                                    <t t-if="!['line_note', 'line_section', 'line_subsection'].includes(record.display_type.raw_value)">\n                                                        <div class="row g-0">\n                                                            <div t-if="record.product_id.raw_value" class="col-2 pe-3">\n                                                                <field name="product_id" widget="image" options="{'preview_image': 'image_128'}" class="w-100"/>\n                                                            </div>\n                                                            <div t-att-class="{'col-10': record.product_id.raw_value}">\n                                                                <div class="row">\n                                                                    <div class="col">\n                                                                        <field t-if="record.product_id.raw_value" class="fw-bold" name="product_id"/>\n                                                                        <field t-else="" class="fw-bold" name="name"/>\n                                                                    </div>\n                                                                    <div class="col-auto fw-bold float-end text-end">\n                                                                        <field name="price_subtotal" t-if="record.document_tax_mode.raw_value == 'tax_excluded'" string="Amount"/>\n                                                                        <field name="price_total" t-if="record.document_tax_mode.raw_value == 'tax_included'" string="Amount"/>\n                                                                    </div>\n                                                                </div>\n                                                                <div class="text-muted">\n                                                                    Quantity:\n                                                                    <field name="quantity"/>\n                                                                    <field name="product_uom_id" groups="uom.group_uom" widget="many2one_uom"/>\n                                                                </div>\n                                                                <div class="text-muted">\n                                                                    Unit Price:\n                                                                    <field name="price_unit"/>\n                                                                </div>\n                                                            </div>\n                                                        </div>\n                                                    </t>\n                                                    <t t-if="['line_section', 'line_subsection', 'line_note'].includes(record.display_type.raw_value)">\n                                                        <div t-att-class="{                                                             'fw-bolder': record.display_type.raw_value === 'line_section',                                                             'fw-bold': record.display_type.raw_value === 'line_subsection',                                                             'fst-italic': record.display_type.raw_value === 'line_note',                                                         }">\n                                                            <field name="name"/>\n                                                        </div>\n                                                    </t>\n                                                </div>\n                                            </t>\n                                        </templates>\n\n                                        <!-- Others fields -->\n                                        <field name="tax_calculation_rounding_method"/>\n                                        <field name="currency_id"/>\n                                        <field name="company_currency_id"/>\n                                        <field name="display_type" force_save="1"/>\n                                        <field name="move_type"/>\n                                        <field name="document_tax_mode"/>\n                                    </kanban>\n\n                                    <!-- Form view to cover mobile use -->\n                                    <form>\n                                        <sheet>\n                                            <field name="tax_calculation_rounding_method" invisible="1"/>\n                                            <field name="display_type" invisible="1"/>\n                                            <field name="company_id" invisible="1"/>\n                                            <field name="partner_id" invisible="1"/>\n                                            <group>\n                                                <field name="product_id" widget="many2one_barcode"/>\n                                                <label for="name" string="Description" invisible="display_type in ('line_section', 'line_subsection', 'line_note')"/>\n                                                <label for="name" string="Section" invisible="display_type != 'line_section'"/>\n                                                <label for="name" string="Subsection" invisible="display_type != 'line_subsection'"/>\n                                                <label for="name" string="Note" invisible="display_type != 'line_note'"/>\n                                                <field name="name" widget="text" nolabel="1"/>\n                                                <field name="quantity"/>\n                                                <field name="product_uom_id" groups="uom.group_uom" widget="many2one_uom"/>\n                                                <field name="price_unit"/>\n                                                <field name="discount" string="Disc.%"/>\n                                            </group>\n                                            <group>\n                                                <field name="account_id" domain="[('company_ids', 'parent_of', company_id)]" options="{'no_create': True}" context="{'partner_id': partner_id, 'move_type': parent.move_type}"/>\n                                                <field name="tax_ids" widget="many2many_tax_tags" domain="[('type_tax_use', '=?', parent.invoice_filter_type_domain), ('company_id', 'parent_of', parent.company_id), ('country_id', '=', parent.tax_country_id)]" context="{                                                         'append_fields': not parent.invoice_filter_type_domain and ['type_tax_use'],                                                         'active_test': True,                                                         'dynamic_fiscal_position_id': parent.fiscal_position_id,                                                     }" options="{'no_create': True}"/>\n                                                <field name="analytic_distribution" widget="analytic_distribution" groups="analytic.group_analytic_accounting"/>\n                                            </group>\n                                            <group>\n                                                <field name="price_subtotal" invisible="parent.move_type not in ['in_invoice', 'in_refund', 'in_receipt'] and parent.company_price_include == 'tax_included'" string="Amount"/>\n                                                <field name="price_total" invisible="parent.move_type in ['in_invoice', 'in_refund', 'in_receipt'] or parent.company_price_include == 'tax_excluded'" string="Amount"/>\n                                            </group>\n                                        </sheet>\n                                    </form>\n                                </field>\n                                <group col="12" class="oe_invoice_lines_tab overflow-hidden pt-3 pt-md-0">\n                                    <group colspan="8">\n                                        <field name="narration" placeholder="Terms and Conditions" nolabel="1"/>\n                                    </group>\n                                    <!-- Totals (only invoices / receipts) -->\n                                    <group colspan="4" class="m-0">\n                                        <group class="oe_subtotal_footer gx-0 gx-md-5" invisible="move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt') or payment_state == 'invoicing_legacy'">\n\n                                            <field name="tax_totals" widget="account-tax-totals-field" nolabel="1" colspan="2" class="mb-3 mb-md-0" readonly="state != 'draft' or (move_type not in ('in_invoice', 'in_refund', 'in_receipt') and not quick_edit_mode)"/>\n\n                                            <field name="invoice_payments_widget" colspan="2" nolabel="1" widget="payment" class="mb-3 mb-md-0" invisible="not invoice_payments_widget"/>\n                                            <div class="d-flex justify-content-end gap-3" colspan="2">\n                                                <label for="amount_residual"/>\n                                                <field name="amount_residual" class="oe_subtotal_footer_separator w-auto"/>\n                                            </div>\n                                        </group>\n                                        <group class="oe_subtotal_footer px-4" invisible="not invoice_has_outstanding" groups="account.group_account_invoice,account.group_account_readonly">\n                                            <field name="invoice_outstanding_credits_debits_widget" class="oe_invoice_outstanding_credits_debits py-3" colspan="2" nolabel="1" widget="payment"/>\n                                        </group>\n                                    </group>\n                                </group>\n                            </page>\n                            <page id="aml_tab" string="Journal Items" groups="account.group_account_readonly" name="aml_tab">\n                                <field name="line_ids" mode="list,kanban" context="{                                            'default_move_type': context.get('default_move_type'),                                            'line_ids': line_ids,                                            'journal_id': journal_id,                                            'default_partner_id': commercial_partner_id,                                            'default_currency_id': currency_id or company_currency_id,                                            'kanban_view_ref': 'account.account_move_line_view_kanban_mobile',                                        }" invisible="payment_state == 'invoicing_legacy' and move_type != 'entry'" readonly="state != 'draft'">\n                                    <list editable="bottom" string="Journal Items" decoration-muted="display_type in ('line_section', 'line_note')" default_order="sequence, id">\n                                        <!-- Displayed fields -->\n                                        <field name="account_id" invisible="display_type in ('line_section', 'line_note')" required="display_type not in ('line_section', 'line_note')" domain="[('company_ids', 'parent_of', company_id), ('account_type', '!=', 'asset_cash')]"/>\n                                        <field name="partner_id" optional="show" domain="['|', ('parent_id', '=', False), ('is_company', '=', True)]" column_invisible="parent.move_type != 'entry'"/>\n                                        <field name="name" optional="show"/>\n                                        <field name="analytic_distribution" widget="analytic_distribution" groups="analytic.group_analytic_accounting" optional="show" options="{'account_field': 'account_id'}" business_domain_compute="parent.move_type in ['out_invoice', 'out_refund', 'out_receipt'] and 'invoice' or parent.move_type in ['in_invoice', 'in_refund', 'in_receipt'] and 'bill' or 'general'"/>\n                                        <field name="date_maturity" optional="hide" decoration-danger="date_maturity and date_maturity &lt; context_today().strftime('%Y-%m-%d') and parent.payment_state not in ('paid', 'in_payment', 'reversed')" invisible="display_type in ('line_section', 'line_note')" column_invisible="context.get('view_no_maturity')"/>\n                                        <field name="amount_currency" groups="base.group_multi_currency" optional="hide"/>\n                                        <field name="currency_id" options="{'no_create': True}" optional="hide" groups="base.group_multi_currency" column_invisible="parent.move_type != 'entry'"/>\n                                        <field name="tax_ids" widget="autosave_many2many_tax_tags" optional="hide" domain="[('type_tax_use', '=?', parent.invoice_filter_type_domain), ('company_id', 'parent_of', parent.company_id)]" context="{                                                     'append_fields': not parent.invoice_filter_type_domain and ['type_tax_use'],                                                     'active_test': True                                                }" options="{'no_create': True}" force_save="1" readonly="display_type in ('line_section', 'line_note') or tax_line_id or (parent.move_type in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt') and account_type in ('asset_receivable', 'liability_payable'))"/>\n                                        <field name="debit" sum="Total Debit" invisible="display_type in ('line_section', 'line_subsection', 'line_note')" readonly="parent.move_type in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt') and display_type in ('line_section', 'line_note', 'product')" decoration-muted="debit == 0"/>\n                                        <field name="credit" sum="Total Credit" invisible="display_type in ('line_section', 'line_subsection', 'line_note')" readonly="parent.move_type in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt') and display_type in ('line_section', 'line_note', 'product')" decoration-muted="credit == 0"/>\n                                        <field name="balance" column_invisible="True"/>\n                                        <field name="discount_date" string="Discount Date" optional="hide"/>\n                                        <field name="discount_amount_currency" string="Discount Amount" optional="hide"/>\n\n                                        <field name="tax_tag_ids" widget="many2many_tags" string="Tax Grids" optional="show" options="{'no_create': True}" domain="[                                                     ('applicability', '=', 'taxes'),                                                     '|', ('country_id', '=', parent.tax_country_id),                                                     ('country_id', '=', False),                                                 ]"/>\n\n                                        <!-- Others fields -->\n                                        <field name="tax_line_id" column_invisible="True"/>\n                                        <field name="company_currency_id" column_invisible="True"/>\n                                        <field name="display_type" force_save="1" column_invisible="True"/>\n                                        <field name="company_id" column_invisible="True"/>\n                                        <field name="sequence" column_invisible="True"/>\n                                        <field name="id" column_invisible="True"/>\n                                        <field name="account_internal_group" column_invisible="True"/>\n                                        <field name="account_type" column_invisible="True"/>\n                                    </list>\n                                    <!-- Form view to cover mobile use -->\n                                    <form>\n                                      <group>\n                                        <field name="account_id" domain="[('company_ids', 'parent_of', company_id)]"/>\n                                        <field name="partner_id" domain="['|', ('parent_id', '=', False), ('is_company', '=', True)]"/>\n                                        <field name="name"/>\n                                        <field name="analytic_distribution" widget="analytic_distribution" groups="analytic.group_analytic_accounting"/>\n                                        <field name="amount_currency" groups="base.group_multi_currency"/>\n                                        <field name="company_currency_id" invisible="1"/>\n                                        <field name="company_id" invisible="1"/>\n                                        <field name="currency_id" options="{'no_create': True}" groups="base.group_multi_currency"/>\n                                        <field name="debit" sum="Total Debit"/>\n                                        <field name="credit" sum="Total Credit"/>\n                                        <field name="balance" invisible="1"/>\n                                        <field name="tax_ids" string="Taxes Applied" widget="many2many_tax_tags" options="{'no_create': True}" domain="[('type_tax_use', '=?', parent.invoice_filter_type_domain), ('company_id', 'parent_of', parent.company_id)]" context="{                                                     'append_fields': not parent.invoice_filter_type_domain and ['type_tax_use'],                                                     'active_test': True,                                                }"/>\n                                        <field name="date_maturity" required="0" invisible="context.get('view_no_maturity', False)"/>\n                                      </group>\n                                    </form>\n                                </field>\n                                <div class="alert alert-info text-center mb-0" role="alert" invisible="payment_state != 'invoicing_legacy' or move_type == 'entry'">\n                                    <span>This entry has been generated through the Invoicing app, before installing Accounting. Its balance has been imported separately.</span>\n                                </div>\n                            </page>\n                            <page id="other_tab" string="Other Info" name="other_info" invisible="move_type == 'entry'">\n                                <group id="other_tab_group">\n                                    <group string="Invoice" name="sale_info_group" invisible="move_type not in ('out_invoice', 'out_refund')">\n                                        <label for="ref" string="Customer Reference"/>\n                                        <field name="ref" nolabel="1"/>\n                                        <field name="user_id" invisible="1" force_save="1"/>\n                                        <field name="invoice_user_id" domain="[('share', '=', False)]" widget="many2one_avatar_user"/>\n                                        <field name="invoice_origin" string="Source Document" force_save="1" invisible="1"/>\n                                        <field name="partner_bank_id" widget="many2one_bank" context="{'default_partner_id': bank_partner_id}" domain="[('partner_id.ref_company_ids', 'parent_of', company_id)]" invisible="move_type != 'out_invoice'" readonly="is_move_sent and state != 'draft'"/>\n                                        <field name="partner_bank_id" context="{'default_partner_id': bank_partner_id, 'display_account_trust': True}" domain="[('partner_id', '=', bank_partner_id)]" invisible="move_type != 'out_refund'" readonly="is_move_sent and state != 'draft'"/>\n                                        <field name="payment_reference" invisible="move_type not in ('out_invoice', 'out_refund')" readonly="inalterable_hash" placeholder="Standard communication"/>\n                                        <field name="qr_code_method" invisible="not display_qr_code"/>\n                                        <field name="delivery_date" readonly="state != 'draft'"/>\n                                    </group>\n                                    <group string="Accounting" name="accounting_info_group">\n                                        <field name="company_id" groups="base.group_multi_company" domain="[('id', 'child_of', journal_company_id)]"/>\n                                        <field name="invoice_incoterm_placeholder" invisible="1"/>    <!-- Needed for placeholder_field -->\n                                        <field name="invoice_incoterm_id" options="{'placeholder_field': 'invoice_incoterm_placeholder'}" invisible="move_type in ('out_receipt', 'in_receipt')"/>\n                                        <field name="incoterm_location" invisible="move_type in ('out_receipt', 'in_receipt')"/>\n                                        <field name="fiscal_position_id" readonly="state in ['cancel', 'posted']"/>\n                                        <field name="secured" groups="account.group_account_secured,base.group_no_one"/>\n                                        <field name="preferred_payment_method_line_id" string="Payment Method" domain="[('payment_type', '=', 'inbound'), ('company_id', 'parent_of', company_id)]" invisible="move_type in ('in_invoice', 'in_refund', 'in_receipt')"/>\n                                        <field name="preferred_payment_method_line_id" string="Payment Method" domain="[('payment_type', '=', 'outbound'), ('company_id', 'parent_of', company_id)]" invisible="move_type in ('out_invoice', 'out_refund', 'out_receipt')"/>\n                                        <field name="invoice_source_email" widget="email" invisible="move_type not in ('in_invoice', 'in_refund') or not invoice_source_email"/>\n                                        <field name="auto_post" invisible="move_type in ('out_receipt', 'in_receipt')" readonly="state != 'draft'"/>\n                                        <field name="auto_post_until" invisible="auto_post in ('no', 'at_date')" readonly="state != 'draft'"/>\n                                    </group>\n                                </group>\n                            </page>\n                            <page id="other_tab_entry" string="Other Info" name="other_info" invisible="move_type != 'entry'">\n                                <group id="other_tab_entry_group">\n                                    <group name="misc_group">\n                                        <field name="auto_post" invisible="move_type != 'entry'" readonly="state != 'draft'"/>\n                                