"o.move_type == 'in_invoice' and not o.journal_id.is_self_billing\\">\\n                        <t name=\\"vendor_bill_title\\">Vendor Bill</t>\\n                    </span>\\n                    <span t-elif=\\"o.move_type == 'in_invoice' and o.journal_id.is_self_billing\\">\\n                        <t name=\\"self_billing_invoice_title\\">Self Billing</t>\\n                    </span>\\n                </t>\\n                <t t-else=\\"\\">\\n                    <span t-if=\\"o.move_type == 'out_invoice' and o.state == 'posted'\\">\\n                        <t name=\\"proforma_invoice_title\\">Proforma Invoice</t>\\n                    </span>\\n                    <span t-elif=\\"o.move_type == 'out_invoice' and o.state == 'draft'\\">\\n                        <t name=\\"draft_proforma_invoice_title\\">Draft Proforma Invoice</t>\\n                    </span>\\n                    <span t-elif=\\"o.move_type == 'out_invoice' and o.state == 'cancel'\\">\\n                        <t name=\\"cancelled_proforma_invoice_title\\">Cancelled Proforma Invoice</t>\\n                    </span>\\n                    <span t-elif=\\"o.move_type == 'out_refund' and o.state == 'posted'\\">\\n                        <t name=\\"proforma_credit_note_title\\">Proforma Credit Note</t>\\n                    </span>\\n                    <span t-elif=\\"o.move_type == 'out_refund' and o.state == 'draft'\\">\\n                        <t name=\\"draft_proforma_credit_note_title\\">Draft Proforma Credit Note</t>\\n                    </span>\\n                    <span t-elif=\\"o.move_type == 'out_refund' and o.state == 'cancel'\\">\\n                        <t name=\\"cancelled_proforma_credit_note_title\\">Cancelled Proforma Credit Note</t>\\n                    </span>\\n                    <span t-elif=\\"o.move_type == 'in_refund'\\">\\n                        <t name=\\"proforma_vendor_credit_note_title\\">Proforma Vendor Credit Note</t>\\n                    </span>\\n                    <span t-elif=\\"o.move_type == 'in_invoice'\\">\\n                        <t name=\\"proforma_vendor_bill_title\\">Proforma Vendor Bill</t>\\n                    </span>\\n                </t>\\n                <span t-if=\\"o.name and o.name != '/'\\" t-field=\\"o.name\\">INV/2023/0001</span>\\n            </t>\\n            <t t-set=\\"o\\" t-value=\\"o.with_context(lang=lang)\\"/>\\n            <t t-set=\\"information_block\\" t-if=\\"o.partner_shipping_id and (o.partner_shipping_id != o.partner_id)\\" groups=\\"account.group_delivery_invoice_address\\">\\n                <div name=\\"shipping_address_block\\">\\n                    <strong class=\\"d-block mt-3\\">Shipping Address</strong>\\n                    <div t-field=\\"o.partner_shipping_id\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: True}\\"/>\\n                </div>\\n            </t>\\n            <t t-set=\\"address\\">\\n                <t t-if=\\"o.partner_shipping_id and (o.partner_shipping_id != o.partner_id)\\">\\n                    <t name=\\"address_not_same_as_shipping\\">\\n                        <address class=\\"mb-0\\" t-field=\\"o.partner_id\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: True}\\"/>\\n                        <div id=\\"partner_vat_address_not_same_as_shipping\\">\\n                            <t t-out=\\"o._get_document_partner_ident_line()\\" id=\\"inv_tax_id_label\\"/>\\n                        </div>\\n                    </t>\\n                </t>\\n                <t t-elif=\\"o.partner_shipping_id and (o.partner_shipping_id == o.partner_id)\\">\\n                    <t name=\\"address_same_as_shipping\\">\\n                        <address class=\\"mb-0\\" t-field=\\"o.partner_id\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: True}\\"/>\\n                        <div id=\\"partner_vat_address_same_as_shipping\\">\\n                            <t t-out=\\"o._get_document_partner_ident_line()\\" id=\\"inv_tax_id_label\\"/>\\n                        </div>\\n                    </t>\\n                </t>\\n                <t t-else=\\"\\">\\n                    <t name=\\"no_shipping\\">\\n                        <address class=\\"mb-0\\" t-field=\\"o.partner_id\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: True}\\"/>\\n                        <div id=\\"partner_vat_no_shipping\\">\\n                            <t t-out=\\"o._get_document_partner_ident_line()\\" id=\\"inv_tax_id_label\\"/>\\n                        </div>\\n                    </t>\\n                </t>\\n            </t>\\n            <t t-call=\\"web.external_layout\\" forced_vat=\\"o.fiscal_position_id.foreign_vat\\" layout_document_title=\\"layout_document_title\\" information_block=\\"information_block\\" lang=\\"lang\\" address=\\"address\\">\\n                <div class=\\"clearfix invoice_main\\">\\n                    <div class=\\"page mb-4\\">\\n                        <div class=\\"oe_structure\\"/>\\n                        <div id=\\"informations\\" class=\\"row mb-4\\" t-if=\\"o.invoice_date or (o.invoice_date_due and o.move_type == 'out_invoice' and o.state == 'posted') or o.delivery_date or o.invoice_origin or o.partner_id.ref or o.ref or o.invoice_incoterm_id\\">\\n                            <div class=\\"col\\" t-if=\\"o.invoice_date\\" name=\\"invoice_date\\">\\n                                <t t-if=\\"o.move_type == 'out_invoice'\\"><strong>Invoice Date</strong></t>\\n                                <t t-elif=\\"o.move_type == 'out_refund'\\"><strong>Credit Note Date</strong></t>\\n                                <t t-elif=\\"o.move_type == 'out_receipt'\\"><strong>Receipt Date</strong></t>\\n                                <t t-else=\\"\\"><strong>Date</strong></t>\\n                                <div t-field=\\"o.invoice_date\\">2023-09-12</div>\\n                            </div>\\n                            <div class=\\"col\\" t-if=\\"o.invoice_date_due and o.move_type == 'out_invoice' and o.state == 'posted'\\" name=\\"due_date\\">\\n                                <strong>Due Date</strong>\\n                                <div t-field=\\"o.invoice_date_due\\">2023-10-31</div>\\n                            </div>\\n                            <div class=\\"col\\" t-if=\\"o.taxable_supply_date and o.show_taxable_supply_date\\" name=\\"taxable_supply_date\\">\\n                                <strong>Taxable Supply</strong>\\n                                <div t-field=\\"o.taxable_supply_date\\">2023-10-31</div>\\n                            </div>\\n                            <div class=\\"col\\" t-if=\\"o.delivery_date\\" name=\\"delivery_date\\">\\n                                <strong>Delivery Date</strong>\\n                                <div t-field=\\"o.delivery_date\\">2023-09-25</div>\\n                            </div>\\n                            <div class=\\"col\\" t-if=\\"o.invoice_origin\\" name=\\"origin\\">\\n                                <strong>Source</strong>\\n                                <div t-field=\\"o.invoice_origin\\">SO123</div>\\n                            </div>\\n                            <div class=\\"col\\" t-if=\\"o.partner_id.ref\\" name=\\"customer_code\\">\\n                                <strong>Customer Code</strong>\\n                                <div t-field=\\"o.partner_id.ref\\"/>\\n                            </div>\\n                            <div class=\\"col\\" t-if=\\"o.ref\\" name=\\"reference\\">\\n                                <strong>Reference</strong>\\n                                <div t-field=\\"o.ref\\">INV/2023/00001</div>\\n                            </div>\\n                            <div class=\\"col\\" t-if=\\"o.invoice_incoterm_id\\" name=\\"incoterm_id\\">\\n                                <strong>Incoterm</strong>\\n                                <div t-if=\\"o.incoterm_location\\">\\n                                    <span t-field=\\"o.invoice_incoterm_id.code\\"/> <br/>\\n                                    <span t-field=\\"o.incoterm_location\\"/>\\n                                </div>\\n                                <div t-else=\\"\\" t-field=\\"o.invoice_incoterm_id.code\\" class=\\"m-0\\"/>\\n                            </div>\\n                        </div>\\n\\n                        <t t-set=\\"lines_to_report\\" t-value=\\"o._get_move_lines_to_report()\\"/>\\n                        <t t-set=\\"display_discount\\" t-value=\\"any(l.discount for l in lines_to_report)\\"/>\\n                        <t t-set=\\"display_taxes\\" t-value=\\"any(l.tax_ids for l in o.invoice_line_ids)\\"/>\\n                        <div class=\\"oe_structure\\"/>\\n                        <t t-set=\\"has_long_desc\\" t-value=\\"any(line.name and line.name.count('\\\\n') &gt; 30 for line in o.invoice_line_ids if line.name)\\"/>\\n                        <div class=\\"table-responsive-sm overflow-visible\\">\\n                            <table class=\\"o_has_total_table table o_main_table table-borderless mb-0\\" name=\\"invoice_line_table\\">\\n                                <thead t-attf-style=\\"#{has_long_desc and 'display: table-row-group;' or ''}\\">\\n                                    <tr>\\n                                        <th name=\\"th_description\\" class=\\"text-start\\"><span>Description</span></th>\\n                                        <th name=\\"th_quantity\\" class=\\"text-end\\"><span>Quantity</span></th>\\n                                        <th name=\\"th_priceunit\\" t-attf-class=\\"text-end text-nowrap {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}\\"><span>Unit Price</span></th>\\n                                        <th name=\\"th_discount\\" t-if=\\"display_discount\\" t-attf-class=\\"text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}\\">\\n                                            <span>Disc.%</span>\\n                                        </th>\\n                                        <th name=\\"th_taxes\\" t-if=\\"display_taxes\\" t-attf-class=\\"text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}\\"><span>Taxes</span></th>\\n                                        <th name=\\"th_subtotal\\" class=\\"text-end\\">\\n                                            <span>Amount</span>\\n                                        </th>\\n                                    </tr>\\n                                </thead>\\n                                <tbody class=\\"invoice_tbody\\">\\n                                    <t t-set=\\"current_section\\" t-value=\\"None\\"/>\\n                                    <t t-set=\\"current_subsection\\" t-value=\\"None\\"/>\\n\\n                                    <t t-foreach=\\"lines_to_report\\" t-as=\\"line\\">\\n                                        <t t-set=\\"is_note\\" t-value=\\"line.display_type == 'line_note'\\"/>\\n                                        <t t-set=\\"is_section\\" t-value=\\"line.display_type == 'line_section'\\"/>\\n                                        <t t-set=\\"is_subsection\\" t-value=\\"line.display_type == 'line_subsection'\\"/>\\n                                        <t t-set=\\"is_product\\" t-value=\\"line.display_type == 'product'\\"/>\\n\\n                                        <t t-if=\\"is_section\\">\\n                                            <t t-set=\\"current_section\\" t-value=\\"line\\"/>\\n                                            <t t-set=\\"current_subsection\\" t-value=\\"None\\"/>\\n                                            <t t-set=\\"line_padding\\" t-value=\\"1\\"/>\\n                                        </t>\\n                                        <t t-elif=\\"is_subsection\\">\\n                                            <t t-set=\\"current_subsection\\" t-value=\\"line\\"/>\\n                                            <t t-set=\\"line_padding\\" t-value=\\"3\\"/>\\n                                        </t>\\n                                        <t t-else=\\"\\">\\n                                            <t t-set=\\"line_padding\\" t-value=\\"4 if current_subsection else (3 if current_section else 0)\\"/>\\n                                        </t>\\n                                        <t t-set=\\"padding_style\\" t-value=\\"line_padding and ('padding-left:' + str(line_padding * 8) + 'px') or ''\\"/>\\n                                        <t t-set=\\"hide_details\\" t-value=\\"line.collapse_composition\\"/>\\n                                        <t t-set=\\"hide_prices\\" t-value=\\"line.collapse_prices\\"/>\\n\\n                                        <t t-if=\\"not hide_details and not hide_prices\\">\\n                                            <tr t-att-class=\\"                                                 'fw-bold o_line_section' if is_section else                                                 'fw-bold o_line_subsection' if is_subsection else                                                 'fst-italic o_line_note' if is_note                                                 else ''\\">\\n                                                <t t-set=\\"line_colspan\\" t-value=\\"3 + (1 if display_discount else 0) + (1 if display_taxes and not line.tax_ids else 0)\\"/>\\n                                                <t t-if=\\"is_product\\" name=\\"account_invoice_line_accountable\\">\\n                                                    <td class=\\"w-100\\" name=\\"account_invoice_line_name\\" t-att-style=\\"padding_style\\">\\n                                                        <span t-if=\\"line.label\\" t-field=\\"line.label\\" t-options=\\"{'widget': 'text'}\\" class=\\"d-inline-block w-100 lh-sm\\">Bacon Burger</span>\\n                                                    </td>\\n                                                    <td name=\\"td_quantity\\" class=\\"o_td_quantity text-end\\">\\n                                                        <span t-field=\\"line.quantity\\" class=\\"text-nowrap\\">3.00</span>\\n                                                        <span t-field=\\"line.product_uom_id\\" groups=\\"uom.group_uom\\">units</span>\\n                                                        <span t-if=\\"line.product_uom_id != line.product_id.uom_id\\" groups=\\"uom.group_uom\\" class=\\"text-muted small\\">\\n                                                            <br/>\\n                                                            <t t-set=\\"product_uom_qty\\" t-value=\\"line.product_uom_id._compute_quantity(line.quantity, line.product_id.uom_id)\\"/>\\n                                                            <span t-out=\\"product_uom_qty\\" t-options=\\"{'widget': 'float', 'decimal_precision': 'Product Unit'}\\" data-oe-demo=\\"3.00\\"/> <span t-field=\\"line.product_id.uom_id\\" data-oe-demo=\\"units\\"/>\\n                                                        </span>\\n                                                    </td>\\n                                                    <td name=\\"td_price_unit\\" t-attf-class=\\"text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}\\">\\n                                                        <span t-if=\\"not hide_prices\\" class=\\"text-nowrap\\" t-field=\\"line.price_unit\\">9.00</span>\\n                                                    </td>\\n                                                    <td name=\\"td_discount\\" t-if=\\"display_discount\\" t-attf-class=\\"text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}\\">\\n                                                        <span class=\\"text-nowrap\\" t-field=\\"line.discount\\">0</span>\\n                                                    </td>\\n                                                    <t t-set=\\"taxes\\" t-value=\\"', '.join(tax.tax_label for tax in line.tax_ids if tax.tax_label)\\"/>\\n                                                    <td name=\\"td_taxes\\" t-if=\\"display_taxes\\" t-attf-class=\\"text-end text-nowrap {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }} {{ 'text-nowrap' if len(taxes) &lt; 10 else '' }}\\">\\n                                                        <span t-if=\\"not hide_prices\\" t-out=\\"taxes\\" id=\\"line_tax_ids\\">Tax 15%</span>\\n                                                    </td>\\n                                                    <td name=\\"td_subtotal\\" class=\\"text-end o_price_total\\">\\n                                                        <span t-if=\\"not hide_prices and o.document_tax_mode == 'tax_excluded'\\" class=\\"text-nowrap\\" t-field=\\"line.price_subtotal\\">27.00</span>\\n                                                        <span t-if=\\"not hide_prices and o.document_tax_mode == 'tax_included'\\" class=\\"text-nowrap\\" t-field=\\"line.price_total\\">31.05</span>\\n                                                    </td>\\n                                                </t>\\n                                                <t t-elif=\\"line.display_type in ('line_section', 'line_subsection')\\" name=\\"account_invoice_line_section\\">\\n                                                    <t t-set=\\"section_subtotal\\" t-value=\\"line.get_section_subtotal() if o.company_price_include == 'tax_excluded' else line.get_section_total()\\"/>\\n                                                    <!-- For desktop -->\\n                                                    <td name=\\"line_name_td\\" t-att-colspan=\\"(1 if is_product else line_colspan)\\" t-attf-class=\\"{{'d-none d-md-table-cell' if report_type == 'html' else ''}} border-end-0\\" t-att-style=\\"padding_style\\">\\n                                                        <span t-if=\\"line.label\\" t-field=\\"line.label\\" t-options=\\"{'widget': 'text'}\\">A section title</span>\\n                                                    </td>\\n                                                    <!-- For mobile -->\\n                                                    <td colspan=\\"2\\" t-attf-class=\\"{{'d-md-none d-table-cell' if report_type == 'html' else 'd-none'}} border-end-0\\" t-att-style=\\"padding_style\\">\\n                                                        <span t-if=\\"line.label\\" t-field=\\"line.label\\" t-options=\\"{'widget': 'text'}\\">A section title</span>\\n                                                    </td>\\n                                                    <td colspan=\\"1\\" class=\\"text-end o_price_total\\">\\n                                                        <span t-out=\\"section_subtotal\\" class=\\"text-nowrap\\" t-options=\\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}\\"/>\\n                                                    </td>\\n                                                </t>\\n                                                <t t-elif=\\"is_note\\">\\n                                                    <td colspan=\\"99\\">\\n                                                        <span t-if=\\"line.label\\" t-field=\\"line.label\\" t-options=\\"{'widget': 'text'}\\">A note, whose content usually applies to the section or product above.</span>\\n                                                    </td>\\n                                                </t>\\n                                            </tr>\\n                                        </t>\\n                                        <t t-else=\\"\\">\\n                                            <t t-set=\\"grouped_lines\\" t-value=\\"line._get_child_lines()\\"/>\\n                                            <t t-foreach=\\"grouped_lines\\" t-as=\\"grouped_line\\">\\n                                                <t t-if=\\"grouped_line['display_type'] == 'product' or hide_details\\">\\n                                                    <t t-set=\\"line_colspan\\" t-value=\\"1\\"/>\\n                                                </t>\\n                                                <t t-else=\\"\\">\\n                                                    <t t-set=\\"line_colspan\\" t-value=\\"3 + (1 if display_discount else 0) + (1 if display_taxes and not grouped_line.get('taxes') else 0)\\"/>\\n                                                </t>\\n                                                <t t-if=\\"hide_prices\\">\\n                                                    <t t-if=\\"grouped_line['display_type'] == 'line_section'\\">\\n                                                        <t t-set=\\"current_section\\" t-value=\\"grouped_line\\"/>\\n                                                        <t t-set=\\"current_subsection\\" t-value=\\"None\\"/>\\n                                                    </t>\\n                                                    <t t-if=\\"grouped_line['display_type'] == 'line_subsection'\\">\\n                                                        <t t-set=\\"current_subsection\\" t-value=\\"grouped_line\\"/>\\n                                                    </t>\\n                                                </t>\\n                                                <tr t-att-class=\\"                                                     'fw-bolder o_line_section' if grouped_line.get('display_type') == 'line_section' and not hide_details else                                                     'fw-bold o_line_subsection' if grouped_line.get('display_type') == 'line_subsection' and not hide_details else                                                     ''\\">\\n                                                    <!-- For desktop -->\\n                                                    <td name=\\"account_invoice_line_name_grouped_desktop\\" t-att-colspan=\\"line_colspan\\" t-attf-class=\\"{{'d-none d-md-table-cell' if report_type == 'html' else ''}}\\" t-att-style=\\"padding_style\\">\\n                                                        <span t-out=\\"grouped_line['label']\\" t-options=\\"{'widget': 'text'}\\">Group 1</span>\\n                                                    </td>\\n                                                    <!-- For mobile -->\\n                                                    <td name=\\"account_invoice_line_name_grouped\\" t-att-colspan=\\"2 if grouped_line['display_type'] != 'product' else 1\\" t-attf-class=\\"{{'d-md-none d-table-cell' if report_type == 'html' else 'd-none'}}\\" t-att-style=\\"padding_style\\">\\n                                                        <span t-out=\\"grouped_line['label']\\" t-options=\\"{'widget': 'text'}\\">Group 1</span>\\n                                                    </td>\\n                                                    <td name=\\"td_quantity_grouped\\" colspan=\\"1\\" t-if=\\"hide_details or (hide_prices and grouped_line['display_type'] not in ('line_section', 'line_subsection'))\\" class=\\"o_td_quantity text-end\\">\\n                                                        <!-- Show the line quantity -->\\n                                                        <div t-if=\\"hide_prices and grouped_line['display_type'] not in ('line_section', 'line_subsection')\\">\\n                                                            <span t-out=\\"grouped_line['quantity']\\" t-options=\\"{'widget': 'float', 'decimal_precision': 'Product Unit'}\\">1.00</span>\\n                                                            <t t-if=\\"grouped_line.get('line_uom')\\">\\n                                                                <span t-out=\\"grouped_line['line_uom'].display_name\\" groups=\\"uom.group_uom\\">Unit</span>\\n                                                                <span t-if=\\"grouped_line.get('product_uom') != grouped_line['line_uom']\\" groups=\\"uom.group_uom\\" class=\\"text-muted small\\">\\n                                                                    <br/>\\n                                                                    <t t-set=\\"product_uom_qty\\" t-value=\\"grouped_line['line_uom']._compute_quantity(grouped_line['quantity'], grouped_line['product_uom'])\\"/>\\n                                                                    <span t-out=\\"product_uom_qty\\" t-options=\\"{'widget': 'float', 'decimal_precision': 'Product Unit'}\\" data-oe-demo=\\"3.00\\"/> <span t-out=\\"grouped_line['product_uom'].display_name\\" data-oe-demo=\\"units\\"/>\\n                                                                </span>\\n                                                            </t>\\n                                                        </div>\\n                                                    </td>\\n                                                    <td name=\\"td_price_unit_grouped\\" t-if=\\"hide_details or grouped_line['display_type'] not in ('line_section', 'line_subsection')\\" colspan=\\"1\\" t-attf-class=\\"text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}\\">\\n                                                        <span t-if=\\"not hide_prices\\" t-out=\\"grouped_line['price_subtotal']\\" t-options=\\"{'widget': 'float', 'decimal_precision': 'Product Price'}\\" class=\\"text-nowrap\\">9.00</span>\\n                                                    </td>\\n                                                    <td name=\\"td_discount_grouped\\" t-if=\\"display_discount and (hide_details or grouped_line['display_type'] == 'product')\\" colspan=\\"1\\" t-attf-class=\\"text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}\\"/>\\n                                                    <td name=\\"td_taxes_grouped\\" colspan=\\"1\\" t-if=\\"display_taxes and (hide_details or grouped_line['display_type'] == 'product' or grouped_line.get('taxes'))\\" t-attf-class=\\"text-end {{'d-none d-md-table-cell' if report_type == 'html' else ''}}\\">\\n                                                        <span t-if=\\"grouped_line.get('taxes')\\" t-out=\\"','.join(grouped_line['taxes'])\\" id=\\"grouped_line_tax_ids\\">Tax 15%</span>\\n                                                    </td>\\n                                                    <td name=\\"td_subtotal_grouped\\" colspan=\\"1\\" class=\\"text-end o_price_total\\">\\n                                                        <span t-if=\\"(grouped_line.get('display_type') == 'line_section' or (not hide_prices and grouped_line.get('display_type') == 'line_subsection') or hide_details) and o.document_tax_mode == 'tax_excluded'\\" class=\\"text-nowrap\\" t-out=\\"grouped_line['price_subtotal']\\" t-options=\\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}\\">27.00</span>\\n                                                        <span t-if=\\"(grouped_line.get('display_type') == 'line_section' or (not hide_prices and grouped_line.get('display_type') == 'line_subsection') or hide_details) and o.document_tax_mode == 'tax_included'\\" class=\\"text-nowrap\\" t-out=\\"grouped_line['price_total']\\" t-options=\\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}\\">31.05</span>\\n                                                    </td>\\n                                                </tr>\\n                                            </t>\\n                                        </t>\\n                                    </t>\\n                                </tbody>\\n                            </table>\\n                        </div>\\n                        <div class=\\"overflow-hidden\\">\\n                            <div id=\\"right-elements\\" class=\\"float-end ms-5\\">\\n                                <div id=\\"total\\" class=\\"clearfix\\">\\n                                    <div class=\\"ms-auto\\">\\n                                        <table class=\\"o_total_table table table-borderless avoid-page-break-inside\\">\\n\\n                                            <!-- Tax totals summary (invoice currency) -->\\n                                            <t t-if=\\"o.tax_totals\\" t-call=\\"account.document_tax_totals\\" tax_totals=\\"o.tax_totals\\" currency=\\"o.currency_id\\"/>\\n\\n                                            <!--Payments-->\\n                                            <t t-if=\\"print_with_payments\\">\\n                                                <t t-if=\\"o.payment_state != 'invoicing_legacy'\\">\\n                                                    <t t-set=\\"payments_vals\\" t-value=\\"o.sudo().invoice_payments_widget and o.sudo().invoice_payments_widget['content'] or []\\"/>\\n                                                    <t t-foreach=\\"payments_vals\\" t-as=\\"payment_vals\\">\\n                                                        <tr t-if=\\"payment_vals['is_exchange'] == 0\\">\\n                                                            <td>\\n                                                                <i class=\\"oe_form_field text-end oe_payment_label\\">\\n                                                                    <t t-if=\\"payment_vals['is_refund']\\">Reversed on </t>\\n                                                                    <t t-else=\\"\\">Paid on </t>\\n                                                                    <t t-out=\\"payment_vals['date']\\" t-options=\\"{&quot;widget&quot;: &quot;date&quot;}\\">2021-09-19</t>\\n                                                                </i>\\n                                                            </td>\\n                                                            <td class=\\"text-end\\">\\n                                                                <span t-out=\\"payment_vals['amount']\\" t-options=\\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}\\">20.00</span>\\n                                                            </td>\\n                                                        </tr>\\n                                                    </t>\\n                                                    <t t-if=\\"len(payments_vals) &gt; 0\\">\\n                                                        <tr class=\\"fw-bold\\">\\n                                                            <td>Amount Due</td>\\n                                                            <td class=\\"text-end\\">\\n                                                                <span t-field=\\"o.amount_residual\\">11.05</span>\\n                                                            </td>\\n                                                        </tr>\\n                                                    </t>\\n                                                </t>\\n                                            </t>\\n                                        </table>\\n                                    </div>\\n                                </div>\\n                                <div class=\\"mb-2\\">\\n                                    <p class=\\"text-end lh-sm\\" t-if=\\"o.company_id.display_invoice_amount_total_words\\">\\n                                        Total amount in words: <br/>\\n                                        <small class=\\"text-muted lh-sm\\"><span t-field=\\"o.amount_total_words\\">Thirty one dollar and Five cents</span></small>\\n                                    </p>\\n                                </div>\\n\\n                                <!-- Tax totals summary (company currency) -->\\n                                <t t-if=\\"o.tax_totals and o.tax_totals.get('display_in_company_currency')\\">\\n                                    <t t-call=\\"account.document_tax_totals_company_currency_template\\" tax_totals=\\"o.tax_totals\\"/>\\n                                </t>\\n                                <t t-else=\\"\\">\\n                                    <div class=\\"oe_structure\\"/>\\n                                </t>\\n                            </div>\\n                            <div id=\\"payment_term\\" class=\\"clearfix mt-3\\">\\n                                <div class=\\"justify-text\\">\\n                                    <p t-if=\\"not is_html_empty(o.fiscal_position_id.note)\\" name=\\"note\\" class=\\"mb-2\\">\\n                                        <span t-field=\\"o.fiscal_position_id.note\\"/>\\n                                    </p>\\n                                </div>\\n                                <div class=\\"justify-text\\">\\n                                    <p t-if=\\"not is_html_empty(o.taxes_legal_notes)\\" name=\\"taxes_legal_notes\\" class=\\"mb-2\\">\\n                                        <span t-field=\\"o.taxes_legal_notes\\"/>\\n                                    </p>\\n                                </div>\\n                                <t t-set=\\"payment_term_details\\" t-value=\\"o.payment_term_details\\"/>\\n                                <div class=\\"mb-3\\">\\n                                    <span id=\\"payment_terms_note_id\\" t-if=\\"o.invoice_payment_term_id.note\\" t-field=\\"o.invoice_payment_term_id.note\\" name=\\"payment_term\\">Payment within 30 calendar day</span><br/>\\n                                    <t t-if=\\"o.invoice_payment_term_id.display_on_invoice and payment_term_details\\">\\n                                        <div t-if=\\"o.show_payment_term_details\\" id=\\"total_payment_term_details_table\\" class=\\"row\\">\\n                                            <div t-attf-class=\\"#{'col-10' if report_type != 'html' else 'col-sm-10 col-md-9'}\\">\\n                                                <t t-if=\\"o._is_eligible_for_early_payment_discount(o.currency_id,o.invoice_date)\\">\\n                                                    <div id=\\"early_payment_discount\\">\\n                                                        <span t-options=\\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}\\" t-out=\\"o.invoice_payment_term_id._get_amount_due_after_discount(o.amount_total, o.amount_tax, currency=o.currency_id, cash_rounding=o.invoice_cash_rounding_id)\\">30.00</span> due if paid before\\n                                                        <span t-out=\\"o.invoice_payment_term_id._get_last_discount_date_formatted(o.invoice_date)\\">2024-01-01</span>\\n                                                    </div>\\n                                                </t>\\n                                                <t t-if=\\"len(payment_term_details) &gt; 1\\" t-foreach=\\"payment_term_details\\" t-as=\\"term\\">\\n                                                    <div>\\n                                                        <span t-out=\\"term_index + 1\\">1</span> - Installment of\\n                                                        <t t-options=\\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}\\" t-out=\\"term.get('amount')\\" class=\\"text-end\\">31.05</t>\\n                                                        <span> due on </span>\\n                                                        <t t-out=\\"term.get('date')\\">2024-01-01</t>\\n                                                    </div>\\n                                                </t>\\n                                            </div>\\n                                        </div>\\n                                    </t>\\n                                </div>\\n                                <div class=\\"mb-3\\" t-if=\\"o.move_type in ('out_invoice', 'in_refund') and o.payment_reference\\">\\n                                    <p name=\\"payment_communication\\">\\n                                        Payment Communication: <span class=\\"fw-bold\\" t-field=\\"o.payment_reference\\">INV/2023/00001</span>\\n                                        <t t-if=\\"o.partner_bank_id\\">\\n                                            <br/> on this account: <span t-field=\\"o.partner_bank_id\\" class=\\"fw-bold\\"/>\\n                                        </t>\\n                                    </p>\\n                                </div>\\n                                <t t-set=\\"show_qr\\" t-value=\\"o.display_qr_code and o.amount_residual\\"/>\\n                                <div t-if=\\"not show_qr\\" name=\\"qr_code_placeholder\\" class=\\"oe_structure\\"/>\\n                                <div id=\\"qrcode\\" class=\\"d-flex mb-3 avoid-page-break-inside\\" t-else=\\"\\">\\n                                    <div class=\\"qrcode me-3\\" id=\\"qrcode_image\\">\\n                                        <t t-set=\\"qr_code_url\\" t-value=\\"o._generate_qr_code(silent_errors=True)\\"/>\\n                                        <p t-if=\\"qr_code_url\\" class=\\"position-relative mb-0\\">\\n                                            <img t-att-src=\\"qr_code_url\\"/>\\n                                            <img src=\\"/account/static/src/img/Odoo_logo_O.svg\\" id=\\"qrcode_odoo_logo\\" class=\\"top-50 start-50 position-absolute bg-white border border-3 rounded-circle\\"/>\\n                                        </p>\\n                                    </div>\\n                                    <div class=\\"d-inline text-muted lh-sm fst-italic\\" id=\\"qrcode_info\\" t-if=\\"qr_code_url\\">\\n                                        <p>Scan this QR Code with<br/>your banking application</p>\\n                                    </div>\\n                                </div>\\n                                <t t-set=\\"show_link_qr\\" t-value=\\"o.display_link_qr_code and o.amount_residual\\"/>\\n                                <div t-if=\\"show_link_qr\\" id=\\"payment_link_qrcode\\" class=\\"d-flex mb-3 avoid-page-break-inside\\">\\n                                    <t t-set=\\"portal_qr_code\\" t-value=\\"o._generate_portal_payment_qr()\\"/>\\n                                    <div class=\\"qrcode me-3 position-relative\\" id=\\"qrcode_image\\">\\n                                        <a t-att-href=\\"o._get_portal_payment_link()\\" target=\\"_blank\\" class=\\"top-0 start-0 position-absolute w-100 h-100 z-1\\"/>\\n                                        <p class=\\"position-relative mb-0\\">\\n                                            <img t-att-src=\\"portal_qr_code\\"/>\\n                                            <img src=\\"/account/static/src/img/Odoo_logo_O.svg\\" id=\\"qrcode_odoo_logo\\" class=\\"top-50 start-50 position-absolute bg-white border border-3 rounded-circle\\"/>\\n                                        </p>\\n                                    </div>\\n                                    <div class=\\"d-inline lh-sm\\" id=\\"qrcode_info\\" t-if=\\"portal_qr_code\\">\\n                                        <p class=\\"fw-bold mb-0\\">PAY IN A FLASH!</p>\\n                                        <p class=\\"text-muted fst-italic\\">Scan the QR code<br/>or click to pay online</p>\\n                                    </div>\\n                                </div>\\n                                <!--terms and conditions-->\\n                                <div class=\\"text-muted mb-3\\" t-if=\\"not is_html_empty(o.narration)\\" name=\\"comment\\">\\n                                    <span t-field=\\"o.narration\\"/>\\n                                </div>\\n                                <div class=\\"oe_structure\\"/>\\n                            </div>\\n                        </div>\\n                    </div>\\n                </div>\\n            </t>\\n        </t>", "es_ES": "<t t-name=\\"account.report_invoice_document\\">\\n            <t t-set=\\"layout_document_title\\">\\n                <t t-if=\\"not proforma\\">\\n                    <span t-if=\\"o.move_type == 'out_invoice' and o.state == 'posted'\\">\\n                        <t name=\\"invoice_title\\">Factura</t>\\n                    </span>\\n                    <span t-elif=\\"o.move_type == 'out_invoice' and o.state == 'draft'\\">\\n                        <t name=\\"draft_invoice_title\\">Borrador de factura</t>\\n                    </span>\\n                    <span t-elif=\\"o.move_type == 'out_invoice' and o.state == 'cancel'\\">\\n                        <t name=\\"cancelled_invoice_title\\">Factura cancelada</t>\\n                    </span>\\n                    <span t-elif=\\"o.move_type == 'out_refund' and o.state == 'posted'\\">\\n                        <t name=\\"credit_note_title\\">Factura rectificativa</t>\\n                    </span>\\n                    <span t-elif=\\"o.move_type == 'out_refund' and o.state == 'draft'\\">\\n                        <t name=\\"draft_credit_note_title\\">Borrador de factura rectificativa</t>\\n                    </span>\\n                    <span t-elif=\\"o.move_type == 'out_refund' and o.state == 'cancel'\\">\\n                        <t name=\\"cancelled_credit_note_title\\">Factura rectificativa cancelada</t>\\n                    </span>\\n                    <span t-elif=\\"o.move_type == 'in_refund' and not o.journal_id.is_self_billing\\">\\n                        <t name=\\"vendor_credit_note_title\\">Factura rectificativa de proveedor</t>\\n                    </span>\\n                    <span t-elif=\\"o.move_type == 'in_refund' and o.journal_id.is_self_billing\\">\\n                        <t name=\\"self_billing_credit_note_title\\">Nota de crédito de autofactura</t>\\n                    </span>\\n                    <span t-elif=\\"o.move_type == 'in_invoice' and not o.journal_id.is_self_billing\\">\\n                        <t name=\\"vendor_bill_title\\">Factura de proveedor</t>\\n                    </span>\\n                    <span t-elif=\\"o.move_type == 'in_invoice' and o.journal_id.is_self_billing\\">\\n                        <t name=\\"self_billing_invoice_title\\">Autofacturación</t>\\n                    </span>\\n                </t>\\n                <t t-else=\\"\\">\\n                    <span t-if=\\"o.move_type == 'out_invoice' and o.state == 'posted'\\">\\n                        <t name=\\"proforma_invoice_title\\">Factura proforma</t>\\n                    </span>\\n                    <span t-elif=\\"o.move_type == 'out_invoice' and o.state == 'draft'\\">\\n                        <t name=\\"draft_proforma_invoice_title\\">Borrador de factura proforma</t>\\n                    </span>\\n                    <span t-elif=\\"o.move_type == 'out_invoice' and o.state == 'cancel'\\">\\n                        <t name=\\"cancelled_proforma_invoice_title\\">Factura proforma cancelada</t>\\n                    </span>\\n                    <span t-elif=\\"o.move_type == 'out_refund' and o.state == 'posted'\\">\\n                        <t name=\\"proforma_credit_note_title\\">Factura rectificativa proforma</t>\\n                    </span>\\n                    <span t-elif=\\"o.move_type == 'out_refund' and o.state == 'draft'\\">\\n                        <t name=\\"draft_proforma_credit_note_title\\">Borrador de factura rectificativa proforma</t>\\n                    </span>\\n                    <span t-elif=\\"o.move_type == 'out_refund' and o.state == 'cancel'\\">\\n                        <t name=\\"cancelled_proforma_credit_note_title\\">Factura rectificativa proforma cancelada</t>\\n                    </span>\\n                    <span t-elif=\\"o.move_type == 'in_refund'\\">\\n                        <t name=\\"proforma_vendor_credit_note_title\\">Factura rectificativa proforma de proveedor</t>\\n                    </span>\\n                    <span t-elif=\\"o.move_type == 'in_invoice'\\">\\n                        <t name=\\"proforma_vendor_bill_title\\">Factura proforma de proveedor</t>\\n                    </span>\\n                </t>\\n                <span t-if=\\"o.name and o.name != '/'\\" t-field=\\"o.name\\">INV/2023/0001</span>\\n            </t>\\n            <t t-set=\\"o\\" t-value=\\"o.with_context(lang=lang)\\"/>\\n            <t t-set=\\"information_block\\" t-if=\\"o.partner_shipping_id and (o.partner_shipping_id != o.partner_id)\\" groups=\\"account.group_delivery_invoice_address\\">\\n                <div name=\\"shipping_address_block\\">\\n                    <strong class=\\"d-block mt-3\\">Dirección de envío</strong>\\n                    <div t-field=\\"o.partner_shipping_id\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: True}\\"/>\\n                </div>\\n            </t>\\n            <t t-set=\\"address\\">\\n                <t t-if=\\"o.partner_shipping_id and (o.partner_shipping_id != o.partner_id)\\">\\n                    <t name=\\"address_not_same_as_shipping\\">\\n                        <address class=\\"mb-0\\" t-field=\\"o.partner_id\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: True}\\"/>\\n                        <div id=\\"partner_vat_address_not_same_as_shipping\\">\\n                            <t t-out=\\"o._get_document_partner_ident_line()\\" id=\\"inv_tax_id_label\\"/>\\n                        </div>\\n                    </t>\\n                </t>\\n                <t t-elif=\\"o.partner_shipping_id and (o.partner_shipping_id == o.partner_id)\\">\\n                    <t name=\\"address_same_as_shipping\\">\\n                        <address class=\\"mb-0\\" t-field=\\"o.partner_id\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: True}\\"/>\\n                        <div id=\\"partner_vat_address_same_as_shipping\\">\\n                            <t t-out=\\"o._get_document_partner_ident_line()\\" id=\\"inv_tax_id_label\\"/>\\n                        </div>\\n                    </t>\\n                </t>\\n                <t t-else=\\"\\">\\n                    <t name=\\"no_shipping\\">\\n                        <address class=\\"mb-0\\" t-field=\\"o.partner_id\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: True}\\"/>\\n                        <div id=\\"partner_vat_no_shipping\\">\\n                            <t t-out=\\"o._get_document_partner_ident_line()\\" id=\\"inv_tax_id_label\\"/>\\n                        </div>\\n                    </t>\\n                </t>\\n            </t>\\n            <t t-call=\\"web.external_layout\\" forced_vat=\\"o.fiscal_position_id.foreign_vat\\" layout_document_title=\\"layout_document_title\\" information_block=\\"information_block\\" lang=\\"lang\\" address=\\"address\\">\\n                <div class=\\"clearfix invoice_main\\">\\n                    <div class=\\"page mb-4\\">\\n                        <div class=\\"oe_structure\\"/>\\n                        <div id=\\"informations\\" class=\\"row mb-4\\" t-if=\\"o.invoice_date or (o.invoice_date_due and o.move_type == 'out_invoice' and o.state == 'posted') or o.delivery_date or o.invoice_origin or o.partner_id.ref or o.ref or o.invoice_incoterm_id\\">\\n                            <div class=\\"col\\" t-if=\\"o.invoice_date\\" name=\\"invoice_date\\">\\n                                <t t-if=\\"o.move_type == 'out_invoice'\\"><strong>Fecha de factura</strong></t>\\n                                <t t-elif=\\"o.move_type == 'out_refund'\\"><strong>Fecha de la factura rectificativa</strong></t>\\n                                <t t-elif=\\"o.move_type == 'out_receipt'\\"><strong>Fecha de recepción</strong></t>\\n                                <t t-else=\\"\\"><strong>Fecha</strong></t>\\n                                <div t-field=\\"o.invoice_date\\">2023-09-12</div>\\n                            </div>\\n                            <div class=\\"col\\" t-if=\\"o.invoice_date_due and o.move_type == 'out_invoice' and o.state == 'posted'\\" name=\\"due_date\\">\\n                                <strong>Fecha de vencimiento</strong>\\n                                <div t-field=\\"o.invoice_date_due\\">2023-10-31</div>\\n                            </div>\\n                            <div class=\\"col\\" t-if=\\"o.taxable_supply_date and o.show_taxable_supply_date\\" name=\\"taxable_supply_date\\">\\n                                <strong>Entrega sujeta a impuestos</strong>\\n                                <div t-field=\\"o.taxable_supply_date\\">2023-10-31</div>\\n                            </div>\\n                            <div class=\\"col\\" t-if=\\"o.delivery_date\\" name=\\"delivery_date\\">\\n                                <strong>Fecha de entrega</strong>\\n                                <div t-field=\\"o.delivery_date\\">2023-09-25</div>\\n                            </div>\\n                            <div class=\\"col\\" t-if=\\"o.invoice_origin\\" name=\\"origin\\">\\n                                <strong>Origen</strong>\\n                                <div t-field=\\"o.invoice_origin\\">SO123</div>\\n                            </div>\\n                            <div class=\\"col\\" t-if=\\"o.partner_id.ref\\" name=\\"customer_code\\">\\n                                <strong>Código de cliente</strong>\\n                                <div t-field=\\"o.partner_id.ref\\"/>\\n                            </div>\\n                            <div class=\\"col\\" t-if=\\"o.ref\\" name=\\"reference\\">\\n                                <strong>Referencia</strong>\\n                                <div t-field=\\"o.ref\\">INV/2023/00001</div>\\n                            </div>\\n                            <div class=\\"col\\" t-if=\\"o.invoice_incoterm_id\\" name=\\"incoterm_id\\">\\n                                <strong>Incoterm</strong>\\n                                <div t-if=\\"o.incoterm_location\\">\\n                                    <span t-field=\\"o.invoice_incoterm_id.code\\"/> <br/>\\n                                    <span t-field=\\"o.incoterm_location\\"/>\\n                                </div>\\n                                <div t-else=\\"\\" t-field=\\"o.invoice_incoterm_id.code\\" class=\\"m-0\\"/>\\n                            </div>\\n                        </div>\\n\\n                        <t t-set=\\"lines_to_report\\" t-value=\\"o._get_move_lines_to_report()\\"/>\\n                        <t t-set=\\"display_discount\\" t-value=\\"any(l.discount for l in lines_to_report)\\"/>\\n                        <t t-set=\\"display_taxes\\" t-value=\\"any(l.tax_ids for l in o.invoice_line_ids)\\"/>\\n                        <div class=\\"oe_structure\\"/>\\n                        <t t-set=\\"has_long_desc\\" t-value=\\"any(line.name and line.name.count('\\\\n') &gt; 30 for line in o.invoice_line_ids if line.name)\\"/>\\n                        <div class=\\"table-responsive-sm overflow-visible\\">\\n                            <table class=\\"o_has_total_table table o_main_table table-borderless mb-0\\" name=\\"invoice_line_table\\">\\n                                <thead t-attf-style=\\"#{has_long_desc and 'display: table-row-group;' or ''}\\">\\n                                    <tr>\\n                                        <th name=\\"th_description\\" class=\\"text-start\\"><span>Descripción</span></th>\\n                                        <th name=\\"th_quantity\\" class=\\"text-end\\"><span>Cantidad</span></th>\\n                                        <th name=\\"th_priceunit\\" t-attf-class=\\"text-end text-nowrap {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}\\"><span>Precio unitario</span></th>\\n                                        <th name=\\"th_discount\\" t-if=\\"display_discount\\" t-attf-class=\\"text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}\\">\\n                                            <span>Desc.%</span>\\n                                        </th>\\n                                        <th name=\\"th_taxes\\" t-if=\\"display_taxes\\" t-attf-class=\\"text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}\\"><span>Impuestos</span></th>\\n                                        <th name=\\"th_subtotal\\" class=\\"text-end\\">\\n                                            <span>Importe</span>\\n                                        </th>\\n                                    </tr>\\n                                </thead>\\n                                <tbody class=\\"invoice_tbody\\">\\n                                    <t t-set=\\"current_section\\" t-value=\\"None\\"/>\\n                                    <t t-set=\\"current_subsection\\" t-value=\\"None\\"/>\\n\\n                                    <t t-foreach=\\"lines_to_report\\" t-as=\\"line\\">\\n                                        <t t-set=\\"is_note\\" t-value=\\"line.display_type == 'line_note'\\"/>\\n                                        <t t-set=\\"is_section\\" t-value=\\"line.display_type == 'line_section'\\"/>\\n                                        <t t-set=\\"is_subsection\\" t-value=\\"line.display_type == 'line_subsection'\\"/>\\n                                        <t t-set=\\"is_product\\" t-value=\\"line.display_type == 'product'\\"/>\\n\\n                                        <t t-if=\\"is_section\\">\\n                                            <t t-set=\\"current_section\\" t-value=\\"line\\"/>\\n                                            <t t-set=\\"current_subsection\\" t-value=\\"None\\"/>\\n                                            <t t-set=\\"line_padding\\" t-value=\\"1\\"/>\\n                                        </t>\\n                                        <t t-elif=\\"is_subsection\\">\\n                                            <t t-set=\\"current_subsection\\" t-value=\\"line\\"/>\\n                                            <t t-set=\\"line_padding\\" t-value=\\"3\\"/>\\n                                        </t>\\n                                        <t t-else=\\"\\">\\n                                            <t t-set=\\"line_padding\\" t-value=\\"4 if current_subsection else (3 if current_section else 0)\\"/>\\n                                        </t>\\n                                        <t t-set=\\"padding_style\\" t-value=\\"line_padding and ('padding-left:' + str(line_padding * 8) + 'px') or ''\\"/>\\n                                        <t t-set=\\"hide_details\\" t-value=\\"line.collapse_composition\\"/>\\n                                        <t t-set=\\"hide_prices\\" t-value=\\"line.collapse_prices\\"/>\\n\\n                                        <t t-if=\\"not hide_details and not hide_prices\\">\\n                                            <tr t-att-class=\\"                                                 'fw-bold o_line_section' if is_section else                                                 'fw-bold o_line_subsection' if is_subsection else                                                 'fst-italic o_line_note' if is_note                                                 else ''\\">\\n                                                <t t-set=\\"line_colspan\\" t-value=\\"3 + (1 if display_discount else 0) + (1 if display_taxes and not line.tax_ids else 0)\\"/>\\n                                                <t t-if=\\"is_product\\" name=\\"account_invoice_line_accountable\\">\\n                                                    <td class=\\"w-100\\" name=\\"account_invoice_line_name\\" t-att-style=\\"padding_style\\">\\n                                                        <span t-if=\\"line.label\\" t-field=\\"line.label\\" t-options=\\"{'widget': 'text'}\\" class=\\"d-inline-block w-100 lh-sm\\">Hamburguesa con bacon</span>\\n                                                    </td>\\n                                                    <td name=\\"td_quantity\\" class=\\"o_td_quantity text-end\\">\\n                                                        <span t-field=\\"line.quantity\\" class=\\"text-nowrap\\">3.00</span>\\n                                                        <span t-field=\\"line.product_uom_id\\" groups=\\"uom.group_uom\\">unidades</span>\\n                                                        <span t-if=\\"line.product_uom_id != line.product_id.uom_id\\" groups=\\"uom.group_uom\\" class=\\"text-muted small\\">\\n                                                            <br/>\\n                                                            <t t-set=\\"product_uom_qty\\" t-value=\\"line.product_uom_id._compute_quantity(line.quantity, line.product_id.uom_id)\\"/>\\n                                                            <span t-out=\\"product_uom_qty\\" t-options=\\"{'widget': 'float', 'decimal_precision': 'Product Unit'}\\" data-oe-demo=\\"3.00\\"/> <span t-field=\\"line.product_id.uom_id\\" data-oe-demo=\\"units\\"/>\\n                                                        </span>\\n                                                    </td>\\n                                                    <td name=\\"td_price_unit\\" t-attf-class=\\"text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}\\">\\n                                                        <span t-if=\\"not hide_prices\\" class=\\"text-nowrap\\" t-field=\\"line.price_unit\\">9.00</span>\\n                                                    </td>\\n                                                    <td name=\\"td_discount\\" t-if=\\"display_discount\\" t-attf-class=\\"text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}\\">\\n                                                        <span class=\\"text-nowrap\\" t-field=\\"line.discount\\">0</span>\\n                                                    </td>\\n                                                    <t t-set=\\"taxes\\" t-value=\\"', '.join(tax.tax_label for tax in line.tax_ids if tax.tax_label)\\"/>\\n                                                    <td name=\\"td_taxes\\" t-if=\\"display_taxes\\" t-attf-class=\\"text-end text-nowrap {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }} {{ 'text-nowrap' if len(taxes) &lt; 10 else '' }}\\">\\n                                                        <span t-if=\\"not hide_prices\\" t-out=\\"taxes\\" id=\\"line_tax_ids\\">Impuesto del 15 %</span>\\n                                                    </td>\\n                                                    <td name=\\"td_subtotal\\" class=\\"text-end o_price_total\\">\\n                                                        <span t-if=\\"not hide_prices and o.document_tax_mode == 'tax_excluded'\\" class=\\"text-nowrap\\" t-field=\\"line.price_subtotal\\">27.00</span>\\n                                                        <span t-if=\\"not hide_prices and o.document_tax_mode == 'tax_included'\\" class=\\"text-nowrap\\" t-field=\\"line.price_total\\">31.05</span>\\n                                                    </td>\\n                                                </t>\\n                                                <t t-elif=\\"line.display_type in ('line_section', 'line_subsection')\\" name=\\"account_invoice_line_section\\">\\n                                                    <t t-set=\\"section_subtotal\\" t-value=\\"line.get_section_subtotal() if o.company_price_include == 'tax_excluded' else line.get_section_total()\\"/>\\n                                                    <!-- For desktop -->\\n                                                    <td name=\\"line_name_td\\" t-att-colspan=\\"(1 if is_product else line_colspan)\\" t-attf-class=\\"{{'d-none d-md-table-cell' if report_type == 'html' else ''}} border-end-0\\" t-att-style=\\"padding_style\\">\\n                                                        <span t-if=\\"line.label\\" t-field=\\"line.label\\" t-options=\\"{'widget': 'text'}\\">Un título de sección</span>\\n                                                    </td>\\n                                                    <!-- For mobile -->\\n                                                    <td colspan=\\"2\\" t-attf-class=\\"{{'d-md-none d-table-cell' if report_type == 'html' else 'd-none'}} border-end-0\\" t-att-style=\\"padding_style\\">\\n                                                        <span t-if=\\"line.label\\" t-field=\\"line.label\\" t-options=\\"{'widget': 'text'}\\">Un título de sección</span>\\n                                                    </td>\\n                                                    <td colspan=\\"1\\" class=\\"text-end o_price_total\\">\\n                                                        <span t-out=\\"section_subtotal\\" class=\\"text-nowrap\\" t-options=\\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}\\"/>\\n                                                    </td>\\n                                                </t>\\n                                                <t t-elif=\\"is_note\\">\\n                                                    <td colspan=\\"99\\">\\n                                                        <span t-if=\\"line.label\\" t-field=\\"line.label\\" t-options=\\"{'widget': 'text'}\\">Una nota, cuyo contenido generalmente aplica a la sección o al producto anterior.</span>\\n                                                    </td>\\n                                                </t>\\n                                            </tr>\\n                                        </t>\\n                                        <t t-else=\\"\\">\\n                                            <t t-set=\\"grouped_lines\\" t-value=\\"line._get_child_lines()\\"/>\\n                                            <t t-foreach=\\"grouped_lines\\" t-as=\\"grouped_line\\">\\n                                                <t t-if=\\"grouped_line['display_type'] == 'product' or hide_details\\">\\n                                                    <t t-set=\\"line_colspan\\" t-value=\\"1\\"/>\\n                                                </t>\\n                                                <t t-else=\\"\\">\\n                                                    <t t-set=\\"line_colspan\\" t-value=\\"3 + (1 if display_discount else 0) + (1 if display_taxes and not grouped_line.get('taxes') else 0)\\"/>\\n                                                </t>\\n                                                <t t-if=\\"hide_prices\\">\\n                                                    <t t-if=\\"grouped_line['display_type'] == 'line_section'\\">\\n                                                        <t t-set=\\"current_section\\" t-value=\\"grouped_line\\"/>\\n                                                        <t t-set=\\"current_subsection\\" t-value=\\"None\\"/>\\n                                                    </t>\\n                                                    <t t-if=\\"grouped_line['display_type'] == 'line_subsection'\\">\\n                                                        <t t-set=\\"current_subsection\\" t-value=\\"grouped_line\\"/>\\n                                                    </t>\\n                                                </t>\\n                                                <tr t-att-class=\\"                                                     'fw-bolder o_line_section' if grouped_line.get('display_type') == 'line_section' and not hide_details else                                                     'fw-bold o_line_subsection' if grouped_line.get('display_type') == 'line_subsection' and not hide_details else                                                     ''\\">\\n                                                    <!-- For desktop -->\\n                                                    <td name=\\"account_invoice_line_name_grouped_desktop\\" t-att-colspan=\\"line_colspan\\" t-attf-class=\\"{{'d-none d-md-table-cell' if report_type == 'html' else ''}}\\" t-att-style=\\"padding_style\\">\\n                                                        <span t-out=\\"grouped_line['label']\\" t-options=\\"{'widget': 'text'}\\">Grupo 1</span>\\n                                                    </td>\\n                                                    <!-- For mobile -->\\n                                                    <td name=\\"account_invoice_line_name_grouped\\" t-att-colspan=\\"2 if grouped_line['display_type'] != 'product' else 1\\" t-attf-class=\\"{{'d-md-none d-table-cell' if report_type == 'html' else 'd-none'}}\\" t-att-style=\\"padding_style\\">\\n                                                        <span t-out=\\"grouped_line['label']\\" t-options=\\"{'widget': 'text'}\\">Grupo 1</span>\\n                                                    </td>\\n                                                    <td name=\\"td_quantity_grouped\\" colspan=\\"1\\" t-if=\\"hide_details or (hide_prices and grouped_line['display_type'] not in ('line_section', 'line_subsection'))\\" class=\\"o_td_quantity text-end\\">\\n                                                        <!-- Show the line quantity -->\\n                                                        <div t-if=\\"hide_prices and grouped_line['display_type'] not in ('line_section', 'line_subsection')\\">\\n                                                            <span t-out=\\"grouped_line['quantity']\\" t-options=\\"{'widget': 'float', 'decimal_precision': 'Product Unit'}\\">1.00</span>\\n                                                            <t t-if=\\"grouped_line.get('line_uom')\\">\\n                                                                <span t-out=\\"grouped_line['line_uom'].display_name\\" groups=\\"uom.group_uom\\">Unidad</span>\\n                                                                <span t-if=\\"grouped_line.get('product_uom') != grouped_line['line_uom']\\" groups=\\"uom.group_uom\\" class=\\"text-muted small\\">\\n                                                                    <br/>\\n                                                                    <t t-set=\\"product_uom_qty\\" t-value=\\"grouped_line['line_uom']._compute_quantity(grouped_line['quantity'], grouped_line['product_uom'])\\"/>\\n                                                                    <span t-out=\\"product_uom_qty\\" t-options=\\"{'widget': 'float', 'decimal_precision': 'Product Unit'}\\" data-oe-demo=\\"3.00\\"/> <span t-out=\\"grouped_line['product_uom'].display_name\\" data-oe-demo=\\"units\\"/>\\n                                                                </span>\\n                                                            </t>\\n                                                        </div>\\n                                                    </td>\\n                                                    <td name=\\"td_price_unit_grouped\\" t-if=\\"hide_details or grouped_line['display_type'] not in ('line_section', 'line_subsection')\\" colspan=\\"1\\" t-attf-class=\\"text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}\\">\\n                                                        <span t-if=\\"not hide_prices\\" t-out=\\"grouped_line['price_subtotal']\\" t-options=\\"{'widget': 'float', 'decimal_precision': 'Product Price'}\\" class=\\"text-nowrap\\">9.00</span>\\n                                                    </td>\\n                                                    <td name=\\"td_discount_grouped\\" t-if=\\"display_discount and (hide_details or grouped_line['display_type'] == 'product')\\" colspan=\\"1\\" t-attf-class=\\"text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}\\"/>\\n                                                    <td name=\\"td_taxes_grouped\\" colspan=\\"1\\" t-if=\\"display_taxes and (hide_details or grouped_line['display_type'] == 'product' or grouped_line.get('taxes'))\\" t-attf-class=\\"text-end {{'d-none d-md-table-cell' if report_type == 'html' else ''}}\\">\\n                                                        <span t-if=\\"grouped_line.get('taxes')\\" t-out=\\"','.join(grouped_line['taxes'])\\" id=\\"grouped_line_tax_ids\\">Impuesto del 15 %</span>\\n                                                    </td>\\n                                                    <td name=\\"td_subtotal_grouped\\" colspan=\\"1\\" class=\\"text-end o_price_total\\">\\n                                                        <span t-if=\\"(grouped_line.get('display_type') == 'line_section' or (not hide_prices and grouped_line.get('display_type') == 'line_subsection') or hide_details) and o.document_tax_mode == 'tax_excluded'\\" class=\\"text-nowrap\\" t-out=\\"grouped_line['price_subtotal']\\" t-options=\\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}\\">27.00</span>\\n                                                        <span t-if=\\"(grouped_line.get('display_type') == 'line_section' or (not hide_prices and grouped_line.get('display_type') == 'line_subsection') or hide_details) and o.document_tax_mode == 'tax_included'\\" class=\\"text-nowrap\\" t-out=\\"grouped_line['price_total']\\" t-options=\\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}\\">31.05</span>\\n                                                    </td>\\n                                                </tr>\\n                                            </t>\\n                                        </t>\\n                                    </t>\\n                                </tbody>\\n                            </table>\\n                        </div>\\n                        <div class=\\"overflow-hidden\\">\\n                            <div id=\\"right-elements\\" class=\\"float-end ms-5\\">\\n                                <div id=\\"total\\" class=\\"clearfix\\">\\n                                    <div class=\\"ms-auto\\">\\n                                        <table class=\\"o_total_table table table-borderless avoid-page-break-inside\\">\\n\\n                                            <!-- Tax totals summary (invoice currency) -->\\n                                            <t t-if=\\"o.tax_totals\\" t-call=\\"account.document_tax_totals\\" tax_totals=\\"o.tax_totals\\" currency=\\"o.currency_id\\"/>\\n\\n                                            <!--Payments-->\\n                                            <t t-if=\\"print_with_payments\\">\\n                                                <t t-if=\\"o.payment_state != 'invoicing_legacy'\\">\\n                                                    <t t-set=\\"payments_vals\\" t-value=\\"o.sudo().invoice_payments_widget and o.sudo().invoice_payments_widget['content'] or []\\"/>\\n                                                    <t t-foreach=\\"payments_vals\\" t-as=\\"payment_vals\\">\\n                                                        <tr t-if=\\"payment_vals['is_exchange'] == 0\\">\\n                                                            <td>\\n                                                                <i class=\\"oe_form_field text-end oe_payment_label\\">\\n                                                                    <t t-if=\\"payment_vals['is_refund']\\">Revertido el </t>\\n                                                                    <t t-else=\\"\\">Pagado el </t>\\n                                                                    <t t-out=\\"payment_vals['date']\\" t-options=\\"{&quot;widget&quot;: &quot;date&quot;}\\">2021-09-19</t>\\n                                                                </i>\\n                                                            </td>\\n                                                            <td class=\\"text-end\\">\\n                                                                <span t-out=\\"payment_vals['amount']\\" t-options=\\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}\\">20.00</span>\\n                                                            </td>\\n                                                        </tr>\\n                                                    </t>\\n                                                    <t t-if=\\"len(payments_vals) &gt; 0\\">\\n                                                        <tr class=\\"fw-bold\\">\\n                                                            <td>Importe adeudado</td>\\n                                                            <td class=\\"text-end\\">\\n                                                                <span t-field=\\"o.amount_residual\\">11.05</span>\\n                                                            </td>\\n                                                        </tr>\\n                                                    </t>\\n                                                </t>\\n                                            </t>\\n                                        </table>\\n                                    </div>\\n                                </div>\\n                                <div class=\\"mb-2\\">\\n                                    <p class=\\"text-end lh-sm\\" t-if=\\"o.company_id.display_invoice_amount_total_words\\">\\n                                        Importe total con letra: <br/>\\n                                        <small class=\\"text-muted lh-sm\\"><span t-field=\\"o.amount_total_words\\">Treinta y un dólares con cinco céntimos</span></small>\\n                                    </p>\\n                                </div>\\n\\n                                <!-- Tax totals summary (company currency) -->\\n                                <t t-if=\\"o.tax_totals and o.tax_totals.get('display_in_company_currency')\\">\\n                                    <t t-call=\\"account.document_tax_totals_company_currency_template\\" tax_totals=\\"o.tax_totals\\"/>\\n                                </t>\\n                                <t t-else=\\"\\">\\n                                    <div class=\\"oe_structure\\"/>\\n                                </t>\\n                            </div>\\n                            <div id=\\"payment_term\\" class=\\"clearfix mt-3\\">\\n                                <div class=\\"justify-text\\">\\n                                    <p t-if=\\"not is_html_empty(o.fiscal_position_id.note)\\" name=\\"note\\" class=\\"mb-2\\">\\n                                        <span t-field=\\"o.fiscal_position_id.note\\"/>\\n                                    </p>\\n                                </div>\\n                                <div class=\\"justify-text\\">\\n                                    <p t-if=\\"not is_html_empty(o.taxes_legal_notes)\\" name=\\"taxes_legal_notes\\" class=\\"mb-2\\">\\n                                        <span t-field=\\"o.taxes_legal_notes\\"/>\\n                                    </p>\\n                                </div>\\n                                <t t-set=\\"payment_term_details\\" t-value=\\"o.payment_term_details\\"/>\\n                                <div class=\\"mb-3\\">\\n                                    <span id=\\"payment_terms_note_id\\" t-if=\\"o.invoice_payment_term_id.note\\" t-field=\\"o.invoice_payment_term_id.note\\" name=\\"payment_term\\">Pago en un plazo de 30 días naturales</span><br/>\\n                                    <t t-if=\\"o.invoice_payment_term_id.display_on_invoice and payment_term_details\\">\\n                                        <div t-if=\\"o.show_payment_term_details\\" id=\\"total_payment_term_details_table\\" class=\\"row\\">\\n                                            <div t-attf-class=\\"#{'col-10' if report_type != 'html' else 'col-sm-10 col-md-9'}\\">\\n                                                <t t-if=\\"o._is_eligible_for_early_payment_discount(o.currency_id,o.invoice_date)\\">\\n                                                    <div id=\\"early_payment_discount\\">\\n                                                        <span t-options=\\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}\\" t-out=\\"o.invoice_payment_term_id._get_amount_due_after_discount(o.amount_total, o.amount_tax, currency=o.currency_id, cash_rounding=o.invoice_cash_rounding_id)\\">30.00</span> adeudado si se paga antes del\\n                                                        <span t-out=\\"o.invoice_payment_term_id._get_last_discount_date_formatted(o.invoice_date)\\">2024-01-01</span>\\n                                                    </div>\\n                                                </t>\\n                                                <t t-if=\\"len(payment_term_details) &gt; 1\\" t-foreach=\\"payment_term_details\\" t-as=\\"term\\">\\n                                                    <div>\\n                                                        <span t-out=\\"term_index + 1\\">1</span> - Cuota de\\n                                                        <t t-options=\\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}\\" t-out=\\"term.get('amount')\\" class=\\"text-end\\">31.05</t>\\n                                                        <span> vence el</span>\\n                                                        <t t-out=\\"term.get('date')\\">2024-01-01</t>\\n                                                    </div>\\n                                                </t>\\n                                            </div>\\n                                        </div>\\n                                    </t>\\n                                </div>\\n                                <div class=\\"mb-3\\" t-if=\\"o.move_type in ('out_invoice', 'in_refund') and o.payment_reference\\">\\n                                    <p name=\\"payment_communication\\">\\n                                        Comunicación de pago: <span class=\\"fw-bold\\" t-field=\\"o.payment_reference\\">INV/2023/00001</span>\\n                                        <t t-if=\\"o.partner_bank_id\\">\\n                                            <br/> en esta cuenta: <span t-field=\\"o.partner_bank_id\\" class=\\"fw-bold\\"/>\\n                                        </t>\\n                                    </p>\\n                                </div>\\n                                <t t-set=\\"show_qr\\" t-value=\\"o.display_qr_code and o.amount_residual\\"/>\\n                                <div t-if=\\"not show_qr\\" name=\\"qr_code_placeholder\\" class=\\"oe_structure\\"/>\\n                                <div id=\\"qrcode\\" class=\\"d-flex mb-3 avoid-page-break-inside\\" t-else=\\"\\">\\n                                    <div class=\\"qrcode me-3\\" id=\\"qrcode_image\\">\\n                                        <t t-set=\\"qr_code_url\\" t-value=\\"o._generate_qr_code(silent_errors=True)\\"/>\\n                                        <p t-if=\\"qr_code_url\\" class=\\"position-relative mb-0\\">\\n                                            <img t-att-src=\\"qr_code_url\\"/>\\n                                            <img src=\\"/account/static/src/img/Odoo_logo_O.svg\\" id=\\"qrcode_odoo_logo\\" class=\\"top-50 start-50 position-absolute bg-white border border-3 rounded-circle\\"/>\\n                                        </p>\\n                                    </div>\\n                                    <div class=\\"d-inline text-muted lh-sm fst-italic\\" id=\\"qrcode_info\\" t-if=\\"qr_code_url\\">\\n                                        <p>Escanee este código de barras con <br/>su aplicación bancaria</p>\\n                                    </div>\\n                                </div>\\n                                <t t-set=\\"show_link_qr\\" t-value=\\"o.display_link_qr_code and o.amount_residual\\"/>\\n                                <div t-if=\\"show_link_qr\\" id=\\"payment_link_qrcode\\" class=\\"d-flex mb-3 avoid-page-break-inside\\">\\n                                    <t t-set=\\"portal_qr_code\\" t-value=\\"o._generate_portal_payment_qr()\\"/>\\n                                    <div class=\\"qrcode me-3 position-relative\\" id=\\"qrcode_image\\">\\n                                        <a t-att-href=\\"o._get_portal_payment_link()\\" target=\\"_blank\\" class=\\"top-0 start-0 position-absolute w-100 h-100 z-1\\"/>\\n                                        <p class=\\"position-relative mb-0\\">\\n                                            <img t-att-src=\\"portal_qr_code\\"/>\\n                                            <img src=\\"/account/static/src/img/Odoo_logo_O.svg\\" id=\\"qrcode_odoo_logo\\" class=\\"top-50 start-50 position-absolute bg-white border border-3 rounded-circle\\"/>\\n                                        </p>\\n                                    </div>\\n                                    <div class=\\"d-inline lh-sm\\" id=\\"qrcode_info\\" t-if=\\"portal_qr_code\\">\\n                                        <p class=\\"fw-bold mb-0\\">PAGAR RÁPIDAMENTE</p>\\n                                        <p class=\\"text-muted fst-italic\\">Escanee el código QR<br/>o haga clic para pagar en línea</p>\\n                                    </div>\\n                                </div>\\n                                <!--terms and conditions-->\\n                                <div class=\\"text-muted mb-3\\" t-if=\\"not is_html_empty(o.narration)\\" name=\\"comment\\">\\n                                    <span t-field=\\"o.narration\\"/>\\n                                </div>\\n                                <div class=\\"oe_structure\\"/>\\n                            </div>\\n                        </div>\\n                    </div>\\n                </div>\\n            </t>\\n        </t>"}	<?xml version="1.0"?>\n<t t-name="account.report_invoice_document">\n            <t t-set="layout_document_title">\n                <t t-if="not proforma">\n                    <span t-if="o.move_type == 'out_invoice' and o.state == 'posted'">\n                        <t name="invoice_title">Invoice</t>\n                    </span>\n                    <span t-elif="o.move_type == 'out_invoice' and o.state == 'draft'">\n                        <t name="draft_invoice_title">Draft Invoice</t>\n                    </span>\n                    <span t-elif="o.move_type == 'out_invoice' and o.state == 'cancel'">\n                        <t name="cancelled_invoice_title">Cancelled Invoice</t>\n                    </span>\n                    <span t-elif="o.move_type == 'out_refund' and o.state == 'posted'">\n                        <t name="credit_note_title">Credit Note</t>\n                    </span>\n                    <span t-elif="o.move_type == 'out_refund' and o.state == 'draft'">\n                        <t name="draft_credit_note_title">Draft Credit Note</t>\n                    </span>\n                    <span t-elif="o.move_type == 'out_refund' and o.state == 'cancel'">\n                        <t name="cancelled_credit_note_title">Cancelled Credit Note</t>\n                    </span>\n                    <span t-elif="o.move_type == 'in_refund' and not o.journal_id.is_self_billing">\n                        <t name="vendor_credit_note_title">Vendor Credit Note</t>\n                    </span>\n                    <span t-elif="o.move_type == 'in_refund' and o.journal_id.is_self_billing">\n                        <t name="self_billing_credit_note_title">Self Billing Credit Note</t>\n                    </span>\n                    <span t-elif="o.move_type == 'in_invoice' and not o.journal_id.is_self_billing">\n                        <t name="vendor_bill_title">Vendor Bill</t>\n                    </span>\n                    <span t-elif="o.move_type == 'in_invoice' and o.journal_id.is_self_billing">\n                        <t name="self_billing_invoice_title">Self Billing</t>\n                    </span>\n                </t>\n                <t t-else="">\n                    <span t-if="o.move_type == 'out_invoice' and o.state == 'posted'">\n                        <t name="proforma_invoice_title">Proforma Invoice</t>\n                    </span>\n                    <span t-elif="o.move_type == 'out_invoice' and o.state == 'draft'">\n                        <t name="draft_proforma_invoice_title">Draft Proforma Invoice</t>\n                    </span>\n                    <span t-elif="o.move_type == 'out_invoice' and o.state == 'cancel'">\n                        <t name="cancelled_proforma_invoice_title">Cancelled Proforma Invoice</t>\n                    </span>\n                    <span t-elif="o.move_type == 'out_refund' and o.state == 'posted'">\n                        <t name="proforma_credit_note_title">Proforma Credit Note</t>\n                    </span>\n                    <span t-elif="o.move_type == 'out_refund' and o.state == 'draft'">\n                        <t name="draft_proforma_credit_note_title">Draft Proforma Credit Note</t>\n                    </span>\n                    <span t-elif="o.move_type == 'out_refund' and o.state == 'cancel'">\n                        <t name="cancelled_proforma_credit_note_title">Cancelled Proforma Credit Note</t>\n                    </span>\n                    <span t-elif="o.move_type == 'in_refund'">\n                        <t name="proforma_vendor_credit_note_title">Proforma Vendor Credit Note</t>\n                    </span>\n                    <span t-elif="o.move_type == 'in_invoice'">\n                        <t name="proforma_vendor_bill_title">Proforma Vendor Bill</t>\n                    </span>\n                </t>\n                <span t-if="o.name and o.name != '/'" t-field="o.name">INV/2023/0001</span>\n            </t>\n            <t t-set="o" t-value="o.with_context(lang=lang)"/>\n            <t t-set="information_block" t-if="o.partner_shipping_id and (o.partner_shipping_id != o.partner_id)" groups="account.group_delivery_invoice_address">\n                <div name="shipping_address_block">\n                    <strong class="d-block mt-3">Shipping Address</strong>\n                    <div t-field="o.partner_shipping_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: True}"/>\n                </div>\n            </t>\n            <t t-set="address">\n                <t t-if="o.partner_shipping_id and (o.partner_shipping_id != o.partner_id)">\n                    <t name="address_not_same_as_shipping">\n                        <address class="mb-0" t-field="o.partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: True}"/>\n                        <div id="partner_vat_address_not_same_as_shipping">\n                            <t t-out="o._get_document_partner_ident_line()" id="inv_tax_id_label"/>\n                        </div>\n                    </t>\n                </t>\n                <t t-elif="o.partner_shipping_id and (o.partner_shipping_id == o.partner_id)">\n                    <t name="address_same_as_shipping">\n                        <address class="mb-0" t-field="o.partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: True}"/>\n                        <div id="partner_vat_address_same_as_shipping">\n                            <t t-out="o._get_document_partner_ident_line()" id="inv_tax_id_label"/>\n                        </div>\n                    </t>\n                </t>\n                <t t-else="">\n                    <t name="no_shipping">\n                        <address class="mb-0" t-field="o.partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: True}"/>\n                        <div id="partner_vat_no_shipping">\n                            <t t-out="o._get_document_partner_ident_line()" id="inv_tax_id_label"/>\n                        </div>\n                    </t>\n                </t>\n            </t>\n            <t t-call="web.external_layout" forced_vat="o.fiscal_position_id.foreign_vat" layout_document_title="layout_document_title" information_block="information_block" lang="lang" address="address">\n                <div class="clearfix invoice_main">\n                    <div class="page mb-4">\n                        <div class="oe_structure"/>\n                        <div id="informations" class="row mb-4" t-if="o.invoice_date or (o.invoice_date_due and o.move_type == 'out_invoice' and o.state == 'posted') or o.delivery_date or o.invoice_origin or o.partner_id.ref or o.ref or o.invoice_incoterm_id">\n                            <div class="col" t-if="o.invoice_date" name="invoice_date">\n                                <t t-if="o.move_type == 'out_invoice'"><strong>Invoice Date</strong></t>\n                                <t t-elif="o.move_type == 'out_refund'"><strong>Credit Note Date</strong></t>\n                                <t t-elif="o.move_type == 'out_receipt'"><strong>Receipt Date</strong></t>\n                                <t t-else=""><strong>Date</strong></t>\n                                <div t-field="o.invoice_date">2023-09-12</div>\n                            </div>\n                            <div class="col" t-if="o.invoice_date_due and o.move_type == 'out_invoice' and o.state == 'posted'" name="due_date">\n                                <strong>Due Date</strong>\n                                <div t-field="o.invoice_date_due">2023-10-31</div>\n                            </div>\n                            <div class="col" t-if="o.taxable_supply_date and o.show_taxable_supply_date" name="taxable_supply_date">\n                                <strong>Taxable Supply</strong>\n                                <div t-field="o.taxable_supply_date">2023-10-31</div>\n                            </div>\n                            <div class="col" t-if="o.delivery_date" name="delivery_date">\n                                <strong>Delivery Date</strong>\n                                <div t-field="o.delivery_date">2023-09-25</div>\n                            </div>\n                            <div class="col" t-if="o.invoice_origin" name="origin">\n                                <strong>Source</strong>\n                                <div t-field="o.invoice_origin">SO123</div>\n                            </div>\n                            <div class="col" t-if="o.partner_id.ref" name="customer_code">\n                                <strong>Customer Code</strong>\n                                <div t-field="o.partner_id.ref"/>\n                            </div>\n                            <div class="col" t-if="o.ref" name="reference">\n                                <strong>Reference</strong>\n                                <div t-field="o.ref">INV/2023/00001</div>\n                            </div>\n                            <div class="col" t-if="o.invoice_incoterm_id" name="incoterm_id">\n                                <strong>Incoterm</strong>\n                                <div t-if="o.incoterm_location">\n                                    <span t-field="o.invoice_incoterm_id.code"/> <br/>\n                                    <span t-field="o.incoterm_location"/>\n                                </div>\n                                <div t-else="" t-field="o.invoice_incoterm_id.code" class="m-0"/>\n                            </div>\n                        </div>\n\n                        <t t-set="lines_to_report" t-value="o._get_move_lines_to_report()"/>\n                        <t t-set="display_discount" t-value="any(l.discount for l in lines_to_report)"/>\n                        <t t-set="display_taxes" t-value="any(l.tax_ids for l in o.invoice_line_ids)"/>\n                        <div class="oe_structure"/>\n                        <t t-set="has_long_desc" t-value="any(line.name and line.name.count('\\n') &gt; 30 for line in o.invoice_line_ids if line.name)"/>\n                        <div class="table-responsive-sm overflow-visible">\n                            <table class="o_has_total_table table o_main_table table-borderless mb-0" name="invoice_line_table">\n                                <thead t-attf-style="#{has_long_desc and 'display: table-row-group;' or ''}">\n                                    <tr>\n                                        <th name="th_description" class="text-start"><span>Description</span></th>\n                                        <th name="th_quantity" class="text-end"><span>Quantity</span></th>\n                                        <th name="th_priceunit" t-attf-class="text-end text-nowrap {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}"><span>Unit Price</span></th>\n                                        <th name="th_discount" t-if="display_discount" t-attf-class="text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}">\n                                            <span>Disc.%</span>\n                                        </th>\n                                        <th name="th_taxes" t-if="display_taxes" t-attf-class="text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}"><span>Taxes</span></th>\n                                        <th name="th_subtotal" class="text-end">\n                                            <span>Amount</span>\n                                        </th>\n                                    </tr>\n                                </thead>\n                                <tbody class="invoice_tbody">\n                                    <t t-set="current_section" t-value="None"/>\n                                    <t t-set="current_subsection" t-value="None"/>\n\n                                    <t t-foreach="lines_to_report" t-as="line">\n                                        <t t-set="is_note" t-value="line.display_type == 'line_note'"/>\n                                        <t t-set="is_section" t-value="line.display_type == 'line_section'"/>\n                                        <t t-set="is_subsection" t-value="line.display_type == 'line_subsection'"/>\n                                        <t t-set="is_product" t-value="line.display_type == 'product'"/>\n\n                                        <t t-if="is_section">\n                                            <t t-set="current_section" t-value="line"/>\n                                            <t t-set="current_subsection" t-value="None"/>\n                                            <t t-set="line_padding" t-value="1"/>\n                                        </t>\n                                        <t t-elif="is_subsection">\n                                            <t t-set="current_subsection" t-value="line"/>\n                                            <t t-set="line_padding" t-value="3"/>\n                                        </t>\n                                        <t t-else="">\n                                            <t t-set="line_padding" t-value="4 if current_subsection else (3 if current_section else 0)"/>\n                                        </t>\n                                        <t t-set="padding_style" t-value="line_padding and ('padding-left:' + str(line_padding * 8) + 'px') or ''"/>\n                                        <t t-set="hide_details" t-value="line.collapse_composition"/>\n                                        <t t-set="hide_prices" t-value="line.collapse_prices"/>\n\n                                        <t t-if="not hide_details and not hide_prices">\n                                            <tr t-att-class="                                                 'fw-bold o_line_section' if is_section else                                                 'fw-bold o_line_subsection' if is_subsection else                                                 'fst-italic o_line_note' if is_note                                                 else ''">\n                                                <t t-set="line_colspan" t-value="3 + (1 if display_discount else 0) + (1 if display_taxes and not line.tax_ids else 0)"/>\n                                                <t t-if="is_product" name="account_invoice_line_accountable">\n                                                    <td class="w-100" name="account_invoice_line_name" t-att-style="padding_style">\n                                                        <span t-if="line.label" t-field="line.label" t-options="{'widget': 'text'}" class="d-inline-block w-100 lh-sm">Bacon Burger</span>\n                                                    </td>\n                                                    <td name="td_quantity" class="o_td_quantity text-end">\n                                                        <span t-field="line.quantity" class="text-nowrap">3.00</span>\n                                                        <span t-field="line.product_uom_id" groups="uom.group_uom">units</span>\n                                                        <span t-if="line.product_uom_id != line.product_id.uom_id" groups="uom.group_uom" class="text-muted small">\n                                                            <br/>\n                                                            <t t-set="product_uom_qty" t-value="line.product_uom_id._compute_quantity(line.quantity, line.product_id.uom_id)"/>\n                                                            <span t-out="product_uom_qty" t-options="{'widget': 'float', 'decimal_precision': 'Product Unit'}" data-oe-demo="3.00"/> <span t-field="line.product_id.uom_id" data-oe-demo="units"/>\n                                                        </span>\n                                                    </td>\n                                                    <td name="td_price_unit" t-attf-class="text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}">\n                                                        <span t-if="not hide_prices" class="text-nowrap" t-field="line.price_unit">9.00</span>\n                                                    </td>\n                                                    <td name="td_discount" t-if="display_discount" t-attf-class="text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}">\n                                                        <span class="text-nowrap" t-field="line.discount">0</span>\n                                                    </td>\n                                                    <t t-set="taxes" t-value="', '.join(tax.tax_label for tax in line.tax_ids if tax.tax_label)"/>\n                                                    <td name="td_taxes" t-if="display_taxes" t-attf-class="text-end text-nowrap {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }} {{ 'text-nowrap' if len(taxes) &lt; 10 else '' }}">\n                                                        <span t-if="not hide_prices" t-out="taxes" id="line_tax_ids">Tax 15%</span>\n                                                    </td>\n                                                    <td name="td_subtotal" class="text-end o_price_total">\n                                                        <span t-if="not hide_prices and o.document_tax_mode == 'tax_excluded'" class="text-nowrap" t-field="line.price_subtotal">27.00</span>\n                                                        <span t-if="not hide_prices and o.document_tax_mode == 'tax_included'" class="text-nowrap" t-field="line.price_total">31.05</span>\n                                                    </td>\n                                                </t>\n                                                <t t-elif="line.display_type in ('line_section', 'line_subsection')" name="account_invoice_line_section">\n                                                    <t t-set="section_subtotal" t-value="line.get_section_subtotal() if o.company_price_include == 'tax_excluded' else line.get_section_total()"/>\n                                                    <!-- For desktop -->\n                                                    <td name="line_name_td" t-att-colspan="(1 if is_product else line_colspan)" t-attf-class="{{'d-none d-md-table-cell' if report_type == 'html' else ''}} border-end-0" t-att-style="padding_style">\n                                                        <span t-if="line.label" t-field="line.label" t-options="{'widget': 'text'}">A section title</span>\n                                                    </td>\n                                                    <!-- For mobile -->\n                                                    <td colspan="2" t-attf-class="{{'d-md-none d-table-cell' if report_type == 'html' else 'd-none'}} border-end-0" t-att-style="padding_style">\n                                                        <span t-if="line.label" t-field="line.label" t-options="{'widget': 'text'}">A section title</span>\n                                                    </td>\n                                                    <td colspan="1" class="text-end o_price_total">\n                                                        <span t-out="section_subtotal" class="text-nowrap" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}"/>\n                                                    </td>\n                                                </t>\n                                                <t t-elif="is_note">\n                                                    <td colspan="99">\n                                                        <span t-if="line.label" t-field="line.label" t-options="{'widget': 'text'}">A note, whose content usually applies to the section or product above.</span>\n                                                    </td>\n                                                </t>\n                                            </tr>\n                                        </t>\n                                        <t t-else="">\n                                            <t t-set="grouped_lines" t-value="line._get_child_lines()"/>\n                                            <t t-foreach="grouped_lines" t-as="grouped_line">\n                                                <t t-if="grouped_line['display_type'] == 'product' or hide_details">\n                                                    <t t-set="line_colspan" t-value="1"/>\n                                                </t>\n                                                <t t-else="">\n                                                    <t t-set="line_colspan" t-value="3 + (1 if display_discount else 0) + (1 if display_taxes and not grouped_line.get('taxes') else 0)"/>\n                                                </t>\n                                                <t t-if="hide_prices">\n                                                    <t t-if="grouped_line['display_type'] == 'line_section'">\n                                                        <t t-set="current_section" t-value="grouped_line"/>\n                                                        <t t-set="current_subsection" t-value="None"/>\n                                                    </t>\n                                                    <t t-if="grouped_line['display_type'] == 'line_subsection'">\n                                                        <t t-set="current_subsection" t-value="grouped_line"/>\n                                                    </t>\n                                                </t>\n                                                <tr t-att-class="                                                     'fw-bolder o_line_section' if grouped_line.get('display_type') == 'line_section' and not hide_details else                                                     'fw-bold o_line_subsection' if grouped_line.get('display_type') == 'line_subsection' and not hide_details else                                                     ''">\n                                                    <!-- For desktop -->\n                                                    <td name="account_invoice_line_name_grouped_desktop" t-att-colspan="line_colspan" t-attf-class="{{'d-none d-md-table-cell' if report_type == 'html' else ''}}" t-att-style="padding_style">\n                                                        <span t-out="grouped_line['label']" t-options="{'widget': 'text'}">Group 1</span>\n                                                    </td>\n                                                    <!-- For mobile -->\n                                                    <td name="account_invoice_line_name_grouped" t-att-colspan="2 if grouped_line['display_type'] != 'product' else 1" t-attf-class="{{'d-md-none d-table-cell' if report_type == 'html' else 'd-none'}}" t-att-style="padding_style">\n                                                        <span t-out="grouped_line['label']" t-options="{'widget': 'text'}">Group 1</span>\n                                                    </td>\n                                                    <td name="td_quantity_grouped" colspan="1" t-if="hide_details or (hide_prices and grouped_line['display_type'] not in ('line_section', 'line_subsection'))" class="o_td_quantity text-end">\n                                                        <!-- Show the line quantity -->\n                                                        <div t-if="hide_prices and grouped_line['display_type'] not in ('line_section', 'line_subsection')">\n                                                            <span t-out="grouped_line['quantity']" t-options="{'widget': 'float', 'decimal_precision': 'Product Unit'}">1.00</span>\n                                                            <t t-if="grouped_line.get('line_uom')">\n                                                                <span t-out="grouped_line['line_uom'].display_name" groups="uom.group_uom">Unit</span>\n                                                                <span t-if="grouped_line.get('product_uom') != grouped_line['line_uom']" groups="uom.group_uom" class="text-muted small">\n                                                                    <br/>\n                                                                    <t t-set="product_uom_qty" t-value="grouped_line['line_uom']._compute_quantity(grouped_line['quantity'], grouped_line['product_uom'])"/>\n                                                                    <span t-out="product_uom_qty" t-options="{'widget': 'float', 'decimal_precision': 'Product Unit'}" data-oe-demo="3.00"/> <span t-out="grouped_line['product_uom'].display_name" data-oe-demo="units"/>\n                                                                </span>\n                                                            </t>\n                                                        </div>\n                                                    </td>\n                                                    <td name="td_price_unit_grouped" t-if="hide_details or grouped_line['display_type'] not in ('line_section', 'line_subsection')" colspan="1" t-attf-class="text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}">\n                                                        <span t-if="not hide_prices" t-out="grouped_line['price_subtotal']" t-options="{'widget': 'float', 'decimal_precision': 'Product Price'}" class="text-nowrap">9.00</span>\n                                                    </td>\n                                                    <td name="td_discount_grouped" t-if="display_discount and (hide_details or grouped_line['display_type'] == 'product')" colspan="1" t-attf-class="text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}"/>\n                                                    <td name="td_taxes_grouped" colspan="1" t-if="display_taxes and (hide_details or grouped_line['display_type'] == 'product' or grouped_line.get('taxes'))" t-attf-class="text-end {{'d-none d-md-table-cell' if report_type == 'html' else ''}}">\n                                                        <span t-if="grouped_line.get('taxes')" t-out="','.join(grouped_line['taxes'])" id="grouped_line_tax_ids">Tax 15%</span>\n                                                    </td>\n                                                    <td name="td_subtotal_grouped" colspan="1" class="text-end o_price_total">\n                                                        <span t-if="(grouped_line.get('display_type') == 'line_section' or (not hide_prices and grouped_line.get('display_type') == 'line_subsection') or hide_details) and o.document_tax_mode == 'tax_excluded'" class="text-nowrap" t-out="grouped_line['price_subtotal']" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}">27.00</span>\n                                                        <span t-if="(grouped_line.get('display_type') == 'line_section' or (not hide_prices and grouped_line.get('display_type') == 'line_subsection') or hide_details) and o.document_tax_mode == 'tax_included'" class="text-nowrap" t-out="grouped_line['price_total']" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}">31.05</span>\n                                                    </td>\n                                                </tr>\n                                            </t>\n                                        </t>\n                                    </t>\n                                </tbody>\n                            </table>\n                        </div>\n                        <div class="overflow-hidden">\n                            <div id="right-elements" class="float-end ms-5">\n                                <div id="total" class="clearfix">\n                                    <div class="ms-auto">\n                                        <table class="o_total_table table table-borderless avoid-page-break-inside">\n\n                                            <!-- Tax totals summary (invoice currency) -->\n                                            <t t-if="o.tax_totals" t-call="account.document_tax_totals" tax_totals="o.tax_totals" currency="o.currency_id"/>\n\n                                            <!--Payments-->\n            