1084	16	676	1	1	Sales Order	\N	sale.sale_order_portal_template	qweb	sale/views/sale_portal_templates.xml	primary	\N	{"en_US": "<data name=\\"Sales Order\\">\\n\\n        <xpath expr=\\"//div[hasclass('o_portal_sidebar')]\\" position=\\"inside\\">\\n            <div class=\\"row o_portal_sale_sidebar\\" t-att-data-order-amount-total=\\"sale_order.amount_total\\" t-att-data-is-partially-paid=\\"'true' if sale_order._is_partially_paid() else 'false'\\">\\n                <t t-set=\\"sidebar_invoices\\" t-value=\\"sale_order.invoice_ids.filtered(lambda i: i.state not in ['draft', 'cancel']).sorted('date', reverse=True)\\"/>\\n\\n                <!-- Sidebar -->\\n                <t t-set=\\"title\\">\\n                    <!-- <t t-if=\\"sale_order._has_to_be_paid() and sale_order.prepayment_percent != 1.0\\">\\n                        <h4>Down payment</h4>\\n                        <h2>\\n                            <t\\n                                t-out=\\"sale_order._get_prepayment_required_amount()\\"\\n                                t-options=\\"{\\n                                    'widget': 'monetary',\\n                                    'display_currency': sale_order.currency_id,\\n                                }\\"\\n                            />\\n                            (<t\\n                                t-out=\\"sale_order.prepayment_percent * 100\\"\\n                                t-options=\\"{'widget': 'float', 'precision': 2, 'min_precision': 0}\\"\\n                            />%)\\n                        </h2>\\n                    </t> -->\\n                    <h2 t-field=\\"sale_order.amount_total\\" class=\\"mb-0 text-break\\"/>\\n                </t>\\n                <t t-set=\\"subtitle\\">Tax Included</t>\\n                <t t-set=\\"entries\\">\\n                    <div t-if=\\"sale_order.state in ('draft', 'sent') and sale_order.prepayment_percent != 1.0\\" class=\\"alert alert-warning mt-3\\" role=\\"alert\\">\\n                        Down payment:\\n                        <span t-out=\\"sale_order._get_prepayment_required_amount()\\" t-options=\\"{                                 'widget': 'monetary',                                 'display_currency': sale_order.currency_id,                             }\\"/>\\n                    </div>\\n                    <div t-if=\\"0 &lt; sale_order.amount_paid &lt; sale_order.amount_total                                 and sale_order.state != 'cancel'\\" class=\\"alert alert-success mt-3\\" role=\\"alert\\">\\n                        Paid:\\n                    <span t-field=\\"sale_order.amount_paid\\" t-options=\\"{                                     'widget': 'monetary',                                     'display_currency': sale_order.currency_id,                                 }\\"/>\\n                    </div>\\n\\n                    <div class=\\"d-none d-lg-flex flex-column mt-3\\">\\n                        <div class=\\"d-flex flex-column gap-2\\" id=\\"sale_order_sidebar_button\\">\\n                            <a t-if=\\"sale_order._has_to_be_signed() and not payment_amount\\" role=\\"button\\" class=\\"btn btn-primary\\" data-bs-toggle=\\"modal\\" data-bs-target=\\"#modalaccept\\" href=\\"#\\"> <!-- If paying by link, signing is skipped. -->\\n                                <t t-if=\\"sale_order._has_to_be_paid()\\"> Sign &amp; Pay</t>\\n                                <t t-else=\\"\\"> Accept &amp; Sign</t>\\n                            </a>\\n                            <a t-elif=\\"sale_order._has_to_be_paid()                                             or (                                                 payment_amount                                                 and sale_order.amount_paid &lt; sale_order.amount_total                                                 and sale_order.state != 'cancel'                                             )\\" id=\\"o_sale_portal_paynow\\" role=\\"button\\" data-bs-toggle=\\"modal\\" data-bs-target=\\"#modalaccept\\" href=\\"#\\" t-att-class=\\"'btn btn-primary' if not sale_order.transaction_ids else 'btn btn-light'\\">\\n                                <t t-if=\\"not sale_order.signature                                              and sale_order._has_to_be_paid()                                              and not payment_amount\\"> Accept &amp; Pay</t>\\n                                <t t-else=\\"\\"> Pay Now</t>\\n                            </a>\\n                            <div id=\\"print_invoice_sidebar_button\\" class=\\"o_download_pdf d-flex gap-2 flex-lg-column flex-xl-row flex-wrap\\">\\n                                <a class=\\"btn btn-light o_print_btn o_portal_invoice_print flex-grow-1\\" t-att-href=\\"sale_order.get_portal_url(report_type='pdf')\\" id=\\"print_invoice_report\\" title=\\"View Details\\" role=\\"button\\" target=\\"_blank\\">Download</a>\\n                            </div>\\n                        </div>\\n\\n                        <t t-if=\\"not sale_order.is_expired and sale_order.state in ['draft', 'sent']\\">\\n                            <div t-if=\\"advantage_tax_incl &lt; 0\\" class=\\"d-none d-lg-block\\" name=\\"sale_order_advantage\\">\\n                                <hr/>\\n                                <strong class=\\"smaller text-uppercase text-muted\\">Your advantage</strong>\\n                                <h5 t-out=\\"advantage_tax_incl\\" t-options=\\"{                                         'widget': 'monetary',                                         'display_currency': sale_order.currency_id,                                     }\\" class=\\"text-success mb-0 mt-1\\"/>\\n                                <small t-if=\\"sale_order.currency_id.compare_amounts(advantage_tax_incl, advantage_tax_excl)\\" class=\\"text-muted\\">\\n                                    (<span t-out=\\"advantage_tax_excl\\" t-options=\\"{                                             'widget': 'monetary',                                             'display_currency': sale_order.currency_id,                                         }\\"/> Excl. Tax)\\n                                </small>\\n                            </div>\\n                        </t>\\n\\n                        <div t-if=\\"sidebar_invoices and sale_order.state in ['sale', 'cancel']\\" id=\\"sidebar_invoices\\" class=\\"d-flex flex-column gap-1 overflow-hidden\\">\\n                            <hr/>\\n                            <strong class=\\"smaller text-uppercase text-muted\\">Invoices</strong>\\n                            <div class=\\"d-flex flex-column gap-1\\">\\n                                <t t-foreach=\\"sidebar_invoices\\" t-as=\\"inv\\">\\n                                    <div class=\\"d-flex align-items-center gap-2 text-wrap\\">\\n                                        <a t-att-href=\\"inv.get_portal_url()\\">\\n                                            <t t-out=\\"inv.name\\"/>\\n                                        </a>\\n                                        <small class=\\"ms-auto text-muted\\" t-field=\\"inv.invoice_date\\"/>\\n                                    </div>\\n                                </t>\\n                            </div>\\n                        </div>\\n\\n                        <div id=\\"sidebar_loyalty_anchor\\"/>\\n\\n                        <div t-if=\\"sale_order.user_id\\">\\n                            <t t-call=\\"portal.portal_my_contact\\" _contact_avatar=\\"image_data_uri(sale_order.user_id.avatar_128)\\" _contact_name=\\"sale_order.user_id.name\\" _contact_link=\\"True\\"/>\\n                        </div>\\n\\n                    </div>\\n                </t>\\n\\n                <t t-call=\\"portal.portal_record_sidebar\\" classes.f=\\"col-lg-4 col-xl-3 d-none d-lg-block d-print-none order-lg-first\\" title=\\"title\\" subtitle=\\"subtitle\\" entries=\\"entries\\"/>\\n\\n\\n                <!-- Page content -->\\n                <div id=\\"quote_content\\" class=\\"col-12 col-lg-8 col-xl-9 mt-0\\">\\n\\n                    <!-- Modals container -->\\n                    <div role=\\"dialog\\" class=\\"modal fade\\" id=\\"modalaccept\\" name=\\"sale_order_modal_sign_and_pay\\">\\n                        <div t-if=\\"sale_order._has_to_be_signed() and not payment_amount\\" class=\\"modal-dialog\\"><t t-call=\\"sale.sale_order_portal_sign_modal\\"/></div>\\n                        <div t-elif=\\"not sale_order._has_to_be_signed()                                     and sale_order._has_to_be_paid()                                     or (payment_amount and sale_order.state != 'cancel')\\" name=\\"sale_order_modal_validate\\" class=\\"modal-dialog\\"><t t-call=\\"sale.sale_order_portal_pay_modal\\"/></div>\\n                    </div>\\n\\n                    <!-- modal relative to the action reject -->\\n                    <div role=\\"dialog\\" class=\\"modal fade\\" id=\\"modaldecline\\">\\n                        <div class=\\"modal-dialog\\">\\n                            <form id=\\"decline\\" method=\\"POST\\" t-attf-action=\\"/my/orders/#{sale_order.id}/decline?access_token=#{sale_order.access_token}\\" class=\\"modal-content\\">\\n                                <input type=\\"hidden\\" name=\\"csrf_token\\" t-att-value=\\"request.csrf_token()\\"/>\\n                                <header class=\\"modal-header\\">\\n                                    <h4 class=\\"modal-title\\">Reject This Quotation</h4>\\n                                    <button type=\\"button\\" class=\\"btn-close\\" data-bs-dismiss=\\"modal\\" aria-label=\\"Close\\"/>\\n                                </header>\\n                                <main class=\\"modal-body\\">\\n                                    <p>\\n                                        Tell us why you are refusing this quotation, this will help us improve our services.\\n                                    </p>\\n                                    <textarea rows=\\"4\\" name=\\"decline_message\\" required=\\"\\" placeholder=\\"Your feedback...\\" class=\\"form-control\\"/>\\n                                </main>\\n                                <footer class=\\"modal-footer\\">\\n                                    <button type=\\"submit\\" t-att-id=\\"sale_order.id\\" class=\\"btn btn-danger\\">\\n                                        <i class=\\"oi\\" data-icon=\\"close\\"/> Reject\\n                                    </button>\\n                                    <button type=\\"button\\" class=\\"btn btn-primary\\" data-bs-dismiss=\\"modal\\">\\n                                        Discard\\n                                    </button>\\n                                </footer>\\n                            </form>\\n                        </div>\\n                    </div>\\n\\n                    <!-- status messages -->\\n                    <div t-if=\\"message == 'sign_ok'\\" class=\\"alert alert-success alert-dismissible d-print-none\\" role=\\"status\\">\\n                        <button type=\\"button\\" class=\\"btn-close\\" data-bs-dismiss=\\"alert\\" aria-label=\\"Close\\"/>\\n                        <strong>Thank You!</strong><br/>\\n                        <t t-if=\\"message == 'sign_ok' and sale_order.state == 'sale'\\">\\n                            Your order has been confirmed.\\n                        </t>\\n                        <t t-elif=\\"message == 'sign_ok' and sale_order._has_to_be_paid()\\">\\n                            Your order has been signed but still needs to be paid to be confirmed.\\n                        </t>\\n                        <t t-else=\\"\\">Your order has been signed.</t>\\n                    </div>\\n\\n                    <div t-if=\\"message == 'cant_reject'\\" class=\\"alert alert-danger alert-dismissible d-print-none\\" role=\\"alert\\">\\n                        <button type=\\"button\\" class=\\"btn-close\\" data-bs-dismiss=\\"alert\\" aria-label=\\"Close\\"/>\\n                        Your order is not in a state to be rejected.\\n                    </div>\\n\\n                    <t t-set=\\"current_tx\\" t-value=\\"sale_order.get_portal_last_transaction()\\"/>\\n                    <!-- hide state header when invoice is posted for current transaction. -->\\n                    <t t-if=\\"current_tx and not (len(current_tx.invoice_ids) == 1 and current_tx.invoice_ids.state == 'posted')\\">\\n                        <t t-call=\\"payment.state_header\\" tx=\\"current_tx\\"/>\\n                    </t>\\n\\n                    <div t-if=\\"sale_order.state == 'cancel'\\" class=\\"alert alert-danger alert-dismissible d-print-none\\" role=\\"alert\\">\\n                        <button type=\\"button\\" class=\\"btn-close\\" data-bs-dismiss=\\"alert\\" aria-label=\\"close\\"/>\\n                        <strong>This quotation has been cancelled.</strong> <a role=\\"button\\" href=\\"#discussion\\"><i class=\\"oi oi-filled\\" data-icon=\\"chat_bubble\\"/> Contact us to get a new quotation.</a>\\n                    </div>\\n\\n                    <div t-if=\\"sale_order.is_expired\\" class=\\"alert alert-warning alert-dismissible d-print-none\\" role=\\"alert\\">\\n                        <button type=\\"button\\" class=\\"btn-close\\" data-bs-dismiss=\\"alert\\" aria-label=\\"close\\"/>\\n                        <strong>This offer expired!</strong> <a role=\\"button\\" href=\\"#discussion\\"><i class=\\"oi oi-filled\\" data-icon=\\"chat_bubble\\"/> Contact us to get a new quotation.</a>\\n                    </div>\\n\\n                    <!-- main content -->\\n                    <div id=\\"portal_sale_content\\">\\n                        <div><t t-call=\\"#{sale_order._get_name_portal_content_view()}\\"/></div>\\n                    </div>\\n\\n                    <!-- Actions -->\\n                    <div t-if=\\"sale_order._has_to_be_signed() or sale_order._has_to_be_paid()\\" class=\\"d-none d-lg-flex flex-column gap-2 w-100 w-lg-50 mx-auto my-5 d-print-none\\">\\n                        <t t-if=\\"sale_order._has_to_be_signed()\\">\\n                            <a role=\\"button\\" class=\\"btn btn-primary btn-lg\\" data-bs-toggle=\\"modal\\" data-bs-target=\\"#modalaccept\\" href=\\"#\\">\\n                                <i class=\\"oi\\" data-icon=\\"check\\"/>\\n                                <t t-if=\\"sale_order._has_to_be_paid()\\">Sign &amp; Pay</t>\\n                                <t t-else=\\"\\">Accept &amp; Sign</t>\\n                            </a>\\n                            <a role=\\"button\\" class=\\"btn btn-link text-reset\\" data-bs-toggle=\\"modal\\" data-bs-target=\\"#modaldecline\\" href=\\"#\\">\\n                                Reject this quotation\\n                            </a>\\n                        </t>\\n                        <t t-elif=\\"sale_order._has_to_be_paid()\\">\\n                            <a role=\\"button\\" data-bs-toggle=\\"modal\\" data-bs-target=\\"#modalaccept\\" href=\\"#\\" t-att-class=\\"'btn btn-lg rounded %s' % ('btn-light' if sale_order.transaction_ids else 'btn-primary')\\">\\n                                <t t-if=\\"not sale_order.signature\\">Accept &amp; Pay</t>\\n                                <t t-else=\\"\\">Pay Now</t>\\n                            </a>\\n                        </t>\\n                    </div>\\n\\n                    <!-- Mobile Invoices  -->\\n                    <div t-if=\\"sidebar_invoices and sale_order.state in ['sale', 'cancel']\\" class=\\"d-lg-none mt-4 p-3 rounded-3 border d-print-none\\">\\n                        <h4>Invoices</h4>\\n                        <div class=\\"d-flex flex-column gap-2 mt-2\\">\\n                            <t t-foreach=\\"sidebar_invoices\\" t-as=\\"inv\\">\\n                                <a t-att-href=\\"inv.get_portal_url()\\" class=\\"d-flex align-items-center gap-2 text-decoration-none\\">\\n                                    <span class=\\"flex-grow-1 text-truncate\\" t-out=\\"inv.name\\"/>\\n                                    <small class=\\"text-muted text-nowrap\\" t-field=\\"inv.invoice_date\\"/>\\n                                </a>\\n                            </t>\\n                        </div>\\n                    </div>\\n\\n                    <!-- Feedback -->\\n                    <div id=\\"provide_feedback\\" class=\\"mt-4 p-3 p-lg-4 rounded-3 border\\">\\n                        <div id=\\"sale_order_communication\\">\\n                            <h4 class=\\"pb-1\\">Provide feedback</h4>\\n                            <t t-call=\\"portal.message_thread\\" hide_header=\\"True\\"/>\\n                        </div>\\n                    </div>\\n                </div><!-- // #quote_content -->\\n\\n                <!-- Mobile sticky action bar -->\\n                <t t-set=\\"mobile_has_to_be_signed\\" t-value=\\"sale_order._has_to_be_signed() and not payment_amount\\"/>\\n                <t t-set=\\"mobile_has_to_be_paid\\" t-value=\\"sale_order._has_to_be_paid() or (payment_amount and sale_order.amount_paid &lt; sale_order.amount_total and sale_order.state != 'cancel')\\"/>\\n                <t t-set=\\"mobile_can_reorder\\" t-value=\\"'website_id' in env['sale.order']._fields and sale_order.with_user(env.user).sudo()._is_reorder_allowed()\\"/>\\n                <!-- Set by the modules contributing an action to the bar, e.g. `sale_stock` for the returns. -->\\n                <t t-set=\\"mobile_additional_action\\" t-value=\\"False\\"/>\\n                <t t-set=\\"mobile_has_primary_action\\" t-value=\\"mobile_has_to_be_signed or mobile_has_to_be_paid or mobile_can_reorder\\"/>\\n                <t t-if=\\"mobile_has_primary_action or mobile_additional_action\\">\\n                    <div id=\\"mobile_action_bar\\" class=\\"o_portal_mobile_action_bar d-flex d-lg-none flex-column position-fixed bottom-0 start-0 end-0 pt-1 bg-white border-top shadow d-print-none\\" t-att-style=\\"'z-index: 1029;'\\">\\n\\n                        <!-- Price row -->\\n                        <div class=\\"d-flex flex-wrap align-items-center pt-2 pb-1\\">\\n                            <span class=\\"fw-bold fs-5\\">\\n                                <t t-if=\\"sale_order._has_to_be_paid() and sale_order.prepayment_percent != 1.0\\">\\n                                    <t t-out=\\"sale_order._get_prepayment_required_amount()\\" t-options=\\"{'widget': 'monetary', 'display_currency': sale_order.currency_id}\\"/>\\n                                    <small class=\\"fw-normal text-muted ms-1\\">(<t t-out=\\"sale_order.prepayment_percent * 100\\" t-options=\\"{'widget': 'float'}\\"/>%)</small>\\n                                </t>\\n                                <span t-else=\\"\\" t-field=\\"sale_order.amount_total\\"/>\\n                            </span>\\n                            <t t-if=\\"not sale_order.is_expired                                     and sale_order.state in ['draft', 'sent']                                     and advantage_tax_incl &lt; 0\\">\\n                                <span class=\\"ms-auto d-inline-flex align-items-center gap-1 small text-nowrap text-success\\">\\n                                    <i class=\\"oi\\" data-icon=\\"sell\\"/>\\n                                    <span class=\\"fw-semibold\\">\\n                                        <t t-out=\\"-advantage_tax_incl\\" t-options=\\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: sale_order.currency_id}\\"/>\\n                                    </span>\\n                                    <span class=\\"text-muted fw-normal\\">saved</span>\\n                                </span>\\n                            </t>\\n                        </div>\\n\\n                        <!-- Action buttons -->\\n                        <div class=\\"o_portal_mobile_action_buttons d-flex flex-wrap gap-2 pb-3 pt-1\\">\\n                            <a t-if=\\"mobile_has_to_be_signed\\" role=\\"button\\" class=\\"btn btn-primary flex-grow-1\\" data-bs-toggle=\\"modal\\" data-bs-target=\\"#modalaccept\\" href=\\"#\\">\\n                                <t t-if=\\"sale_order._has_to_be_paid()\\">Sign &amp; Pay</t>\\n                                <t t-else=\\"\\">Accept &amp; Sign</t>\\n                            </a>\\n                            <a t-elif=\\"mobile_has_to_be_paid\\" id=\\"o_sale_portal_paynow_mobile\\" role=\\"button\\" data-bs-toggle=\\"modal\\" data-bs-target=\\"#modalaccept\\" href=\\"#\\" t-att-class=\\"'btn flex-grow-1 ' + ('btn-primary' if not sale_order.transaction_ids else 'btn-light')\\">\\n                                <t t-if=\\"not sale_order.signature                                         and sale_order._has_to_be_paid()                                         and not payment_amount\\">Accept &amp; Pay</t>\\n                                <t t-else=\\"\\">Pay Now</t>\\n                            </a>\\n                            <button t-elif=\\"mobile_can_reorder\\" class=\\"btn btn-secondary flex-grow-1 o_wsale_reorder_button oe_website_sale\\" t-att-data-sale-order-id=\\"sale_order.id\\">\\n                                <i class=\\"oi me-1\\" data-icon=\\"redo\\"/>Order Again\\n                            </button>\\n                            <a role=\\"button\\" t-if=\\"mobile_has_to_be_signed\\" class=\\"btn btn-light\\" data-bs-toggle=\\"modal\\" data-bs-target=\\"#modaldecline\\" href=\\"#\\">\\n                                Reject\\n                            </a>\\n                            <a role=\\"button\\" id=\\"mobile_feedback_button\\" class=\\"btn btn-light\\" href=\\"#provide_feedback\\" aria-label=\\"Provide feedback\\">\\n                                <i class=\\"oi\\" data-icon=\\"chat_bubble\\"/>\\n                            </a>\\n                        </div>\\n                    </div>\\n                </t>\\n            </div>\\n        </xpath>\\n    <xpath expr=\\".\\" position=\\"attributes\\"><attribute name=\\"t-name\\">sale.sale_order_portal_template</attribute></xpath></data>", "es_ES": "<data name=\\"Sales Order\\">\\n\\n        <xpath expr=\\"//div[hasclass('o_portal_sidebar')]\\" position=\\"inside\\">\\n            <div class=\\"row o_portal_sale_sidebar\\" t-att-data-order-amount-total=\\"sale_order.amount_total\\" t-att-data-is-partially-paid=\\"'true' if sale_order._is_partially_paid() else 'false'\\">\\n                <t t-set=\\"sidebar_invoices\\" t-value=\\"sale_order.invoice_ids.filtered(lambda i: i.state not in ['draft', 'cancel']).sorted('date', reverse=True)\\"/>\\n\\n                <!-- Sidebar -->\\n                <t t-set=\\"title\\">\\n                    <!-- <t t-if=\\"sale_order._has_to_be_paid() and sale_order.prepayment_percent != 1.0\\">\\n                        <h4>Down payment</h4>\\n                        <h2>\\n                            <t\\n                                t-out=\\"sale_order._get_prepayment_required_amount()\\"\\n                                t-options=\\"{\\n                                    'widget': 'monetary',\\n                                    'display_currency': sale_order.currency_id,\\n                                }\\"\\n                            />\\n                            (<t\\n                                t-out=\\"sale_order.prepayment_percent * 100\\"\\n                                t-options=\\"{'widget': 'float', 'precision': 2, 'min_precision': 0}\\"\\n                            />%)\\n                        </h2>\\n                    </t> -->\\n                    <h2 t-field=\\"sale_order.amount_total\\" class=\\"mb-0 text-break\\"/>\\n                </t>\\n                <t t-set=\\"subtitle\\">Tax Included</t>\\n                <t t-set=\\"entries\\">\\n                    <div t-if=\\"sale_order.state in ('draft', 'sent') and sale_order.prepayment_percent != 1.0\\" class=\\"alert alert-warning mt-3\\" role=\\"alert\\">\\n                        Down payment:\\n                        <span t-out=\\"sale_order._get_prepayment_required_amount()\\" t-options=\\"{                                 'widget': 'monetary',                                 'display_currency': sale_order.currency_id,                             }\\"/>\\n                    </div>\\n                    <div t-if=\\"0 &lt; sale_order.amount_paid &lt; sale_order.amount_total                                 and sale_order.state != 'cancel'\\" class=\\"alert alert-success mt-3\\" role=\\"alert\\">\\n                        Paid:\\n                    <span t-field=\\"sale_order.amount_paid\\" t-options=\\"{                                     'widget': 'monetary',                                     'display_currency': sale_order.currency_id,                                 }\\"/>\\n                    </div>\\n\\n                    <div class=\\"d-none d-lg-flex flex-column mt-3\\">\\n                        <div class=\\"d-flex flex-column gap-2\\" id=\\"sale_order_sidebar_button\\">\\n                            <a t-if=\\"sale_order._has_to_be_signed() and not payment_amount\\" role=\\"button\\" class=\\"btn btn-primary\\" data-bs-toggle=\\"modal\\" data-bs-target=\\"#modalaccept\\" href=\\"#\\"> <!-- If paying by link, signing is skipped. -->\\n                                <t t-if=\\"sale_order._has_to_be_paid()\\"> Firmar &amp; pagar</t>\\n                                <t t-else=\\"\\"> Aceptar y firmar</t>\\n                            </a>\\n                            <a t-elif=\\"sale_order._has_to_be_paid()                                             or (                                                 payment_amount                                                 and sale_order.amount_paid &lt; sale_order.amount_total                                                 and sale_order.state != 'cancel'                                             )\\" id=\\"o_sale_portal_paynow\\" role=\\"button\\" data-bs-toggle=\\"modal\\" data-bs-target=\\"#modalaccept\\" href=\\"#\\" t-att-class=\\"'btn btn-primary' if not sale_order.transaction_ids else 'btn btn-light'\\">\\n                                <t t-if=\\"not sale_order.signature                                              and sale_order._has_to_be_paid()                                              and not payment_amount\\"> Aceptar y pagar</t>\\n                                <t t-else=\\"\\"> Pagar ahora</t>\\n                            </a>\\n                            <div id=\\"print_invoice_sidebar_button\\" class=\\"o_download_pdf d-flex gap-2 flex-lg-column flex-xl-row flex-wrap\\">\\n                                <a class=\\"btn btn-light o_print_btn o_portal_invoice_print flex-grow-1\\" t-att-href=\\"sale_order.get_portal_url(report_type='pdf')\\" id=\\"print_invoice_report\\" title=\\"Ver detalles\\" role=\\"button\\" target=\\"_blank\\">Descargar</a>\\n                            </div>\\n                        </div>\\n\\n                        <t t-if=\\"not sale_order.is_expired and sale_order.state in ['draft', 'sent']\\">\\n                            <div t-if=\\"advantage_tax_incl &lt; 0\\" class=\\"d-none d-lg-block\\" name=\\"sale_order_advantage\\">\\n                                <hr/>\\n                                <strong class=\\"smaller text-uppercase text-muted\\">Your advantage</strong>\\n                                <h5 t-out=\\"advantage_tax_incl\\" t-options=\\"{                                         'widget': 'monetary',                                         'display_currency': sale_order.currency_id,                                     }\\" class=\\"text-success mb-0 mt-1\\"/>\\n                                <small t-if=\\"sale_order.currency_id.compare_amounts(advantage_tax_incl, advantage_tax_excl)\\" class=\\"text-muted\\">\\n                                    (<span t-out=\\"advantage_tax_excl\\" t-options=\\"{                                             'widget': 'monetary',                                             'display_currency': sale_order.currency_id,                                         }\\"/> excl. impuestos)\\n                                </small>\\n                            </div>\\n                        </t>\\n\\n                        <div t-if=\\"sidebar_invoices and sale_order.state in ['sale', 'cancel']\\" id=\\"sidebar_invoices\\" class=\\"d-flex flex-column gap-1 overflow-hidden\\">\\n                            <hr/>\\n                            <strong class=\\"smaller text-uppercase text-muted\\">Invoices</strong>\\n                            <div class=\\"d-flex flex-column gap-1\\">\\n                                <t t-foreach=\\"sidebar_invoices\\" t-as=\\"inv\\">\\n                                    <div class=\\"d-flex align-items-center gap-2 text-wrap\\">\\n                                        <a t-att-href=\\"inv.get_portal_url()\\">\\n                                            <t t-out=\\"inv.name\\"/>\\n                                        </a>\\n                                        <small class=\\"ms-auto text-muted\\" t-field=\\"inv.invoice_date\\"/>\\n                                    </div>\\n                                </t>\\n                            </div>\\n                        </div>\\n\\n                        <div id=\\"sidebar_loyalty_anchor\\"/>\\n\\n                        <div t-if=\\"sale_order.user_id\\">\\n                            <t t-call=\\"portal.portal_my_contact\\" _contact_avatar=\\"image_data_uri(sale_order.user_id.avatar_128)\\" _contact_name=\\"sale_order.user_id.name\\" _contact_link=\\"True\\"/>\\n                        </div>\\n\\n                    </div>\\n                </t>\\n\\n                <t t-call=\\"portal.portal_record_sidebar\\" classes.f=\\"col-lg-4 col-xl-3 d-none d-lg-block d-print-none order-lg-first\\" title=\\"title\\" subtitle=\\"subtitle\\" entries=\\"entries\\"/>\\n\\n\\n                <!-- Page content -->\\n                <div id=\\"quote_content\\" class=\\"col-12 col-lg-8 col-xl-9 mt-0\\">\\n\\n                    <!-- Modals container -->\\n                    <div role=\\"dialog\\" class=\\"modal fade\\" id=\\"modalaccept\\" name=\\"sale_order_modal_sign_and_pay\\">\\n                        <div t-if=\\"sale_order._has_to_be_signed() and not payment_amount\\" class=\\"modal-dialog\\"><t t-call=\\"sale.sale_order_portal_sign_modal\\"/></div>\\n                        <div t-elif=\\"not sale_order._has_to_be_signed()                                     and sale_order._has_to_be_paid()                                     or (payment_amount and sale_order.state != 'cancel')\\" name=\\"sale_order_modal_validate\\" class=\\"modal-dialog\\"><t t-call=\\"sale.sale_order_portal_pay_modal\\"/></div>\\n                    </div>\\n\\n                    <!-- modal relative to the action reject -->\\n                    <div role=\\"dialog\\" class=\\"modal fade\\" id=\\"modaldecline\\">\\n                        <div class=\\"modal-dialog\\">\\n                            <form id=\\"decline\\" method=\\"POST\\" t-attf-action=\\"/my/orders/#{sale_order.id}/decline?access_token=#{sale_order.access_token}\\" class=\\"modal-content\\">\\n                                <input type=\\"hidden\\" name=\\"csrf_token\\" t-att-value=\\"request.csrf_token()\\"/>\\n                                <header class=\\"modal-header\\">\\n                                    <h4 class=\\"modal-title\\">Rechazar este presupuesto</h4>\\n                                    <button type=\\"button\\" class=\\"btn-close\\" data-bs-dismiss=\\"modal\\" aria-label=\\"Cerrar\\"/>\\n                                </header>\\n                                <main class=\\"modal-body\\">\\n                                    <p>\\n                                        Cuéntenos por qué rechaza este presupuesto. Nos ayudará a mejorar nuestro servicio.\\n                                    </p>\\n                                    <textarea rows=\\"4\\" name=\\"decline_message\\" required=\\"\\" placeholder=\\"Sus comentarios...\\" class=\\"form-control\\"/>\\n                                </main>\\n                                <footer class=\\"modal-footer\\">\\n                                    <button type=\\"submit\\" t-att-id=\\"sale_order.id\\" class=\\"btn btn-danger\\">\\n                                        <i class=\\"oi\\" data-icon=\\"close\\"/> Rechazar\\n                                    </button>\\n                                    <button type=\\"button\\" class=\\"btn btn-primary\\" data-bs-dismiss=\\"modal\\">\\n                                        Descartar\\n                                    </button>\\n                                </footer>\\n                            </form>\\n                        </div>\\n                    </div>\\n\\n                    <!-- status messages -->\\n                    <div t-if=\\"message == 'sign_ok'\\" class=\\"alert alert-success alert-dismissible d-print-none\\" role=\\"status\\">\\n                        <button type=\\"button\\" class=\\"btn-close\\" data-bs-dismiss=\\"alert\\" aria-label=\\"Cerrar\\"/>\\n                        <strong>¡Gracias!</strong><br/>\\n                        <t t-if=\\"message == 'sign_ok' and sale_order.state == 'sale'\\">\\n                            Se ha confirmado su pedido.\\n                        </t>\\n                        <t t-elif=\\"message == 'sign_ok' and sale_order._has_to_be_paid()\\">\\n                            Se ha firmado su pedido, pero tiene que pagarse para ser confirmado.\\n                        </t>\\n                        <t t-else=\\"\\">Se ha firmado su pedido.</t>\\n                    </div>\\n\\n                    <div t-if=\\"message == 'cant_reject'\\" class=\\"alert alert-danger alert-dismissible d-print-none\\" role=\\"alert\\">\\n                        <button type=\\"button\\" class=\\"btn-close\\" data-bs-dismiss=\\"alert\\" aria-label=\\"Cerrar\\"/>\\n                        No se puede rechazar su pedido.\\n                    </div>\\n\\n                    <t t-set=\\"current_tx\\" t-value=\\"sale_order.get_portal_last_transaction()\\"/>\\n                    <!-- hide state header when invoice is posted for current transaction. -->\\n                    <t t-if=\\"current_tx and not (len(current_tx.invoice_ids) == 1 and current_tx.invoice_ids.state == 'posted')\\">\\n                        <t t-call=\\"payment.state_header\\" tx=\\"current_tx\\"/>\\n                    </t>\\n\\n                    <div t-if=\\"sale_order.state == 'cancel'\\" class=\\"alert alert-danger alert-dismissible d-print-none\\" role=\\"alert\\">\\n                        <button type=\\"button\\" class=\\"btn-close\\" data-bs-dismiss=\\"alert\\" aria-label=\\"cerrar\\"/>\\n                        <strong>Este presupuesto ha sido cancelado.</strong> <a role=\\"button\\" href=\\"#discussion\\"><i class=\\"oi oi-filled\\" data-icon=\\"chat_bubble\\"/> Contacta con nosotros para recibir un nuevo presupuesto.</a>\\n                    </div>\\n\\n                    <div t-if=\\"sale_order.is_expired\\" class=\\"alert alert-warning alert-dismissible d-print-none\\" role=\\"alert\\">\\n                        <button type=\\"button\\" class=\\"btn-close\\" data-bs-dismiss=\\"alert\\" aria-label=\\"cerrar\\"/>\\n                        <strong>¡Esta oferta expiró!</strong> <a role=\\"button\\" href=\\"#discussion\\"><i class=\\"oi oi-filled\\" data-icon=\\"chat_bubble\\"/> Contacta con nosotros para recibir un nuevo presupuesto.</a>\\n                    </div>\\n\\n                    <!-- main content -->\\n                    <div id=\\"portal_sale_content\\">\\n                        <div><t t-call=\\"#{sale_order._get_name_portal_content_view()}\\"/></div>\\n                    </div>\\n\\n                    <!-- Actions -->\\n                    <div t-if=\\"sale_order._has_to_be_signed() or sale_order._has_to_be_paid()\\" class=\\"d-none d-lg-flex flex-column gap-2 w-100 w-lg-50 mx-auto my-5 d-print-none\\">\\n                        <t t-if=\\"sale_order._has_to_be_signed()\\">\\n                            <a role=\\"button\\" class=\\"btn btn-primary btn-lg\\" data-bs-toggle=\\"modal\\" data-bs-target=\\"#modalaccept\\" href=\\"#\\">\\n                                <i class=\\"oi\\" data-icon=\\"check\\"/>\\n                                <t t-if=\\"sale_order._has_to_be_paid()\\">Firmar &amp; pagar</t>\\n                                <t t-else=\\"\\">Aceptar y firmar</t>\\n                            </a>\\n                            <a role=\\"button\\" class=\\"btn btn-link text-reset\\" data-bs-toggle=\\"modal\\" data-bs-target=\\"#modaldecline\\" href=\\"#\\">\\n                                Reject this quotation\\n                            </a>\\n                        </t>\\n                        <t t-elif=\\"sale_order._has_to_be_paid()\\">\\n                            <a role=\\"button\\" data-bs-toggle=\\"modal\\" data-bs-target=\\"#modalaccept\\" href=\\"#\\" t-att-class=\\"'btn btn-lg rounded %s' % ('btn-light' if sale_order.transaction_ids else 'btn-primary')\\">\\n                                <t t-if=\\"not sale_order.signature\\">Aceptar y pagar</t>\\n                                <t t-else=\\"\\">Pagar ahora</t>\\n                            </a>\\n                        </t>\\n                    </div>\\n\\n                    <!-- Mobile Invoices  -->\\n                    <div t-if=\\"sidebar_invoices and sale_order.state in ['sale', 'cancel']\\" class=\\"d-lg-none mt-4 p-3 rounded-3 border d-print-none\\">\\n                        <h4>Facturas</h4>\\n                        <div class=\\"d-flex flex-column gap-2 mt-2\\">\\n                            <t t-foreach=\\"sidebar_invoices\\" t-as=\\"inv\\">\\n                                <a t-att-href=\\"inv.get_portal_url()\\" class=\\"d-flex align-items-center gap-2 text-decoration-none\\">\\n                                    <span class=\\"flex-grow-1 text-truncate\\" t-out=\\"inv.name\\"/>\\n                                    <small class=\\"text-muted text-nowrap\\" t-field=\\"inv.invoice_date\\"/>\\n                                </a>\\n                            </t>\\n                        </div>\\n                    </div>\\n\\n                    <!-- Feedback -->\\n                    <div id=\\"provide_feedback\\" class=\\"mt-4 p-3 p-lg-4 rounded-3 border\\">\\n                        <div id=\\"sale_order_communication\\">\\n                            <h4 class=\\"pb-1\\">Provide feedback</h4>\\n                            <t t-call=\\"portal.message_thread\\" hide_header=\\"True\\"/>\\n                        </div>\\n                    </div>\\n                </div><!-- // #quote_content -->\\n\\n                <!-- Mobile sticky action bar -->\\n                <t t-set=\\"mobile_has_to_be_signed\\" t-value=\\"sale_order._has_to_be_signed() and not payment_amount\\"/>\\n                <t t-set=\\"mobile_has_to_be_paid\\" t-value=\\"sale_order._has_to_be_paid() or (payment_amount and sale_order.amount_paid &lt; sale_order.amount_total and sale_order.state != 'cancel')\\"/>\\n                <t t-set=\\"mobile_can_reorder\\" t-value=\\"'website_id' in env['sale.order']._fields and sale_order.with_user(env.user).sudo()._is_reorder_allowed()\\"/>\\n                <!-- Set by the modules contributing an action to the bar, e.g. `sale_stock` for the returns. -->\\n                <t t-set=\\"mobile_additional_action\\" t-value=\\"False\\"/>\\n                <t t-set=\\"mobile_has_primary_action\\" t-value=\\"mobile_has_to_be_signed or mobile_has_to_be_paid or mobile_can_reorder\\"/>\\n                <t t-if=\\"mobile_has_primary_action or mobile_additional_action\\">\\n                    <div id=\\"mobile_action_bar\\" class=\\"o_portal_mobile_action_bar d-flex d-lg-none flex-column position-fixed bottom-0 start-0 end-0 pt-1 bg-white border-top shadow d-print-none\\" t-att-style=\\"'z-index: 1029;'\\">\\n\\n                        <!-- Price row -->\\n                        <div class=\\"d-flex flex-wrap align-items-center pt-2 pb-1\\">\\n                            <span class=\\"fw-bold fs-5\\">\\n                                <t t-if=\\"sale_order._has_to_be_paid() and sale_order.prepayment_percent != 1.0\\">\\n                                    <t t-out=\\"sale_order._get_prepayment_required_amount()\\" t-options=\\"{'widget': 'monetary', 'display_currency': sale_order.currency_id}\\"/>\\n                                    <small class=\\"fw-normal text-muted ms-1\\">(<t t-out=\\"sale_order.prepayment_percent * 100\\" t-options=\\"{'widget': 'float'}\\"/>%)</small>\\n                                </t>\\n                                <span t-else=\\"\\" t-field=\\"sale_order.amount_total\\"/>\\n                            </span>\\n                            <t t-if=\\"not sale_order.is_expired                                     and sale_order.state in ['draft', 'sent']                                     and advantage_tax_incl &lt; 0\\">\\n                                <span class=\\"ms-auto d-inline-flex align-items-center gap-1 small text-nowrap text-success\\">\\n                                    <i class=\\"oi\\" data-icon=\\"sell\\"/>\\n                                    <span class=\\"fw-semibold\\">\\n                                        <t t-out=\\"-advantage_tax_incl\\" t-options=\\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: sale_order.currency_id}\\"/>\\n                                    </span>\\n                                    <span class=\\"text-muted fw-normal\\">saved</span>\\n                                </span>\\n                            </t>\\n                        </div>\\n\\n                        <!-- Action buttons -->\\n                        <div class=\\"o_portal_mobile_action_buttons d-flex flex-wrap gap-2 pb-3 pt-1\\">\\n                            <a t-if=\\"mobile_has_to_be_signed\\" role=\\"button\\" class=\\"btn btn-primary flex-grow-1\\" data-bs-toggle=\\"modal\\" data-bs-target=\\"#modalaccept\\" href=\\"#\\">\\n                                <t t-if=\\"sale_order._has_to_be_paid()\\">Firmar &amp; pagar</t>\\n                                <t t-else=\\"\\">Aceptar y firmar</t>\\n                            </a>\\n                            <a t-elif=\\"mobile_has_to_be_paid\\" id=\\"o_sale_portal_paynow_mobile\\" role=\\"button\\" data-bs-toggle=\\"modal\\" data-bs-target=\\"#modalaccept\\" href=\\"#\\" t-att-class=\\"'btn flex-grow-1 ' + ('btn-primary' if not sale_order.transaction_ids else 'btn-light')\\">\\n                                <t t-if=\\"not sale_order.signature                                         and sale_order._has_to_be_paid()                                         and not payment_amount\\">Aceptar y pagar</t>\\n                                <t t-else=\\"\\">Pagar ahora</t>\\n                            </a>\\n                            <button t-elif=\\"mobile_can_reorder\\" class=\\"btn btn-secondary flex-grow-1 o_wsale_reorder_button oe_website_sale\\" t-att-data-sale-order-id=\\"sale_order.id\\">\\n                                <i class=\\"oi me-1\\" data-icon=\\"redo\\"/>Order Again\\n                            </button>\\n                            <a role=\\"button\\" t-if=\\"mobile_has_to_be_signed\\" class=\\"btn btn-light\\" data-bs-toggle=\\"modal\\" data-bs-target=\\"#modaldecline\\" href=\\"#\\">\\n                                Reject\\n                            </a>\\n                            <a role=\\"button\\" id=\\"mobile_feedback_button\\" class=\\"btn btn-light\\" href=\\"#provide_feedback\\" aria-label=\\"Provide feedback\\">\\n                                <i class=\\"oi\\" data-icon=\\"chat_bubble\\"/>\\n                            </a>\\n                        </div>\\n                    </div>\\n                </t>\\n            </div>\\n        </xpath>\\n    <xpath expr=\\".\\" position=\\"attributes\\"><attribute name=\\"t-name\\">sale.sale_order_portal_template</attribute></xpath></data>"}	<?xml version="1.0"?>\n<data name="Sales Order">\n\n        <xpath expr="//div[hasclass('o_portal_sidebar')]" position="inside">\n            <div class="row o_portal_sale_sidebar" t-att-data-order-amount-total="sale_order.amount_total" t-att-data-is-partially-paid="'true' if sale_order._is_partially_paid() else 'false'">\n                <t t-set="sidebar_invoices" t-value="sale_order.invoice_ids.filtered(lambda i: i.state not in ['draft', 'cancel']).sorted('date', reverse=True)"/>\n\n                <!-- Sidebar -->\n                <t t-set="title">\n                    <!-- <t t-if="sale_order._has_to_be_paid() and sale_order.prepayment_percent != 1.0">\n                        <h4>Down payment</h4>\n                        <h2>\n                            <t\n                                t-out="sale_order._get_prepayment_required_amount()"\n                                t-options="{\n                                    'widget': 'monetary',\n                                    'display_currency': sale_order.currency_id,\n                                }"\n                            />\n                            (<t\n                                t-out="sale_order.prepayment_percent * 100"\n                                t-options="{'widget': 'float', 'precision': 2, 'min_precision': 0}"\n                            />%)\n                        </h2>\n                    </t> -->\n                    <h2 t-field="sale_order.amount_total" class="mb-0 text-break"/>\n                </t>\n                <t t-set="subtitle">Tax Included</t>\n                <t t-set="entries">\n                    <div t-if="sale_order.state in ('draft', 'sent') and sale_order.prepayment_percent != 1.0" class="alert alert-warning mt-3" role="alert">\n                        Down payment:\n                        <span t-out="sale_order._get_prepayment_required_amount()" t-options="{                                 'widget': 'monetary',                                 'display_currency': sale_order.currency_id,                             }"/>\n                    </div>\n                    <div t-if="0 &lt; sale_order.amount_paid &lt; sale_order.amount_total                                 and sale_order.state != 'cancel'" class="alert alert-success mt-3" role="alert">\n                        Paid:\n                    <span t-field="sale_order.amount_paid" t-options="{                                     'widget': 'monetary',                                     'display_currency': sale_order.currency_id,                                 }"/>\n                    </div>\n\n                    <div class="d-none d-lg-flex flex-column mt-3">\n                        <div class="d-flex flex-column gap-2" id="sale_order_sidebar_button">\n                            <a t-if="sale_order._has_to_be_signed() and not payment_amount" role="button" class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#modalaccept" href="#"> <!-- If paying by link, signing is skipped. -->\n                                <t t-if="sale_order._has_to_be_paid()"> Sign &amp; Pay</t>\n                                <t t-else=""> Accept &amp; Sign</t>\n                            </a>\n                            <a t-elif="sale_order._has_to_be_paid()                                             or (                                                 payment_amount                                                 and sale_order.amount_paid &lt; sale_order.amount_total                                                 and sale_order.state != 'cancel'                                             )" id="o_sale_portal_paynow" role="button" data-bs-toggle="modal" data-bs-target="#modalaccept" href="#" t-att-class="'btn btn-primary' if not sale_order.transaction_ids else 'btn btn-light'">\n                                <t t-if="not sale_order.signature                                              and sale_order._has_to_be_paid()                                              and not payment_amount"> Accept &amp; Pay</t>\n                                <t t-else=""> Pay Now</t>\n                            </a>\n                            <div id="print_invoice_sidebar_button" class="o_download_pdf d-flex gap-2 flex-lg-column flex-xl-row flex-wrap">\n                                <a class="btn btn-light o_print_btn o_portal_invoice_print flex-grow-1" t-att-href="sale_order.get_portal_url(report_type='pdf')" id="print_invoice_report" title="View Details" role="button" target="_blank">Download</a>\n                            </div>\n                        </div>\n\n                        <t t-if="not sale_order.is_expired and sale_order.state in ['draft', 'sent']">\n                            <div t-if="advantage_tax_incl &lt; 0" class="d-none d-lg-block" name="sale_order_advantage">\n                                <hr/>\n                                <strong class="smaller text-uppercase text-muted">Your advantage</strong>\n                                <h5 t-out="advantage_tax_incl" t-options="{                                         'widget': 'monetary',                                         'display_currency': sale_order.currency_id,                                     }" class="text-success mb-0 mt-1"/>\n                                <small t-if="sale_order.currency_id.compare_amounts(advantage_tax_incl, advantage_tax_excl)" class="text-muted">\n                                    (<span t-out="advantage_tax_excl" t-options="{                                             'widget': 'monetary',                                             'display_currency': sale_order.currency_id,                                         }"/> Excl. Tax)\n                                </small>\n                            </div>\n                        </t>\n\n                        <div t-if="sidebar_invoices and sale_order.state in ['sale', 'cancel']" id="sidebar_invoices" class="d-flex flex-column gap-1 overflow-hidden">\n                            <hr/>\n                            <strong class="smaller text-uppercase text-muted">Invoices</strong>\n                            <div class="d-flex flex-column gap-1">\n                                <t t-foreach="sidebar_invoices" t-as="inv">\n                                    <div class="d-flex align-items-center gap-2 text-wrap">\n                                        <a t-att-href="inv.get_portal_url()">\n                                            <t t-out="inv.name"/>\n                                        </a>\n                                        <small class="ms-auto text-muted" t-field="inv.invoice_date"/>\n                                    </div>\n                                </t>\n                            </div>\n                        </div>\n\n                        <div id="sidebar_loyalty_anchor"/>\n\n                        <div t-if="sale_order.user_id">\n                            <t t-call="portal.portal_my_contact" _contact_avatar="image_data_uri(sale_order.user_id.avatar_128)" _contact_name="sale_order.user_id.name" _contact_link="True"/>\n                        </div>\n\n                    </div>\n                </t>\n\n                <t t-call="portal.portal_record_sidebar" classes.f="col-lg-4 col-xl-3 d-none d-lg-block d-print-none order-lg-first" title="title" subtitle="subtitle" entries="entries"/>\n\n\n                <!-- Page content -->\n                <div id="quote_content" class="col-12 col-lg-8 col-xl-9 mt-0">\n\n                    <!-- Modals container -->\n                    <div role="dialog" class="modal fade" id="modalaccept" name="sale_order_modal_sign_and_pay">\n                        <div t-if="sale_order._has_to_be_signed() and not payment_amount" class="modal-dialog"><t t-call="sale.sale_order_portal_sign_modal"/></div>\n                        <div t-elif="not sale_order._has_to_be_signed()                                     and sale_order._has_to_be_paid()                                     or (payment_amount and sale_order.state != 'cancel')" name="sale_order_modal_validate" class="modal-dialog"><t t-call="sale.sale_order_portal_pay_modal"/></div>\n                    </div>\n\n                    <!-- modal relative to the action reject -->\n                    <div role="dialog" class="modal fade" id="modaldecline">\n                        <div class="modal-dialog">\n                            <form id="decline" method="POST" t-attf-action="/my/orders/#{sale_order.id}/decline?access_token=#{sale_order.access_token}" class="modal-content">\n                                <input type="hidden" name="csrf_token" t-att-value="request.csrf_token()"/>\n                                <header class="modal-header">\n                                    <h4 class="modal-title">Reject This Quotation</h4>\n                                    <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"/>\n                                </header>\n                                <main class="modal-body">\n                                    <p>\n                                        Tell us why you are refusing this quotation, this will help us improve our services.\n                                    </p>\n                                    <textarea rows="4" name="decline_message" required="" placeholder="Your feedback..." class="form-control"/>\n                                </main>\n                                <footer class="modal-footer">\n                                    <button type="submit" t-att-id="sale_order.id" class="btn btn-danger">\n                                        <i class="oi" data-icon="close"/> Reject\n                                    </button>\n                                    <button type="button" class="btn btn-primary" data-bs-dismiss="modal">\n                                        Discard\n                                    </button>\n                                </footer>\n                            </form>\n                        </div>\n                    </div>\n\n                    <!-- status messages -->\n                    <div t-if="message == 'sign_ok'" class="alert alert-success alert-dismissible d-print-none" role="status">\n                        <button type="button" class="btn-close" data-bs-dismiss="alert" aria-label="Close"/>\n                        <strong>Thank You!</strong><br/>\n                        <t t-if="message == 'sign_ok' and sale_order.state == 'sale'">\n                            Your order has been confirmed.\n                        </t>\n                        <t t-elif="message == 'sign_ok' and sale_order._has_to_be_paid()">\n                            Your order has been signed but still needs to be paid to be confirmed.\n                        </t>\n                        <t t-else="">Your order has been signed.</t>\n                    </div>\n\n                    <div t-if="message == 'cant_reject'" class="alert alert-danger alert-dismissible d-print-none" role="alert">\n                        <button type="button" class="btn-close" data-bs-dismiss="alert" aria-label="Close"/>\n                        Your order is not in a state to be rejected.\n                    </div>\n\n                    <t t-set="current_tx" t-value="sale_order.get_portal_last_transaction()"/>\n                    <!-- hide state header when invoice is posted for current transaction. -->\n                    <t t-if="current_tx and not (len(current_tx.invoice_ids) == 1 and current_tx.invoice_ids.state == 'posted')">\n                        <t t-call="payment.state_header" tx="current_tx"/>\n                    </t>\n\n                    <div t-if="sale_order.state == 'cancel'" class="alert alert-danger alert-dismissible d-print-none" role="alert">\n                        <button type="button" class="btn-close" data-bs-dismiss="alert" aria-label="close"/>\n                        <strong>This quotation has been cancelled.</strong> <a role="button" href="#discussion"><i class="oi oi-filled" data-icon="chat_bubble"/> Contact us to get a new quotation.</a>\n                    </div>\n\n                    <div t-if="sale_order.is_expired" class="alert alert-warning alert-dismissible d-print-none" role="alert">\n                        <button type="button" class="btn-close" data-bs-dismiss="alert" aria-label="close"/>\n                        <strong>This offer expired!</strong> <a role="button" href="#discussion"><i class="oi oi-filled" data-icon="chat_bubble"/> Contact us to get a new quotation.</a>\n                    </div>\n\n                    <!-- main content -->\n                    <div id="portal_sale_content">\n                        <div><t t-call="#{sale_order._get_name_portal_content_view()}"/></div>\n                    </div>\n\n                    <!-- Actions -->\n                    <div t-if="sale_order._has_to_be_signed() or sale_order._has_to_be_paid()" class="d-none d-lg-flex flex-column gap-2 w-100 w-lg-50 mx-auto my-5 d-print-none">\n                        <t t-if="sale_order._has_to_be_signed()">\n                            <a role="button" class="btn btn-primary btn-lg" data-bs-toggle="modal" data-bs-target="#modalaccept" href="#">\n                                <i class="oi" data-icon="check"/>\n                                <t t-if="sale_order._has_to_be_paid()">Sign &amp; Pay</t>\n                                <t t-else="">Accept &amp; Sign</t>\n                            </a>\n                            <a role="button" class="btn btn-link text-reset" data-bs-toggle="modal" data-bs-target="#modaldecline" href="#">\n                                Reject this quotation\n                            </a>\n                        </t>\n                        <t t-elif="sale_order._has_to_be_paid()">\n                            <a role="button" data-bs-toggle="modal" data-bs-target="#modalaccept" href="#" t-att-class="'btn btn-lg rounded %s' % ('btn-light' if sale_order.transaction_ids else 'btn-primary')">\n                                <t t-if="not sale_order.signature">Accept &amp; Pay</t>\n                                <t t-else="">Pay Now</t>\n                            </a>\n                        </t>\n                    </div>\n\n                    <!-- Mobile Invoices  -->\n                    <div t-if="sidebar_invoices and sale_order.state in ['sale', 'cancel']" class="d-lg-none mt-4 p-3 rounded-3 border d-print-none">\n                        <h4>Invoices</h4>\n                        <div class="d-flex flex-column gap-2 mt-2">\n                            <t t-foreach="sidebar_invoices" t-as="inv">\n                                <a t-att-href="inv.get_portal_url()" class="d-flex align-items-center gap-2 text-decoration-none">\n                                    <span class="flex-grow-1 text-truncate" t-out="inv.name"/>\n                                    <small class="text-muted text-nowrap" t-field="inv.invoice_date"/>\n                                </a>\n                            </t>\n                        </div>\n                    </div>\n\n                    <!-- Feedback -->\n                    <div id="provide_feedback" class="mt-4 p-3 p-lg-4 rounded-3 border">\n                        <div id="sale_order_communication">\n                            <h4 class="pb-1">Provide feedback</h4>\n                            <t t-call="portal.message_thread" hide_header="True"/>\n                        </div>\n                    </div>\n                </div><!-- // #quote_content -->\n\n                <!-- Mobile sticky action bar -->\n                <t t-set="mobile_has_to_be_signed" t-value="sale_order._has_to_be_signed() and not payment_amount"/>\n                <t t-set="mobile_has_to_be_paid" t-value="sale_order._has_to_be_paid() or (payment_amount and sale_order.amount_paid &lt; sale_order.amount_total and sale_order.state != 'cancel')"/>\n                <t t-set="mobile_can_reorder" t-value="'website_id' in env['sale.order']._fields and sale_order.with_user(env.user).sudo()._is_reorder_allowed()"/>\n                <!-- Set by the modules contributing an action to the bar, e.g. `sale_stock` for the returns. -->\n                <t t-set="mobile_additional_action" t-value="False"/>\n                <t t-set="mobile_has_primary_action" t-value="mobile_has_to_be_signed or mobile_has_to_be_paid or mobile_can_reorder"/>\n                <t t-if="mobile_has_primary_action or mobile_additional_action">\n                    <div id="mobile_action_bar" class="o_portal_mobile_action_bar d-flex d-lg-none flex-column position-fixed bottom-0 start-0 end-0 pt-1 bg-white border-top shadow d-print-none" t-att-style="'z-index: 1029;'">\n\n                        <!-- Price row -->\n                        <div class="d-flex flex-wrap align-items-center pt-2 pb-1">\n                            <span class="fw-bold fs-5">\n                                <t t-if="sale_order._has_to_be_paid() and sale_order.prepayment_percent != 1.0">\n                                    <t t-out="sale_order._get_prepayment_required_amount()" t-options="{'widget': 'monetary', 'display_currency': sale_order.currency_id}"/>\n                                    <small class="fw-normal text-muted ms-1">(<t t-out="sale_order.prepayment_percent * 100" t-options="{'widget': 'float'}"/>%)</small>\n                                </t>\n                                <span t-else="" t-field="sale_order.amount_total"/>\n                            </span>\n                            <t t-if="not sale_order.is_expired                                     and sale_order.state in ['draft', 'sent']                                     and advantage_tax_incl &lt; 0">\n                                <span class="ms-auto d-inline-flex align-items-center gap-1 small text-nowrap text-success">\n                                    <i class="oi" data-icon="sell"/>\n                                    <span class="fw-semibold">\n                                        <t t-out="-advantage_tax_incl" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: sale_order.currency_id}"/>\n                                    </span>\n                                    <span class="text-muted fw-normal">saved</span>\n                                </span>\n                            </t>\n                        </div>\n\n                        <!-- Action buttons -->\n                        <div class="o_portal_mobile_action_buttons d-flex flex-wrap gap-2 pb-3 pt-1">\n                            <a t-if="mobile_has_to_be_signed" role="button" class="btn btn-primary flex-grow-1" data-bs-toggle="modal" data-bs-target="#modalaccept" href="#">\n                                <t t-if="sale_order._has_to_be_paid()">Sign &amp; Pay</t>\n                                <t t-else="">Accept &amp; Sign</t>\n                            </a>\n                            <a t-elif="mobile_has_to_be_paid" id="o_sale_portal_paynow_mobile" role="button" data-bs-toggle="modal" data-bs-target="#modalaccept" href="#" t-att-class="'btn flex-grow-1 ' + ('btn-primary' if not sale_order.transaction_ids else 'btn-light')">\n                                <t t-if="not sale_order.signature                                         and sale_order._has_to_be_paid()                                         and not payment_amount">Accept &amp; Pay</t>\n                                <t t-else="">Pay Now</t>\n                            </a>\n                            <button t-elif="mobile_can_reorder" class="btn btn-secondary flex-grow-1 o_wsale_reorder_button oe_website_sale" t-att-data-sale-order-id="sale_order.id">\n                                <i class="oi me-1" data-icon="redo"/>Order Again\n                            </button>\n                            <a role="button" t-if="mobile_has_to_be_signed" class="btn btn-light" data-bs-toggle="modal" data-bs-target="#modaldecline" href="#">\n                                Reject\n                            </a>\n                            <a role="button" id="mobile_feedback_button" class="btn btn-light" href="#provide_feedback" aria-label="Provide feedback">\n                                <i class="oi" data-icon="chat_bubble"/>\n                            </a>\n                        </div>\n                    </div>\n                </t>\n            </div>\n        </xpath>\n    <xpath expr="." position="attributes"><attribute name="t-name">sale.sale_order_portal_template</attribute></xpath></data>\n\n    	\N	f	t	2026-10-26 23:48:31.401934	2026-10-26 23:48:31.401934	f
