1088	16	\N	1	1	Sales Order Portal Content	\N	sale.sale_order_portal_content	qweb	sale/views/sale_portal_templates.xml	primary	\N	{"en_US": "<t name=\\"Sales Order Portal Content\\" t-name=\\"sale.sale_order_portal_content\\">\\n        <!-- Intro -->\\n        <div id=\\"introduction\\" class=\\"p-3 p-lg-4 bg-100 border rounded-top\\">\\n            <div class=\\"d-flex flex-column flex-lg-row\\" id=\\"intro_row\\">\\n                <div class=\\"d-flex flex-row flex-grow-1 flex-shrink-1 flex-basis-0 min-w-0\\">\\n                    <div class=\\"d-flex flex-column me-auto\\">\\n                        <small>\\n                            <span class=\\"text-muted\\">\\n                                <t t-if=\\"sale_order.state == 'sale'\\">Sales Order for</t>\\n                                <t t-else=\\"\\">Quotation for</t>\\n                            </span>\\n                            <b t-out=\\"sale_order.partner_id.name\\"/>\\n                        </small>\\n                        <h2 class=\\"mb-0\\">\\n                            <t t-out=\\"sale_order.name\\"/>\\n                        </h2>\\n                        <div class=\\"d-flex align-items-center gap-1 text-muted small flex-wrap\\">\\n                            <span t-field=\\"sale_order.date_order\\" t-options=\\"{&quot;widget&quot;: &quot;date&quot;}\\"/>\\n                            <t t-if=\\"sale_order.validity_date and sale_order.state in ['draft', 'sent']\\">\\n                                <span>·</span>\\n                                <span class=\\"text-warning-emphasis\\">Valid until <span t-field=\\"sale_order.validity_date\\" t-options=\\"{&quot;widget&quot;: &quot;date&quot;}\\"/></span>\\n                            </t>\\n                            <t t-if=\\"sale_order.client_order_ref\\">\\n                                <span>·</span>\\n                                <span>Ref: <span t-field=\\"sale_order.client_order_ref\\"/></span>\\n                            </t>\\n                            <t t-if=\\"sale_order.incoterm\\">\\n                                <span>·</span>\\n                                <span t-field=\\"sale_order.incoterm.code\\"/>\\n                                <span t-if=\\"sale_order.incoterm_location\\" t-field=\\"sale_order.incoterm_location\\"/>\\n                            </t>\\n                        </div>\\n                    </div>\\n                    <div class=\\"d-inline-block d-lg-none\\">\\n                        <a class=\\"btn btn-secondary flex-grow-1 o_print_btn o_portal_invoice_print\\" t-att-href=\\"sale_order.get_portal_url(report_type='pdf')\\" title=\\"Download\\" role=\\"button\\" target=\\"_blank\\">\\n                            <i class=\\"oi\\" data-icon=\\"download\\"/>\\n                        </a>\\n                    </div>\\n                </div>\\n                <div class=\\"d-flex flex-column align-items-end flex-grow-1 flex-shrink-1 flex-basis-0 min-w-0\\" id=\\"transaction_info\\">\\n                    <div t-if=\\"sale_order.get_portal_last_transaction() and not invoices and sale_order.state in ('sent', 'sale') and portal_confirmation == 'pay' and not success and not error\\" t-att-data-order-id=\\"sale_order.id\\">\\n                        <t t-if=\\"sale_order.transaction_ids\\">\\n                            <t t-call=\\"payment.state_header\\" tx=\\"sale_order.get_portal_last_transaction()\\"/>\\n                        </t>\\n                    </div>\\n                </div>\\n            </div>\\n            <hr t-if=\\"has_info_cards\\" class=\\"my-3 my-lg-4 mx-n3 mx-lg-n4\\"/>\\n            <div t-if=\\"has_info_cards\\" id=\\"informations\\" class=\\"d-flex flex-column flex-lg-row gap-4 pt-2\\"/>\\n        </div>\\n        <div id=\\"content\\">\\n\\n            <section id=\\"details\\" class=\\"p-0 p-lg-3 pt-lg-0 rounded-bottom border-start border-end border-bottom\\" style=\\"page-break-inside: auto;\\">\\n                <t t-set=\\"lines_to_report\\" t-value=\\"sale_order._get_order_lines_to_report()\\"/>\\n                <t t-set=\\"display_discount\\" t-value=\\"any(line.discount &gt; 0 for line in lines_to_report)\\"/>\\n                <t t-set=\\"hide_taxes_details\\" t-value=\\"False\\"/>\\n                <t t-set=\\"display_taxes\\" t-value=\\"not hide_taxes_details and any(line._has_taxes() for line in lines_to_report)\\"/>\\n                <t t-if=\\"sale_order.company_id.show_sol_numbers\\" t-set=\\"line_counter\\" t-value=\\"1\\"/>\\n                <!-- ===== MOBILE VIEW ===== -->\\n                    <div class=\\"d-lg-none\\">\\n                        <t t-set=\\"current_section_m\\" t-value=\\"None\\"/>\\n                        <t t-set=\\"current_subsection_m\\" t-value=\\"None\\"/>\\n                        <t t-set=\\"collapse_prices_m\\" t-value=\\"False\\"/>\\n                        <t t-set=\\"price_field_m\\" t-value=\\"'price_total' if hide_taxes_details else 'price_subtotal'\\"/>\\n\\n                        <t t-foreach=\\"lines_to_report\\" t-as=\\"line\\">\\n                            <t t-set=\\"is_note_m\\" t-value=\\"line.display_type == 'line_note'\\"/>\\n                            <t t-set=\\"is_section_m\\" t-value=\\"line.display_type == 'line_section'\\"/>\\n                            <t t-set=\\"is_subsection_m\\" t-value=\\"line.display_type == 'line_subsection'\\"/>\\n                            <t t-set=\\"is_combo_m\\" t-value=\\"line.product_type == 'combo'\\"/>\\n\\n                            <t t-if=\\"is_section_m\\">\\n                                <t t-set=\\"current_section_m\\" t-value=\\"line\\"/>\\n                                <t t-set=\\"current_subsection_m\\" t-value=\\"None\\"/>\\n                                <t t-set=\\"collapse_prices_m\\" t-value=\\"line.collapse_prices\\"/>\\n                            </t>\\n                            <t t-elif=\\"is_subsection_m\\">\\n                                <t t-set=\\"current_subsection_m\\" t-value=\\"line\\"/>\\n                                <t t-set=\\"collapse_prices_m\\" t-value=\\"current_section_m.collapse_prices or line.collapse_prices\\"/>\\n                            </t>\\n\\n                            <t t-if=\\"not line.collapse_composition\\">\\n                                <!-- Section / Subsection header -->\\n                                <div t-if=\\"is_section_m or is_subsection_m\\" t-attf-class=\\"d-flex justify-content-between align-items-center py-2 px-3 fw-bold border-bottom {{ 'bg-200' if is_section_m else 'bg-100' }}\\">\\n                                    <span t-field=\\"line.label\\"/>\\n                                    <span t-if=\\"is_section_m or not line.parent_id.collapse_prices\\" class=\\"text-nowrap ms-2\\" t-out=\\"line._get_section_totals(price_field_m)\\" t-options=\\"{'widget': 'monetary', 'display_currency': sale_order.currency_id}\\"/>\\n                                </div>\\n\\n                                <!-- Note -->\\n                                <div t-elif=\\"is_note_m\\" class=\\"fst-italic py-2 px-3 border-bottom text-muted small\\">\\n                                    <span t-field=\\"line.label\\"/>\\n                                </div>\\n\\n                                <!-- Combo header -->\\n                                <div t-elif=\\"is_combo_m\\" class=\\"d-flex justify-content-between align-items-start py-3 px-3 border-bottom fw-bold\\">\\n                                    <div>\\n                                        <span t-field=\\"line.label\\"/>\\n                                        <div class=\\"fw-normal text-muted small mt-1\\">\\n                                            <span t-field=\\"line.product_uom_qty\\" t-options=\\"{'min_precision': 0}\\"/>\\n                                            <span class=\\"ms-1\\" t-field=\\"line.product_uom_id\\"/>\\n                                        </div>\\n                                    </div>\\n                                    <span t-if=\\"not collapse_prices_m\\" class=\\"text-nowrap ms-3\\" t-out=\\"line._get_combo_totals(price_field_m)\\" t-options=\\"{'widget': 'monetary', 'display_currency': sale_order.currency_id}\\"/>\\n                                </div>\\n\\n                                <!-- Regular product line -->\\n                                <div t-else=\\"\\" class=\\"py-3 px-3 border-bottom\\">\\n                                    <!-- Name + subtotal -->\\n                                    <div class=\\"d-flex justify-content-between align-items-start gap-2\\">\\n                                        <t t-set=\\"label_parts_m\\" t-value=\\"(line.label or '').split('\\\\n', 1)\\"/>\\n                                        <t t-set=\\"name_title_m\\" t-value=\\"label_parts_m[0][label_parts_m[0].find(']') + 2:] if label_parts_m[0].startswith('[') else label_parts_m[0]\\"/>\\n                                        <span t-out=\\"name_title_m\\"/>\\n                                        <t t-if=\\"not line.is_downpayment and not collapse_prices_m\\">\\n                                            <span t-if=\\"price_field_m == 'price_subtotal'\\" class=\\"text-nowrap\\" t-field=\\"line.price_subtotal\\"/>\\n                                            <span t-else=\\"\\" class=\\"text-nowrap\\" t-field=\\"line.price_total\\"/>\\n                                        </t>\\n                                    </div>\\n                                    <!-- Optional description -->\\n                                    <span t-if=\\"len(label_parts_m) &gt; 1\\" class=\\"o_sale_portal_line_description d-block text-muted small mt-1\\" t-out=\\"label_parts_m[1]\\"/>\\n                                    <t t-if=\\"not collapse_prices_m\\">\\n                                        <!-- Qty × price (with strikethrough + discounted price if rebate) -->\\n                                        <div class=\\"d-flex flex-wrap align-items-baseline gap-1 mt-1 small text-muted\\">\\n                                            <span name=\\"span_qty_uom\\">\\n                                                <span t-field=\\"line.product_uom_qty\\" t-options=\\"{'min_precision': 0}\\"/>\\n                                                <span class=\\"ms-1\\" t-field=\\"line.product_uom_id\\"/>\\n                                            </span>\\n                                            <t t-if=\\"line.price_unit\\">\\n                                                <span>×</span>\\n                                                <span t-if=\\"line.discount\\" t-out=\\"line._get_discounted_price()\\" t-options=\\"{'widget': 'monetary', 'display_currency': line.currency_id}\\"/>\\n                                                <span t-if=\\"line.discount &gt;= 0\\" t-field=\\"line.price_unit\\" t-att-class=\\"line.discount &gt; 0 and 'text-decoration-line-through opacity-50' or ''\\" t-options=\\"{'widget': 'monetary', 'display_currency': line.currency_id}\\"/>\\n                                                <t t-if=\\"line.discount &gt; 0\\">\\n                                                    <span class=\\"small text-success fw-medium\\">\\n                                                        (−<t t-out=\\"((line.discount % 1) and '%s' or '%d') % line.discount\\"/>%)\\n                                                    </span>\\n                                                </t>\\n                                            </t>\\n                                        </div>\\n                                        <!-- Taxes as plain text -->\\n                                        <div t-if=\\"display_taxes and line.tax_ids\\" class=\\"mt-1 small text-muted\\">\\n                                            <span>Tax:</span>\\n                                            <span t-out=\\"', '.join(map(lambda x: (x.name), line.tax_ids))\\"/>\\n                                        </div>\\n                                    </t>\\n                                </div>\\n                            </t>\\n                            <t t-else=\\"\\">\\n                                <!-- Collapsed composition: grouped section summary -->\\n                                <t t-foreach=\\"line._get_grouped_section_summary(display_taxes)\\" t-as=\\"section_line\\">\\n                                    <div class=\\"py-3 px-3 border-bottom\\">\\n                                        <div class=\\"d-flex justify-content-between align-items-start gap-2\\">\\n                                            <span t-field=\\"line.label\\"/>\\n                                            <span t-out=\\"section_line[price_field_m]\\" t-options=\\"{'widget': 'monetary', 'display_currency': sale_order.currency_id}\\" class=\\"text-nowrap\\"/>\\n                                        </div>\\n                                        <div class=\\"d-flex flex-wrap align-items-center gap-2 mt-1 small text-muted\\">\\n                                            <span t-field=\\"line.section_qty\\" t-options=\\"{'min_precision': 0}\\"/>\\n                                            <span t-field=\\"line.section_uom_id\\"/>\\n                                            <span>×</span>\\n                                            <span t-out=\\"section_line['price_subtotal']/line.section_qty\\" t-options=\\"{'widget': 'monetary', 'display_currency': sale_order.currency_id}\\"/>\\n                                        </div>\\n                                        <div t-if=\\"display_taxes and section_line.get('tax_labels')\\" class=\\"mt-1 small text-muted\\">\\n                                            <span>Tax:</span>\\n                                            <t t-foreach=\\"section_line['tax_labels']\\" t-as=\\"tax_label\\">\\n                                                <t t-if=\\"not tax_label_first\\">, </t>\\n                                                <span t-out=\\"tax_label\\"/>\\n                                            </t>\\n                                        </div>\\n                                    </div>\\n                                </t>\\n                            </t>\\n                        </t>\\n                    </div>\\n\\n                <!-- ===== DESKTOP TABLE ===== -->\\n                <div name=\\"sol_table\\" class=\\"table-responsive d-none d-lg-block\\">\\n                    <table t-att-data-order-id=\\"sale_order.id\\" t-att-data-token=\\"sale_order.access_token\\" class=\\"table\\" id=\\"sales_order_table\\">\\n                        <thead class=\\"d-none d-lg-contents\\">\\n                            <tr>\\n                                <th t-if=\\"line_counter\\" id=\\"line_number_header\\" class=\\"text-start\\" style=\\"width: 1%; white-space: nowrap;\\">#</th>\\n                                <th class=\\"text-start\\" id=\\"product_name_header\\" aria-label=\\"Description\\"/>\\n                                <th class=\\"text-end\\" id=\\"product_qty_header\\" aria-label=\\"Quantity\\"/>\\n                                <th t-if=\\"display_discount\\" class=\\"text-end d-none d-sm-table-cell\\" id=\\"product_discount_header\\">\\n                                    <span>Discount</span>\\n                                </th>\\n                                <th class=\\"text-end text-nowrap d-none d-sm-table-cell\\" id=\\"product_unit_price_header\\">\\n                                    Unit Price\\n                                </th>\\n                                <th t-if=\\"display_taxes\\" class=\\"text-end d-none d-md-table-cell\\" id=\\"taxes_header\\">\\n                                    <span>Taxes</span>\\n                                </th>\\n                                <th class=\\"text-end\\" id=\\"subtotal_header\\">\\n                                    <span>Amount</span>\\n                                </th>\\n                            </tr>\\n                        </thead>\\n                        <tbody class=\\"sale_tbody\\">\\n\\n                            <t t-set=\\"current_section\\" t-value=\\"None\\"/>\\n                            <t t-set=\\"current_subsection\\" t-value=\\"None\\"/>\\n                            <t t-set=\\"price_field\\" t-value=\\"'price_total' if (hide_taxes_details or sale_order.company_price_include == 'tax_included') else 'price_subtotal'\\"/>\\n                            <t t-set=\\"default_section_uom\\" t-value=\\"sale_order.env.ref('uom.product_uom_unit')\\"/>\\n\\n                            <t t-foreach=\\"lines_to_report\\" t-as=\\"line\\">\\n\\n                                <t t-set=\\"is_note\\" t-value=\\"line.display_type == 'line_note'\\"/>\\n                                <t t-set=\\"is_section\\" t-value=\\"line.display_type == 'line_section'\\"/>\\n                                <t t-set=\\"is_subsection\\" t-value=\\"line.display_type == 'line_subsection'\\"/>\\n                                <t t-set=\\"is_combo\\" t-value=\\"line.product_type == 'combo'\\"/>\\n\\n                                <t t-if=\\"is_section\\">\\n                                    <t t-set=\\"current_section\\" t-value=\\"line\\"/>\\n                                    <t t-set=\\"current_subsection\\" t-value=\\"None\\"/>\\n                                    <t t-set=\\"line_padding\\" t-value=\\"0\\"/>\\n                                    <t t-set=\\"collapse_prices\\" t-value=\\"line.collapse_prices\\"/>\\n                                </t>\\n                                <t t-elif=\\"is_subsection\\">\\n                                    <t t-set=\\"current_subsection\\" t-value=\\"line\\"/>\\n                                    <t t-set=\\"line_padding\\" t-value=\\"2\\"/>\\n                                    <t t-set=\\"collapse_prices\\" t-value=\\"current_section.collapse_prices or line.collapse_prices\\"/>\\n                                </t>\\n                                <t t-else=\\"\\">\\n                                    <t t-set=\\"line_padding\\" t-value=\\"3 if current_subsection else (2 if current_section else 0)\\"/>\\n                                </t>\\n\\n                                <t t-if=\\"line.combo_item_id\\">\\n                                    <t t-set=\\"line_padding\\" t-value=\\"line_padding + 1\\"/>\\n                                </t>\\n\\n                                <t t-set=\\"padding_style\\" t-value=\\"(                                         line_padding                                         and ('padding-left:' + str(line_padding * 8) + 'px')                                         or 'padding-left: 4px'                                     )\\"/>\\n                                <t t-set=\\"show_section_total\\" t-value=\\"is_section or not line.parent_id.collapse_prices\\"/>\\n\\n                                <t t-if=\\"not line.collapse_composition\\">\\n                                    <tr t-if=\\"is_section or is_subsection\\" name=\\"tr_section\\" t-attf-class=\\"{{'o_line_section bg-200' if is_section else 'o_line_subsection bg-100'}} fw-bold\\">\\n                                        <t t-set=\\"show_section_total\\" t-value=\\"(                                                 (                                                     is_section                                                     or not line.parent_id.collapse_prices                                                 )                                                 and not line.is_downpayment                                             )\\"/>\\n                                        <t t-set=\\"section_name_colspan\\" t-value=\\"3 + (1 if display_discount else 0) + (1 if display_taxes else 0)\\"/>\\n                                        <t t-if=\\"not show_section_total\\">\\n                                            <t t-set=\\"section_name_colspan\\" t-value=\\"99\\"/>\\n                                        </t>\\n                                        <t t-set=\\"show_section_qty_uom\\" t-value=\\"line.section_qty != 1 or (line.section_uom_id and line.section_uom_id != default_section_uom)\\"/>\\n                                        <!-- Some columns (e.g. Discount and Unit Price)\\n                                        are not displayed on smaller viewports -->\\n                                        <td t-if=\\"line_counter\\" name=\\"td_section_line_no\\" class=\\"text-start\\">\\n                                            <span t-out=\\"line_counter\\"/>\\n                                            <t t-set=\\"line_counter\\" t-value=\\"line_counter + 1\\"/>\\n                                        </td>\\n                                        <td name=\\"td_section_name_xs\\" t-att-colspan=\\"section_name_colspan - 1 - (1 if display_discount else 0) - (1 if display_taxes else 0)\\" class=\\"d-sm-none\\" t-att-style=\\"padding_style\\">\\n                                            <span t-field=\\"line.label\\"/>\\n                                            <span t-if=\\"show_section_qty_uom\\" class=\\"text-muted fw-normal ms-1\\">(<span t-field=\\"line.section_qty\\" t-options=\\"{'widget': 'float', 'min_precision': 0}\\"/> <span t-field=\\"line.section_uom_id\\"/>)</span>\\n                                        </td>\\n                                        <td name=\\"td_section_name_sm\\" t-att-colspan=\\"section_name_colspan - (1 if display_taxes else 0)\\" class=\\"d-none d-sm-table-cell d-md-none\\" t-att-style=\\"padding_style\\">\\n                                            <span t-field=\\"line.label\\"/>\\n                                            <span t-if=\\"show_section_qty_uom\\" class=\\"text-muted fw-normal ms-1\\">(<span t-field=\\"line.section_qty\\" t-options=\\"{'widget': 'float', 'min_precision': 0}\\"/> <span t-field=\\"line.section_uom_id\\"/>)</span>\\n                                        </td>\\n                                        <td name=\\"td_section_name\\" t-att-colspan=\\"section_name_colspan\\" class=\\"d-none d-md-table-cell\\" t-att-style=\\"padding_style\\">\\n                                            <span t-field=\\"line.label\\"/>\\n                                            <span t-if=\\"show_section_qty_uom\\" class=\\"text-muted fw-normal ms-1\\">(<span t-field=\\"line.section_qty\\" t-options=\\"{'widget': 'float', 'min_precision': 0}\\"/> <span t-field=\\"line.section_uom_id\\"/>)</span>\\n                                        </td>\\n                                        <td t-if=\\"show_section_total\\" name=\\"td_section_price\\" class=\\"text-end o_price_total\\">\\n                                            <span name=\\"price_subtotal_section\\" t-out=\\"line._get_section_totals(price_field)\\" class=\\"text-nowrap\\" t-options=\\"{'widget': 'monetary', 'display_currency': sale_order.currency_id}\\"/>\\n                                        </td>\\n                                    </tr>\\n                                    <tr t-elif=\\"is_note\\" name=\\"tr_note\\" class=\\"fst-italic o_line_note\\">\\n                                        <td t-if=\\"line_counter\\" name=\\"td_note_line_no\\" class=\\"text-start fst-normal\\">\\n                                            <span t-out=\\"line_counter\\"/>\\n                                            <t t-set=\\"line_counter\\" t-value=\\"line_counter + 1\\"/>\\n                                        </td>\\n                                        <td name=\\"td_note_name\\" colspan=\\"99\\" t-att-style=\\"padding_style\\">\\n                                            <span t-field=\\"line.label\\"/>\\n                                        </td>\\n                                    </tr>\\n                                    <tr t-elif=\\"is_combo\\" name=\\"tr_combo\\" class=\\"fw-bold\\">\\n                                        <td t-if=\\"line_counter\\" name=\\"td_combo_line_no\\" class=\\"text-start\\">\\n                                            <span t-out=\\"line_counter\\"/>\\n                                            <t t-set=\\"line_counter\\" t-value=\\"line_counter + 1\\"/>\\n                                        </td>\\n                                        <td name=\\"td_combo_name\\" t-att-style=\\"padding_style\\">\\n                                            <span t-field=\\"line.label\\">Combo Product</span>\\n                                        </td>\\n                                        <td name=\\"td_combo_quantity\\" class=\\"text-end\\">\\n                                            <div id=\\"quote_qty\\">\\n                                                <span t-field=\\"line.product_uom_qty\\" t-options=\\"{'min_precision': 0}\\"/>\\n                                                <span t-field=\\"line.product_uom_id\\"/>\\n                                            </div>\\n                                        </td>\\n                                        <td name=\\"td_combo_subtotal\\" class=\\"text-end\\" t-att-colspan=\\"2 + (1 if display_discount else 0) + (1 if display_taxes else 0)\\">\\n                                            <span t-if=\\"not collapse_prices\\" name=\\"price_subtotal_combo\\" t-out=\\"line._get_combo_totals(price_field)\\" class=\\"text-nowrap\\" t-options=\\"{'widget': 'monetary', 'display_currency': sale_order.currency_id}\\">\\n                                                27.00\\n                                            </span>\\n                                        </td>\\n                                    </tr>\\n                                    <tr t-else=\\"\\" name=\\"tr_product\\">\\n                                        <td t-if=\\"line_counter\\" name=\\"td_product_line_no\\" class=\\"text-start\\">\\n                                            <span t-out=\\"line_counter\\"/>\\n                                            <t t-set=\\"line_counter\\" t-value=\\"line_counter + 1\\"/>\\n                                        </td>\\n                                        <td name=\\"td_product_name\\" t-att-style=\\"padding_style\\">\\n                                            <div class=\\"d-flex flex-row align-items-center\\">\\n                                                <img t-if=\\"sale_order.company_id.display_product_images_on_so and line.product_id.image_128\\" t-att-src=\\"image_data_uri(line.product_id.image_128)\\" t-att-alt=\\"line.product_id.display_name\\" class=\\"o_sale_portal_product_image d-none d-lg-inline me-2 rounded object-fit-cover\\"/>\\n                                                <div>\\n                                                    <t t-set=\\"label_parts\\" t-value=\\"(line.label or '').split('\\\\n', 1)\\"/>\\n                                                    <span name=\\"span_product_name\\" t-out=\\"label_parts[0]\\"/>\\n                                                    <span t-if=\\"len(label_parts) &gt; 1\\" class=\\"o_sale_portal_line_description d-block text-muted small\\" t-out=\\"label_parts[1]\\"/>\\n                                                </div>\\n                                            </div>\\n                                        </td>\\n                                        <td name=\\"td_product_quantity\\" class=\\"text-end\\">\\n                                            <div id=\\"quote_qty\\">\\n                                                <span t-field=\\"line.product_uom_qty\\" t-options=\\"{'min_precision': 0}\\"/>\\n                                                <span t-field=\\"line.product_uom_id\\"/>\\n                                            </div>\\n                                        </td>\\n                                        <td t-if=\\"display_discount\\" name=\\"td_product_discount\\" class=\\"text-end d-none d-sm-table-cell\\">\\n                                            <t t-if=\\"not collapse_prices\\">\\n                                                <!-- ! Always check collapse_prices separately; keep\\n                                                discount condition below for XPath -->\\n                                                <span t-if=\\"line.discount &gt; 0\\" class=\\"badge text-bg-success\\">\\n                                                    <t t-out=\\"((line.discount % 1) and '%s' or '%d') % line.discount\\"/>\\n                                                    % </span>\\n                                            </t>\\n                                        </td>\\n                                        <td name=\\"td_product_priceunit\\" class=\\"text-end d-none d-sm-table-cell\\">\\n                                            <t t-if=\\"not collapse_prices\\">\\n                                                <span t-if=\\"line.discount &gt;= 0\\" t-field=\\"line.price_unit\\" t-att-style=\\"line.discount and 'text-decoration: line-through' or None\\" t-att-class=\\"(line.discount and 'text-muted' or '')\\" t-options=\\"{'widget': 'monetary', 'display_currency': line.currency_id}\\"/>\\n                                                <span t-if=\\"line.discount\\" class=\\"ms-2\\">\\n                                                    <t t-out=\\"line._get_discounted_price()\\" t-options=\\"{'widget': 'monetary', 'display_currency': line.currency_id}\\"/>\\n                                                </span>\\n                                            </t>\\n                                        </td>\\n                                        <td t-if=\\"display_taxes\\" name=\\"td_product_taxes\\" class=\\"text-end d-none d-md-table-cell\\">\\n                                            <t t-if=\\"not collapse_prices\\">\\n                                                <t t-foreach=\\"line.tax_ids\\" t-as=\\"tax\\">\\n                                                    <span class=\\"badge text-bg-secondary me-1\\" t-out=\\"tax.name\\"/>\\n                                                </t>\\n                                            </t>\\n                                        </td>\\n                                        <td name=\\"td_product_subtotal\\" class=\\"text-end\\">\\n                                            <t t-if=\\"not line.is_downpayment and not collapse_prices\\">\\n                                                <span t-if=\\"price_field == 'price_subtotal'\\" t-field=\\"line.price_subtotal\\"/>\\n                                                <span t-else=\\"\\" t-field=\\"line.price_total\\"/>\\n                                            </t>\\n                                        </td>\\n                                    </tr>\\n                                </t>\\n                                <t t-else=\\"\\">\\n                                    <!-- Displaying the section inner content, grouped by taxes -->\\n                                    <tr t-foreach=\\"line._get_grouped_section_summary(display_taxes)\\" t-as=\\"section_line\\" name=\\"tr_section_group\\">\\n                                        <td t-if=\\"line_counter\\" name=\\"td_section_group_line_no\\" class=\\"text-start\\">\\n                                            <span t-out=\\"line_counter\\"/>\\n                                            <t t-set=\\"line_counter\\" t-value=\\"line_counter + 1\\"/>\\n                                        </td>\\n                                        <td name=\\"td_section_group_name\\" t-att-style=\\"padding_style\\">\\n                                            <span t-field=\\"line.label\\">\\n                                                Section Summary\\n                                            </span>\\n                                        </td>\\n                                        <td name=\\"td_section_group_quantity\\" class=\\"text-end text-nowrap\\">\\n                                            <span t-field=\\"line.section_qty\\" t-options=\\"{'min_precision': 0}\\"/>\\n                                            <span t-field=\\"line.section_uom_id\\"/>\\n                                        </td>\\n                                        <td t-if=\\"display_discount\\" name=\\"td_section_group_discount\\" class=\\"d-none d-sm-table-cell\\"/>\\n                                        <td name=\\"td_section_group_priceunit\\" class=\\"d-none d-sm-table-cell text-end text-nowrap\\">\\n                                            <span t-if=\\"show_section_total\\" t-out=\\"section_line['price_subtotal']/line.section_qty\\" t-options=\\"{'widget': 'monetary', 'display_currency': sale_order.currency_id}\\"/>\\n                                        </td>\\n                                        <td t-if=\\"display_taxes\\" name=\\"td_section_group_taxes\\" class=\\"d-none d-md-table-cell text-end\\">\\n                                            <t t-if=\\"show_section_total\\">\\n                                                <t t-foreach=\\"section_line['tax_names']\\" t-as=\\"tax_name\\">\\n                                                    <span class=\\"badge text-bg-secondary me-1\\" t-out=\\"tax_name\\"/>\\n                                                </t>\\n                                            </t>\\n                                        </td>\\n                                        <td name=\\"td_section_group_total\\" class=\\"text-end o_price_total\\">\\n                                            <span t-if=\\"show_section_total\\" name=\\"price_subtotal_section_grouped\\" t-out=\\"section_line[price_field]\\" t-options=\\"{'widget': 'monetary', 'display_currency': sale_order.currency_id}\\">\\n                                                31.05\\n                                            </span>\\n                                        </td>\\n                                    </tr>\\n                                </t>\\n                            </t>\\n                        </tbody>\\n                    </table>\\n                </div>\\n\\n                <div id=\\"total\\" name=\\"total\\" class=\\"mb-0 mb-lg-5\\" style=\\"page-break-inside: avoid;\\">\\n                    <div class=\\"col-xs-7 col-md-5 ms-auto\\">\\n                        <t t-call=\\"sale.sale_order_portal_content_totals_table\\"/>\\n                    </div>\\n                </div>\\n\\n                <div t-if=\\"not is_html_empty(sale_order.note) or sale_order.payment_term_id\\" id=\\"payment_terms\\" class=\\"px-3 px-lg-2 my-3\\">\\n                    <div t-if=\\"not is_html_empty(sale_order.note)\\">\\n                        <span t-field=\\"sale_order.note\\"/>\\n                    </div>\\n                    <div t-if=\\"sale_order.payment_term_id\\">\\n                        <span t-field=\\"sale_order.payment_term_id.note\\"/>\\n                    </div>\\n                </div>\\n            </section>\\n\\n            <!-- Product Documents -->\\n            <section t-if=\\"product_documents\\" id=\\"product_documents\\" class=\\"p-3 p-lg-4 mt-4 rounded-3 border\\">\\n                <h4>Documents</h4>\\n                <div class=\\"d-flex flex-wrap gap-2\\">\\n                    <t t-foreach=\\"product_documents\\" t-as=\\"document_sudo\\">\\n                        <div class=\\"bg-light p-2 rounded\\">\\n                            <div class=\\"position-relative text-center\\">\\n                                <t t-set=\\"attachment_sudo\\" t-value=\\"document_sudo.ir_attachment_id\\"/>\\n                                <t t-set=\\"target\\" t-value=\\"attachment_sudo.type == 'url' and '_blank' or '_self'\\"/>\\n                                <a t-att-href=\\"sale_order.get_portal_url('/document/' + str(document_sudo.id))\\" t-att-target=\\"target\\" class=\\"d-flex gap-2\\">\\n                                    <div class=\\"o_image\\" t-att-title=\\"attachment_sudo.name\\" t-att-data-mimetype=\\"attachment_sudo.mimetype\\" t-attf-data-src=\\"/web/image/#{attachment_sudo.id}/100x80?access_token=#{attachment_sudo.access_token}\\"/>\\n                                    <div class=\\"o_portal_product_document align-self-center small\\" t-out=\\"attachment_sudo.name\\"/>\\n                                </a>\\n                            </div>\\n                        </div>\\n                    </t>\\n                </div>\\n            </section>\\n\\n            <!-- Customer Addresses -->\\n            <section id=\\"customer_info\\" class=\\"p-3 p-lg-4 mt-4 rounded-3 border\\">\\n                <div t-if=\\"sale_order.partner_shipping_id == sale_order.partner_invoice_id\\">\\n                    <!-- Single column when addresses are the same -->\\n                    <div class=\\"mb-2\\" id=\\"address_combined\\">\\n                        <span class=\\"badge text-bg-info\\">Delivery &amp; Billing</span>\\n                        <small t-if=\\"sale_order.partner_id == sale_order.partner_invoice_id == sale_order.env.user.partner_id\\">\\n                            <a class=\\"small\\" t-attf-href=\\"/my/account?redirect={{sale_order.get_portal_url()}}\\">\\n                                <i class=\\"oi oi-fw oi-filled\\" data-icon=\\"edit\\"/>\\n                            </a>\\n                        </small>\\n                    </div>\\n                    <div t-field=\\"sale_order.partner_invoice_id\\" t-options=\\"{'widget': 'contact', 'fields': ['name', 'address'], 'no_marker': True}\\"/>\\n                </div>\\n                <div t-else=\\"\\" class=\\"row\\">\\n                    <!-- Double column when addresses are different -->\\n                    <div class=\\"col-12 col-lg-6\\">\\n                        <div class=\\"mb-2\\" id=\\"address_billing\\">\\n                            <span class=\\"badge text-bg-info\\">Billing</span>\\n                            <small t-if=\\"sale_order.partner_id == sale_order.partner_invoice_id == sale_order.env.user.partner_id\\">\\n                                <a class=\\"small\\" t-attf-href=\\"/my/account?redirect={{sale_order.get_portal_url()}}\\">\\n                                    <i class=\\"oi oi-fw oi-filled\\" data-icon=\\"edit\\"/>\\n                                </a>\\n                            </small>\\n                        </div>\\n                        <div t-field=\\"sale_order.partner_invoice_id\\" t-options=\\"{'widget': 'contact', 'fields': ['name', 'address'], 'no_marker': True}\\"/>\\n                    </div>\\n                    <div class=\\"col-12 col-lg-6\\">\\n                        <div class=\\"mb-2\\" id=\\"address_delivery\\">\\n                            <span class=\\"badge text-bg-info\\">Delivery</span>\\n                        </div>\\n                        <div t-field=\\"sale_order.partner_shipping_id\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;name&quot;, &quot;address&quot;], &quot;no_marker&quot;: true}\\"/>\\n                    </div>\\n                </div>\\n            </section>\\n        </div>\\n    </t>", "es_ES": "<t name=\\"Sales Order Portal Content\\" t-name=\\"sale.sale_order_portal_content\\">\\n        <!-- Intro -->\\n        <div id=\\"introduction\\" class=\\"p-3 p-lg-4 bg-100 border rounded-top\\">\\n            <div class=\\"d-flex flex-column flex-lg-row\\" id=\\"intro_row\\">\\n                <div class=\\"d-flex flex-row flex-grow-1 flex-shrink-1 flex-basis-0 min-w-0\\">\\n                    <div class=\\"d-flex flex-column me-auto\\">\\n                        <small>\\n                            <span class=\\"text-muted\\">\\n                                <t t-if=\\"sale_order.state == 'sale'\\">Sales Order for</t>\\n                                <t t-else=\\"\\">Quotation for</t>\\n                            </span>\\n                            <b t-out=\\"sale_order.partner_id.name\\"/>\\n                        </small>\\n                        <h2 class=\\"mb-0\\">\\n                            <t t-out=\\"sale_order.name\\"/>\\n                        </h2>\\n                        <div class=\\"d-flex align-items-center gap-1 text-muted small flex-wrap\\">\\n                            <span t-field=\\"sale_order.date_order\\" t-options=\\"{&quot;widget&quot;: &quot;date&quot;}\\"/>\\n                            <t t-if=\\"sale_order.validity_date and sale_order.state in ['draft', 'sent']\\">\\n                                <span>·</span>\\n                                <span class=\\"text-warning-emphasis\\">Valid until <span t-field=\\"sale_order.validity_date\\" t-options=\\"{&quot;widget&quot;: &quot;date&quot;}\\"/></span>\\n                            </t>\\n                            <t t-if=\\"sale_order.client_order_ref\\">\\n                                <span>·</span>\\n                                <span>Ref: <span t-field=\\"sale_order.client_order_ref\\"/></span>\\n                            </t>\\n                            <t t-if=\\"sale_order.incoterm\\">\\n                                <span>·</span>\\n                                <span t-field=\\"sale_order.incoterm.code\\"/>\\n                                <span t-if=\\"sale_order.incoterm_location\\" t-field=\\"sale_order.incoterm_location\\"/>\\n                            </t>\\n                        </div>\\n                    </div>\\n                    <div class=\\"d-inline-block d-lg-none\\">\\n                        <a class=\\"btn btn-secondary flex-grow-1 o_print_btn o_portal_invoice_print\\" t-att-href=\\"sale_order.get_portal_url(report_type='pdf')\\" title=\\"Descargar\\" role=\\"button\\" target=\\"_blank\\">\\n                            <i class=\\"oi\\" data-icon=\\"download\\"/>\\n                        </a>\\n                    </div>\\n                </div>\\n                <div class=\\"d-flex flex-column align-items-end flex-grow-1 flex-shrink-1 flex-basis-0 min-w-0\\" id=\\"transaction_info\\">\\n                    <div t-if=\\"sale_order.get_portal_last_transaction() and not invoices and sale_order.state in ('sent', 'sale') and portal_confirmation == 'pay' and not success and not error\\" t-att-data-order-id=\\"sale_order.id\\">\\n                        <t t-if=\\"sale_order.transaction_ids\\">\\n                            <t t-call=\\"payment.state_header\\" tx=\\"sale_order.get_portal_last_transaction()\\"/>\\n                        </t>\\n                    </div>\\n                </div>\\n            </div>\\n            <hr t-if=\\"has_info_cards\\" class=\\"my-3 my-lg-4 mx-n3 mx-lg-n4\\"/>\\n            <div t-if=\\"has_info_cards\\" id=\\"informations\\" class=\\"d-flex flex-column flex-lg-row gap-4 pt-2\\"/>\\n        </div>\\n        <div id=\\"content\\">\\n\\n            <section id=\\"details\\" class=\\"p-0 p-lg-3 pt-lg-0 rounded-bottom border-start border-end border-bottom\\" style=\\"page-break-inside: auto;\\">\\n                <t t-set=\\"lines_to_report\\" t-value=\\"sale_order._get_order_lines_to_report()\\"/>\\n                <t t-set=\\"display_discount\\" t-value=\\"any(line.discount &gt; 0 for line in lines_to_report)\\"/>\\n                <t t-set=\\"hide_taxes_details\\" t-value=\\"False\\"/>\\n                <t t-set=\\"display_taxes\\" t-value=\\"not hide_taxes_details and any(line._has_taxes() for line in lines_to_report)\\"/>\\n                <t t-if=\\"sale_order.company_id.show_sol_numbers\\" t-set=\\"line_counter\\" t-value=\\"1\\"/>\\n                <!-- ===== MOBILE VIEW ===== -->\\n                    <div class=\\"d-lg-none\\">\\n                        <t t-set=\\"current_section_m\\" t-value=\\"None\\"/>\\n                        <t t-set=\\"current_subsection_m\\" t-value=\\"None\\"/>\\n                        <t t-set=\\"collapse_prices_m\\" t-value=\\"False\\"/>\\n                        <t t-set=\\"price_field_m\\" t-value=\\"'price_total' if hide_taxes_details else 'price_subtotal'\\"/>\\n\\n                        <t t-foreach=\\"lines_to_report\\" t-as=\\"line\\">\\n                            <t t-set=\\"is_note_m\\" t-value=\\"line.display_type == 'line_note'\\"/>\\n                            <t t-set=\\"is_section_m\\" t-value=\\"line.display_type == 'line_section'\\"/>\\n                            <t t-set=\\"is_subsection_m\\" t-value=\\"line.display_type == 'line_subsection'\\"/>\\n                            <t t-set=\\"is_combo_m\\" t-value=\\"line.product_type == 'combo'\\"/>\\n\\n                            <t t-if=\\"is_section_m\\">\\n                                <t t-set=\\"current_section_m\\" t-value=\\"line\\"/>\\n                                <t t-set=\\"current_subsection_m\\" t-value=\\"None\\"/>\\n                                <t t-set=\\"collapse_prices_m\\" t-value=\\"line.collapse_prices\\"/>\\n                            </t>\\n                            <t t-elif=\\"is_subsection_m\\">\\n                                <t t-set=\\"current_subsection_m\\" t-value=\\"line\\"/>\\n                                <t t-set=\\"collapse_prices_m\\" t-value=\\"current_section_m.collapse_prices or line.collapse_prices\\"/>\\n                            </t>\\n\\n                            <t t-if=\\"not line.collapse_composition\\">\\n                                <!-- Section / Subsection header -->\\n                                <div t-if=\\"is_section_m or is_subsection_m\\" t-attf-class=\\"d-flex justify-content-between align-items-center py-2 px-3 fw-bold border-bottom {{ 'bg-200' if is_section_m else 'bg-100' }}\\">\\n                                    <span t-field=\\"line.label\\"/>\\n                                    <span t-if=\\"is_section_m or not line.parent_id.collapse_prices\\" class=\\"text-nowrap ms-2\\" t-out=\\"line._get_section_totals(price_field_m)\\" t-options=\\"{'widget': 'monetary', 'display_currency': sale_order.currency_id}\\"/>\\n                                </div>\\n\\n                                <!-- Note -->\\n                                <div t-elif=\\"is_note_m\\" class=\\"fst-italic py-2 px-3 border-bottom text-muted small\\">\\n                                    <span t-field=\\"line.label\\"/>\\n                                </div>\\n\\n                                <!-- Combo header -->\\n                                <div t-elif=\\"is_combo_m\\" class=\\"d-flex justify-content-between align-items-start py-3 px-3 border-bottom fw-bold\\">\\n                                    <div>\\n                                        <span t-field=\\"line.label\\"/>\\n                                        <div class=\\"fw-normal text-muted small mt-1\\">\\n                                            <span t-field=\\"line.product_uom_qty\\" t-options=\\"{'min_precision': 0}\\"/>\\n                                            <span class=\\"ms-1\\" t-field=\\"line.product_uom_id\\"/>\\n                                        </div>\\n                                    </div>\\n                                    <span t-if=\\"not collapse_prices_m\\" class=\\"text-nowrap ms-3\\" t-out=\\"line._get_combo_totals(price_field_m)\\" t-options=\\"{'widget': 'monetary', 'display_currency': sale_order.currency_id}\\"/>\\n                                </div>\\n\\n                                <!-- Regular product line -->\\n                                <div t-else=\\"\\" class=\\"py-3 px-3 border-bottom\\">\\n                                    <!-- Name + subtotal -->\\n                                    <div class=\\"d-flex justify-content-between align-items-start gap-2\\">\\n                                        <t t-set=\\"label_parts_m\\" t-value=\\"(line.label or '').split('\\\\n', 1)\\"/>\\n                                        <t t-set=\\"name_title_m\\" t-value=\\"label_parts_m[0][label_parts_m[0].find(']') + 2:] if label_parts_m[0].startswith('[') else label_parts_m[0]\\"/>\\n                                        <span t-out=\\"name_title_m\\"/>\\n                                        <t t-if=\\"not line.is_downpayment and not collapse_prices_m\\">\\n                                            <span t-if=\\"price_field_m == 'price_subtotal'\\" class=\\"text-nowrap\\" t-field=\\"line.price_subtotal\\"/>\\n                                            <span t-else=\\"\\" class=\\"text-nowrap\\" t-field=\\"line.price_total\\"/>\\n                                        </t>\\n                                    </div>\\n                                    <!-- Optional description -->\\n                                    <span t-if=\\"len(label_parts_m) &gt; 1\\" class=\\"o_sale_portal_line_description d-block text-muted small mt-1\\" t-out=\\"label_parts_m[1]\\"/>\\n                                    <t t-if=\\"not collapse_prices_m\\">\\n                                        <!-- Qty × price (with strikethrough + discounted price if rebate) -->\\n                                        <div class=\\"d-flex flex-wrap align-items-baseline gap-1 mt-1 small text-muted\\">\\n                                            <span name=\\"span_qty_uom\\">\\n                                                <span t-field=\\"line.product_uom_qty\\" t-options=\\"{'min_precision': 0}\\"/>\\n                                                <span class=\\"ms-1\\" t-field=\\"line.product_uom_id\\"/>\\n                                            </span>\\n                                            <t t-if=\\"line.price_unit\\">\\n                                                <span>×</span>\\n                                                <span t-if=\\"line.discount\\" t-out=\\"line._get_discounted_price()\\" t-options=\\"{'widget': 'monetary', 'display_currency': line.currency_id}\\"/>\\n                                                <span t-if=\\"line.discount &gt;= 0\\" t-field=\\"line.price_unit\\" t-att-class=\\"line.discount &gt; 0 and 'text-decoration-line-through opacity-50' or ''\\" t-options=\\"{'widget': 'monetary', 'display_currency': line.currency_id}\\"/>\\n                                                <t t-if=\\"line.discount &gt; 0\\">\\n                                                    <span class=\\"small text-success fw-medium\\">\\n                                                        (−<t t-out=\\"((line.discount % 1) and '%s' or '%d') % line.discount\\"/>%)\\n                                                    </span>\\n                                                </t>\\n                                            </t>\\n                                        </div>\\n                                        <!-- Taxes as plain text -->\\n                                        <div t-if=\\"display_taxes and line.tax_ids\\" class=\\"mt-1 small text-muted\\">\\n                                            <span>Tax:</span>\\n                                            <span t-out=\\"', '.join(map(lambda x: (x.name), line.tax_ids))\\"/>\\n                                        </div>\\n                                    </t>\\n                                </div>\\n                            </t>\\n                            <t t-else=\\"\\">\\n                                <!-- Collapsed composition: grouped section summary -->\\n                                <t t-foreach=\\"line._get_grouped_section_summary(display_taxes)\\" t-as=\\"section_line\\">\\n                                    <div class=\\"py-3 px-3 border-bottom\\">\\n                                        <div class=\\"d-flex justify-content-between align-items-start gap-2\\">\\n                                            <span t-field=\\"line.label\\"/>\\n                                            <span t-out=\\"section_line[price_field_m]\\" t-options=\\"{'widget': 'monetary', 'display_currency': sale_order.currency_id}\\" class=\\"text-nowrap\\"/>\\n                                        </div>\\n                                        <div class=\\"d-flex flex-wrap align-items-center gap-2 mt-1 small text-muted\\">\\n                                            <span t-field=\\"line.section_qty\\" t-options=\\"{'min_precision': 0}\\"/>\\n                                            <span t-field=\\"line.section_uom_id\\"/>\\n                                            <span>×</span>\\n                                            <span t-out=\\"section_line['price_subtotal']/line.section_qty\\" t-options=\\"{'widget': 'monetary', 'display_currency': sale_order.currency_id}\\"/>\\n                                        </div>\\n                                        <div t-if=\\"display_taxes and section_line.get('tax_labels')\\" class=\\"mt-1 small text-muted\\">\\n                                            <span>Tax:</span>\\n                                            <t t-foreach=\\"section_line['tax_labels']\\" t-as=\\"tax_label\\">\\n                                                <t t-if=\\"not tax_label_first\\">, </t>\\n                                                <span t-out=\\"tax_label\\"/>\\n                                            </t>\\n                                        </div>\\n                                    </div>\\n                                </t>\\n                            </t>\\n                        </t>\\n                    </div>\\n\\n                <!-- ===== DESKTOP TABLE ===== -->\\n                <div name=\\"sol_table\\" class=\\"table-responsive d-none d-lg-block\\">\\n                    <table t-att-data-order-id=\\"sale_order.id\\" t-att-data-token=\\"sale_order.access_token\\" class=\\"table\\" id=\\"sales_order_table\\">\\n                        <thead class=\\"d-none d-lg-contents\\">\\n                            <tr>\\n                                <th t-if=\\"line_counter\\" id=\\"line_number_header\\" class=\\"text-start\\" style=\\"width: 1%; white-space: nowrap;\\">#</th>\\n                                <th class=\\"text-start\\" id=\\"product_name_header\\" aria-label=\\"Descripción\\"/>\\n                                <th class=\\"text-end\\" id=\\"product_qty_header\\" aria-label=\\"Cantidad\\"/>\\n                                <th t-if=\\"display_discount\\" class=\\"text-end d-none d-sm-table-cell\\" id=\\"product_discount_header\\">\\n                                    <span>Discount</span>\\n                                </th>\\n                                <th class=\\"text-end text-nowrap d-none d-sm-table-cell\\" id=\\"product_unit_price_header\\">\\n                                    Precio unitario\\n                                </th>\\n                                <th t-if=\\"display_taxes\\" class=\\"text-end d-none d-md-table-cell\\" id=\\"taxes_header\\">\\n                                    <span>Impuestos</span>\\n                                </th>\\n                                <th class=\\"text-end\\" id=\\"subtotal_header\\">\\n                                    <span>Importe</span>\\n                                </th>\\n                            </tr>\\n                        </thead>\\n                        <tbody class=\\"sale_tbody\\">\\n\\n                            <t t-set=\\"current_section\\" t-value=\\"None\\"/>\\n                            <t t-set=\\"current_subsection\\" t-value=\\"None\\"/>\\n                            <t t-set=\\"price_field\\" t-value=\\"'price_total' if (hide_taxes_details or sale_order.company_price_include == 'tax_included') else 'price_subtotal'\\"/>\\n                            <t t-set=\\"default_section_uom\\" t-value=\\"sale_order.env.ref('uom.product_uom_unit')\\"/>\\n\\n                            <t t-foreach=\\"lines_to_report\\" t-as=\\"line\\">\\n\\n                                <t t-set=\\"is_note\\" t-value=\\"line.display_type == 'line_note'\\"/>\\n                                <t t-set=\\"is_section\\" t-value=\\"line.display_type == 'line_section'\\"/>\\n                                <t t-set=\\"is_subsection\\" t-value=\\"line.display_type == 'line_subsection'\\"/>\\n                                <t t-set=\\"is_combo\\" t-value=\\"line.product_type == 'combo'\\"/>\\n\\n                                <t t-if=\\"is_section\\">\\n                                    <t t-set=\\"current_section\\" t-value=\\"line\\"/>\\n                                    <t t-set=\\"current_subsection\\" t-value=\\"None\\"/>\\n                                    <t t-set=\\"line_padding\\" t-value=\\"0\\"/>\\n                                    <t t-set=\\"collapse_prices\\" t-value=\\"line.collapse_prices\\"/>\\n                                </t>\\n                                <t t-elif=\\"is_subsection\\">\\n                                    <t t-set=\\"current_subsection\\" t-value=\\"line\\"/>\\n                                    <t t-set=\\"line_padding\\" t-value=\\"2\\"/>\\n                                    <t t-set=\\"collapse_prices\\" t-value=\\"current_section.collapse_prices or line.collapse_prices\\"/>\\n                                </t>\\n                                <t t-else=\\"\\">\\n                                    <t t-set=\\"line_padding\\" t-value=\\"3 if current_subsection else (2 if current_section else 0)\\"/>\\n                                </t>\\n\\n                                <t t-if=\\"line.combo_item_id\\">\\n                                    <t t-set=\\"line_padding\\" t-value=\\"line_padding + 1\\"/>\\n                                </t>\\n\\n                                <t t-set=\\"padding_style\\" t-value=\\"(                                         line_padding                                         and ('padding-left:' + str(line_padding * 8) + 'px')                                         or 'padding-left: 4px'                                     )\\"/>\\n                                <t t-set=\\"show_section_total\\" t-value=\\"is_section or not line.parent_id.collapse_prices\\"/>\\n\\n                                <t t-if=\\"not line.collapse_composition\\">\\n                                    <tr t-if=\\"is_section or is_subsection\\" name=\\"tr_section\\" t-attf-class=\\"{{'o_line_section bg-200' if is_section else 'o_line_subsection bg-100'}} fw-bold\\">\\n                                        <t t-set=\\"show_section_total\\" t-value=\\"(                                                 (                                                     is_section                                                     or not line.parent_id.collapse_prices                                                 )                                                 and not line.is_downpayment                                             )\\"/>\\n                                        <t t-set=\\"section_name_colspan\\" t-value=\\"3 + (1 if display_discount else 0) + (1 if display_taxes else 0)\\"/>\\n                                        <t t-if=\\"not show_section_total\\">\\n                                            <t t-set=\\"section_name_colspan\\" t-value=\\"99\\"/>\\n                                        </t>\\n                                        <t t-set=\\"show_section_qty_uom\\" t-value=\\"line.section_qty != 1 or (line.section_uom_id and line.section_uom_id != default_section_uom)\\"/>\\n                                        <!-- Some columns (e.g. Discount and Unit Price)\\n                                        are not displayed on smaller viewports -->\\n                                        <td t-if=\\"line_counter\\" name=\\"td_section_line_no\\" class=\\"text-start\\">\\n                                            <span t-out=\\"line_counter\\"/>\\n                                            <t t-set=\\"line_counter\\" t-value=\\"line_counter + 1\\"/>\\n                                        </td>\\n                                        <td name=\\"td_section_name_xs\\" t-att-colspan=\\"section_name_colspan - 1 - (1 if display_discount else 0) - (1 if display_taxes else 0)\\" class=\\"d-sm-none\\" t-att-style=\\"padding_style\\">\\n                                            <span t-field=\\"line.label\\"/>\\n                                            <span t-if=\\"show_section_qty_uom\\" class=\\"text-muted fw-normal ms-1\\">(<span t-field=\\"line.section_qty\\" t-options=\\"{'widget': 'float', 'min_precision': 0}\\"/> <span t-field=\\"line.section_uom_id\\"/>)</span>\\n                                        </td>\\n                                        <td name=\\"td_section_name_sm\\" t-att-colspan=\\"section_name_colspan - (1 if display_taxes else 0)\\" class=\\"d-none d-sm-table-cell d-md-none\\" t-att-style=\\"padding_style\\">\\n                                            <span t-field=\\"line.label\\"/>\\n                                            <span t-if=\\"show_section_qty_uom\\" class=\\"text-muted fw-normal ms-1\\">(<span t-field=\\"line.section_qty\\" t-options=\\"{'widget': 'float', 'min_precision': 0}\\"/> <span t-field=\\"line.section_uom_id\\"/>)</span>\\n                                        </td>\\n                                        <td name=\\"td_section_name\\" t-att-colspan=\\"section_name_colspan\\" class=\\"d-none d-md-table-cell\\" t-att-style=\\"padding_style\\">\\n                                            <span t-field=\\"line.label\\"/>\\n                                            <span t-if=\\"show_section_qty_uom\\" class=\\"text-muted fw-normal ms-1\\">(<span t-field=\\"line.section_qty\\" t-options=\\"{'widget': 'float', 'min_precision': 0}\\"/> <span t-field=\\"line.section_uom_id\\"/>)</span>\\n                                        </td>\\n                                        <td t-if=\\"show_section_total\\" name=\\"td_section_price\\" class=\\"text-end o_price_total\\">\\n                                            <span name=\\"price_subtotal_section\\" t-out=\\"line._get_section_totals(price_field)\\" class=\\"text-nowrap\\" t-options=\\"{'widget': 'monetary', 'display_currency': sale_order.currency_id}\\"/>\\n                                        </td>\\n                                    </tr>\\n                                    <tr t-elif=\\"is_note\\" name=\\"tr_note\\" class=\\"fst-italic o_line_note\\">\\n                                        <td t-if=\\"line_counter\\" name=\\"td_note_line_no\\" class=\\"text-start fst-normal\\">\\n                                            <span t-out=\\"line_counter\\"/>\\n                                            <t t-set=\\"line_counter\\" t-value=\\"line_counter + 1\\"/>\\n                                        </td>\\n                                        <td name=\\"td_note_name\\" colspan=\\"99\\" t-att-style=\\"padding_style\\">\\n                                            <span t-field=\\"line.label\\"/>\\n                                        </td>\\n                                    </tr>\\n                                    <tr t-elif=\\"is_combo\\" name=\\"tr_combo\\" class=\\"fw-bold\\">\\n                                        <td t-if=\\"line_counter\\" name=\\"td_combo_line_no\\" class=\\"text-start\\">\\n                                            <span t-out=\\"line_counter\\"/>\\n                                            <t t-set=\\"line_counter\\" t-value=\\"line_counter + 1\\"/>\\n                                        </td>\\n                                        <td name=\\"td_combo_name\\" t-att-style=\\"padding_style\\">\\n                                            <span t-field=\\"line.label\\">Producto combinado</span>\\n                                        </td>\\n                                        <td name=\\"td_combo_quantity\\" class=\\"text-end\\">\\n                                            <div id=\\"quote_qty\\">\\n                                                <span t-field=\\"line.product_uom_qty\\" t-options=\\"{'min_precision': 0}\\"/>\\n                                                <span t-field=\\"line.product_uom_id\\"/>\\n                                            </div>\\n                                        </td>\\n                                        <td name=\\"td_combo_subtotal\\" class=\\"text-end\\" t-att-colspan=\\"2 + (1 if display_discount else 0) + (1 if display_taxes else 0)\\">\\n                                            <span t-if=\\"not collapse_prices\\" name=\\"price_subtotal_combo\\" t-out=\\"line._get_combo_totals(price_field)\\" class=\\"text-nowrap\\" t-options=\\"{'widget': 'monetary', 'display_currency': sale_order.currency_id}\\">\\n                                                27.00\\n                                            </span>\\n                                        </td>\\n                                    </tr>\\n                                    <tr t-else=\\"\\" name=\\"tr_product\\">\\n                                        <td t-if=\\"line_counter\\" name=\\"td_product_line_no\\" class=\\"text-start\\">\\n                                            <span t-out=\\"line_counter\\"/>\\n                                            <t t-set=\\"line_counter\\" t-value=\\"line_counter + 1\\"/>\\n                                        </td>\\n                                        <td name=\\"td_product_name\\" t-att-style=\\"padding_style\\">\\n                                            <div class=\\"d-flex flex-row align-items-center\\">\\n                                                <img t-if=\\"sale_order.company_id.display_product_images_on_so and line.product_id.image_128\\" t-att-src=\\"image_data_uri(line.product_id.image_128)\\" t-att-alt=\\"line.product_id.display_name\\" class=\\"o_sale_portal_product_image d-none d-lg-inline me-2 rounded object-fit-cover\\"/>\\n                                                <div>\\n                                                    <t t-set=\\"label_parts\\" t-value=\\"(line.label or '').split('\\\\n', 1)\\"/>\\n                                                    <span name=\\"span_product_name\\" t-out=\\"label_parts[0]\\"/>\\n                                                    <span t-if=\\"len(label_parts) &gt; 1\\" class=\\"o_sale_portal_line_description d-block text-muted small\\" t-out=\\"label_parts[1]\\"/>\\n                                                </div>\\n                                            </div>\\n                                        </td>\\n                                        <td name=\\"td_product_quantity\\" class=\\"text-end\\">\\n                                            <div id=\\"quote_qty\\">\\n                                                <span t-field=\\"line.product_uom_qty\\" t-options=\\"{'min_precision': 0}\\"/>\\n                                                <span t-field=\\"line.product_uom_id\\"/>\\n                                            </div>\\n                                        </td>\\n                                        <td t-if=\\"display_discount\\" name=\\"td_product_discount\\" class=\\"text-end d-none d-sm-table-cell\\">\\n                                            <t t-if=\\"not collapse_prices\\">\\n                                                <!-- ! Always check collapse_prices separately; keep\\n                                                discount condition below for XPath -->\\n                                                <span t-if=\\"line.discount &gt; 0\\" class=\\"badge text-bg-success\\">\\n                                                    <t t-out=\\"((line.discount % 1) and '%s' or '%d') % line.discount\\"/>\\n                                                    % </span>\\n                                            </t>\\n                                        </td>\\n                                        <td name=\\"td_product_priceunit\\" class=\\"text-end d-none d-sm-table-cell\\">\\n                                            <t t-if=\\"not collapse_prices\\">\\n                                                <span t-if=\\"line.discount &gt;= 0\\" t-field=\\"line.price_unit\\" t-att-style=\\"line.discount and 'text-decoration: line-through' or None\\" t-att-class=\\"(line.discount and 'text-muted' or '')\\" t-options=\\"{'widget': 'monetary', 'display_currency': line.currency_id}\\"/>\\n                                                <span t-if=\\"line.discount\\" class=\\"ms-2\\">\\n                                                    <t t-out=\\"line._get_discounted_price()\\" t-options=\\"{'widget': 'monetary', 'display_currency': line.currency_id}\\"/>\\n                                                </span>\\n                                            </t>\\n                                        </td>\\n                                        <td t-if=\\"display_taxes\\" name=\\"td_product_taxes\\" class=\\"text-end d-none d-md-table-cell\\">\\n                                            <t t-if=\\"not collapse_prices\\">\\n                                                <t t-foreach=\\"line.tax_ids\\" t-as=\\"tax\\">\\n                                                    <span class=\\"badge text-bg-secondary me-1\\" t-out=\\"tax.name\\"/>\\n                                                </t>\\n                                            </t>\\n                                        </td>\\n                                        <td name=\\"td_product_subtotal\\" class=\\"text-end\\">\\n                                            <t t-if=\\"not line.is_downpayment and not collapse_prices\\">\\n                                                <span t-if=\\"price_field == 'price_subtotal'\\" t-field=\\"line.price_subtotal\\"/>\\n                                                <span t-else=\\"\\" t-field=\\"line.price_total\\"/>\\n                                            </t>\\n                                        </td>\\n                                    </tr>\\n                                </t>\\n                                <t t-else=\\"\\">\\n                                    <!-- Displaying the section inner content, grouped by taxes -->\\n                                    <tr t-foreach=\\"line._get_grouped_section_summary(display_taxes)\\" t-as=\\"section_line\\" name=\\"tr_section_group\\">\\n                                        <td t-if=\\"line_counter\\" name=\\"td_section_group_line_no\\" class=\\"text-start\\">\\n                                            <span t-out=\\"line_counter\\"/>\\n                                            <t t-set=\\"line_counter\\" t-value=\\"line_counter + 1\\"/>\\n                                        </td>\\n                                        <td name=\\"td_section_group_name\\" t-att-style=\\"padding_style\\">\\n                                            <span t-field=\\"line.label\\">\\n                                                Resumen de la sección\\n                                            </span>\\n                                        </td>\\n                                        <td name=\\"td_section_group_quantity\\" class=\\"text-end text-nowrap\\">\\n                                            <span t-field=\\"line.section_qty\\" t-options=\\"{'min_precision': 0}\\"/>\\n                                            <span t-field=\\"line.section_uom_id\\"/>\\n                                        </td>\\n                                        <td t-if=\\"display_discount\\" name=\\"td_section_group_discount\\" class=\\"d-none d-sm-table-cell\\"/>\\n                                        <td name=\\"td_section_group_priceunit\\" class=\\"d-none d-sm-table-cell text-end text-nowrap\\">\\n                                            <span t-if=\\"show_section_total\\" t-out=\\"section_line['price_subtotal']/line.section_qty\\" t-options=\\"{'widget': 'monetary', 'display_currency': sale_order.currency_id}\\"/>\\n                                        </td>\\n                                        <td t-if=\\"display_taxes\\" name=\\"td_section_group_taxes\\" class=\\"d-none d-md-table-cell text-end\\">\\n                                            <t t-if=\\"show_section_total\\">\\n                                                <t t-foreach=\\"section_line['tax_names']\\" t-as=\\"tax_name\\">\\n                                                    <span class=\\"badge text-bg-secondary me-1\\" t-out=\\"tax_name\\"/>\\n                                                </t>\\n                                            </t>\\n                                        </td>\\n                                        <td name=\\"td_section_group_total\\" class=\\"text-end o_price_total\\">\\n                                            <span t-if=\\"show_section_total\\" name=\\"price_subtotal_section_grouped\\" t-out=\\"section_line[price_field]\\" t-options=\\"{'widget': 'monetary', 'display_currency': sale_order.currency_id}\\">\\n                                                31.05\\n                                            </span>\\n                                        </td>\\n                                    </tr>\\n                                </t>\\n                            </t>\\n                        </tbody>\\n                    </table>\\n                </div>\\n\\n                <div id=\\"total\\" name=\\"total\\" class=\\"mb-0 mb-lg-5\\" style=\\"page-break-inside: avoid;\\">\\n                    <div class=\\"col-xs-7 col-md-5 ms-auto\\">\\n                        <t t-call=\\"sale.sale_order_portal_content_totals_table\\"/>\\n                    </div>\\n                </div>\\n\\n                <div t-if=\\"not is_html_empty(sale_order.note) or sale_order.payment_term_id\\" id=\\"payment_terms\\" class=\\"px-3 px-lg-2 my-3\\">\\n                    <div t-if=\\"not is_html_empty(sale_order.note)\\">\\n                        <span t-field=\\"sale_order.note\\"/>\\n                    </div>\\n                    <div t-if=\\"sale_order.payment_term_id\\">\\n                        <span t-field=\\"sale_order.payment_term_id.note\\"/>\\n                    </div>\\n                </div>\\n            </section>\\n\\n            <!-- Product Documents -->\\n            <section t-if=\\"product_documents\\" id=\\"product_documents\\" class=\\"p-3 p-lg-4 mt-4 rounded-3 border\\">\\n                <h4>Documentos</h4>\\n                <div class=\\"d-flex flex-wrap gap-2\\">\\n                    <t t-foreach=\\"product_documents\\" t-as=\\"document_sudo\\">\\n                        <div class=\\"bg-light p-2 rounded\\">\\n                            <div class=\\"position-relative text-center\\">\\n                                <t t-set=\\"attachment_sudo\\" t-value=\\"document_sudo.ir_attachment_id\\"/>\\n                                <t t-set=\\"target\\" t-value=\\"attachment_sudo.type == 'url' and '_blank' or '_self'\\"/>\\n                                <a t-att-href=\\"sale_order.get_portal_url('/document/' + str(document_sudo.id))\\" t-att-target=\\"target\\" class=\\"d-flex gap-2\\">\\n                                    <div class=\\"o_image\\" t-att-title=\\"attachment_sudo.name\\" t-att-data-mimetype=\\"attachment_sudo.mimetype\\" t-attf-data-src=\\"/web/image/#{attachment_sudo.id}/100x80?access_token=#{attachment_sudo.access_token}\\"/>\\n                                    <div class=\\"o_portal_product_document align-self-center small\\" t-out=\\"attachment_sudo.name\\"/>\\n                                </a>\\n                            </div>\\n                        </div>\\n                    </t>\\n                </div>\\n            </section>\\n\\n            <!-- Customer Addresses -->\\n            <section id=\\"customer_info\\" class=\\"p-3 p-lg-4 mt-4 rounded-3 border\\">\\n                <div t-if=\\"sale_order.partner_shipping_id == sale_order.partner_invoice_id\\">\\n                    <!-- Single column when addresses are the same -->\\n                    <div class=\\"mb-2\\" id=\\"address_combined\\">\\n                        <span class=\\"badge text-bg-info\\">Delivery &amp; Billing</span>\\n                        <small t-if=\\"sale_order.partner_id == sale_order.partner_invoice_id == sale_order.env.user.partner_id\\">\\n                            <a class=\\"small\\" t-attf-href=\\"/my/account?redirect={{sale_order.get_portal_url()}}\\">\\n                                <i class=\\"oi oi-fw oi-filled\\" data-icon=\\"edit\\"/>\\n                            </a>\\n                        </small>\\n                    </div>\\n                    <div t-field=\\"sale_order.partner_invoice_id\\" t-options=\\"{'widget': 'contact', 'fields': ['name', 'address'], 'no_marker': True}\\"/>\\n                </div>\\n                <div t-else=\\"\\" class=\\"row\\">\\n                    <!-- Double column when addresses are different -->\\n                    <div class=\\"col-12 col-lg-6\\">\\n                        <div class=\\"mb-2\\" id=\\"address_billing\\">\\n                            <span class=\\"badge text-bg-info\\">Billing</span>\\n                            <small t-if=\\"sale_order.partner_id == sale_order.partner_invoice_id == sale_order.env.user.partner_id\\">\\n                                <a class=\\"small\\" t-attf-href=\\"/my/account?redirect={{sale_order.get_portal_url()}}\\">\\n                                    <i class=\\"oi oi-fw oi-filled\\" data-icon=\\"edit\\"/>\\n                                </a>\\n                            </small>\\n                        </div>\\n                        <div t-field=\\"sale_order.partner_invoice_id\\" t-options=\\"{'widget': 'contact', 'fields': ['name', 'address'], 'no_marker': True}\\"/>\\n                    </div>\\n                    <div class=\\"col-12 col-lg-6\\">\\n                        <div class=\\"mb-2\\" id=\\"address_delivery\\">\\n                            <span class=\\"badge text-bg-info\\">Delivery</span>\\n                        </div>\\n                        <div t-field=\\"sale_order.partner_shipping_id\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;name&quot;, &quot;address&quot;], &quot;no_marker&quot;: true}\\"/>\\n                    </div>\\n                </div>\\n            </section>\\n        </div>\\n    </t>"}	<?xml version="1.0"?>\n<t name="Sales Order Portal Content" t-name="sale.sale_order_portal_content">\n        <!-- Intro -->\n        <div id="introduction" class="p-3 p-lg-4 bg-100 border rounded-top">\n            <div class="d-flex flex-column flex-lg-row" id="intro_row">\n                <div class="d-flex flex-row flex-grow-1 flex-shrink-1 flex-basis-0 min-w-0">\n                    <div class="d-flex flex-column me-auto">\n                        <small>\n                            <span class="text-muted">\n                                <t t-if="sale_order.state == 'sale'">Sales Order for</t>\n                                <t t-else="">Quotation for</t>\n                            </span>\n                            <b t-out="sale_order.partner_id.name"/>\n                        </small>\n                        <h2 class="mb-0">\n                            <t t-out="sale_order.name"/>\n                        </h2>\n                        <div class="d-flex align-items-center gap-1 text-muted small flex-wrap">\n                            <span t-field="sale_order.date_order" t-options="{&quot;widget&quot;: &quot;date&quot;}"/>\n                            <t t-if="sale_order.validity_date and sale_order.state in ['draft', 'sent']">\n                                <span>·</span>\n                                <span class="text-warning-emphasis">Valid until <span t-field="sale_order.validity_date" t-options="{&quot;widget&quot;: &quot;date&quot;}"/></span>\n                            </t>\n                            <t t-if="sale_order.client_order_ref">\n                                <span>·</span>\n                                <span>Ref: <span t-field="sale_order.client_order_ref"/></span>\n                            </t>\n                            <t t-if="sale_order.incoterm">\n                                <span>·</span>\n                                <span t-field="sale_order.incoterm.code"/>\n                                <span t-if="sale_order.incoterm_location" t-field="sale_order.incoterm_location"/>\n                            </t>\n                        </div>\n                    </div>\n                    <div class="d-inline-block d-lg-none">\n                        <a class="btn btn-secondary flex-grow-1 o_print_btn o_portal_invoice_print" t-att-href="sale_order.get_portal_url(report_type='pdf')" title="Download" role="button" target="_blank">\n                            <i class="oi" data-icon="download"/>\n                        </a>\n                    </div>\n                </div>\n                <div class="d-flex flex-column align-items-end flex-grow-1 flex-shrink-1 flex-basis-0 min-w-0" id="transaction_info">\n                    <div t-if="sale_order.get_portal_last_transaction() and not invoices and sale_order.state in ('sent', 'sale') and portal_confirmation == 'pay' and not success and not error" t-att-data-order-id="sale_order.id">\n                        <t t-if="sale_order.transaction_ids">\n                            <t t-call="payment.state_header" tx="sale_order.get_portal_last_transaction()"/>\n                        </t>\n                    </div>\n                </div>\n            </div>\n            <hr t-if="has_info_cards" class="my-3 my-lg-4 mx-n3 mx-lg-n4"/>\n            <div t-if="has_info_cards" id="informations" class="d-flex flex-column flex-lg-row gap-4 pt-2"/>\n        </div>\n        <div id="content">\n\n            <section id="details" class="p-0 p-lg-3 pt-lg-0 rounded-bottom border-start border-end border-bottom" style="page-break-inside: auto;">\n                <t t-set="lines_to_report" t-value="sale_order._get_order_lines_to_report()"/>\n                <t t-set="display_discount" t-value="any(line.discount &gt; 0 for line in lines_to_report)"/>\n                <t t-set="hide_taxes_details" t-value="False"/>\n                <t t-set="display_taxes" t-value="not hide_taxes_details and any(line._has_taxes() for line in lines_to_report)"/>\n                <t t-if="sale_order.company_id.show_sol_numbers" t-set="line_counter" t-value="1"/>\n                <!-- ===== MOBILE VIEW ===== -->\n                    <div class="d-lg-none">\n                        <t t-set="current_section_m" t-value="None"/>\n                        <t t-set="current_subsection_m" t-value="None"/>\n                        <t t-set="collapse_prices_m" t-value="False"/>\n                        <t t-set="price_field_m" t-value="'price_total' if hide_taxes_details else 'price_subtotal'"/>\n\n                        <t t-foreach="lines_to_report" t-as="line">\n                            <t t-set="is_note_m" t-value="line.display_type == 'line_note'"/>\n                            <t t-set="is_section_m" t-value="line.display_type == 'line_section'"/>\n                            <t t-set="is_subsection_m" t-value="line.display_type == 'line_subsection'"/>\n                            <t t-set="is_combo_m" t-value="line.product_type == 'combo'"/>\n\n                            <t t-if="is_section_m">\n                                <t t-set="current_section_m" t-value="line"/>\n                                <t t-set="current_subsection_m" t-value="None"/>\n                                <t t-set="collapse_prices_m" t-value="line.collapse_prices"/>\n                            </t>\n                            <t t-elif="is_subsection_m">\n                                <t t-set="current_subsection_m" t-value="line"/>\n                                <t t-set="collapse_prices_m" t-value="current_section_m.collapse_prices or line.collapse_prices"/>\n                            </t>\n\n                            <t t-if="not line.collapse_composition">\n                                <!-- Section / Subsection header -->\n                                <div t-if="is_section_m or is_subsection_m" t-attf-class="d-flex justify-content-between align-items-center py-2 px-3 fw-bold border-bottom {{ 'bg-200' if is_section_m else 'bg-100' }}">\n                                    <span t-field="line.label"/>\n                                    <span t-if="is_section_m or not line.parent_id.collapse_prices" class="text-nowrap ms-2" t-out="line._get_section_totals(price_field_m)" t-options="{'widget': 'monetary', 'display_currency': sale_order.currency_id}"/>\n                                </div>\n\n                                <!-- Note -->\n                                <div t-elif="is_note_m" class="fst-italic py-2 px-3 border-bottom text-muted small">\n                                    <span t-field="line.label"/>\n                                </div>\n\n                                <!-- Combo header -->\n                                <div t-elif="is_combo_m" class="d-flex justify-content-between align-items-start py-3 px-3 border-bottom fw-bold">\n                                    <div>\n                                        <span t-field="line.label"/>\n                                        <div class="fw-normal text-muted small mt-1">\n                                            <span t-field="line.product_uom_qty" t-options="{'min_precision': 0}"/>\n                                            <span class="ms-1" t-field="line.product_uom_id"/>\n                                        </div>\n                                    </div>\n                                    <span t-if="not collapse_prices_m" class="text-nowrap ms-3" t-out="line._get_combo_totals(price_field_m)" t-options="{'widget': 'monetary', 'display_currency': sale_order.currency_id}"/>\n                                </div>\n\n                                <!-- Regular product line -->\n                                <div t-else="" class="py-3 px-3 border-bottom">\n                                    <!-- Name + subtotal -->\n                                    <div class="d-flex justify-content-between align-items-start gap-2">\n                                        <t t-set="label_parts_m" t-value="(line.label or '').split('\\n', 1)"/>\n                                        <t t-set="name_title_m" t-value="label_parts_m[0][label_parts_m[0].find(']') + 2:] if label_parts_m[0].startswith('[') else label_parts_m[0]"/>\n                                        <span t-out="name_title_m"/>\n                                        <t t-if="not line.is_downpayment and not collapse_prices_m">\n                                            <span t-if="price_field_m == 'price_subtotal'" class="text-nowrap" t-field="line.price_subtotal"/>\n                                            <span t-else="" class="text-nowrap" t-field="line.price_total"/>\n                                        </t>\n                                    </div>\n                                    <!-- Optional description -->\n                                    <span t-if="len(label_parts_m) &gt; 1" class="o_sale_portal_line_description d-block text-muted small mt-1" t-out="label_parts_m[1]"/>\n                                    <t t-if="not collapse_prices_m">\n                                        <!-- Qty × price (with strikethrough + discounted price if rebate) -->\n                                        <div class="d-flex flex-wrap align-items-baseline gap-1 mt-1 small text-muted">\n                                            <span name="span_qty_uom">\n                                                <span t-field="line.product_uom_qty" t-options="{'min_precision': 0}"/>\n                                                <span class="ms-1" t-field="line.product_uom_id"/>\n                                            </span>\n                                            <t t-if="line.price_unit">\n                                                <span>×</span>\n                                                <span t-if="line.discount" t-out="line._get_discounted_price()" t-options="{'widget': 'monetary', 'display_currency': line.currency_id}"/>\n                                                <span t-if="line.discount &gt;= 0" t-field="line.price_unit" t-att-class="line.discount &gt; 0 and 'text-decoration-line-through opacity-50' or ''" t-options="{'widget': 'monetary', 'display_currency': line.currency_id}"/>\n                                                <t t-if="line.discount &gt; 0">\n                                                    <span class="small text-success fw-medium">\n                                                        (−<t t-out="((line.discount % 1) and '%s' or '%d') % line.discount"/>%)\n                                                    </span>\n                                                </t>\n                                            </t>\n                                        </div>\n                                        <!-- Taxes as plain text -->\n                                        <div t-if="display_taxes and line.tax_ids" class="mt-1 small text-muted">\n                                            <span>Tax:</span>\n                                            <span t-out="', '.join(map(lambda x: (x.name), line.tax_ids))"/>\n                                        </div>\n                                    </t>\n                                </div>\n                            </t>\n                            <t t-else="">\n                                <!-- Collapsed composition: grouped section summary -->\n                                <t t-foreach="line._get_grouped_section_summary(display_taxes)" t-as="section_line">\n                                    <div class="py-3 px-3 border-bottom">\n                                        <div class="d-flex justify-content-between align-items-start gap-2">\n                                            <span t-field="line.label"/>\n                                            <span t-out="section_line[price_field_m]" t-options="{'widget': 'monetary', 'display_currency': sale_order.currency_id}" class="text-nowrap"/>\n                                        </div>\n                                        <div class="d-flex flex-wrap align-items-center gap-2 mt-1 small text-muted">\n                                            <span t-field="line.section_qty" t-options="{'min_precision': 0}"/>\n                                            <span t-field="line.section_uom_id"/>\n                                            <span>×</span>\n                                            <span t-out="section_line['price_subtotal']/line.section_qty" t-options="{'widget': 'monetary', 'display_currency': sale_order.currency_id}"/>\n                                        </div>\n                                        <div t-if="display_taxes and section_line.get('tax_labels')" class="mt-1 small text-muted">\n                                            <span>Tax:</span>\n                                            <t t-foreach="section_line['tax_labels']" t-as="tax_label">\n                                                <t t-if="not tax_label_first">, </t>\n                                                <span t-out="tax_label"/>\n                                            </t>\n                                        </div>\n                                    </div>\n                                </t>\n                            </t>\n                        </t>\n                    </div>\n\n                <!-- ===== DESKTOP TABLE ===== -->\n                <div name="sol_table" class="table-responsive d-none d-lg-block">\n                    <table t-att-data-order-id="sale_order.id" t-att-data-token="sale_order.access_token" class="table" id="sales_order_table">\n                        <thead class="d-none d-lg-contents">\n                            <tr>\n                                <th t-if="line_counter" id="line_number_header" class="text-start" style="width: 1%; white-space: nowrap;">#</th>\n                                <th class="text-start" id="product_name_header" aria-label="Description"/>\n                                <th class="text-end" id="product_qty_header" aria-label="Quantity"/>\n                                <th t-if="display_discount" class="text-end d-none d-sm-table-cell" id="product_discount_header">\n                                    <span>Discount</span>\n                                </th>\n                                <th class="text-end text-nowrap d-none d-sm-table-cell" id="product_unit_price_header">\n                                    Unit Price\n                                </th>\n                                <th t-if="display_taxes" class="text-end d-none d-md-table-cell" id="taxes_header">\n                                    <span>Taxes</span>\n                                </th>\n                                <th class="text-end" id="subtotal_header">\n                                    <span>Amount</span>\n                                </th>\n                            </tr>\n                        </thead>\n                        <tbody class="sale_tbody">\n\n                            <t t-set="current_section" t-value="None"/>\n                            <t t-set="current_subsection" t-value="None"/>\n                            <t t-set="price_field" t-value="'price_total' if (hide_taxes_details or sale_order.company_price_include == 'tax_included') else 'price_subtotal'"/>\n                            <t t-set="default_section_uom" t-value="sale_order.env.ref('uom.product_uom_unit')"/>\n\n                            <t t-foreach="lines_to_report" t-as="line">\n\n                                <t t-set="is_note" t-value="line.display_type == 'line_note'"/>\n                                <t t-set="is_section" t-value="line.display_type == 'line_section'"/>\n                                <t t-set="is_subsection" t-value="line.display_type == 'line_subsection'"/>\n                                <t t-set="is_combo" t-value="line.product_type == 'combo'"/>\n\n                                <t t-if="is_section">\n                                    <t t-set="current_section" t-value="line"/>\n                                    <t t-set="current_subsection" t-value="None"/>\n                                    <t t-set="line_padding" t-value="0"/>\n                                    <t t-set="collapse_prices" t-value="line.collapse_prices"/>\n                                </t>\n                                <t t-elif="is_subsection">\n                                    <t t-set="current_subsection" t-value="line"/>\n                                    <t t-set="line_padding" t-value="2"/>\n                                    <t t-set="collapse_prices" t-value="current_section.collapse_prices or line.collapse_prices"/>\n                                </t>\n                                <t t-else="">\n                                    <t t-set="line_padding" t-value="3 if current_subsection else (2 if current_section else 0)"/>\n                                </t>\n\n                                <t t-if="line.combo_item_id">\n                                    <t t-set="line_padding" t-value="line_padding + 1"/>\n                                </t>\n\n                                <t t-set="padding_style" t-value="(                                         line_padding                                         and ('padding-left:' + str(line_padding * 8) + 'px')                                         or 'padding-left: 4px'                                     )"/>\n                                <t t-set="show_section_total" t-value="is_section or not line.parent_id.collapse_prices"/>\n\n                                <t t-if="not line.collapse_composition">\n                                    <tr t-if="is_section or is_subsection" name="tr_section" t-attf-class="{{'o_line_section bg-200' if is_section else 'o_line_subsection bg-100'}} fw-bold">\n                                        <t t-set="show_section_total" t-value="(                                                 (                                                     is_section                                                     or not line.parent_id.collapse_prices                                                 )                                                 and not line.is_downpayment                                             )"/>\n                                        <t t-set="section_name_colspan" t-value="3 + (1 if display_discount else 0) + (1 if display_taxes else 0)"/>\n                                        <t t-if="not show_section_total">\n                                            <t t-set="section_name_colspan" t-value="99"/>\n                                        </t>\n                                        <t t-set="show_section_qty_uom" t-value="line.section_qty != 1 or (line.section_uom_id and line.section_uom_id != default_section_uom)"/>\n                                        <!-- Some columns (e.g. Discount and Unit Price)\n                                        are not displayed on smaller viewports -->\n                                        <td t-if="line_counter" name="td_section_line_no" class="text-start">\n                                            <span t-out="line_counter"/>\n                                            <t t-set="line_counter" t-value="line_counter + 1"/>\n                                        </td>\n                                        <td name="td_section_name_xs" t-att-colspan="section_name_colspan - 1 - (1 if display_discount else 0) - (1 if display_taxes else 0)" class="d-sm-none" t-att-style="padding_style">\n                                            <span t-field="line.label"/>\n                                            <span t-if="show_section_qty_uom" class="text-muted fw-normal ms-1">(<span t-field="line.section_qty" t-options="{'widget': 'float', 'min_precision': 0}"/> <span t-field="line.section_uom_id"/>)</span>\n                                        </td>\n                                        <td name="td_section_name_sm" t-att-colspan="section_name_colspan - (1 if display_taxes else 0)" class="d-none d-sm-table-cell d-md-none" t-att-style="padding_style">\n                                            <span t-field="line.label"/>\n                                            <span t-if="show_section_qty_uom" class="text-muted fw-normal ms-1">(<span t-field="line.section_qty" t-options="{'widget': 'float', 'min_precision': 0}"/> <span t-field="line.section_uom_id"/>)</span>\n                                        </td>\n                                        <td name="td_section_name" t-att-colspan="section_name_colspan" class="d-none d-md-table-cell" t-att-style="padding_style">\n                                            <span t-field="line.label"/>\n                                            <span t-if="show_section_qty_uom" class="text-muted fw-normal ms-1">(<span t-field="line.section_qty" t-options="{'widget': 'float', 'min_precision': 0}"/> <span t-field="line.section_uom_id"/>)</span>\n                                        </td>\n                                        <td t-if="show_section_total" name="td_section_price" class="text-end o_price_total">\n                                            <span name="price_subtotal_section" t-out="line._get_section_totals(price_field)" class="text-nowrap" t-options="{'widget': 'monetary', 'display_currency': sale_order.currency_id}"/>\n                                        </td>\n                                    </tr>\n                                    <tr t-elif="is_note" name="tr_note" class="fst-italic o_line_note">\n                                        <td t-if="line_counter" name="td_note_line_no" class="text-start fst-normal">\n                                            <span t-out="line_counter"/>\n                                            <t t-set="line_counter" t-value="line_counter + 1"/>\n                                        </td>\n                                        <td name="td_note_name" colspan="99" t-att-style="padding_style">\n                                            <span t-field="line.label"/>\n                                        </td>\n                                    </tr>\n                                    <tr t-elif="is_combo" name="tr_combo" class="fw-bold">\n                                        <td t-if="line_counter" name="td_combo_line_no" class="text-start">\n                                            <span t-out="line_counter"/>\n                                            <t t-set="line_counter" t-value="line_counter + 1"/>\n                                        </td>\n                                        <td name="td_combo_name" t-att-style="padding_style">\n                                            <span t-field="line.label">Combo Product</span>\n                                        </td>\n                                        <td name="td_combo_quantity" class="text-end">\n                                            <div id="quote_qty">\n                                                <span t-field="line.product_uom_qty" t-options="{'min_precision': 0}"/>\n                                                <span t-field="line.product_uom_id"/>\n                                            </div>\n                                        </td>\n                                        <td name="td_combo_subtotal" class="text-end" t-att-colspan="2 + (1 if display_discount else 0) + (1 if display_taxes else 0)">\n                                            <span t-if="not collapse_prices" name="price_subtotal_combo" t-out="line._get_combo_totals(price_field)" class="text-nowrap" t-options="{'widget': 'monetary', 'display_currency': sale_order.currency_id}">\n                                                27.00\n                                            </span>\n                                        </td>\n                                    </tr>\n                                    <tr t-else="" name="tr_product">\n                                        <td t-if="line_counter" name="td_product_line_no" class="text-start">\n                                            <span t-out="line_counter"/>\n                                            <t t-set="line_counter" t-value="line_counter + 1"/>\n                                        </td>\n                                        <td name="td_product_name" t-att-style="padding_style">\n                                            <div class="d-flex flex-row align-items-center">\n                                                <img t-if="sale_order.company_id.display_product_images_on_so and line.product_id.image_128" t-att-src="image_data_uri(line.product_id.image_128)" t-att-alt="line.product_id.display_name" class="o_sale_portal_product_image d-none d-lg-inline me-2 rounded object-fit-cover"/>\n                                                <div>\n                                                    <t t-set="label_parts" t-value="(line.label or '').split('\\n', 1)"/>\n                                                    <span name="span_product_name" t-out="label_parts[0]"/>\n                                                    <span t-if="len(label_parts) &gt; 1" class="o_sale_portal_line_description d-block text-muted small" t-out="label_parts[1]"/>\n                                                </div>\n                                            </div>\n                                        </td>\n                                        <td name="td_product_quantity" class="text-end">\n                                            <div id="quote_qty">\n                                                <span t-field="line.product_uom_qty" t-options="{'min_precision': 0}"/>\n                                                <span t-field="line.product_uom_id"/>\n                                            </div>\n                                        </td>\n                                        <td t-if="display_discount" name="td_product_discount" class="text-end d-none d-sm-table-cell">\n                                            <t t-if="not collapse_prices">\n                                                <!-- ! Always check collapse_prices separately; keep\n                                                discount condition below for XPath -->\n                                                <span t-if="line.discount &gt; 0" class="badge text-bg-success">\n                                                    <t t-out="((line.discount % 1) and '%s' or '%d') % line.discount"/>\n                                                    % </span>\n                                            </t>\n                                        </td>\n                                        <td name="td_product_priceunit" class="text-end d-none d-sm-table-cell">\n                                            <t t-if="not collapse_prices">\n                                                <span t-if="line.discount &gt;= 0" t-field="line.price_unit" t-att-style="line.discount and 'text-decoration: line-through' or None" t-att-class="(line.discount and 'text-muted' or '')" t-options="{'widget': 'monetary', 'display_currency': line.currency_id}"/>\n                                                <span t-if="line.discount" class="ms-2">\n                                                    <t t-out="line._get_discounted_price()" t-options="{'widget': 'monetary', 'display_currency': line.currency_id}"/>\n                                                </span>\n                                            </t>\n                                        </td>\n                                        <td t-if="display_taxes" name="td_product_taxes" class="text-end d-none d-md-table-cell">\n                                            <t t-if="not collapse_prices">\n                                                <t t-foreach="line.tax_ids" t-as="tax">\n                                                    <span class="badge text-bg-secondary me-1" t-out="tax.name"/>\n                                                </t>\n                                            </t>\n                                        </td>\n                                        <td name="td_product_subtotal" class="text-end">\n                                            <t t-if="not line.is_downpayment and not collapse_prices">\n                                                <span t-if="price_field == 'price_subtotal'" t-field="line.price_subtotal"/>\n                                                <span t-else="" t-field="line.price_total"/>\n                                            </t>\n                                        </td>\n                                    </tr>\n                                </t>\n                                <t t-else="">\n                                    <!-- Displaying the section inner content, grouped by taxes -->\n                                    <tr t-foreach="line._get_grouped_section_summary(display_taxes)" t-as="section_line" name="tr_section_group">\n                                        <td t-if="line_counter" name="td_section_group_line_no" class="text-start">\n                                            <span t-out="line_counter"/>\n                                            <t t-set="line_counter" t-value="line_counter + 1"/>\n                                        </td>\n                                        <td name="td_section_group_name" t-att-style="padding_style">\n                                            <span t-field="line.label">\n                                                Section Summary\n                                            </span>\n                                        </td>\n                                        <td name="td_section_group_quantity" class="text-end text-nowrap">\n                                            <span t-field="line.section_qty" t-options="{'min_precision': 0}"/>\n                                            <span t-field="line.section_uom_id"/>\n                                        </td>\n                                        <td t-if="display_discount" name="td_section_group_discount" class="d-none d-sm-table-cell"/>\n                                        <td name="td_section_group_priceunit" class="d-none d-sm-table-cell text-end text-nowrap">\n                                            <span t-if="show_section_total" t-out="section_line['price_subtotal']/line.section_qty" t-options="{'widget': 'monetary', 'display_currency': sale_order.currency_id}"/>\n                                        </td>\n                                        <td t-if="display_taxes" name="td_section_group_taxes" class="d-none d-md-table-cell text-end">\n                                            <t t-if="show_section_total">\n                                                <t t-foreach="section_line['tax_names']" t-as="tax_name">\n                                                    <span class="badge text-bg-secondary me-1" t-out="tax_name"/>\n                                                </t>\n                                            </t>\n                                        </td>\n                                        <td name="td_section_group_total" class="text-end o_price_total">\n                                            <span t-if="show_section_total" name="price_subtotal_section_grouped" t-out="section_line[price_field]" t-options="{'widget': 'monetary', 'display_currency': sale_order.currency_id}">\n                                                31.05\n                                            </span>\n                                        </td>\n                                    </tr>\n                                </t>\n                            </t>\n                        </tbody>\n                    </table>\n                </div>\n\n                <div id="total" name="total" class="mb-0 mb-lg-5" style="page-break-inside: avoid;">\n                    <div class="col-xs-7 col-md-5 ms-auto">\n                        <t t-call="sale.sale_order_portal_content_totals_table"/>\n                    </div>\n                </div>\n\n                <div t-if="not is_html_empty(sale_order.note) or sale_order.payment_term_id" id="payment_terms" class="px-3 px-lg-2 my-3">\n                    <div t-if="not is_html_empty(sale_order.note)">\n                        <span t-field="sale_order.note"/>\n                    </div>\n                    <div t-if="sale_order.payment_term_id">\n                        <span t-field="sale_order.payment_term_id.note"/>\n                    </div>\n                </div>\n            </section>\n\n            <!-- Product Documents -->\n            <section t-if="product_documents" id="product_documents" class="p-3 p-lg-4 mt-4 rounded-3 border">\n                <h4>Documents</h4>\n                <div class="d-flex flex-wrap gap-2">\n                    <t t-foreach="product_documents" t-as="document_sudo">\n                        <div class="bg-light p-2 rounded">\n                            <div class="position-relative text-center">\n                                <t t-set="attachment_sudo" t-value="document_sudo.ir_attachment_id"/>\n                                <t t-set="target" t-value="attachment_sudo.type == 'url' and '_blank' or '_self'"/>\n                                <a t-att-href="sale_order.get_portal_url('/document/' + str(document_sudo.id))" t-att-target="target" class="d-flex gap-2">\n                                    <div class="o_image" t-att-title="attachment_sudo.name" t-att-data-mimetype="attachment_sudo.mimetype" t-attf-data-src="/web/image/#{attachment_sudo.id}/100x80?access_token=#{attachment_sudo.access_token}"/>\n                                    <div class="o_portal_product_document align-self-center small" t-out="attachment_sudo.name"/>\n                                </a>\n                            </div>\n                        </div>\n                    </t>\n                </div>\n            </section>\n\n            <!-- Customer Addresses -->\n            <section id="customer_info" class="p-3 p-lg-4 mt-4 rounded-3 border">\n                <div t-if="sale_order.partner_shipping_id == sale_order.partner_invoice_id">\n                    <!-- Single column when addresses are the same -->\n                    <div class="mb-2" id="address_combined">\n                        <span class="badge text-bg-info">Delivery &amp; Billing</span>\n                        <small t-if="sale_order.partner_id == sale_order.partner_invoice_id == sale_order.env.user.partner_id">\n                            <a class="small" t-attf-href="/my/account?redirect={{sale_order.get_portal_url()}}">\n                                <i class="oi oi-fw oi-filled" data-icon="edit"/>\n                            </a>\n                        </small>\n                    </div>\n                    <div t-field="sale_order.partner_invoice_id" t-options="{'widget': 'contact', 'fields': ['name', 'address'], 'no_marker': True}"/>\n                </div>\n                <div t-else="" class="row">\n                    <!-- Double column when addresses are different -->\n                    <div class="col-12 col-lg-6">\n                        <div class="mb-2" id="address_billing">\n                            <span class="badge text-bg-info">Billing</span>\n                            <small t-if="sale_order.partner_id == sale_order.partner_invoice_id == sale_order.env.user.partner_id">\n                                <a class="small" t-attf-href="/my/account?redirect={{sale_order.get_portal_url()}}">\n                                    <i class="oi oi-fw oi-filled" data-icon="edit"/>\n                                </a>\n                            </small>\n                        </div>\n                        <div t-field="sale_order.partner_invoice_id" t-options="{'widget': 'contact', 'fields': ['name', 'address'], 'no_marker': True}"/>\n                    </div>\n                    <div class="col-12 col-lg-6">\n                        <div class="mb-2" id="address_delivery">\n                            <span class="badge text-bg-info">Delivery</span>\n                        </div>\n                        <div t-field="sale_order.partner_shipping_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;name&quot;, &quot;address&quot;], &quot;no_marker&quot;: true}"/>\n                    </div>\n                </div>\n            </section>\n        </div>\n    </t>\n\n    	\N	f	t	2026-10-26 23:48:31.401934	2026-10-26 23:48:31.401934	f
