1053	16	799	1	1	Account Invoice	account.move	\N	form	sale/views/account_views.xml	extension	\N	{"en_US": "<data><xpath expr=\\"//group[@name='sale_info_group']/field[@name='invoice_user_id']\\" position=\\"after\\">\\n                <field name=\\"team_id\\" context=\\"{'kanban_view_ref': 'sales_team.crm_team_view_kanban'}\\"/>\\n            </xpath>\\n            <xpath expr=\\"//group[@id='other_tab_group']\\" position=\\"inside\\">\\n                <group string=\\"Marketing\\" name=\\"utm_link\\" groups=\\"base.group_no_one\\" invisible=\\"move_type not in ('out_invoice', 'out_refund')\\">\\n                    <field name=\\"campaign_id\\" options=\\"{'create_name_field': 'title'}\\"/>\\n                    <field name=\\"medium_id\\"/>\\n                    <field name=\\"source_id\\"/>\\n                    <field name=\\"utm_reference\\" string=\\"Reference\\" options=\\"{'hide_model': True}\\" invisible=\\"not utm_reference\\" readonly=\\"True\\"/>\\n                </group>\\n            </xpath>\\n            <xpath expr=\\"//div[@name='button_box']\\" position=\\"inside\\">\\n                <button class=\\"oe_stat_button\\" name=\\"action_view_source_sale_orders\\" type=\\"object\\" icon=\\"edit_square\\" invisible=\\"sale_order_count == 0 or move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')\\">\\n                    <field string=\\"Sale Orders\\" name=\\"sale_order_count\\" widget=\\"statinfo\\"/>\\n                </button>\\n                <button name=\\"action_view_services_analytic_lines\\" type=\\"object\\" class=\\"oe_stat_button\\" icon=\\"menu\\" groups=\\"sale.group_services_and_material\\" invisible=\\"service_line_count == 0\\">\\n                    <field name=\\"service_line_count\\" string=\\"Services\\" widget=\\"statinfo\\"/>\\n                </button>\\n            </xpath>\\n            <xpath expr=\\"//field[@name='invoice_line_ids']/list\\" position=\\"inside\\">\\n       