1086	16	\N	1	1	Sales Order Portal Pay Modal	\N	sale.sale_order_portal_pay_modal	qweb	sale/views/sale_portal_templates.xml	primary	\N	{"en_US": "<t name=\\"Sales Order Portal Pay Modal\\" t-name=\\"sale.sale_order_portal_pay_modal\\">\\n        <div class=\\"modal-content\\">\\n            <header class=\\"modal-header\\">\\n                <h4 class=\\"modal-title\\">Pay Order</h4>\\n                <button type=\\"button\\" class=\\"btn-close\\" data-bs-dismiss=\\"modal\\" aria-label=\\"Close\\"/>\\n            </header>\\n            <main class=\\"modal-body\\" id=\\"sign-dialog\\">\\n                <t t-set=\\"prepayment_amount\\" t-value=\\"sale_order._get_prepayment_required_amount()\\"/>\\n                <t t-set=\\"full_prepayment\\" t-value=\\"amount == prepayment_amount\\"/>\\n                <t t-if=\\"sale_order._has_to_be_paid() and prepayment_available\\" t-call=\\"sale.sale_order_portal_pay_modal_amount_selector\\"/>\\n                <div t-if=\\"sale_order._has_to_be_paid() and full_prepayment\\" class=\\"mb-3\\">\\n                    <!-- The widget associated with this modal will hide and show spans depending of the selected option. -->\\n                    <span t-if=\\"prepayment_available\\">\\n                        <span id=\\"o_sale_portal_use_amount_prepayment\\">\\n                            By paying a <u>down payment</u> of\\n                            <span t-out=\\"amount\\" t-options=\\"{                                     'widget': 'monetary',                                     'display_currency': sale_order.currency_id                                 }\\" class=\\"fw-bold\\"/>\\n                            <t t-if=\\"sale_order._get_prepayment_required_amount() == amount\\">\\n                                (<b t-out=\\"sale_order.prepayment_percent * 100\\" t-options=\\"{'widget': 'float', 'precision': 2, 'min_precision': 0}\\"/>%),\\n                            </t>\\n                        </span>\\n                        <span id=\\"o_sale_portal_use_amount_total\\">By paying,</span>\\n                    </span>\\n                    <span t-else=\\"\\">\\n                        By paying,\\n                        <span t-out=\\"amount\\" t-options=\\"{                                 'widget': 'monetary',                                 'display_currency': sale_order.currency_id,                             }\\" class=\\"fw-bold\\"/>\\n                    </span>\\n                    you confirm acceptance on behalf of\\n                    <b t-field=\\"sale_order.partner_id.commercial_partner_id\\"/>\\n                    for the <b data-id=\\"total_amount\\" t-field=\\"sale_order.amount_total\\"/> quote.\\n                    <b t-if=\\"sale_order.payment_term_id\\" t-field=\\"sale_order.payment_term_id.note\\" class=\\"o_sale_payment_terms\\"/>\\n                </div>\\n                <div t-if=\\"payment_amount and not sale_order._has_to_be_paid()\\" class=\\"mb-3\\">\\n                    Amount:\\n                    <span t-out=\\"payment_amount\\" t-options=\\"{                             'widget': 'monetary',                             'display_currency': sale_order.currency_id,                         }\\" class=\\"fw-bold\\"/>\\n                </div>\\n                <div t-if=\\"company_mismatch\\"><t t-call=\\"payment.company_mismatch_warning\\"/></div>\\n                <div t-elif=\\"not sale_order._has_to_be_paid() and not payment_amount\\" class=\\"alert alert-danger\\">\\n                    The order is not in a state requiring customer payment.\\n                </div>\\n                <div t-else=\\"\\" id=\\"payment_method\\" class=\\"text-start mt-0\\">\\n                    <!-- Inject the order ID to allow Stripe to check if tokenization is required. -->\\n                    <t t-call=\\"payment.form\\" sale_order_id=\\"sale_order.id\\"/>\\n                </div>\\n            </main>\\n        </div>\\n    </t>", "es_ES": "<t name=\\"Sales Order Portal Pay Modal\\" t-name=\\"sale.sale_order_portal_pay_modal\\">\\n        <div class=\\"modal-content\\">\\n            <header class=\\"modal-header\\">\\n                <h4 class=\\"modal-title\\">Pagar pedido</h4>\\n                <button type=\\"button\\" class=\\"btn-close\\" data-bs-dismiss=\\"modal\\" aria-label=\\"Cerrar\\"/>\\n            </header>\\n            <main class=\\"modal-body\\" id=\\"sign-dialog\\">\\n                <t t-set=\\"prepayment_amount\\" t-value=\\"sale_order._get_prepayment_required_amount()\\"/>\\n                <t t-set=\\"full_prepayment\\" t-value=\\"amount == prepayment_amount\\"/>\\n                <t t-if=\\"sale_order._has_to_be_paid() and prepayment_available\\" t-call=\\"sale.sale_order_portal_pay_modal_amount_selector\\"/>\\n                <div t-if=\\"sale_order._has_to_be_paid() and full_prepayment\\" class=\\"mb-3\\">\\n                    <!-- The widget associated with this modal will hide and show spans depending of the selected option. -->\\n                    <span t-if=\\"prepayment_available\\">\\n                        <span id=\\"o_sale_portal_use_amount_prepayment\\">\\n                            Al pagar un <u>anticipo</u> de\\n                            <span t-out=\\"amount\\" t-options=\\"{                                     'widget': 'monetary',                                     'display_currency': sale_order.currency_id                                 }\\" class=\\"fw-bold\\"/>\\n                            <t t-if=\\"sale_order._get_prepayment_required_amount() == amount\\">\\n                                (<b t-out=\\"sale_order.prepayment_percent * 100\\" t-options=\\"{'widget': 'float', 'precision': 2, 'min_precision': 0}\\"/>%),\\n                            </t>\\n                        </span>\\n                        <span id=\\"o_sale_portal_use_amount_total\\">Al pagar,</span>\\n                    </span>\\n                    <span t-else=\\"\\">\\n                