                 <!-- (3) Domicilio Comercial (Domicilio Fiscal is the same) -->\\n                        <br/>\\n                        <div/>\\n                        <!-- we dont use the address widget as it adds a new line on the phone and we want to reduce at maximum lines qty -->\\n                        <t t-out=\\"' - '.join([item for item in [                             ', '.join([item for item in [header_address.street, header_address.street2] if item]),                             header_address.city,                             header_address.state_id and header_address.state_id.name,                             header_address.zip,                             header_address.country_id and header_address.country_id.name] if item])\\"/><span t-if=\\"header_address.phone\\"> - </span><span t-if=\\"header_address.phone\\" style=\\"white-space: nowrap;\\" t-out=\\"'Tel: ' + header_address.phone\\"/>\\n                        <br/>\\n                        <span t-att-style=\\"'color: %s;' % o.company_id.primary_color\\" t-out=\\"' - '.join([item for item in [(header_address.website or '').replace('https://', '').replace('http://', ''), header_address.email] if item])\\"/>\\n                    </t>\\n                </div>\\n                <div id=\\"l10n_ar_header_right\\" class=\\"col-6 text-end\\" style=\\"padding-left: 0px;\\">\\n\\n                    <t t-if=\\"not pre_printed_report\\">\\n                        <!-- (7) Numero punto venta - (8) numero de documento -->\\n                        <span t-att-style=\\"'color: %s;' % o.company_id.secondary_color\\">Nro: </span><span t-out=\\"report_number\\"/>\\n                    </t>\\n                    <br/>\\n\\n                    <!-- (9) Fecha -->\\n                    <span t-att-style=\\"'color: %s;' % o.company_id.secondary_color\\">Date: </span><span t-out=\\"report_date\\" t-options=\\"{&quot;widget&quot;: &quot;date&quot;}\\"/>\\n\\n                    <t t-if=\\"not pre_printed_report\\">\\n                        <!-- (5) Condicion de IVA / Responsabilidad -->\\n                        <!-- (10) CUIT -->\\n                        <br/>\\n                        <span t-field=\\"o.company_id.l10n_ar_afip_responsibility_type_id\\"/><span t-att-style=\\"'color: %s;' % o.company_id.secondary_color\\"> - CUIT: </span><span t-field=\\"o.company_id.partner_id.l10n_ar_formatted_vat\\"/>\\n\\n                        <!-- (11) IIBB: -->\\n                        <!-- (12) Inicio de actividades -->\\n                        <br/><span t-att-style=\\"'color: %s;' % o.company_id.secondary_color\\">IIBB: </span><span t-out=\\"o.company_id.l10n_ar_gross_income_type == 'exempt' and 'Exento' or o.company_id.l10n_ar_gross_income_number\\"/><span t-att-style=\\"'color: %s;' % o.company_id.secondary_color\\"> - Activities Start: </span><span t-field=\\"o.company_id.l10n_ar_afip_start_date\\"/>\\n                    </t>\\n\\n                </div>\\n            </div>\\n        </div>\\n    </t>"}	<?xml version="1.0"?>\n<t t-name="l10n_ar.custom_header">\n        <div class="mb-3">\n            <div class="row mb-2">\n                <div name="left-upper-side" class="col-5" t-if="not pre_printed_report">\n                    <img t-if="o.company_id.logo" t-att-src="image_data_uri(o.company_id.logo)" style="max-height: 65px;" alt="Logo"/>\n                </div>\n                <div name="center-upper" class="col-2 text-center" t-att-style="'color: %s;' % o.company_id.primary_color">\n                    <span id="withholding_legend" style="display: inline-block; text-align: center; line-height: 8px;">\n                        <h1 style="line-height: 35px;">\n                            <strong><span t-out="not pre_printed_report and document_letter or ' '"/></strong>\n                        </h1>\n                        <span style="font-size: x-small;" t-out="not pre_printed_report and document_legend or ' '"/>\n                    </span>\n                </div>\n                <div name="right-upper-side" class="col-5 text-end" style="padding-left: 0px;" t-if="not pre_printed_report">\n\n                    <!-- (6) Titulo de Documento -->\n                    <h4 t-att-style="'color: %s;' % o.company_id.primary_color"><strong>\n                        <span t-out="report_name"/>\n                    </strong></h4>\n\n                </div>\n            </div>\n            <div class="row">\n                <div class="col-6" style="padding-right: 0px;">\n                    <t t-if="not pre_printed_report">\n                        <!-- (1) Nombre de Fantasia -->\n                        <!-- (2) Apellido y Nombre o Razon Social -->\n                        <span t-field="o.company_id.partner_id.name"/>\n\n                        <!-- (3) Domicilio Comercial (Domicilio Fiscal is the same) -->\n                        <br/>\n                        <div/>\n                        <!-- we dont use the address widget as it adds a new line on the phone and we want to reduce at maximum lines qty -->\n                        <t t-out="' - '.join([item for item in [                             ', '.join([item for item in [header_address.street, header_address.street2] if item]),                             header_address.city,                             header_address.state_id and header_address.state_id.name,                             header_address.zip,                             header_address.country_id and header_address.country_id.name] if item])"/><span t-if="header_address.phone"> - </span><span t-if="header_address.phone" style="white-space: nowrap;" t-out="'Tel: ' + header_address.phone"/>\n                        <br/>\n                        <span t-att-style="'color: %s;' % o.company_id.primary_color" t-out="' - '.join([item for item in [(header_address.website or '').replace('https://', '').replace('http://', ''), header_address.email] if item])"/>\n                    </t>\n                </div>\n                <div id="l10n_ar_header_right" class="col-6 text-end" style="padding-left: 0px;">\n\n                    <t t-if="not pre_printed_report">\n                        <!-- (7) Numero punto venta - (8) numero de documento -->\n                        <span t-att-style="'color: %s;' % o.company_id.secondary_color">Nro: </span><span t-out="report_number"/>\n                    </t>\n                    <br/>\n\n                    <!-- (9) Fecha -->\n                    <span t-att-style="'color: %s;' % o.company_id.secondary_color">Date: </span><span t-out="report_date" t-options="{&quot;widget&quot;: &quot;date&quot;}"/>\n\n                    <t t-if="not pre_printed_report">\n                        <!-- (5) Condicion de IVA / Responsabilidad -->\n                        <!-- (10) CUIT -->\n                        <br/>\n                        <span t-field="o.company_id.l10n_ar_afip_responsibility_type_id"/><span t-att-style="'color: %s;' % o.company_id.secondary_color"> - CUIT: </span><span t-field="o.company_id.partner_id.l10n_ar_formatted_vat"/>\n\n                        <!-- (11) IIBB: -->\n                        <!-- (12) Inicio de actividades -->\n                        <br/><span t-att-style="'color: %s;' % o.company_id.secondary_color">IIBB: </span><span t-out="o.company_id.l10n_ar_gross_income_type == 'exempt' and 'Exento' or o.company_id.l10n_ar_gross_income_number"/><span t-att-style="'color: %s;' % o.company_id.secondary_color"> - Activities Start: </span><span t-field="o.company_id.l10n_ar_afip_start_date"/>\n                    </t>\n\n                </div>\n            </div>\n        </div>\n    </t>\n\n    	\N	f	t	2026-10-26 23:48:36.567735	2026-10-26 23:48:36.567735	f
1117	16	881	1	1	report_invoice_document	\N	l10n_ar.report_invoice_document	qweb	l10n_ar/views/report_invoice.xml	primary	\N	{"en_US": "<data>\\n      <!-- custom header and footer -->\\n        <t t-call=\\"web.external_layout\\" position=\\"before\\">\\n            <t t-set=\\"custom_header\\" t-value=\\"'l10n_ar.custom_header'\\"/>\\n            <t t-set=\\"report_date\\" t-value=\\"o.invoice_date\\"/>\\n            <t t-set=\\"report_number\\" t-value=\\"o.l10n_latam_document_number\\"/>\\n            <t t-set=\\"pre_printed_report\\" t-value=\\"report_type == 'pdf' and o.journal_id.l10n_ar_afip_pos_system == 'II_IM'\\"/>\\n            <t t-set=\\"document_letter\\" t-value=\\"o.l10n_latam_document_type_id.l10n_ar_letter\\"/>\\n            <t t-set=\\"document_type_code\\" t-value=\\"o.l10n_latam_document_type_id.code\\"/>\\n            <t t-set=\\"document_legend\\" t-value=\\"document_type_code and 'Cod. %02d' % int(document_type_code) or ''\\"/>\\n            <t t-set=\\"report_name\\" t-value=\\"o.l10n_latam_document_type_id.report_name\\"/>\\n            <t t-set=\\"header_address\\" t-value=\\"o.journal_id.l10n_ar_afip_pos_partner_id\\"/>\\n\\n            <t t-set=\\"custom_footer\\">\\n                <div class=\\"row\\">\\n                    <div name=\\"footer_left_column\\" class=\\"col-8 text-start\\">\\n                    </div>\\n                    <div name=\\"footer_right_column\\" class=\\"col-4 text-end\\">\\n                        <div name=\\"pager\\" t-if=\\"report_type == 'pdf'\\">\\n                            Page: <span class=\\"page\\"/> / <span class=\\"topage\\"/>\\n                        </div>\\n                    </div>\\n                </div>\\n            </t>\\n            <t t-set=\\"fiscal_bond\\" t-value=\\"o.journal_id.l10n_ar_afip_pos_system in ['BFERCEL', 'BFEWS']\\"/>\\n        </t>\\n\\n        <!-- remove default partner address -->\\n        <t t-set=\\"address\\" position=\\"replace\\"/>\\n\\n        <!-- remove default document title -->\\n        <xpath expr=\\"//t[@t-set='layout_document_title']\\" position=\\"replace\\"/>\\n\\n        <!-- NCM column for fiscal bond -->\\n        <th name=\\"th_description\\" position=\\"after\\">\\n            <th t-if=\\"fiscal_bond\\" name=\\"th_ncm_code\\" class=\\"text-start\\"><span>NCM</span></th>\\n        </th>\\n        <td name=\\"account_invoice_line_name\\" position=\\"after\\">\\n            <td t-if=\\"fiscal_bond\\" name=\\"ncm_code\\"><span t-field=\\"line.product_id.l10n_ar_ncm_code\\"/></td>\\n        </td>\\n\\n        <!-- use latam prices (to include/exclude VAT) -->\\n        <xpath expr=\\"//t[@t-foreach='lines_to_report']/t\\" position=\\"before\\">\\n            <t t-set=\\"l10n_ar_values\\" t-value=\\"line._l10n_ar_prices_and_taxes()\\"/>\\n        </xpath>\\n        <xpath expr=\\"//span[@t-field='line.price_unit']\\" position=\\"attributes\\">\\n            <attribute name=\\"t-field\\"/>\\n            <attribute name=\\"t-out\\">l10n_ar_values['price_unit']</attribute>\\n            <attribute name=\\"t-options\\">{\\"widget\\": \\"float\\", \\"display_currency\\": o.currency_id, \\"decimal_precision\\": \\"Product Price\\"}</attribute>\\n        </xpath>\\n        <!-- if b2c we still wants the latam subtotal -->\\n        <!-- In the parent implementation, when company_price_include == 'tax_include',\\n        get_section_total is used instead. However, this is not adapted for AR localization,\\n        which intentionally keeps the LATAM subtotal logic here. -->\\n        <xpath expr=\\"//t[@t-set='section_subtotal']\\" position=\\"attributes\\">\\n            <attribute name=\\"t-value\\">\\n                line.get_section_subtotal() + l10n_ar_values['price_subtotal']\\n            </attribute>\\n        </xpath>\\n        <xpath expr=\\"//t/tr/t[@t-set='line_colspan']\\" position=\\"attributes\\">\\n            <attribute name=\\"t-value\\">3 + (1 if display_discount else 0) + (1 if not line.tax_ids and not o._l10n_ar_include_vat() else 0)</attribute>\\n        </xpath>\\n\\n        <xpath expr=\\"//t/t/t[@t-else='']/t[@t-set='line_colspan']\\" position=\\"attributes\\">\\n            <attribute name=\\"t-value\\">3 + (1 if display_discount else 0) + (1 if display_taxes and not grouped_line.get('taxes') and o._l10n_ar_include_vat() else 0)</attribute>\\n        </xpath>\\n        <!-- label amount for subtotal column on b2b and b2c -->\\n        <xpath expr=\\"//th[@name='th_subtotal']/span\\" position=\\"replace\\">\\n            <span>Amount</span>\\n        </xpath>\\n        <span t-field=\\"line.price_subtotal\\" position=\\"attributes\\">\\n            <attribute name=\\"t-field\\"/>\\n            <attribute name=\\"t-out\\">l10n_ar_values['price_subtotal']</attribute>\\n            <attribute name=\\"t-options\\">{\\"widget\\": \\"monetary\\", \\"display_currency\\": o.currency_id}</attribute>\\n        </span>\\n\\n        <t t-call=\\"account.document_tax_totals\\" position=\\"attributes\\">\\n            <attribute name=\\"tax_totals\\">o._l10n_ar_get_invoice_totals_for_report()</attribute>\\n        </t>\\n\\n        <!-- use column vat instead of taxes and only if vat discriminated -->\\n        <xpath expr=\\"//th[@name='th_taxes']\\" position=\\"replace\\">\\n            <th name=\\"th_taxes\\" t-attf-class=\\"text-start {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}\\" t-if=\\"not o._l10n_ar_include_vat()\\">\\n                <span t-if=\\"o.company_id.country_id.code == 'AR'\\">% VAT</span>\\n                <span t-else=\\"\\">Taxes</span>\\n            </th>\\n        </xpath>\\n\\n        <xpath expr=\\"//span[@id='line_tax_ids']/..\\" position=\\"attributes\\">\\n            <attribute name=\\"t-if\\">not hide_prices and not o._l10n_ar_include_vat()</attribute>\\n        </xpath>\\n        <xpath expr=\\"//span[@id='grouped_line_tax_ids']/..\\" position=\\"attributes\\">\\n            <attribute name=\\"t-if\\">not o._l10n_ar_include_vat()</attribute>\\n        </xpath>\\n        <span id=\\"line_tax_ids\\" position=\\"attributes\\">\\n            <attribute name=\\"t-out\\">', '.join(tax.tax_label for tax in line.tax_ids if tax.tax_label and tax.tax_group_id.l10n_ar_vat_afip_code)</attribute>\\n        </span>\\n\\n        <!-- remove payment reference that is not used in Argentina -->\\n        <xpath expr=\\"//span[@t-field='o.payment_reference']/../..\\" position=\\"replace\\"/>\\n\\n        <!-- replace information section and usage argentinean style -->\\n        <div id=\\"informations\\" position=\\"replace\\">\\n            <div id=\\"informations\\" class=\\"row mt8 mb8\\">\\n                <div class=\\"col-6\\">\\n\\n                    <!-- IDENTIFICACION (ADQUIRIENTE-LOCATARIO-PRESTARIO) -->\\n\\n                    <!-- (14) Apellido uy Nombre: Denominicacion o Razon Soclial -->\\n                    <t t-if=\\"o.is_sale_document(include_receipts=True)\\"><strong>Customer: </strong></t>\\n                    <t t-else=\\"\\"><strong>Supplier: </strong></t>\\n                    <span t-field=\\"o.partner_id.commercial_partner_id.name\\"/>\\n\\n                    <!-- (15) Domicilio Comercial -->\\n                    <br/>\\n                    <span t-field=\\"o.partner_id\\" t-options=\\"{'widget': 'contact', 'fields': ['address'], 'no_marker': true, 'no_tag_br': True}\\"/>\\n\\n                    <!-- (16) Responsabilidad ARCA -->\\n                    <strong>VAT Cond: </strong><span t-field=\\"o.partner_id.l10n_ar_afip_responsibility_type_id\\"/>\\n\\n                    <!-- (17) CUIT -->\\n                    <t t-if=\\"o.partner_id.l10n_ar_afip_code and o.partner_id.l10n_ar_afip_code != '99'\\">\\n                        <t t-set=\\"ar_doc_vals\\" t-value=\\"o.partner_id._get_preferred_legal_entity_identifier_vals()\\"/>\\n                        <t t-set=\\"ar_doc_label\\" t-value=\\"ar_doc_vals.get('label') or o.company_id.account_fiscal_country_id.vat_label\\"/>\\n                        <br/><strong><t t-out=\\"ar_doc_label\\" id=\\"inv_tax_id_label\\"/>:</strong> <span t-out=\\"o.partner_id.l10n_ar_formatted_vat or ar_doc_vals.get('value', '')\\"/>\\n                    </t>\\n\\n                </div>\\n                <div class=\\"col-6\\">\\n\\n                    <t t-if=\\"o.invoice_date_due\\">\\n                        <strong>Due Date: </strong>\\n                        <span t-field=\\"o.invoice_date_due\\"/>\\n                    </t>\\n\\n                    <t t-if=\\"o.invoice_payment_term_id\\" name=\\"payment_term\\">\\n                        <br/><strong>Payment Terms: </strong><span t-field=\\"o.invoice_payment_term_id.name\\"/>\\n                    </t>\\n\\n                    <t t-if=\\"o.invoice_origin\\">\\n                        <br/><strong>Source:</strong>\\n                        <span t-field=\\"o.invoice_origin\\"/>\\n                    </t>\\n\\n                    <t t-if=\\"o.ref\\">\\n                        <br/><strong>Reference:</strong>\\n                        <span t-field=\\"o.ref\\"/>\\n                    </t>\\n\\n                    <!-- (18) REMITOS -->\\n                    <!-- We do not have remitos implement yet. print here the remito number when we have it -->\\n\\n                    <t t-if=\\"o.invoice_incoterm_id\\">\\n                        <br/>\\n                        <strong>Incoterm:</strong>\\n                        <p t-if=\\"o.incoterm_location\\">\\n                            <span t-field=\\"o.invoice_incoterm_id.code\\"/> <br/>\\n                            <span t-field=\\"o.incoterm_location\\"/>\\n                        </p>\\n                        <p t-else=\\"\\" t-field=\\"o.invoice_incoterm_id.name\\" class=\\"m-0\\"/>\\n                    </t>\\n\\n                </div>\\n\\n            </div>\\n        </div>\\n\\n        <xpath expr=\\"//div[@id='payment_term']\\" position=\\"before\\">\\n            <div class=\\"mb-4\\">\\n                <t t-if=\\"o.l10n_ar_afip_concept in ['2', '3', '4'] and o.l10n_ar_afip_service_start and o.l10n_ar_afip_service_end\\">\\n                    <strong>Invoiced period: </strong><span t-field=\\"o.l10n_ar_afip_service_start\\"/> to <span t-field=\\"o.l10n_ar_afip_service_end\\"/>\\n                </t>\\n                <t t-if=\\"o.currency_id != o.company_id.currency_id\\">\\n                    <br/><strong>Currency: </strong><span t-out=\\"'%s - %s' % (o.currency_id.name, o.currency_id.currency_unit_label)\\"/>\\n                    <br/><span>1 <t t-out=\\"o.currency_id.name\\"/> = <t t-out=\\"1 / o.invoice_currency_rate\\" t-options=\\"{&quot;widget&quot;: &quot;float&quot;, &quot;precision&quot;: 2}\\"/> <t t-out=\\"o.company_currency_id.name\\"/></span>\\n                </t>\\n                <!-- Show CBU for FACTURA DE CREDITO ELECTRONICA MiPyMEs and NOTA DE DEBITO ELECTRONICA MiPyMEs -->\\n                <t t-if=\\"o.l10n_latam_document_type_id.code in ['201', '206', '211', '202', '207', '212'] and o.partner_bank_id\\">\\n                    <br/><strong>CBU for payment: </strong><span t-out=\\"o.partner_bank_id.account_number or '' if o.partner_bank_id.account_type == 'cbu' else ''\\"/>\\n                </t>\\n\\n            </div>\\n        </xpath>\\n\\n        <!-- Show total amount in letters for MiPyMEs document types according to the law\\n         http://biblioteca.afip.gob.ar/dcp/LEY_C_027440_2018_05_09 article 5.f -->\\n        <xpath expr=\\"//div[@id='total']/div/table\\" position=\\"after\\">\\n            <t t-if=\\"o.l10n_latam_document_type_id.code in ['201', '202', '203', '206', '207', '208', '211', '212', '213']\\">\\n                <strong>Son: </strong><span t-out=\\"o.currency_id.amount_to_text(o.amount_total)\\"/>\\n            </t>\\n        </xpath>\\n\\n        <!-- RG 5003: Add legend for 'A' documents that have a Monotribuista receptor -->\\n        <div name=\\"comment\\" position=\\"after\\">\\n            <p t-if=\\"o.partner_id.l10n_ar_afip_responsibility_type_id.code in ['6', '13'] and o.l10n_latam_document_type_id.l10n_ar_letter == 'A'\\">\\n                The tax credit specified in this voucher may only be computed for purposes of the Tax Support and Inclusion Regime for Small Taxpayers of Law No. 27,618.\\n            </p>\\n        </div>\\n\\n        <t t-call=\\"account.document_tax_totals\\" position=\\"attributes\\">\\n            <attribute name=\\"t-call\\">l10n_ar.document_tax_totals</attribute>\\n        </t>\\n\\n        <div id=\\"qrcode\\" position=\\"after\\">\\n            <!-- RG 5614/2024: Show ARCA VAT and Other National Internal Taxes -->\\n            <t t-set=\\"l10n_ar_custom_tax_summary\\" t-value=\\"o._l10n_ar_get_invoice_custom_tax_summary_for_report()\\"/>\\n            <div t-attf-class=\\"l10n_ar_tax_details {{ 'col-6' if report_type == 'pdf' else '' }}\\" t-if=\\"l10n_ar_custom_tax_summary\\">\\n                <table class=\\"table table-sm table-borderless\\" style=\\"page-break-inside: avoid;\\">\\n                    <th class=\\"border-black\\" style=\\"border-bottom: 1px solid\\" colspan=\\"2\\">\\n                           Fiscal Transparency Regime for the Final Consumer (Law 27.743)\\n                    </th>\\n                    <t t-foreach=\\"l10n_ar_custom_tax_summary\\" t-as=\\"detail\\">\\n                        <tr>\\n                            <td class=\\"text-end\\"><strong t-out=\\"detail['name']\\"/></td>\\n                            <td class=\\"text-end\\">\\n                                <span class=\\"oe_subtotal_footer_separator\\" t-out=\\"detail['formatted_tax_amount_currency']\\"/>\\n                            </td>\\n                        </tr>\\n                    </t>\\n                </table>\\n            </div>\\n        </div>\\n\\n    <xpath expr=\\".\\" position=\\"attributes\\"><attribute name=\\"t-name\\">l10n_ar.report_invoice_document</attribute></xpath></data>"}	<?xml version="1.0"?>\n<data>\n      <!-- custom header and footer -->\n        <t t-call="web.external_layout" position="before">\n            <t t-set="custom_header" t-value="'l10n_ar.custom_header'"/>\n            <t t-set="report_date" t-value="o.invoice_date"/>\n            <t t-set="report_number" t-value="o.l10n_latam_document_number"/>\n            <t t-set="pre_printed_report" t-value="report_type == 'pdf' and o.journal_id.l10n_ar_afip_pos_system == 'II_IM'"/>\n            <t t-set="document_letter" t-value="o.l10n_latam_document_type_id.l10n_ar_letter"/>\n            <t t-set="document_type_code" t-value="o.l10n_latam_document_type_id.code"/>\n            <t t-set="document_legend" t-value="document_type_code and 'Cod. %02d' % int(document_type_code) or ''"/>\n            <t t-set="report_name" t-value="o.l10n_latam_document_type_id.report_name"/>\n            <t t-set="header_address" t-value="o.journal_id.l10n_ar_afip_pos_partner_id"/>\n\n            <t t-set="custom_footer">\n                <div class="row">\n                    <div name="footer_left_column" class="col-8 text-start">\n                    </div>\n                    <div name="footer_right_column" class="col-4 text-end">\n                        <div name="pager" t-if="report_type == 'pdf'">\n                            Page: <span class="page"/> / <span class="topage"/>\n                        </div>\n                    </div>\n                </div>\n            </t>\n            <t t-set="fiscal_bond" t-value="o.journal_id.l10n_ar_afip_pos_system in ['BFERCEL', 'BFEWS']"/>\n        </t>\n\n        <!-- remove default partner address -->\n        <t t-set="address" position="replace"/>\n\n        <!-- remove default document title -->\n        <xpath expr="//t[@t-set='layout_document_title']" position="replace"/>\n\n        <!-- NCM column for fiscal bond -->\n        <th name="th_description" position="after">\n            <th t-if="fiscal_bond" name="th_ncm_code" class="text-start"><span>NCM</span></th>\n        </th>\n        <td name="account_invoice_line_name" position="after">\n            <td t-if="fiscal_bond" name="ncm_code"><span t-field="line.product_id.l10n_ar_ncm_code"/></td>\n        </td>\n\n        <!-- use latam prices (to include/exclude VAT) -->\n        <xpath expr="//t[@t-foreach='lines_to_report']/t" position="before">\n            <t t-set="l10n_ar_values" t-value="line._l10n_ar_prices_and_taxes()"/>\n        </xpath>\n        <xpath expr="//span[@t-field='line.price_unit']" position="attributes">\n            <attribute name="t-field"/>\n            <attribute name="t-out">l10n_ar_values['price_unit']</attribute>\n            <attribute name="t-options">{"widget": "float", "display_currency": o.currency_id, "decimal_precision": "Product Price"}</attribute>\n        </xpath>\n        <!-- if b2c we still wants the latam subtotal -->\n        <!-- In the parent implementation, when company_price_include == 'tax_include',\n        get_section_total is used instead. However, this is not adapted for AR localization,\n        which intentionally keeps the LATAM subtotal logic here. -->\n        <xpath expr="//t[@t-set='section_subtotal']" position="attributes">\n            <attribute name="t-value">\n                line.get_section_subtotal() + l10n_ar_values['price_subtotal']\n            </attribute>\n        </xpath>\n        <xpath expr="//t/tr/t[@t-set='line_colspan']" position="attributes">\n            <attribute name="t-value">3 + (1 if display_discount else 0) + (1 if not line.tax_ids and not o._l10n_ar_include_vat() else 0)</attribute>\n        </xpath>\n\n        <xpath expr="//t/t/t[@t-else='']/t[@t-set='line_colspan']" position="attributes">\n            <attribute name="t-value">3 + (1 if display_discount else 0) + (1 if display_taxes and not grouped_line.get('taxes') and o._l10n_ar_include_vat() else 0)</attribute>\n        </xpath>\n        <!-- label amount for subtotal column on b2b and b2c -->\n        <xpath expr="//th[@name='th_subtotal']/span" position="replace">\n            <span>Amount</span>\n        </xpath>\n        <span t-field="line.price_subtotal" position="attributes">\n            <attribute name="t-field"/>\n            <attribute name="t-out">l10n_ar_values['price_subtotal']</attribute>\n            <attribute name="t-options">{"widget": "monetary", "display_currency": o.currency_id}</attribute>\n        </span>\n\n        <t t-call="account.document_tax_totals" position="attributes">\n            <attribute name="tax_totals">o._l10n_ar_get_invoice_totals_for_report()</attribute>\n        </t>\n\n        <!-- use column vat instead of taxes and only if vat discriminated -->\n        <xpath expr="//th[@name='th_taxes']" position="replace">\n            <th name="th_taxes" t-attf-class="text-start {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}" t-if="not o._l10n_ar_include_vat()">\n                <span t-if="o.company_id.country_id.code == 'AR'">% VAT</span>\n                <span t-else="">Taxes</span>\n            </th>\n        </xpath>\n\n        <xpath expr="//span[@id='line_tax_ids']/.." position="attributes">\n            <attribute name="t-if">not hide_prices and not o._l10n_ar_include_vat()</attribute>\n        </xpath>\n        <xpath expr="//span[@id='grouped_line_tax_ids']/.." position="attributes">\n            <attribute name="t-if">not o._l10n_ar_include_vat()</attribute>\n        </xpath>\n        <span id="line_tax_ids" position="attributes">\n            <attribute name="t-out">', '.join(tax.tax_label for tax in line.tax_ids if tax.tax_label and tax.tax_group_id.l10n_ar_vat_afip_code)</attribute>\n        </span>\n\n        <!-- remove payment reference that is not used in Argentina -->\n        <xpath expr="//span[@t-field='o.payment_reference']/../.." position="replace"/>\n\n        <!-- replace information section and usage argentinean style -->\n        <div id="informations" position="replace">\n            <div id="informations" class="row mt8 mb8">\n                <div class="col-6">\n\n                    <!-- IDENTIFICACION (ADQUIRIENTE-LOCATARIO-PRESTARIO) -->\n\n                    <!-- (14) Apellido uy Nombre: Denominicacion o Razon Soclial -->\n                    <t t-if="o.is_sale_document(include_receipts=True)"><strong>Customer: </strong></t>\n                    <t t-else=""><strong>Supplier: </strong></t>\n                    <span t-field="o.partner_id.commercial_partner_id.name"/>\n\n                    <!-- (15) Domicilio Comercial -->\n                    <br/>\n                    <span t-field="o.partner_id" t-options="{'widget': 'contact', 'fields': ['address'], 'no_marker': true, 'no_tag_br': True}"/>\n\n                    <!-- (16) Responsabilidad ARCA -->\n                    <strong>VAT Cond: </strong><span t-field="o.partner_id.l10n_ar_afip_responsibility_type_id"/>\n\n                    <!-- (17) CUIT -->\n                    <t t-if="o.partner_id.l10n_ar_afip_code and o.partner_id.l10n_ar_afip_code != '99'">\n                        <t t-set="ar_doc_vals" t-value="o.partner_id._get_preferred_legal_entity_identifier_vals()"/>\n                        <t t-set="ar_doc_label" t-value="ar_doc_vals.get('label') or o.company_id.account_fiscal_country_id.vat_label"/>\n                        <br/><strong><t t-out="ar_doc_label" id="inv_tax_id_label"/>:</strong> <span t-out="o.partner_id.l10n_ar_formatted_vat or ar_doc_vals.get('value', '')"/>\n                    </t>\n\n                </div>\n                <div class="col-6">\n\n                    <t t-if="o.invoice_date_due">\n                        <strong>Due Date: </strong>\n                        <span t-field="o.invoice_date_due"/>\n                    </t>\n\n                    <t t-if="o.invoice_payment_term_id" name="payment_term">\n                        <br/><strong>Payment Terms: </strong><span t-field="o.invoice_payment_term_id.name"/>\n                    </t>\n\n                    <t t-if="o.invoice_origin">\n                        <br/><strong>Source:</strong>\n                        <span t-field="o.invoice_origin"/>\n                    </t>\n\n                    <t t-if="o.ref">\n                        <br/><strong>Reference:</strong>\n                        <span t-field="o.ref"/>\n                    </t>\n\n                    <!-- (18) REMITOS -->\n                    <!-- We do not have remitos implement yet. print here the remito number when we have it -->\n\n                    <t t-if="o.invoice_incoterm_id">\n                        <br/>\n                        <strong>Incoterm:</strong>\n                        <p t-if="o.incoterm_location">\n                            <span t-field="o.invoice_incoterm_id.code"/> <br/>\n                            <span t-field="o.incoterm_location"/>\n                        </p>\n                        <p t-else="" t-field="o.invoice_incoterm_id.name" class="m-0"/>\n                    </t>\n\n                </div>\n\n            </div>\n        </div>\n\n        <xpath expr="//div[@id='payment_term']" position="before">\n            <div class="mb-4">\n                <t t-if="o.l10n_ar_afip_concept in ['2', '3', '4'] and o.l10n_ar_afip_service_start and o.l10n_ar_afip_service_end">\n                    <strong>Invoiced period: </strong><span t-field="o.l10n_ar_afip_service_start"/> to <span t-field="o.l10n_ar_afip_service_end"/>\n                </t>\n                <t t-if="o.currency_id != o.company_id.currency_id">\n                    <br/><strong>Currency: </strong><span t-out="'%s - %s' % (o.currency_id.name, o.currency_id.currency_unit_label)"/>\n                    <br/><span>1 <t t-out="o.currency_id.name"/> = <t t-out="1 / o.invoice_currency_rate" t-options="{&quot;widget&quot;: &quot;float&quot;, &quot;precision&quot;: 2}"/> <t t-out="o.company_currency_id.name"/></span>\n                </t>\n                <!-- Show CBU for FACTURA DE CREDITO ELECTRONICA MiPyMEs and NOTA DE DEBITO ELECTRONICA MiPyMEs -->\n                <t t-if="o.l10n_latam_document_type_id.code in ['201', '206', '211', '202', '207', '212'] and o.partner_bank_id">\n                    <br/><strong>CBU for payment: </strong><span t-out="o.partner_bank_id.account_number or '' if o.partner_bank_id.account_type == 'cbu' else ''"/>\n                </t>\n\n            </div>\n        </xpath>\n\n        <!-- Show total amount in letters for MiPyMEs document types according to the law\n         http://biblioteca.afip.gob.ar/dcp/LEY_C_027440_2018_05_09 article 5.f -->\n        <xpath expr="//div[@id='total']/div/table" position="after">\n            <t t-if="o.l10n_latam_document_type_id.code in ['201', '202', '203', '206', '207', '208', '211', '212', '213']">\n                <strong>Son: </strong><span t-out="o.currency_id.amount_to_text(o.amount_total)"/>\n            </t>\n        </xpath>\n\n        <!-- RG 5003: Add legend for 'A' documents that have a Monotribuista receptor -->\n        <div name="comment" position="after">\n            <p t-if="o.partner_id.l10n_ar_afip_responsibility_type_id.code in ['6', '13'] and o.l10n_latam_document_type_id.l10n_ar_letter == 'A'">\n                The tax credit specified in this voucher may only be computed for purposes of the Tax Support and Inclusion Regime for Small Taxpayers of Law No. 27,618.\n            </p>\n        </div>\n\n        <t t-call="account.document_tax_totals" position="attributes">\n            <attribute name="t-call">l10n_ar.document_tax_totals</attribute>\n        </t>\n\n        <div id="qrcode" position="after">\n            <!-- RG 5614/2024: Show ARCA VAT and Other National Internal Taxes -->\n            <t t-set="l10n_ar_custom_tax_summary" t-value="o._l10n_ar_get_invoice_custom_tax_summary_for_report()"/>\n            <div t-attf-class="l10n_ar_tax_details {{ 'col-6' if report_type == 'pdf' else '' }}" t-if="l10n_ar_custom_tax_summary">\n                <table class="table table-sm table-borderless" style="page-break-inside: avoid;">\n                    <th class="border-black" style="border-bottom: 1px solid" colspan="2">\n                           Fiscal Transparency Regime for the Final Consumer (Law 27.743)\n                    </th>\n                    <t t-foreach="l10n_ar_custom_tax_summary" t-as="detail">\n                        <tr>\n                            <td class="text-end"><strong t-out="detail['name']"/></td>\n                            <td class="text-end">\n                                <span class="oe_subtotal_footer_separator" t-out="detail['formatted_tax_amount_currency']"/>\n                            </td>\n                        </tr>\n                    </t>\n                </table>\n            </div>\n        </div>\n\n    <xpath expr="." position="attributes"><attribute name="t-name">l10n_ar.report_invoice_document</attribute></xpath></data>\n\n    	\N	f	t	2026-10-26 23:48:36.567735	2026-10-26 23:48:36.567735	f
1118	16	883	1	1	document_tax_totals	\N	l10n_ar.document_tax_totals	qweb	l10n_ar/views/report_invoice.xml	primary	\N	{"en_US": "<data>\\n        <xpath expr=\\"//t[@t-foreach]/tr\\" position=\\"attributes\\">\\n            <!-- Only for the Untaxed Amount  -->\\n            <attribute name=\\"t-if\\">not o._l10n_ar_include_vat()</attribute>\\n        </xpath>\\n    <xpath expr=\\".\\" position=\\"attributes\\"><attribute name=\\"t-name\\">l10n_ar.document_tax_totals</attribute></xpath></data>"}	<?xml version="1.0"?>\n<data>\n        <xpath expr="//t[@t-foreach]/tr" position="attributes">\n            <!-- Only for the Untaxed Amount  -->\n            <attribute name="t-if">not o._l10n_ar_include_vat()</attribute>\n        </xpath>\n    <xpath expr="." position="attributes"><attribute name="t-name">l10n_ar.document_tax_totals</attribute></xpath></data>\n\n    	\N	f	t	2026-10-26 23:48:36.567735	2026-10-26 23:48:36.567735	f
