                         <field name="name"/>\n                                    </page>\n                                    <page string="Section" name="order_section" invisible="display_type != 'line_section'">\n                                        <field name="name"/>\n                                    </page>\n                                    <page string="Note" name="order_note" invisible="display_type != 'line_note'">\n                                        <field name="name"/>\n                                    </page>\n                                </notebook>\n                            </form>\n                            <list name="sotl_list" string="Quotation Template Lines" editable="bottom">\n                                <control>\n                                    <create name="add_product_control" string="Add a product"/>\n                                    <create name="add_section_control" string="Add a section" context="{'default_display_type': 'line_section'}"/>\n                                    <create name="add_note_control" string="Add a note" context="{'default_display_type': 'line_note'}"/>\n                                    <button string="Catalog" name="action_add_from_catalog" type="object" class="px-4 btn-link" context="{'order_id': parent.id}"/>\n                                </control>\n                                <field name="display_type" column_invisible="True"/>\n                                <field name="is_optional" column_invisible="True"/>\n                                <field name="collapse_prices" column_invisible="True"/>\n                                <field name="collapse_composition" column_invisible="True"/>\n                                <field name="product_custom_attribute_value_ids" column_invisible="True">\n                                    <list>\n                                        <field name="custom_product_template_attribute_value_id"/>\n                         