ion\\"/>\\n                        <div>\\n                            <field name=\\"description\\" placeholder=\\"p. ej. Regístrese en la plataforma\\" class=\\"w-100\\"/>\\n                        </div>\\n\\n                        <group string=\\"¿Cómo se calcula la meta?\\" name=\\"compute_details\\">\\n\\n                            <field widget=\\"radio\\" name=\\"computation_mode\\"/>\\n\\n                            <!-- Hide the fields below if manually -->\\n                            <field name=\\"model_id\\" class=\\"oe_inline\\" invisible=\\"computation_mode not in ('sum', 'count')\\" required=\\"computation_mode in ('sum', 'count')\\"/>\\n                            <field name=\\"model_inherited_ids\\" invisible=\\"1\\"/>\\n                            <field name=\\"field_id\\" class=\\"oe_inline\\" options=\\"{'no_create': True}\\" invisible=\\"computation_mode != 'sum'\\" required=\\"computation_mode == 'sum'\\"/>\\n                            <field name=\\"field_date_id\\" class=\\"oe_inline\\" invisible=\\"computation_mode not in ('sum', 'count')\\"/>\\n                            <field name=\\"domain\\" invisible=\\"computation_mode not in ('sum', 'count')\\" required=\\"computation_mode in ('sum', 'count')\\" class=\\"oe_inline\\"/>\\n                            <field name=\\"compute_code\\" invisible=\\"computation_mode != 'python'\\" required=\\"computation_mode == 'python'\\"/>\\n                            <field name=\\"condition\\" widget=\\"radio\\"/>\\n                        </group>\\n                        <group string=\\"Optimización\\" name=\\"optimisation\\" invisible=\\"computation_mode not in ('sum', 'count')\\">\\n                            <field name=\\"batch_mode\\"/>\\n                            <div colspan=\\"2\\">En el modo de proceso por lotes, el dominio se evalúa globalmente. Si está habilitado, no utilices la palabra clave 'user' en el filtro de dominio que está a continuación.</div>\\n                   