tton_box\\" name=\\"button_box\\">\\n                        <button class=\\"oe_stat_button\\" name=\\"action_bill_matching\\" type=\\"object\\" groups=\\"account.group_account_invoice\\" invisible=\\"not partner_id or state != 'purchase' or not partner_bill_count\\">\\n                            <field name=\\"bill_matched_ratio\\" string=\\"Bill Matching\\" widget=\\"percentpie\\"/>\\n                        </button>\\n                        <button type=\\"object\\" name=\\"action_view_invoice\\" class=\\"oe_stat_button\\" icon=\\"edit_square\\" invisible=\\"invoice_count == 0 or state in ('draft', 'sent', 'to approve')\\">\\n                            <field name=\\"invoice_count\\" widget=\\"statinfo\\" string=\\"Vendor Bills\\"/>\\n                            <field name=\\"invoice_ids\\" invisible=\\"1\\"/>\\n                        </button>\\n                        <button type=\\"object\\" name=\\"action_purchase_comparison\\" class=\\"oe_stat_button\\" invisible=\\"not show_comparison\\" icon=\\"attach_money\\">\\n                            <div class=\\"o_field_statinfo\\">\\n                                <span class=\\"o_stat_text\\">Price Comparison</span>\\n                            </div>\\n                            <field name=\\"show_comparison\\" invisible=\\"1\\"/>\\n                        </button>\\n                    </div>\\n                    <div class=\\"badge rounded-pill text-bg-secondary float-end fs-6 border-0\\" invisible=\\"not locked\\">\\n                        <i class=\\"oi\\" data-icon=\\"lock\\"/>\\n                        Locked\\n                    </div>\\n                    <div class=\\"oe_title\\">\\n                        <span class=\\"o_form_label\\" invisible=\\"state not in ('draft', 'sent')\\">Request for Quotation</span>\\n                        <span class=\\"o_form_label\\" invisible=\\"state in ('draft', 'sent')\\">Purchase Order</span>\\n                        <h1 class=\\"o_outlined d-flex align-items-center gap-2\\">\\n                            <field name=\\"priority\\" widget=\\"priority\\"/>\\n                            <field name=\\"name\\" readonly=\\"1\\"/>\\n                        </h1>\\n                    </div>\\n                    <group>\\n                        <group>\\n                            <field name=\\"partner_id\\" widget=\\"res_partner_many2one\\" context=\\"{'res_partner_search_mode': 'supplier', 'show_identifier': True}\\" placeholder=\\"Name, TIN, Email, or Reference\\" readonly=\\"state in ['cancel', 'purchase']\\"/>\\n                            <field name=\\"partner_ref\\"/>\\n                            <field name=\\"currency_id\\" groups=\\"base.group_multi_currency\\" force_save=\\"1\\" readonly=\\"state in ['cancel', 'purchase']\\"/>\\n                            <field name=\\"payment_term_id\\" readonly=\\"invoice_status == 'invoiced' or locked\\" options=\\"{'no_create': True}\\"/>\\n                            <field name=\\"id\\" invisible=\\"1\\"/>\\n                            <field name=\\"company_id\\" invisible=\\"1\\" readonly=\\"state in ['cancel', 'purchase']\\"/>\\n                            <field name=\\"currency_id\\" invisible=\\"1\\" readonly=\\"state in ['cancel', 'purchase']\\" groups=\\"!base.group_multi_currency\\"/>\\n                            <field name=\\"tax_calculation_rounding_method\\" invisible=\\"1\\"/>\\n                        </group>\\n                        <group>\\n                            <label for=\\"date_order\\" invisible=\\"state == 'purchase'\\"/>\\n                            <div class=\\"o_row d-flex\\" invisible=\\"state == 'purchase'\\">\\n                                <field name=\\"date_order\\" nolabel=\\"1\\" readonly=\\"state == 'cancel'\\" class=\\"flex-grow-0\\" style=\\" width: auto !important;\\" decoration-danger=\\"date_order and date_order &lt; context_today().strftime('%Y-%m-%d')\\"/>\\n                                <button title=\\"Reset to today's date to recompute expected arrival based on available lead time                                     and previous information from the RFQ.\\" name=\\"button_reset_date_order\\" type=\\"object\\" icon=\\"refresh\\" class=\\"btn-link p-0 ms-2\\" invisible=\\"date_order and date_order &gt;= context_today().strftime('%Y-%m-%d')\\"/>\\n                            </div>\\n                            <label for=\\"date_planned\\"/>\\n                            <div name=\\"date_planned_div\\">\\n                                <field name=\\"date_planned\\" readonly=\\"state not in ('draft', 'sent', 'to approve', 'purchase')\\"/>\\n                            </div>\\n                            <label for=\\"receipt_reminder_email\\" string=\\"Arrival Confirmation\\" groups=\\"purchase.group_send_reminder\\"/>\\n                            <div name=\\"reminder\\" class=\\"o_row\\" groups=\\"purchase.group_send_reminder\\" title=\\"Automatically send a confirmation email to the vendor X days before the expected receipt date, asking him to confirm the exact date.\\">\\n                                <field name=\\"receipt_reminder_email\\"/>\\n                                <field name=\\"reminder_date_before_receipt\\" class=\\"mb-0\\" invisible=\\"not receipt_reminder_email\\" style=\\"max-width: 30px;\\"/>\\n                                <span invisible=\\"not receipt_reminder_email\\">day(s) before</span>\\n                                <widget name=\\"toaster_button\\" button_name=\\"send_reminder_preview\\" additionalClasses=\\"o_external_button py-0\\" title=\\"Preview the reminder email by sending it to yourself.\\" invisible=\\"not receipt_reminder_email or not id\\"/>\\n                            </div>\\n                            <label for=\\"receipt_status\\" invisible=\\"state !='purchase'\\"/>\\n                                <div class=\\"d-flex align-items-center\\" invisible=\\"state !='purchase'\\">\\n                                    <div name=\\"receipt_status_on_form\\" class=\\"me-3\\">\\n                                        <field name=\\"receipt_status\\" widget=\\"badge\\" invisible=\\"state != 'purchase'\\" decoration-success=\\"receipt_status == 'full'\\" decoration-info=\\"receipt_status == 'partial'\\" decoration-danger=\\"receipt_status == 'pending' and date_planned and date_planned &lt; context_today().strftime('%Y-%m-%d')\\"/>\\n                                    </div>\\n                                </div>\\n                        </group>\\n                        <div>\\n                            <field name=\\"document_tax_mode\\" class=\\"tax_mode_badge d-md-none\\" widget=\\"document_tax_mode_selector\\" nolabel=\\"True\\" readonly=\\"state != 'draft'\\"/>\\n                        </div>\\n                    </group>\\n                    <notebook>\\n                        <page string=\\"Products\\" name=\\"products\\">\\n                            <div class=\\"position-relative document_tax_mode\\">\\n                                <field name=\\"document_tax_mode\\" class=\\"overlap_badge_tab tax_mode_badge d-none d-md-block\\" widget=\\"document_tax_mode_selector\\" nolabel=\\"True\\" readonly=\\"state != 'draft'\\"/>\\n                            </div>\\n                            <field name=\\"tax_country_id\\" invisible=\\"1\\"/>\\n                            <field name=\\"order_line\\" widget=\\"product_label_section_and_note_field_o2m\\" mode=\\"list,kanban\\" aggregated_fields=\\"price_subtotal\\" context=\\"{'default_state': 'draft'}\\" readonly=\\"state == 'cancel' or locked\\" options=\\"{ 'subsections': True }\\">\\n                                <list string=\\"Purchase Order Lines\\" editable=\\"bottom\\" decoration-warning=\\"purchase_line_warn_msg\\">\\n                                    <control>\\n                                        <create name=\\"add_product_control\\" string=\\"Add a product\\" data-hotkey=\\"