ntext=\\"{'partner_id':partner_id, 'quantity':product_qty, 'company_id': parent.company_id}\\" force_save=\\"1\\" domain=\\"[('purchase_ok', '=', True), '|', ('company_id', '=', False), ('company_id', 'parent_of', parent.company_id)]\\" invisible=\\"display_type\\" placeholder=\\"Select a Product\\"/>\\n                                        <field name=\\"name\\" decoration-warning=\\"not display_type and not product_id\\" placeholder=\\"Enter a Description...\\" optional=\\"show\\"/>\\n                                        <field name=\\"label\\" widget=\\"text\\" invisible=\\"display_type\\"/>\\n                                    </column>\\n                                    <field name=\\"date_planned\\" optional=\\"hide\\" required=\\"not display_type and not is_downpayment\\" force_save=\\"1\\" readonly=\\"is_downpayment\\"/>\\n                                    <field name=\\"analytic_distribution\\" widget=\\"analytic_distribution\\" groups=\\"analytic.group_analytic_accounting\\" options=\\"{'product_field': 'product_id', 'business_domain': 'purchase_order', 'amount_field': 'price_subtotal'}\\"/>\\n                                    <field name=\\"product_qty\\" readonly=\\"is_downpayment\\"/>\\n                                    <field name=\\"qty_received_manual\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"qty_received_method\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"qty_received\\" string=\\"Received\\" column_invisible=\\"parent.state != 'purchase'\\" readonly=\\"qty_received_method != 'manual' or is_downpayment\\" optional=\\"show\\"/>\\n                                    <field name=\\"qty_invoiced\\" string=\\"Billed\\" column_invisible=\\"parent.state != 'purchase'\\" optional=\\"show\\"/>\\n                                    <field name=\\"uom_id\\" groups=\\"uom.group_uom\\" readonly=\\"state in ('purchase', 'cancel') or is_downpayment\\" required=\\"no