                                             Tax incl.: <field name=\\"price_total\\"/>\\n                                                    </span>\\n                                                </div>\\n                                                <span class=\\"text-muted\\">\\n                                                    Unit Price:\\n                                                    <field name=\\"price_unit\\"/>\\n                                                </span>\\n                                                <span class=\\"text-muted\\" t-if=\\"record.discount.raw_value\\">\\n                                                    Discount: <field name=\\"discount\\"/>%\\n                                                </span>\\n                                            </t>\\n                                            <div t-elif=\\"['line_section', 'line_subsection', 'line_note'].includes(record.display_type.raw_value)\\">\\n                                                <div t-att-class=\\"{                                                     'fw-bolder': record.display_type.raw_value === 'line_section',                                                     'fw-bold': record.display_type.raw_value === 'line_subsection',                                                     'fst-italic': record.display_type.raw_value === 'line_note',                                                 }\\">\\n                                                    <field name=\\"name\\"/>\\n                                                </div>\\n                                            </div>\\n                                         </t>\\n                                     </templates>\\n                                 </kanban>\\n                            </field>\\n                            <group>\\n                                <group>\\n                                    <field colspan=\\"2\\" name=\\"note\\" nolabel=\\"1\\" placeholder=\\