no_create': True}\\"/>\\n                                            </group>\\n                                            <group>\\n                                                <field name=\\"date_planned\\" required=\\"not display_type and not is_downpayment\\"/>\\n                                                <field name=\\"analytic_distribution\\" widget=\\"analytic_distribution\\" groups=\\"analytic.group_analytic_accounting\\" options=\\"{'product_field': 'product_id', 'business_domain': 'purchase_order'}\\"/>\\n                                            </group>\\n                                            <group>\\n                                            <notebook colspan=\\"4\\">\\n                                                <page string=\\"Notas\\" name=\\"notes\\">\\n                                                    <field name=\\"name\\"/>\\n                                                </page>\\n                                                <page string=\\"Facturas y recepciones\\" name=\\"invoices_incoming_shiptments\\">\\n                                                    <field name=\\"invoice_lines\\"/>\\n                                                </page>\\n                                            </notebook>\\n                                            </group>\\n                                        </group>\\n                                        <label for=\\"name\\" string=\\"Nombre de la sección (p. ej., productos, servicios)\\" invisible=\\"display_type != 'line_section'\\"/>\\n                                        <label for=\\"name\\" string=\\"Nombre de la subsección\\" invisible=\\"display_type != 'line_subsection'\\"/>\\n                                        <label for=\\"name\\" string=\\"Nota\\" invisible=\\"display_type != 'line_note'\\"/>\\n                                        <field name=\\"name\\" nolabel=\\"1\\" invisible=\\"not display_type\\"/>\\n                                </form>\