                                     <field name=\\"uom_id\\" groups=\\"uom.group_uom\\" class=\\"small\\"/>\\n                                                    </span>\\n                                                    <span class=\\"fw-bold col-4\\" t-if=\\"record.tax_calculation_rounding_method.raw_value === 'round_per_line'\\">\\n                                                        Impuestos incluidos: <field name=\\"price_total\\"/>\\n                                                    </span>\\n                                                </div>\\n                                                <span class=\\"text-muted\\">\\n                                                    Precio unitario:\\n                                                    <field name=\\"price_unit\\"/>\\n                                                </span>\\n                                                <span class=\\"text-muted\\" t-if=\\"record.discount.raw_value\\">\\n                                                    Descuento: <field name=\\"discount\\"/>%\\n                                                </span>\\n                                            </t>\\n                                            <div t-elif=\\"['line_section', 'line_subsection', 'line_note'].includes(record.display_type.raw_value)\\">\\n                                                <div t-att-class=\\"{                                                     'fw-bolder': record.display_type.raw_value === 'line_section',                                                     'fw-bold': record.display_type.raw_value === 'line_subsection',                                                     'fst-italic': record.display_type.raw_value === 'line_note',                                                 }\\">\\n                                                    <field name=\\"name\\"/>\\n                                                </div>\\n                                            </div>\\n                                         </t>\\n                                     </templates>\\n                                 </kanban>\\n                            </field>\\n                            <group>\\n                                <group>\\n                                    <field colspan=\\"2\\" name=\\"note\\" nolabel=\\"1\\" placeholder=\\"Defina sus términos y condiciones ...\\"/>\\n                                </group>\\n                                <group class=\\"oe_subtotal_footer border-top-0\\">\\n                                    <field name=\\"tax_totals\\" widget=\\"account-tax-totals-field\\" nolabel=\\"1\\" readonly=\\"1\\"/>\\n                                </group>\\n                            </group>\\n                            <div class=\\"clearfix\\"/>\\n                        </page>\\n                        <page string=\\"Other Info\\" name=\\"purchase_delivery_invoice\\">\\n                            <group>\\n                                <group name=\\"purchase_info\\" string=\\"purchase\\">\\n                                    <field name=\\"user_id\\" domain=\\"[('share', '=', False)]\\" widget=\\"many2one_avatar_user\\"/>\\n                                    <field name=\\"company_id\\" groups=\\"base.group_multi_company\\" options=\\"{'no_create': True}\\" readonly=\\"state in ['cancel', 'purchase']\\"/>\\n                                    <field name=\\"date_approve\\" invisible=\\"state not in ('purchase', 'cancel')\\"/>\\n                                </group>\\n                                <group name=\\"billing_info\\" string=\\"billing\\">\\n                                    <field name=\\"invoice_status\\" invisible=\\"state in ('draft', 'sent', 'to approve', 'cancel')\\"/>\\n                                    <field name=\\"fiscal_position_id\\" options=\\"{'no_create': True}\\" readonly=\\"invoice_status == 'invoiced' or locked\\"/>\\n                                    <field name=\\"incoterm_id\\" readonly=\\"locked\\"/>\\n                                    <field name=\\"incoterm_location\\" readonly=\\"locked\\"/>\\n                                </group>\\n                                <group name=\\"tracking_info\\" string=\\"tracking\\">\\n                                    <field name=\\"origin\\"/>\\n                                </group>\\n                            </group>\\n                        </page>\\n                    </notebook>\\n                </sheet>\\n                <chatter/>\\n                </form>"}	<?xml version="1.0"?>\n<form string="Purchase Order" class="o_purchase_order">\n                <header>\n                    <field name="locked" invisible="1"/>\n                    <field name="lock_confirmed_po" invisible="1"/>\n                    <button name="action_rfq_send" invisible="state != 'draft'" string="Send RFQ" type="object" context="{'send_rfq':True}" class="oe_highlight" data-hotkey="g"/>\n                    <button name="button_confirm" type="object" invisible="state != 'sent'" string="Confirm Order" context="{'validate_analytic': True}" class="oe_highlight" id="bid_confirm" data-hotkey="q"/>\n                    <button name="button_approve" type="object" invisible="state != 'to approve'" string="Approve Order" class="oe_highlight" groups="purchase.group_purchase_manager" data-hotkey="z"/>\n                    <button name="action_rfq_send" invisible="state != 'sent'" string="Send RFQ" type="object" context="{'send_rfq':True}" data-hotkey="g"/>\n                    <button name="button_confirm" type="object" invisible="state != 'draft'" context="{'validate_analytic': True}" string="Confirm Order" id="draft_confirm" data-hotkey="q"/>\n                    <button name="action_receive" class="btn-primary" type="object" string="Receive" data-hotkey="e" invisible="not show_receive_button"/>\n                    <widget name="purchase_file_uploader" invisible="state != 'purchase'"/>\n                    <button name="action_rfq_send" invisible="state != 'purchase'" string="Send PO" type="object" context="{'send_rfq':False}" data-hotkey="g"/>\n                    <button name="action_acknowledge" string="Acknowledge" type="object" invisible="acknowledged or state != 'purchase'" data-hotkey="a"/>\n                    <button name="button_draft" invisible="state != 'cancel'" string="Set to Draft" type="object" data-hotkey="o"/>\n                    <button name="728" string="Print" type="action" groups="base.group_user" data-hotkey="k" invisible="state == 'purchase'"/>\n                    <button name="727" string="Print" type="action" groups="base.group_user" data-hotkey="k" invisible="state != 'purchase'"/>\n                    <button name="button_cancel" invisible="state not in ('draft', 'to approve', 'sent', 'purchase') or locked" string="Cancel" type="object" data-hotkey="x"/>\n                    <button name="button_lock" type="object" string="Lock" invisible="locked or state != 'purchase' or not lock_confirmed_po == 'lock'" data-hotkey="l"/>\n                    <button name="button_unlock" type="object" string="Unlock" invisible="not locked" groups="purchase.group_purchase_manager" data-hotkey="l"/>\n                    <field name="state" widget="statusbar" statusbar_visible="draft,purchase" readonly="1"/>\n                </header>\n                <div class="alert alert-warning" role="alert" invisible="not purchase_warning_text">\n                    <field name="purchase_warning_text" class="fw-bold"/>\n                </div>\n                <div class="alert alert-warning w-100 d-flex align-items-center gap-1" invisible="state != 'draft' or not duplicated_order_ids" role="alert">\n                    <span>Warning: this order might be a duplicate of</span>\n                    <field name="duplicated_order_ids" widget="x2many_buttons" string="Duplicated Documents"/>\n                </div>\n                <sheet>\n                    <div class="oe_button_box" name="button_box">\n                        <button class="oe_stat_button" name="action_bill_matching" type="object" groups="account.group_account_invoice" invisible="not partner_id or state != 'purchase' or not partner_bill_count">\n                            <field name="bill_matched_ratio" string="Bill Matching" widget="percentpie"/>\n                        </button>\n                        <button type="object" name="action_view_invoice" class="oe_stat_button" icon="edit_square" invisible="invoice_count == 0 or state in ('draft', 'sent', 'to approve')">\n                            <field name="invoice_count" widget="statinfo" string="Vendor Bills"/>\n                            <field name="invoice_ids" invisible="1"/>\n                        </button>\n                        <button type="object" name="action_purchase_comparison" class="oe_stat_button" invisible="not show_comparison" icon="attach_money">\n                            <div class="o_field_statinfo">\n                                <span class="o_stat_text">Price Comparison</span>\n                            </div>\n                            <field name="show_comparison" invisible="1"/>\n                        </button>\n                    </div>\n                    <div class="badge rounded-pill text-bg-secondary float-end fs-6 border-0" invisible="not locked">\n                        <i class="oi" data-icon="lock"/>\n                        Locked\n                    </div>\n                    <div class="oe_title">\n                        <span class="o_form_label" invisible="state not in ('draft', 'sent')">Request for Quotation</span>\n                        <span class="o_form_label" invisible="state in ('draft', 'sent')">Purchase Order</span>\n                        <h1 class="o_outlined d-flex align-items-center gap-2">\n                            <field name="priority" widget="priority"/>\n                            <field name="name" readonly="1"/>\n                        </h1>\n                    </div>\n                    <group>\n                        <group>\n                            <field name="partner_id" widget="res_partner_many2one" context="{'res_partner_search_mode': 'supplier', 'show_identifier': True}" placeholder="Name, TIN, Email, or Reference" readonly="state in ['cancel', 'purchase']"/>\n                            <field name="partner_ref"/>\n                            <field name="currency_id" groups="base.group_multi_currency" force_save="1" readonly="state in ['cancel', 'purchase']"/>\n                            <field name="payment_term_id" readonly="invoice_status == 'invoiced' or locked" options="{'no_create': True}"/>\n                            <field name="id" invisible="1"/>\n                            <field name="company_id" invisible="1" readonly="state in ['cancel', 'purchase']"/>\n                            <field name="currency_id" invisible="1" readonly="state in ['cancel', 'purchase']" groups="!base.group_multi_currency"/>\n                            <field name="tax_calculation_rounding_method" invisible="1"/>\n                        </group>\n                        <group>\n                            <label for="date_order" invisible="state == 'purchase'"/>\n                            <div class="o_row d-flex" invisible="state == 'purchase'">\n                                <field name="date_order" nolabel="1" readonly="state == 'cancel'" class="flex-grow-0" style=" width: auto !important;" decoration-danger="date_order and date_order &lt; context_today().strftime('%Y-%m-%d')"/>\n                                <button title="Reset to today's date to recompute expected arrival based on available lead time                                     and previous information from the RFQ." name="button_reset_date_order" type="object" icon="refresh" class="btn-link p-0 ms-2" invisible="date_order and date_order &gt;= context_today().strftime('%Y-%m-%d')"/>\n                            </div>\n                            <label for="date_planned"/>\n                            <div name="date_planned_div">\n                                <field name="date_planned" readonly="state not in ('draft', 'sent', 'to approve', 'purchase')"/>\n                            </div>\n                            <label for="receipt_reminder_email" string="Arrival Confirmation" groups="purchase.group_send_reminder"/>\n                            <div name="reminder" class="o_row" groups="purchase.group_send_reminder" title="Automatically send a confirmation email to the vendor X days before the expected receipt date, asking him to confirm the exact date.">\n                                <field name="receipt_reminder_email"/>\n                                <field name="reminder_date_before_receipt" class="mb-0" invisible="not receipt_reminder_email" style="max-width: 30px;"/>\n                                <span invisible="not receipt_reminder_email">day(s) before</span>\n                                <widget name="toaster_button" button_name="send_reminder_preview" additionalClasses="o_external_button py-0" title="Preview the reminder email by sending it to yourself." invisible="not receipt_reminder_email or not id"/>\n                            </div>\n                            <label for="receipt_status" invisible="state !='purchase'"/>\n                                <div class="d-flex align-items-center" invisible="state !='purchase'">\n                                    <div name="receipt_status_on_form" class="me-3">\n                                        <field name="receipt_status" widget="badge" invisible="state != 'purchase'" decoration-success="receipt_status == 'full'" decoration-info="receipt_status == 'partial'" decoration-danger="receipt_status == 'pending' and date_planned and date_planned &lt; context_today().strftime('%Y-%m-%d')"/>\n                                    </div>\n                                </div>\n                        </group>\n                        <div>\n                            <field name="document_tax_mode" class="tax_mode_badge d-md-none" widget="document_tax_mode_selector" nolabel="True" readonly="state != 'draft'"/>\n                        </div>\n                    </group>\n                    <notebook>\n                        <page string="Products" name="products">\n                            <div class="position-relative document_tax_mode">\n                                <field name="document_tax_mode" class="overlap_badge_tab tax_mode_badge d-none d-md-block" widget="document_tax_mode_selector" nolabel="True" readonly="state != 'draft'"/>\n                            </div>\n                            <field name="tax_country_id" invisible="1"/>\n                            <field name="order_line" widget="product_label_section_and_note_field_o2m" mode="list,kanban" aggregated_fields="price_subtotal" context="{'default_state': 'draft'}" readonly="state == 'cancel' or locked" options="{ 'subsections': True }">\n                                <list string="Purchase Order Lines" editable="bottom" decoration-warning="purchase_line_warn_msg">\n                                    <control>\n                                        <create name="add_product_control" string="Add a product" data-hotkey="shift+p"/>\n                                        <create name="add_section_control" string="Add a section" data-hotkey="shift+h" context="{'default_display_type': 'line_section'}"/>\n                                        <create name="add_note_control" string="Add a note" data-hotkey="shift+n" context="{'default_display_type': 'line_note'}"/>\n                                        <button name="action_add_from_catalog" string="Catalog" data-hotkey="shift+k" type="object" class="px-4 btn-link" context="{'order_id': parent.id}"/>\n                                    </control>\n                                    <field name="tax_calculation_rounding_method" column_invisible="True"/>\n                                    <field name="display_type" column_invisible="True"/>\n                                    <field name="company_id" column_invisible="True"/>\n                                    <field name="currency_id" column_invisible="True"/>\n                                    <field name="state" column_invisible="True"/>\n                                    <field name="product_type" column_invisible="True"/>\n                                    <field name="invoice_lines" column_invisible="True"/>\n                                    <field name="technical_price_unit" column_invisible="True"/>\n                                    <field name="sequence" widget="handle"/>\n                                    <!-- optional="show" allows name (description) to be editable -->\n                                    <column name="product_and_description">\n                                        <field name="product_id" widget="account_product_field" readonly="state in ('purchase', 'to approve', 'cancel') or is_downpayment" required="not display_type and not is_downpayment" optional="show" context="{'partner_id':partner_id, 'quantity':product_qty, 'company_id': parent.company_id}" force_save="1" domain="[('purchase_ok', '=', True), '|', ('company_id', '=', False), ('company_id', 'parent_of', parent.company_id)]" invisible="display_type" placeholder="Select a Product"/>\n                                        <field name="name" decoration-warning="not display_type and not product_id" placeholder="Enter a Description..." optional="show"/>\n                                        <field name="label" widget="text" invisible="display_type"/>\n                                    </column>\n                                    <field name="date_planned" optional="hide" required="not display_type and not is_downpayment" force_save="1" readonly="is_downpayment"/>\n                                    <field name="analytic_distribution" widget="analytic_distribution" groups="analytic.group_analytic_accounting" options="{'product_field': 'product_id', 'business_domain': 'purchase_order', 'amount_field': 'price_subtotal'}"/>\n                                    <field name="product_qty" readonly="is_downpayment"/>\n                                    <field name="qty_received_manual" column_invisible="True"/>\n                                    <field name="qty_received_method" column_invisible="True"/>\n                                    <field name="qty_received" string="Received" column_invisible="parent.state != 'purchase'" readonly="qty_received_method != 'manual' or is_downpayment" optional="show"/>\n                                    <field name="qty_invoiced" string="Billed" column_invisible="parent.state != 'purchase'" optional="show"/>\n                                    <field name="uom_id" groups="uom.group_uom" readonly="state in ('purchase', 'cancel') or is_downpayment" required="not display_type and not is_downpayment" options="{'no_create': True, 'no_open': True, 'quantity_field': 'product_qty'}" widget="many2one_uom" force_save="1" optional="show"/>\n                                    <field name="price_unit" readonly="qty_invoiced != 0"/>\n                                    <field name="tax_ids" widget="many2many_tax_tags" domain="[('type_tax_use', '=', 'purchase'), ('company_id', 'parent_of', parent.company_id), ('country_id', '=', parent.tax_country_id), ('active', '=', True)]" context="{'default_type_tax_use': 'purchase', 'search_view_ref': 'account.account_tax_view_search'}" options="{'no_create': True}" optional="show" readonly="is_downpayment"/>\n                                    <field name="discount" string="Disc.%" width="50px" readonly="qty_invoiced != 0" optional="hide"/>\n                                    <field name="price_subtotal" string="Amount" column_invisible="parent.document_tax_mode == 'tax_included'"/>\n                                    <field name="price_total" string="Amount" column_invisible="parent.document_tax_mode == 'tax_excluded'"/>\n                                </list>\n                                <form string="Purchase Order Line">\n                                        <field name="tax_calculation_rounding_method" invisible="1"/>\n                                        <field name="state" invisible="1"/>\n                                        <field name="display_type" invisible="1"/>\n                                        <field name="company_id" invisible="1"/>\n                                        <group invisible="display_type">\n                                            <group>\n                                                <field name="product_id" context="{'partner_id': parent.partner_id}" widget="many2one_barcode" domain="[('purchase_ok', '=', True), '|', ('company_id', '=', False), ('company_id', '=', parent.company_id)]" readonly="state in ('purchase', 'to approve', 'cancel')"/>\n                                                <label for="product_qty"/>\n                                                <div class="o_row">\n                                                    <field name="product_qty"/>\n                                                    <field name="uom_id" groups="uom.group_uom" readonly="state in ('purchase', 'cancel') or is_downpayment" required="not display_type and not is_downpayment" widget="many2one_uom" options="{'no_create': True, 'no_open': True}"/>\n                                                </div>\n                                                <field name="qty_received_method" invisible="1"/>\n                                                <field name="qty_received" string="Received Quantity" invisible="parent.state != 'purchase'" readonly="qty_received_method != 'manual'"/>\n                                                <field name="qty_invoiced" string="Billed Quantity" invisible="parent.state != 'purchase'"/>\n                                                <field name="price_unit"/>\n                                                <field name="discount"/>\n                                                <field name="tax_ids" widget="many2many_tax_tags" domain="[('type_tax_use', '=', 'purchase'), ('company_id', 'parent_of', parent.company_id), ('country_id', '=', parent.tax_country_id)]" options="{'no_create': True}"/>\n                                            </group>\n                                            <group>\n                                                <field name="date_planned" required="not display_type and not is_downpayment"/>\n                                                <field name="analytic_distribution" widget="analytic_distribution" groups="analytic.group_analytic_accounting" options="{'product_field': 'product_id', 'business_domain': 'purchase_order'}"/>\n                                            </group>\n                                            <group>\n                                            <notebook colspan="4">\n                                                <page string="Notes" name="notes">\n                                                    <field name="name"/>\n                                                </page>\n                                                <page string="Invoices and Incoming Shipments" name="invoices_incoming_shiptments">\n                                                    <field name="invoice_lines"/>\n                                                </page>\n                                            </notebook>\n                                            </group>\n                                        </group>\n                                        <label for="name" string="Section Name (eg. Products, Services)" invisible="display_type != 'line_section'"/>\n                                        <label for="name" string="Subsection Name" invisible="display_type != 'line_subsection'"/>\n                                        <label for="name" string="Note" invisible="display_type != 'line_note'"/>\n                                        <field name="name" nolabel="1" invisible="not display_type"/>\n                                </form>\n                                <kanban class="o_kanban_mobile">\n                                     <field name="display_type"/>\n                                     <field name="tax_calculation_rounding_method"/>\n                                     <control>\n                                        <create name="add_product_control" string="Add product"/>\n                                        <create name="add_section_control" string="Add section" context="{'default_display_type': 'line_section'}"/>\n                                        <create name="add_note_control" string="Add note" context="{'default_display_type': 'line_note'}"/>\n                                        <button name="action_add_from_catalog" string="Catalog" type="object" context="{'order_id': parent.id}"/>\n                                     </control>\n                                     <templates>\n                                         <t t-name="card">\n                                            <t t-if="!record.display_type.raw_value">\n                                                <div class="row">\n                                                    <field name="product_id" class="fw-bold col-8"/>\n                                                    <span class="fw-bold col-4">\n                                                        Tax excl.: <field name="price_subtotal" class="float-end"/>\n                                                    </span>\n                                                </div>\n                                                <div class="row">\n                                                    <span class="col-8 text-muted">\n                                                        Quantity:\n                                                        <field name="product_qty"/>\n                                                        <field name="uom_id" groups="uom.group_uom" class="small"/>\n                                                    </span>\n                                                    <span class="fw-bold col-4" t-if="record.tax_calculation_rounding_method.raw_value === 'round_per_line'">\n                                                        Tax incl.: <field name="price_total"/>\n                                                    </span>\n                                                </div>\n                                                <span class="text-muted">\n                                                    Unit Price:\n                                                    <field name="price_unit"/>\n                                                </span>\n                                                <span class="text-muted" t-if="record.discount.raw_value">\n                                                    Discount: <field name="discount"/>%\n                                                </span>\n                                            </t>\n                                            <div t-elif="['line_section', 'line_subsection', 'line_note'].includes(record.display_type.raw_value)">\n                                                <div t-att-class="{                                                     'fw-bolder': record.display_type.raw_value === 'line_section',                                                     'fw-bold': record.display_type.raw_value === 'line_subsection',                                                     'fst-italic': record.display_type.raw_value === 'line_note',                                                 }">\n                                                    <field name="name"/>\n                                                </div>\n                                            </div>\n                                         </t>\n                                     </templates>\n                                 </kanban>\n                            </field>\n                            <group>\n                                <group>\n                                    <field colspan="2" name="note" nolabel="1" placeholder="Define your terms and conditions ..."/>\n                                </group>\n                                <group class="oe_subtotal_footer border-top-0">\n                                    <field name="tax_totals" widget="account-tax-totals-field" nolabel="1" readonly="1"/>\n                                </group>\n                            </group>\n                            <div class="clearfix"/>\n                        </page>\n                        <page string="Other Info" name="purchase_delivery_invoice">\n                            <group>\n                                <group name="purchase_info" string="purchase">\n                                    <field name="user_id" domain="[('share', '=', False)]" widget="many2one_avatar_user"/>\n                                    <field name="company_id" groups="base.group_multi_company" options="{'no_create': True}" readonly="state in ['cancel', 'purchase']"/>\n                                    <field name="date_approve" invisible="state not in ('purchase', 'cancel')"/>\n                                </group>\n                                <group name="billing_info" string="billing">\n                                    <field name="invoice_status" invisible="state in ('draft', 'sent', 'to approve', 'cancel')"/>\n                                    <field name="fiscal_position_id" options="{'no_create': True}" readonly="invoice_status == 'invoiced' or locked"/>\n                                    <field name="incoterm_id" readonly="locked"/>\n                                    <field name="incoterm_location" readonly="locked"/>\n                                </group>\n                                <group name="tracking_info" string="tracking">\n                                    <field name="origin"/>\n                                </group>\n                            </group>\n                        </page>\n                    </notebook>\n                </sheet>\n                <chatter/>\n                </form>\n            	\N	f	t	2026-10-27 00:01:55.233435	2026-10-27 00:01:55.233435	f
