                  </group>\\n                                    <group string=\\"Contacto de emergencia\\">\\n                                        <field name=\\"emergency_contact\\" string=\\"Nombre del contacto\\"/>\\n                                        <field name=\\"emergency_phone_sanitized\\" invisible=\\"1\\"/>\\n                                        <field name=\\"emergency_phone_formatted\\" invisible=\\"1\\"/>\\n                                        <field name=\\"emergency_phone\\" widget=\\"phone\\" class=\\"o_force_ltr\\" string=\\"Teléfono\\"/>\\n                                    </group>\\n                                    <group string=\\"Ubicación\\" name=\\"hr_location_group\\">\\n                                        <label for=\\"private_street\\" string=\\"Dirección privada\\"/>\\n                                        <div class=\\"o_address_format o_hr_address\\">\\n                                            <field name=\\"private_street\\" placeholder=\\"Calle...\\" class=\\"o_address_street\\"/>\\n                                            <field name=\\"private_street2\\" placeholder=\\"Calle 2...\\" class=\\"o_address_street\\"/>\\n                                            <field name=\\"private_city\\" placeholder=\\"Ciudad\\" class=\\"o_address_city\\"/>\\n                                            <field name=\\"private_state_id\\" class=\\"o_address_state\\" placeholder=\\"Provincia\\" options=\\"{&quot;no_open&quot;: True, &quot;no_create&quot;: True}\\" context=\\"{'default_country_id': private_country_id}\\" domain=\\"[('id', 'in', allowed_country_state_ids)]\\"/>\\n                                            <field name=\\"private_zip\\" placeholder=\\"C.P.\\" class=\\"o_address_zip\\"/>\\n                                            <field name=\\"private_country_id\\" placeholder=\\"País\\" class=\\"o_address_country\\" options=\\"{&quot;no_open&quot;: True, &quot;no_create&quot;: True}\\"/>\\n                                        </div>\\n                                        <label for=\\"distance_home_work\\"/>\\n                                        <div class=\\"o_row\\" name=\\"div_km_home_work\\">\\n                                            <field name=\\"distance_home_work\\"/>\\n                                            <span><field name=\\"distance_home_work_unit\\"/></span>\\n                                        </div>\\n                                    </group>\\n                                    <group string=\\"Familia\\" name=\\"hr_family_group\\">\\n                                        <field name=\\"marital\\"/>\\n                                        <field name=\\"spouse_complete_name\\" invisible=\\"marital not in ['married', 'cohabitant']\\"/>\\n                                        <field name=\\"spouse_birthdate\\" invisible=\\"marital not in ['married', 'cohabitant']\\"/>\\n                                        <field name=\\"children\\"/>\\n                                    </group>\\n                                    <group string=\\"Educación\\" name=\\"hr_education_group\\">\\n                                        <field name=\\"certificate\\"/>\\n                                        <field name=\\"study_field\\" placeholder=\\"e.g. Engineering, Commerce, Business Administration, ...\\"/>\\n                                    </group>\\n                                    <group string=\\"Documentos\\" name=\\"hr_document_group\\">\\n                                        <field name=\\"id_card_name\\" invisible=\\"1\\"/>\\n                                        <field name=\\"driving_license_name\\" invisible=\\"1\\"/>\\n                                        <field name=\\"id_card\\" filename=\\"id_card_name\\"/>\\n                                        <field name=\\"driving_license\\" filename=\\"driving_license_name\\"/>\\n                                    </group>\\n                                </group>\\n                            </page>\\n                            <page name=\\"departure\\" string=\\"End of Collaboration\\" groups=\\"hr.group_hr_user\\" invisible=\\"not departure_id\\">\\n                                <group class=\\"mt-2 mb-4\\" invisible=\\"not departure_apply_date\\">\\n                                    <span class=\\"alert alert-warning\\" role=\\"alert\\">\\n                                        The departure process has been completed on\\n                                        <field name=\\"departure_apply_date\\" readonly=\\"1\\" class=\\"oe_inline\\"/>\\n                                        <a name=\\"action_cancel_departure\\" type=\\"object\\" class=\\"oe_inline\\" confirm=\\"This action will delete the departure entirely. Are you sure you want to proceed?\\">\\n                                            <i class=\\"oi ms-1\\" data-icon=\\"east\\"/>\\n                                            Cancel Departure\\n                                        </a>\\n                                    </span>\\n                                </group>\\n                                <group name=\\"header_group\\">\\n                                    <group readonly=\\"1\\">\\n                                        <field name=\\"departure_reason_id\\" readonly=\\"1\\" options=\\"{'no_edit': True, 'no_create': True, 'no_open': True}\\"/>\\n                                        <label for=\\"dismissal_date\\"/>\\n                                        <div class=\\"o_row\\">\\n                                            <field name=\\"dismissal_date\\" readonly=\\"1\\"/>\\n                                            <button name=\\"action_cancel_departure\\" string=\\"Cancel End of Collaboration\\" type=\\"object\\" class=\\"btn btn-link p-0 ms-2 text-decoration-none\\" groups=\\"hr.group_hr_user\\" invisible=\\"not id or not departure_id or departure_apply_date\\"/>\\n                                        </div>\\n                                    </group>\\n                                    <group>\\n                                        <field name=\\"departure_description\\" string=\\"Motivo\\" placeholder=\\"Información adicional\\" readonly=\\"1\\"/>\\n                                        <field name=\\"departure_action_date\\" placeholder=\\"The day after departure\\" string=\\"Archive Employee On\\" readonly=\\"1\\"/>\\n                                    </group>\\n                                </group>\\n                            </page>\\n                            <page name=\\"hr_settings\\" string=\\"Ajustes\\" groups=\\"hr.group_hr_user\\">\\n                                <group name=\\"settings_group\\">\\n                                    <group string=\\"Usuario\\" name=\\"user\\">\\n                                        <label for=\\"user_id\\"/>\\n                                        <div class=\\"o_row align-items-center\\">\\n                                            <field name=\\"user_id\\" string=\\"Usuario\\" placeholder=\\"No hay ningún usuario vinculado\\" domain=\\"[('company_ids', 'in', company_id)]\\" context=\\"{                                                     'default_create_employee_id': id,                                                     'default_name': name,                                                     'default_phone': work_phone,                                                     'default_mobile': mobile_phone,                                                     'default_login': work_email,                                                     'default_partner_id': work_contact_id,                                                     'search_default_filter_no_share': 1,                                                 }\\" widget=\\"many2one_avatar_user\\" groups=\\"base.group_erp_manager\\"/>\\n                                            <field name=\\"user_id\\" string=\\"Usuario\\" placeholder=\\"No hay ningún usuario vinculado\\" domain=\\"[('company_ids', 'in', company_id)]\\" context=\\"{                                                     'default_create_employee_id': id,                                                     'default_name': name,                                                     'default_phone': work_phone,                                                     'default_mobile': mobile_phone,                                                     'default_login': work_email,                                                     'default_partner_id': work_contact_id,                                                     'search_default_filter_no_share': 1,                                                 }\\" widget=\\"many2one_avatar_user\\" groups=\\"!base.group_erp_manager\\" options=\\"{'no_open': True}\\"/>\\n                                        </div>\\n                                        <field name=\\"tz\\" required=\\"id\\" placeholder=\\"User Timezone\\"/>\\n                                    </group>\\n                                    <group name=\\"managers\\" string=\\"Aprobadores\\">\\n                                        <field name=\\"hr_responsible_id\\" widget=\\"many2one_avatar_user\\"/>\\n                                    </group>\\n                                    <group name=\\"application_group\\" string=\\"Ajustes de solicitud\\" invisible=\\"1\\">\\n                                        <label for=\\"hourly_cost\\"/>\\n                                        <div name=\\"hourly_cost\\">\\n                                            <field name=\\"hourly_cost\\" class=\\"oe_inline\\"/>\\n                                            <field name=\\"currency_id\\" invisible=\\"1\\"/>\\n                                        </div>\\n                                    </group>\\n                                    <group string=\\"Asistencia/Punto de Venta\\" name=\\"identification_group\\">\\n                                        <field name=\\"pin\\" string=\\"Código PIN\\" placeholder=\\"e.g. 1234\\"/>\\n                                        <label for=\\"barcode\\"/>\\n                                        <div class=\\"o_row\\">\\n                                            <field name=\\"barcode\\"/>\\n                                            <button string=\\"Generar\\" class=\\"btn btn-link\\" type=\\"object\\" name=\\"generate_random_barcode\\" invisible=\\"barcode\\"/>\\n                                            <button name=\\"410\\" string=\\"Imprimir credencial\\" class=\\"btn btn-link\\" type=\\"action\\" invisible=\\"not barcode\\"/>\\n                                        </div>\\n                                    </group>\\n                                </group>\\n                            </page>\\n                        </notebook>\\n                    </sheet>\\n                    <chatter reload_on_follower=\\"True\\"/>\\n                </form>"}	<?xml version="1.0"?>\n<form string="Employee" js_class="hr_employee_form" duplicate="false">\n                    <header groups="hr.group_hr_user">\n                        <button string="Invite" name="action_send_invitation" type="object" class="btn btn-primary" invisible="user_id" groups="base.group_erp_manager"/>\n                        <button name="400" string="Launch Plan" type="action" class="o_button_plan_wizard_action" groups="hr.group_hr_user" invisible="not active or not id" context="{'sort_by_responsible': True}"/>\n                        <field name="user_state" widget="employee_user_status"/>\n                        <field name="version_id" widget="versions_timeline" context="{'version_revision': version_revision}" invisible="not id" options="{'clickable': True}" readonly="False"/>\n                        <field name="version_revision" invisible="1"/>\n                    </header>\n                    <sheet>\n                        <div name="button_box" class="oe_button_box">\n                            <button name="action_open_versions" class="oe_stat_button" icon="contact_page" icon_class="oi-filled" type="object" groups="hr.group_hr_user" invisible="not id">\n                                <div class="o_stat_info">\n                                    History\n                                    <span class="o_stat_value">\n                                        <field name="versions_count"/>\n                                    </span>\n                                </div>\n                            </button>\n                        </div>\n                        <div class="d-flex flex-column flex-md-row align-items-center gap-3" name="employee_photo_and_info">\n                            <div class="o_employee_avatar">\n                                <field name="hr_icon_display" invisible="not show_hr_icon_display or not id" widget="hr_presence_status"/>\n                                <field name="image_1920" widget="image" options="{'size': [128,158], 'zoom': true, 'preview_image':'avatar_128', 'img_class': 'border rounded h-100 object-fit-contain'}"/>\n                                <field name="show_hr_icon_display" invisible="1"/>\n                            </div>\n                            <group class="d-flex flex-column gap-md-0 w-100">\n                                <label for="name" class="d-md-none"/>\n                                <h1 class="o_employee_form_header_info d-flex flex-row align-items-center gap-2">\n                                    <field name="name" placeholder="Employee's Name (e.g. John Doe, ...)" required="True"/>\n                                </h1>\n                                <label for="work_email" class="d-md-none"/>\n                                <div class="d-flex align-items-baseline w-md-50 gap-2">\n                                    <i class="oi oi-filled d-none d-md-inline-flex" data-icon="mail" title="Work Email"/>\n                                    <field name="work_email" widget="email" placeholder="e.g. johndoe@example.com" string="Work Email"/>\n                                </div>\n                                <label for="work_phone" class="d-md-none"/>\n                                <div class="d-flex align-items-baseline w-md-50 gap-2">\n                                    <i class="oi oi-filled d-none d-md-inline-flex" data-icon="phone" title="Work Phone"/>\n                                    <field name="work_phone_sanitized" invisible="1"/>\n                                    <field name="work_phone_formatted" invisible="1"/>\n                                    <field name="work_phone" widget="phone" placeholder="Work Phone" string="Work Phone"/>\n                                </div>\n                                <label for="mobile_phone" class="d-md-none"/>\n                                <div class="d-flex align-items-baseline w-md-50 gap-2">\n                                    <i class="oi d-none d-md-inline-flex" data-icon="smartphone" title="Work Mobile"/>\n                                    <field name="mobile_phone_sanitized" invisible="1"/>\n                                    <field name="mobile_phone_formatted" invisible="1"/>\n                                    <field name="mobile_phone" widget="phone" placeholder="Work Mobile" string="Work Mobile"/>\n                                </div>\n                                <label for="category_ids" class="d-md-none"/>\n                                <div class="d-flex align-items-baseline w-md-50 gap-2">\n                                    <i class="oi d-none d-md-inline-flex" data-icon="sell" title="Tags"/>\n                                    <field name="category_ids" widget="many2many_tags" options="{'color_field': 'color', 'no_create_edit': True}" placeholder="e.g. Founder, Motorized, Building B, ..." groups="hr.group_hr_user"/>\n                                </div>\n                            </group>\n                        </div>\n                        <widget name="web_ribbon" title="Archived" bg_color="text-bg-danger" invisible="active"/>\n                        <field name="employee_properties" columns="2"/>\n                        <notebook>\n                            <page name="payroll_information" string="Payroll" groups="hr.group_hr_manager">\n                                <field name="currency_id" invisible="1"/>\n                                <group name="payroll_group">\n                                    <group name="contract" groups="hr.group_hr_user">\n                                        <div colspan="2" class="col-lg-6 w-100 mt-4 mb-3 o_horizontal_separator text-uppercase fw-bolder small d-flex">\n                                            <span>Contract Overview</span>\n                                            <field name="contract_template_id" widget="contract_template_button" class="ms-auto text-end w-auto p-0 mb-0 border-0 lh-1" nolabel="1"/>\n                                            </div>\n                                        <field name="employee_type_id" string="Employee Type" placeholder="Select employee type" domain="[('country_id', 'in', [company_country_id, False]), '|', ('company_id', 'in', [company_id, False]), ('company_id', '=', parent_company_id)]"/>\n                                        <label for="contract_date_start" string="Contract"/>\n                                        <div class="o_row" name="contract_dates">\n                                            <field name="contract_date_start" string="Start Date" placeholder="Not Employed" class="o_hr_narrow_field me-3"/>\n                                            <span invisible="not contract_date_start">to</span>\n                                            <field name="contract_date_end" string="End Date" placeholder="Indefinite" widget="date_dynamic_min" options="{'min_date_field': 'contract_date_start'}" class="o_hr_narrow_field ms-3" invisible="not contract_date_start"/>\n                                            <widget name="button_new_contract"/>\n                                        </div>\n                                        <field name="fixed_term" string="Fixed Term" invisible="1"/>\n                                        <label for="wage"/>\n                                        <div class="o_row" name="wage">\n                                            <field name="wage" class="oe_inline o_hr_narrow_field" nolabel="1"/>\n                                        </div>\n                                        <field name="structure_type_id" string="Pay Category" placeholder="Employee will be excluded from Pay Runs" domain="['|', ('country_id', '=', False), ('country_id', '=', company_country_id)]"/>\n                                    </group>\n                                    <group name="schedule" string="Schedule">\n                                        <field name="resource_calendar_id" help="The default working hours are set in configuration." context="{'employee_id': id}"/>\n                                    </group>\n                                </group>\n                            </page>\n                            <page name="work_information" string="Work">\n                                <div class="row" id="o_hr_work_information_container">\n                                    <div id="o_work_information" class="o_hr_column col-lg-7 d-flex flex-column">\n                                        <group name="work" string="work">\n                                            <field name="company_id" groups="base.group_multi_company" domain="[('id', 'in', allowed_company_ids)]"/>\n                                            <field name="department_id"/>\n                                            <field name="job_id" string="Job Position" context="{'default_no_of_recruitment': 0, 'default_is_favorite': False}" placeholder="e.g. Sales Manager"/>\n                                            <field name="job_title"/>\n                                            <field name="parent_id" widget="many2one_avatar_employee"/>\n                                        </group>\n                                        <group name="work_location" string="Location">\n                                            <field name="address_id" context="{'show_address': 1}" options="{&quot;highlight_first_line&quot;: True}" invisible="1"/>\n                                            <field name="work_location_id" string="Usual Work Location" context="{'default_address_id': address_id}" placeholder="e.g. Building 2, Remote, etc."/>\n                                                <field name="monday_location_id" placeholder="Unspecified" force_save="1"/>\n                                                <field name="tuesday_location_id" placeholder="Unspecified" force_save="1"/>\n                                                <field name="wednesday_location_id" placeholder="Unspecified" force_save="1"/>\n                                                <field name="thursday_location_id" placeholder="Unspecified" force_save="1"/>\n                                                <field name="friday_location_id" placeholder="Unspecified" force_save="1"/>\n                                                <field name="saturday_location_id" placeholder="Unspecified" force_save="1"/>\n                                                <field name="sunday_location_id" placeholder="Unspecified" force_save="1"/>\n                                        </group>\n                                        <group string="Note" name="note" groups="hr.group_hr_user">\n                                            <field name="additional_note" placeholder="Provide additional information about this employee..." colspan="2" nolabel="1"/>\n                                        </group>\n                                    </div>\n                                    <div id="o_employee_org_chart" class="o_hr_column col-lg-5">\n                                        <div invisible="not subordinate_ids and (not parent_id or parent_id == id)" class="o_horizontal_separator mt-4 mb-3 text-uppercase fw-bolder small">\n                                            Organization Chart\n                                            <a name="411" type="action" role="button" class="float-end me-2 cursor-pointer" context="{'hierarchy_res_id': id}">\n                                                <i class="oi oi-filled oi-rotate-90 ms-1 mt-1" data-icon="share" role="img" aria-label="Full Chart"/>\n                                                Full Chart\n                                            </a>\n                                        </div>\n                                        <div invisible="subordinate_ids or (parent_id and not parent_id == id)" class="o_horizontal_separator mt-4 mb-3 text-uppercase fw-bolder small">\n                                            Organization Chart\n                                        </div>\n                                        <field name="child_ids" class="position-relative w-100" widget="hr_org_chart" readonly="1" nolabel="1"/>\n                                    </div>\n                                </div>\n                            </page>\n                            <page name="resume" string="Resume">\n                                <div class="row" id="o_hr_skills_resume_container">\n                                    <div id="o_employee_left" class="o_hr_skills_editable o_hr_skills_group o_hr_column o_group_resume col-lg-7 d-flex flex-column"/>\n                                    <div id="o_work_information_right" class="o_hr_skills_editable o_hr_skills_group o_hr_column o_group_skills col-lg-5"/>\n                                </div>\n                            </page>\n                            <page name="personal_information" string="Personal" groups="hr.group_hr_user">\n                                <group>\n                                    <group string="Private Contact">\n                                        <field name="private_email" placeholder="e.g. myprivateemail@example.com" string="Email"/>\n                                        <field name="private_phone_sanitized" invisible="1"/>\n                                        <field name="private_phone_formatted" invisible="1"/>\n                                        <field name="private_phone" widget="phone" string="Phone"/>\n                                        <field name="has_multiple_bank_accounts" invisible="1"/>\n                                        <field name="is_trusted_bank_account" invisible="1"/>\n                                        <field name="bank_account_ids" invisible="1" widget="many2many_tags" options="{'color_field': 'color', 'on_tag_click': 'edit_color'}"/>\n                                        <label for="bank_account_ids"/>\n                                        <div class="d-flex align-items-start justify-content-between" invisible="not has_multiple_bank_accounts">\n                                                <field name="bank_account_ids" widget="many2many_tags_salary_bank" context="{'default_partner_id': work_contact_id}" options="{'color_field': 'color', 'no_quick_create': True, 'on_tag_click': 'open_form'}"/>\n                                            <div class="pt-0 ms-2">\n                                                <button name="action_open_allocation_wizard" type="object" string="Salary Allocation" class="btn btn-link p-0 ms-auto text-nowrap"/>\n                                            </div>\n                                        </div>\n\n                                        <div class="o-row d-flex justify-content-between gap-2 align-items-start" invisible="has_multiple_bank_accounts">\n                                            <field name="bank_account_ids" widget="many2many_tags_salary_bank" context="{'default_partner_id': work_contact_id}" options="{'color_field': 'color', 'no_quick_create': True, 'on_tag_click': 'open_form'}"/>\n                                            <div class="d-flex align-items-start" invisible="not bank_account_ids">\n                                                <span class="d-flex w-50">\n                                                    <span invisible="is_trusted_bank_account" class="text-muted">Untrusted</span>\n                                                    <span invisible="not is_trusted_bank_account" class="text-success">Trusted</span>\n                                                </span>\n                                                <button title="Trust Bank Account" class="pt-0" icon="toggle_off" icon_class="oi-lg" type="object" name="action_toggle_primary_bank_account_trust" invisible="is_trusted_bank_account"/>\n                                                <button title="Untrust Bank Account" class="button-on pt-0" icon="toggle_on" icon_class="oi-lg" type="object" name="action_toggle_primary_bank_account_trust" invisible="not is_trusted_bank_account"/>\n                                            </div>\n                                        </div>\n                                    </group>\n                                    <group string="Personal Information" name="hr_birth_group">\n                                        <field name="legal_name" invisible="split_legal_name"/>\n                                        <field name="birthday"/>\n                                        <field name="birthday_public_display" invisible="not birthday" widget="boolean_toggle"/>\n                                        <label for="place_of_birth"/>\n                                        <div class="o_row" name="birth_location">\n                                            <field name="place_of_birth" class="oe_inline o_hr_narrow_field" nolabel="1" placeholder="City"/>\n                                            <div class="mx-3 flex-grow-0">─</div>\n                                            <field name="country_of_birth" class="oe_inline o_hr_narrow_field" nolabel="1" placeholder="Country"/>\n                                        </div>\n                                        <field name="sex"/>\n                                    </group>\n                                    <group name="citizenship" string="Citizenship">\n                                        <field name="country_id" options="{&quot;no_open&quot;: True, &quot;no_create&quot;: True}"/>\n                                        <field name="identification_id" placeholder="Issued by Government"/>\n                                        <label for="passport_id"/>\n                                        <div class="o_wrap_label d-flex flex-row gap-3 align-items-baseline">\n                                            <field name="passport_id"/>\n                                            <label for="passport_expiration_date" class="flex-shrink-0" invisible="not passport_id" string="Expires on"/>\n                                            <field name="passport_expiration_date" invisible="not passport_id"/>\n                                        </div>\n                                    </group>\n                                    <group string="Visa &amp; Work Permit">\n                                        <label for="visa_no"/>\n                                        <div class="o_wrap_label d-flex flex-row gap-3 align-items-baseline">\n                                            <field name="visa_no"/>\n                                            <label for="visa_expire" class="flex-shrink-0" invisible="not visa_no" string="Expires on"/>\n                                            <field name="visa_expire" invisible="not visa_no"/>\n                                        </div>\n                                        <label for="permit_no"/>\n                                        <div class="o_wrap_label d-flex flex-row gap-3 align-items-baseline">\n                                            <field name="permit_no"/>\n                                            <label for="work_permit_expiration_date" class="flex-shrink-0" invisible="not permit_no" string="Expires on"/>\n                                            <field name="work_permit_expiration_date" invisible="not permit_no"/>\n                                        </div>\n                                        <field name="work_permit_name" invisible="1"/>\n                                        <field name="has_work_permit" widget="binary" filename="work_permit_name" string="Document"/>\n                                    </group>\n                                    <group string="Emergency Contact">\n                                        <field name="emergency_contact" string="Contact Name"/>\n                                        <field name="emergency_phone_sanitized" invisible="1"/>\n                                        <field name="emergency_phone_formatted" invisible="1"/>\n                                        <field name="emergency_phone" widget="phone" class="o_force_ltr" string="Phone"/>\n                                    </group>\n                                    <group string="Location" name="hr_location_group">\n                                        <label for="private_street" string="Private Address"/>\n                                        <div class="o_address_format o_hr_address">\n                                            <field name="private_street" placeholder="Street..." class="o_address_street"/>\n                                            <field name="private_street2" placeholder="Street 2..." class="o_address_street"/>\n                                            <field name="private_city" placeholder="City" class="o_address_city"/>\n                                            <field name="private_