g_list in lists_optout\\">\\n                                                Not subscribed\\n                                            </t>\\n                                            <t t-else=\\"\\">\\n                                                Subscribed\\n                                            </t>\\n                                        </span>\\n                                    </li>\\n                                </ul>\\n                                <p t-if=\\"lists_public\\">\\n                                    You may also be interested in\\n                                </p>\\n                                <ul id=\\"o_mailing_subscription_form_lists_additional\\" t-if=\\"lists_public\\" class=\\"list-group\\">\\n                                    <li t-foreach=\\"lists_public\\" t-as=\\"mailing_list\\" class=\\"list-group-item\\">\\n                                        <input type=\\"checkbox\\" name=\\"mailing_list_ids\\" t-att-disabled=\\"'disabled' if is_blocklisted else None\\" t-att-value=\\"mailing_list.id\\" t-att-title=\\"mailing_list.name\\"/>\\n                                        <span class=\\"ms-1\\" t-out=\\"mailing_list.name\\"/>\\n                                    </li>\\n                                </ul>\\n                                <p t-if=\\"not lists_optin and not lists_optout and not lists_public\\">\\n                                    You are not subscribed to any of our mailing list.\\n                                </p>\\n                            </div>\\n                            <div id=\\"o_mailing_subscription_blocklist\\" class=\\"d-flex align-items-center mb-4 pt-3\\">\\n                                <button type=\\"submit\\" id=\\"button_form_send\\" t-att-disabled=\\"'disabled' if is_blocklisted else None\\" t-att-class=\\"'btn btn-primary ' + ('' if lists_optin or lists_optout or lists_public else 'd-none')\\">\\n                                    Apply changes\\n