1274	16	\N	1	1	Mass Mailing: A/B Test Description	\N	mass_mailing.ab_testing_description	qweb	mass_mailing/data/mailing_data_templates.xml	primary	\N	{"en_US": "<t name=\\"Mass Mailing: A/B Test Description\\" t-name=\\"mass_mailing.ab_testing_description\\">\\n        <div name=\\"ab_testing_description\\" class=\\"mb-2\\">\\n            <t t-if=\\"mailing.state == 'done' and mailing.sent == 0 and mailing.failed == 0 and mailing.canceled == 0\\">\\n                <span>There wasn't enough recipients left for this mailing</span>\\n            </t>\\n            <t t-if=\\"mailing.ab_testing_completed\\">\\n                <p t-if=\\"mailing.ab_testing_is_winner_mailing\\">\\n                    This <t t-out=\\"mailing.mailing_type_description\\"/> is the winner of the A/B testing campaign and has been sent to all remaining recipients.\\n                </p>\\n                <p t-else=\\"\\">The winner has already been sent. Use <b>Compare Version</b> to get an overview of this A/B testing campaign.</p>\\n            </t>\\n            <t t-elif=\\"ab_testing_count &gt;= 2\\">\\n                <p>\\n                    A sample of <b><t t-out=\\"mailing.ab_testing_pc\\"/>% of recipients</b> will receive this version.<br/>\\n                    <t t-if=\\"total_ab_testing_pc &gt; 100 and mailing.active\\">\\n                        <i class=\\"oi text-danger\\" data-icon=\\"warning\\" aria-hidden=\\"true\\"/>\\n                        The sum of all percentages for this A/B campaign totals <b class=\\"text-danger\\"><t t-out=\\"total_ab_testing_pc\\"/>%</b> of all potential recipients.<br/>\\n                        <b class=\\"text-danger\\">Some of the mailings will not be sent</b>, as only 1 email will be sent for each unique recipient in this campaign.\\n                    </t>\\n                </p>\\n                <p>\\n\\t\\t    <t t-if=\\"mailing.ab_testing_winner_selection == 'manual'\\">Don't forget to send your preferred version</t>\\n\\t\\t    <t t-elif=\\"not mailing.ab_testing_schedule_datetime\\">Since the date and time for this test has not been scheduled, don't forget to manually send your preferred version.</t>\\n                    <t t-else=\\"\\">\\n                        Then on <b><t t-out=\\"mailing.ab_testing_schedule_datetime.strftime('%b %d, %Y')\\"/></b> the <t t-out=\\"mailing.mailing_type_description\\"/> having the <b><t t-out=\\"ab_testing_winner_selection_description\\"/></b> will be sent\\n                    </t> to the remaining recipients.\\n                </p>\\n            </t>\\n            <t t-else=\\"\\">\\n                <p>\\n                    A sample of <b><t t-out=\\"mailing.ab_testing_pc\\"/>% of recipients</b> will receive this version.\\n                </p>\\n                <t t-if=\\"mailing.ab_testing_winner_selection != 'manual'\\">\\n                    <p>Try different variations in the campaign to compare their <t t-out=\\"ab_testing_winner_selection_description\\"/>.</p>\\n                    <p>Once the best version is identified, we will send the best one to the remaining recipients.</p>\\n                </t>\\n                <p t-else=\\"\\">Use alternative versions to be able to select the winner.</p>\\n            </t>\\n        </div>\\n    </t>", "es_ES": "<t name=\\"Mass Mailing: A/B Test Description\\" t-name=\\"mass_mailing.ab_testing_description\\">\\n        <div name=\\"ab_testing_description\\" class=\\"mb-2\\">\\n            <t t-if=\\"mailing.state == 'done' and mailing.sent == 0 and mailing.failed == 0 and mailing.canceled == 0\\">\\n                <span>No había suficientes destinatarios para este correo</span>\\n            </t>\\n            <t t-if=\\"mailing.ab_testing_completed\\">\\n                <p t-if=\\"mailing.ab_testing_is_winner_mailing\\">\\n                    Este <t t-out=\\"mailing.mailing_type_description\\"/> es el ganador de la campaña de prueba A/B y se envió a todos los destinatarios restantes.\\n                </p>\\n                <p t-else=\\"\\">Ya se envió el ganador. Use <b>comparar versión</b> para obtener una vista general de esta campaña de prueba A/B.</p>\\n            </t>\\n            <t t-elif=\\"ab_testing_count &gt;= 2\\">\\n                <p>\\n                    Una muestra de <b><t t-out=\\"mailing.ab_testing_pc\\"/>% de destinatarios</b> recibirá esta versión.<br/>\\n                    <t t-if=\\"total_ab_testing_pc &gt; 100 and mailing.active\\">\\n                        <i class=\\"oi text-danger\\" data-icon=\\"warning\\" aria-hidden=\\"True\\"/>\\n                        La suma de todos los porcentajes para esta campaña A/B da un total de <b class=\\"text-danger\\"><t t-out=\\"total_ab_testing_pc\\"/>%</b> de todos los destinatarios potenciales.<br/>\\n                        <b class=\\"text-danger\\">Algunos de los correos no se enviarán</b>, pues solo se enviará 1 solo correo para cada destinatario único de esta campaña.\\n                    </t>\\n                </p>\\n                <p>\\n\\t\\t    <t t-if=\\"mailing.ab_testing_winner_selection == 'manual'\\">No olvide enviar su versión preferida</t>\\n\\t\\t    <t t-elif=\\"not mailing.ab_testing_schedule_datetime\\">Dado que no se ha programado la fecha y la hora de esta prueba, no olvide enviar manualmente su versión preferida.</t>\\n                    <t t-else=\\"\\">\\n                        Después, el <b><t t-out=\\"mailing.ab_testing_schedule_datetime.strftime('%b %d, %Y')\\"/></b> el <t t-out=\\"mailing.mailing_type_description\\"/> con <b><t t-out=\\"ab_testing_winner_selection_description\\"/></b> se enviará\\n                    </t> a los destinatarios restantes.\\n                </p>\\n            </t>\\n            <t t-else=\\"\\">\\n                <p>\\n                    Una muestra de <b><t t-out=\\"mailing.ab_testing_pc\\"/>% de destinatarios</b> recibirá esta versión.\\n                </p>\\n                <t t-if=\\"mailing.ab_testing_winner_selection != 'manual'\\">\\n                    <p>Pruebe diferentes variaciones en la campaña para comparar su(s) <t t-out=\\"ab_testing_winner_selection_description\\"/>.</p>\\n                    <p>Una vez que se identifique la mejor versión, se la enviaremos a los destinatarios restantes.</p>\\n                </t>\\n                <p t-else=\\"\\">Use versiones alternativas para poder seleccionar al ganador.</p>\\n            </t>\\n        </div>\\n    </t>"}	<?xml version="1.0"?>\n<t name="Mass Mailing: A/B Test Description" t-name="mass_mailing.ab_testing_description">\n        <div name="ab_testing_description" class="mb-2">\n            <t t-if="mailing.state == 'done' and mailing.sent == 0 and mailing.failed == 0 and mailing.canceled == 0">\n                <span>There wasn't enough recipients left for this mailing</span>\n            </t>\n            <t t-if="mailing.ab_testing_completed">\n                <p t-if="mailing.ab_testing_is_winner_mailing">\n                    This <t t-out="mailing.mailing_type_description"/> is the winner of the A/B testing campaign and has been sent to all remaining recipients.\n                </p>\n                <p t-else="">The winner has already been sent. Use <b>Compare Version</b> to get an overview of this A/B testing campaign.</p>\n            </t>\n            <t t-elif="ab_testing_count &gt;= 2">\n                <p>\n                    A sample of <b><t t-out="mailing.ab_testing_pc"/>% of recipients</b> will receive this version.<br/>\n                    <t t-if="total_ab_testing_pc &gt; 100 and mailing.active">\n                        <i class="oi text-danger" data-icon="warning" aria-hidden="true"/>\n                        The sum of all percentages for this A/B campaign totals <b class="text-danger"><t t-out="total_ab_testing_pc"/>%</b> of all potential recipients.<br/>\n                        <b class="text-danger">Some of the mailings will not be sent</b>, as only 1 email will be sent for each unique recipient in this campaign.\n                    </t>\n                </p>\n                <p>\n\t\t    <t t-if="mailing.ab_testing_winner_selection == 'manual'">Don't forget to send your preferred version</t>\n\t\t    <t t-elif="not mailing.ab_testing_schedule_datetime">Since the date and time for this test has not been scheduled, don't forget to manually send your preferred version.</t>\n                    <t t-else="">\n                        Then on <b><t t-out="mailing.ab_testing_schedule_datetime.strftime('%b %d, %Y')"/></b> the <t t-out="mailing.mailing_type_description"/> having the <b><t t-out="ab_testing_winner_selection_description"/></b> will be sent\n                    </t> to the remaining recipients.\n                </p>\n            </t>\n            <t t-else="">\n                <p>\n                    A sample of <b><t t-out="mailing.ab_testing_pc"/>% of recipients</b> will receive this version.\n                </p>\n                <t t-if="mailing.ab_testing_winner_selection != 'manual'">\n                    <p>Try different variations in the campaign to compare their <t t-out="ab_testing_winner_selection_description"/>.</p>\n                    <p>Once the best version is identified, we will send the best one to the remaining recipients.</p>\n                </t>\n                <p t-else="">Use alternative versions to be able to select the winner.</p>\n            </t>\n        </div>\n    </t>\n\n    	\N	f	t	2026-10-26 23:48:58.810362	2026-10-26 23:48:58.810362	f
