le_type_now_text\\">Este correo se enviará lo antes posible.</span>\\n                                    <button name=\\"action_reload\\" type=\\"object\\" class=\\"btn btn-link pe-0\\">\\n                                        <u>Volver a cargar <i class=\\"oi ms-1\\" data-icon=\\"refresh\\"/></u>\\n                                    </button>\\n                                </strong>\\n                            </div>\\n                            <div class=\\"o_mails_scheduled o_mails_process\\" invisible=\\"scheduled == 0 and process == 0\\">\\n                                <span invisible=\\"scheduled == 0\\">\\n                                    <button class=\\"btn btn-link p-0\\" name=\\"action_view_traces_scheduled\\" type=\\"object\\">\\n                                        <strong>\\n                                            <field name=\\"scheduled\\" class=\\"oe_inline me-1\\"/>\\n                                            <span name=\\"scheduled_text\\">emails are in queue and will be sent soon</span>\\n                                        </strong>\\n                                    </button>\\n                                </span>\\n                                <span invisible=\\"not scheduled or not process\\">, </span>\\n                                <span invisible=\\"process == 0\\">\\n                                    <button class=\\"btn btn-link p-0\\" name=\\"action_view_traces_process\\" type=\\"object\\">\\n                                        <strong>\\n                                            <field name=\\"process\\" class=\\"oe_inline me-1\\"/>\\n                                            <span name=\\"process_text\\">emails are being processed</span>\\n                                        </strong>\\n                                    </button>\\n                                </span>\\n                                <span>.</span>\\n                            </div>\\n                        </div>\\n                        <field name=\\"state\\" readonly=\\"1\\" widget=\\"statusbar\\" statusbar_visible=\\"draft,sending,done\\" invisible=\\"is_template\\"/>\\n                    </header>\\n                    <field name=\\"is_template\\" invisible=\\"1\\"/>\\n                    <div class=\\"alert alert-info\\" role=\\"alert\\" invisible=\\"is_template or not warning_message\\">\\n                        <strong><field name=\\"warning_message\\"/></strong>\\n                    </div>\\n                    <sheet>\\n                        <div class=\\"badge rounded-pill text-bg-300 float-end border-0\\" invisible=\\"not is_template\\">Plantilla</div>\\n                        <div class=\\"oe_button_box\\" name=\\"button_box\\" invisible=\\"is_template\\">\\n                            <button name=\\"action_view_traces\\" type=\\"object\\" invisible=\\"state in ('draft', 'test')\\" class=\\"oe_stat_button\\">\\n                                <field name=\\"delivered\\" invisible=\\"1\\"/>\\n                                <field name=\\"received_ratio\\" widget=\\"deliverance_percentpie\\" top_field=\\"delivered\\" bottom_field=\\"failed\\"/>\\n                            </button>\\n                            <button name=\\"action_view_traces_canceled\\" type=\\"object\\" invisible=\\"state in ('draft', 'test') or canceled == 0\\">\\n                                <field name=\\"canceled_ratio\\" string=\\"Cancelado\\" widget=\\"percentpie\\"/>\\n                            </button>\\n                            <button name=\\"action_view_opened\\" type=\\"object\\" context=\\"{'search_default_filter_opened': True,                                     'search_default_state': True,}\\" invisible=\\"state in ('draft', 'test')\\" class=\\"oe_stat_button\\">\\n                                <field name=\\"opened_ratio\\" string=\\"Abierto\\" widget=\\"percentpie\\"/>\\n                            </button>\\n                            <button name=\\"action_view_replied\\" type=\\"object\\" context=\\"{'search_default_filter_replied': True}\\" invisible=\\"state in ('draft', 'test')\\" class=\\"oe_stat_button\\">\\n                                <field name=\\"replied_ratio\\" string=\\"Respondido\\" widget=\\"percentpie\\"/>\\n                            </button>\\n                            <button name=\\"action_view_clicked\\" type=\\"object\\" context=\\"{'search_default_filter_clicked': True}\\" invisible=\\"state in ('draft', 'test')\\" class=\\"oe_stat_button\\">\\n                                <field name=\\"clicks_ratio\\" string=\\"Cliqueado\\" widget=\\"percentpie\\"/>\\n                            </button>\\n                            <button name=\\"action_view_bounced\\" type=\\"object\\" context=\\"{'search_default_filter_bounced': True}\\" invisible=\\"state in ('draft', 'test')\\" class=\\"oe_stat_button\\">\\n                                <field name=\\"bounced_ratio\\" string=\\"Rebotado\\" widget=\\"percentpie\\"/>\\n                            </button>\\n                            <button name=\\"action_view_link_trackers\\" invisible=\\"state != 'done'\\" type=\\"object\\" class=\\"oe_stat_button\\" icon=\\"link\\">\\n                                <field name=\\"link_trackers_count\\" widget=\\"statinfo\\" string=\\"Rastreadores de enlaces\\"/>\\n                            </button>\\n                        </div>\\n                        <widget name=\\"web_ribbon\\" title=\\"Archivado\\" bg_color=\\"text-bg-danger\\" invisible=\\"active\\"/>\\n                        <group class=\\"o_mass_mailing_mailing_group\\">\\n                            <field name=\\"active\\" invisible=\\"1\\"/>\\n                            <field name=\\"create_uid\\" invisible=\\"1\\"/>\\n                            <field name=\\"mailing_type\\" widget=\\"radio\\" options=\\"{'horizontal': true}\\" invisible=\\"1\\" readonly=\\"state != 'draft'\\" force_save=\\"1\\"/>\\n                            <field class=\\"text-break w-75\\" name=\\"subject\\" options=\\"{'dynamic_placeholder': true, 'dynamic_placeholder_model_reference_field': 'mailing_model_real'}\\" readonly=\\"state in ('sending', 'done')\\" widget=\\"char_emojis\\" placeholder=\\"p. ej. Nueva rebaja en todas las camisetas\\"/>\\n                            <label for=\\"mailing_model_id\\" string=\\"Destinatarios\\"/>\\n                            <div name=\\"mailing_model_id_container\\">\\n                                <div class=\\"row\\">\\n                                    <div class=\\"col-md-auto\\">\\n                                        <field name=\\"mailing_model_id\\" options=\\"{'no_open': True, 'no_create': True}\\" readonly=\\"state in ('sending', 'done')\\" placeholder=\\"Select a Target\\"/>\\n                                    </div>\\n                                    <!-- MANUAL LISTS -->\\n                                    <div invisible=\\"is_template or not mailing_on_mailing_list\\" class=\\"o_mass_mailing_contact_list_ids col-md-auto\\">\\n                                        <label for=\\"contact_list_ids\\" string=\\"Listas de correo:\\" class=\\"oe_edit_only pe-3\\"/>\\n                                        <div class=\\"d-inline-flex flex-row align-items-center\\">\\n                                            <field name=\\"contact_list_ids\\" widget=\\"many2many_tags\\" placeholder=\\"Seleccione a los destinatarios...\\" class=\\"oe_inline mb-0\\" context=\\"{'form_view_ref': 'mass_mailing.mailing_list_view_form_simplified'}\\" domain=\\"[('active', '=', True)]\\" readonly=\\"state in ('sending', 'done')\\" options=\\"{'color_field': 'color'}\\"/>\\n                                            <button icon=\\"person_add\\" icon_class=\\"oi-filled\\" type=\\"object\\" class=\\"btn btn-secondary py-0 px-1 ms-1\\" invisible=\\"not contact_list_ids or not contact_list_ids or state in ('sending', 'done')\\" name=\\"action_import_mailing_contacts\\" title=\\"Importar contactos de correo\\"/>\\n                                        </div>\\n                                    </div>\\n                                    <!-- DYNAMIC LISTS -->\\n                                    <div class=\\"col-md-auto\\" invisible=\\"is_template or not mailing_model_id or mailing_on_mailing_list or (state in ('sending', 'done') and not mailing_filter_ids)\\">\\n                                        <label for=\\"mailing_filter_ids\\" string=\\"Dynamic Lists:\\" class=\\"oe_edit_only pe-3\\"/>\\n                                        <field name=\\"mailing_filter_ids\\" widget=\\"mailing_many2many_tags\\" placeholder=\\"Select dynamic lists...\\" class=\\"o_field_many2many_tags oe_inline mb-0\\" context=\\"{                                                 'form_view_ref': 'mass_mailing.mailing_filter_view_form_simplified',                                                  'default_mailing_model_id': mailing_model_id                                             }\\" options=\\"{'no_quick_create': True, 'on_tag_click': 'open_form', 'color_field': 'color'}\\" readonly=\\"state in ('sending', 'done')\\"/>\\n                                        <div invisible=\\"not mailing_filter_ids or state == 'done'\\" class=\\"o_mass_mailing_recipients_count d-inline-flex align-items-baseline gap-1 text-nowrap ms-2 text-muted\\">\\n                                            <field name=\\"recipients_count\\" class=\\"lh-1\\"/>\\n                                            <span>Recipients</span>\\n                                        </div>\\n                                    </div>\\n                                    <div invisible=\\"is_template or mailing_model_real == 'mailing.contact'\\" class=\\"o_mass_mailing_use_exclusion_list col-md-auto\\">\\n                                        <field name=\\"use_exclusion_list\\" string=\\"Utilizar lista de exclusión\\" readonly=\\"state != 'draft'\\"/>\\n                                        <label for=\\"use_exclusion_list\\" class=\\"ps-2\\" string=\\"Exclude Blacklisted Recipients\\"/>\\n                                    </div>\\n                                </div>\\n                            </div>\\n                            <label for=\\"mailing_domain\\" string=\\"Dominio\\" invisible=\\"is_template or not mailing_model_id or mailing_on_mailing_list or mailing_filter_ids\\"/>\\n                            <div invisible=\\"is_template or not mailing_model_id or mailing_on_mailing_list or mailing_filter_ids\\">\\n                                <field name=\\"mailing_domain\\" widget=\\"domain_savable\\" options=\\"{'model': 'mailing_model_real', 'foldable': True, 'model_id': 'mailing_model_id'}\\" readonly=\\"state in ('sending', 'done')\\"/>\\n                            </div>\\n                            <field name=\\"mailing_model_name\\" invisible=\\"1\\"/>\\n                            <field name=\\"mailing_on_mailing_list\\" invisible=\\"1\\"/>\\n                            <field name=\\"mailing_model_real\\" invisible=\\"1\\"/>\\n                        </group>\\n                        <notebook>\\n                            <page string=\\"Cuerpo del correo\\" name=\\"mail_body\\">\\n                                <div class=\\"position-relative\\">\\n                                    <field name=\\"body_arch\\" class=\\"o_mail_body_mailing\\" widget=\\"mass_mailing_html\\" required=\\"is_template\\" options=\\"{                                             'inline_field': 'body_html',                                             'dynamic_placeholder': true,                                             'dynamic_placeholder_model_reference_field': 'mailing_model_real',                                             'filterTemplates': true,                                         }\\" readonly=\\"state in ('sending', 'done')\\"/>\\n                                    <field name=\\"body_html\\" invisible=\\"1\\" required=\\"body_arch\\"/>\\n                                    <field name=\\"is_body_empty\\" invisible=\\"1\\"/>\\n                                </div>\\n                            </page>\\n                            <page string=\\"Ajustes\\" name=\\"settings\\" invisible=\\"is_template\\">\\n                                <group>\\n                                    <group string=\\"Contenido del correo electrónico\\" name=\\"email_content\\" invisible=\\"mailing_type != 'mail'\\">\\n                                        <field class=\\"o_text_overflow\\" name=\\"preview\\" string=\\"Vista previa del texto\\" options=\\"{'dynamic_placeholder': true, 'dynamic_placeholder_model_reference_field': 'mailing_model_real'}\\" readonly=\\"state in ('sending', 'done')\\" widget=\\"char_emojis\\" placeholder=\\"This text will appear in inboxes, next to the subject\\"/>\\n                                        <field name=\\"email_from\\" readonly=\\"state in ('sending', 'done')\\" required=\\"mailing_type == 'mail' and not is_template\\"/>\\n                                        <label for=\\"reply_to\\"/>\\n                                        <div name=\\"reply_to_details\\">\\n                                            <field name=\\"reply_to_mode\\" widget=\\"radio\\" invisible=\\"mailing_model_name in ['mailing.contact', 'res.partner', 'mailing.list']\\" readonly=\\"state in ('sending', 'done')\\"/>\\n                                            <field name=\\"reply_to\\" invisible=\\"reply_to_mode == 'update'\\" readonly=\\"state in ('sending', 'done')\\" required=\\"not is_template and reply_to_mode == 'new'\\"/>\\n                                            <div style=\\"margin-top:-5px\\">\\n                                                <small class=\\"oe_edit_only text-muted mb-2\\" style=\\"font-size:74%\\" invisible=\\"reply_to_mode == 'update' or mailing_model_name in ['mailing.contact', 'res.partner', 'mailing.list']\\">\\n                                                    Para rastrear respuestas. esta dirección de correo debe pertenecer a esta base de datos.\\n                                                </small>\\n                                            </div>\\n                                        </div>\\n                                        <label for=\\"attachment_ids\\"/>\\n                                        <div name=\\"attachment_ids_details\\">\\n                                            <field name=\\"attachment_ids\\" widget=\\"many2many_binary\\" string=\\"Adjuntar un archivo\\" readonly=\\"state in ('sending', 'done')\\"/>\\n                                        </div>\\n                                    </group>\\n                                    <group string=\\"Seguimiento\\">\\n                                        <field name=\\"campaign_id\\" string=\\"Campaña\\" groups=\\"mass_mailing.group_mass_mailing_campaign\\" options=\\"{'create_name_field': 'title'}\\" readonly=\\"state in ('sending', 'done')\\"/>\\n                                        <field name=\\"medium_id\\" string=\\"Media\\" required=\\"True\\"/>\\n                                        <field name=\\"source_id\\" string=\\"Origen\\" class=\\"o_text_overflow\\" required=\\"False\\"/>\\n                                        <field name=\\"user_id\\" widget=\\"many2one_avatar_user\\" domain=\\"[('share', '=', False)]\\"/>\\n                                    </group>\\n                                    <group string=\\"Avanzado\\">\\n                                        <field name=\\"mail_server_available\\" invisible=\\"1\\"/>\\n                                        <field name=\\"mail_server_id\\" invisible=\\"not mail_server_available\\" readonly=\\"state in ('sending', 'done')\\" domain=\\"[('owner_user_id', '=', False)]\\"/>\\n                                        <field name=\\"keep_archives\\" readonly=\\"state in ('sending', 'done')\\"/>\\n                                    </group>\\n                                </group>\\n                                <div class=\\"row\\" name=\\"ab_testing\\">\\n                                    <group class=\\"col-12 col-md-6\\">\\n                                        <label for=\\"ab_testing_enabled\\"/>\\n                                        <span class=\\"d-flex\\">\\n                                            <field name=\\"ab_testing_enabled\\" readonly=\\"state != 'draft'\\" force_save=\\"1\\"/>\\n                                            <span class=\\"d-flex\\" invisible=\\"not ab_testing_enabled\\">\\n                                                el <field name=\\"ab_testing_pc\\" class=\\"mx-1 text-center\\" readonly=\\"state != 'draft'\\"/> %\\n                                            </span>\\n                                        </span>\\n                                        <field name=\\"ab_testing_version_name\\" invisible=\\"not ab_testing_enabled\\" placeholder=\\"e.g. 'Header with product picture'\\"/>\\n                                        <field name=\\"ab_testing_winner_selection\\" invisible=\\"not ab_testing_enabled or mailing_type != 'mail'\\" readonly=\\"state != 'draft'\\" required=\\"ab_testing_enabled and mailing_type == 'mail'\\"/>\\n                                        <field name=\\"ab_testing_schedule_datetime\\" invisible=\\"not ab_testing_enabled or ab_testing_winner_selection == 'manual'\\" readonly=\\"not ab_testing_enabled or state != 'draft'\\" required=\\"ab_testing_enabled and ab_testing_winner_selection != 'manual'\\"/>\\n                                        <field name=\\"is_ab_test_sent\\" invisible=\\"1\\"/>\\n                                    </group>\\n                                    <div class=\\"col-12 col-md-6\\">\\n                                        <field name=\\"ab_testing_mailings_count\\" invisible=\\"1\\"/>\\n                                        <field name=\\"ab_testing_completed\\" invisible=\\"1\\"/>\\n                                        <field name=\\"ab_testing_description\\" nolabel=\\"1\\"/>\\n                                        <div id=\\"mailing_form_ab_buttons\\" invisible=\\"ab_testing_mailings_count &lt; 2 or not ab_testing_enabled\\">\\n                                            <button name=\\"action_compare_versions\\" type=\\"object\\" class=\\"btn btn-link d-block\\">\\n                                                <i class=\\"oi\\" data-icon=\\"bar_chart\\"/> Comparar versión\\n                                            </button>\\n                                            <button name=\\"action_duplicate\\" type=\\"object\\" class=\\"btn btn-link d-block\\" invisible=\\"ab_testing_completed\\">\\n                                                <i class=\\"oi\\" data-icon=\\"content_copy\\"/> Crear una alternativa\\n                                            </button>\\n                                            <button name=\\"action_send_winner_mailing\\" type=\\"object\\" class=\\"btn btn-link d-block\\" invisible=\\"not is_ab_test_sent or ab_testing_completed or ab_testing_winner_selection == 'manual'\\">\\n                                                <i class=\\"oi oi-filled\\" data-icon=\\"mail\\"/><span name=\\"ab_test_auto\\">\\n                                                   Enviar ganador ahora\\n                                                </span>\\n                                            </button>\\n                                            <button name=\\"action_select_as_winner\\" type=\\"object\\" class=\\"btn btn-link d-block\\" invisible=\\"ab_testing_completed or ab_testing_winner_selection != 'manual'\\">\\n                                                <i class=\\"oi oi-filled\\" data-icon=\\"mail\\"/> Enviar esto al ganador\\n                                            </button>\\n                                        </div>\\n                                        <button name=\\"action_duplicate\\" type=\\"object\\" class=\\"btn btn-primary\\" invisible=\\"ab_testing_mailings_count &gt;= 2 or not ab_testing_enabled\\">\\n                                            Crear una versión alternativa\\n                                        </button>\\n                                    </div>\\n                                </div>\\n                            </page>\\n                        </notebook>\\n                    </sheet>\\n                    <chatter/>\\n                </form>"}	<?xml version="1.0"?>\n<form string="Mailing" class="o_mass_mailing_mailing_form">\n                    <header>\n                        <button name="action_new_mailing_from_template" type="object" class="oe_highlight" string="Use this" invisible="not is_template or not body_arch"/>\n                        <button name="action_launch" type="object" class="oe_highlight" string="Send" invisible="is_template or state in ('in_queue', 'sending', 'done')" data-hotkey="q" confirm="Once you send these emails, they'll be making a grand entrance in all the inboxes, creating quite the buzz!" confirm-title="Ready to unleash emails?" confirm-label="Send to all"/>\n                        <button name="action_schedule" type="object" class="btn-secondary" string="Schedule" invisible="is_template or state in ('in_queue', 'sending', 'done')" data-hotkey="v"/>\n                        <button name="action_retry_failed" type="object" invisible="is_template or state != 'done' or failed == 0" string="Retry" data-hotkey="y"/>\n                        <button name="action_duplicate" type="object" class="btn-secondary" string="Duplicate" data-hotkey="d" invisible="not is_template and state != 'done'"/>\n                        <button name="action_preview" type="object" class="btn-secondary" string="Preview" data-hotkey="k" invisible="is_template or not body_html or is_body_empty or state == 'done'"/>\n                        <button name="action_test" type="object" class="btn-secondary" string="Test" data-hotkey="t" invisible="is_template or not body_html or is_body_empty or state == 'done'"/>\n                        <button name="action_cancel" type="object" invisible="is_template or state != 'in_queue'" class="btn-secondary" string="Cancel" data-hotkey="x"/>\n                        <div class="alert alert-info o_mass_mailing_alert_message mb-0 ms-2 py-1" role="alert" invisible="is_template or state != 'in_queue' and scheduled == 0 and not warning_message">\n                            <div class="o_mails_in_queue" invisible="state != 'in_queue'">\n                                <strong invisible="next_departure_is_past or schedule_type == 'now'">\n                                    <span name="next_departure_text">This mailing is scheduled for </span>\n                                    <field name="next_departure" class="oe_inline"/>.\n                                </strong>\n                                <strong invisible="not next_departure_is_past or schedule_type == 'now'" class="d-flex align-items-center">\n                                    <field name="next_departure_is_past" invisible="1"/>\n                                    <span name="refresh_text">This mailing will be sent as soon as possible.</span>\n                                    <button name="action_reload" type="object" class="btn btn-link pe-0">\n                                        <u>Refresh <i class="oi ms-1" data-icon="refresh"/></u>\n                                    </button>\n                                </strong>\n                                <strong invisible="schedule_type != 'now'" class="d-flex align-items-center">\n                                    <field name="next_departure_is_past" invisible="1"/>\n                                    <field name="schedule_type" invisible="1"/>\n                                    <span name="mailing_schedule_type_now_text">This mailing will be sent as soon as possible.</span>\n                                    <button name="action_reload" type="object" class="btn btn-link pe-0">\n                                        <u>Refresh <i class="oi ms-1" data-icon="refresh"/></u>\n                                    </button>\n                                </strong>\n                            </div>\n                            <div class="o_mails_scheduled o_mails_process" invisible="scheduled == 0 and process == 0">\n                                <span invisible="scheduled == 0">\n                                    <button class="btn btn-link p-0" name="action_view_traces_scheduled" type="object">\n                                        <strong>\n                                            <field name="scheduled" class="oe_inline me-1"/>\n                                            <span name="scheduled_text">emails are in queue and will be sent soon</span>\n                                        </strong>\n                                    </button>\n                                </span>\n                                <span invisible="not scheduled or not process">, </span>\n                                <span invisible="process == 0">\n                                    <button class="btn btn-link p-0" name="action_view_traces_process" type="object">\n                                        <strong>\n                                            <field name="process" class="oe_inline me-1"/>\n                                            <span name="process_text">emails are being processed</span>\n                                        </strong>\n                                    </button>\n                                </span>\n                                <span>.</span>\n                            </div>\n                        </div>\n                        <field name="state" readonly="1" widget="statusbar" statusbar_visible="draft,sending,done" invisible="is_template"/>\n                    </header>\n                    <field name="is_template" invisible="1"/>\n                    <div class="alert alert-info" role="alert" invisible="is_template or not warning_message">\n                        <strong><field name="warning_message"/></strong>\n                    </div>\n                    <sheet>\n                        <div class="badge rounded-pill text-bg-300 float-end border-0" invisible="not is_template">Template</div>\n                        <div class="oe_button_box" name="button_box" invisible="is_template">\n                            <button name="action_view_traces" type="object" invisible="state in ('draft', 'test')" class="oe_stat_button">\n                                <field name="delivered" invisible="1"/>\n                                <field name="received_ratio" widget="deliverance_percentpie" top_field="delivered" bottom_field="failed"/>\n                            </button>\n                            <button name="action_view_traces_canceled" type="object" invisible="state in ('draft', 'test') or canceled == 0">\n                                <field name="canceled_ratio" string="Canceled" widget="percentpie"/>\n                            </button>\n                            <button name="action_view_opened" type="object" context="{'search_default_filter_opened': True,                                     'search_default_state': True,}" invisible="state in ('draft', 'test')" class="oe_stat_button">\n                                <field name="opened_ratio" string="Opened" widget="percentpie"/>\n                            </button>\n                            <button name="action_view_replied" type="object" context="{'search_default_filter_replied': True}" invisible="state in ('draft', 'test')" class="oe_stat_button">\n                                <field name="replied_ratio" string="Replied" widget="percentpie"/>\n                            </button>\n                            <button name="action_view_clicked" type="object" context="{'search_default_filter_clicked': True}" invisible="state in ('draft', 'test')" class="oe_stat_button">\n                                <field name="clicks_ratio" string="Clicked" widget="percentpie"/>\n                            </button>\n                            <button name="action_view_bounced" type="object" context="{'search_default_filter_bounced': True}" invisible="state in ('draft', 'test')" class="oe_stat_button">\n                                <field name="bounced_ratio" string="Bounced" widget="percentpie"/>\n                            </button>\n                            <button name="action_view_link_trackers" invisible="state != 'done'" type="object" class="oe_stat_button" icon="link">\n                                <field name="link_trackers_count" widget="statinfo" string="Link Trackers"/>\n                            </button>\n                        </div>\n                        <widget name="web_ribbon" title="Archived" bg_color="text-bg-danger" invisible="active"/>\n                        <group class="o_mass_mailing_mailing_group">\n                            <field name="active" invisible="1"/>\n                            <field name="create_uid" invisible="1"/>\n                            <field name="mailing_type" widget="radio" options="{'horizontal': true}" invisible="1" readonly="state != 'draft'" force_save="1"/>\n                            <field class="text-break w-75" name="subject" options="{'dynamic_placeholder': true, 'dynamic_placeholder_model_reference_field': 'mailing_model_real'}" readonly="state in ('sending', 'done')" widget="char_emojis" placeholder="e.g. New Sale on all T-shirts"/>\n                            <label for="mailing_model_id" string="Recipients"/>\n                            <div name="mailing_model_id_container">\n                                <div class="row">\n                                    <div class="col-md-auto">\n                                        <field name="mailing_model_id" options="{'no_open': True, 'no_create': True}" readonly="state in ('sending', 'done')" placeholder="Select a Target"/>\n                                    </div>\n                                    <!-- MANUAL LISTS -->\n                                    <div invisible="is_template or not mailing_on_mailing_list" class="o_mass_mailing_contact_list_ids col-md-auto">\n                                        <label for="contact_list_ids" string="Mailing Lists:" class="oe_edit_only pe-3"/>\n                                        <div class="d-inline-flex flex-row align-items-center">\n                                            <field name="contact_list_ids" widget="many2many_tags" placeholder="Select recipients..." class="oe_inline mb-0" context="{'form_view_ref': 'mass_mailing.mailing_list_view_form_simplified'}" domain="[('active', '=', True)]" readonly="state in ('sending', 'done')" options="{'color_field': 'color'}"/>\n                                            <button icon="person_add" icon_class="oi-filled" type="object" class="btn btn-secondary py-0 px-1 ms-1" invisible="not contact_list_ids or not contact_list_ids or state in ('sending', 'done')" name="action_import_mailing_contacts" title="Import Mailing Contacts"/>\n                                        </div>\n                                    </div>\n                                    <!-- DYNAMIC LISTS -->\n                                    <div class="col-md-auto" invisible="is_template or not mailing_model_id or mailing_on_mailing_list or (state in ('sending', 'done') and not mailing_filter_ids)">\n                                        <label for="mailing_filter_ids" string="Dynamic Lists:" class="oe_edit_only pe-3"/>\n                                        <field name="mailing_filter_ids" widget="mailing_many2many_tags" placeholder="Select dynamic lists..." class="o_field_many2many_tags oe_inline mb-0" context="{                                                 'form_view_ref': 'mass_mailing.mailing_filter_view_form_simplified',                                                  'default_mailing_model_id': mailing_model_id                                             }" options="{'no_quick_create': True, 'on_tag_click': 'open_form', 'color_field': 'color'}" readonly="state in ('sending', 'done')"/>\n                                        <div invisible="not mailing_filter_ids or state == 'done'" class="o_mass_mailing_recipients_count d-inline-flex align-items-baseline gap-1 text-nowrap ms-2 text-muted">\n                                            <field name="recipients_count" class="lh-1"/>\n                                            <span>Recipients</span>\n                                        </div>\n                                    </div>\n                                    <div invisible="is_template or mailing_model_real == 'mailing.contact'" class="o_mass_mailing_use_exclusion_list col-md-auto">\n                                        <field name="use_exclusion_list" string="Use Exclusion List" readonly="state != 'draft'"/>\n                                        <label for="use_exclusion_list" class="ps-2" string="Exclude Blacklisted Recipients"/>\n                                    </div>\n                                </div>\n                            </div>\n                            <label for="mailing_domain" string="Domain" invisible="is_template or not mailing_model_id or mailing_on_mailing_list or mailing_filter_ids"/>\n                            <div invisible="is_template or not mailing_model_id or mailing_on_mailing_list or mailing_filter_ids">\n                                <field name="mailing_domain" widget="domain_savable" options="{'model': 'mailing_model_real', 'foldable': True, 'model_id': 'mailing_model_id'}" readonly="state in ('sending', 'done')"/>\n                            </div>\n                            <field name="mailing_model_name" invisible="1"/>\n                            <field name="mailing_on_mailing_list" invisible="1"/>\n                            <field name="mailing_model_real" invisible="1"/>\n                        </group>\n                        <notebook>\n                            <page string="Mail Body" name="mail_body">\n                                <div class="position-relative">\n                                    <field name="body_arch" class="o_mail_body_mailing" widget="mass_mailing_html" required="is_template" options="{                                             'inline_field': 'body_html',                                             'dynamic_placeholder': true,                                             'dynamic_placeholder_model_reference_field': 'mailing_model_real',                                             'filterTemplates': true,                                         }" readonly="state in ('sending', 'done')"/>\n                                    <field name="body_html" invisible="1" required="body_arch"/>\n                                    <field name="is_body_empty" invisible="1"/>\n                                </div>\n                            </page>\n                            <page string="Settings" name="settings" invisible="is_template">\n                                <group>\n                                    <group string="Email Content" name="email_content" invisible="mailing_type != 'mail'">\n                                        <field class="o_text_overflow" name="preview" string="Preview Text" options="{'dynamic_placeholder': true, 'dynamic_placeholder_model_reference_field': 'mailing_model_real'}" readonly="state in ('sending', 'done')" widget="char_emojis" placeholder="This text will appear in inboxes, next to the subject"/>\n                                        <field name="email_from" readonly="state in ('sending', 'done')" required="mailing_type == 'mail' and not is_template"/>\n                                        <label for="reply_to"/>\n                                        <div name="reply_to_details">\n                                            <field name="reply_to_mode" widget="radio" invisible="mailing_model_name in ['mailing.contact', 'res.partner', 'mailing.list']" readonly="state in ('sending', 'done')"/>\n                                            <field name="reply_to" invisible="reply_to_mode == 'update'" readonly="state in ('sending', 'done')" required="not is_template and reply_to_mode == 'new'"/>\n                                            <div style="margin-top:-5px">\n                                                <small class="oe_edit_only text-muted mb-2" style="font-size:74%" invisible="reply_to_mode == 'update' or mailing_model_name in ['mailing.contact', 'res.partner', 'mailing.list']">\n                                                    To track replies, this address must belong to this database.\n                                                </small>\n                                            </div>\n                                        </div>\n                                        <label for="attachment_ids"/>\n                                        <div name="attachment_ids_details">\n                                            <field name="attachment_ids" widget="many2many_binary" string="Attach a file" readonly="state in ('sending', 'done')"/>\n                                        </div>\n                                    </group>\n                                    <group string="Tracking">\n                                        <field name="campaign_id" string="Campaign" groups="mass_mailing.group_mass_mailing_campaign" options="{'create_name_field': 'title'}" readonly="state in ('sending', 'done')"/>\n                                        <field name="medium_id" string="Medium" required="True"/>\n                                        <field name="source_id" string="Source" class="o_text_overflow" required="False"/>\n                                        <field name="user_id" widget="many2one_avatar_user" domain="[('share', '=', False)]"/>\n                                    </group>\n                                    <group string="Advanced">\n                                        <field name="mail_server_available" invisible="1"/>\n                                        <field name="mail_server_id" invisible="not mail_server_available" readonly="state in ('sending', 'done')" domain="[('owner_user_id', '=', False)]"/>\n                                        <field name="keep_archives" readonly="state in ('sending', 'done')"/>\n                                    </group>\n                                </group>\n                                <div class="row" name="ab_testing">\n                                    <group class="col-12 col-md-6">\n                                        <label for="ab_testing_enabled"/>\n                                        <span class="d-flex">\n                                            <field name="ab_testing_enabled" readonly="state != 'draft'" force_save="1"/>\n                                            <span class="d-flex" invisible="not ab_testing_enabled">\n                                                on <field name="ab_testing_pc" class="mx-1 text-center" readonly="state != 'draft'"/> %\n                                            </span>\n                                        </span>\n                                        <field name="ab_testing_version_name" invisible="not ab_testing_enabled" placeholder="e.g. 'Header with product picture'"/>\n                                        <field name="ab_testing_winner_selection" invisible="not ab_testing_enabled or mailing_type != 'mail'" readonly="state != 'draft'" required="ab_testing_enabled and mailing_type == 'mail'"/>\n                                        <field name="ab_testing_schedule_datetime" invisible="not ab_testing_enabled or ab_testing_winner_selection == 'manual'" readonly="not ab_testing_enabled or state != 'draft'" required="ab_testing_enabled and ab_testing_winner_selection != 'manual'"/>\n                                        <field name="is_ab_test_sent" invisible="1"/>\n                                    </group>\n                                    <div class="col-12 col-md-6">\n                                        <field name="ab_testing_mailings_count" invisible="1"/>\n                                        <field name="ab_testing_completed" invisible="1"/>\n                                        <field name="ab_testing_description" nolabel="1"/>\n                                        <div id="mailing_form_ab_buttons" invisible="ab_testing_mailings_count &lt; 2 or not ab_testing_enabled">\n                                            <button name="action_compare_versions" type="object" class="btn btn-link d-block">\n                                                <i class="oi" data-icon="bar_chart"/> Compare Version\n                                            </button>\n                                            <button name="action_duplicate" type="object" class="btn btn-link d-block" invisible="ab_testing_completed">\n                                                <i class="oi" data-icon="content_copy"/> Create an Alternative\n                                            </button>\n                                            <button name="action_send_winner_mailing" type="object" class="btn btn-link d-block" invisible="not is_ab_test_sent or ab_testing_completed or ab_testing_winner_selection == 'manual'">\n                                                <i class="oi oi-filled" data-icon="mail"/><span name="ab_test_auto">\n                                                    Send Winner Now\n                                                </span>\n                                            </button>\n                                            <button name="action_select_as_winner" type="object" class="btn btn-link d-block" invisible="ab_testing_completed or ab_testing_winner_selection != 'manual'">\n                                                <i class="oi oi-filled" data-icon="mail"/> Send this as winner\n                                            </button>\n                                        </div>\n                                        <button name="action_duplicate" type="object" class="btn btn-primary" invisible="ab_testing_mailings_count &gt;= 2 or not ab_testing_enabled">\n                                            Create an Alternative Version\n                                        </button>\n                                    </div>\n                                </div>\n                            </page>\n                        </notebook>\n                    </sheet>\n                    <chatter/>\n                </form>\n            	\N	f	t	2026-10-26 23:48:58.810362	2026-10-26 23:48:58.810362	f
1644	16	\N	1	1	todo_user_onboarding	\N	project_todo.todo_user_onboarding	qweb	project_todo/data/todo_template.xml	primary	\N	{"en_US": "<t t-name=\\"project_todo.todo_user_onboarding\\">\\n<h1>\\n    <span style=\\"font-size: 36px; color: #374151\\">Hey <t t-out=\\"object.name\\"/> &amp;#128075; <br/>\\n    Welcome to the To-do app! </span>\\n</h1>\\n<p>\\n    <span style=\\"font-size: 14px;\\">\\n        Use it to manage your work, take notes on the go, and create tasks based on them.\\n    </span>\\n</p>\\n<p><br/></p>\\n<h3>Using the editor</h3>\\n<hr/>\\n<p>\\n    <span style=\\"font-size: 14px;\\">This private to-do is for you to play around with.</span>\\n    <br/>\\n    <span style=\\"font-size: 14px;\\">Ready to give it a spin?</span>\\n</p>\\n<p>\\n    <span style=\\"font-size: 14px;\\">Try the following</span>\\n</p>\\n<ul class=\\"o_checklist\\">\\n    <li id=\\"checkId-948702291173\\">\\n        <span style=\\"font-size: 14px;\\">Check this box to indicate it's done</span>\\n    </li>\\n    <li id=\\"checkId-140908257281\\">\\n        <span style=\\"font-size: 14px;\\">Click anywhere, and just start typing</span>\\n    </li>\\n    <li id=\\"checkId-441216037148\\">\\n        <span style=\\"font-size: 14px;\\">Press Ctrl+Z/⌘+Z to undo any change</span>\\n    </li>\\n    <li id=\\"checkId-980463482772\\">\\n        <span style=\\"font-size: 14px;\\">\\n            Select text to\\n            <font style=\\"background-color: #017E84; color: white\\">Highlight</font>,\\n            <span style=\\"text-decoration-line: line-through;\\">strikethrough</span>\\n            or\\n            <span style=\\"font-weight: bolder;\\">style</span>\\n            <span style=\\"font-style: italic; text-decoration-line: underline;\\">it</span>\\n        </span>\\n    </li>\\n    <li id=\\"checkId-152369821198\\">\\n        <span style=\\"font-size: 14px;\\">\\n            Below this list, try\\n            <span style=\\"font-weight: bolder;\\">commands</span>\\n            by\\n            <span style=\\"font-weight: bolder;\\">\\n                <font style=\\"color: #017E84\\">typing</font>\\n            </span>\\n            \\"<span style=\\"font-weight: bolder;\\">/</span>\\"\\n        </span>\\n    </li>\\n    <li class=\\"oe-nested\\" id=\\"checkId-947916154443\\">\\n        <ul class=\\"o_checklist\\">\\n            <li id=\\"checkId-1422510558483\\">\\n                <span style=\\"font-size: 14px;\\">\\n                    Add a checklist\\n                    (/<span style=\\"font-style: italic;\\">checklist</span>)\\n                </span>\\n            </li>\\n            <li id=\\"checkId-109605733655\\">\\n                <span style=\\"font-size: 14px;\\">\\n                    Add a separator\\n                    (/<span style=\\"font-style: italic;\\">separator</span>)\\n                </span>\\n            </li>\\n            <li id=\\"checkId-1518315885641\\">\\n                <span style=\\"font-size: 14px;\\">\\n                    Use\\n                    /<span style=\\"font-style: italic;\\">heading</span>\\n                    to convert a text into a title\\n                </span>\\n            </li>\\n        </ul>\\n    </li>\\n</ul>\\n<p><br/></p>\\n\\n<h3>Who has access to what?</h3>\\n<hr/>\\n<p>\\n    <span style=\\"font-size: 14px;\\">\\n        By default, to-dos are only visible to you. You can share them with other users by adding them as\\n        <span>\\n            <font style=\\"font-weight: bolder;\\" class=\\"text-o-color-2\\">assignees</font>.\\n        </span>\\n    </span>\\n    <br/>\\n    <img class=\\"img-fluid d-none d-sm-block\\" src=\\"/project_todo/static/img/todo_access.png\\" alt=\\"todo-access\\" style=\\"width: 50%;\\"/>\\n</p>\\n<p><br/></p>\\n\\n<h3>Organize your to-dos however you want</h3>\\n<hr/>\\n<p>\\n    <span style=\\"font-size: 14px;\\">\\n        Customize the stages from the\\n        <span style=\\"font-weight: bolder;\\">\\n            <font class=\\"text-o-color-2\\">Kanban view</font>\\n        </span>\\n        to reflect your preferred workflow.\\n    </span>\\n</p>\\n<p><br/></p>\\n\\n<t name=\\"shortcut_section\\">\\n    <h3 class=\\"fw-bolder\\">Enhance Your To-Dos with Shortcuts &amp;#9889;</h3>\\n    <hr/>\\n    <p>\\n        <span style=\\"font-size: 14px;\\">\\n            Use these keywords in the title to streamline your to-dos:\\n        </span>\\n        <br/>\\n        <ul>\\n            <li>\\n                <span style=\\"font-weight: bolder;\\">\\n                    <font class=\\"text-o-color-2\\">#tags:</font>\\n                </span>\\n                Add tags to categorize the to-do\\n            </li>\\n            <li>\\n                <span style=\\"font-weight: bolder;\\">\\n                    <font class=\\"text-o-color-2\\">@user:</font>\\n                </span>\\n                Assign the to-do to a specific user\\n            </li>\\n            <li>\\n                <span style=\\"font-weight: bolder;\\">\\n                    <font class=\\"text-o-color-2\\">!:</font>\\n                </span>\\n                Mark the to-do as medium priority\\n            </li>\\n            <li>\\n                <span style=\\"font-weight: bolder;\\">\\n                    <font class=\\"text-o-color-2\\">!!:</font>\\n                </span>\\n                Mark the to-do as high priority\\n            </li>\\n            <li>\\n                <span style=\\"font-weight: bolder;\\">\\n                    <font class=\\"text-o-color-2\\">!!!:</font>\\n                </span>\\n                Mark the to-do as urgent\\n            </li>\\n        </ul>\\n        <br/>\\n        <span style=\\"font-size: 14px;\\">\\n            Ensure you follow the correct format and order. For example: Send invitations #event @Mitchell !\\n        </span>\\n    </p>\\n    <p><br/></p>\\n</t>\\n\\n<h3 class=\\"fw-bolder\\">Manage your to-dos and assigned tasks from a single place</h3>\\n<hr/>\\n<p>\\n    <span style=\\"font-size: 14px;\\">\\n        Access your personal pipeline with your to-dos and assigned tasks by going to the Project app and clicking\\n        <span>\\n            <font style=\\"font-weight: bolder;\\" class=\\"text-o-color-2\\">My Tasks</font>.\\n        </span>\\n    </span>\\n    <br/>\\n    <br/>\\n    <span style=\\"font-size: 14px;\\">\\n        There, your to-dos are listed as\\n        <span style=\\"font-weight: bolder;\\">\\n            <font class=\\"text-o-color-2\\">private tasks.</font>\\n        </span>\\n        Any task you create privately will also be included in your to-dos. Essentially, they are interchangeable.\\n    </span>\\n</p>\\n<p><br/></p>\\n\\n<h3>Convert to-dos into tasks</h3>\\n<hr/>\\n<p>\\n    <span style=\\"font-size: 14px;\\">\\n        If you want to assign your to-do to a specific project, open the ⚙️ menu and click\\n        <span>\\n            <font style=\\"font-weight: bolder;\\" class=\\"text-o-color-2\\">Convert to Task</font>.\\n        </span>\\n        This action will make it visible to other users.\\n    </span>\\n    <br/>\\n    <img class=\\"img-fluid d-none d-sm-block\\" src=\\"/project_todo/static/img/convert_todo.png\\" alt=\\"convert-todo\\" style=\\"width: 50%;\\"/>\\n</p>\\n<p><br/></p>\\n\\n<h3>Create to-dos from anywhere</h3>\\n<hr/>\\n<p>\\n    <span style=\\"font-size: 14px;\\">\\n        Wherever you are, use the magic keyboard shortcut to add yourself a reminder &amp;#128161;\\n    </span>\\n    <br/>\\n    <ul>\\n        <li>\\n            <span style=\\"font-weight: bolder;\\">\\n                <font class=\\"text-o-color-2\\">Alt + Shift + T</font>\\n            </span>\\n            (Windows/Linux)\\n        </li>\\n        <li>\\n            <span style=\\"font-weight: bolder;\\">\\n                <font class=\\"text-o-color-2\\">Ctrl + Shift + T</font>\\n            </span>\\n            (MacOs)\\n        </li>\\n    </ul>\\n</p>\\n    </t>", "es_ES": "<t t-name=\\"project_todo.todo_user_onboarding\\">\\n<h1>\\n    <span style=\\"font-size: 36px; color: #374151\\">Hola <t t-out=\\"object.name\\"/> &amp;#128075; <br/>\\n    ¡Le damos la bienvenida a la aplicación Actividades pendientes! </span>\\n</h1>\\n<p>\\n    <span style=\\"font-size: 14px;\\">\\n        Úsela para administrar su trabajo, tomar notas al instante y crear tareas.\\n    </span>\\n</p>\\n<p><br/></p>\\n<h3>Usando el editor</h3>\\n<hr/>\\n<p>\\n    <span style=\\"font-size: 14px;\\">En esta actividad pendiente podrá probar todas las funciones que desee.</span>\\n    <br/>\\n    <span style=\\"font-size: 14px;\\">¿Está listo para explorar?</span>\\n</p>\\n<p>\\n    <span style=\\"font-size: 14px;\\">Intente lo siguiente</span>\\n</p>\\n<ul class=\\"o_checklist\\">\\n    <li id=\\"checkId-948702291173\\">\\n        <span style=\\"font-size: 14px;\\">Marque esta casilla para indicar que está hecha</span>\\n    </li>\\n    <li id=\\"checkId-140908257281\\">\\n        <span style=\\"font-size: 14px;\\">Haga clic en cualquier parte y solo comience a escribir</span>\\n    </li>\\n    <li id=\\"checkId-441216037148\\">\\n        <span style=\\"font-size: 14px;\\">Presione Ctrl+Z/⌘+Z para deshacer cualquier cambio</span>\\n    </li>\\n    <li id=\\"checkId-980463482772\\">\\n        <span style=\\"font-size: 14px;\\">\\n            Seleccione el texto para\\n            <font style=\\"background-color: #017E84; color: white\\">resaltarlo</font>,\\n            <span style=\\"text-decoration-line: line-through;\\">tacharlo</span>\\n            o\\n            <span style=\\"font-weight: bolder;\\">darle</span>\\n            <span style=\\"font-style: italic; text-decoration-line: underline;\\">estilo</span>\\n        </span>\\n    </li>\\n    <li id=\\"checkId-152369821198\\">\\n        <span style=\\"font-size: 14px;\\">\\n            Debajo de esta lista, pruebe los\\n            <span style=\\"font-weight: bolder;\\">comandos</span>\\n            ,\\n            <span style=\\"font-weight: bolder;\\">\\n                <font style=\\"color: #017E84\\">escribiendo</font>\\n            </span>\\n            \\"<span style=\\"font-weight: bolder;\\">/</span>\\"\\n        </span>\\n    </li>\\n    <li class=\\"oe-nested\\" id=\\"checkId-947916154443\\">\\n        <ul class=\\"o_checklist\\">\\n            <li id=\\"checkId-1422510558483\\">\\n                <span style=\\"font-size: 14px;\\">\\n                    Añadir una lista de comprobación\\n                    (/<span style=\\"font-style: italic;\\">lista de comprobación</span>)\\n                </span>\\n            </li>\\n            <li id=\\"checkId-109605733655\\">\\n                <span style=\\"font-size: 14px;\\">\\n                    Añadir un separador\\n                    (/<span style=\\"font-style: italic;\\">separador</span>)\\n                </span>\\n            </li>\\n            <li id=\\"checkId-1518315885641\\">\\n                <span style=\\"font-size: 14px;\\">\\n                    Utilicar \\n                    /<span style=\\"font-style: italic;\\">título</span>\\n                    para convertir el texto a título\\n                </span>\\n            </li>\\n        </ul>\\n    </li>\\n</ul>\\n<p><br/></p>\\n\\n<h3>¿Quién tiene acceso a qué?</h3>\\n<hr/>\\n<p>\\n    <span style=\\"font-size: 14px;\\">\\n        Por defecto, las tareas pendientes sólo son visibles para usted. Puede compartirlas con otros usuarios si los añade como\\n        <span>\\n            <font style=\\"font-weight: bolder;\\" class=\\"text-o-color-2\\">personas asignadas</font>.\\n        </span>\\n    </span>\\n    <br/>\\n    <img class=\\"img-fluid d-none d-sm-block\\" src=\\"/project_todo/static/img/todo_access.png\\" alt=\\"todo-access\\" style=\\"width: 50%;\\"/>\\n</p>\\n<p><br/></p>\\n\\n<h3>Organice sus actividades pendientes como quiera</h3>\\n<hr/>\\n<p>\\n    <span style=\\"font-size: 14px;\\">\\n        Personalice las etapas con la\\n        <span style=\\"font-weight: bolder;\\">\\n            <font class=\\"text-o-color-2\\">vista de kanban</font>\\n        </span>\\n        para que coincidan con su flujo de trabajo preferido.\\n    </span>\\n</p>\\n<p><br/></p>\\n\\n<t name=\\"shortcut_section\\">\\n    <h3 class=\\"fw-bolder\\">Mejora tus tareas pendientes con atajos &amp;#9889;</h3>\\n    <hr/>\\n    <p>\\n        <span style=\\"font-size: 14px;\\">\\n            Use these keywords in the title to streamline your to-dos:\\n        </span>\\n        <br/>\\n        <ul>\\n            <li>\\n                <span style=\\"font-weight: bolder;\\">\\n                    <font class=\\"text-o-color-2\\">#tags:</font>\\n                </span>\\n                Add tags to categorize the to-do\\n            </li>\\n            <li>\\n                <span style=\\"font-weight: bolder;\\">\\n                    <font class=\\"text-o-color-2\\">@user:</font>\\n                </span>\\n                Assign the to-do to a specific user\\n            </li>\\n            <li>\\n                <span style=\\"font-weight: bolder;\\">\\n                    <font class=\\"text-o-color-2\\">!:</font>\\n                </span>\\n                Mark the to-do as medium priority\\n            </li>\\n            <li>\\n                <span style=\\"font-weight: bolder;\\">\\n                    <font class=\\"text-o-color-2\\">!!:</font>\\n                </span>\\n                Mark the to-do as high priority\\n            </li>\\n            <li>\\n                <span style=\\"font-weight: bolder;\\">\\n                    <font class=\\"text-o-color-2\\">!!!:</font>\\n                </span>\\n                Mark the to-do as urgent\\n            </li>\\n        </ul>\\n        <br/>\\n        <span style=\\"font-size: 14px;\\">\\n            Ensure you follow the correct format and order. For example: Send invitations #event @Mitchell !\\n        </span>\\n    </p>\\n    <p><br/></p>\\n</t>\\n\\n<h3 class=\\"fw-bolder\\">Gestione sus actividades pendientes y tareas asignadas desde un solo lugar</h3>\\n<hr/>\\n<p>\\n    <span style=\\"font-size: 14px;\\">\\n        Acceda a su flujo y sus tareas pendientes desde la aplicación de Proyecto y luego haga clic en\\n        <span>\\n            <font style=\\"font-weight: bolder;\\" class=\\"text-o-color-2\\">Mis tareas</font>.\\n        </span>\\n    </span>\\n    <br/>\\n    <br/>\\n    <span style=\\"font-size: 14px;\\">\\n        Allí aparecerán su actividades pendientes como\\n        <span style=\\"font-weight: bolder;\\">\\n            <font class=\\"text-o-color-2\\">tareas privadas.</font>\\n        </span>\\n        Todas las tareas que cree en privado también aparecerán en sus actividades pendientes.\\n    </span>\\n</p>\\n<p><br/></p>\\n\\n<h3>Convertir las actividades pendientes en tareas</h3>\\n<hr/>\\n<p>\\n    <span style=\\"font-size: 14px;\\">\\n        Si desea asignar su actividad pendiente a un proyecto específico, abra el menú ⚙️ y haga clic en\\n        <span>\\n            <font style=\\"font-weight: bolder;\\" class=\\"text-o-color-2\\">Convertir en tarea</font>.\\n        </span>\\n        Esta acción hará que otros usuarios puedan verla.\\n    </span>\\n    <br/>\\n    <img class=\\"img-fluid d-none d-sm-block\\" src=\\"/project_todo/static/img/convert_todo.png\\" alt=\\"convert-todo\\" style=\\"width: 50%;\\"/>\\n</p>\\n<p><br/></p>\\n\\n<h3>Cree actividades pendientes desde cualquier lugar</h3>\\n<hr/>\\n<p>\\n    <span style=\\"font-size: 14px;\\">\\n        Use los atajos del teclado para añadir sus recordatorios &amp;#128161;\\n    </span>\\n    <br/>\\n    <ul>\\n        <li>\\n            <span style=\\"font-weight: bolder;\\">\\n                <font class=\\"text-o-color-2\\">Alt + Shift + T</font>\\n            </span>\\n            (Windows/Linux)\\n        </li>\\n        <li>\\n            <span style=\\"font-weight: bolder;\\">\\n                <font class=\\"text-o-color-2\\">Ctrl + Shift + T</font>\\n            </span>\\n            (MacOS)\\n        </li>\\n    </ul>\\n</p>\\n    </t>"}	<?xml version="1.0"?>\n<t t-name="project_todo.todo_user_onboarding">\n<h1>\n    <span style="font-size: 36px; color: #374151">Hey <t t-out="object.name"/> &amp;#128075; <br/>\n    Welcome to the To-do app! </span>\n</h1>\n<p>\n    <span style="font-size: 14px;">\n        Use it to manage your work, take notes on the go, and create tasks based on them.\n    </span>\n</p>\n<p><br/></p>\n<h3>Using the editor</h3>\n<hr/>\n<p>\n    <span style="font-size: 14px;">This private to-do is for you to play around with.</span>\n    <br/>\n    <span style="font-size: 14px;">Ready to give it a spin?</span>\n</p>\n<p>\n    <span style="font-size: 14px;">Try the following</span>\n</p>\n<ul class="o_checklist">\n    <li id="checkId-948702291173">\n        <span style="font-size: 14px;">Check this box to indicate it's done</span>\n    </li>\n    <li id="checkId-140908257281">\n        <span style="font-size: 14px;">Click anywhere, and just start typing</span>\n    </li>\n    <li id="checkId-441216037148">\n        <span style="font-size: 14px;">Press Ctrl+Z/⌘+Z to undo any change</span>\n    </li>\n    <li id="checkId-980463482772">\n        <span style="font-size: 14px;">\n            Select text to\n            <font style="background-color: #017E84; color: white">Highlight</font>,\n            <span style="text-decoration-line: line-through;">strikethrough</span>\n            or\n            <span style="font-weight: bolder;">style</span>\n            <span style="font-style: italic; text-decoration-line: underline;">it</span>\n        </span>\n    </li>\n    <li id="checkId-152369821198">\n        <span style="font-size: 14px;">\n            Below this list, try\n            <span style="font-weight: bolder;">commands</span>\n            by\n            <span style="font-weight: bolder;">\n                <font style="color: #017E84">typing</font>\n            </span>\n            "<span style="font-weight: bolder;">/</span>"\n        </span>\n    </li>\n    <li class="oe-nested" id="checkId-947916154443">\n        <ul class="o_checklist">\n            <li id="checkId-1422510558483">\n                <span style="font-size: 14px;">\n                    Add a checklist\n                    (/<span style="font-style: italic;">checklist</span>)\n                </span>\n            </li>\n            <li id="checkId-109605733655">\n                <span style="font-size: 14px;">\n                    Add a separator\n                    (/<span style="font-style: italic;">separator</span>)\n                </span>\n            </li>\n            <li id="checkId-1518315885641">\n                <span style="font-size: 14px;">\n                    Use\n                    /<span style="font-style: italic;">heading</span>\n                    to convert a text into a title\n                </span>\n            </li>\n        </ul>\n    </li>\n</ul>\n<p><br/></p>\n\n<h3>Who has access to what?</h3>\n<hr/>\n<p>\n    <span style="font-size: 14px;">\n        By default, to-dos are only visible to you. You can share them with other users by adding them as\n        <span>\n            <font style="font-weight: bolder;" class="text-o-color-2">assignees</font>.\n        </span>\n    </span>\n    <br/>\n    <img class="img-fluid d-none d-sm-block" src="/project_todo/static/img/todo_access.png" alt="todo-access" style="width: 50%;"/>\n</p>\n<p><br/></p>\n\n<h3>Organize your to-dos however you want</h3>\n<hr/>\n<p>\n    <span style="font-size: 14px;">\n        Customize the stages from the\n        <span style="font-weight: bolder;">\n            <font class="text-o-color-2">Kanban view</font>\n        </span>\n        to reflect your preferred workflow.\n    </span>\n</p>\n<p><br/></p>\n\n<t name="shortcut_section">\n    <h3 class="fw-bolder">Enhance Your To-Dos with Shortcuts &amp;#9889;</h3>\n    <hr/>\n    <p>\n        <span style="font-size: 14px;">\n            Use these keywords in the title to streamline your to-dos:\n        </span>\n        <br/>\n        <ul>\n            <li>\n                <span style="font-weight: bolder;">\n                    <font class="text-o-color-2">#tags:</font>\n                </span>\n                Add tags to categorize the to-do\n            </li>\n            <li>\n                <span style="font-weight: bolder;">\n                    <font class="text-o-color-2">@user:</font>\n                </span>\n                Assign the to-do to a specific user\n            </li>\n            <li>\n                <span style="font-weight: bolder;">\n                    <font class="text-o-color-2">!:</font>\n                </span>\n                Mark the to-do as medium priority\n            </li>\n            <li>\n                <span style="font-weight: bolder;">\n                    <font class="text-o-color-2">!!:</font>\n                </span>\n                Mark the to-do as high priority\n            </li>\n            <li>\n                <span style="font-weight: bolder;">\n                    <font class="text-o-color-2">!!!:</font>\n                </span>\n                Mark the to-do as urgent\n            </li>\n        </ul>\n        <br/>\n        <span style="font-size: 14px;">\n            Ensure you follow the correct format and order. For example: Send invitations #event @Mitchell !\n        </span>\n    </p>\n    <p><br/></p>\n</t>\n\n<h3 class="fw-bolder">Manage your to-dos and assigned tasks from a single place</h3>\n<hr/>\n<p>\n    <span style="font-size: 14px;">\n        Access your personal pipeline with your to-dos and assigned tasks by going to the Project app and clicking\n        <span>\n            <font style="font-weight: bolder;" class="text-o-color-2">My Tasks</font>.\n        </span>\n    </span>\n    <br/>\n    <br/>\n    <span style="font-size: 14px;">\n        There, your to-dos are listed as\n        <span style="font-weight: bolder;">\n            <font class="text-o-color-2">private tasks.</font>\n        </span>\n        Any task you create privately will also be included in your to-dos. Essentially, they are interchangeable.\n    </span>\n</p>\n<p><br/></p>\n\n<h3>Convert to-dos into tasks</h3>\n<hr/>\n<p>\n    <span style="font-size: 14px;">\n        If you want to assign your to-do to a specific project, open the ⚙️ menu and click\n        <span>\n            <font style="font-weight: bolder;" class="text-o-color-2">Convert to Task</font>.\n        </span>\n        This action will make it visible to other users.\n    </span>\n    <br/>\n    <img class="img-fluid d-none d-sm-block" src="/project_todo/static/img/convert_todo.png" alt="convert-todo" style="width: 50%;"/>\n</p>\n<p><br/></p>\n\n<h3>Create to-dos from anywhere</h3>\n<hr/>\n<p>\n    <span style="font-size: 14px;">\n        Wherever you are, use the magic keyboard shortcut to add yourself a reminder &amp;#128161;\n    </span>\n    <br/>\n    <ul>\n        <li>\n            <span style="font-weight: bolder;">\n                <font class="text-o-color-2">Alt + Shift + T</font>\n            </span>\n            (Windows/Linux)\n        </li>\n        <li>\n            <span style="font-weight: bolder;">\n                <font class="text-o-color-2">Ctrl + Shift + T</font>\n            </span>\n            (MacOs)\n        </li>\n    </ul>\n</p>\n    </t>\n\n	\N	f	t	2026-10-26 23:49:18.153705	2026-10-26 23:49:18.153705	f
1326	16	\N	1	1	mailing.mailing.kanban	mailing.mailing	\N	kanban	mass_mailing/views/mailing_mailing_views.xml	primary	\N	{"en_US": "<kanban highlight_color=\\"color\\" default_group_by=\\"state\\" quick_create=\\"false\\" sample=\\"1\\">\\n                    <field name=\\"mailing_on_mailing_list\\"/>\\n                    <field name=\\"next_departure\\"/>\\n                    <field name=\\"active\\"/>\\n                    <templates>\\n                        <t t-name=\\"menu\\" t-if=\\"!selection_mode\\">\\n                            <field name=\\"color\\" widget=\\"kanban_color_picker\\"/>\\n                            <t t-if=\\"widget.deletable\\">\\n                                <a role=\\"menuitem\\" type=\\"delete\\" class=\\"dropdown-item\\">Delete</a>\\n                            </t>\\n                            <a role=\\"menuitem\\" type=\\"object\\" name=\\"action_archive\\" class=\\"dropdown-item o_kanban_mailing_active\\" t-if=\\"record.active.raw_value\\">Archive</a>\\n                            <a role=\\"menuitem\\" type=\\"object\\" name=\\"action_unarchive\\" class=\\"dropdown-item o_kanban_mailing_active\\" t-if=\\"!record.active.raw_value\\">Restore</a>\\n                        </t>\\n                        <t t-name=\\"card\\">\\n                            <field name=\\"subject\\" class=\\"my-1 text-truncate fs-3 fw-bold\\"/>\\n                            <field name=\\"campaign_id\\" invisible=\\"not sent_date\\" class=\\"fw-bold fs-5\\" groups=\\"mass_mailing.group_mass_mailing_campaign\\"/>\\n                            <div>\\n                                <i class=\\"oi me-2\\" data-icon=\\"crisis_alert\\" role=\\"img\\" aria-label=\\"Lead/Opportunity\\"/>\\n                                <field name=\\"mailing_model_id\\" invisible=\\"mailing_on_mailing_list\\"/>\\n                                <span invisible=\\"not mailing_on_mailing_list\\">Mailing Contact</span>\\n                            </div>\\n                            <footer class=\\"pt-0\\">\\n                                <div>\\n                                    <span invisible=\\"not sent_date\\" t-attf-title=\\"Sent on #{record.sent_date.value}\\">\\n                                        <span class=\\"oi oi-filled me-2 small my-auto\\" data-icon=\\"send\\" aria-label=\\"Sent date\\"/>\\n                                        <field name=\\"sent_date\\"/>\\n                                    </span>\\n                                    <span invisible=\\"not schedule_date\\" t-attf-title=\\"Scheduled on #{record.schedule_date.value}\\">\\n                                        <span class=\\"oi me-2 small my-auto\\" data-icon=\\"hourglass_bottom\\" aria-label=\\"Scheduled date\\"/>\\n                                        <field name=\\"schedule_date\\" readonly=\\"state not in ['draft', 'in_queue']\\"/>\\n                                    </span>\\n                                    <span invisible=\\"sent_date or schedule_date or state == 'in_queue'\\">\\n                                        <field name=\\"total\\" class=\\"me-1 fw-bold\\"/>\\n                                        <field name=\\"mailing_model_id\\" invisible=\\"mailing_on_mailing_list\\"/>\\n                                        <span invisible=\\"not mailing_on_mailing_list\\">Mailing Contact</span>\\n                                    </span>\\n                                    <span invisible=\\"schedule_date or state != 'in_queue' or not next_departure\\" t-attf-title=\\"Scheduled on #{record.next_departure.value}\\">\\n                                        <span class=\\"oi me-2 small my-auto\\" data-icon=\\"hourglass_empty\\" aria-label=\\"Scheduled date\\"/>\\n                                        <span>Next Batch</span>\\n                                    </span>\\n                                </div>\\n                                <field name=\\"user_id\\" widget=\\"many2one_avatar_user\\" class