1462	999	\N	1	1	project.sharing.project.task.view.form	project.task	\N	form	project/views/project_sharing_project_task_views.xml	primary	\N	{"en_US": "<form string=\\"Project Sharing: Task\\" class=\\"o_form_project_tasks\\">\\n                <header>\\n                    <button name=\\"action_project_sharing_toggle_assign\\" type=\\"object\\" string=\\"Assign to Me\\" class=\\"btn-primary\\" invisible=\\"context.get('portal_is_readonly') or uid in user_ids\\"/>\\n                    <button name=\\"action_project_sharing_toggle_assign\\" type=\\"object\\" string=\\"Remove Me\\" class=\\"btn-secondary\\" invisible=\\"context.get('portal_is_readonly') or uid not in user_ids\\"/>\\n                    <field name=\\"stage_id\\" readonly=\\"not context.get('portal_can_advanced_edit', False)\\" widget=\\"statusbar_duration\\" options=\\"{'clickable': '1', 'fold_field': 'fold'}\\" invisible=\\"not project_id and not stage_id\\"/>\\n                </header>\\n                <div groups=\\"base.group_user\\" role=\\"status\\" class=\\"alert alert-info alert-dismissible rounded-0 fade show d-print-none css_editable_mode_hidden\\">\\n                    <div class=\\"text-center\\">This is a preview of how the project will look when it's shared with customers and they have editing access.\\n                        <a name=\\"action_redirect_to_project_task_form\\" type=\\"object\\"><i class=\\"oi me-1\\" data-icon=\\"east\\"/>Back to edit mode</a>\\n                    </div>\\n                </div>\\n                <sheet string=\\"Task\\">\\n                    <div class=\\"oe_button_box\\" name=\\"button_box\\">\\n                        <field name=\\"display_parent_task_button\\" invisible=\\"1\\"/>\\n                        <field name=\\"recurrence_id\\" invisible=\\"1\\"/>\\n                        <button name=\\"action_project_sharing_view_parent_task\\" type=\\"object\\" class=\\"oe_stat_button\\" icon=\\"check\\" invisible=\\"not display_parent_task_button\\">\\n                            <div class=\\"o_stat_info\\">\\n                                <span class=\\"o_stat_text\\">Parent Task</span>\\n                            </div>\\n                        </button>\\n                        <button name=\\"action_project_sharing_recurring_tasks\\" type=\\"object\\" invisible=\\"not active or not recurrence_id or not allow_recurring_tasks\\" class=\\"oe_stat_button\\" icon=\\"redo\\" context=\\"{'default_user_ids': [(6, 0, [uid])]}\\">\\n                            <field name=\\"recurring_count\\" widget=\\"statinfo\\" string=\\"Recurring Tasks\\"/>\\n                        </button>\\n                        <button name=\\"action_project_sharing_open_subtasks\\" type=\\"object\\" class=\\"oe_stat_button\\" icon=\\"check\\" invisible=\\"not id or subtask_count == 0\\" context=\\"{                                 'default_user_ids': [(6, 0, [uid])],                                 'default_project_id': project_id,                             }\\">\\n                            <field name=\\"subtask_count\\" widget=\\"statinfo\\" string=\\"Sub-tasks\\"/>\\n                            <field name=\\"display_in_project\\" invisible=\\"True\\"/>\\n                        </button>\\n                        <button name=\\"action_project_sharing_open_blocking\\" type=\\"object\\" invisible=\\"not dependent_tasks_count or not allow_task_dependencies\\" class=\\"oe_stat_button\\" icon=\\"check\\">\\n                            <div class=\\"o_field_widget o_stat_info\\">\\n                                <span class=\\"o_stat_text\\">Blocked Tasks</span>\\n                                <span class=\\"o_stat_value \\">\\n                                    <field name=\\"dependent_tasks_count\\" widget=\\"statinfo\\" nolabel=\\"1\\"/>\\n                                </span>\\n                            </div>\\n                        </button>\\n                    </div>\\n                    <widget name=\\