_field\\" invisible=\\"survey_type == 'live_session' or access_mode == 'public' and not users_login_required\\">\\n                                        <field name=\\"is_attempts_limited\\" nolabel=\\"1\\"/>\\n                                        <div invisible=\\"not is_attempts_limited\\">\\n                                            a <field name=\\"attempts_limit\\" nolabel=\\"1\\" class=\\"oe_inline\\"/> intentos\\n                                        </div>\\n                                    </div>\\n                                </group>\\n                                <group string=\\"Tiempo y puntuación\\" name=\\"scoring\\" invisible=\\"survey_type == 'survey'\\">\\n                                    <!-- Time -->\\n                                    <label for=\\"is_time_limited\\" string=\\"Límite de tiempo de la encuesta\\" invisible=\\"survey_type == 'live_session'\\"/>\\n                                    <div class=\\"o_checkbox_optional_field\\" name=\\"is_time_limited\\" invisible=\\"survey_type == 'live_session'\\">\\n                                        <field name=\\"is_time_limited\\" nolabel=\\"1\\"/>\\n                                        <div invisible=\\"not is_time_limited\\">\\n                                            <field name=\\"time_limit\\" widget=\\"float_time\\" options=\\"{'unit': 'minutes'}\\" nolabel=\\"1\\" class=\\"oe_inline\\"/>\\n                                        </div>\\n                                    </div>\\n                                    <!-- Scoring -->\\n                                    <field name=\\"scoring_type\\" widget=\\"radio\\" force_save=\\"1\\"/>\\n                                    <field name=\\"scoring_success_min\\" invisible=\\"scoring_type == 'no_scoring'\\"/>\\n                                    <label for=\\"certification\\" invisible=\\"survey_type == 'live_session' or scoring_type == 'no_scoring'\\"/>\\n                                    <div class=\\"o_checkbox_optional_field\\" name=\\"certification\\" invisible=\\"survey_type == 'live_session'\\">\\n                                        <field name=\\"certification\\" invisible=\\"scoring_type == 'no_scoring'\\"/>\\n                                        <div invisible=\\"not certification\\" class=\\"w-100\\">\\n                                            <field name=\\"certification_report_layout\\" placeholder=\\"Elija un estilo...\\" class=\\"w-50\\"/>\\n                                            <button name=\\"action_survey_preview_certification_template\\" string=\\"Vista previa\\" type=\\"object\\" icon=\\"open_in_new\\" target=\\"_blank\\" class=\\"btn-link pt-0\\"/>\\n                                        </div>\\n                                    </div>\\n                                    <field name=\\"certification_mail_template_id\\" placeholder=\\"Elija una plantilla...\\" invisible=\\"not certification\\"/>\\n                                    <label for=\\"certification_give_badge\\" invisible=\\"not certification or not users_login_required\\"/>\\n                                    <div class=\\"float-start o_checkbox_optional_field\\" invisible=\\"not certification or not users_login_required\\">\\n                                        <field name=\\"certification_give_badge\\"/>\\n                                        <div invisible=\\"not certification_give_badge\\">\\n                                            <field name=\\"certification_badge_id\\" placeholder=\\"Elija una insignia...\\" invisible=\\"not certification_give_badge or certification_badge_id\\" required=\\"certification_give_badge\\" domain=\\"[('survey_id', '=', id), ('survey_id', '!=', False)]\\" context=\\"{'default_name': title,                                                         'default_description': 'Congratulations, you have succeeded this certification',                                                         'default_rule_auth': 'nobody', 