me=\\"title\\" class=\\"fw-bold\\"/>\\n                                    <i t-if=\\"record.certification.raw_value\\" class=\\"o_survey_certification_icon oi oi-filled\\" data-icon=\\"trophy\\" role=\\"img\\" title=\\"Certification\\"/>\\n                                </div>\\n                                <span t-if=\\"!selection_mode\\" class=\\"d-flex align-items-center gap-1\\">\\n                                    <field name=\\"user_id\\" widget=\\"many2one_avatar_user\\" options=\\"{'display_avatar_name': True}\\"/>\\n                                    <span>-</span>\\n                                    <t t-out=\\"luxon.DateTime.fromISO(record.create_date.raw_value).toFormat('MMM yyyy')\\"/>\\n                                </span>\\n                            </div>\\n                        </div>\\n                        <div class=\\"g-col-12 g-col-lg-6 d-flex column-gap-4 column-gap-lg-5 row-gap-2 flex-wrap order-1 order-md-2 order-lg-1\\">\\n                            <div class=\\"d-flex flex-column\\">\\n                                <field name=\\"question_count\\" class=\\"fw-bold fs-4\\"/>\\n                                <span class=\\"text-muted\\">Questions</span>\\n                            </div>\\n                            <t t-if=\\"!selection_mode\\">\\n                                <div t-if=\\"!isGrouped\\" class=\\"d-flex flex-column\\">\\n                                    <field name=\\"answer_duration_avg\\" widget=\\"float_time\\" class=\\"fw-bold fs-4\\"/>\\n                                    <span class=\\"text-muted\\">Average Duration</span>\\n                                </div>\\n                                <a t-if=\\"!isGrouped\\" type=\\"object\\" name=\\"action_survey_user_input\\" class=\\"d-flex flex-column\\">\\n                                    <field name=\\"answer_count\\" class=\\"fw-bold fs-4\\"/>\\n                                    <span>Registered</span>\\n                        