esta correcta\\" class=\\"oe_inline\\" invisible=\\"question_type != 'date'\\" required=\\"is_scored_question and question_type == 'date'\\"/>\\n                                    <field name=\\"answer_datetime\\" string=\\"Respuesta correcta\\" class=\\"oe_inline\\" invisible=\\"question_type != 'datetime'\\" required=\\"is_scored_question and question_type == 'datetime'\\"/>\\n                                </group>\\n\\n                                <group invisible=\\"question_type !='char_box'\\">\\n                                    <group invisible=\\"question_type != 'char_box'\\">\\n                                        <field name=\\"validation_email\\"/>\\n                                    </group>\\n                                    <group invisible=\\"not validation_email or question_type != 'char_box'\\">\\n                                        <field name=\\"save_as_email\\"/>\\n                                    </group>\\n                                    <group invisible=\\"question_type != 'char_box'\\">\\n                                        <field name=\\"save_as_nickname\\"/>\\n                                    </group>\\n                                </group>\\n\\n                                <group invisible=\\"scoring_type == 'no_scoring' or question_type not in ['numerical_box', 'date', 'datetime']\\">\\n                                    <label for=\\"is_scored_question\\"/>\\n                                    <div name=\\"survey_scored_question\\">\\n                                        <field name=\\"is_scored_question\\" nolabel=\\"1\\"/>\\n                                        <field name=\\"answer_score\\" class=\\"w-50 mx-2\\" invisible=\\"not is_scored_question\\" nolabel=\\"1\\"/>\\n                                        <span invisible=\\"not is_scored_question\\">Puntos</span>\\n                                    </div>\\n                                </group>\\n                            </group>\\n                            <field name=\\"suggested_answer_ids\\" context=\\"{'default_question_id': id}\\" invisible=\\"question_type not in ['simple_choice', 'multiple_choice', 'matrix']\\">\\n                                <list editable=\\"bottom\\">\\n                                    <field name=\\"sequence\\" widget=\\"handle\\"/>\\n                                    <field name=\\"value\\" string=\\"Opciones\\" required=\\"not value_image\\" placeholder=\\"Option Name\\"/>\\n                                    <field name=\\"is_correct\\" column_invisible=\\"parent.scoring_type == 'no_scoring' or parent.question_type == 'matrix'\\"/>\\n                                    <field name=\\"answer_score\\" column_invisible=\\"parent.scoring_type == 'no_scoring' or parent.question_type == 'matrix'\\"/>\\n                                    <field name=\\"value_image_filename\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"value_image\\" width=\\"200px\\" widget=\\"binary\\" filename=\\"value_image_filename\\" options=\\"{'accepted_file_extensions': 'image/*'}\\" column_invisible=\\"parent.question_type in ['matrix', 'scale']\\" required=\\"not value\\"/>\\n                                </list>\\n                            </field>\\n\\n                            <field name=\\"matrix_row_ids\\" context=\\"{'default_matrix_question_id': id}\\" invisible=\\"question_type != 'matrix'\\">\\n                                <list editable=\\"bottom\\">\\n                                    <field name=\\"sequence\\" widget=\\"handle\\"/>\\n                                    <field name=\\"value\\" string=\\"Fila4\\"/>\\n                                </list>\\n                            </field>\\n                        </page>\\n                        <page string=\\"Opciones\\" name=\\"options\\" invisible=\\"is_page\\">\\n                            <group>\\n                                <group string=\\"Respuestas\\" invisible=\\"question_type == 'scale'\\">\\n                                    <!-- Global validation setting -->\\n                                    <field name=\\"validation_required\\" invisible=\\"question_type not in ['char_box', 'numerical_box', 'date', 'datetime']\\"/>\\n                                    <div class=\\"o_wrap_label o_form_label\\" invisible=\\"not validation_required\\">Límites mínimos/máximos</div>\\n                                    <div class=\\"o_survey_question_validation_parameters\\" invisible=\\"not validation_required\\">\\n                                        <!-- Minima -->\\n                                        <field name=\\"validation_length_min\\" class=\\"o_survey_question_validation_inline\\" nolabel=\\"1\\" placeholder=\\"Mínimo\\" invisible=\\"question_type != 'char_box'\\" required=\\"validation_required and question_type == 'char_box'\\"/>\\n                                        <field name=\\"validation_min_float_value\\" class=\\"o_survey_question_validation_inline\\" nolabel=\\"1\\" placeholder=\\"Mínimo\\" invisible=\\"question_type != 'numerical_box'\\" required=\\"validation_required and question_type == 'numerical_box'\\"/>\\n                                        <field name=\\"validation_min_date\\" nolabel=\\"1\\" placeholder=\\"Mínimo\\" invisible=\\"question_type != 'date'\\" required=\\"validation_required and question_type == 'date' and not validation_max_date\\"/>\\n                                        <field name=\\"validation_min_datetime\\" nolabel=\\"1\\" placeholder=\\"Mínimo\\" invisible=\\"question_type != 'datetime'\\" required=\\"validation_required and question_type == 'datetime' and not validation_max_datetime\\"/>\\n\\n                                        <i class=\\"oi mx-2\\" data-icon=\\"east\\" aria-label=\\"Arrow icon\\" title=\\"Arrow\\"/>\\n                                        <!-- Maxima -->\\n                                        <field name=\\"validation_length_max\\" class=\\"o_survey_question_validation_inline\\" nolabel=\\"1\\" placeholder=\\"Máximo\\" invisible=\\"question_type != 'char_box'\\" required=\\"validation_required and question_type == 'char_box'\\"/>\\n                                        <field name=\\"validation_max_float_value\\" class=\\"o_survey_question_validation_inline\\" nolabel=\\"1\\" placeholder=\\"Máximo\\" invisible=\\"question_type != 'numerical_box'\\" required=\\"validation_required and question_type == 'numerical_box'\\"/>\\n                                        <field name=\\"validation_max_date\\" nolabel=\\"1\\" placeholder=\\"Máximo\\" invisible=\\"question_type != 'date'\\" required=\\"validation_required and question_type == 'date' and not validation_min_date\\"/>\\n                                        <field name=\\"validation_max_datetime\\" nolabel=\\"1\\" placeholder=\\"Máximo\\" invisible=\\"question_type != 'datetime'\\" required=\\"validation_required and question_type == 'datetime' and not validation_min_datetime\\"/>\\n                                    </div>\\n                                    <field name=\\"validation_error_msg\\" invisible=\\"not validation_required\\" placeholder=\\"Mostrado cuando la respuesta proporcionada no es válida.\\"/>\\n\\n                                    <field name=\\"matrix_subtype\\" invisible=\\"question_type != 'matrix'\\" required=\\"question_type == 'matrix'\\"/>\\n                                    <field name=\\"question_placeholder\\" invisible=\\"question_type not in ['text_box', 'char_box', 'date', 'datetime', 'numerical_box']\\" placeholder=\\"Ayude a los participantes a saber qué escribir\\"/>\\n                                    <field name=\\"comments_allowed\\" invisible=\\"question_type not in ['simple_choice', 'multiple_choice', 'matrix']\\"/>\\n                                    <field name=\\"comments_message\\" invisible=\\"question_type not in ['simple_choice', 'multiple_choice', 'matrix'] or not comments_allowed\\" placeholder=\\"Si otra, por favor, precisar:\\"/>\\n                                    <field name=\\"comment_count_as_answer\\" invisible=\\"question_type not in ['simple_choice', 'multiple_choice', 'matrix'] or not comments_allowed\\"/>\\n                                </group>\\n                                <group string=\\"Visualización condicional\\">\\n                                    <p class=\\"text-muted\\" colspan=\\"2\\" invisible=\\"questions_selection == 'all'\\">\\n                                        La visualización condicional no está disponible cuando las preguntas se eligen al azar.\\n                                    </p>\\n                                    <field name=\\"allowed_triggering_question_ids\\" invisible=\\"1\\"/>\\n                                    <field name=\\"triggering_answer_ids\\" widget=\\"many2many_tags\\" options=\\"{'no_open': True, 'no_create': True}\\" domain=\\"[('question_id', 'in', allowed_triggering_question_ids)]\\" invisible=\\"questions_selection == 'random'\\" placeholder=\\"Se requieren respuestas previas opcionales\\"/>\\n                                </group>\\n                            </group>\\n                            <group>\\n                                <group string=\\"Restricciones\\">\\n                                    <field name=\\"constr_mandatory\\" string=\\"Respuesta obligatoria\\"/>\\n                                    <field name=\\"constr_error_msg\\" invisible=\\"not constr_mandatory\\" placeholder=\\"Esta pregunta requiere una respuesta.\\"/>\\n                                </group>\\n                                <group string=\\"Sesiones en vivo\\" invisible=\\"not session_available\\">\\n                                    <field name=\\"is_time_customized\\" invisible=\\"True\\"/>\\n                                    <field name=\\"session_available\\" invisible=\\"True\\"/>\\n                                    <label for=\\"is_time_limited\\" string=\\"Límite de tiempo (segundos)\\"/>\\n                                    <div>\\n                                        <field name=\\"is_time_limited\\" nolabel=\\"1\\" class=\\"oe_inline\\" widget=\\"boolean_update_flag\\" options=\\"{'flagFieldName': 'is_time_customized'}\\" context=\\"{'referenceValue': survey_session_speed_rating}\\"/>\\n                                        <field name=\\"time_limit\\" nolabel=\\"1\\" class=\\"oe_inline\\" widget=\\"integer_update_flag\\" options=\\"{'flagFieldName': 'is_time_customized'}\\" context=\\"{'referenceValue': survey_session_speed_rating_time_limit}\\" invisible=\\"not is_time_limited\\"/>\\n                                    </div>\\n                                </group>\\n                            </group>\\n                        </page>\\n                    </notebook>\\n                </sheet>\\n            </form>"}	<?xml version="1.0"?>\n<form string="Survey Question" create="false" class="o_survey_question_view_form">\n                <field name="is_placed_before_trigger" invisible="1"/>\n                <div class="alert alert-warning text-center" role="alert" invisible="not is_placed_before_trigger">\n                    ⚠️ This question is positioned before some or all of its triggers and could be skipped.\n                </div>\n                <field name="is_page" invisible="1"/>\n                <field name="page_id" invisible="1" required="False"/>\n                <field name="sequence" invisible="1"/>\n                <field name="scoring_type" invisible="1"/>\n                <sheet>\n                    <field name="survey_id" invisible="not context.get('show_survey_field')" readonly="1"/>\n                    <div class="float-end d-flex flex-column text-center" invisible="not is_page">\n                        <label for="background_image"/>\n                        <field name="background_image" widget="image" class="oe_avatar"/>\n                    </div>\n                    <div invisible="is_page" class="mb-0">\n                        <field name="question_type" nolabel="1" widget="badges_selection" required="not is_page" options="{'icon_mapping': {                                 'simple_choice': 'radio_button_checked',                                 'multiple_choice': 'check_box',                                 'text_box': 'menu',                                 'char_box': 'remove',                                 'numerical_box': 'tag',                                 'scale': 'sentiment_satisfied',                                 'date': 'calendar_today',                                 'datetime': 'calendar_today',                                 'time': 'schedule',                                 'matrix': 'grid_view',                             }}"/>\n                    </div>\n                    <div class="oe_title">\n                        <label for="title" string="Section" invisible="not is_page"/>\n                        <label for="title" string="Question" invisible="is_page"/>\n                        <h1>\n                            <field name="title" placeholder="Ask something..." nolabel="1" options="{'line_breaks': False}" widget="text"/>\n                        </h1>\n                    </div>\n\n                    <div class="w-100 mw-100">\n                        <field name="questions_selection" invisible="1"/>\n                        <field name="description" options="{'embedded_components': false}" placeholder="Optional: provide extra guidelines, instructions, pictures... here, to help attendees answer" nolabel="1" class="o_survey_description_editor"/>\n                    </div>\n                    <group class="o_label_nowrap" invisible="not is_page or questions_selection == 'all'">\n                        <field name="random_questions_count"/>\n                    </group>\n                    <notebook>\n                        <page string="Answers" name="answers" invisible="is_page or question_type == 'text_box' or scoring_type == 'no_scoring' and question_type in ['numerical_box', 'date', 'datetime']">\n                            <group>\n                                <group invisible="question_type != 'scale'">\n                                    <label for="scale_min" string="Scale Range"/>\n                                    <div class="o_row">\n                                        <field name="scale_min" nolabel="1" placeholder="Scale Minimum Value (0 to 10)"/>\n                                        <span class="mx-2 o_form_label">to</span>\n                                        <field name="scale_max" nolabel="1" placeholder="Scale Maximim Value (0 to 10)"/>\n                                    </div>\n                                    \n                                    <label for="scale_min_label" string="Labels"/>\n                                    <field name="scale_min_label_placeholder" invisible="1"/>\n                                    <field name="scale_max_label_placeholder" invisible="1"/>\n                                    <div class="o_row">\n                                        <field name="scale_min_label" nolabel="1" options="{'placeholder_field': 'scale_min_label_placeholder'}"/>\n                                        <span class="mx-2 o_form_label">to</span>\n                                        <field name="scale_max_label" nolabel="1" options="{'placeholder_field': 'scale_max_label_placeholder'}"/>\n                                    </div>\n                                </group>\n                                <group invisible="question_type not in ['numerical_box', 'date', 'datetime']">\n                                    <field name="answer_numerical_box" string="Correct Answer" class="oe_inline" invisible="question_type != 'numerical_box'" required="is_scored_question and question_type == 'numerical_box'"/>\n                                    <field name="answer_date" string="Correct Answer" class="oe_inline" invisible="question_type != 'date'" required="is_scored_question and question_type == 'date'"/>\n                                    <field name="answer_datetime" string="Correct Answer" class="oe_inline" invisible="question_type != 'datetime'" required="is_scored_question and question_type == 'datetime'"/>\n                                </group>\n\n                                <group invisible="question_type !='char_box'">\n                                    <group invisible="question_type != 'char_box'">\n                                        <field name="validation_email"/>\n                                    </group>\n                                    <group invisible="not validation_email or question_type != 'char_box'">\n                                        <field name="save_as_email"/>\n                                    </group>\n                                    <group invisible="question_type != 'char_box'">\n                                        <field name="save_as_nickname"/>\n                                    </group>\n                                </group>\n\n                                <group invisible="scoring_type == 'no_scoring' or question_type not in ['numerical_box', 'date', 'datetime']">\n                                    <label for="is_scored_question"/>\n                                    <div name="survey_scored_question">\n                                        <field name="is_scored_question" nolabel="1"/>\n                                        <field name="answer_score" class="w-50 mx-2" invisible="not is_scored_question" nolabel="1"/>\n                                        <span invisible="not is_scored_question">Points</span>\n                                    </div>\n                                </group>\n                            </group>\n                            <field name="suggested_answer_ids" context="{'default_question_id': id}" invisible="question_type not in ['simple_choice', 'multiple_choice', 'matrix']">\n                                <list editable="bottom">\n                                    <field name="sequence" widget="handle"/>\n                                    <field name="value" string="Choices" required="not value_image" placeholder="Option Name"/>\n                                    <field name="is_correct" column_invisible="parent.scoring_type == 'no_scoring' or parent.question_type == 'matrix'"/>\n                                    <field name="answer_score" column_invisible="parent.scoring_type == 'no_scoring' or parent.question_type == 'matrix'"/>\n                                    <field name="value_image_filename" column_invisible="True"/>\n                                    <field name="value_image" width="200px" widget="binary" filename="value_image_filename" options="{'accepted_file_extensions': 'image/*'}" column_invisible="parent.question_type in ['matrix', 'scale']" required="not value"/>\n                                </list>\n                            </field>\n\n                            <field name="matrix_row_ids" context="{'default_matrix_question_id': id}" invisible="question_type != 'matrix'">\n                                <list editable="bottom">\n                                    <field name="sequence" widget="handle"/>\n                                    <field name="value" string="Rows"/>\n                                </list>\n                            </field>\n                        </page>\n                        <page string="Options" name="options" invisible="is_page">\n                            <group>\n                                <group string="Answers" invisible="question_type == 'scale'">\n                                    <!-- Global validation setting -->\n                                    <field name="validation_required" invisible="question_type not in ['char_box', 'numerical_box', 'date', 'datetime']"/>\n                                    <div class="o_wrap_label o_form_label" invisible="not validation_required">Min/Max Limits</div>\n                                    <div class="o_survey_question_validation_parameters" invisible="not validation_required">\n                                        <!-- Minima -->\n                                        <field name="validation_length_min" class="o_survey_question_validation_inline" nolabel="1" placeholder="Minimum" invisible="question_type != 'char_box'" required="validation_required and question_type == 'char_box'"/>\n                                        <field name="validation_min_float_value" class="o_survey_question_validation_inline" nolabel="1" placeholder="Minimum" invisible="question_type != 'numerical_box'" required="validation_required and question_type == 'numerical_box'"/>\n                                        <field name="validation_min_date" nolabel="1" placeholder="Minimum" invisible="question_type != 'date'" required="validation_required and question_type == 'date' and not validation_max_date"/>\n                                        <field name="validation_min_datetime" nolabel="1" placeholder="Minimum" invisible="question_type != 'datetime'" required="validation_required and question_type == 'datetime' and not validation_max_datetime"/>\n\n                                        <i class="oi mx-2" data-icon="east" aria-label="Arrow icon" title="Arrow"/>\n                                        <!-- Maxima -->\n                                        <field name="validation_length_max" class="o_survey_question_validation_inline" nolabel="1" placeholder="Maximum" invisible="question_type != 'char_box'" required="validation_required and question_type == 'char_box'"/>\n                                        <field name="validation_max_float_value" class="o_survey_question_validation_inline" nolabel="1" placeholder="Maximum" invisible="question_type != 'numerical_box'" required="validation_required and question_type == 'numerical_box'"/>\n                                        <field name="validation_max_date" nolabel="1" placeholder="Maximum" invisible="question_type != 'date'" required="validation_required and question_type == 'date' and not validation_min_date"/>\n                                        <field name="validation_max_datetime" nolabel="1" placeholder="Maximum" invisible="question_type != 'datetime'" required="validation_required and question_type == 'datetime' and not validation_min_datetime"/>\n                                    </div>\n                                    <field name="validation_error_msg" invisible="not validation_required" placeholder="Displayed when the answer entered is not valid."/>\n\n                                    <field name="matrix_subtype" invisible="question_type != 'matrix'" required="question_type == 'matrix'"/>\n                                    <field name="question_placeholder" invisible="question_type not in ['text_box', 'char_box', 'date', 'datetime', 'numerical_box']" placeholder="Help Participants know what to write"/>\n                                    <field name="comments_allowed" invisible="question_type not in ['simple_choice', 'multiple_choice', 'matrix']"/>\n                                    <field name="comments_message" invisible="question_type not in ['simple_choice', 'multiple_choice', 'matrix'] or not comments_allowed" placeholder="If other, please specify:"/>\n                                    <field name="comment_count_as_answer" invisible="question_type not in ['simple_choice', 'multiple_choice', 'matrix'] or not comments_allowed"/>\n                                </group>\n                                <group string="Conditional display">\n                                    <p class="text-muted" colspan="2" invisible="questions_selection == 'all'">\n                                        Conditional display is not available when questions are randomly picked.\n                                    </p>\n                                    <field name="allowed_triggering_question_ids" invisible="1"/>\n                                    <field name="triggering_answer_ids" widget="many2many_tags" options="{'no_open': True, 'no_create': True}" domain="[('question_id', 'in', allowed_triggering_question_ids)]" invisible="questions_selection == 'random'" placeholder="Optional previous answers required"/>\n                                </group>\n                            </group>\n                            <group>\n                                <group string="Constraints">\n                                    <field name="constr_mandatory" string="Mandatory Answer"/>\n                                    <field name="constr_error_msg" invisible="not constr_mandatory" placeholder="This question requires an answer."/>\n                                </group>\n                                <group string="Live Sessions" invisible="not session_available">\n                                    <field name="is_time_customized" invisible="True"/>\n                                    <field name="session_available" invisible="True"/>\n                                    <label for="is_time_limited" string="Time Limit (seconds)"/>\n                                    <div>\n                                        <field name="is_time_limited" nolabel="1" class="oe_inline" widget="boolean_update_flag" options="{'flagFieldName': 'is_time_customized'}" context="{'referenceValue': survey_session_speed_rating}"/>\n                                        <field name="time_limit" nolabel="1" class="oe_inline" widget="integer_update_flag" options="{'flagFieldName': 'is_time_customized'}" context="{'referenceValue': survey_session_speed_rating_time_limit}" invisible="not is_time_limited"/>\n                                    </div>\n                                </group>\n                            </group>\n                     