rvey_fill_form"/>\n                            </div>\n                            <t t-call="survey.survey_toolbar"/>\n                            <t t-call="survey.survey_brand_message"/>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </t>\n    </t>\n\n    	\N	f	t	2026-10-26 23:49:10.293583	2026-10-26 23:49:10.293583	f
1523	16	\N	1	1	Survey: toolbar with timer, progress bar, brand message and navigation	\N	survey.survey_toolbar	qweb	survey/views/survey_templates.xml	primary	\N	{"en_US": "<t name=\\"Survey: toolbar with timer, progress bar, brand message and navigation\\" t-name=\\"survey.survey_toolbar\\">\\n        <div class=\\"o_survey_toolbar position-fixed bottom-0 end-0 d-flex d-print-none align-items-center m-3 me-md-4 border rounded py-2 bg-body shadow-sm\\">\\n            <div class=\\"o_survey_timer fs-5\\">\\n                <span class=\\"o_survey_timer_container timer\\"/>\\n            </div>\\n            <div class=\\"o_survey_progress_wrapper\\">\\n                <t t-if=\\"survey and survey.questions_layout != 'one_page' and answer and answer.state == 'in_progress' and (not question or not question.is_page) and not survey_form_readonly\\">\\n                    <t t-if=\\"survey.questions_layout == 'page_per_section'\\">\\n                        <t t-set=\\"page_ids\\" t-value=\\"survey.page_ids.ids\\"/>\\n                        <t t-set=\\"page_number\\" t-value=\\"page_ids.index(page.id) + (1 if survey.progression_mode == 'number' else 0)\\"/>\\n                    </t>\\n                    <t t-else=\\"\\">\\n                        <t t-if=\\"not answer.is_session_answer and survey.questions_selection == 'random'\\" t-set=\\"page_ids\\" t-value=\\"answer.predefined_question_ids.ids\\"/>\\n                        <t t-else=\\"\\" t-set=\\"page_ids\\" t-value=\\"survey.question_ids.ids\\"/>\\n                        <t t-set=\\"page_number\\" t-value=\\"page_ids.index(question.id)\\"/>\\n                    </t>\\n                    <t t-call=\\"survey.survey_progression\\"/>\\n                </t>\\n            </div>\\n            <div t-if=\\"not no_survey_navigation\\" class=\\"o_survey_navigation_wrapper\\">\\n                <t t-call=\\"survey.survey_navigation\\"/>\\n            </div>\\n        </div>\\n    </t>"}	<?xml version="1.0"?>\n<t name="Survey: toolbar with timer, progress bar, brand message and navigation" t-name="survey.survey_toolbar">\n        <div class="o_survey_toolbar position-fixed bottom-0 end-0 d-flex d-print-none align-items-center m-3 me-md-4 border rounded py-2 bg-body shadow-sm">\n            <div class="o_survey_timer fs-5">\n                <span class="o_survey_timer_container timer"/>\n            </div>\n            <div class="o_survey_progress_wrapper">\n                <t t-if="survey and survey.questions_layout != 'one_page' and answer and answer.state == 'in_progress' and (not question or not question.is_page) and not survey_form_readonly">\n                    <t t-if="survey.questions_layout == 'page_per_section'">\n                        <t t-set="page_ids" t-value="survey.page_ids.ids"/>\n                        <t t-set="page_number" t-value="page_ids.index(page.id) + (1 if survey.progression_mode == 'number' else 0)"/>\n                    </t>\n                    <t t-else="">\n                        <t t-if="not answer.is_session_answer and survey.questions_selection == 'random'" t-set="page_ids" t-value="answer.predefined_question_ids.ids"/>\n                        <t t-else="" t-set="page_ids" t-value="survey.question_ids.ids"/>\n                        <t t-set="page_number" t-value="page_ids.index(question.id)"/>\n                    </t>\n                    <t t-call="survey.survey_progression"/>\n                </t>\n            </div>\n            <div t-if="not no_survey_navigation" class="o_survey_navigation_wrapper">\n                <t t-call="survey.survey_navigation"/>\n            </div>\n        </div>\n    </t>\n\n    	\N	f	t	2026-10-26 23:49:10.293583	2026-10-26 23:49:10.293583	f
1528	16	\N	1	1	Survey: question container	\N	survey.question_container	qweb	survey/views/survey_templates.xml	primary	\N	{"en_US": "<t name=\\"Survey: question container\\" t-name=\\"survey.question_container\\">\\n        <t t-set=\\"display_question\\" t-value=\\"survey.questions_layout == 'page_per_question'                     or survey.questions_selection == 'random'                     or (survey.questions_layout == 'one_page' and not question.triggering_answer_ids)                     or (survey.questions_layout == 'page_per_section' and (not question.triggering_answer_ids                         or any(triggering_answer in selected_answers for triggering_answer in triggering_answers_by_question[question.id])))\\"/>\\n\\n        <t t-set=\\"answer_lines\\" t-value=\\"answer.user_input_line_ids.filtered(lambda line: line.question_id == question)\\"/>\\n        <t t-set=\\"answers_contain_image\\" t-value=\\"any(a.value_image for a in question.suggested_answer_ids)\\"/>\\n        <t t-set=\\"use_half_columns\\" t-value=\\"survey.questions_layout == 'page_per_question' and answers_contain_image\\"/>\\n        <t t-set=\\"use_half_col_lg\\" t-value=\\"'col-lg-6' if (use_half_columns and not survey_form_readonly) or (answer.is_session_answer and answers_contain_image) else ''\\"/>\\n        <!--Use Key selection if number of choices is < 26 to keep Z for other choice if any-->\\n        <t t-set=\\"letters\\" t-value=\\"'ABCDEFGHIJKLMNOPQRSTUVWXYZ'\\"/>\\n        <t t-set=\\"useKeySelection\\" t-value=\\"len(question.suggested_answer_ids) &lt; len(letters) and survey.questions_layout == 'page_per_question'\\"/>\\n        <t t-set=\\"default_constr_error_msg\\">This question requires an answer.</t>\\n        <t t-set=\\"default_validation_error_msg\\">The answer you entered is not valid.</t>\\n        <t t-set=\\"default_comments_message\\">If other, please specify:</t>\\n        <t t-set=\\"is_post_submit_question\\" t-value=\\"post_submit_questions and question in post_submit_questions\\"/>\\n        <div t-attf-class=\\"o_survey_question #{'d-none' if not display_question else ''}\\" t-att-id=\\"question.id\\" t-att-data-required=\\"bool(question.constr_mandatory and (not survey.users_can_go_back or survey.questions_layout == 'one_page')) or None\\" t-att-data-constr-error-msg=\\"question.constr_error_msg or default_constr_error_msg if question.constr_mandatory else None\\" t-att-data-validation-error-msg=\\"question.validation_error_msg or default_validation_error_msg if question.validation_required else None\\">\\n            <h2 t-attf-class=\\"#{'h5' if survey.questions_layout != 'page_per_question' else 'h4'}\\" t-if=\\"not hide_question_title\\">\\n                <span t-field=\\"question.title\\" class=\\"text-break\\"/>\\n                <span t-if=\\"question.constr_mandatory\\" class=\\"text-danger\\">*</span>\\n            </h2>\\n            <div t-if=\\"not is_html_empty(question.description)\\" t-field=\\"question.description\\" class=\\"oe_no_empty o_survey_description text-break\\"/>\\n            <t t-if=\\"question.question_type == 'text_box'\\" t-call=\\"survey.question_text_box\\"/>\\n            <t t-if=\\"question.question_type == 'char_box'\\" t-call=\\"survey.question_char_box\\"/>\\n            <t t-if=\\"question.question_type == 'numerical_box'\\" t-call=\\"survey.question_numerical_box\\"/>\\n            <t t-if=\\"question.question_type == 'date'\\" t-call=\\"survey.question_date\\"/>\\n            <t t-if=\\"question.question_type == 'datetime'\\" t-call=\\"survey.question_datetime\\"/>\\n            <t t-if=\\"question.question_type == 'simple_choice'\\" t-call=\\"survey.question_simple_choice\\"/>\\n            <t t-if=\\"question.question_type == 'scale'\\" t-call=\\"survey.question_scale\\"/>\\n            <t t-if=\\"question.question_type == 'multiple_choice'\\" t-call=\\"survey.question_multiple_choice\\"/>\\n            <t t-if=\\"question.question_type == 'matrix'\\" t-call=\\"survey.question_matrix\\"/>\\n            <!-- Display the error message if the question is considered post submit (needs to be reviewed to get an answer) and\\n            it's the post-submit flow or it's the pre-submit flow and the question was effectively skipped. -->\\n            <t t-set=\\"display_error_msg\\" t-value=\\"is_post_submit_question and                 (answer.survey_first_submitted or (answer_lines and all(answer_lines.mapped('skipped'))))\\"/>\\n            <div t-attf-class=\\"o_survey_question_error alert alert-danger d-flex align-items-center justify-content-between border-0 overflow-hidden                 #{'slide_in mt-2' if display_error_msg else 'm-0'}                 #{'d-none' if answer.is_session_answer else ''}\\" role=\\"alert\\">\\n                <span t-if=\\"display_error_msg\\" t-out=\\"question.constr_error_msg or default_constr_error_msg\\"/>\\n            </div>\\n        </div>\\n    </t>", "es_ES": "<t name=\\"Survey: question container\\" t-name=\\"survey.question_container\\">\\n        <t t-set=\\"display_question\\" t-value=\\"survey.questions_layout == 'page_per_question'                     or survey.questions_selection == 'random'                     or (survey.questions_layout == 'one_page' and not question.triggering_answer_ids)                     or (survey.questions_layout == 'page_per_section' and (not question.triggering_answer_ids                         or any(triggering_answer in selected_answers for triggering_answer in triggering_answers_by_question[question.id])))\\"/>\\n\\n        <t t-set=\\"answer_lines\\" t-value=\\"answer.user_input_line_ids.filtered(lambda line: line.question_id == question)\\"/>\\n        <t t-set=\\"answers_contain_image\\" t-value=\\"any(a.value_image for a in question.suggested_answer_ids)\\"/>\\n        <t t-set=\\"use_half_columns\\" t-value=\\"survey.questions_layout == 'page_per_question' and answers_contain_image\\"/>\\n        <t t-set=\\"use_half_col_lg\\" t-value=\\"'col-lg-6' if (use_half_columns and not survey_form_readonly) or (answer.is_session_answer and answers_contain_image) else ''\\"/>\\n        <!--Use Key selection if number of choices is < 26 to keep Z for other choice if any-->\\n        <t t-set=\\"letters\\" t-value=\\"'ABCDEFGHIJKLMNOPQRSTUVWXYZ'\\"/>\\n        <t t-set=\\"useKeySelection\\" t-value=\\"len(question.suggested_answer_ids) &lt; len(letters) and survey.questions_layout == 'page_per_question'\\"/>\\n        <t t-set=\\"default_constr_error_msg\\">Esta pregunta requiere una respuesta.</t>\\n        <t t-set=\\"default_validation_error_msg\\">La respuesta introducida no es válida.</t>\\n        <t t-set=\\"default_comments_message\\">Si otra, por favor, precisar:</t>\\n        <t t-set=\\"is_post_submit_question\\" t-value=\\"post_submit_questions and question in post_submit_questions\\"/>\\n        <div t-attf-class=\\"o_survey_question #{'d-none' if not display_question else ''}\\" t-att-id=\\"question.id\\" t-att-data-required=\\"bool(question.constr_mandatory and (not survey.users_can_go_back or survey.questions_layout == 'one_page')) or None\\" t-att-data-constr-error-msg=\\"question.constr_error_msg or default_constr_error_msg if question.constr_mandatory else None\\" t-att-data-validation-error-msg=\\"question.validation_error_msg or default_validation_error_msg if question.validation_required else None\\">\\n            <h2 t-attf-class=\\"#{'h5' if survey.questions_layout != 'page_per_question' else 'h4'}\\" t-if=\\"not hide_question_title\\">\\n                <span t-field=\\"question.title\\" class=\\"text-break\\"/>\\n                <span t-if=\\"question.constr_mandatory\\" class=\\"text-danger\\">*</span>\\n            </h2>\\n            <div t-if=\\"not is_html_empty(question.description)\\" t-field=\\"question.description\\" class=\\"oe_no_empty o_survey_description text-break\\"/>\\n            <t t-if=\\"question.question_type == 'text_box'\\" t-call=\\"survey.question_text_box\\"/>\\n     