survey_form_choice_item form-check-input position-relative m-0\\" t-att-name=\\"question.id\\" t-att-checked=\\"'checked' if answer_line else None\\" t-att-data-selection-key=\\"letters[item_idx] if useKeySelection else ''\\"/>\\n                            <span class=\\"text-break\\" t-field=\\"label.value\\"/>\\n                            <t t-call=\\"survey.survey_selection_key\\" selection_key_class.f=\\"position-relative d-flex ms-auto\\"/>\\n                            <t t-if=\\"has_correct_answer and label.is_correct and (not answer_selected or answer_selected)\\">\\n                                <i class=\\"oi oi-fw ms-auto text-success\\" data-icon=\\"check\\" aria-label=\\"Correct\\" role=\\"img\\"/>\\n                            </t>\\n                            <t t-if=\\"answer_line and not label.is_correct and has_correct_answer\\">\\n                                <i class=\\"oi oi-fw ms-auto text-danger\\" data-icon=\\"close\\" aria-label=\\"Incorrect\\" role=\\"img\\"/>\\n                            </t>\\n                        </div>\\n                        <t t-call=\\"survey.question_suggested_value_image\\"/>\\n                    </label>\\n                </div>\\n            </t>\\n            <t t-if=\\"question.comments_allowed and question.comment_count_as_answer\\">\\n                <div t-attf-class=\\"#{use_half_col_lg}\\">\\n                    <label t-attf-class=\\"o_survey_choice_btn d-flex align-items-center py-2 px-3 h-100 w-100 rounded #{'o_survey_selected' if comment_line else ''}\\">\\n                        <t t-set=\\"item_idx\\" t-value=\\"item_idx + 1\\"/>\\n                        <input type=\\"checkbox\\" class=\\"o_survey_form_choice_item o_survey_js_form_other_comment position-relative me-2\\" value=\\"-1\\" t-att-name=\\"question.id\\" t-att-checked=\\"comment_line and 'checked' or None\\" t-att-data-selection-key=\\"letters[item_idx] if useKeySelection else ''\\"/>\\n                        <span class=\