bar mt-2 d-print-none\\">\\n                <t t-call=\\"survey.survey_results_filters\\"/>\\n            </div>\\n            <p class=\\"mt-4 text-muted text-center\\" t-else=\\"\\">\\n                Lo sentimos, nadie ha respondido esta encuesta todavía.\\n            </p>\\n            <div class=\\"row row-cols-2 row-cols-md-4 gx-2 gy-2 mt-3\\" t-if=\\"survey.scoring_type in ['scoring_with_answers', 'scoring_without_answers']\\">\\n                <div class=\\"col\\">\\n                    <div class=\\"border rounded p-3\\">\\n                        <div class=\\"d-flex align-items-center justify-content-between\\">\\n                            <h4 class=\\"mb-0\\" t-out=\\"survey.question_count\\"/>\\n                            <i class=\\"oi rounded-2 p-2 text-primary-emphasis bg-primary-subtle\\" data-icon=\\"help\\" aria-hidden=\\"true\\"/>\\n                        </div>\\n                        <span class=\\"text-muted\\">Preguntas</span>\\n                    </div>\\n                </div>\\n                <div class=\\"col\\">\\n                    <div class=\\"border rounded p-3\\">\\n                        <div class=\\"d-flex align-items-center justify-content-between\\">\\n                            <h4 class=\\"mb-0\\" t-out=\\"survey.answer_count\\"/>\\n                            <i class=\\"oi oi-filled rounded-2 p-2 text-primary-emphasis bg-primary-subtle\\" data-icon=\\"contact_mail\\" aria-hidden=\\"true\\"/>\\n                        </div>\\n                        <span class=\\"text-muted\\">Registered</span>\\n                    </div>\\n                </div>\\n                <div class=\\"col\\">\\n                    <div class=\\"border rounded p-3\\">\\n                        <div class=\\"d-flex align-items-center justify-content-between\\">\\n                            <h4 class=\\"mb-0\\" t-out=\\"survey.answer_done_count\\"/>\\n                            <i class=\\"oi oi-filled rounded-2 p-2 text-primary-emphasis bg-primary-subtle\\" data-icon=\\"check_circle\\" aria-hidden=\\"true\\"/>\\n                        </div>\\n                        <span class=\\"text-muted\\">Completed</span>\\n                    </div>\\n                </div>\\n                <div class=\\"col\\">\\n                    <div class=\\"border rounded p-3\\">\\n                        <div class=\\"d-flex align-items-center justify-content-between\\">\\n                            <h4 class=\\"mb-0\\"><t t-call=\\"survey.survey_remove_unnecessary_decimals\\" value_to_format=\\"survey_data['global_success_rate']\\"/>%</h4>\\n                            <i class=\\"oi oi-filled rounded-2 p-2 text-primary-emphasis bg-primary-subtle\\" data-icon=\\"trophy\\" aria-hidden=\\"true\\"/>\\n                        </div>\\n                        <span class=\\"text-muted\\">Success rate</span>\\n                    </div>\\n                </div>\\n                <div class=\\"col\\" t-if=\\"survey.answer_duration_avg\\">\\n                    <div class=\\"border rounded p-3\\">\\n                        <div class=\\"d-flex align-items-center justify-content-between\\">\\n                            <h4 class=\\"mb-0\\" t-out=\\"survey.answer_duration_avg\\" t-options=\\"{'widget': 'float_time'}\\"/>\\n                            <i class=\\"oi rounded-2 p-2 text-primary-emphasis bg-primary-subtle\\" data-icon=\\"schedule\\" aria-hidden=\\"true\\"/>\\n                        </div>\\n                        <span class=\\"text-muted\\">Avg. Duration</span>\\n                    </div>\\n                </div>\\n                <div class=\\"col\\" t-if=\\"survey.answer_score_avg\\">\\n                    <div class=\\"border rounded p-3\\">\\n                        <div class=\\"d-flex align-items-center justify-content-between\\">\\n                            <h4 class=\\"mb-0\\"><t t-out=\\"round(survey.answer_score_avg, 2)\\"/>%</h4>\\n                            <i class=\\"oi oi-filled rounded-2 p-2 text-primary-emphasis bg-primary-subtle\\" data-icon=\\"star\\" aria-hidden=\\"true\\"/>\\n                        </div>\\n                        <span class=\\"text-muted\\">Avg. Score</span>\\n                    </div>\\n                </div>\\n            </div>\\n        </div>\\n    </t>"}	<?xml version="1.0"?>\n<t name="Survey: result statistics header" t-name="survey.survey_page_statistics_header">\n        <div class="o_survey_statistics_header mt-4 rounded border p-4 bg-body">\n            <div class="d-flex align-items-center justify-content-between">\n                <h1 class="h3" t-field="survey.title"/>\n                <div class="btn-group">\n                    <button class="o_survey_results_print btn btn-light d-print-none" aria-label="Print" title="Print">\n                        <i class="oi" data-icon="print" aria-hidden="true"/>\n                    </button>\n                </div>\n            </div>\n            <div t-if="question_and_page_data" class="o_survey_results_topbar mt-2 d-print-none">\n                <t t-call="survey.survey_results_filters"/>\n            </div>\n            <p class="mt-4 text-muted text-center" t-else="">\n                Sorry, no one answered this survey yet.\n            </p>\n            <div class="row row-cols-2 row-cols-md-4 gx-2 gy-2 mt-3" t-if="survey.scoring_type in ['scoring_with_answers', 'scoring_without_answers']">\n                <div class="col">\n                    <div class="border rounded p-3">\n                        <div class="d-flex align-items-center justify-content-between">\n                            <h4 class="mb-0" t-out="survey.question_count"/>\n                            <i class="oi rounded-2 p-2 text-primary-emphasis bg-primary-subtle" data-icon="help" aria-hidden="true"/>\n                        </div>\n                        <span class="text-muted">Questions</span>\n                    </div>\n                </div>\n                <div class="col">\n                    <div class="border rounded p-3">\n                        <div class="d-flex align-items-center justify-content-between">\n                            <h4 class="mb-0" t-out="survey.answer_count"/>\n                            <i class="oi oi-filled rounded-2 p-2 text-primary-emphasis bg-primary-subtle" data-icon="contact_mail" aria-hidden="true"/>\n                        </div>\n                        <span class="text-muted">Registered</span>\n                    </div>\n                </div>\n                <div class="col">\n                    <div class="border rounded p-3">\n                        <div class="d-flex align-items-center justify-content-between">\n                            <h4 class="mb-0" t-out="survey.answer_done_count"/>\n                            <i class="oi oi-filled rounded-2 p-2 text-primary-emphasis bg-primary-subtle" data-icon="check_circle" aria-hidden="true"/>\n                        </div>\n                        <span class="text-muted">Completed</span>\n                    </div>\n                </div>\n                <div class="col">\n                    <div class="border rounded p-3">\n                        <div class="d-flex align-items-center justify-content-between">\n                            <h4 class="mb-0"><t t-call="survey.survey_remove_unnecessary_decimals" value_to_format="survey_data['global_success_rate']"/>%</h4>\n                            <i class="oi oi-filled rounded-2 p-2 text-primary-emphasis bg-primary-subtle" data-icon="trophy" aria-hidden="true"/>\n                        </div>\n                        <span class="text-muted">Success rate</span>\n                    </div>\n                </div>\n                <div class="col" t-if="survey.answer_duration_avg">\n                    <div class="border rounded p-3">\n                        <div class="d-flex align-items-center justify-content-between">\n                            <h4 class="mb-0" t-out="survey.answer_duration_avg" t-options="{'widget': 'float_time'}"/>\n                            <i class="oi rounded-2 p-2 text-primary-emphasis bg-primary-subtle" data-icon="schedule" aria-hidden="true"/>\n                        </div>\n                        <span class="text-muted">Avg. Duration</span>\n                    </div>\n                </div>\n                <div class="col" t-if="survey.answer_score_avg">\n                    <div class="border rounded p-3">\n                        <div class="d-flex align-items-center justify-content-between">\n                            <h4 class="mb-0"><t t-out="round(survey.answer_score_avg, 2)"/>%</h4>\n                            <i class="oi oi-filled rounded-2 p-2 text-primary-emphasis bg-primary-subtle" data-icon="star" aria-hidden="true"/>\n                        </div>\n                        <span class="text-muted">Avg. Score</span>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </t>\n\n    	\N	f	t	2026-10-26 23:49:10.293583	2026-10-26 23:49:10.293583	f
