1568	16	\N	1	1	Survey User Input Session Manage	\N	survey.user_input_session_manage_content	qweb	survey/views/survey_templates_user_input_session.xml	primary	\N	{"en_US": "<t name=\\"Survey User Input Session Manage\\" t-name=\\"survey.user_input_session_manage_content\\">\\n        <t t-set=\\"question\\" t-value=\\"survey.session_question_id\\"/>\\n        <t t-set=\\"is_scored_question\\" t-value=\\"any(answer.answer_score for answer in question.suggested_answer_ids)\\"/>\\n        <t t-set=\\"show_bar_chart\\" t-value=\\"question.question_type in ['simple_choice', 'multiple_choice', 'scale']\\"/>\\n        <t t-set=\\"show_text_answers\\" t-value=\\"question.question_type in ['char_box', 'date', 'datetime'] and not question.save_as_email and not question.save_as_nickname\\"/>\\n        <t t-set=\\"bar_reserved_with_rem\\" t-value=\\"25\\"/> <!-- See setup of SurveySessionLeaderboard -->\\n        <div class=\\"wrap min-vh-100 align-items-center justify-content-center d-flex flex-column o_survey_session_manage invisible\\" t-att-style=\\"'display: none;' if is_rpc_call else ''\\" t-att-data-is-rpc-call=\\"is_rpc_call\\" t-att-data-survey-id=\\"survey.id\\" t-att-data-survey-has-conditional-questions=\\"survey.has_conditional_questions\\" t-att-data-attendees-count=\\"survey.session_answer_count\\" t-att-data-survey-access-token=\\"survey.access_token\\" t-att-data-timer=\\"survey.session_question_start_time.isoformat()\\" t-att-data-time-limit-minutes=\\"question.time_limit / 60\\" t-att-data-is-scored-question=\\"is_scored_question\\" t-att-data-session-show-leaderboard=\\"survey.session_show_leaderboard\\" t-att-data-question-statistics=\\"question_statistics_graph\\" t-att-data-question-type=\\"question.question_type\\" t-att-data-has-correct-answers=\\"any(answer.is_correct for answer in question.suggested_answer_ids)\\" t-att-data-answers-validity=\\"answers_validity\\" t-att-data-is-first-question=\\"is_first_question\\" t-att-data-is-last-question=\\"is_last_question\\" t-att-data-all-participants-shown=\\"all_participants_shown\\" t-att-data-survey-last-triggering-answers=\\"survey_last_triggering_answers\\" t-att-data-current-screen=\\"'question' if is_scored_question else 'userInputs'\\" t-att-data-show-bar-chart=\\"show_bar_chart\\" t-att-data-show-text-answers=\\"show_text_answers\\" t-att-data-refresh-background=\\"any(page.background_image for page in survey.page_ids)\\" t-att-data-is-session-closed=\\"is_session_closed\\">\\n            <div t-if=\\"not is_session_closed\\" class=\\"d-flex justify-content-between align-items-center position-absolute top-0 end-0 w-100  rounded-top-start px-3 py-2 fs-5 bg-black-50 text-white\\">\\n                <span class=\\"o_survey_session_copy o_survey_session_copy_url cursor-pointer\\" t-out=\\"survey.session_link\\"/>\\n                <input class=\\"d-none\\" type=\\"text\\" t-att-value=\\"survey.session_link\\"/>\\n                <h1 t-if=\\"question.is_time_limited\\" class=\\"o_survey_timer_container\\">\\n                    <span class=\\"o_survey_timer d-inline-block\\"/>\\n                </h1>\\n                <div class=\\"d-flex align-items-center gap-2\\">\\n                    Answered:\\n                    <div class=\\"progress\\" title=\\"Attendees are answering the question...\\">\\n                        <div class=\\"progress-bar o_survey_session_progress_small\\" role=\\"progressbar\\" aria-valuenow=\\"0\\" aria-valuemin=\\"0\\" aria-valuemax=\\"100\\" aria-label=\\"Progress bar\\"/>\\n                    </div>\\n                    <span>\\n                        <span class=\\"o_survey_session_answer_count\\">0</span> /\\n                        <span t-out=\\"survey.session_answer_count\\"/>\\n                    </span>\\n                </div>\\n            </div>\\n            <a role=\\"button\\" href=\\"#\\" class=\\"oi o_survey_session_navigation o_survey_session_navigation_previous position-absolute start-0 ms-3 rounded p-3 bg-black-50 text-white z-3\\" data-icon=\\"chevron_backward\\" aria-label=\\"Previous Question\\"/>\\n            <a role=\\"button\\" href=\\"#\\" class=\\"o_survey_session_navigation o_survey_session_navigation_next position-absolute end-0 me-3 rounded p-3 bg-black-50 text-white z-3\\" aria-label=\\"Next Question\\">\\n                <span class=\\"o_survey_session_navigation_next_label me-2 d-none d-md-inline\\" aria-hidden=\\"true\\"/>\\n                <i class=\\"fw-bold oi\\" data-icon=\\"chevron_forward\\" aria-hidden=\\"true\\"/>\\n            </a>\\n            <div class=\\"o_survey_session_manage_container d-flex flex-column p-5 bg-black-50 rounded\\">\\n                <div class=\\"o_survey_session_description_done d-none o_container_small\\">\\n                    <h1 class=\\"fs-2\\">Thank you!</h1>\\n                    <div t-field=\\"survey.description_done\\"/>\\n                </div>\\n                <div class=\\"o_survey_session_results flex-column flex-grow-1\\">\\n                    <h1 class=\\"h2 mb-0\\" t-out=\\"question.title\\"/>\\n                    <div t-attf-class=\\"d-flex flex-column flex-grow-1 #{'justify-content-center' if not show_text_answers else ''} #{'align-items-center' if show_bar_chart else ''}\\">\\n                        <!-- Has to stay in 'style' attribute for Chartjs -->\\n                        <div t-if=\\"show_bar_chart\\" class=\\"p-2 o_survey_session_chart\\" style=\\"position: relative; width: 75vw; height: 70vh;\\">\\n                            <!-- canvas element for drawing bar chart -->\\n                            <canvas/>\\n                        </div>\\n                        <div t-elif=\\"show_text_answers\\" class=\\"o_survey_session_text_answers_container\\"/>\\n                        <div t-elif=\\"question.is_page and not is_html_empty(question.description)\\" class=\\"fs-5\\" t-field=\\"question.description\\"/>\\n                        <div t-else=\\"\\">\\n                            <fieldset disabled=\\"disabled\\" class=\\"mt-5\\" t-if=\\"question.question_type == 'matrix'\\">\\n                                <t t-call=\\"survey.question_container\\" hide_question_title=\\"True\\" answer=\\"env['survey.user_input']\\" survey_form_readonly=\\"True\\"/>\\n                            </fieldset>\\n                        </div>\\n                    </div>\\n                </div>\\n                <!-- BAR_RESERVED_WIDTH_REM + 15rem (where BAR_RESERVED_WIDTH_REM is the place for the score, nickname, ...) -->\\n                <div class=\\"o_survey_session_leaderboard w-100 flex-column flex-grow-1 min-vw-75 d-none\\" t-attf-style=\\"max-height: 70vh; min-width: max(50vw, #{bar_reserved_with_rem + 15}rem)\\">\\n                    <!--Set question to false to avoid background miss match when no question are displayed.-->\\n                    <t t-set=\\"question\\" t-value=\\"False\\"/>\\n                    <div class=\\"d-flex flex-wrap\\">\\n                        <h1 class=\\"o_survey_session_leaderboard_title h3 flex-grow-1 me-4 ms-1\\">\\n                            <span t-if=\\"is_last_question and all_participants_shown\\">Final Scoreboard</span>\\n                            <span t-elif=\\"is_last_question\\">Final Leaderboard</span>\\n                            <span t-elif=\\"all_participants_shown\\">Scoreboard</span>\\n                            <span t-else=\\"\\">Leaderboard</span>\\n                        </h1>\\n                        <div class=\\"ms-2\\">\\n                            <a href=\\"#\\" role=\\"button\\" class=\\"o_survey_session_close btn border-light text-light\\">End the Session</a>\\n                            <a href=\\"#\\" role=\\"button\\" class=\\"o_survey_session_close btn btn-light\\" t-att-data-show-results=\\"True\\">\\n                                <i class=\\"oi\\" data-icon=\\"bar_chart\\" aria-hidden=\\"true\\"/> Results\\n                            </a>\\n                        </div>\