\"\\">\\n                            <fieldset disabled=\\"disabled\\" class=\\"mt-5\\" t-if=\\"question.question_type == 'matrix'\\">\\n                                <t t-call=\\"survey.question_container\\" hide_question_title=\\"True\\" answer=\\"env['survey.user_input']\\" survey_form_readonly=\\"True\\"/>\\n                            </fieldset>\\n                        </div>\\n                    </div>\\n                </div>\\n                <!-- BAR_RESERVED_WIDTH_REM + 15rem (where BAR_RESERVED_WIDTH_REM is the place for the score, nickname, ...) -->\\n                <div class=\\"o_survey_session_leaderboard w-100 flex-column flex-grow-1 min-vw-75 d-none\\" t-attf-style=\\"max-height: 70vh; min-width: max(50vw, #{bar_reserved_with_rem + 15}rem)\\">\\n                    <!--Set question to false to avoid background miss match when no question are displayed.-->\\n                    <t t-set=\\"question\\" t-value=\\"False\\"/>\\n                    <div class=\\"d-flex flex-wrap\\">\\n                        <h1 class=\\"o_survey_session_leaderboard_title h3 flex-grow-1 me-4 ms-1\\">\\n                            <span t-if=\\"is_last_question and all_participants_shown\\">Final Scoreboard</span>\\n                            <span t-elif=\\"is_last_question\\">Tabla de clasificación final</span>\\n                            <span t-elif=\\"all_participants_shown\\">Scoreboard</span>\\n                            <span t-else=\\"\\">Tabla de clasificación</span>\\n                        </h1>\\n                        <div class=\\"ms-2\\">\\n                            <a href=\\"#\\" role=\\"button\\" class=\\"o_survey_session_close btn border-light text-light\\">End the Session</a>\\n                            <a href=\\"#\\" role=\\"button\\" class=\\"o_survey_session_close btn btn-light\\" t-att-data-show-results=\\"True\\">\\n                                <i class=\\"oi\\" data-icon=\\"bar_chart\\" aria-hidden=\\"true\\"/> Results\\n   