1560	16	\N	1	1	Question: choice result (simple_choice, multiple_choice, scale)	\N	survey.question_result_choice	qweb	survey/views/survey_templates_statistics.xml	primary	\N	{"en_US": "<t name=\\"Question: choice result (simple_choice, multiple_choice, scale)\\" t-name=\\"survey.question_result_choice\\">\\n        <div class=\\"tab-content\\">\\n            <div t-if=\\"question_answered\\" role=\\"tabpanel\\" class=\\"tab-pane active survey_graph\\" t-att-id=\\"'survey_graph_question_%d' % question.id\\" t-att-data-question-id=\\"question.id\\" t-att-data-graph-type=\\"'pie' if question.question_type == 'simple_choice' else 'bar'\\" t-att-data-graph-data=\\"graph_data\\" t-att-data-right-answers=\\"list(question_data['answer_line_done_ids'].mapped('value_scale')) if question.question_type in ['scale'] else list(question_data['right_answers'].mapped('value'))\\">\\n                <!-- canvas element for drawing bar chart -->\\n                <canvas class=\\"mx-auto w-100 h-auto\\"/>\\n            </div>\\n            <div role=\\"tabpanel\\" t-att-id=\\"'survey_data_question_%d' % question.id\\" t-attf-class=\\"tab-pane #{'active' if not question_answered else ''} table-responsive\\">\\n                <table class=\\"table table-hover table-sm mb-0\\">\\n                    <thead>\\n                        <tr>\\n                            <th>Answer</th>\\n                            <th t-if=\\"question_has_image_answers\\">Image</th>\\n                            <th>User Choice</th>\\n                            <th t-if=\\"question.is_scored_question\\">Score</th>\\n                        </tr>\\n                    </thead>\\n                    <tbody>\\n                        <tr t-foreach=\\"table_data\\" t-as=\\"choice_data\\">\\n                            <td>\\n                                <p class=\\"text-nowrap my-0\\">\\n                                    <span t-if=\\"question.question_type == 'numerical_box'\\">\\n                      