iv>\n                </div>\n            </div>\n            <div t-attf-class="collapse show o_survey_results_question_#{question.id} border rounded p-3">\n                <div class="d-flex flex-wrap align-items-center justify-content-between">\n                    <!-- Data buttons -->\n                    <div t-if="question.question_type not in ['text_box', 'char_box'] and question_answered" class="btn-group d-print-none mb-3" role="tablist">\n                        <a t-if="question.question_type in ['simple_choice', 'multiple_choice', 'matrix', 'scale']" t-att-href="'#survey_graph_question_%d' % question.id" t-att-aria-controls="'survey_graph_question_%d' % question.id" data-bs-toggle="tab" role="tab" class="o_survey_results_data_tab btn btn-light py-1 px-2 active" aria-label="Charts">\n                            <i t-if="question.question_type == 'simple_choice'" class="oi me-2" data-icon="pie_chart"/>\n                            <i t-else="" class="oi oi-fw" data-icon="bar_chart" aria-hidden="true"/><span class="d-none d-lg-inline ms-2">Charts</span>\n                        </a>\n                        <a t-elif="question.question_type in ['numerical_box', 'date', 'datetime']" t-att-href="'#survey_stats_question_%d' % question.id" t-att-aria-controls="'survey_stats_question_%d' % question.id" data-bs-toggle="tab" role="tab" class="o_survey_results_data_tab btn btn-light py-1 px-2 active" aria-label="Stats">\n                            <i class="oi oi-fw oi-filled" data-icon="trophy" aria-hidden="true"/><span class="d-none d-lg-inline ms-2">Stats</span>\n                        </a>\n                        <a t-att-href="'#survey_data_question_%d' % question.id" t-att-aria-controls="'survey_data_question_%d' % question.id" data-bs-toggle="tab" role="tab" class="o_survey_results_data_tab btn btn-light py-1 px-2" aria-label="Answers">\n                            <i class="oi oi-fw" data-icon="menu" aria-hidden="true"/><span class="d-none d-lg-inline ms-2">Answers</span>\n                        </a>\n                    </div>\n                    <!-- Question info -->\n                    <div t-if="survey.scoring_type != 'no_scoring' and (question.answer_numerical_box or question.answer_date or                         question.answer_datetime or any([a.is_correct for a in question.suggested_answer_ids]))" class="d-flex gap-2 align-items-center mb-3">\n                        <!-- Scoring info -->\n                        <small t-if="question.question_type in ['numerical_box', 'date', 'datetime', 'simple_choice', 'multiple_choice']" t-att-class="'rounded-pill py-1 px-3 ' + (                                 'border-success-subtle text-success-emphasis bg-success-subtle'                                 if question_data['right_inputs_count']                                 else 'border'                             )">\n                            <strong t-out="question_data['right_inputs_count']"/>\n                            <span> Correct</span>\n                        </small>\n                        <span t-if="question.question_type == 'multiple_choice'" t-att-class="'rounded-pill py-1 px-3 ' + (                                 'border-warning-subtle text-warning-emphasis bg-warning-subtle'                                 if question_data['partial_inputs_count']                                 else 'border'                             )">\n                            <strong t-out="question_data['partial_inputs_count']"/>\n                            <span>Partial</span>\n                        </span>\n                    </div>\n                    <!-- Numerical KPIs -->\n                    <span t-if="question.question_type in ['numerical_box', 'scale']" class="d-flex gap-2 mb-3 small">\n                        <div class="list-group list-group-horizontal" role="group" aria-label="Maximum">\n                            <span class="list-group-item py-1 px-2">Max</span>\n                            