r: #ffffff;\n                --btn-secondary-border-color: #03f9e3;\n                --btn-secondary-border-width: 2px;\n            }\n        </style>\n        <t t-set="now" t-value="datetime.datetime.now()"/>\n        <t t-set="website_url_or_none" t-value="(company_id.website) or '#'"/>\n        <section class="s_header_social o_mail_block_header_social o_mail_snippet_general pt16 pb16" data-vxml="001" data-snippet="s_mail_block_header_social" style="background-color: rgb(26, 36, 54) !important;" data-name="Header Social">\n            <div class="container">\n                <div class="row">\n                    <div class="col-md-4">\n                        <a style="text-decoration:none;float:none;" href="http://www.example.com" target="_blank">\n                             <img src="/mass_mailing_themes/static/src/img/theme_event/s_default_image_logo.png" style="height: auto; max-width: 100%; width: 194px;" width="194" alt="Your Logo" class="img-fluid"/>\n                        </a>\n                    </div>\n                    <div class="col-md-8 o_mail_header_social" t-translation="off" style="padding-left: 5px; padding-right: 5px;">\n                        <t t-call="mass_mailing.s_social_media_template" optionalIconLayout.f="rounded-circle shadow-sm" optionalTextStyle.f="color: white; background-color: rgb(43, 59, 88) !important;" optionalTextPosition.f="text-end" optionalSnippetClass.f="no_icon_color"/>\n                    </div>\n                </div>\n            </div>\n        </section>\n        <section class="s_cover o_mail_snippet_general" data-vxml="001" data-snippet="s_cover" data-name="Cover">\n            <div class="container">\n                <div class="row">\n                    <div class="oe_img_bg o_bg_img_center pb48 pt48 col-md-12" data-original-src="/mass_mailing_themes/static/src/img/theme_event/s_cover_default_image.jpg" style="background-image: url('/mass_mailing_themes/static/src/img/theme_event/s_cover_default_image.jpg');">\n                        <div class="o_we_bg_filter bg-black-50"/>\n                        <p><font class="text-white"><strong>SEPT 24-26, 2026</strong></font></p>\n                        <h1>\n                            <span class="display-1-fs"><font class="text-white">Join us at the</font></span>\n                            <font class="text-white"><br/></font>\n                            <span class="display-1-fs"><font class="text-white">Odoo Experience.</font></span>\n                        </h1>\n                        <p class="lead"><font class="text-white">Join us for a 2-day event filled with tech and business talks,<br/>workshops, and networking opportunities.</font></p>\n                        <p><a class="btn btn-lg btn-primary" href="https://www.example.com">Grab your ticket!</a></p>\n                    </div>\n                </div>\n            </div>\n        </section>\n        <section class="s_company_team_shapes o_mail_snippet_general pt48 pb48" data-snippet="s_company_team_shapes" data-name="Team Shapes">\n            <div class="container">\n                <p style="text-align: center;">\n                    <font style="color: rgb(3, 249, 227);">TECH &amp; BUSINESS TALKS<br/>﻿</font>\n                    <font class="text-o-color-4"><span class="h1-fs">Discover our panel of experts<br/><br/></span></font>\n                </p>\n                <div class="row">\n                    <div class="col-12 col-md-6 pb24">\n                       <div class="mb-3 o_not_editable">\n                            <img src="/web/image/mass_mailing.s_company_team_default_image_1" style="width: 100% !important;" class="img img-fluid o_editable_media mx-auto d-block mw-100" alt=""/>\n                        </div>\n                        <h3 style="text-align: center;"><font class="text-o-color-4">Mark E. Ting</font></h3>\n                        <p style="text-align: center;"><font class="text-o-color-4">Go beyond the basics and unlock the full power of Odoo's framework.</font></p>\n                    </div>\n                    <div class="col-12 col-md-6 pb24">\n                        <div class="mb-3 o_not_editable">\n                            <img src="/web/image/mass_mailing.s_company_team_default_image_2" style="width: 100% !important;" class="img img-fluid o_editable_media mx-auto d-block mw-100" alt=""/>\n                        </div>\n                        <h3 style="text-align: center;"><font class="text-o-color-4">Otto Mation</font></h3>\n                        <p style="text-align: center;"><font class="text-o-color-4">From idea to implementation, build smarter and faster in Odoo.</font></p>\n                    </div>\n                </div>\n            </div>\n        </section>\n        <section class="s_media_list o_mail_snippet_general o_cc o_cc2 pb16 pt0" style="background-color: rgb(26, 36, 54) !important; padding-left: 15px; padding-right: 15px;" data-snippet="s_media_list" data-vcss="001" data-vxml="001" data-name="Media List">\n            <div class="container">\n                <div class="row s_nb_column_fixed">\n                    <div class="col-md-12 s_media_list_item pt0 pb0" data-name="Media item">\n                        <div class="row s_col_no_resize o_mail_no_colorpicker align-items-center o_cc o_cc1">\n                            <div class="col-md-5 s_media_list_img_wrapper px-0">\n                                <img src="/mass_mailing_themes/static/src/img/theme_event/s_default_image_media_list_1.jpg" class="s_media_list_img w-100" style="padding: 10px;"/>\n                            </div>\n                            <div class="col-md-7 s_media_list_body">\n                                <h3>Get 6-months' worth of knowledge<br/>in just 2 days</h3>\n                                <p>Learn through workshops, product demos, and inspiring talks from Odoo Experts and Partners.</p>\n                                <p><a class="btn btn-lg btn-primary" t-att-href="website_url_or_none">Check the agenda</a></p>\n                            </div>\n                        </div>\n                    </div>\n                    <div class="col-md-12 s_media_list_item pt16 pb0" data-name="Media item">\n                        <div class="row s_col_no_resize o_mail_no_colorpicker align-items-center o_cc o_cc1">\n                            <div class="col-md-5 s_media_list_img_wrapper px-0">\n                                <img src="/mass_mailing_themes/static/src/img/theme_event/s_default_image_media_list_2.jpg" class="s_media_list_img w-100" style="padding: 10px;"/>\n                            </div>\n                            <div class="col-md-7 s_media_list_body">\n                                <h3>Meet (other) awesome members<br/>of the community</h3>\n                                <p>Create your very own chat room or join an existing one that sparks your interest.</p>\n                                <p><a class="btn btn-lg btn-primary" t-att-href="website_url_or_none">Browse chatrooms</a></p>\n                            </div>\n                        </div>\n                    </div>\n                    <div class="col-md-12 s_media_list_item pt16 pb0" data-name="Media item">\n                        <div class="row s_col_no_resize o_mail_no_colorpicker align-items-center o_cc o_cc1">\n                            <div class=" col-md-5 s_media_list_img_wrapper px-0">\n                                <img src="/mass_mailing_themes/static/src/img/theme_event/s_default_image_media_list_3.jpg" class="s_media_list_img w-100" style="padding: 10px;"/>\n                            </div>\n                            <div class="col-md-7 s_media_list_body">\n                                <h3>An interactive, fun<br/>and comprehensive experience</h3>\n                                <p>Experience everything from a virtual exhibitor's hall to multiple interactive presentations and demos.</p>\n                                <p><a class="btn btn-lg btn-primary" t-att-href="website_url_or_none">Find out more</a></p>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </section>\n        <section class="s_call_to_action o_mail_snippet_general o_cc o_cc3 pt40 pb40" data-vxml="001" style="background-color: rgb(26, 36, 54) !important;" data-snippet="s_call_to_action" data-name="Call to Action">\n            <div class="container">\n                <div class="row">\n                    <div class="col-md-12" style="border-color: rgb(56, 62, 69) !important;">\n                        <h3 style="text-align: center;"><font style="color: rgb(255, 255, 255);">And it won't cost you a thing!</font></h3>\n                        <p style="text-align: center;"><font style="color: rgb(255, 255, 255);">Zero, zilch, nada! Odoo Experience is free for everyone!</font></p>\n                    </div>\n                    <div class="col-md-12" style="text-align: center;">\n                        <p><a class="btn btn-primary btn-lg" t-att-href="website_url_or_none">Register now!</a></p>\n                    </div>\n                </div>\n            </div>\n        </section>\n        <section class="s_footer_social o_mail_block_footer_social o_mail_footer_social_center o_mail_snippet_general pt16 pb16" data-vxml="001" data-snippet="s_mail_block_footer_social" data-name="Footer Center">\n            <div class="container">\n                <div class="row">\n                    <div class="col-md-12 o_mail_footer_links pt8 pb8" style="text-align: center;">\n                        <a role="button" href="/unsubscribe_from_list" class="btn btn-link ">Unsubscribe</a>\n                    </div>\n                </div>\n                <div class="row">\n                    <div class="col-md-12">\n                        <p style="text-align: center;">\n                            <font style="color: rgb(255, 255, 255);">\n                                © <t t-out="now.strftime('%Y')"/> All Rights Reserved\n                            </font>\n                        </p>\n                    </div>\n                </div>\n            </div>\n        </section>\n    </t>\n\n    	\N	f	t	2026-10-26 23:49:16.255758	2026-10-26 23:49:16.255758	f
1632	16	\N	1	1	theme_event_updates_template	\N	mass_mailing_themes.theme_event_updates_template	qweb	mass_mailing_themes/views/mass_mailing_themes_templates.xml	primary	\N	{"en_US": "<t t-name=\\"mass_mailing_themes.theme_event_updates_template\\">\\n        <style id=\\"design-element\\">\\n            .o_layout .o_mail_wrapper .o_mail_wrapper_td {\\n                --h1-color: #ffffff;\\n                --h2-color: #ffffff;\\n                --h3-color: #ffffff;\\n                --h4-color: #ffffff;\\n                --text-color: rgba(255, 255, 255, 0.78);\\n                --text-font-size: 14px;\\n                --link-color: rgba(255, 255, 255, 0.78);\\n                --btn-primary-background-color: #6214d9;\\n                --btn-primary-border-color: #6214d9;\\n                --btn-primary-color: #ffffff;\\n                --btn-secondary-background-color:rgb(255, 255, 255);\\n                --btn-secondary-border-color: #252525;\\n                --btn-secondary-color: #252525;\\n                --separator-border-color: #e5e7eb !important;\\n                --wrapper-background-color: #0a0a0a;\\n            }\\n        </style>\\n        <t t-set=\\"now\\" t-value=\\"datetime.datetime.now()\\"/>\\n        <t t-set=\\"event1_date\\" t-value=\\"datetime.date.today() + datetime.timedelta(days=30)\\"/>\\n        <t t-set=\\"event2_date\\" t-value=\\"datetime.date.today() + datetime.timedelta(days=60)\\"/>\\n        <t t-set=\\"website_url_or_none\\" t-value=\\"(company_id.website) or '#'\\"/>\\n\\n        <section class=\\"s_header_logo o_mail_block_header_logo o_mail_snippet_general pt24 pb24\\" data-name=\\"Centered Logo\\" data-vxml=\\"001\\" data-snippet=\\"s_mail_block_header_logo\\">\\n            <div class=\\"container\\">\\n                <div class=\\"row\\">\\n                    <div class=\\"col-md-3\\"/>\\n                    <div class=\\"col-md-6\\" style=\\"text-align: center;\\">\\n                        <div class=\\"o_not_editable\\">\\n                            <a t-att-href=\\"(company_id.website) or '#'\\" style=\\"text-decoration:none;\\" target=\\"_blank\\">\\n                                <img src=\\"/mass_mailing_themes/static/src/img/theme_cta_centric/company_logo_dark.png\\" style=\\"height:auto; width: 50% !important;\\" alt=\\"Your Logo\\" class=\\"img-fluid o_editable_media py-4\\"/>\\n                            </a>\\n                        </div>\\n                    </div>\\n                    <div class=\\"col-md-3\\" style=\\"text-align: right;\\"/>\\n                </div>\\n            </div>\\n        </section>\\n\\n        <section class=\\"s_text_block o_mail_snippet_general px-3 pt32 pb16\\" data-vxml=\\"001\\" data-snippet=\\"s_text_block\\" data-name=\\"Paragraph\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <p style=\\"text-align: center; color: rgba(255, 255, 255, 0.78);\\" class=\\"mb-0\\">\\n                    There are new events for artists you follow. Don't miss out.\\n                </p>\\n            </div>\\n        </section>\\n\\n        <section class=\\"s_bento_blocks o_mail_snippet_general pt0 pb0\\" data-snippet=\\"s_bento_blocks\\" data-name=\\"Bento Blocks\\">\\n            <div class=\\"container\\">\\n                <div class=\\"row\\">\\n                    <div class=\\"col-md-12 col-12 pb24\\">\\n                        <div class=\\"o_colored_level o_cc o_cc2 bg-900\\" style=\\"padding: 24px; border-radius: 16px !important; text-align: center;\\" data-name=\\"Bento card\\">\\n                            <p style=\\"text-align: center;\\">\\n                                <img class=\\"img-fluid o_we_custom_image\\" src=\\"/mass_mailing_themes/static/src/img/theme_cta_centric/s_bento_block_default_image_1.webp\\" alt=\\"\\" style=\\"width: 30% !important; border-radius: 16px !important;\\"/>\\n                            </p>\\n                            <h3 style=\\"text-align: center; color: #fff