1626	16	\N	1	1	theme_newsletter_template	\N	mass_mailing_themes.theme_newsletter_template	qweb	mass_mailing_themes/views/mass_mailing_themes_templates.xml	primary	\N	{"en_US": "<t t-name=\\"mass_mailing_themes.theme_newsletter_template\\">\\n        <style id=\\"design-element\\">\\n            .o_layout .o_mail_wrapper .o_mail_wrapper_td {\\n                --h1-color: #CE0000;\\n                --h1-font-size: 54px;\\n\\n                --h2-font-weight: bolder;\\n\\n                --h3-font-size: 16px;\\n                --h3-font-weight: bolder;\\n\\n                --text-font-size: 16px;\\n\\n                --link-text-decoration-line: underline;\\n                --link-color: #212529;\\n\\n                --btn-primary-background-color: #CE0000;\\n                --btn-primary-border-color: #CE0000;\\n\\n                --btn-secondary-color: #CE0000;\\n                --btn-secondary-background-color: #FFFFFF;\\n                --btn-secondary-border-color: #CE0000;\\n            }\\n        </style>\\n        <t t-set=\\"now\\" t-value=\\"datetime.datetime.now()\\"/>\\n        <section class=\\"o_snippet_view_in_browser o_mail_snippet_general pt16 pb0\\" style=\\"text-align: left; padding-left: 15px; padding-right: 15px;\\" data-vxml=\\"001\\" data-name=\\"View in Browser\\">\\n            <p><a href=\\"/view\\" class=\\"\\" target=\\"_blank\\" data-bs-original-title=\\"\\" title=\\"\\">View in Browser</a> - <font style=\\"color: rgb(183, 191, 199);\\"><span style=\\"font-size: 12.25px\\" t-out=\\"datetime.datetime.now().strftime('%B %d %Y')\\"/></font></p>\\n        </section>\\n        <section class=\\"s_title o_mail_snippet_general pt32 pb32\\" data-vxml=\\"001\\" data-snippet=\\"s_title\\" data-name=\\"Title\\" style=\\"background-color: rgb(255, 255, 255) !important;\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <h1 style=\\"text-align:center\\" class=\\"\\">Weekly Musings</h1>\\n            </div>\\n        </section>\\n        <section class=\\"s_title o_mail_snippet_general px-3 pb0 pt0\\" data-vxml=\\"001\\" data-snippet=\\"s_title\\" data-name=\\"Title\\">\\n            <div class=\\"container s_allow_columns\\">\\n                    <h2 style=\\"\\" class=\\"\\">The story of Odoo</h2>\\n            </div>\\n        </section>\\n        <section class=\\"s_header_social o_mail_block_header_social o_mail_snippet_general bg-white px-3 pt24 pb24\\" style=\\"\\" data-vxml=\\"001\\" data-snippet=\\"s_mail_block_header_social\\" data-name=\\"Left Logo\\">\\n            <div class=\\"container\\" style=\\"\\">\\n                <div class=\\"col-md-12 o_mail_header_social\\" style=\\"background-color: rgb(255, 255, 255) !important; text-align: left;\\">\\n                    <a aria-label=\\"Facebook\\" target=\\"_blank\\" href=\\"https://www.facebook.com/Odoo\\" data-original-title=\\"Facebook\\" rel=\\"noreferrer\\">\\n                        <img class=\\"img-fluid o_we_custom_image\\" src=\\"/mass_mailing_themes/static/src/img/theme_newsletter/social-facebook.png\\" data-attachment-id=\\"435\\" data-original-id=\\"435\\" data-original-src=\\"/mass_mailing_themes/static/src/img/theme_newsletter/social-facebook.png\\" data-mimetype=\\"image/png\\" style=\\"width: 30px;\\"/>\\n                    </a>&amp;nbsp;&amp;nbsp;\\n                    <a aria-label=\\"X\\" target=\\"_blank\\" href=\\"https://twitter.com/Odoo\\" data-original-title=\\"X\\" rel=\\"noreferrer\\">\\n                        <img class=\\"img-fluid o_we_custom_image\\" src=\\"/mass_mailing_themes/static/src/img/theme_newsletter/social-twitter.png\\" data-attachment-id=\\"436\\" data-original-id=\\"436\\" data-original-src=\\"/mass_mailing_themes/static/src/img/theme_newsletter/social-twitter.png\\" data-mimetype=\\"image/png\\" style=\\"width: 30px;\\"/>\\n                    </a>&amp;nbsp;&amp;nbsp;\\n                    <a aria-label=\\"Instagram\\" target=\\"_blank\\" href=\\"https://www.linkedin.com/company/odoo\\" data-original-title=\\"Linkedin\\" rel=\\"noreferrer\\">\\n                        <img class=\\"img-fluid o_we_custom_image\\" src=\\"/mass_mailing_themes/static/src/img/theme_newsletter/social-linkedin.png\\" data-attachment-id=\\"437\\" data-original-id=\\"437\\" data-original-src=\\"/mass_mailing_themes/static/src/img/theme_newsletter/social-linkedin.png\\" data-mimetype=\\"image/png\\" style=\\"width: 30px;\\"/>\\n                    </a>\\n                </div>\\n            </div>\\n        </section>\\n        <section class=\\"s_text_block o_mail_snippet_general px-3 pb24\\" data-vxml=\\"001\\" data-snippet=\\"s_text_block\\" data-name=\\"Text\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <p style=\\"font-size: 14px;\\" class=\\"small text-muted\\">Musings on the week from <a style=\\"font-size: 14px;\\" href=\\"https://twitter.com/fpodoo?ref_src=twsrc%5Egoogle%7Ctwcamp%5Eserp%7Ctwgr%5Eauthor\\">@fpodoo</a></p>\\n            </div>\\n        </section>\\n        <section class=\\"s_title o_mail_snippet_general px-3 pb0 pt0\\" data-vxml=\\"001\\" data-snippet=\\"s_title\\" data-name=\\"Title\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <h3>Making companies a better place, one app at a time</h3>\\n            </div>\\n        </section>\\n        <section class=\\"s_text_block o_mail_snippet_general px-3 pt16 pb24 \\" data-vxml=\\"001\\" data-snippet=\\"s_text_block\\" data-name=\\"Text\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <p>I needed to change the world. I wanted to... You know how it is when you are young; you have big dreams, a lot of energy and naive stupidity. My dream was to lead the enterprise management market with a fully open source software (I also wanted to get 100 employees before 30 years old with a self-financed company but I failed this one by only a few months).</p>\\n                <p>To fuel my motivation, I had to pick someone to fight against. In business, it's like a playground. When you arrive in a new school, if you want to quickly become the leader, you must choose the class bully, the older guy who terrorizes small boys, and kick his butt in front of everyone. That was my strategy with SAP, the enterprise software giant.</p>\\n                <p>So in 2005, I started to develop the TinyERP product, the software that (at least in my mind) would change the enterprise world. While preparing for the \\"day of the fight\\" in 2006, I <a href=\\"http://whois.domaintools.com/sorrysap.com\\" target=\\"_blank\\">bought the SorrySAP.com domain name</a>. I put it on hold for 6 years, waiting for the right moment to use it. I thought it would take 3 years to deprecate a 77 billion dollars company just because open source is so cool. Sometimes it's better for your self-motivation not to face reality...</p>\\n                <p>To make things happen, I worked hard, very hard. I worked 13 hours a day, 7 days a week, with no vacation for 7 years. I lost friendships and broke up with my girlfriend in the process.</p>\\n                <p>Three years later, I discovered you can't change the world if you are \\"tiny\\". Especially if the United States is part of this world, where it's better to be a BigERP, rather than a TinyERP. Can you imagine how small you feel <a href=\\"http://slidesha.re/ohc44E\\" target=\\"_blank\\">in front of Danone's directors</a> asking; \\"But why should we pay millions of dollars for a tiny software?\\" So, we renamed TinyERP to OpenERP.</p>\\n                <p>As we worked hard, things started to evolve. We were developing dozens of modules for OpenERP, the open source community was growing and I was even able to pay all employees' salaries at the end of the month without fear (which was a situation I struggled with for 4 years).</p>\\n                <p>In 2010, we had a 100+ employees selling services on OpenERP and a powerful but ugly product. This is what happens when delivering services to customers distracts you from building an exceptional product. It was time to do a pivot in the business model.</p>\\n            </div>\\n        </section>\\n        <section class=\\"s_cover o_mail_snippet_general\\" data-vxml=\\"001\\" data-snippet=\\"s_cover\\" data-name=\\"Cover\\">\\n            <img src=\\"/mass_mailing_themes/static/src/img/theme_newsletter/s_default_image_block_banner.jpg\\" alt=\\"Cover image\\" class=\\"img-fluid w-100 mx-auto\\"/>\\n        </section>\\n        <section class=\\"s_title o_mail_snippet_general px-3 pb0 pt0\\" data-vxml=\\"001\\" data-snippet=\\"s_title\\" data-name=\\"Title\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <h3>The Pivot</h3>\\n            </div>\\n        </section>\\n        <section class=\\"s_text_block o_mail_snippet_general px-3 pt16 pb24\\" data-vxml=\\"001\\" data-snippet=\\"s_text_block\\" data-name=\\"Text\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <p>We wanted to switch from a service company to a software publisher company. This would allow us to increase our efforts in our research and development activities. As a result, <a href=\\"https://accounts.openerp.com/blog/OpenERP-Blog-Post-1/post/Open-Source-Free-as-in-Freedom-not-free-as-in-Free-services-119\\" target=\\"_blank\\">we changed our business model</a> and decided to stop our services for customers and focus on building a strong partner network and maintenance offer. This would cost money, so I had to raise a few million euros.</p>\\n                <p>After a few months of pitching investors, I got roughly 10 LOI from different VCs. We chose Sofinnova Partners, the biggest European VC, and Xavier Niel the founder of Iliad, the only company in France funded in the past 10 years to have reached the 1 billion EUR valuation.</p>\\n                <p>I signed the LOI. I didn't realize that this contract could have turned me into a homeless person. (I already had a dog, all I needed was to lose a lot of money to become homeless). The fundraising was based on a company valuation but there was a financial mechanism to re-evaluate the company up by 9.8 m€ depending on the turnover of the next 4 years. I should have received warrants convertible into shares if we achieved the turnover targeted in the business plan.</p>\\n                <p>The night before receiving the warrants in front of the notary, my wife checked the contracts. She asked me what would be the taxation on these warrants. I rang the lawyer and guess what? Belgium is probably the only country in the world where you have to pay taxes on warrants when you receive them, even if you never reach the conditions to convert them into shares. If I had accepted these warrants, I would have had to pay a 12.5% tax on 9.8 m€; resulting in a tax of 1.2m€ to pay in 18 months! So, my wife is worth 1.2 million EUR. I would have ended up a homeless person without her, as I still did not have a salary at that time.</p>\\n                <p>We changed the deal and I got the 3 million EUR. It allowed me to recruit a rocking management team.</p>\\n            </div>\\n        </section>\\n        <section class=\\"s_cover o_mail_snippet_general pb24\\" data-vxml=\\"001\\" data-snippet=\\"s_cover\\" data-name=\\"Cover\\">\\n            <img src=\\"/mass_mailing_themes/static/src/img/theme_newsletter/s_default_image_block_banner_2.jpg\\" alt=\\"Cover image\\" class=\\"img-fluid w-100 mx-auto\\"/>\\n        </section>\\n        <section class=\\"s_title o_mail_snippet_general px-3 pb0 pt0\\" data-vxml=\\"001\\" data-snippet=\\"s_title\\" data-name=\\"Title\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <h3>Being a Mature Company</h3>\\n            </div>\\n        </section>\\n        <section class=\\"s_text_block o_mail_snippet_general px-3 pt16 pb24\\" data-vxml=\\"001\\" data-snippet=\\"s_text_block\\" data-name=\\"Text\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <p>With this money in our bank account, we boosted two departments: R&amp;D and Sales. We burned 2 million EUR in 18 months, mostly in salaries. The company started to grow even faster. We developed a partner network of 500 partners in 100 countries and we started to sign contracts with 6 zeros.</p>\\n                <p>Then, things became different. You know, tedious things like handling human resources, board meetings, dealing with big customer contracts, traveling to launch international subsidiaries. We did boring stuff like budgets, career paths, management meetings, etc.</p>\\n                <p>2011 was a complex year. We did not meet our expectations: we only achieved 70% of the forecasted sales budget. Our management meetings were tense. We under-performed. We were not satisfied with ourselves. We had a constant feeling that we were missing something. It's a strange feeling to build extraordinary things but to not be proud of ourselves.</p>\\n                <p>But one day, someone (I don't remember who, I have a goldfish memory) made a graph of the monthly turnover of the past 2 years. It was like waking up from a nightmare. In fact, it was not that bad, we had multiplied the monthly turnover by 10 over the span of roughly two years! This is when we understood that OpenERP is a marathon, not a sprint. Only 100% growth a year is ok... if you can keep the rhythm for several years. </p>\\n                <p>As usual, I should have listened to my wife. She is way more lucid than I am. Every week I complained to her \\"It's not good enough, we should grow faster, what am I missing?\\" and she used to reply: \\"But you already are the fastest growing company in Belgium!\\" (Deloitte awarded us as <a href=\\"https://accounts.openerp.com/blog/OpenERP-Blog-1/post/Three-Awards-for-OpenERP-in-2013-139\\" target=\\"_blank\\">the fastest growing company of Belgium</a> with 1549% growth of the turnover between 2007 and 2011).</p>\\n            </div>\\n        </section>\\n        <section class=\\"s_title o_mail_snippet_general px-3 pb0 pt0\\" data-vxml=\\"001\\" data-snippet=\\"s_title\\" data-name=\\"Title\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <h3>Changing the World</h3>\\n            </div>\\n        </section>\\n        <section class=\\"s_text_block o_mail_snippet_general px-3 pt16 pb24\\" data-vxml=\\"001\\" data-snippet=\\"s_text_block\\" data-name=\\"Text\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <p>Then the dream started to become reality. We started to get clues that what we did would change the world:</p>\\n                <ul>\\n                    <li>With 1000 installations per day, we became the most installed management software in the world\\n                    </li>\\n                    <li><a href=\\"http://amzn.to/P4lRmE\\" target=\\"_blank\\">Analysts from Big 4 started to prefer OpenERP over SAP</a></li>\\n                    <li>OpenERP is now a compulsory subject for the baccalaureate in France like Word, Excel and PowerPoint</li>\\n                    <li>60 new modules are released every month (we became the wikipedia of the management software thanks to our strong community)</li>\\n                    <li>In 2013, we had 2,000,000 users worldwide</li>\\n                </ul>\\n                <p>Something is happening... And it's big!</p>\\n            </div>\\n        </section>\\n        <section class=\\"s_title o_mail_snippet_general px-3 pb0 pt0\\" data-vxml=\\"001\\" data-snippet=\\"s_title\\" data-name=\\"Title\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <h3>New Financing in 2014</h3>\\n            </div>\\n        </section>\\n        <section class=\\"s_text_block o_mail_snippet_general px-3 pt16 pb24\\" data-vxml=\\"001\\" data-snippet=\\"s_text_block\\" data-name=\\"Text\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <p>After years of rapid growth, we achieved another amazing goal - we secured a new round of 10 Million USD of financing, jointly provided by leading venture capital firms XAnge (France), SRIW (Belgium), Sofinnova (France), and the management team.</p>\\n                <p>The new financing will support the acceleration of the outstanding growth the company has seen over the last years, enabling the doubling of the commercial force and increased R&amp;D staff - already 100+ people strong. </p>\\n            </div>\\n        </section>\\n        <section class=\\"s_cover o_mail_snippet_general pb24\\" data-vxml=\\"001\\" data-snippet=\\"s_cover\\" data-name=\\"Cover\\">\\n            <img src=\\"/mass_mailing_themes/static/src/img/theme_newsletter/s_default_image_block_banner_3.jpg\\" alt=\\"Cover image\\" class=\\"img-fluid w-100 mx-auto\\"/>\\n        </section>\\n        <section class=\\"s_title o_mail_snippet_general px-3 pb0 pt0\\" data-vxml=\\"001\\" data-snippet=\\"s_title\\" data-name=\\"Title\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <h3>The Rise of Odoo</h3>\\n            </div>\\n        </section>\\n        <section class=\\"s_text_block o_mail_snippet_general px-3 pt16\\" data-vxml=\\"001\\" data-snippet=\\"s_text_block\\" data-name=\\"Text\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <p>After having disrupted the ERP market, OpenERP moved far beyond the boundaries of traditional ERP players. The integration of business activities is no longer restricted to sales, accounting, inventory and procurements. In June 2014, we released version 8 with awesome CMS &amp; eCommerce, a Point of Sale, an integrated Business Intelligence engine and much more (3000+ modules).</p>\\n                <p>Our exceptional technology allowed us to move to newer markets (CMS &amp; eCommerce) and propose a product that disrupts existing open source players (Wordpress, Magento, etc). The OpenERP CMS is so good that even top competitors admitted it publicly when we released the beta version.</p>\\n                <p>If current open source players have a real technical challenge to follow us, we also have a huge marketing challenge. Wordpress has 22% of all internet websites. We were the leader in management software, but we start with 0% of the website market.</p>\\n                <p>To move forward, we raised 10 million USD in May 2014 in order to boost marketing and sales activities. In order to support our vision, we had to change the name that is not restricted to ERPs functions. We needed a name that allowed us to support our ambitions; build business solutions like CMS, eCommerce, Business Intelligence and, who knows, even sky rockets or driverless cars in the future...</p>\\n                <p>In May 2014, we renamed the company and product to Odoo.</p>\\n                <p>And a new story just started...</p>\\n            </div>\\n        </section>\\n        <section class=\\"s_text_block o_mail_snippet_general pb16 px-3\\" data-vxml=\\"001\\" data-snippet=\\"s_text_block\\" data-name=\\"Text\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <img src=\\"/mass_mailing_themes/static/src/img/theme_newsletter/FPsignature.gif\\" style=\\"width: 125px\\" alt=\\"\\"/>\\n                <p style=\\"text-align:center;\\" class=\\"pt32\\">\\n                    <a role=\\"button\\" href=\\"#\\" class=\\"btn btn-primary btn-lg\\" target=\\"_blank\\">&amp;nbsp;&amp;nbsp;Comment on this post&amp;nbsp;&amp;nbsp;</a>\\n                </p>\\n            </div>\\n        </section>\\n        <section class=\\"s_footer_social o_mail_block_footer_social o_mail_footer_social_center o_mail_snippet_general o_cc o_cc1 pt0 pb0\\" data-vxml=\\"001\\" data-snippet=\\"s_mail_block_footer_social\\" data-name=\\"Footer Center\\">\\n            <div class=\\"container\\">\\n                <div class=\\"col-md-12 o_mail_footer_social pt0 pb0\\" style=\\"text-align: center;\\">\\n                    <a aria-label=\\"Facebook\\" target=\\"_blank\\" href=\\"https://www.facebook.com/Odoo\\" data-original-title=\\"Facebook\\" rel=\\"noreferrer\\">\\n                        <img class=\\"img-fluid o_we_custom_image\\" src=\\"/mass_mailing_themes/static/src/img/theme_newsletter/social-facebook.png\\" data-attachment-id=\\"435\\" data-original-id=\\"435\\" data-original-src=\\"/mass_mailing_themes/static/src/img/theme_newsletter/social-facebook.png\\" data-mimetype=\\"image/png\\" style=\\"width: 30px;\\"/>\\n                    </a>&amp;nbsp;&amp;nbsp;\\n                    <a aria-label=\\"X\\" target=\\"_blank\\" href=\\"https://twitter.com/Odoo\\" data-original-title=\\"X\\" rel=\\"noreferrer\\">\\n                        <img class=\\"img-fluid o_we_custom_image\\" src=\\"/mass_mailing_themes/static/src/img/theme_newsletter/social-twitter.png\\" data-attachment-id=\\"436\\" data-original-id=\\"436\\" data-original-src=\\"/mass_mailing_themes/static/src/img/theme_newsletter/social-twitter.png\\" data-mimetype=\\"image/png\\" style=\\"width: 30px;\\"/>\\n                    </a>&amp;nbsp;&amp;nbsp;\\n                    <a aria-label=\\"Instagram\\" target=\\"_blank\\" href=\\"https://www.linkedin.com/company/odoo\\" data-original-title=\\"Linkedin\\" rel=\\"noreferrer\\">\\n                        <img class=\\"img-fluid o_we_custom_image\\" src=\\"/mass_mailing_themes/static/src/img/theme_newsletter/social-linkedin.png\\" data-attachment-id=\\"437\\" data-original-id=\\"437\\" data-original-src=\\"/mass_mailing_themes/static/src/img/theme_newsletter/social-linkedin.png\\" data-mimetype=\\"image/png\\" style=\\"width: 30px;\\"/>\\n                    </a>\\n                </div>\\n            </div>\\n        </section>\\n        <div class=\\"s_hr o_mail_snippet_general pt16 pb16\\" data-vxml=\\"001\\" data-snippet=\\"s_hr\\" data-name=\\"Separator\\">\\n            <hr class=\\"s_hr_1px s_hr_solid\\" style=\\"border-top-color: rgb(108, 117, 125) !important;\\"/>\\n        </div>\\n        <section class=\\"s_footer_social o_mail_block_footer_social o_mail_footer_social_center o_mail_snippet_general o_cc o_cc1 pt0 pb0\\" data-vxml=\\"001\\" data-snippet=\\"s_mail_block_footer_social\\" data-name=\\"Footer Center\\">\\n            <div class=\\"container\\" style=\\"text-align: center; color:rgb(183, 191, 199) !important;\\">\\n                <span style=\\"font-size: 12px;\\"><font style=\\"color: rgb(183, 191, 199);\\">8000 Marina Blvd, Suite 300</font></span>\\n                <br/>\\n                <span style=\\"font-size: 12px;\\"><font style=\\"color: rgb(183, 191, 199);\\">Brisbane, California 94005</font></span>\\n                <br/>\\n                <span style=\\"font-size: 12px;\\"><font style=\\"color: rgb(183, 191, 199);\\">You received this email from </font></span><a href=\\"mailto:\\" target=\\"_blank\\"><span style=\\"font-size: 12px;\\"><font style=\\"color: rgb(183, 191, 199);\\">hello@musingsoftheweek.com</font></span></a>\\n                <br/>\\n                <span style=\\"font-size: 12px;\\"><font style=\\"color: rgb(183, 191, 199);\\">To unsubscribe, </font></span><a href=\\"/unsubscribe_from_list\\" target=\\"_blank\\"><span style=\\"font-size: 12px;\\"><font style=\\"color: rgb(183, 191, 199);\\">click here</font></span></a><span style=\\"font-size: 12px;\\"><font style=\\"color: rgb(183, 191, 199);\\">.</font></span>\\n            </div>\\n        </section>\\n    </t>", "es_ES": "<t t-name=\\"mass_mailing_themes.theme_newsletter_template\\">\\n        <style id=\\"design-element\\">\\n            .o_layout .o_mail_wrapper .o_mail_wrapper_td {\\n                --h1-color: #CE0000;\\n                --h1-font-size: 54px;\\n\\n                --h2-font-weight: bolder;\\n\\n                --h3-font-size: 16px;\\n                --h3-font-weight: bolder;\\n\\n                --text-font-size: 16px;\\n\\n                --link-text-decoration-line: underline;\\n                --link-color: #212529;\\n\\n                --btn-primary-background-color: #CE0000;\\n                --btn-primary-border-color: #CE0000;\\n\\n                --btn-secondary-color: #CE0000;\\n                --btn-secondary-background-color: #FFFFFF;\\n                --btn-secondary-border-color: #CE0000;\\n            }\\n        </style>\\n        <t t-set=\\"now\\" t-value=\\"datetime.datetime.now()\\"/>\\n        <section class=\\"o_snippet_view_in_browser o_mail_snippet_general pt16 pb0\\" style=\\"text-align: left; padding-left: 15px; padding-right: 15px;\\" data-vxml=\\"001\\" data-name=\\"View in Browser\\">\\n            <p><a href=\\"/view\\" class=\\"\\" target=\\"_blank\\" data-bs-original-title=\\"\\" title=\\"\\">View in Browser</a> - <font style=\\"color: rgb(183, 191, 199);\\"><span style=\\"font-size: 12.25px\\" t-out=\\"datetime.datetime.now().strftime('%B %d %Y')\\"/></font></p>\\n        </section>\\n        <section class=\\"s_title o_mail_snippet_general pt32 pb32\\" data-vxml=\\"001\\" data-snippet=\\"s_title\\" data-name=\\"Title\\" style=\\"background-color: rgb(255, 255, 255) !important;\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <h1 style=\\"text-align:center\\" class=\\"\\">Reflexiones semanales</h1>\\n            </div>\\n        </section>\\n        <section class=\\"s_title o_mail_snippet_general px-3 pb0 pt0\\" data-vxml=\\"001\\" data-snippet=\\"s_title\\" data-name=\\"Title\\">\\n            <div class=\\"container s_allow_columns\\">\\n                    <h2 style=\\"\\" class=\\"\\">La historia de Odoo</h2>\\n            </div>\\n        </section>\\n        <section class=\\"s_header_social o_mail_block_header_social o_mail_snippet_general bg-white px-3 pt24 pb24\\" style=\\"\\" data-vxml=\\"001\\" data-snippet=\\"s_mail_block_header_social\\" data-name=\\"Left Logo\\">\\n            <div class=\\"container\\" style=\\"\\">\\n                <div class=\\"col-md-12 o_mail_header_social\\" style=\\"background-color: rgb(255, 255, 255) !important; text-align: left;\\">\\n                    <a aria-label=\\"Facebook\\" target=\\"_blank\\" href=\\"https://www.facebook.com/Odoo\\" data-original-title=\\"Facebook\\" rel=\\"noreferrer\\">\\n                        <img class=\\"img-fluid o_we_custom_image\\" src=\\"/mass_mailing_themes/static/src/img/theme_newsletter/social-facebook.png\\" data-attachment-id=\\"435\\" data-original-id=\\"435\\" data-original-src=\\"/mass_mailing_themes/static/src/img/theme_newsletter/social-facebook.png\\" data-mimetype=\\"image/png\\" style=\\"width: 30px;\\"/>\\n                    </a>&amp;nbsp;&amp;nbsp;\\n                    <a aria-label=\\"X\\" target=\\"_blank\\" href=\\"https://twitter.com/Odoo\\" data-original-title=\\"X\\" rel=\\"noreferrer\\">\\n                        <img class=\\"img-fluid o_we_custom_image\\" src=\\"/mass_mailing_themes/static/src/img/theme_newsletter/social-twitter.png\\" data-attachment-id=\\"436\\" data-original-id=\\"436\\" data-original-src=\\"/mass_mailing_themes/static/src/img/theme_newsletter/social-twitter.png\\" data-mimetype=\\"image/png\\" style=\\"width: 30px;\\"/>\\n                    </a>&amp;nbsp;&amp;nbsp;\\n                    <a aria-label=\\"Instagram\\" target=\\"_blank\\" href=\\"https://www.linkedin.com/company/odoo\\" data-original-title=\\"Linkedin\\" rel=\\"noreferrer\\">\\n                        <img class=\\"img-fluid o_we_custom_image\\" src=\\"/mass_mailing_themes/static/src/img/theme_newsletter/social-linkedin.png\\" data-attachment-id=\\"437\\" data-original-id=\\"437\\" data-original-src=\\"/mass_mailing_themes/static/src/img/theme_newsletter/social-linkedin.png\\" data-mimetype=\\"image/png\\" style=\\"width: 30px;\\"/>\\n                    </a>\\n                </div>\\n            </div>\\n        </section>\\n        <section class=\\"s_text_block o_mail_snippet_general px-3 pb24\\" data-vxml=\\"001\\" data-snippet=\\"s_text_block\\" data-name=\\"Text\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <p style=\\"font-size: 14px;\\" class=\\"small text-muted\\">Reflexiones de la semana de <a style=\\"font-size: 14px;\\" href=\\"https://twitter.com/fpodoo?ref_src=twsrc%5Egoogle%7Ctwcamp%5Eserp%7Ctwgr%5Eauthor\\">@fpodoo</a></p>\\n            </div>\\n        </section>\\n        <section class=\\"s_title o_mail_snippet_general px-3 pb0 pt0\\" data-vxml=\\"001\\" data-snippet=\\"s_title\\" data-name=\\"Title\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <h3>Haciendo de las empresas un lugar mejor, una aplicación a la vez</h3>\\n            </div>\\n        </section>\\n        <section class=\\"s_text_block o_mail_snippet_general px-3 pt16 pb24 \\" data-vxml=\\"001\\" data-snippet=\\"s_text_block\\" data-name=\\"Text\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <p>Necesitaba cambiar el mundo. Quería... ya sabe como es cuando uno es joven, uno tiene muchos sueños, mucha energía y estupidez ingenua. Mi sueño era liderar el mercado de la gestión empresarial con un software de código completamente abierto (también quería tener 100 empleados antes de cumplir 30 años con una empresa autofinanciada pero fracasé en esto por sólo unos meses).</p>\\n                <p>Para motivarme, tuve que escoger contra quién pelear. Los negocios son como un patio de juegos. Cuando se llega a una nueva escuela, si se quiere ser el líder rápidamente, debe enfrentarse al matón de la clase, el que aterroriza a los niños pequeños, y les patea el culo en frente de todos. Esta era mi estrategia con SAP, el gigante de software empresarial.</p>\\n                <p>En 2005, comencé a desarrollar el producto de TinyERP, el software que (por lo menos en mi cabeza) cambiaría el mundo empresarial. Mientras me preparaba para el \\"día de la batalla\\" en 2006, <a href=\\"http://whois.domaintools.com/sorrysap.com\\" target=\\"_blank\\">compramos el nombre del dominio de SorrySAP.com</a>. Lo guardé por 6 años, esperando el momento correcto para usarlo. Creí que una empresa de 77 mil millones de dólares tardaría 3 años en depreciarse solamente porque el código abierto es genial. A veces es mejor no enfrentar la realidad por el bien de la motivación.</p>\\n                <p>Para que todo funcionara, trabaje duro, muy duro. Trabajaba 13 horas los 7 días de la semana, sin vacaciones por 7 años. Perdí amistades y rompí con mi pareja en el proceso.</p>\\n                <p>Tres años después, descubrí que no se puede cambiar el mundo si eres \\"tiny\\" (pequeño). Especialmente si los Estados Unidos forman parte de este mundo, dónde es mejor ser una BigERP en lugar de una TinyERP. Ya se imaginará lo pequeños que nos sentimos <a href=\\"http://slidesha.re/ohc44E\\" target=\\"_blank\\">en frente de los directores de Danone</a> preguntando; \\"Pero, ¿por qué pagaríamos millones de dólares por un software pequeño?\\" Entonces, cambiamos el nombre de TinyERP a OpenERP.</p>\\n                <p>A medida que trabajábamos duro, las cosas empezaron a cambiar. Estábamos desarrollando docenas de módulos para OpenERP, la comunidad de código abierto estaba creciendo e incluso pude pagar la nómina de todos mis empleados sin preocuparme (una situación con la que luché durante 4 años).</p>\\n                <p>En 2010, tuvimos más de 100 empleados vendiendo servicios en OpenERP y un producto poderoso pero feo. Esto es lo que sucede cuando proporcionar un servicio a los clientes lo distrae de crear un producto excepcional. Ya era hora de dar un giro al modelo de negocios.</p>\\n            </div>\\n        </section>\\n        <section class=\\"s_cover o_mail_snippet_general\\" data-vxml=\\"001\\" data-snippet=\\"s_cover\\" data-name=\\"Cover\\">\\n            <img src=\\"/mass_mailing_themes/static/src/img/theme_newsletter/s_default_image_block_banner.jpg\\" alt=\\"Imagen de la portada\\" class=\\"img-fluid w-100 mx-auto\\"/>\\n        </section>\\n        <section class=\\"s_title o_mail_snippet_general px-3 pb0 pt0\\" data-vxml=\\"001\\" data-snippet=\\"s_title\\" data-name=\\"Title\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <h3>El momento crucial</h3>\\n            </div>\\n        </section>\\n        <section class=\\"s_text_block o_mail_snippet_general px-3 pt16 pb24\\" data-vxml=\\"001\\" data-snippet=\\"s_text_block\\" data-name=\\"Text\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <p>Quisimos cambiar de una empresa de servicios a una empresa editora de software. Esto nos permitiría incrementar nuestros esfuerzo en actividades de investigación y desarrollo. Como resultado, <a href=\\"https://accounts.openerp.com/blog/OpenERP-Blog-Post-1/post/Open-Source-Free-as-in-Freedom-not-free-as-in-Free-services-119\\" target=\\"_blank\\">cambiamos nuestro modelo de negocios</a> y decidimos suspender nuestros servicios para los clientes y nos concentramos en construir una red sólida de socios y una oferta de mantenimiento. Esto sería costoso, por lo que tuve que recaudar unos cuantos millones de euros.</p>\\n                <p>Después de algunos meses de negociar con inversores, recibí cerca de 10 cartas de intenciones de diferentes fondos de capital de riesgo. Escogimos a Sofinnova Partners, el fondo de capital de riesgo más grande de Europa, y a Xavier Niel, fundador de Iliad, la única empresa francesa de los últimos 10 años que ha logrado alcanzar una valoración de mil millones de euros.</p>\\n                <p>Firmé la carta de intención. No me di cuenta de que este contrato pudo haberme dejado en la calle. (Ya tenía un perro, todo lo que necesitaba era perder muchísimo dinero para ser que así fuera). La recaudación de fondos estaba basada en la valuación de la empresa pero había un mecanismo financiero para reevaluar la empresa hasta los 9,8 m de euros que dependía de la facturación de los próximos 4 años. Debí haber recibido garantías que se pudieran convertir en acciones si lográbamos la facturación proyectada en el plan de negocios.</p>\\n                <p>La noche previa a recibir las garantías frente al notario, mi esposa revisó los contratos. Me preguntó qué podría ser el impuesto sobre esas garantías. Llamé a mi abogado y ¿adivine qué? Probablemente Bélgica sea el único país en el mundo en donde se deben pagar impuestos sobre las garantías que recibe, incluso si nunca logra las condiciones para convertirlas en acciones. Si hubiera aceptado estas garantías, habría pagado un 12,5 % de impuesto sobre 9,8m de euros, lo que da como resultado un impuesto a pagar de 1,2 m de euros en 18 meses. Entonces, mi esposa vale 1,2 millones de euros. Habría terminado en la calle de no ser por ella, y en ese tiempo aún no tenía salario.</p>\\n                <p>Cambiamos el acuerdo y obtuve los 3 millones de euros, lo que me permitió reclutar un increíble equipo de administración.</p>\\n            </div>\\n        </section>\\n        <section class=\\"s_cover o_mail_snippet_general pb24\\" data-vxml=\\"001\\" data-snippet=\\"s_cover\\" data-name=\\"Cover\\">\\n            <img src=\\"/mass_mailing_themes/static/src/img/theme_newsletter/s_default_image_block_banner_2.jpg\\" alt=\\"Imagen de la portada\\" class=\\"img-fluid w-100 mx-auto\\"/>\\n        </section>\\n        <section class=\\"s_title o_mail_snippet_general px-3 pb0 pt0\\" data-vxml=\\"001\\" data-snippet=\\"s_title\\" data-name=\\"Title\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <h3>Ser una empresa madura</h3>\\n            </div>\\n        </section>\\n        <section class=\\"s_text_block o_mail_snippet_general px-3 pt16 pb24\\" data-vxml=\\"001\\" data-snippet=\\"s_text_block\\" data-name=\\"Text\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <p>Con este dinero en nuestra cuenta bancaria, impulsamos dos departamentos: I&amp;D y ventas. Nos gastamos 2 millones de euros en 18 meses, sobre todo en salarios. La empresa empezó a crecer aún más rápido. Desarrollamos una red de 500 socios en 100 países, y empezamos a firmar contratos de 7 cifras.</p>\\n                <p>Luego, las cosas empezaron a cambiar. Cosas tediosas como gestionar recursos humanos, reuniones directivas, lidiar con grandes contratos de clientes, viajar para inaugurar filiales internacionales. Hicimos cosas aburridas como presupuestos, planes de carrera, reuniones administrativas, etc.</p>\\n                <p>El año 2011 fue complicado. No cumplimos con nuestros objetivos: solo alcanzamos el 70 % del presupuesto de ventas pronosticado. Nuestras reuniones directivas son tensas, no tuvimos un buen rendimiento y no estamos satisfechos. Tenemos constantemente la sensación de que algo nos falta. Es extraño sentir que construimos algo extraordinario y no sentirnos orgullosos de ello.</p>\\n                <p>Pero un día, alguien (no recuerdo quién, tengo memoria de pez dorado) hizo una gráfica de la facturación mensual de los últimos 2 años. Fue como despertar de una pesadilla. De hecho, no estaba tan mal, habíamos multiplicado la facturación mensual por 10 a lo largo de esos dos años. Ahí fue cuando entendimos que OpenERP era un maratón y no una carrera. Un crecimiento de solo el 100 % está bien, siempre y cuando podamos seguir así por muchos años. </p>\\n                <p>Como siempre, debería haber escuchado a mi mujer. Ella es mucho más brillante que yo. Todas las semanas me quejaba con ella: \\"No es lo suficientemente bueno, deberíamos crecer más rápido, ¿qué me estoy perdiendo?\\" y ella solía responder: \\"¡Pero si ya sois la empresa que más rápido crece en Bélgica!\\". (Deloitte nos premió como <a href=\\"https://accounts.openerp.com/blog/OpenERP-Blog-1/post/Three-Awards-for-OpenERP-in-2013-139\\" target=\\"_blank\\">la empresa de más rápido crecimiento en Bélgica</a> con un crecimiento de facturación del 1549 % entre 2007 y 2011).</p>\\n            </div>\\n        </section>\\n        <section class=\\"s_title o_mail_snippet_general px-3 pb0 pt0\\" data-vxml=\\"001\\" data-snippet=\\"s_title\\" data-name=\\"Title\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <h3>Cambiando el mundo</h3>\\n            </div>\\n        </section>\\n        <section class=\\"s_text_block o_mail_snippet_general px-3 pt16 pb24\\" data-vxml=\\"001\\" data-snippet=\\"s_text_block\\" data-name=\\"Text\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <p>Entonces mis sueños empezaron a hacerse realidad. Comenzamos a obtener pistas de que lo que hicimos podía cambiar el mundo:</p>\\n                <ul>\\n                    <li>Con 1000 instalaciones al día, nos convertimos en el software de gestión más instalado en el mundo\\n                    </li>\\n                    <li><a href=\\"http://amzn.to/P4lRmE\\" target=\\"_blank\\">Analistas de los Big 4 prefieren OpenERP en lugar de SAP</a></li>\\n                    <li>Ahora, OpenERP es una materia obligatoria en las preparatorias de Francia como Word, Excel y PowerPoint</li>\\n                    <li>Se publican 60 módulos nuevos cada mes (nos convertimos en la Wikipedia del software empresarial gracias a nuestra comunidad tan spolida)</li>\\n                    <li>En 2013, tuvimos 2.000.000 de usuarios en todo el mundo.</li>\\n                </ul>\\n                <p>Algo está pasando ¡y será algo grande!</p>\\n            </div>\\n        </section>\\n        <section class=\\"s_title o_mail_snippet_general px-3 pb0 pt0\\" data-vxml=\\"001\\" data-snippet=\\"s_title\\" data-name=\\"Title\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <h3>Nuevo financiamiento en 2014</h3>\\n            </div>\\n        </section>\\n        <section class=\\"s_text_block o_mail_snippet_general px-3 pt16 pb24\\" data-vxml=\\"001\\" data-snippet=\\"s_text_block\\" data-name=\\"Text\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <p>Después de años de rápido crecimiento, hemos alcanzado otra meta asombrosa: conseguimos una nueva ronda de financiamiento de 10 millones de dólares, proporcionados de manera conjunta por XAnge (Francia), SRIW (Bélgica), Sofinnova (Francia) , las principales empresas de fondos de capital de riesgo; además del apoyo del equipo directivo.</p>\\n                <p>El nuevo financiamiento ayudará al aumento del increíble crecimiento del que la empresa se ha beneficiado los últimos años, y así, permitir que se doble la fuerza comercial y crezca el equipo de investigación y desarrollo de más de 100 grandes personas. </p>\\n            </div>\\n        </section>\\n        <section class=\\"s_cover o_mail_snippet_general pb24\\" data-vxml=\\"001\\" data-snippet=\\"s_cover\\" data-name=\\"Cover\\">\\n            <img src=\\"/mass_mailing_themes/static/src/img/theme_newsletter/s_default_image_block_banner_3.jpg\\" alt=\\"Imagen de la portada\\" class=\\"img-fluid w-100 mx-auto\\"/>\\n        </section>\\n        <section class=\\"s_title o_mail_snippet_general px-3 pb0 pt0\\" data-vxml=\\"001\\" data-snippet=\\"s_title\\" data-name=\\"Title\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <h3>El auge de Odoo</h3>\\n            </div>\\n        </section>\\n        <section class=\\"s_text_block o_mail_snippet_general px-3 pt16\\" data-vxml=\\"001\\" data-snippet=\\"s_text_block\\" data-name=\\"Text\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <p>Despúes de haber cambiado el mercado de los ERP, OpenERP ha superado los límites de los ERP tradicionales. La integración de actividades empresariales ya no se limita a las ventas, contabilidad, inventario y suministro. En junio del 2014, lanzamos la versión 8 que incluye un increíble CMS (Sistema de gestión de contenidos), comercio electrónico, un punto de venta, un motor de Inteligencia Empresarial integrado y mucho más (+3000 módulos).</p>\\n                <p>Nuestra tecnología excepcional nos ha permitido movernos a mercados más nuevos (CMS y comercio electrónico) y proponer un producto que impacte a los usuarios existentes del código abierto (Wordpress, Magento, etc.). El CMS de OpenERP es tan bueno que incluso nuestra competencia principal lo admitió públicamente cuando lanzamos la versión beta.</p>\\n                <p>Si los actores actuales del código abierto enfrentan un verdadero reto técnico para seguirnos, nosotros también enfrentamos un enorme reto de marketing. Wordpress tiene el 22 % de todos los sitios web de internet. Éramos el líder en software de gestión, pero empezamos con un 0 % del mercado de sitios web.</p>\\n                <p>Para seguir adelante, recaudamos 10 millones de dólares en mayo de 2014 para reforzar nuestras actividades de marketing y ventas. También para respaldar nuestra visión, tuvimos que cambiar el nombre para que no se limitara a las funciones de ERP. Necesitábamos un nombre que nos permitiera reforzar nuestras ambiciones; crear soluciones empresariales como el CMS, el comercio electrónico, la inteligencia empresarial y, quién sabe, incluso cohetes y coches sin conductor en el futuro...</p>\\n                <p>En mayo de 2014, le cambiamos el nombre a la empresa y al producto por Odoo.</p>\\n                <p>Y acaba de iniciar una nueva historia...</p>\\n            </div>\\n        </section>\\n        <section class=\\"s_text_block o_mail_snippet_general pb16 px-3\\" data-vxml=\\"001\\" data-snippet=\\"s_text_block\\" data-name=\\"Text\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <img src=\\"/mass_mailing_themes/static/src/img/theme_newsletter/FPsignature.gif\\" style=\\"width: 125px\\" alt=\\"\\"/>\\n                <p style=\\"text-align:center;\\" class=\\"pt32\\">\\n                    <a role=\\"button\\" href=\\"#\\" class=\\"btn btn-primary btn-lg\\" target=\\"_blank\\">&amp;nbsp;&amp;nbsp;Comentar esta publicación&amp;nbsp;&amp;nbsp;</a>\\n                </p>\\n            </div>\\n        </section>\\n        <section class=\\"s_footer_social o_mail_block_footer_social o_mail_footer_social_center o_mail_snippet_general o_cc o_cc1 pt0 pb0\\" data-vxml=\\"001\\" data-snippet=\\"s_mail_block_footer_social\\" data-name=\\"Footer Center\\">\\n            <div class=\\"container\\">\\n                <div class=\\"col-md-12 o_mail_footer_social pt0 pb0\\" style=\\"text-align: center;\\">\\n                    <a aria-label=\\"Facebook\\" target=\\"_blank\\" href=\\"https://www.facebook.com/Odoo\\" data-original-title=\\"Facebook\\" rel=\\"noreferrer\\">\\n                        <img class=\\"img-fluid o_we_custom_image\\" src=\\"/mass_mailing_themes/static/src/img/theme_newsletter/social-facebook.png\\" data-attachment-id=\\"435\\" data-original-id=\\"435\\" data-original-src=\\"/mass_mailing_themes/static/src/img/theme_newsletter/social-facebook.png\\" data-mimetype=\\"image/png\\" style=\\"width: 30px;\\"/>\\n                    </a>&amp;nbsp;&amp;nbsp;\\n                    <a aria-label=\\"X\\" target=\\"_blank\\" href=\\"https://twitter.com/Odoo\\" data-original-title=\\"X\\" rel=\\"noreferrer\\">\\n                        <img class=\\"img-fluid o_we_custom_image\\" src=\\"/mass_mailing_themes/static/src/img/theme_newsletter/social-twitter.png\\" data-attachment-id=\\"436\\" data-original-id=\\"436\\" data-original-src=\\"/mass_mailing_themes/static/src/img/theme_newsletter/social-twitter.png\\" data-mimetype=\\"image/png\\" style=\\"width: 30px;\\"/>\\n                    </a>&amp;nbsp;&amp;nbsp;\\n                    <a aria-label=\\"Instagram\\" target=\\"_blank\\" href=\\"https://www.linkedin.com/company/odoo\\" data-original-title=\\"Linkedin\\" rel=\\"noreferrer\\">\\n                        <img class=\\"img-fluid o_we_custom_image\\" src=\\"/mass_mailing_themes/static/src/img/theme_newsletter/social-linkedin.png\\" data-attachment-id=\\"437\\" data-original-id=\\"437\\" data-original-src=\\"/mass_mailing_themes/static/src/img/theme_newsletter/social-linkedin.png\\" data-mimetype=\\"image/png\\" style=\\"width: 30px;\\"/>\\n                    </a>\\n                </div>\\n            </div>\\n        </section>\\n        <div class=\\"s_hr o_mail_snippet_general pt16 pb16\\" data-vxml=\\"001\\" data-snippet=\\"s_hr\\" data-name=\\"Separator\\">\\n            <hr class=\\"s_hr_1px s_hr_solid\\" style=\\"border-top-color: rgb(108, 117, 125) !important;\\"/>\\n        </div>\\n        <section class=\\"s_footer_social o_mail_block_footer_social o_mail_footer_social_center o_mail_snippet_general o_cc o_cc1 pt0 pb0\\" data-vxml=\\"001\\" data-snippet=\\"s_mail_block_footer_social\\" data-name=\\"Footer Center\\">\\n            <div class=\\"container\\" style=\\"text-align: center; color:rgb(183, 191, 199) !important;\\">\\n                <span style=\\"font-size: 12px;\\"><font style=\\"color: rgb(183, 191, 199);\\">8000 Marina Blvd, Suite 300</font></span>\\n                <br/>\\n                <span style=\\"font-size: 12px;\\"><font style=\\"color: rgb(183, 191, 199);\\">Brisbane, California 94005</font></span>\\n                <br/>\\n                <span style=\\"font-size: 12px;\\"><font style=\\"color: rgb(183, 191, 199);\\">Este correo electrónico lo ha enviado </font></span><a href=\\"mailto:\\" target=\\"_blank\\"><span style=\\"font-size: 12px;\\"><font style=\\"color: rgb(183, 191, 199);\\">hello@musingsoftheweek.com</font></span></a>\\n                <br/>\\n                <span style=\\"font-size: 12px;\\"><font style=\\"color: rgb(183, 191, 199);\\">Para cancelar la suscripción, </font></span><a href=\\"/unsubscribe_from_list\\" target=\\"_blank\\"><span style=\\"font-size: 12px;\\"><font style=\\"color: rgb(183, 191, 199);\\">haga clic aquí</font></span></a><span style=\\"font-size: 12px;\\"><font style=\\"color: rgb(183, 191, 199);\\">.</font></span>\\n            </div>\\n        </section>\\n    </t>"}	<?xml version="1.0"?>\n<t t-name="mass_mailing_themes.theme_newsletter_template">\n        <style id="design-element">\n            .o_layout .o_mail_wrapper .o_mail_wrapper_td {\n                --h1-color: #CE0000;\n                --h1-font-size: 54px;\n\n                --h2-font-weight: bolder;\n\n                --h3-font-size: 16px;\n                --h3-font-weight: bolder;\n\n                --text-font-size: 16px;\n\n                --link-text-decoration-line: underline;\n                --link-color: #212529;\n\n                --btn-primary-background-color: #CE0000;\n                --btn-primary-border-color: #CE0000;\n\n                --btn-secondary-color: #CE0000;\n                --btn-secondary-background-color: #FFFFFF;\n                --btn-secondary-border-color: #CE0000;\n            }\n        </style>\n        <t t-set="now" t-value="datetime.datetime.now()"/>\n        <section class="o_snippet_view_in_browser o_mail_snippet_general pt16 pb0" style="text-align: left; padding-left: 15px; padding-right: 15px;" data-vxml="001" data-name="View in Browser">\n            <p><a href="/view" class="" target="_blank" data-bs-original-title="" title="">View in Browser</a> - <font style="color: rgb(183, 191, 199);"><span style="font-size: 12.25px" t-out="datetime.datetime.now().strftime('%B %d %Y')"/></font></p>\n        </section>\n        <section class="s_title o_mail_snippet_general pt32 pb32" data-vxml="001" data-snippet="s_title" data-name="Title" style="background-color: rgb(255, 255, 255) !important;">\n            <div class="container s_allow_columns">\n                <h1 style="text-align:center" class="">Weekly Musings</h1>\n            </div>\n        </section>\n        <section class="s_title o_mail_snippet_general px-3 pb0 pt0" data-vxml="001" data-snippet="s_title" data-name="Title">\n            <div class="container s_allow_columns">\n                    <h2 style="" class="">The story of Odoo</h2>\n            </div>\n        </section>\n        <section class="s_header_social o_mail_block_header_social o_mail_snippet_general bg-white px-3 pt24 pb24" style="" data-vxml="001" data-snippet="s_mail_block_header_social" data-name="Left Logo">\n            <div class="container" style="">\n                <div class="col-md-12 o_mail_header_social" style="background-color: rgb(255, 255, 255) !important; text-align: left;">\n                    <a aria-label="Facebook" target="_blank" href="https://www.facebook.com/Odoo" data-original-title="Facebook" rel="noreferrer">\n                        <img class="img-fluid o_we_custom_image" src="/mass_mailing_themes/static/src/img/theme_newsletter/social-facebook.png" data-attachment-id="435" data-original-id="435" data-original-src="/mass_mailing_themes/static/src/img/theme_newsletter/social-facebook.png" data-mimetype="image/png" style="width: 30px;"/>\n                    </a>&amp;nbsp;&amp;nbsp;\n                    <a aria-label="X" target="_blank" href="https://twitter.com/Odoo" data-original-title="X" rel="noreferrer">\n                        <img class="img-fluid o_we_custom_image" src="/mass_mailing_themes/static/src/img/theme_newsletter/social-twitter.png" data-attachment-id="436" data-original-id="436" data-original-src="/mass_mailing_themes/static/src/img/theme_newsletter/social-twitter.png" data-mimetype="image/png" style="width: 30px;"/>\n                    </a>&amp;nbsp;&amp;nbsp;\n                    <a aria-label="Instagram" target="_blank" href="https://www.linkedin.com/company/odoo" data-original-title="Linkedin" rel="noreferrer">\n                        <img class="img-fluid o_we_custom_image" src="/mass_mailing_themes/static/src/img/theme_newsletter/social-linkedin.png" data-attachment-id="437" data-original-id="437" data-original-src="/mass_mailing_themes/static/src/img/theme_newsletter/social-linkedin.png" data-mimetype="image/png" style="width: 30px;"/>\n                    </a>\n                </div>\n            </div>\n        </section>\n        <section class="s_text_block o_mail_snippet_general px-3 pb24" data-vxml="001" data-snippet="s_text_block" data-name="Text">\n            <div class="container s_allow_columns">\n                <p style="font-size: 14px;" class="small text-muted">Musings on the week from <a style="font-size: 14px;" href="https://twitter.com/fpodoo?ref_src=twsrc%5Egoogle%7Ctwcamp%5Eserp%7Ctwgr%5Eauthor">@fpodoo</a></p>\n            </div>\n        </section>\n        <section class="s_title o_mail_snippet_general px-3 pb0 pt0" data-vxml="001" data-snippet="s_title" data-name="Title">\n            <div class="container s_allow_columns">\n                <h3>Making companies a better place, one app at a time</h3>\n            </div>\n        </section>\n        <section class="s_text_block o_mail_snippet_general px-3 pt16 pb24 " data-vxml="001" data-snippet="s_text_block" data-name="Text">\n            <div class="container s_allow_columns">\n                <p>I needed to change the world. I wanted to... You know how it is when you are young; you have big dreams, a lot of energy and naive stupidity. My dream was to lead the enterprise management market with a fully open source software (I also wanted to get 100 employees before 30 years old with a self-financed company but I failed this one by only a few months).</p>\n                <p>To fuel my motivation, I had to pick someone to fight against. In business, it's like a playground. When you arrive in a new school, if you want to quickly become the leader, you must choose the class bully, the older guy who terrorizes small boys, and kick his butt in front of everyone. That was my strategy with SAP, the enterprise software giant.</p>\n                <p>So in 2005, I started to develop the TinyERP product, the software that (at least in my mind) would change the enterprise world. While preparing for the "day of the fight" in 2006, I <a href="http://whois.domaintools.com/sorrysap.com" target="_blank">bought the SorrySAP.com domain name</a>. I put it on hold for 6 years, waiting for the right moment to use it. I thought it would take 3 years to deprecate a 77 billion dollars company just because open source is so cool. Sometimes it's better for your self-motivation not to face reality...</p>\n                <p>To make things happen, I worked hard, very hard. I worked 13 hours a day, 7 days a week, with no vacation for 7 years. I lost friendships and broke up with my girlfriend in the process.</p>\n                <p>Three years later, I discovered you can't change the world if you are "tiny". Especially if the United States is part of this world, where it's better to be a BigERP, rather than a TinyERP. Can you imagine how small you feel <a href="http://slidesha.re/ohc44E" target="_blank">in front of Danone's directors</a> asking; "But why should we pay millions of dollars for a tiny software?" So, we renamed TinyERP to OpenERP.</p>\n                <p>As we worked hard, things started to evolve. We were developing dozens of modules for OpenERP, the open source community was growing and I was even able to pay all employees' salaries at the end of the month without fear (which was a situation I struggled with for 4 years).</p>\n                <p>In 2010, we had a 100+ employees selling services on OpenERP and a powerful but ugly product. This is what happens when delivering services to customers distracts you from building an exceptional product. It was time to do a pivot in the business model.</p>\n            </div>\n        </section>\n        <section class="s_cover o_mail_snippet_general" data-vxml="001" data-snippet="s_cover" data-name="Cover">\n            <img src="/mass_mailing_themes/static/src/img/theme_newsletter/s_default_image_block_banner.jpg" alt="Cover image" class="img-fluid w-100 mx-auto"/>\n        </section>\n        <section class="s_title o_mail_snippet_general px-3 pb0 pt0" data-vxml="001" data-snippet="s_title" data-name="Title">\n            <div class="container s_allow_columns">\n                <h3>The Pivot</h3>\n            </div>\n        </section>\n        <section class="s_text_block o_mail_snippet_general px-3 pt16 pb24" data-vxml="001" data-snippet="s_text_block" data-name="Text">\n            <div class="container s_allow_columns">\n                <p>We wanted to switch from a service company to a software publisher company. This would allow us to increase our efforts in our research and development activities. As a result, <a href="https://accounts.openerp.com/blog/OpenERP-Blog-Post-1/post/Open-Source-Free-as-in-Freedom-not-free-as-in-Free-services-119" target="_blank">we changed our business model</a> and decided to stop our services for customers and focus on building a strong partner network and maintenance offer. This would cost money, so I had to raise a few million euros.</p>\n                <p>After a few months of pitching investors, I got roughly 10 LOI from different VCs. We chose Sofinnova Partners, the biggest European VC, and Xavier Niel the founder of Iliad, the only company in France funded in the past 10 years to have reached the 1 billion EUR valuation.</p>\n                <p>I signed the LOI. I didn't realize that this contract could have turned me into a homeless person. (I already had a dog, all I needed was to lose a lot of money to become homeless). The fundraising was based on a company valuation but there was a financial mechanism to re-evaluate the company up by 9.8 m€ depending on the turnover of the next 4 years. I should have received warrants convertible into shares if we achieved the turnover targeted in the business plan.</p>\n                <p>The night before receiving the warrants in front of the notary, my wife checked the contracts. She asked me what would be the taxation on these warrants. I rang the lawyer and guess what? Belgium is probably the only country in the world where you have to pay taxes on warrants when you receive them, even if you never reach the conditions to convert them into shares. If I had accepted these warrants, I would have had to pay a 12.5% tax on 9.8 m€; resulting in a tax of 1.2m€ to pay in 18 months! So, my wife is worth 1.2 million EUR. I would have ended up a homeless person without her, as I still did not have a salary at that time.</p>\n                <p>We changed the deal and I got the 3 million EUR. It allowed me to recruit a rocking management team.</p>\n            </div>\n        </section>\n        <section class="s_cover o_mail_snippet_general pb24" data-vxml="001" data-snippet="s_cover" data-name="Cover">\n            <img src="/mass_mailing_themes/static/src/img/theme_newsletter/s_default_image_block_banner_2.jpg" alt="Cover image" class="img-fluid w-100 mx-auto"/>\n        </section>\n        <section class="s_title o_mail_snippet_general px-3 pb0 pt0" data-vxml="001" data-snippet="s_title" data-name="Title">\n            <div class="container s_allow_columns">\n                <h3>Being a Mature Company</h3>\n            </div>\n        </section>\n        <section class="s_text_block o_mail_snippet_general px-3 pt16 pb24" data-vxml="001" data-snippet="s_text_block" data-name="Text">\n            <div class="container s_allow_columns">\n                <p>With this money in our bank account, we boosted two departments: R&amp;D and Sales. We burned 2 million EUR in 18 months, mostly in salaries. The company started to grow even faster. We developed a partner network of 500 partners in 100 countries and we started to sign contracts with 6 zeros.</p>\n                <p>Then, things became different. You know, tedious things like handling human resources, board meetings, dealing with big customer contracts, traveling to launch international subsidiaries. We did boring stuff like budgets, career paths, management meetings, etc.</p>\n                <p>2011 was a complex year. We did not meet our expectations: we only achieved 70% of the forecasted sales budget. Our management meetings were tense. We under-performed. We were not satisfied with ourselves. We had a constant feeling that we were missing something. It's a strange feeling to build extraordinary things but to not be proud of ourselves.</p>\n                <p>But one day, someone (I don't remember who, I have a goldfish memory) made a graph of the monthly turnover of the past 2 years. It was like waking up from a nightmare. In fact, it was not that bad, we had multiplied the monthly turnover by 10 over the span of roughly two years! This is when we understood that OpenERP is a marathon, not a sprint. Only 100% growth a year is ok... if you can keep the rhythm for several years. </p>\n                <p>As usual, I should have listened to my wife. She is way more lucid than I am. Every week I complained to her "It's not good enough, we should grow faster, what am I missing?" and she used to reply: "But you already are the fastest growing company in Belgium!" (Deloitte awarded us as <a href="https://accounts.openerp.com/blog/OpenERP-Blog-1/post/Three-Awards-for-OpenERP-in-2013-139" target="_blank">the fastest growing company of Belgium</a> with 1549% growth of the turnover between 2007 and 2011).</p>\n            </div>\n        </section>\n        <section class="s_title o_mail_snippet_general px-3 pb0 pt0" data-vxml="001" data-snippet="s_title" data-name="Title">\n            <div class="container s_allow_columns">\n                <h3>Changing the World</h3>\n            </div>\n        </section>\n        <section class="s_text_block o_mail_snippet_general px-3 pt16 pb24" data-vxml="001" data-snippet="s_text_block" data-name="Text">\n            <div class="container s_allow_columns">\n                <p>Then the dream started to become reality. We started to get clues that what we did would change the world:</p>\n                <ul>\n                    <li>With 1000 installations per day, we became the most installed management software in the world\n                    </li>\n                    <li><a href="http://amzn.to/P4lRmE" target="_blank">Analysts from Big 4 started to prefer OpenERP over SAP</a></li>\n                    <li>OpenERP is now a compulsory subject for the baccalaureate in France like Word, Excel and PowerPoint</li>\n                    <li>60 new modules are released every month (we became the wikipedia of the management software thanks to our strong community)</li>\n                    <li>In 2013, we had 2,000,000 users worldwide</li>\n                </ul>\n                <p>Something is happening... And it's big!</p>\n            </div>\n        </section>\n        <section class="s_title o_mail_snippet_general px-3 pb0 pt0" data-vxml="001" data-snippet="s_title" data-name="Title">\n            <div class="container s_allow_columns">\n                <h3>New Financing in 2014</h3>\n            </div>\n        </section>\n        <section class="s_text_block o_mail_snippet_general px-3 pt16 pb24" data-vxml="001" data-snippet="s_text_block" data-name="Text">\n            <div class="container s_allow_columns">\n                <p>After years of rapid growth, we achieved another amazing goal - we secured a new round of 10 Million USD of financing, jointly provided by leading venture capital firms XAnge (France), SRIW (Belgium), Sofinnova (France), and the management team.</p>\n                <p>The new financing will support the acceleration of the outstanding growth the company has seen over the last years, enabling the doubling of the commercial force and increased R&amp;D staff - already 100+ people strong. </p>\n            </div>\n        </section>\n        <section class="s_cover o_mail_snippet_general pb24" data-vxml="001" data-snippet="s_cover" data-name="Cover">\n            <img src="/mass_mailing_themes/static/src/img/theme_newsletter/s_default_image_block_banner_3.jpg" alt="Cover image" class="img-fluid w-100 mx-auto"/>\n        </section>\n        <section class="s_title o_mail_snippet_general px-3 pb0 pt0" data-vxml="001" data-snippet="s_title" data-name="Title">\n            <div class="container s_allow_columns">\n                <h3>The Rise of Odoo</h3>\n            </div>\n        </section>\n        <section class="s_text_block o_mail_snippet_general px-3 pt16" data-vxml="001" data-snippet="s_text_block" data-name="Text">\n            <div class="container s_allow_columns">\n                <p>After having disrupted the ERP market, OpenERP moved far beyond the boundaries of traditional ERP players. The integration of business activities is no longer restricted to sales, accounting, inventory and procurements. In June 2014, we released version 8 with awesome CMS &amp; eCommerce, a Point of Sale, an integrated Business Intelligence engine and much more (3000+ modules).</p>\n                <p>Our exceptional technology allowed us to move to newer markets (CMS &amp; eCommerce) and propose a product that disrupts existing open source players (Wordpress, Magento, etc). The OpenERP CMS is so good that even top competitors admitted it publicly when we released the beta version.</p>\n                <p>If current open source players have a real technical challenge to follow us, we also have a huge marketing challenge. Wordpress has 22% of all internet websites. We were the leader in management software, but we start with 0% of the website market.</p>\n                <p>To move forward, we raised 10 million USD in May 2014 in order to boost marketing and sales activities. In order to support our vision, we had to change the name that is not restricted to ERPs functions. We needed a name that allowed us to support our ambitions; build business solutions like CMS, eCommerce, Business Intelligence and, who knows, even sky rockets or driverless cars in the future...</p>\n                <p>In May 2014, we renamed the company and product to Odoo.</p>\n                <p>And a new story just started...</p>\n            </div>\n        </section>\n        <section class="s_text_block o_mail_snippet_general pb16 px-3" data-vxml="001" data-snippet="s_text_block" data-name="Text">\n            <div class="container s_allow_columns">\n                <img src="/mass_mailing_themes/static/src/img/theme_newsletter/FPsignature.gif" style="width: 125px" alt=""/>\n                <p style="text-align:center;" class="pt32">\n                    <a role="button" href="#" class="btn btn-primary btn-lg" target="_blank">&amp;nbsp;&amp;nbsp;Comment on this post&amp;nbsp;&amp;nbsp;</a>\n                </p>\n            </div>\n        </section>\n        <section class="s_footer_social o_mail_block_footer_social o_mail_footer_social_center o_mail_snippet_general o_cc o_cc1 pt0 pb0" data-vxml="001" data-snippet="s_mail_block_footer_social" data-name="Footer Center">\n            <div class="container">\n                <div class="col-md-12 o_mail_footer_social pt0 pb0" style="text-align: center;">\n                    <a aria-label="Facebook" target="_blank" href="https://www.facebook.com/Odoo" data-original-title="Facebook" rel="noreferrer">\n                        <img class="img-fluid o_we_custom_image" src="/mass_mailing_themes/static/src/img/theme_newsletter/social-facebook.png" data-attachment-id="435" data-original-id="435" data-original-src="/mass_mailing_themes/static/src/img/theme_newsletter/social-facebook.png" data-mimetype="image/png" style="width: 30px;"/>\n                    </a>&amp;nbsp;&amp;nbsp;\n                    <a aria-label="X" target="_blank" href="https://twitter.com/Odoo" data-original-title="X" rel="noreferrer">\n                        <img class="img-fluid o_we_custom_image" src="/mass_mailing_themes/static/src/img/theme_newsletter/social-twitter.png" data-attachment-id="436" data-original-id="436" data-original-src="/mass_mailing_themes/static/src/img/theme_newsletter/social-twitter.png" data-mimetype="image/png" style="width: 30px;"/>\n                    </a>&amp;nbsp;&amp;nbsp;\n                    <a aria-label="Instagram" target="_blank" href="https://www.linkedin.com/company/odoo" data-original-title="Linkedin" rel="noreferrer">\n                        <img class="img-fluid o_we_custom_image" src="/mass_mailing_themes/static/src/img/theme_newsletter/social-linkedin.png" data-attachment-id="437" data-original-id="437" data-original-src="/mass_mailing_themes/static/src/img/theme_newsletter/social-linkedin.png" data-mimetype="image/png" style="width: 30px;"/>\n                    </a>\n                </div>\n            </div>\n        </section>\n        <div class="s_hr o_mail_snippet_general pt16 pb16" data-vxml="001" data-snippet="s_hr" data-name="Separator">\n            <hr class="s_hr_1px s_hr_solid" style="border-top-color: rgb(108, 117, 125) !important;"/>\n        </div>\n        <section class="s_footer_social o_mail_block_footer_social o_mail_footer_social_center o_mail_snippet_general o_cc o_cc1 pt0 pb0" data-vxml="001" data-snippet="s_mail_block_footer_social" data-name="Footer Center">\n            <div class="container" style="text-align: center; color:rgb(183, 191, 199) !important;">\n                <span style="font-size: 12px;"><font style="color: rgb(183, 191, 199);">8000 Marina Blvd, Suite 300</font></span>\n                <br/>\n                <span style="font-size: 12px;"><font style="color: rgb(183, 191, 199);">Brisbane, California 94005</font></span>\n                <br/>\n                <span style="font-size: 12px;"><font style="color: rgb(183, 191, 199);">You received this email from </font></span><a href="mailto:" target="_blank"><span style="font-size: 12px;"><font style="color: rgb(183, 191, 199);">hello@musingsoftheweek.com</font></span></a>\n                <br/>\n                <span style="font-size: 12px;"><font style="color: rgb(183, 191, 199);">To unsubscribe, </font></span><a href="/unsubscribe_from_list" target="_blank"><span style="font-size: 12px;"><font style="color: rgb(183, 191, 199);">click here</font></span></a><span style="font-size: 12px;"><font style="color: rgb(183, 191, 199);">.</font></span>\n            </div>\n        </section>\n    </t>\n\n    	\N	f	t	2026-10-26 23:49:16.255758	2026-10-26 23:49:16.255758	f
1627	16	\N	1	1	theme_roadshow1_template	\N	mass_mailing_themes.theme_roadshow1_template	qweb	mass_mailing_themes/views/mass_mailing_themes_templates.xml	primary	\N	{"en_US": "<t t-name=\\"mass_mailing_themes.theme_roadshow1_template\\">\\n        <style id=\\"design-element\\">\\n            .o_layout .o_mail_wrapper .o_mail_wrapper_td {\\n                --h1-font-size: 24px;\\n                --h1-font-weight: bolder;\\n\\n                --h2-font-size: 21px;\\n\\n                --h3-font-size: 18px;\\n                --h3-font-weight: bolder;\\n\\n                --link-color: #35979c;\\n            }\\n        </style>\\n        <section class=\\"s_text_block o_mail_snippet_general pt40 px-3 pb0\\" data-vxml=\\"001\\" data-snippet=\\"s_text_block\\" data-name=\\"Text\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <div class=\\"s_title o_mail_snippet_general pb0 pt0\\" data-vxml=\\"001\\" data-snippet=\\"s_title\\" data-name=\\"Title\\">\\n                    <div class=\\"container s_allow_columns\\">\\n                        <h1>We're almost there!</h1>\\n                    </div>\\n                </div>\\n                <p>Odoo invites you on <span class=\\"font-weight: bolder\\">[date]</span> at <span class=\\"font-weight: bolder\\">[time]</span> for their infamous roadshow in <span class=\\"font-weight: bolder\\">[city]</span>: an event that combines learning and networking in a casual afterwork-like atmosphere.</p>\\n            </div>\\n        </section>\\n        <section class=\\"s_text_block o_mail_snippet_general px-3 pt8 pb0\\" data-vxml=\\"001\\" data-snippet=\\"s_text_block\\" data-name=\\"Text\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <p>Registration is free, but mandatory:</p>\\n                <p style=\\"text-align: center;\\">\\n                    <a href=\\"#\\" class=\\"btn btn-primary btn-lg\\">Save your seat now</a>\\n                </p>\\n                <p style=\\"text-align: center;\\">\\n                    <span class=\\"font-weight: bolder\\">\\n                        <font style=\\"color: rgb(206, 0, 0); font-weight: normal;\\">(only 195 tickets left)</font>\\n                    </span>\\n                </p>\\n            </div>\\n        </section>\\n        <section class=\\"s_text_block o_mail_snippet_general px-3 pt0 pb0\\" data-vxml=\\"001\\" data-snippet=\\"s_text_block\\" data-name=\\"Text\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <p>Discover Odoo, the all-in-one management platform, and its apps designed to improve employees' daily tasks. From sales and deliveries, to logistics, marketing and accounting ; learn what are the best available options to digitize your company.</p>\\n            </div>\\n        </section>\\n        <section class=\\"s_text_block o_mail_snippet_general px-3 pt0 pb0\\" data-vxml=\\"001\\" data-snippet=\\"s_text_block\\" data-name=\\"Text\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <p>[speaker] and [speaker] will rely on a unique demo concept in which YOU lead the demo and choose what you wish to see. They'll show how to tackle the challenge using the best tools, live. You will be amazed!</p>\\n            </div>\\n        </section>\\n        <section class=\\"s_text_block o_mail_snippet_general px-3 pt0 pb0\\" data-vxml=\\"001\\" data-snippet=\\"s_text_block\\" data-name=\\"Text\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <p>You may then take part in round table discussions with experts who will give you their tips and tricks to help digitize companies. We'll wrap up the event with a networking session including a walking dinner.</p>\\n            </div>\\n        </section>\\n        <section class=\\"s_title o_mail_snippet_general pb0 pt8\\" data-vxml=\\"001\\" data-snippet=\\"s_title\\" data-name=\\"Title\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <div class=\\"row\\">\\n                    <div class=\\"offset-md-2 col-md-8\\">\\n                        <h3 class=\\"text-center\\">Schedule</h3>\\n                    </div>\\n                </div>\\n            </div>\\n        </section>\\n        <div class=\\"s_hr o_mail_snippet_general pb16 pt4\\" data-vxml=\\"001\\" data-snippet=\\"s_hr\\" data-name=\\"Separator\\">\\n            <hr class=\\"s_hr_1px s_hr_solid w-50\\"/>\\n        </div>\\n        <section class=\\"s_text_block o_mail_snippet_general px-3 pt8 pb32\\" data-vxml=\\"001\\" data-snippet=\\"s_text_block\\" data-name=\\"Text\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <table class=\\"mx-auto\\" data-name=\\"Schedule Table\\">\\n                    <tr style=\\"vertical-align:top\\" data-name=\\"Schedule Item\\">\\n                        <td style=\\"text-align: right;\\" class=\\"p-2\\" data-name=\\"Time\\">\\n                            <span class=\\"font-weight: bolder\\">8h:</span>\\n                        </td>\\n                        <td class=\\"p-2\\" data-name=\\"Activity\\">\\n                            <span class=\\"font-weight: bolder\\">Welcome</span>\\n                        </td>\\n                    </tr>\\n                    <tr style=\\"vertical-align:top\\" data-name=\\"Schedule Item\\">\\n                        <td style=\\"text-align: right;\\" class=\\"p-2\\" data-name=\\"Time\\">\\n                            <span class=\\"font-weight: bolder\\">18h30:</span>\\n                        </td>\\n                        <td class=\\"p-2\\" data-name=\\"Activity\\">\\n                            <span class=\\"font-weight: bolder\\">[speaker] &amp; [speaker]'s conference</span>\\n                            <ul>\\n                                <li>Interactive Odoo demo</li>\\n                                <li>Best practices to digitize your company</li>\\n                            </ul>\\n                        </td>\\n                    </tr>\\n                    <tr style=\\"vertical-align:top\\" data-name=\\"Schedule Item\\">\\n                        <td style=\\"text-align: right;\\" class=\\"p-2\\" data-name=\\"Time\\">\\n                            <span class=\\"font-weight: bolder\\">19h00:</span>\\n                        </td>\\n                        <td class=\\"p-2\\" data-name=\\"Activity\\">\\n                            <span class=\\"font-weight: bolder\\">Table Ronde</span>\\n                            <ul>\\n                                <li>Business Case</li>\\n                                <li>Client Testimonials</li>\\n                            </ul>\\n                        </td>\\n                    </tr>\\n                    <tr style=\\"vertical-align:top\\" data-name=\\"Schedule Item\\">\\n                        <td style=\\"text-align: right;\\" class=\\"p-2\\" data-name=\\"Time\\">\\n                            <span class=\\"font-weight: bolder\\">19h30: </span>\\n                        </td>\\n                        <td class=\\"p-2\\" data-name=\\"Activity\\">\\n                            <span class=\\"font-weight: bolder\\">Networking: Walking Dinner &amp; Drinks</span>\\n                        </td>\\n                    </tr>\\n                </table>\\n            </div>\\n        </section>\\n        <section class=\\"s_text_block o_mail_snippet_general px-3 pt0 pb4\\" data-vxml=\\"001\\" data-snippet=\\"s_text_block\\" data-name=\\"Text\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <p>For more information, check the event page : <a href=\\"#\\" target=\\"_blank\\" rel=\\"noreferrer\\">[link]</a>.</p>\\n                <p>We're on the starting blocks to prepare an incredible event for you!\\n                    <br/>We hope to see you there.\\n                </p>\\n                <p>See you soon.</p>\\n                <p>--</p>\\n                <p>[speaker] &amp; [speaker]</p>\\n                <p><span style=\\"font-style: italic;\\"><font class=\\"text-600\\">The first 20 participants will get a free copy of our business game \\"Scale-Up\\".</font></span></p>\\n            </div>\\n        </section>\\n    </t>", "es_ES": "<t t-name=\\"mass_mailing_themes.theme_roadshow1_template\\">\\n        <style id=\\"design-element\\">\\n            .o_layout .o_mail_wrapper .o_mail_wrapper_td {\\n                --h1-font-size: 24px;\\n                --h1-font-weight: bolder;\\n\\n                --h2-font-size: 21px;\\n\\n                --h3-font-size: 18px;\\n                --h3-font-weight: bolder;\\n\\n                --link-color: #35979c;\\n            }\\n        </style>\\n        <section class=\\"s_text_block o_mail_snippet_general pt40 px-3 pb0\\" data-vxml=\\"001\\" data-snippet=\\"s_text_block\\" data-name=\\"Text\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <div class=\\"s_title o_mail_snippet_general pb0 pt0\\" data-vxml=\\"001\\" data-snippet=\\"s_title\\" data-name=\\"Title\\">\\n                    <div class=\\"container s_allow_columns\\">\\n                        <h1>¡Ya casi lo logramos!</h1>\\n                    </div>\\n                </div>\\n                <p>Odoo le invita el <span class=\\"font-weight: bolder\\">[fecha]</span> a las <span class=\\"font-weight: bolder\\">[hora]</span> a su roadshow famoso en <span class=\\"font-weight: bolder\\">[ciudad]</span>: un evento que combina aprendizaje y networking en un ambiente casual como una convivencia después del trabajo.</p>\\n            </div>\\n        </section>\\n        <section class=\\"s_text_block o_mail_snippet_general px-3 pt8 pb0\\" data-vxml=\\"001\\" data-snippet=\\"s_text_block\\" data-name=\\"Text\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <p>La inscripción es gratuita, pero obligatoria:</p>\\n                <p style=\\"text-align: center;\\">\\n                    <a href=\\"#\\" class=\\"btn btn-primary btn-lg\\">Reserve ya su entrada</a>\\n                </p>\\n                <p style=\\"text-align: center;\\">\\n                    <span class=\\"font-weight: bolder\\">\\n                        <font style=\\"color: rgb(206, 0, 0); font-weight: normal;\\">(solo quedan 195 entradas disponibles)</font>\\n                    </span>\\n                </p>\\n            </div>\\n        </section>\\n        <section class=\\"s_text_block o_mail_snippet_general px-3 pt0 pb0\\" data-vxml=\\"001\\" data-snippet=\\"s_text_block\\" data-name=\\"Text\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <p>Descubra Odoo, la plataforma de gestión empresarial todo en uno. Sus aplicaciones están diseñadas para mejorar el rendimiento de los empleados en sus tareas diarias. Desde ventas y envíos, hasta logística, marketing y contabilidad; aprenda cuáles son las mejores opciones disponibles para digitalizar su empresa.</p>\\n            </div>\\n        </section>\\n        <section class=\\"s_text_block o_mail_snippet_general px-3 pt0 pb0\\" data-vxml=\\"001\\" data-snippet=\\"s_text_block\\" data-name=\\"Text\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <p>[ponente] y [ponente] se basarán en un concepto único de demostración en el que USTED estará al mando y escogerá que es lo que quiere ver. Le mostrarán como cumplir el objetivo usando las mejores herramientas, en vivo. ¡Se sorprenderá!</p>\\n            </div>\\n        </section>\\n        <section class=\\"s_text_block o_mail_snippet_general px-3 pt0 pb0\\" data-vxml=\\"001\\" data-snippet=\\"s_text_block\\" data-name=\\"Text\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <p>Entonces podrá ser parte de una mesa redonda de debate con expertos que le darán los mejores consejos y trucos para ayudar a digitalizar empresas. Cerraremos el evento con una sesión de networking que incluye bocadillos.</p>\\n            </div>\\n        </section>\\n        <section class=\\"s_title o_mail_snippet_general pb0 pt8\\" data-vxml=\\"001\\" data-snippet=\\"s_title\\" data-name=\\"Title\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <div class=\\"row\\">\\n                    <div class=\\"offset-md-2 col-md-8\\">\\n                        <h3 class=\\"text-center\\">Programa</h3>\\n                    </div>\\n                </div>\\n            </div>\\n        </section>\\n        <div class=\\"s_hr o_mail_snippet_general pb16 pt4\\" data-vxml=\\"001\\" data-snippet=\\"s_hr\\" data-name=\\"Separator\\">\\n            <hr class=\\"s_hr_1px s_hr_solid w-50\\"/>\\n        </div>\\n        <section class=\\"s_text_block o_mail_snippet_general px-3 pt8 pb32\\" data-vxml=\\"001\\" data-snippet=\\"s_text_block\\" data-name=\\"Text\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <table class=\\"mx-auto\\" data-name=\\"Schedule Table\\">\\n                    <tr style=\\"vertical-align:top\\" data-name=\\"Schedule Item\\">\\n                        <td style=\\"text-align: right;\\" class=\\"p-2\\" data-name=\\"Time\\">\\n                            <span class=\\"font-weight: bolder\\">8h:</span>\\n                        </td>\\n                        <td class=\\"p-2\\" data-name=\\"Activity\\">\\n                            <span class=\\"font-weight: bolder\\">Bienvenidos</span>\\n                        </td>\\n                    </tr>\\n                    <tr style=\\"vertical-align:top\\" data-name=\\"Schedule Item\\">\\n                        <td style=\\"text-align: right;\\" class=\\"p-2\\" data-name=\\"Time\\">\\n                            <span class=\\"font-weight: bolder\\">18h30:</span>\\n                        </td>\\n                        <td class=\\"p-2\\" data-name=\\"Activity\\">\\n                            <span class=\\"font-weight: bolder\\">conferencia de [speaker] &amp; [speaker]</span>\\n                            <ul>\\n                                <li>Demostración interactiva de Odoo</li>\\n                                <li>Las mejores prácticas para digitalizar su empresa</li>\\n                            </ul>\\n                        </td>\\n                    </tr>\\n                    <tr style=\\"vertical-align:top\\" data-name=\\"Schedule Item\\">\\n                        <td style=\\"text-align: right;\\" class=\\"p-2\\" data-name=\\"Time\\">\\n                            <span class=\\"font-weight: bolder\\">19h00:</span>\\n                        </td>\\n                        <td class=\\"p-2\\" data-name=\\"Activity\\">\\n                            <span class=\\"font-weight: bolder\\">Mesa redonda</span>\\n                            <ul>\\n                                <li>Caso de negocios</li>\\n                                <li>Testimonios de clientes</li>\\n                            </ul>\\n                        </td>\\n                    </tr>\\n                    <tr style=\\"vertical-align:top\\" data-name=\\"Schedule Item\\">\\n                        <td style=\\"text-align: right;\\" class=\\"p-2\\" data-name=\\"Time\\">\\n                            <span class=\\"font-weight: bolder\\">19h30: </span>\\n                        </td>\\n                        <td class=\\"p-2\\" data-name=\\"Activity\\">\\n                            <span class=\\"font-weight: bolder\\">Networking: Walking Dinner &amp; bebidas</span>\\n                        </td>\\n                    </tr>\\n                </table>\\n            </div>\\n        </section>\\n        <section class=\\"s_text_block o_mail_snippet_general px-3 pt0 pb4\\" data-vxml=\\"001\\" data-snippet=\\"s_text_block\\" data-name=\\"Text\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <p>Para obtener más información, revise la página del evento: <a href=\\"#\\" target=\\"_blank\\" rel=\\"noreferrer\\">[link]</a>.</p>\\n                <p>¡Estamos preparando un evento increíble para usted!\\n                    <br/>Esperamos verlo ahí.\\n                </p>\\n                <p>Nos vemos pronto.</p>\\n                <p>--</p>\\n                <p>[speaker] &amp; [speaker]</p>\\n                <p><span style=\\"font-style: italic;\\"><font class=\\"text-600\\">Las primeras 20 personas en participar recibirán una copia gratuita de nuestro juego empresarial \\"Scale-Up\\".</font></span></p>\\n            </div>\\n        </section>\\n    </t>"}	<?xml version="1.0"?>\n<t t-name="mass_mailing_themes.theme_roadshow1_template">\n        <style id="design-element">\n            .o_layout .o_mail_wrapper .o_mail_wrapper_td {\n                --h1-font-size: 24px;\n                --h1-font-weight: bolder;\n\n                --h2-font-size: 21px;\n\n                --h3-font-size: 18px;\n                --h3-font-weight: bolder;\n\n                --link-color: #35979c;\n            }\n        </style>\n        <section class="s_text_block o_mail_snippet_general pt40 px-3 pb0" data-vxml="001" data-snippet="s_text_block" data-name="Text">\n            <div class="container s_allow_columns">\n                <div class="s_title o_mail_snippet_general pb0 pt0" data-vxml="001" data-snippet="s_title" data-name="Title">\n                    <div class="container s_allow_columns">\n                        <h1>We're almost there!</h1>\n                    </div>\n                </div>\n                <p>Odoo invites you on <span class="font-weight: bolder">[date]</span> at <span class="font-weight: bolder">[time]</span> for their infamous roadshow in <span class="font-weight: bolder">[city]</span>: an event that combines learning and networking in a casual afterwork-like atmosphere.</p>\n            </div>\n        </section>\n        <section class="s_text_block o_mail_snippet_general px-3 pt8 pb0" data-vxml="001" data-snippet="s_text_block" data-name="Text">\n            <div class="container s_allow_columns">\n                <p>Registration is free, but mandatory:</p>\n                <p style="text-align: center;">\n                    <a href="#" class="btn btn-primary btn-lg">Save your seat now</a>\n                </p>\n                <p style="text-align: center;">\n                    <span class="font-weight: bolder">\n                        <font style="color: rgb(206, 0, 0); font-weight: normal;">(only 195 tickets left)</font>\n                    </span>\n                </p>\n            </div>\n        </section>\n        <section class="s_text_block o_mail_snippet_general px-3 pt0 pb0" data-vxml="001" data-snippet="s_text_block" data-name="Text">\n            <div class="container s_allow_columns">\n                <p>Discover Odoo, the all-in-one management platform, and its apps designed to improve employees' daily tasks. From sales and deliveries, to logistics, marketing and accounting ; learn what are the best available options to digitize your company.</p>\n            </div>\n        </section>\n        <section class="s_text_block o_mail_snippet_general px-3 pt0 pb0" data-vxml="001" data-snippet="s_text_block" data-name="Text">\n            <div class="container s_allow_columns">\n                <p>[speaker] and [speaker] will rely on a unique demo concept in which YOU lead the demo and choose what you wish to see. They'll show how to tackle the challenge using the best tools, live. You will be amazed!</p>\n            </div>\n        </section>\n        <section class="s_text_block o_mail_snippet_general px-3 pt0 pb0" data-vxml="001" data-snippet="s_text_block" data-name="Text">\n            <div class="container s_allow_columns">\n                <p>You may then take part in round table discussions with experts who will give you their tips and tricks to help digitize companies. We'll wrap up the event with a networking session including a walking dinner.</p>\n            </div>\n        </section>\n        <section class="s_title o_mail_snippet_general pb0 pt8" data-vxml="001" data-snippet="s_title" data-name="Title">\n            <div class="container s_allow_columns">\n                <div class="row">\n                    <div class="offset-md-2 col-md-8">\n                        <h3 class="text-center">Schedule</h3>\n                    </div>\n                </div>\n            </div>\n        </section>\n        <div class="s_hr o_mail_snippet_general pb16 pt4" data-vxml="001" data-snippet="s_hr" data-name="Separator">\n            <hr class="s_hr_1px s_hr_solid w-50"/>\n        </div>\n        <section class="s_text_block o_mail_snippet_general px-3 pt8 pb32" data-vxml="001" data-snippet="s_text_block" data-name="Text">\n            <div class="container s_allow_columns">\n                <table class="mx-auto" data-name="Schedule Table">\n                    <tr style="vertical-align:top" data-name="Schedule Item">\n                        <td style="text-align: right;" class="p-2" data-name="Time">\n                            <span class="font-weight: bolder">8h:</span>\n                        </td>\n                        <td class="p-2" data-name="Activity">\n                            <span class="font-weight: bolder">Welcome</span>\n                        </td>\n                    </tr>\n                    <tr style="vertical-align:top" data-name="Schedule Item">\n                        <td style="text-align: right;" class="p-2" data-name="Time">\n                            <span class="font-weight: bolder">18h30:</span>\n                        </td>\n                        <td class="p-2" data-name="Activity">\n                            <span class="font-weight: bolder">[speaker] &amp; [speaker]'s conference</span>\n                            <ul>\n                                <li>Interactive Odoo demo</li>\n                                <li>Best practices to digitize your company</li>\n                            </ul>\n                        </td>\n                    </tr>\n                    <tr style="vertical-align:top" data-name="Schedule Item">\n                        <td style="text-align: right;" class="p-2" data-name="Time">\n                            <span class="font-weight: bolder">19h00:</span>\n                        </td>\n                        <td class="p-2" data-name="Activity">\n                            <span class="font-weight: bolder">Table Ronde</span>\n                            <ul>\n                                <li>Business Case</li>\n                                <li>Client Testimonials</li>\n                            </ul>\n                        </td>\n                    </tr>\n                    <tr style="vertical-align:top" data-name="Schedule Item">\n                        <td style="text-align: right;" class="p-2" data-name="Time">\n                            <span class="font-weight: bolder">19h30: </span>\n                        </td>\n                        <td class="p-2" data-name="Activity">\n                            <span class="font-weight: bolder">Networking: Walking Dinner &amp; Drinks</span>\n                        </td>\n                    </tr>\n                </table>\n            </div>\n        </section>\n        <section class="s_text_block o_mail_snippet_general px-3 pt0 pb4" data-vxml="001" data-snippet="s_text_block" data-name="Text">\n            <div class="container s_allow_columns">\n                <p>For more information, check the event page : <a href="#" target="_blank" rel="noreferrer">[link]</a>.</p>\n                <p>We're on the starting blocks to prepare an incredible event for you!\n                    <br/>We hope to see you there.\n                </p>\n                <p>See you soon.</p>\n                <p>--</p>\n                <p>[speaker] &amp; [speaker]</p>\n                <p><span style="font-style: italic;"><font class="text-600">The first 20 participants will get a free copy of our business game "Scale-Up".</font></span></p>\n            </div>\n        </section>\n    </t>\n\n    	\N	f	t	2026-10-26 23:49:16.255758	2026-10-26 23:49:16.255758	f
1628	16	\N	1	1	theme_roadshow2_template	\N	mass_mailing_themes.theme_roadshow2_template	qweb	mass_mailing_themes/views/mass_mailing_themes_templates.xml	primary	\N	{"en_US": "<t t-name=\\"mass_mailing_themes.theme_roadshow2_template\\">\\n        <style id=\\"design-element\\">\\n            .o_layout .o_mail_wrapper .o_mail_wrapper_td {\\n                --h1-font-size: 24px;\\n                --h1-font-weight: bolder;\\n\\n                --h2-font-size: 21px;\\n\\n                --h3-font-size: 18px;\\n                --h3-font-weight: bolder;\\n\\n                --link-color: #35979c;\\n            }\\n        </style>\\n        <section class=\\"s_text_block o_mail_snippet_general px-3 pt40 pb0\\" data-vxml=\\"001\\" data-snippet=\\"s_text_block\\" data-name=\\"Text\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <div class=\\"s_title o_mail_snippet_general pb0 pt0\\" data-vxml=\\"001\\" data-snippet=\\"s_title\\" data-name=\\"Title\\">\\n                    <div class=\\"container s_allow_columns\\">\\n                        <h1>Yesterday's event at [venue] in [city] was incredible!</h1>\\n                    </div>\\n                </div>\\n                <p>Here are some photos taken during the event:</p>\\n                <ul>\\n                    <li><a href=\\"#\\" target=\\"_blank\\">Link 1</a></li>\\n                    <li><a href=\\"#\\" target=\\"_blank\\">Link 2</a></li>\\n                </ul>\\n                <p>Don't hesitate to send us more!</p>\\n            </div>\\n        </section>\\n        <section class=\\"s_text_block o_mail_snippet_general px-3 pt8 pb0\\" data-vxml=\\"001\\" data-snippet=\\"s_text_block\\" data-name=\\"Text\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <p>You had the chance to discover Odoo during a full 3 hours, how great is that?\\n                    <br/>Now that you've seen Odoo in action and asked some questions, you likely need more information to move forward in your project and to work with us. You'll find additional points just below.\\n                </p>\\n            </div>\\n        </section>\\n        <section class=\\"s_title o_mail_snippet_general pb0 pt0\\" data-vxml=\\"001\\" data-snippet=\\"s_title\\" data-name=\\"Title\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <h3>Do you wish to use Odoo?</h3>\\n                <p>If you wish to evaluate Odoo while taking into account your company's specific needs, you can book a free appointment with one of our <a href=\\"https://odoo.com/r/meeting\\" target=\\"_blank\\">Odoo Experts</a> or <a href=\\"https://odoo.com/page/tour\\" target=\\"_blank\\">watch our videos about the product</a>.</p>\\n            </div>\\n        </section>\\n        <section class=\\"s_text_block o_mail_snippet_general px-3 pt8 pb0\\" data-vxml=\\"001\\" data-snippet=\\"s_text_block\\" data-name=\\"Text\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <p>Here are the links to our sponsors' websites if you wish to meet them:</p>\\n                <ul>\\n                    <li><a href=\\"#\\" target=\\"_blank\\">Link 1</a></li>\\n                    <li><a href=\\"#\\" target=\\"_blank\\">Link 2</a></li>\\n                    <li><a href=\\"#\\" target=\\"_blank\\">Link 3</a></li>\\n                    <li><a href=\\"#\\" target=\\"_blank\\">Link 4</a></li>\\n                </ul>\\n                <p>You may test Odoo for free by clicking <a href=\\"https://odoo.com/trial\\" target=\\"_blank\\">here</a>.</p>\\n            </div>\\n        </section>\\n        <section class=\\"s_title o_mail_snippet_general pb0 pt0\\" data-vxml=\\"001\\" data-snippet=\\"s_title\\" data-name=\\"Title\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <h3>Do you wish to become a partner?</h3>\\n                <p>If you wish to become a partner and offer your services in [country], take a look at <a href=\\"https://odoo.com/r/meeting\\" target=\\"_blank\\">this page</a>.</p>\\n                <p>Learn more about our pricing <a href=\\"https://odoo.com/r/meeting\\" target=\\"_blank\\">here</a>.</p>\\n            </div>\\n        </section>\\n        <section class=\\"s_text_block o_mail_snippet_general px-3 pt8 pb0\\" data-vxml=\\"001\\" data-snippet=\\"s_text_block\\" data-name=\\"Text\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <p>You may then take part in round table discussions with experts who will give you their tips and tricks to help digitize companies. We'll wrap up the event with a networking session including a walking dinner.</p>\\n            </div>\\n        </section>\\n        <section class=\\"s_text_block o_mail_snippet_general px-3 pt8 pb0\\" data-vxml=\\"001\\" data-snippet=\\"s_text_block\\" data-name=\\"Text\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <p>Thank you, once again, for your attendance at yesterday's event.</p>\\n                <p>--</p>\\n                <p>[speaker] &amp; [speaker]</p>\\n            </div>\\n        </section>\\n    </t>", "es_ES": "<t t-name=\\"mass_mailing_themes.theme_roadshow2_template\\">\\n        <style id=\\"design-element\\">\\n            .o_layout .o_mail_wrapper .o_mail_wrapper_td {\\n                --h1-font-size: 24px;\\n                --h1-font-weight: bolder;\\n\\n                --h2-font-size: 21px;\\n\\n                --h3-font-size: 18px;\\n                --h3-font-weight: bolder;\\n\\n                --link-color: #35979c;\\n            }\\n        </style>\\n        <section class=\\"s_text_block o_mail_snippet_general px-3 pt40 pb0\\" data-vxml=\\"001\\" data-snippet=\\"s_text_block\\" data-name=\\"Text\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <div class=\\"s_title o_mail_snippet_general pb0 pt0\\" data-vxml=\\"001\\" data-snippet=\\"s_title\\" data-name=\\"Title\\">\\n                    <div class=\\"container s_allow_columns\\">\\n                        <h1>¡El evento de ayer en [ubicación] en [ciudad] estuvo increíble!</h1>\\n                    </div>\\n                </div>\\n                <p>Estas son algunas fotos del evento:</p>\\n                <ul>\\n                    <li><a href=\\"#\\" target=\\"_blank\\">Enlace 1</a></li>\\n                    <li><a href=\\"#\\" target=\\"_blank\\">Enlace 2</a></li>\\n                </ul>\\n                <p>¡No dude en enviarnos más!</p>\\n            </div>\\n        </section>\\n        <section class=\\"s_text_block o_mail_snippet_general px-3 pt8 pb0\\" data-vxml=\\"001\\" data-snippet=\\"s_text_block\\" data-name=\\"Text\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <p>Tuvo la oportunidad de descubrir Odoo por 3 horas, ¿qué tan genial es?\\n                    <br/>Ahora que ya vio a Odoo en acción y externo sus dudas, es probable que necesite más información para continuar con su proyecto y trabajar con nosotros. Encontrará puntos adicionales a continuación.\\n                </p>\\n            </div>\\n        </section>\\n        <section class=\\"s_title o_mail_snippet_general pb0 pt0\\" data-vxml=\\"001\\" data-snippet=\\"s_title\\" data-name=\\"Title\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <h3>¿Quiere usar Odoo?</h3>\\n                <p>Si desea evaluar Odoo teniendo en cuenta las necesidades específicas de su empresa, puede programar una reunión gratuita con uno de nuestros <a href=\\"https://odoo.com/r/meeting\\" target=\\"_blank\\">Expertos de Odoo</a> o <a href=\\"https://odoo.com/page/tour\\" target=\\"_blank\\">vea nuestros vídeos sobre el producto</a>.</p>\\n            </div>\\n        </section>\\n        <section class=\\"s_text_block o_mail_snippet_general px-3 pt8 pb0\\" data-vxml=\\"001\\" data-snippet=\\"s_text_block\\" data-name=\\"Text\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <p>Este es un enlace a los sitios web de nuestros patrocinadores, si desea conocerlos:</p>\\n                <ul>\\n                    <li><a href=\\"#\\" target=\\"_blank\\">Enlace 1</a></li>\\n                    <li><a href=\\"#\\" target=\\"_blank\\">Enlace 2</a></li>\\n                    <li><a href=\\"#\\" target=\\"_blank\\">Enlace 3</a></li>\\n                    <li><a href=\\"#\\" target=\\"_blank\\">Enlace 4</a></li>\\n                </ul>\\n                <p>Puede probar Odoo gratis haciendo clic <a href=\\"https://odoo.com/trial\\" target=\\"_blank\\">aquí</a>.</p>\\n            </div>\\n        </section>\\n        <section class=\\"s_title o_mail_snippet_general pb0 pt0\\" data-vxml=\\"001\\" data-snippet=\\"s_title\\" data-name=\\"Title\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <h3>¿Quiere convertirse en partner?</h3>\\n                <p>Si desea convertirse en partner y ofrecer sus servicios en [país], eche un vistazo a <a href=\\"https://odoo.com/r/meeting\\" target=\\"_blank\\">esta página</a>.</p>\\n                <p>Descubra más acerca de nuestros precios <a href=\\"https://odoo.com/r/meeting\\" target=\\"_blank\\">aquí</a>.</p>\\n            </div>\\n        </section>\\n        <section class=\\"s_text_block o_mail_snippet_general px-3 pt8 pb0\\" data-vxml=\\"001\\" data-snippet=\\"s_text_block\\" data-name=\\"Text\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <p>Entonces podrá ser parte de una mesa redonda de debate con expertos que le darán los mejores consejos y trucos para ayudar a digitalizar empresas. Cerraremos el evento con una sesión de networking que incluye bocadillos.</p>\\n            </div>\\n        </section>\\n        <section class=\\"s_text_block o_mail_snippet_general px-3 pt8 pb0\\" data-vxml=\\"001\\" data-snippet=\\"s_text_block\\" data-name=\\"Text\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <p>Gracias, una vez más, por asistir al evento de ayer.</p>\\n                <p>--</p>\\n                <p>[speaker] &amp; [speaker]</p>\\n            </div>\\n        </section>\\n    </t>"}	<?xml version="1.0"?>\n<t t-name="mass_mailing_themes.theme_roadshow2_template">\n        <style id="design-element">\n            .o_layout .o_mail_wrapper .o_mail_wrapper_td {\n                --h1-font-size: 24px;\n                --h1-font-weight: bolder;\n\n                --h2-font-size: 21px;\n\n                --h3-font-size: 18px;\n                --h3-font-weight: bolder;\n\n                --link-color: #35979c;\n            }\n        </style>\n        <section class="s_text_block o_mail_snippet_general px-3 pt40 pb0" data-vxml="001" data-snippet="s_text_block" data-name="Text">\n            <div class="container s_allow_columns">\n                <div class="s_title o_mail_snippet_general pb0 pt0" data-vxml="001" data-snippet="s_title" data-name="Title">\n                    <div class="container s_allow_columns">\n                        <h1>Yesterday's event at [venue] in [city] was incredible!</h1>\n                    </div>\n                </div>\n                <p>Here are some photos taken during the event:</p>\n                <ul>\n                    <li><a href="#" target="_blank">Link 1</a></li>\n                    <li><a href="#" target="_blank">Link 2</a></li>\n                </ul>\n                <p>Don't hesitate to send us more!</p>\n            </div>\n        </section>\n        <section class="s_text_block o_mail_snippet_general px-3 pt8 pb0" data-vxml="001" data-snippet="s_text_block" data-name="Text">\n            <div class="container s_allow_columns">\n                <p>You had the chance to discover Odoo during a full 3 hours, how great is that?\n                    <br/>Now that you've seen Odoo in action and asked some questions, you likely need more information to move forward in your project and to work with us. You'll find additional points just below.\n                </p>\n            </div>\n        </section>\n        <section class="s_title o_mail_snippet_general pb0 pt0" data-vxml="001" data-snippet="s_title" data-name="Title">\n            <div class="container s_allow_columns">\n                <h3>Do you wish to use Odoo?</h3>\n                <p>If you wish to evaluate Odoo while taking into account your company's specific needs, you can book a free appointment with one of our <a href="https://odoo.com/r/meeting" target="_blank">Odoo Experts</a> or <a href="https://odoo.com/page/tour" target="_blank">watch our videos about the product</a>.</p>\n            </div>\n        </section>\n        <section class="s_text_block o_mail_snippet_general px-3 pt8 pb0" data-vxml="001" data-snippet="s_text_block" data-name="Text">\n            <div class="container s_allow_columns">\n                <p>Here are the links to our sponsors' websites if you wish to meet them:</p>\n                <ul>\n                    <li><a href="#" target="_blank">Link 1</a></li>\n                    <li><a href="#" target="_blank">Link 2</a></li>\n                    <li><a href="#" target="_blank">Link 3</a></li>\n                    <li><a href="#" target="_blank">Link 4</a></li>\n                </ul>\n                <p>You may test Odoo for free by clicking <a href="https://odoo.com/trial" target="_blank">here</a>.</p>\n            </div>\n        </section>\n        <section class="s_title o_mail_snippet_general pb0 pt0" data-vxml="001" data-snippet="s_title" data-name="Title">\n            <div class="container s_allow_columns">\n                <h3>Do you wish to become a partner?</h3>\n                <p>If you wish to become a partner and offer your services in [country], take a look at <a href="https://odoo.com/r/meeting" target="_blank">this page</a>.</p>\n                <p>Learn more about our pricing <a href="https://odoo.com/r/meeting" target="_blank">here</a>.</p>\n            </div>\n        </section>\n        <section class="s_text_block o_mail_snippet_general px-3 pt8 pb0" data-vxml="001" data-snippet="s_text_block" data-name="Text">\n            <div class="container s_allow_columns">\n                <p>You may then take part in round table discussions with experts who will give you their tips and tricks to help digitize companies. We'll wrap up the event with a networking session including a walking dinner.</p>\n            </div>\n        </section>\n        <section class="s_text_block o_mail_snippet_general px-3 pt8 pb0" data-vxml="001" data-snippet="s_text_block" data-name="Text">\n            <div class="container s_allow_columns">\n                <p>Thank you, once again, for your attendance at yesterday's event.</p>\n                <p>--</p>\n                <p>[speaker] &amp; [speaker]</p>\n            </div>\n        </section>\n    </t>\n\n    	\N	f	t	2026-10-26 23:49:16.255758	2026-10-26 23:49:16.255758	f
1631	16	\N	1	1	theme_terms_update_template	\N	mass_mailing_themes.theme_terms_update_template	qweb	mass_mailing_themes/views/mass_mailing_themes_templates.xml	primary	\N	{"en_US": "<t t-name=\\"mass_mailing_themes.theme_terms_update_template\\">\\n        <style id=\\"design-element\\">\\n            .o_layout .o_mail_wrapper .o_mail_wrapper_td {\\n                --h1-color: #111827;\\n                --h2-color: #111827;\\n                --h3-color: #111827;\\n                --text-color: #111827;\\n                --text-font-size: 15px;\\n                --link-color: #111827;\\n                --btn-primary-background-color: #111827;\\n                --btn-primary-border-color: #111827;\\n                --btn-primary-color: #ffffff;\\n                --separator-border-color: #e5e7eb !important;\\n            }\\n        </style>\\n        <t t-set=\\"now\\" t-value=\\"datetime.datetime.now()\\"/>\\n        <t t-set=\\"website_url_or_none\\" t-value=\\"(company_id.website) or '#'\\"/>\\n\\n        <section class=\\"o_snippet_view_in_browser o_mail_snippet_general pt16 pb16\\" data-name=\\"View in Browser\\" data-vxml=\\"001\\">\\n            <p style=\\"text-align: center\\" class=\\"mb-0\\">\\n                <a href=\\"/view\\">View in Browser</a>\\n            </p>\\n        </section>\\n\\n        <section class=\\"o_mail_snippet_general pt0 pb24\\" data-vxml=\\"001\\" data-snippet=\\"s_mail_block_header_logo_and_stacked_menu\\" data-name=\\"Logo + Stacked Menu\\">\\n            <div class=\\"container\\">\\n                <div class=\\"row\\">\\n                    <div class=\\"col-md-12 col-12\\">\\n                        <div class=\\"o_not_editable\\">\\n                            <a style=\\"text-decoration:none;\\" href=\\"http://www.example.com\\">\\n                                <img src=\\"/mass_mailing_themes/static/src/img/theme_bignews/s_default_image_logo.png\\" style=\\"height:auto;max-width:100%; width: 25% !important;\\" class=\\"img img-fluid o_editable_media mx-auto py-4 o_we_custom_image\\"/>\\n                            </a>\\n                        </div>\\n                    </div>\\n                </div>\\n                <div class=\\"row\\">\\n                    <div class=\\"col-md-12 col-12\\">\\n                        <p class=\\"m-0\\" style=\\"text-align: center;\\"><a href=\\"#\\" class=\\"btn btn-link\\">News</a><a href=\\"#\\" class=\\"btn btn-link\\">Shop</a><a href=\\"#\\" class=\\"btn btn-link\\">Contact Us</a></p>\\n                    </div>\\n                </div>\\n            </div>\\n        </section>\\n\\n        <section class=\\"s_bento_blocks o_mail_snippet_general pt0 pb32\\" data-snippet=\\"s_bento_blocks\\" data-name=\\"Bento Blocks\\">\\n            <div class=\\"container\\">\\n                <div class=\\"row\\">\\n                    <div class=\\"col-md-12 col-12 pb0\\" style=\\"padding-left: 48px; padding-right: 48px;\\">\\n                        <div class=\\"o_cc o_cc2 o_colored_level\\" style=\\"background-color: rgb(240, 249, 255) !important; border-radius: 16px !important; padding: 24px;\\" data-name=\\"Bento card\\">\\n                            <h1><span style=\\"font-size: 24px;\\">Inside this update</span></h1>\\n                            <ul>\\n                                <li>What's changing</li>\\n                                <li>What it changes for you</li>\\n                                <li>What stays the same</li>\\n                                <li>Action required</li>\\n                            </ul>\\n                        </div>\\n                    </div>\\n                </div>\\n            </div>\\n        </section>\\n\\n        <section class=\\"s_text_block o_mail_snippet_general pt0 pb0\\" style=\\"padding-left: 48px; padding-right: 48px;\\" data-vxml=\\"001\\" data-snippet=\\"s_text_block\\" data-name=\\"Text\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <h2>What's changing</h2>\\n                <p><strong>Data retention period shortened.</strong> <em t-out=\\"company_id.name\\">YourCompany</em> is reducing the default data retention period from 5 years to 2 years. This aligns with current privacy best practices and gives you more control over your personal data. Archived accounts will be subject to the new timeline starting June 1.</p>\\n                <p><strong>Updated third-party sharing clause.</strong> <em t-out=\\"company_id.name\\">YourCompany</em> has clarified and limited the scope of data shared with third-party partners. Going forward, only anonymized, aggregated usage data may be shared for analytics purposes; no personally identifiable information, ever.</p>\\n                <p><strong>Revised payment and refund terms.</strong> The refund window for annual subscriptions changes from 30 to 14 days from the billing date. Monthly subscriptions are unaffected. <em t-out=\\"company_id.name\\">YourCompany</em> has also added clearer language around failed payment retries and grace periods.</p>\\n                <p>\\n                    <a class=\\"btn btn-lg btn-primary\\" href=\\"#\\">Read more</a>\\n                </p>\\n            </div>\\n            <div class=\\"s_hr o_mail_snippet_general o_not_editable pt32 pb32\\" data-snippet=\\"s_hr\\" data-name=\\"Separator\\" data-vxml=\\"001\\">\\n                <hr class=\\"w-100 mx-auto\\"/>\\n            </div>\\n        </section>\\n\\n        <section class=\\"s_text_block o_mail_snippet_general pt0 pb0\\" style=\\"padding-left: 48px; padding-right: 48px;\\" data-vxml=\\"001\\" data-snippet=\\"s_text_block\\" data-name=\\"Text\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <h2>What it changes for you</h2>\\n                <p>In most cases, these changes will be invisible in your day-to-day use of the platform. However, there are a few situations where you'll notice a direct impact:</p>\\n                <div class=\\"oe_unmovable s_alert s_mail_alert s_alert_md alert alert-info w-100 row border rounded\\" style=\\"border-radius: 0px !important; background-color: rgb(240, 249, 255) !important; border-color: rgb(14, 165, 233) !important; --box-border-left-width: 4px; --box-border-bottom-width: 0px; --box-border-right-width: 0px; --box-border-top-width: 0px;\\" data-snippet=\\"s_alert\\" data-name=\\"Alert\\">\\n                    <div class=\\"s_alert_content col-12\\">\\n                        <p class=\\"mb-0\\"><strong>If you have an annual subscription:</strong><br/>Your refund window is <strong>now 14 days</strong> (not 30). If you recently renewed and would like to request a refund, please contact support within this window.</p>\\n                    </div>\\n                </div>\\n                <div class=\\"oe_unmovable s_alert s_mail_alert s_alert_md alert alert-info w-100 row border rounded\\" style=\\"border-radius: 0px !important; background-color: rgb(240, 249, 255) !important; border-color: rgb(14, 165, 233) !important; --box-border-left-width: 4px; --box-border-bottom-width: 0px; --box-border-right-width: 0px; --box-border-top-width: 0px;\\" data-snippet=\\"s_alert\\" data-name=\\"Alert\\">\\n                    <div class=\\"s_alert_content col-12\\">\\n                        <p class=\\"mb-0\\"><strong>If your account is inactive or archived:</strong><br/>Data <strong>older than 2 years</strong> will be deleted starting end of the year. You'll receive a separate reminder 60 days before any deletion occurs.</p>\\n                    </div>\\n                </div>\\n                <p>For everyone else, your account continues to function exactly as before.</p>\\n            </div>\\n            <div class=\\"s_hr o_mail_snippet_general o_not_editable pt32 pb32\\" data-snippet=\\"s_hr\\" data-name=\\"Separator\\" data-vxml=\\"001\\">\\n                <hr class=\\"w-100 mx-auto\\"/>\\n            </div>\\n        </section>\\n\\n        <section class=\\"s_text_block o_mail_snippet_general ptO pb24\\" style=\\"padding-left: 48px; padding-right: 48px;\\" data-vxml=\\"001\\" data-snippet=\\"s_text_block\\" data-name=\\"Text\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <h2>What stays the same</h2>\\n                <p>The vast majority of our Terms remain exactly as they were. In particular:</p>\\n                <ul>\\n                    <li>Your right to export and delete your data at any time</li>\\n                    <li>Our commitment to never selling your personal data to third parties</li>\\n                    <li>Pricing and plan features for existing subscribers</li>\\n                    <li>Your ability to cancel your subscription at any time</li>\\n                    <li>Our SLA and uptime commitments</li>\\n                </ul>\\n                <p><em t-out=\\"company_id.name\\">YourCompany</em> believes good terms should be readable. If anything in the updated document is unclear, reach out to us directly.</p>\\n                <p>\\n                    <a class=\\"btn btn-lg btn-primary\\" href=\\"#\\">Read more</a>\\n                </p>\\n            </div>\\n            <div class=\\"s_hr o_mail_snippet_general o_not_editable pt32 pb32\\" data-snippet=\\"s_hr\\" data-name=\\"Separator\\" data-vxml=\\"001\\">\\n                <hr class=\\"w-100 mx-auto\\"/>\\n            </div>\\n        </section>\\n\\n        <section class=\\"s_subtitle o_mail_snippet_general pb8\\" data-snippet=\\"s_subtitle\\" data-name=\\"Subtitle\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <div class=\\"col-md-12 o_colored_level\\" style=\\"padding-left: 48px; padding-right: 48px;\\">\\n                    <h2>Action required</h2>\\n                </div>\\n            </div>\\n        </section>\\n\\n        <section class=\\"s_text_block o_mail_snippet_general pt0 pb24\\" style=\\"padding-left: 48px; padding-right: 48px;\\" data-vxml=\\"001\\" data-snippet=\\"s_text_block\\" data-name=\\"Text\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <p>To continue using <em t-out=\\"company_id.name\\">YourCompany</em>'s services, you'll need to accept the updated Terms &amp; Conditions. Logging into your account will prompt you automatically — or you can review them now at your own pace.</p>\\n                <p>If you do not accept the new terms by the end of June, your account will be paused until you do so. No data will be deleted immediately; you'll have an additional 30-day window to accept or export your data.</p>\\n                <p>\\n                    <a class=\\"btn btn-lg btn-primary\\" href=\\"#\\">Review now</a>\\n                </p>\\n            </div>\\n        </section>\\n\\n        <section class=\\"s_footer_social o_mail_block_footer_social o_mail_footer_social_center o_mail_snippet_general pt16 pb16\\" data-snippet=\\"s_mail_block_footer_social\\" data-name=\\"Footer Center\\" data-vxml=\\"001\\">\\n            <div class=\\"container\\">\\n                <div class=\\"row\\">\\n                    <div class=\\"col-md-12 col-12\\">\\n                        <div class=\\"o_not_editable\\">\\n                            <a t-att-href=\\"company_id.website or '#'\\" target=\\"_blank\\">\\n                                <img class=\\"img img-fluid o_editable_media mx-auto py-4\\" style=\\"width: 25% !important;\\" src=\\"/mass_mailing_themes/static/src/img/theme_bignews/s_default_image_logo.png\\"/>\\n                            </a>\\n                        </div>\\n                        <t t-call=\\"mass_mailing.s_social_media_template\\" optionalTextPosition.f=\\"text-center\\" optionalSnippetClass.f=\\"o_mail_footer_social pb16 no_icon_color\\" optionalTextStyle.f=\\"color: #111827 !important;\\"/>\\n                        <p style=\\"text-align: center\\"><t t-if=\\"company_id\\"><strong>© <t t-out=\\"company_id.partner_id.name\\"/></strong><br/><t t-out=\\"company_id.partner_id._display_address()\\"/><br/></t>You received this email because your account is subject to the updated Terms &amp; Conditions.</p>\\n                        <p style=\\"text-align: center\\"><a class=\\"btn btn-link\\" role=\\"button\\" href=\\"/unsubscribe_from_list\\">Unsubscribe</a></p>\\n                    </div>\\n                </div>\\n            </div>\\n        </section>\\n    </t>", "es_ES": "<t t-name=\\"mass_mailing_themes.theme_terms_update_template\\">\\n        <style id=\\"design-element\\">\\n            .o_layout .o_mail_wrapper .o_mail_wrapper_td {\\n                --h1-color: #111827;\\n                --h2-color: #111827;\\n                --h3-color: #111827;\\n                --text-color: #111827;\\n                --text-font-size: 15px;\\n                --link-color: #111827;\\n                --btn-primary-background-color: #111827;\\n                --btn-primary-border-color: #111827;\\n                --btn-primary-color: #ffffff;\\n                --separator-border-color: #e5e7eb !important;\\n            }\\n        </style>\\n        <t t-set=\\"now\\" t-value=\\"datetime.datetime.now()\\"/>\\n        <t t-set=\\"website_url_or_none\\" t-value=\\"(company_id.website) or '#'\\"/>\\n\\n        <section class=\\"o_snippet_view_in_browser o_mail_snippet_general pt16 pb16\\" data-name=\\"View in Browser\\" data-vxml=\\"001\\">\\n            <p style=\\"text-align: center\\" class=\\"mb-0\\">\\n                <a href=\\"/view\\">View in Browser</a>\\n            </p>\\n        </section>\\n\\n        <section class=\\"o_mail_snippet_general pt0 pb24\\" data-vxml=\\"001\\" data-snippet=\\"s_mail_block_header_logo_and_stacked_menu\\" data-name=\\"Logo + Stacked Menu\\">\\n            <div class=\\"container\\">\\n                <div class=\\"row\\">\\n                    <div class=\\"col-md-12 col-12\\">\\n                        <div class=\\"o_not_editable\\">\\n                            <a style=\\"text-decoration:none;\\" href=\\"http://www.example.com\\">\\n                                <img src=\\"/mass_mailing_themes/static/src/img/theme_bignews/s_default_image_logo.png\\" style=\\"height:auto;max-width:100%; width: 25% !important;\\" class=\\"img img-fluid o_editable_media mx-auto py-4 o_we_custom_image\\"/>\\n                            </a>\\n                        </div>\\n                    </div>\\n                </div>\\n                <div class=\\"row\\">\\n                    <div class=\\"col-md-12 col-12\\">\\n                        <p class=\\"m-0\\" style=\\"text-align: center;\\"><a href=\\"#\\" class=\\"btn btn-link\\">News</a><a href=\\"#\\" class=\\"btn btn-link\\">Shop</a><a href=\\"#\\" class=\\"btn btn-link\\">Contact Us</a></p>\\n                    </div>\\n                </div>\\n            </div>\\n        </section>\\n\\n        <section class=\\"s_bento_blocks o_mail_snippet_general pt0 pb32\\" data-snippet=\\"s_bento_blocks\\" data-name=\\"Bento Blocks\\">\\n            <div class=\\"container\\">\\n                <div class=\\"row\\">\\n                    <div class=\\"col-md-12 col-12 pb0\\" style=\\"padding-left: 48px; padding-right: 48px;\\">\\n                        <div class=\\"o_cc o_cc2 o_colored_level\\" style=\\"background-color: rgb(240, 249, 255) !important; border-radius: 16px !important; padding: 24px;\\" data-name=\\"Bento card\\">\\n                            <h1><span style=\\"font-size: 24px;\\">Inside this update</span></h1>\\n                            <ul>\\n                                <li>What's changing</li>\\n                                <li>What it changes for you</li>\\n                                <li>What stays the same</li>\\n                                <li>Action required</li>\\n                            </ul>\\n                        </div>\\n                    </div>\\n                </div>\\n            </div>\\n        </section>\\n\\n        <section class=\\"s_text_block o_mail_snippet_general pt0 pb0\\" style=\\"padding-left: 48px; padding-right: 48px;\\" data-vxml=\\"001\\" data-snippet=\\"s_text_block\\" data-name=\\"Text\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <h2>What's changing</h2>\\n                <p><strong>Data retention period shortened.</strong> <em t-out=\\"company_id.name\\">YourCompany</em> is reducing the default data retention period from 5 years to 2 years. This aligns with current privacy best practices and gives you more control over your personal data. Archived accounts will be subject to the new timeline starting June 1.</p>\\n                <p><strong>Updated third-party sharing clause.</strong> <em t-out=\\"company_id.name\\">YourCompany</em> has clarified and limited the scope of data shared with third-party partners. Going forward, only anonymized, aggregated usage data may be shared for analytics purposes; no personally identifiable information, ever.</p>\\n                <p><strong>Revised payment and refund terms.</strong> The refund window for annual subscriptions changes from 30 to 14 days from the billing date. Monthly subscriptions are unaffected. <em t-out=\\"company_id.name\\">YourCompany</em> has also added clearer language around failed payment retries and grace periods.</p>\\n                <p>\\n                    <a class=\\"btn btn-lg btn-primary\\" href=\\"#\\">Read more</a>\\n                </p>\\n            </div>\\n            <div class=\\"s_hr o_mail_snippet_general o_not_editable pt32 pb32\\" data-snippet=\\"s_hr\\" data-name=\\"Separator\\" data-vxml=\\"001\\">\\n                <hr class=\\"w-100 mx-auto\\"/>\\n            </div>\\n        </section>\\n\\n        <section class=\\"s_text_block o_mail_snippet_general pt0 pb0\\" style=\\"padding-left: 48px; padding-right: 48px;\\" data-vxml=\\"001\\" data-snippet=\\"s_text_block\\" data-name=\\"Text\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <h2>What it changes for you</h2>\\n                <p>In most cases, these changes will be invisible in your day-to-day use of the platform. However, there are a few situations where you'll notice a direct impact:</p>\\n                <div class=\\"oe_unmovable s_alert s_mail_alert s_alert_md alert alert-info w-100 row border rounded\\" style=\\"border-radius: 0px !important; background-color: rgb(240, 249, 255) !important; border-color: rgb(14, 165, 233) !important; --box-border-left-width: 4px; --box-border-bottom-width: 0px; --box-border-right-width: 0px; --box-border-top-width: 0px;\\" data-snippet=\\"s_alert\\" data-name=\\"Alert\\">\\n                    <div class=\\"s_alert_content col-12\\">\\n                        <p class=\\"mb-0\\"><strong>If you have an annual subscription:</strong><br/>Your refund window is <strong>now 14 days</strong> (not 30). If you recently renewed and would like to request a refund, please contact support within this window.</p>\\n                    </div>\\n                </div>\\n                <div class=\\"oe_unmovable s_alert s_mail_alert s_alert_md alert alert-info w-100 row border rounded\\" style=\\"border-radius: 0px !important; background-color: rgb(240, 249, 255) !important; border-color: rgb(14, 165, 233) !important; --box-border-left-width: 4px; --box-border-bottom-width: 0px; --box-border-right-width: 0px; --box-border-top-width: 0px;\\" data-snippet=\\"s_alert\\" data-name=\\"Alert\\">\\n                    <div class=\\"s_alert_content col-12\\">\\n                        <p class=\\"mb-0\\"><strong>If your account is inactive or archived:</strong><br/>Data <strong>older than 2 years</strong> will be deleted starting end of the year. You'll receive a separate reminder 60 days before any deletion occurs.</p>\\n                    </div>\\n                </div>\\n                <p>For everyone else, your account continues to function exactly as before.</p>\\n            </div>\\n            <div class=\\"s_hr o_mail_snippet_general o_not_editable pt32 pb32\\" data-snippet=\\"s_hr\\" data-name=\\"Separator\\" data-vxml=\\"001\\">\\n                <hr class=\\"w-100 mx-auto\\"/>\\n            </div>\\n        </section>\\n\\n        <section class=\\"s_text_block o_mail_snippet_general ptO pb24\\" style=\\"padding-left: 48px; padding-right: 48px;\\" data-vxml=\\"001\\" data-snippet=\\"s_text_block\\" data-name=\\"Text\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <h2>What stays the same</h2>\\n                <p>The vast majority of our Terms remain exactly as they were. In particular:</p>\\n                <ul>\\n                    <li>Your right to export and delete your data at any time</li>\\n                    <li>Our commitment to never selling your personal data to third parties</li>\\n                    <li>Pricing and plan features for existing subscribers</li>\\n                    <li>Your ability to cancel your subscription at any time</li>\\n                    <li>Our SLA and uptime commitments</li>\\n                </ul>\\n                <p><em t-out=\\"company_id.name\\">YourCompany</em> believes good terms should be readable. If anything in the updated document is unclear, reach out to us directly.</p>\\n                <p>\\n                    <a class=\\"btn btn-lg btn-primary\\" href=\\"#\\">Read more</a>\\n                </p>\\n            </div>\\n            <div class=\\"s_hr o_mail_snippet_general o_not_editable pt32 pb32\\" data-snippet=\\"s_hr\\" data-name=\\"Separator\\" data-vxml=\\"001\\">\\n                <hr class=\\"w-100 mx-auto\\"/>\\n            </div>\\n        </section>\\n\\n        <section class=\\"s_subtitle o_mail_snippet_general pb8\\" data-snippet=\\"s_subtitle\\" data-name=\\"Subtitle\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <div class=\\"col-md-12 o_colored_level\\" style=\\"padding-left: 48px; padding-right: 48px;\\">\\n                    <h2>Action required</h2>\\n                </div>\\n            </div>\\n        </section>\\n\\n        <section class=\\"s_text_block o_mail_snippet_general pt0 pb24\\" style=\\"padding-left: 48px; padding-right: 48px;\\" data-vxml=\\"001\\" data-snippet=\\"s_text_block\\" data-name=\\"Text\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <p>To continue using <em t-out=\\"company_id.name\\">YourCompany</em>'s services, you'll need to accept the updated Terms &amp; Conditions. Logging into your account will prompt you automatically — or you can review them now at your own pace.</p>\\n                <p>If you do not accept the new terms by the end of June, your account will be paused until you do so. No data will be deleted immediately; you'll have an additional 30-day window to accept or export your data.</p>\\n                <p>\\n                    <a class=\\"btn btn-lg btn-primary\\" href=\\"#\\">Review now</a>\\n                </p>\\n            </div>\\n        </section>\\n\\n        <section class=\\"s_footer_social o_mail_block_footer_social o_mail_footer_social_center o_mail_snippet_general pt16 pb16\\" data-snippet=\\"s_mail_block_footer_social\\" data-name=\\"Footer Center\\" data-vxml=\\"001\\">\\n            <div class=\\"container\\">\\n                <div class=\\"row\\">\\n                    <div class=\\"col-md-12 col-12\\">\\n                        <div class=\\"o_not_editable\\">\\n                            <a t-att-href=\\"company_id.website or '#'\\" target=\\"_blank\\">\\n                                <img class=\\"img img-fluid o_editable_media mx-auto py-4\\" style=\\"width: 25% !important;\\" src=\\"/mass_mailing_themes/static/src/img/theme_bignews/s_default_image_logo.png\\"/>\\n                            </a>\\n                        </div>\\n                        <t t-call=\\"mass_mailing.s_social_media_template\\" optionalTextPosition.f=\\"text-center\\" optionalSnippetClass.f=\\"o_mail_footer_social pb16 no_icon_color\\" optionalTextStyle.f=\\"color: #111827 !important;\\"/>\\n                        <p style=\\"text-align: center\\"><t t-if=\\"company_id\\"><strong>© <t t-out=\\"company_id.partner_id.name\\"/></strong><br/><t t-out=\\"company_id.partner_id._display_address()\\"/><br/></t>You received this email because your account is subject to the updated Terms &amp; Conditions.</p>\\n                        <p style=\\"text-align: center\\"><a class=\\"btn btn-link\\" role=\\"button\\" href=\\"/unsubscribe_from_list\\">Cancelar suscripción</a></p>\\n                    </div>\\n                </div>\\n            </div>\\n        </section>\\n    </t>"}	<?xml version="1.0"?>\n<t t-name="mass_mailing_themes.theme_terms_update_template">\n        <style id="design-element">\n            .o_layout .o_mail_wrapper .o_mail_wrapper_td {\n                --h1-color: #111827;\n                --h2-color: #111827;\n                --h3-color: #111827;\n                --text-color: #111827;\n                --text-font-size: 15px;\n                --link-color: #111827;\n                --btn-primary-background-color: #111827;\n                --btn-primary-border-color: #111827;\n                --btn-primary-color: #ffffff;\n                --separator-border-color: #e5e7eb !important;\n            }\n        </style>\n        <t t-set="now" t-value="datetime.datetime.now()"/>\n        <t t-set="website_url_or_none" t-value="(company_id.website) or '#'"/>\n\n        <section class="o_snippet_view_in_browser o_mail_snippet_general pt16 pb16" data-name="View in Browser" data-vxml="001">\n            <p style="text-align: center" class="mb-0">\n                <a href="/view">View in Browser</a>\n            </p>\n        </section>\n\n        <section class="o_mail_snippet_general pt0 pb24" data-vxml="001" data-snippet="s_mail_block_header_logo_and_stacked_menu" data-name="Logo + Stacked Menu">\n            <div class="container">\n                <div class="row">\n    