l pt8 pb8\\">\\n                        <t t-call=\\"mass_mailing.s_social_media_template\\" optionalSnippetClass.f=\\"no_icon_color\\" optionalTextStyle.f=\\"color: #1466B8\\" optionalTextPosition.f=\\"text-center\\"/>\\n                    </div>\\n                </div>\\n                <div class=\\"row\\">\\n                    <div class=\\"col-md o_mail_footer_links\\">\\n                        <a role=\\"button\\" href=\\"/unsubscribe_from_list\\" class=\\"btn btn-link\\">Unsubscribe</a>\\n                    </div>\\n                </div>\\n                <div class=\\"row\\">\\n                    <div class=\\"col-md\\">\\n                        <p><span style=\\"font-size: 10px;\\">\\n                            © 2022 All Rights Reserved\\n                        </span></p>\\n                    </div>\\n                </div>\\n            </div>\\n        </section>\\n    </t>", "es_ES": "<t t-name=\\"mass_mailing_themes.theme_training_template\\">\\n        <style id=\\"design-element\\">\\n            * :not(.oi), *:not(.oi) {\\n                font-family: \\"Lucida Grande\\", \\"Lucida Sans Unicode\\", \\"Lucida Sans\\", Geneva, Verdana, sans-serif !important;\\n            }\\n            .o_layout .o_mail_wrapper .o_mail_wrapper_td {\\n                --h1-color: rgb(255, 255, 255);\\n                --h1-font-size: 39px;\\n\\n                --h3-color: rgb(20, 102, 184);\\n\\n                --text-color: rgb(91, 119, 143);\\n                --text-font-size: 16px;\\n\\n                --link-color: rgb(20, 102, 184);\\n\\n                --btn-primary-color: rgb(255, 255, 255);\\n                --btn-primary-background-color: rgb(67, 128, 219);\\n                --btn-primary-font-size: 14px;\\n\\n                --btn-secondary-color: rgb(255, 255, 255);\\n                --btn-secondary-background-color: rgb(255, 152, 0);\\n\\n                --separator-border-color: rgb(67, 129, 219);\\n                --separator-border-top-width: 2px;\\n            }\\n        </style>\\n        <t t-set=\\"training_date\\" t-value=\\"datetime.date.today() + datetime.timedelta(days=30)\\"/>\\n        <section class=\\"s_header_logo o_mail_block_header_logo o_mail_snippet_general\\" data-vxml=\\"001\\" data-snippet=\\"s_mail_block_header_logo\\" data-name=\\"Centered Logo\\" style=\\"background-color: rgb(220, 234, 255);\\">\\n            <div class=\\"container\\">\\n                <div class=\\"row\\">\\n                    <div class=\\"col-md-4\\"/>\\n                    <div class=\\"col-md-4 pt16 pb16\\" style=\\"text-align: center;\\">\\n                        <a style=\\"text-decoration:none;\\" href=\\"#\\" target=\\"_blank\\">\\n                            <font style=\\"color: rgb(20, 102, 184); font-size: 24px;\\"><span style=\\"font-weight: normal\\">Formación</span></font> <font style=\\"font-size: 24px; background-color: rgb(20, 102, 184);\\" class=\\"text-o-color-4\\">A+</font>\\n                        </a>\\n                    </div>\\n                    <div class=\\"col-md-4\\" style=\\"text-align: right;\\"/>\\n                </div>\\n            </div>\\n        </section>\\n        <section class=\\"s_picture o_mail_snippet_general pt48 px-3 o_cc o_cc2 pb0\\" data-vxml=\\"001\\" data-snippet=\\"s_picture\\" data-name=\\"Picture\\" placeholder=\\"Escriba &quot;/&quot; para comandos\\" style=\\"background-color: rgb(67, 128, 219);\\">\\n            <img class=\\"img-fluid o_we_custom_image\\" src=\\"/html_editor/image_shape/mass_mailing_themes.s_default_image_block_image/html_builder/composition/composition_organic_line.svg?c1=%23FF9800\\" data-shape=\\"html_builder/composition/composition_organic_line\\" data-file-name=\\"picture-composition_organic_line.svg\\" data-shape-colors=\\"#FF9800;;;;\\" data-format-mimetype=\\"image/jpeg\\"/>\\n        </section>\\n        <section class=\\"s_title o_mail_snippet_general pt32 pb0\\" data-vxml=\\"001\\" data-snippet=\\"s_title\\" data-name=\\"Title\\" style=\\"background-color: rgb(67, 128, 219);\\">\\n            <div class=\\"container s_allow_columns\\">\\n                <div class=\\"row\\">\\n                    <div class=\\"col-md-10 offset-md-1 pb32\\">\\n                        <h1>Aprenda con los mejores desarrolladores</h1>\\n                    </div>\\n                </div>\\n            </div>\\n        </section>\\n        <section class=\\"s_mail_block_event o_mail_snippet_general bg-white o_colored_level\\" data-vxml=\\"001\\" data-snippet=\\"s_event\\" data-name=\\"Event\\" contenteditable=\\"false\\">\\n            <div class=\\"container\\" contenteditable=\\"true\\">\\n                <div class=\\"row align-items-center\\">\\n                    <div class=\\"o_mail_no_colorpicker pt32 pb0 o_colored_level col-md-10 offset-md-1\\" style=\\"padding-left: 0px; padding-right: 0px;\\">\\n                        <div class=\\"card bg-white h-100 border\\" style=\\"border-radius: 5px !important; border-color: rgb(233, 236, 239) !important; border-width: 0px !important;\\">\\n                            <div class=\\"card-body\\">\\n                                <div class=\\"s_title o_mail_snippet_general pb0 pt0 o_colored_level\\" data-vxml=\\"001\\" data-snippet=\\"s_title\\" data-name=\\"Title\\">\\n                                    <div class=\\"container\\">\\n                                        <div class=\\"row\\">\\n                                            <div class=\\"o_colored_level col-md-12 o_draggable\\" style=\\"padding-left: 0px; padding-right: 0px;\\">\\n                                                <h3 class=\\"card-title\\">Formación para el desarrollo de software</h3>\\n                                                <p><span style=\\"font-weight: bolder;\\"><t t-out=\\"training_date.strftime('%d %B %Y')\\"/> - 4:30 PM</span></p>\\n                                            </div>\\n                                        </div>\\n                                    </div>\\n                                </div>\\n                                <p><i class=\\"oi\\" data-icon=\\"location_on\\" contenteditable=\\"false\\"/> London, United Kingdom</p>\\n                            </div>\\n                        </div>\\n                    </div>\\n                </div>\\n                <div class=\\"row\\">\\n                    <div class=\\"col-md-10 offset-md-1 pb0 o_colored_level\\">\\n                        <p>La formación para desarrolladores de software puede resultar cara, por lo que hemos recopilado una lista de cursos gratuitos perfectos para los no titulados en informática que quieran actualizarse y aprender a programar.</p>\\n                        <p>Puede que las universidades nos den títulos vistosos, pero eso no nos da las <span style=\\"font-weight: bolder;\\">habilidades prácticas que necesitamos para empezar un innovadora carrera en tecnología</span>.</p>\\n                        <p>Tener experiencia práctica es tan probable como que le caiga un rayo,<span style=\\"font-style: italic;\\">graicas coronavirus</span>, pero puede hacerse cargo usted mismo y usar su tiempo libre para mejorar sus habilidades.</p>\\n                        <p><span style=\\"font-weight: bolder;\\">¿Y qué mejor sector que el desarrollo de software para mejorar sus habilidades?</span> Nuestra oferta laboral ha ido en ascenso constante estos últimos años y así seguirá. Al tomar uno de estos cursos gratuitos, puede hacer su CV más competitivo y su portafolio más interesante.</p>\\n                        <p/>\\n                        <p><a href=\\"#\\" target=\\"_blank\\" class=\\"btn btn-primary flat btn-lg\\"><span style=\\"font-weight: bolder;\\">Inscríbase ahora</span></a></p>\\n                    </div>\\n                </div>\\n            </div>\\n        </section>\\n        <section class=\\"s_text_block o_mail_snippet_general\\" data-vxml=\\"001\\" data-snippet=\\"s_text_block\\" data-name=\\"Text\\"