_general pt48 px-3 o_cc o_cc2 pb0" data-vxml="001" data-snippet="s_picture" data-name="Picture" placeholder="Type &quot;/&quot; for commands" style="background-color: rgb(67, 128, 219);">\n            <img class="img-fluid o_we_custom_image" src="/html_editor/image_shape/mass_mailing_themes.s_default_image_block_image/html_builder/composition/composition_organic_line.svg?c1=%23FF9800" data-shape="html_builder/composition/composition_organic_line" data-file-name="picture-composition_organic_line.svg" data-shape-colors="#FF9800;;;;" data-format-mimetype="image/jpeg"/>\n        </section>\n        <section class="s_title o_mail_snippet_general pt32 pb0" data-vxml="001" data-snippet="s_title" data-name="Title" style="background-color: rgb(67, 128, 219);">\n            <div class="container s_allow_columns">\n                <div class="row">\n                    <div class="col-md-10 offset-md-1 pb32">\n                        <h1>Train with the best developers</h1>\n                    </div>\n                </div>\n            </div>\n        </section>\n        <section class="s_mail_block_event o_mail_snippet_general bg-white o_colored_level" data-vxml="001" data-snippet="s_event" data-name="Event" contenteditable="false">\n            <div class="container" contenteditable="true">\n                <div class="row align-items-center">\n                    <div class="o_mail_no_colorpicker pt32 pb0 o_colored_level col-md-10 offset-md-1" style="padding-left: 0px; padding-right: 0px;">\n                        <div class="card bg-white h-100 border" style="border-radius: 5px !important; border-color: rgb(233, 236, 239) !important; border-width: 0px !important;">\n                            <div class="card-body">\n                                <div class="s_title o_mail_snippet_general pb0 pt0 o_colored_level" data-vxml="001" data-snippet="s_title" data-name="Title">\n                                    <div class="container">\n                                        <div class="row">\n                                            <div class="o_colored_level col-md-12 o_draggable" style="padding-left: 0px; padding-right: 0px;">\n                                                <h3 class="card-title">Software development training</h3>\n                                                <p><span style="font-weight: bolder;"><t t-out="training_date.strftime('%d %B %Y')"/> - 4:30 PM</span></p>\n                                            </div>\n                                        </div>\n                                    </div>\n                                </div>\n                                <p><i class="oi" data-icon="location_on" contenteditable="false"/> London, United Kingdom</p>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n                <div class="row">\n                    <div class="col-md-10 offset-md-1 pb0 o_colored_level">\n                        <p>Software developer training can be expensive, so we've compiled a list of free courses that are perfect for non-Computer Science graduates who want to upskill and learn to code.</p>\n                        <p>Universities may give us a shiny degrees, but it does not give us the <span style="font-weight: bolder;">practical skills we need to start an innovative career in tech</span>.</p>\n                        <p>Getting practical experience can be as likely as getting struck by lightning – <span style="font-style: italic;">thank you, coronavirus</span> – but, you can take things into your own hands and use your free time to upskill.</p>\n                        <p><span style="font-weight: bolder;">And what better field to upskill in than software development?</span> Jobs have been steadily booming for years, and will continue to do so. By taking some of these free courses, you can make your CV more competitive and your portfolio more interesting.</p>\n                        <p/>\n                        <p><a href="#" target="_blank" class="btn btn-primary flat btn-lg"><span style="font-weight: bolder;">Register now</span></a></p>\n                    </div>\n                </div>\n            </div>\n        </section>\n        <section class="s_text_block o_mail_snippet_general" data-vxml="001" data-snippet="s_text_block" data-name="Text">\n            <div class="container s_allow_columns">\n                <div class="row">\n                    <div class="offset-md-1 col-md-10">\n                        <p><img src="/mass_mailing_themes/static/src/img/theme_training/s_default_image_block_banner.jpg" class="img img-fluid o_we_custom_image" data-original-id="347" data-original-src="/mass_mailing_themes/static/src/img/theme_training/s_default_image_block_banner.jpg" data-mimetype="image/jpeg" style="width: 658px;"/></p>\n                    </div>\n                </div>\n            </div>\n        </section>\n        <section class="s_cover o_mail_snippet_general" data-vxml="001" data-snippet="s_cover" data-name="Cover" style="background-color: rgb(220, 234, 255);">\n            <div class="container">\n                <div class="row">\n                    <div class="oe_img_bg o_bg_img_center pb88 pt104 col-md-12" data-original-src="/mass_mailing_themes/static/src/img/theme_training/see_you_soon.svg" style="background-image: url('/mass_mailing_themes/static/src/img/theme_training/see_you_soon.svg');">\n                        <div class="o_we_bg_filter" style="background-image: linear-gradient(0deg, rgb(67, 128, 219) 0%, rgba(67, 128, 219, 0.4) 100%);"/>\n                        <h1 style="text-align: center;">See you soon !</h1>\n                    </div>\n                </div>\n            </div>\n        </section>\n        <section class="s_text_block o_mail_snippet_general px-3 pt16 pb0" data-vxml="001" data-snippet="s_text_block" data-name="Text" style="background-color: rgb(220, 234, 255);">\n            <div class="container s