--
-- Name: project_task_stage_report _RETURN; Type: RULE; Schema: public; Owner: -
--

CREATE OR REPLACE VIEW public.project_task_stage_report AS
 SELECT (((t.id)::bigint * 1000000) + COALESCE(s.id, 0)) AS id,
    t.name,
    t.milestone_id,
    t.company_id,
    t.partner_id,
    t.create_date,
    t.date_deadline,
    t.date_last_stage_update,
        CASE
            WHEN ((t.state)::text = ANY ((ARRAY['1_done'::character varying, '1_canceled'::character varying])::text[])) THEN true
            ELSE false
        END AS is_closed,
    t.priority,
    t.id AS task_id,
    t.project_id,
    s.id AS stage_id,
    ((step.duration)::double precision / (60)::double precision) AS time_spent,
    t.task_properties,
    s.sequence
   FROM ((public.project_task t
     CROSS JOIN LATERAL jsonb_each((((t.duration_tracking - 'd'::text) - 's'::text) || jsonb_build_object((t.duration_tracking ->> 's'::text), (((EXTRACT(epoch FROM (timezone('UTC'::text, now()) - ((t.duration_tracking ->> 'd'::text))::timestamp without time zone)) / (60)::numeric))::integer + (COALESCE((t.duration_tracking ->> (t.duration_tracking ->> 's'::text)), '0'::text))::integer)))) step(stage_id, duration))
     LEFT JOIN public.project_task_type s ON ((s.id = (step.stage_id)::integer)))
  WHERE (t.project_id IS NOT NULL)
  GROUP BY t.id, t.name, t.milestone_id, t.company_id, t.partner_id, t.create_date, t.date_deadline, t.date_last_stage_update, t.priority, s.id, step.duration;


--
-- Name: report_project_task_user _RETURN; Type: RULE; Schema: public; Owner: -
--

CREATE OR REPLACE VIEW public.report_project_task_user AS
 SELECT ( SELECT 1) AS nbr,
    t.id,
    t.id AS task_id,
    t.create_date,
    t.date_assign,
    t.date_end,
    t.date_last_stage_update,
    t.date_deadline,
    t.display_in_project,
    t.project_id,
    t.priority,
    t.name,
    t.company_id,
    t.partner_id,
    t.parent_id,
    t.stage_id,
    t.state,
    t.milestone_id,
        CASE
            WHEN ((t.state)::text = ANY ((ARRAY['1_done'::character varying, '1_canceled'::character varying])::text[])) THEN true
            ELSE false
        END AS is_closed,
        CASE
            WHEN (pm.id IS NOT NULL) THEN true
            ELSE false
        END AS has_late_and_unreached_milestone,
    t.description,
    NULLIF(t.rating_last_value, (0)::double precision) AS rating_last_value,
    avg(rt.rating) AS rating_avg,
    NULLIF(t.working_days_close, (0)::double precision) AS working_days_close,
    NULLIF(t.working_days_open, (0)::double precision) AS working_days_open,
    NULLIF(t.working_hours_open, (0)::numeric) AS working_hours_open,
    NULLIF(t.working_hours_close, (0)::numeric) AS working_hours_close,
    (EXTRACT(epoch FROM (t.date_deadline - (now() AT TIME ZONE 'UTC'::text))) / ((3600 * 24))::numeric) AS delay_endings_days,
    count(td.task_id) AS dependent_ids_count,
    t.is_template,
    t.has_template_ancestor,
    p.is_template AS has_project_template,
    t.sale_line_id,
    t.sale_order_id
   FROM ((((public.project_task t
     LEFT JOIN public.rating_rating rt ON (((rt.res_id = t.id) AND ((rt.res_model)::text = 'project.task'::text) AND (rt.consumed = true) AND (rt.rating >= (1)::double precision))))
     LEFT JOIN public.project_milestone pm ON (((pm.id = t.milestone_id) AND (pm.is_reached = false) AND (pm.deadline <= (now())::date))))
     LEFT JOIN public.task_dependencies_rel td ON ((td.depends_on_id = t.id)))
     LEFT JOIN public.project_project p ON ((p.id = t.project_id)))
  WHERE (t.project_id IS NOT NULL)
  GROUP BY t.id, t.create_date, t.date_assign, t.date_end, t.date_last_stage_update, t.date_deadline, t.project_id, t.priority, t.name, t.company_id, t.partner_id, t.parent_id, t.stage_id, t.state, t.rating_last_value, t.working_days_close, t.working_days_open, t.working_hours_open, t.working_hours_close, t.milestone_id, pm.id, td.depends_on_id, p.is_template, t.sale_line_id, t.sale_order_id;


--
-- Name: vendor_delay_report _RETURN; Type: RULE; Schema: public; Owner: -
--

CREATE OR REPLACE VIEW public.vendor_delay_report AS
 SELECT pol.id,
    min(m.date) AS date,
    pol.id AS purchase_line_id,
    pol.product_id,
    min(pc.id) AS category_id,
    pol.partner_id,
    pol.product_uom_qty AS qty_total,
    sum(
        CASE
            WHEN (((m.state)::text = 'done'::text) AND ((pol.date_promised)::date >= (m.date)::date)) THEN ((ml.quantity * ml_uom.factor) / pt_uom.factor)
            ELSE (0)::numeric
        END) AS qty_on_time
   FROM (((((((public.stock_move m
     JOIN public.purchase_order_line pol ON ((pol.id = m.purchase_line_id)))
     JOIN public.product_product p ON ((p.id = m.product_id)))
     JOIN public.product_template pt ON ((pt.id = p.product_tmpl_id)))
     JOIN public.uom_uom pt_uom ON ((pt_uom.id = pt.uom_id)))
     LEFT JOIN public.product_category pc ON ((pc.id = pt.categ_id)))
     LEFT JOIN public.stock_move_line ml ON ((ml.move_id = m.id)))
     LEFT JOIN public.uom_uom ml_uom ON ((ml_uom.id = ml.uom_id)))
  GROUP BY pol.id;


